local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:6027"] = {n="Buch der Uralten",s="Am Turm von Ethel Rethor vertraut Euch Azore Aldamort den Edelstein der Schlange an. Legt ihn auf die Schlangenstatue auf der Insel Ranazjar nordwestlich des Turms, und der Beschützer des Buchs der Uralten erscheint.",h="Am Turm von Ethel Rethor vertraut Euch Azore Aldamort den Edelstein der Schlange an.",kw={"azore aldamort","buch der uralten","ethel rethor","edelstein der schlange","naga","die insel ranazjar","schlangenstatue"},sec={{t="Die Schlangenstatue",b="Nach Szepter des Lichts gibt Euch Azore Aldamort den Edelstein der Schlange. Die Insel Ranazjar liegt nordwestlich des Turms von Ethel Rethor, und dort wartet die Schlangenstatue. Legt den Edelstein auf ihre Hand, um den Beschützer des Buchs der Uralten herbeizurufen. Die Naga hüten die Geheimnisse des Buchs seit Jahrhunderten, und Azore hofft, dass es viel über ihre geschuppten Feinde lehren wird."}},faq={{q="Wer ist Azore Aldamort?",a="Azore Aldamort hütet den Turm von Ethel Rethor. Azore hofft, viel über die Naga zu erfahren, die Azore als geschuppte Feinde bezeichnet.",al={"azore aldamort","wer gibt das buch der uralten","typ im turm von ethel rethor"}},{q="Was ist das Buch der Uralten?",a="Das Buch der Uralten birgt Geheimnisse, die die Naga seit Jahrhunderten hüten. Jemand bewacht es.",al={"was ist das buch der uralten","geschichte des buchs","naga buch desolace"}},{q="Wo liegt die Insel Ranazjar?",a="Die Insel Ranazjar ist eine kleine Insel nordwestlich des Turms von Ethel Rethor.",al={"lage der insel ranazjar","wo liegt die insel ranazjar","wohin mit dem edelstein"}},{q="Wozu dient der Edelstein der Schlange?",a="Legt den Edelstein der Schlange auf die Hand der Schlangenstatue auf der Insel Ranazjar, um den Beschützer des Buchs der Uralten herbeizurufen.",al={"edelstein der schlange","hand der schlangenstatue","wie den beschützer herbeirufen"}},{q="Was kam davor?",a="Szepter des Lichts kommt vor diesem Schritt.",al={"vorherige quest","questreihe szepter des lichts","voraussetzung"}}},fp="20,212,18.355.0,22.119.0,33.91.0,23.68.0,35.134.0,22.40.0"}
P.entries["quest:603"] = {n="Ansirems Schlüssel",s="Ein uralter Trolldolch könnte die Magie schwächen, die den Stein der Gezeiten stärkt. Erzmagier Ansirem Runenweber fand die Klinge im Schlingendorntal und gab sie dann seiner Tochter Catelyn, die ihr Zuhause für die Piraten von Beutebucht verließ.",h="Ein uralter Trolldolch könnte die Magie schwächen, die den Stein der Gezeiten stärkt.",kw={"ansirem","beutebucht","catelyn","dolch","runenweber","stein der gezeiten","trollrelikt"},sec={{t="Eine eigensinnige Tochter",b="Erzmagier Ansirem Runenweber hat herausgefunden, dass ein Altar oder Fokuspunkt den Stein der Gezeiten verstärkt. Um diese Magie zu überwältigen, braucht er einen uralten Trolldolch, den er bei seinen Forschungen im Schlingendorntal entdeckte. Er gab die Klinge vor langer Zeit seiner Tochter Catelyn. Eigensinnig verließ sie ihr Zuhause für die Piraten von Beutebucht."},{t="Eine entwaffnete Kämpferin",b="In Beutebucht trägt Catelyn den Dolch nicht mehr an der Hüfte. Einst die geschickteste Messerkämpferin der Siedlung, verlor sie ein Duell gegen einen der Blutsegelbukaniere. Ihr Bezwinger nahm die Trollklinge als Trophäe an sich. Nun steht Catelyn entwaffnet und gedemütigt dem bitteren Spott ihrer Halsabschneidergefährten gegenüber."}},faq={{q="Warum braucht Erzmagier Ansirem den Trolldolch?",a="Der Magier, der den Stein der Gezeiten besitzt, kanalisiert dessen Magie durch einen Altar. Ansirem hofft, dass ein uralter Trolldolch diese Verstärkung stören kann, indem er sie überwältigt.",al={"warum dolch nötig","ansirems schlüssel zweck","wozu dient der dolch"}},{q="Wer ist Catelyn?",a="Catelyn ist die eigensinnige Tochter von Erzmagier Ansirem Runenweber. Sie verließ ihren Vater, um als Piratin in Beutebucht zu leben.",al={"wer ist catelyn","ansirems tochter","catelyn die klinge"}},{q="Wo hat Ansirem den Dolch ursprünglich gefunden?",a="Ansirem fand das Relikt bei seinen Forschungen in den Dschungeln des Schlingendorntals und gab es dann seiner Tochter.",al={"herkunft des dolches","wo fand ansirem den dolch"}},{q="Wo ist Catelyn zu finden?",a="Catelyn lebt in Beutebucht, dem Piratenzufluchtsort an der Südspitze des Schlingendorntals.",al={"wo ist catelyn","catelyns aufenthaltsort"}}},fp="13,223,18.317.0,18.289.1,48.163.0,15.128.0,45.109.0,27.87.0"}
P.entries["quest:604"] = {n="Die Blutsegelbukaniere",s="An den wilden Ufern haben die Blutsegelbukaniere einen südlichen Kommandoposten errichtet. Flottenmeister Seehorn schickt einen vertrauenswürdigen Blackwater Raider, um ihre Karten und Befehle zu erbeuten, damit die Flotte ihre Pläne erfährt.",h="An den wilden Ufern haben die Blutsegelbukaniere einen südlichen Kommandoposten errichtet.",kw={"blackwater raiders","blutsegelbukaniere","blutsegelkarten","blutsegelbefehle","beutebucht","flottenmeister seehorn","die wilden ufer"},sec={{t="Angriff auf die wilden Ufer",b="Crazz’ Lob hat Flottenmeister Seehorn auf Euch aufmerksam gemacht. Die Blutsegelbukaniere haben an den wilden Ufern einen südlichen Kommandoposten errichtet. Seehorn schickt Euch, um ihr Lager anzugreifen, ihre Haudegen niederzustrecken und ihre Seekarten sowie schriftlichen Befehle zu erbeuten. Die Flotte braucht diese Unterlagen, um die Absichten ihrer Rivalen zu erfahren."},{t="Der Plan der Flotte",b="Die Karten und Befehle der Blutsegel enthüllen den Plan der Piraten. Seehorn kommt zu dem Schluss, dass sie nahe am Kap vor Anker gegangen sind."}},faq={{q="Wer erteilt den Auftrag für diesen Angriff?",a="Flottenmeister Seehorn erteilt den Auftrag für den Angriff von Beutebucht aus, nachdem Crazz Eure Hingabe gelobt hat.",al={"wer vergibt die quest der blutsegelbukaniere","seehorn quest"}},{q="Wo liegt der Kommandoposten der Blutsegel?",a="Das südliche Kommandolager der Blutsegelbukaniere liegt an den wilden Ufern, südlich von Beutebucht im Schlingendorntal.",al={"standort des südlichen kommandopostens der blutsegel","wo sind die wilden ufer"}},{q="Welche Gegenstände werden aus dem Lager der Blutsegel benötigt?",a="Seehorn bittet Euch, die Blutsegelkarten und die schriftlichen Blutsegelbefehle zu bergen, um die Absichten der rivalisierenden Bukaniere zu erfahren.",al={"welche dokumente will seehorn","blutsegelbefehle und blutsegelkarten"}},{q="Warum will Flottenmeister Seehorn ihre Karten und Befehle?",a="Flottenmeister Seehorn will die Karten und Befehle, um zu erfahren, was die Blutsegelbukaniere planen.",al={"warum die wilden ufer angreifen","was will seehorn wissen"}}},fp="24,205,22.329.0,29.115.1,22.89.0,44.118.0,52.120.0,59.101.0"}
P.entries["quest:605"] = {n="Singende blaue Splitter",s="Im Schlingendorntal suchen Käufer nach Singenden blauen Splittern. Die Venture Company erschwert es Crank Fizzlebub, rohe Singende Kristalle zu sammeln, also bietet er Euch für zehn Splitter aus Basiliskenhäuten einen Gewinnanteil an.",h="Im Schlingendorntal suchen Käufer nach Singenden blauen Splittern.",kw={"basilisken","crank fizzlebub","singende blaue splitter","singende kristalle","schlingendorntal","venture company","zul'kunda"},sec={{t="Eine lukrative Gelegenheit",b="Crank Fizzlebub hat Käufer für Singende Kristalle, die nur im Schlingendorntal vorkommen. Die Venture Company erschwert ihm das Sammeln roher Kristalle. Also sucht er einen anderen Weg, an sie zu gelangen. Basilisken fressen die Kristalle, und das Mineral wird Teil ihrer verhärteten Häute. Daraus könnt Ihr brauchbare Splitter gewinnen."},{t="Jagd an der Küste",b="Basilisken im ganzen Dschungel können Kristallfragmente liefern. Fizzlebub verweist Euch auf die friedfertigeren Exemplare an den nördlichen Küsten südlich von Zul'Kunda. Bringt ihm zehn Splitter, damit er mit seinen Käufern ins Geschäft kommen kann. Dann richtet er seine Aufmerksamkeit auf die Aktivitäten der Venture Company."}},faq={{q="Warum will Crank Fizzlebub Singing Crystal Shards haben?",a="Singende Kristalle gibt es nur im Schlingendorntal, und ausgewählte Käufer schätzen sie sehr. Crank Fizzlebub sagt, dass er sie verkaufen kann, und bietet Euch einen Gewinnanteil an.",al={"warum singende kristalle","crank fizzlebubs absicht","wozu dienen singende kristalle"}},{q="Warum kann Crank Fizzlebub die Kristalle nicht direkt sammeln?",a="Fizzlebub sagt, die Venture Company erschwere es ihm, selbst rohe Kristalle zu sammeln.",al={"warum basilisken töten","problem mit der venture company","warum kristalle nicht abbauen"}},{q="Warum haben Basilisken diese Kristalle?",a="Basilisken im Schlingendorntal fressen die Kristalle. Das Mineral wird Teil ihrer Häute und verleiht ihnen ihre harte, felsige Haut.",al={"hintergrund zu basiliskenkristallen","warum hinterlassen basilisken kristalle"}},{q="Wo schlägt Crank Fizzlebub vor, nach Basilisken zu suchen?",a="Fizzlebub sagt, jeder Basilisk könne Splitter liefern. Friedfertigere Exemplare leben an den nördlichen Küsten südlich von Zul'Kunda.",al={"wo splitter finden","fundort der basilisken","zul kunda basilisken"}},{q="Was geschieht nach der Abgabe der Splitter?",a="Wenn Ihr Fizzlebub zehn Splitter bringt, zahlt er Euch den versprochenen Gewinnanteil aus. Dann richtet er seine Aufmerksamkeit auf die Aktivitäten der Venture Company.",al={"was folgt nach singende blaue splitter","folgequest von singende blaue splitter"}}},fp="19,221,23.301.0,17.264.0,53.162.0,57.88.0,37.128.0,57.109.0,41.143.1"}
P.entries["quest:606"] = {n="Zitterhand Angst einjagen",s="An den Docks von Beutebucht schuldet Zitterhand Phillipe Seewolf MacKinley noch Geld vom Spiel der letzten Woche. MacKinley schickt Euch vor die Stadt, um Innereien von Elder Mistvale Gorillas zu holen und Phillipe damit zur Zahlung zu schrecken.",h="An den Docks von Beutebucht schuldet Zitterhand Phillipe Seewolf MacKinley noch Geld vom Spiel der letzten...",kw={"beutebucht","spielschulden","mistvale innereien","mistvale gorillas","zitterhand angst einjagen","seewolf mackinley","zitterhand phillipe","schlingendorntal"},sec={{t="Schulden eintreiben",b="Seewolf MacKinley will seine Spielschulden eintreiben, und viele Leute schulden ihm Geld. Zitterhand Phillipe ist als Erster dran. Er wartet an den Docks in Beutebucht und schuldet noch eine große Summe vom Spiel der letzten Woche. MacKinley schickt Euch vor die Stadt, um Elder Mistvale Gorillas zu jagen und reichlich Innereien zurückzubringen. Verschweigt, dass sie von Tieren stammen, damit Phillipe sich das Schlimmste ausmalt."},{t="Phillipes Reaktion",b="Zitterhand Phillipe schreckt vor den Innereien zurück und will nichts über ihre Herkunft wissen. Dann fragt er, ob Seewolf Euch geschickt hat."}},faq={{q="Wer ist Seewolf MacKinley?",a="Viele Leute haben Spielschulden bei Seewolf MacKinley. Er möchte Hilfe beim Eintreiben, angefangen bei Zitterhand Phillipe.",al={"wer ist mackinley","seewolf mackinley","wer vergibt zitterhand angst einjagen"}},{q="Warum will MacKinley Zitterhand Phillipe Angst einjagen?",a="Phillipe schuldet MacKinley noch eine große Summe vom Spiel der letzten Woche. MacKinley hofft, dass ein Schrecken ihn zur Zahlung bewegt.",al={"warum zitterhand erschrecken","zitterhand phillipe schulden","warum phillipe ins visier nehmen"}},{q="Welche Kreaturen liefern die Innereien?",a="MacKinley sagt, die Innereien stammen von Elder Mistvale Gorillas vor der Stadt.",al={"woher stammen die innereien","mistvale innereien herkunft","was für innereien töten"}},{q="Wo ist Zitterhand Phillipe zu finden?",a="Zitterhand Phillipe ist an den Docks in Beutebucht zu finden.",al={"wo ist zitterhand phillipe","zitterhand aufenthaltsort","zitterhand phillipe finden"}},{q="Was sollt Ihr Phillipe über die Innereien sagen?",a="Sagt nichts darüber, woher die Innereien stammen. MacKinley will, dass Phillipe sich das Schlimmste ausmalt.",al={"zitterhand die herkunft der innereien verraten"}}},fp="13,203,17.353.0,19.134.1,28.131.0,50.108.0,35.74.0,36.60.0,48.93.0"}
P.entries["quest:6061"] = {n="Die Zähmung der Bestie",s="Im Dorf der Bluthufe beginnt Yaw Scharfmähne die Ausbildung eines jungen Taurenjägers mit „Die Zähmung der Bestie“. Die erste Prüfung führt nach Mulgore, wo der Jäger einen ausgewachsenen Ebenenschreiter zähmt und ein Band mit den Geschöpfen der Erdenmutter knüpft.",h="Im Dorf der Bluthufe beginnt Yaw Scharfmähne die Ausbildung eines jungen Taurenjägers mit „Die Zähmung der...",kw={"dorf der bluthufe","erdenmutter","jägerquest","mulgore","ebenenschreiter","zähmen","zähmerrute","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger beginnt Ihr unter der Führung der Erdenmutter zu lernen, ein Band mit Tieren zu knüpfen.",["race:Tauren"]="Als Tauren erbt Ihr Mulgores überlieferte Jagdtradition, in der das Zähmen die Verbindung zwischen Jäger und Natur stärkt."},sec={{t="Ein heiliges Band zur Wildnis",b="Taurenjäger suchen mehr als Fleisch und Felle. Ihre überlieferten Bräuche lehren, dass Begegnungen mit Mulgores wilden Geschöpfen sie der Erdenmutter näherbringen können. Ein gezähmter Gefährte mag einst ein Widersacher gewesen sein. Nun wirken Tier und Jäger als Partner im natürlichen Gleichgewicht der Ebenen zusammen."},{t="Die erste Prüfung",b="Yaw Scharfmähne beginnt die Ausbildung eines Jägers mit den Ebenenschreitern, die Mulgores Grasländer durchstreifen. Mit einer verzauberten Zähmerrute tritt der Jäger einem ausgewachsenen Ebenenschreiter entgegen und besänftigt dessen wilde Instinkte, um sein Vertrauen zu gewinnen. Diese erste Prüfung stellt die Entschlossenheit des Jägers auf die Probe und bereitet ihn auf anspruchsvollere Bestien vor."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Dies ist die erste praktische Prüfung für einen jungen Taurenjäger, der lernt, ein Band mit einem Tier zu knüpfen. Die Zähmerrute besänftigt einen ausgewachsenen Ebenenschreiter und vermittelt die Grundlagen einer spirituellen Verbindung und der Zusammenarbeit mit Bestien.",al={"warum einen ebenenschreiter zähmen","zweck der quest","zweck der taurenbegleiterquest"}},{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Yaw Scharfmähne, der Jägerlehrer, vergibt die Prüfung im Dorf der Bluthufe, im Herzen Mulgores.",al={"wer vergibt die quest","standort des questgebers","yaw scharfmähne standort"}},{q="Behalte ich den ausgewachsenen Ebenenschreiter dauerhaft?",a="Nein. Die Bestien in Yaw Scharfmähnes ersten drei Prüfungen sind vorübergehende Übungspartner. Nachdem Ihr die gesamte Ausbildung abgeschlossen und das Zähmen von Bestien gemeistert habt, könnt Ihr einen geeigneten Gefährten dauerhaft zähmen.",al={"ist dieser begleiter dauerhaft","ebenenschreiter behalten","bestie nach der quest behalten"}},{q="Warum betrachten Tauren das Zähmen von Bestien als spirituellen Akt?",a="Die Tradition der Tauren lehrt, dass Jäger durch die Begegnung mit wilden Geschöpfen und deren Bezwingen ihre Geister aufnehmen und sich mit der Natur verbinden können. Eine Bestie zu zähmen zeigt Respekt und Verbundenheit mit den Geschöpfen der Erdenmutter.",al={"hintergrund zu taurenbegleitern","hintergrund zu erdenmutter und zähmung","warum tauren bestien zähmen"}},{q="Wo sind ausgewachsene Ebenenschreiter zu finden?",a="Ausgewachsene Ebenenschreiter durchstreifen die Täler und Savannen rund um das Dorf der Bluthufe in Mulgore.",al={"wo sind ebenenschreiter","ebenenschreiter standort","ausgewachsenen ebenenschreiter finden"}},{q="Was folgt auf diese Quest?",a="Wenn Ihr die Zähmerrute zu Yaw Scharfmähne zurückbringt, schickt Euch die nächste Prüfung los, um einen stalker und dann einen aggressive swoop zu zähmen. Nach diesen Prüfungen lernt Ihr, Bestien dauerhaft auszubilden.",al={"was kommt als nächstes","questreihe nach dieser quest","nächster schritt beim zähmen"}}},fx={fd2667bc={q="Warum möchte Yaw Scharfmähne, dass ich einen Ebenenschreiter zähme?",a="Yaw Scharfmähne führt Euch durch die heiligen Traditionen des Tauren-Jägers. Für Tauren ist das Besiegen und Zähmen wilder Tiere eine spirituelle Disziplin, die den Jäger näher zur Erdenmutter bringt und ihn mit der natürlichen Welt in Einklang bringt. Er beginnt Euer Training mit den flinken erwachsenen Ebenenschreitern von Mulgore, damit Ihr die Geduld und den spirituellen Fokus meistern könnt, die nötig sind, bevor Ihr eine dauerhafte Bindung mit einem Begleiter eingeht.",al={"warum ebenenschreiter zähmen","yaw scharfmähne beweggrund","warum erwachsener ebenenschreiter"}},fe0439d7={q="Warum lässt Yaw Scharfmähne mich diese Prüfung ablegen, anstatt sie selbst zu machen?",a="Dies ist ein persönlicher Ritus des Übergangs, den jeder angehende Jäger selbst durchlaufen muss. Yaw Scharfmähne ist ein erfahrener Mentor, der damit betraut ist, uralte Bräuche zu lehren, nicht die Arbeit für Euch zu erledigen. Das Zähmen einer wilden Kreatur erfordert, dass Ihr Eure eigene spirituelle Verbindung zur Natur schmiedet und Euch der Präsenz der Erdenmutter öffnet. Kein Ältester oder Wächter kann diese Bindung in Eurem Namen aufbauen.",al={"warum schickt er mich","warum yaw scharfmähne mich braucht","warum muss ich das tier zähmen"}}},fp="16,235,27.287.0,14.313.0,34.202.0,48.92.0,45.199.0,52.210.0,39.87.0,28.177.0"}
P.entries["quest:6062"] = {n="Die Zähmung der Bestie",s="In Klingenhügel stellt Die Zähmung der Bestie junge Jäger der Horde erstmals mit einer Zähmerrute auf die Probe. Thotar schickt sie gegen einen wilden, bösartigen graugesprenkelten Eber.",h="In Klingenhügel stellt Die Zähmung der Bestie junge Jäger der Horde erstmals mit einer Zähmerrute auf die...",kw={"bösartiger graugesprenkelter eber","durotar","jägerquest","begleiter zähmen","klingenhügel","zähmerrute","thotar"},ang={["class:Hunter"]="Als Jäger lernt Ihr die Bindung zu tierischen Gefährten kennen, die einen Meister der Bestien auszeichnet.",["race:Orc"]="Als Orc beweist Ihr Willensstärke, indem Ihr eine Bestie in der rauen Wildnis Durotars, Eurer neuen Heimat, beherrscht.",["race:Troll"]="Als Jäger der Dunkelspeertrolle stimmt Ihr Euren Geist auf Kalimdors raue Tierwelt ein und führt die uralten Pirschtraditionen Eures Volkes fort."},sec={{t="Die Bewährungsprobe eines Jägers",b="In Durotar müssen Jäger der Orcs und Dunkelspeertrolle lernen, die Wildnis zu beherrschen und in ihr zu überleben. Thotar gibt jungen Jägern eine verzauberte Zähmerrute und schickt sie gegen einen wilden Eber. Sie müssen die Bestie unterwerfen, ohne sie zu töten, und sie dann zu einem treuen Verbündeten machen."},{t="Die Eber von Durotar",b="Bösartige graugesprenkelte Eber durchstreifen das trockene Gestrüpp rund um Klingenhügel. Ihre Stärke und ihr Temperament machen sie zu einer passenden ersten Prüfung für junge Jäger. Die Rute kann einen heranstürmenden Eber unterwerfen, doch ihr Einsatz erfordert Geduld und Entschlossenheit. Jeder Fährtenleser der Horde braucht diese Eigenschaften."}},faq={{q="Welchen Zweck hat diese Prüfung?",a="Die Prüfung gibt jungen Jägern in Durotar ihre erste praktische Lektion im Umgang mit einer Zähmerrute. Sie lernen, ein wildes Tier zu unterwerfen, statt es zu töten.",al={"warum diese quest machen","grund für die eberzähmungsquest","zweck der zähmung der bestie"}},{q="Wer vergibt diese Quest?",a="Thotar, der Jägerlehrer in Klingenhügel, gibt Euch diese Prüfung, nachdem Ihr Eure grundlegenden Überlebensfähigkeiten in ganz Durotar bewiesen habt.",al={"questgeber","wer vergibt die zähmung der bestie","wo gibt es die eberquest"}},{q="Wo findet man die bösartigen graugesprenkelten Eber?",a="Bösartige graugesprenkelte Eber durchstreifen das trockene Buschland vor den Palisaden von Klingenhügel im Zentrum Durotars.",al={"fundort der eber","wo ist der bösartige graugesprenkelte eber","wo eber finden"}},{q="Behaltet Ihr den Eber nach dieser Quest dauerhaft?",a="Nein. Der Eber, den Ihr zähmt, dient der Übung und verlässt Euch, wenn Ihr zu Thotar zurückkehrt. Ihr setzt Eure Ausbildung mit anderen Kreaturen fort, bevor Ihr eine dauerhafte Bindung eingeht.",al={"behalte ich den eber","ist der eber mein dauerhafter begleiter","bösartigen graugesprenkelten eber behalten"}},{q="Was folgt auf diese Aufgabe?",a="Nachdem Ihr zu Thotar zurückgekehrt seid, prüft er Eure Kontrolle über andere tödliche Raubtiere Durotars, darunter surf crawlers und armored scorpid beasts.",al={"nächste quest","was folgt nach der eberzähmung","nächster schritt der zähmungsquestreihe"}},{q="Warum eine Zähmerrute statt reinen Instinkts verwenden?",a="Angehende Jäger haben noch nicht die geistige und körperliche Disziplin erlangt, um sich unmittelbar mit Bestien zu verbinden. Die verzauberte Rute richtet ihren Willen auf den Geist einer wilden Bestie, bis sie diese Kunst beherrschen.",al={"warum eine zähmerrute","was bewirkt die rute","hintergrund der zähmerrute"}}},fx={["97dfd1bd"]={q="Warum möchte Thotar, dass Ihr einen gescheckten Schreckenseber zähmt?",a="Thotar bereitet Euch darauf vor, ein wahrer Jäger der Horde zu werden. In seinen Augen ist es für Eure Disziplin wesentlich, Autorität über die Natur auszuüben und die innewohnende Stärke wilder Tiere zu nutzen. Er beginnt mit einem lokalen gescheckten Schreckenseber, damit Ihr Eure Entschlossenheit beweisen und lernen könnt, an der Seite eines Begleiters zu kämpfen, bevor Ihr zu wilderen Raubtieren übergeht.",al={"thotar beweggrund","warum eber bei thotar zähmen","warum schickt thotar euch"}},["9ea8907b"]={q="Was sind gescheckte Schreckenseber?",a="Gescheckte Schreckenseber sind robuste, aggressive Schweine, die in den trockenen Ebenen von Durotar heimisch sind. Bekannt für ihre dicken Häute, sturen Temperamente und bösartigen Stoßzähne, durchstreifen sie die Felsen und Schluchten in der Nähe von Klingenhügel auf der Suche nach Nahrung. Ihre sture Natur macht sie zu robusten ersten Partnern für einen angehenden Jäger, der die Kunst der Tierherrschaft erlernt.",al={"gescheckter schreckenseber","was ist ein gescheckter schreckenseber","gescheckte eber in durotar"}},["81608777"]={q="Warum schickt Thotar Euch auf diese Prüfung, anstatt sie selbst zu erledigen?",a="Dies ist keine Besorgung oder ein Notfall für die Verteidiger von Klingenhügel; es ist Eure persönliche Initiation als Jäger. Die Kontrolle über ein Tier zu erlangen erfordert direkte Willenskraft, Übung und persönliche Entschlossenheit, die kein Mentor oder Kundschafter in Eurem Namen erbringen kann. Thotars Rolle ist es, Euer Training zu leiten, aber die Wildnis zu meistern ist eine Last, die Ihr alleine tragen müsst.",al={"warum ich thotar","warum muss ich ihn zähmen","warum zähmt thotar ihn nicht"}}},fp="16,149,26.265.0,20.252.0,34.148.0,21.121.0,39.95.0,50.146.0,27.138.0,46.193.0"}
P.entries["quest:6063"] = {n="Die Zähmung der Bestie",s="In Dolanaar stellt sich ein junger Nachtelfenjäger mit einem wilden Webwood Lurker der ersten Prüfung von Die Zähmung der Bestie. Dazalar leiht ihm eine verzauberte Zähmerrute, und der Jäger muss durch ein Band zur Natur das Vertrauen der Spinne gewinnen.",h="In Dolanaar stellt sich ein junger Nachtelfenjäger mit einem wilden Webwood Lurker der ersten Prüfung von Die...",kw={"dazalar","dolanaar","tiergefährte des jägers","kaldorei","zähmen","zähmerrute","teldrassil","webwood lurker"},ang={["class:Hunter"]="Als Jäger werdet Ihr vom einsamen Bogenschützen zum Partner der Wildnis, verbunden mit den Tieren des Waldes.",["race:NightElf"]="Als Nachtelf lernt Ihr, durch Zwiesprache und Ehrfurcht vor der Natur zu zähmen, statt durch Unterwerfung."},sec={{t="Ein heiliges Band",b="Für die Kaldorei verlangt die Jagd mehr als Geschick beim Aufspüren von Beute oder beim Überleben in der Wildnis. Sie verbindet einen Jäger mit der Natur, die jeden Sterblichen überragt. Tiere sind eigenständige Geschöpfe, keine Werkzeuge, die dem Willen eines Jägers unterworfen werden sollen. Dazalar lehrt angehende Jäger, ihnen mit Respekt zu begegnen. Bevor ein Jäger einen lebenslangen Tiergefährten gewinnt, muss er die heimische Tierwelt durch uralte Techniken meistern, niemals durch rohe Gewalt."},{t="Die erste Prüfung",b="Riesige Spinnentiere befallen das Geäst von Teldrassil, deshalb gibt Dazalar dem Jäger eine Zähmerrute. In schattigen Dickichten sucht der Jäger einen Webwood Lurker und stellt sich den Angriffen der giftigen Spinne. Um sie zu erreichen, muss der Jäger mit Einfühlungsvermögen reagieren. Ein kurzes geistiges Band beweist, dass der Jäger mit den unheimlichen, huschenden Raubtieren des Weltbaums Zwiesprache halten kann."}},faq={{q="Welchen Zweck hat diese Quest?",a="Mit dieser Prüfung beginnt die Ausbildung der Nachtelfenjäger im Zähmen von Tiergefährten. Der Einsatz einer Zähmerrute an heimischen Wildtieren prüft die Ruhe des Jägers und sein Geschick bei der Zwiesprache mit wilden Raubtieren.",al={"warum diese quest machen","zweck der tiergefährtenquest","was bringt die zähmung der bestie"}},{q="Wer vergibt diese Quest?",a="Dazalar, ein Jägerlehrer in Dolanaar auf Teldrassil, bietet die Prüfung jungen Nachtelfenjägern mit ausreichender Erfahrung an.",al={"questgeber","wo gibt es die zähmquest","wer startet die zähmung der bestie"}},{q="Welches Geschöpf muss in dieser Prüfung gezähmt werden?",a="Ihr müsst einen Webwood Lurker zähmen, eine giftige Riesenspinne aus den wilden Dickichten und Wäldern außerhalb von Dolanaar.",al={"welchen tiergefährten zähmen","webwood lurker als ziel","welches wildtier zähmen"}},{q="Behalte ich den Webwood Lurker dauerhaft?",a="Nein. Der Webwood Lurker ist ein vorübergehender Gefährte, mit dem Ihr die Grundlagen des Umgangs mit Wildtieren übt. Wenn Ihr zu Dazalar zurückkehrt, endet das Band, während Ihr Euch auf die nächste Prüfung vorbereitet.",al={"spinne behalten","ist der webwood lurker dauerhaft","tiergefährten behalten"}},{q="Warum prüfen Nachtelfen Jäger zuerst mit Spinnen?",a="Webwood Lurker sind räuberisch und aggressiv und stellen die Besonnenheit eines angehenden Jägers auf die Probe. Ein Spinnentier zu meistern zeigt, dass ein Jäger sein Bewusstsein mit feindseligen Formen der Natur verbinden kann.",al={"warum webwood lurker","warum eine spinne zähmen","hintergrund zum spinnenzähmen"}},{q="Was folgt nach der Rückkehr zu Dazalar?",a="Nach Eurer Rückkehr zu Dazalar schickt er Euch los, um Euer Band mit einem Nightsaber Stalker und einem Strigid Screecher zu erproben, beide auf Teldrassil heimisch. Dann gewährt er Euch dauerhafte Zähmfähigkeiten.",al={"was kommt danach","nach der zähmung der bestie","nächste prüfung"}}},fx={["641cd576"]={q="Warum möchte Dazalar, dass dies erledigt wird?",a="Dazalar glaubt, dass die Natur keine Kraft ist, die dem Willen eines Sterblichen unterworfen werden kann, sondern eine Macht, die tiefe Ehrfurcht und Respekt erfordert. Bevor er Euch die beständige Kunst des Zähmens wilder Tiere anvertraut, muss er sicherstellen, dass Ihr diese heilige Pflicht begreift. Die Prüfung testet, ob Ihr die Geduld und Demut besitzt, die von einem wahren Kaldorei-Jäger verlangt wird, anstatt wilde Kreaturen wie bloße Werkzeuge zu behandeln.",al={"warum prüft dazalar euch","dazalar beweggrund","zweck der dazalar prüfung"}},a645c3ca={q="Warum schickt Dazalar Euch, anstatt dies selbst zu erledigen?",a="Dies ist ein wesentlicher Ritus des Übergangs für Euer eigenes Wachstum als Jäger. Dazalar hat die Wildnis bereits gemeistert; seine Rolle ist es, Euren Fortschritt zu leiten und zu bewerten. Die Prüfung erfordert, dass Ihr aus eigenem Willen eine Bindung schmiedet und beweist, dass Ihr die notwendige Disziplin erlernt habt, um an der Seite der Kreaturen von Teldrassil als vertrauenswürdiger Wächter zu wandeln.",al={"warum muss ich die spinne zähmen","warum ich dazalar","warum macht dazalar es nicht selbst"}}},fp="16,220,13.403.0,15.339.0,34.176.0,21.124.0,42.106.0,41.161.0,51.182.0,38.180.1"}
P.entries["quest:6064"] = {n="Die Zähmung der Bestie",s="In Dun Morogh stellt Die Zähmung der Bestie einen Jäger vor die erste Prüfung im Umgang mit Tiergefährten. In Kharanos leitet Grif Wildherz junge Fährtenleser an, mit einer verzauberten Zähmerrute einen Großen Felseber zu besänftigen.",h="In Dun Morogh stellt Die Zähmung der Bestie einen Jäger vor die erste Prüfung im Umgang mit Tiergefährten.",kw={"bestie","eber","felseber","dun morogh","grif wildherz","jäger","kharanos","zähmung","zähmerrute"},ang={["class:Hunter"]="Als Jäger werdet Ihr vom unerfahrenen Schützen zum Meister der Tiere und beginnt die Prüfungen, die Euch dauerhafte Tiergefährten ermöglichen.",["race:Dwarf"]="Als Zwerg folgt Ihr den Gebirgsjägern von Eisenschmiede, die Tiere verehren, die der beißenden Kälte von Dun Morogh trotzen können. Mit dem widerstandsfähigen Felseber zu beginnen, spiegelt die zwergische Achtung vor Zähigkeit und Ausdauer wider."},sec={{t="Der Gefährte eines Jägers",b="Zwergische Gebirgsjäger und Fährtenleser verlassen sich in der Wildnis auf Gewehre, Fallen und ihren Verstand. Doch die Berufung eines Jägers ist es, einen lebenslangen Bund mit einem wilden Tier zu schließen. Vor der Brauerei Donnerbräu in Kharanos wacht Grif Wildherz über diesen Ritus. Er prüft Neulinge an mehreren in Dun Morogh heimischen Tierarten, bevor er sie auffordert, ein Tier dauerhaft an sich zu binden."},{t="Der Felseber",b="Ein Großer Felseber ist die erste Prüfung für einen jungen Fährtenleser. Diese dickhäutigen Schweine durchstreifen die verschneiten Ausläufer von Dun Morogh, wo ihr borstiges Fell und ihr zähes Fleisch sie störrisch und wild machen. Grif stellt eine verzauberte Zähmerrute bereit. Der Jäger stellt sich dem Ansturm des Ebers und versucht, dessen Wut zu besänftigen, bis er sich seinem Befehl unterwirft."}},faq={{q="Wer bietet diese Prüfung an?",a="Grif Wildherz bietet die Prüfung vor der Brauerei Donnerbräu in Kharanos an, wo er zwergische Jäger ausbildet.",al={"questgeber","wer startet die zähmung der bestie","grif wildherz standort"}},{q="Warum zähme ich zuerst einen Großen Felseber?",a="Große Felseber sind kräftig und störrisch, kommen aber auf den verschneiten Bergrücken von Dun Morogh in großer Zahl vor. Einen zu zähmen, gibt Euch erstmals Gelegenheit, einem angriffslustigen, dickhäutigen Tier mit Ruhe Befehle zu erteilen.",al={"warum felseber","welches tier zähmen","eber zähmen"}},{q="Darf ich diesen Eber für immer behalten?",a="Nein. Der mit der Zähmerrute geschlossene Bund ist vorübergehend. Ihr könnt dem Eber Befehle erteilen, dann die Rute zurückgeben und Euch an anderen Tierarten versuchen.",al={"ist dieser eber dauerhaft","felseber behalten","tiergefährten behalten"}},{q="Wo finde ich Große Felseber?",a="Große Felseber durchstreifen die offenen Schneefelder und Kiefernhainе rund um Kharanos sowie die gefrorenen Hänge von Dun Morogh.",al={"eber fundorte","wo sind große felseber","großer felseber erscheinungsort"}},{q="Was folgt nach der Zähmung des Felsebers?",a="Wenn Ihr zu Grif Wildherz zurückkehrt, ist die erste Lektion abgeschlossen und die zweite Prüfung beginnt: einen Snow Leopard zu zähmen.",al={"nächste prüfung","was folgt nach dieser quest","jäger questreihe fortsetzung"}},{q="Wie funktioniert die Zähmerrute?",a="Jägerlehrer stellen eine verzauberte Zähmerrute bereit, die Neulingen hilft, ihren Willen zu bündeln und wilde Instinkte zu besänftigen. Dafür braucht es weder eine fortgeschrittene magische Ausbildung noch lebenslange Erfahrung im Flüstern mit Tieren.",al={"zähmerrute hintergrund","was ist die rute","wie zähmen"}}},fx={["49cdd252"]={q="Warum möchte Grif Wildherz, dass Ihr ein Tier zähmt?",a="Grif Wildherz trainiert Euch in den Grundlagen, ein wahrer Zwergenjäger zu sein. In seinen Augen ist es genauso wichtig zu wissen, wie man eine Bindung zu einem tierischen Begleiter aufbaut und ihn befehligt, wie die Pflege Eurer Waffe. Anstatt Euch ein Haustier zu geben, glaubt er, dass der einzig richtige Weg zu lernen die praktische Erfahrung in der Wildnis ist, bei der Ihr Eure Geduld und Meisterschaft gegen verschiedene Arten lokaler Kreaturen testet, bevor Ihr Euch für einen dauerhaften Begleiter entscheidet.",al={"grif wildherz beweggrund","warum ein tier zähmen","grif wildherz training grund"}}},fp="16,210,20.345.0,13.318.0,22.112.0,38.179.0,35.122.0,34.113.0,38.115.0,29.192.0"}
P.entries["quest:6065"] = {n="Der Weg des Jägers",s="In Mulgore schickt Der Weg des Jägers junge Tauren zur weiterführenden Ausbildung ins Dorf der Bluthufe. Dort suchen sie Yaw Scharfmähne auf und beginnen die Prüfungen im Zähmen wilder Bestien und im Aufbau einer Bindung zu ihnen.",h="In Mulgore schickt Der Weg des Jägers junge Tauren zur weiterführenden Ausbildung ins Dorf der Bluthufe.",kw={"bestie","dorf der bluthufe","camp narache","weg des jägers","mulgore","begleiterquest","zähmen","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger macht Ihr Euren ersten Schritt vom Bogenschützen oder Gewehrschützen zum Meister der Bestien, mit einem treuen Begleiter an Eurer Seite.",["faction:Horde"]="Als Jäger der Horde verlasst Ihr Euch auf wilde Bestien aus den Grenzgebieten, um die Front zu verteidigen und in Kalimdors rauer Wildnis Fährten zu lesen.",["race:Tauren"]="Als Angehöriger der Shu'halo lernt Ihr, wilde Bestien zu zähmen, als Ausdruck der Ehrfurcht vor der Natur und der Schöpfung der Earth Mother."},sec={{t="Ein Übergangsritus",b="Bei den Shu'halo ist die Jagd heilig. Ein Jäger lernt das Gleichgewicht der Natur kennen, ehrt die Geister der Ebenen und achtet die Tiere, die die Stämme ernähren. Nachdem junge Jäger bewiesen haben, dass sie in der Wildnis überleben und mit Bogen oder Gewehr umgehen können, schicken ihre Ältesten sie zu erfahrenen Lehrmeistern. Die Reise markiert in der Kultur der Tauren ihren Schritt über das einsame Fährtenlesen hinaus und hin zum Erwachsensein."},{t="Zum Dorf der Bluthufe",b="Die Straße zum Dorf der Bluthufe führt durch Mulg ores Grasland und erreicht die Siedlung am Stonebullsee. Dort unterrichtet Yaw Scharfmähne Jäger über die einheimischen Bestien. Die Begegnung mit ihm zeigt, dass ein Jäger für die Prüfungen im Zähmen von Bestien bereit ist. Sie lernen, mit Raubtieren Zwiesprache zu halten und sie auch zu jagen."}},faq={{q="Welchem Zweck dient der Weg des Jägers?",a="Der Weg des Jägers schickt unerfahrene Taurenjäger ins Dorf der Bluthufe, um ihre Prüfungen im Zähmen von Bestien zu beginnen. Dort sprechen sie mit Yaw Scharfmähne, der die Rituale zur Bindung an einen tierischen Begleiter leitet.",al={"warum diese quest erhalten","zweck des wegs des jägers","start der jägerbegleiterquest"}},{q="Wer schickt Euch auf diese Quest?",a="Jägerlehrer der Tauren schicken angehende Jäger los, nachdem diese die Grundlagen des Überlebens und der Schießkunst gemeistert haben. Kary Thunderhorn in Donnerfels ist einer dieser Lehrer.",al={"wer vergibt den weg des jägers","jägerlehrerquest"}},{q="Wer ist Yaw Scharfmähne?",a="Yaw Scharfmähne ist ein angesehener Jägerlehrer der Tauren im Dorf der Bluthufe. Er lehrt junge Jäger, sich Mulg ores wilden Bestien zu nähern, sie zu beruhigen und zu zähmen.",al={"wer ist scharfmähne","yaw scharfmähnes rolle"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Nachdem Ihr mit Yaw Scharfmähne gesprochen habt, beginnt Ihr die Prüfungen von Taming the Beast. Ihr zieht mit einer Zähmerrute in die Wildnis und besänftigt mehrere einheimische Kreaturen, bevor Ihr das Recht erlangt, einen dauerhaften Begleiter auszubilden.",al={"what comes next","nächste quest nach dem weg des jägers"}},{q="Warum gehen Taurenjäger Bindungen mit Bestien ein, statt sie nur zu jagen?",a="Nach der Tradition der Tauren sind Bestien verwandte Geister der Earth Mother. Ein Tier, mit dem eine Bindung besteht, ist ein Begleiter und Jagdgefährte, verbunden durch gegenseitigen Respekt und das gemeinsame Überleben auf den Ebenen.",al={"hintergrund der taurenbegleiter","warum tauren begleiter zähmen"}},{q="Können Jäger anderer Völker diese bestimmte Quest annehmen?",a="Dieser Weg ist für Taurenjäger bestimmt, die in Mulgore ausgebildet werden. Andere Völker der Horde, etwa Orcs und Trolle, erhalten ähnliche Ausbildungsanweisungen in ihren Heimatgebieten in Durotar.",al={"nur für tauren","können orcs den weg des jägers für tauren machen"}}},fx={a380c02c={q="Warum schickt Euer Ausbilder Euch zu Yaw Scharfmähne?",a="Euer Ausbilder erkennt, dass Ihr in der Wildnis erfahren genug geworden seid, um den nächsten entscheidenden Schritt im Leben eines Jägers zu machen: die Bindung zu einem tierischen Begleiter und dessen Ausbildung. Sie schicken Euch zu Yaw Scharfmähne im Dorf der Bluthufe, weil er über das spezialisierte Wissen und die uralten Traditionen verfügt, die erforderlich sind, um Euch durch die Prüfungen des Tierzähmens zu führen.",al={"warum zu yaw scharfmähne","ausbilder beweggrund pfad des jägers","warum nach bloodhoof schicken"}}},fp="17,183,17.365.0,29.299.0,41.203.0,28.158.0,21.148.0,41.210.0,68.182.0,52.170.0"}
P.entries["quest:6068"] = {n="Der Weg des Jägers",s="In Durotar führt der Weg des Jägers junge Orc- und Trolljäger nach Klingenhügel. Dort lehrt Thotar sie, wilde Raubtiere an sich zu binden.",h="In Durotar führt der Weg des Jägers junge Orc- und Trolljäger nach Klingenhügel.",kw={"durotar","jägerlehrer","weg des jägers","begleiterquest","klingenhügel","tier zähmen","thotar"},ang={["class:Hunter"]="Als Jäger geht Ihr vom einsamen Kampf dazu über, das Befehligen von Tieren zu erlernen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr ihren Spähern und Fährtenlesern, Durotars Raubtiere zu zähmen und das raue Land zum Vorteil Eures Volkes zu nutzen.",["race:Orc"]="Als Orcjäger folgt Ihr einer Tradition, die mit den Wolfsreitern von Draenor verbunden ist, wenn Ihr einen wilden Begleiter an Euch bindet.",["race:Troll"]="Als Dunkelspeerjäger lernt Ihr, heimische Raptoren und Eber zu zähmen, um in Durotars gefährlicher Wildnis Fuß zu fassen."},sec={{t="Das Erwachen eines Jägers",b="In Durotar lernen junge Jäger, Beute mit Bogen und List zu verfolgen. Fährten durch rote Lehmschluchten und karges Buschland lehren sie Geduld. Um die Jagdweise der Horde zu meistern, müssen sie auch lernen, ein Band mit wilden Tieren zu knüpfen. Wenn Klassenlehrer einen Schüler für bereit halten, schicken sie ihn nach Klingenhügel."},{t="Der Meister in Klingenhügel",b="In Klingenhügel lehrt Thotar junge Jäger, Durotars wilde Tiere zu unterwerfen, ohne ihren Geist zu brechen. Seine Lektionen sind der Anfang ihres Weges, die Wildnis mit einem treuen Begleiter zu durchstreifen."}},faq={{q="Welchen Zweck hat der Weg des Jägers?",a="Junge Orc- und Trolljäger gehen nach Klingenhügel, um zu lernen, wie man Tiere zähmt.",al={"warum den weg des jägers machen","zweck der quest der weg des jägers","was bewirkt diese quest"}},{q="Wer ist Thotar?",a="Thotar ist ein erfahrener Jäger in Klingenhügel, der junge Fährtenleser der Horde lehrt, wilde Tiere an sich zu binden und zu befehligen.",al={"thotar wer ist er","wer ist thotar","thotar klingenhügel"}},{q="Warum können junge Jäger nicht sofort Begleiter zähmen?",a="Junge Jäger brauchen Disziplin, Geduld und eine besondere Ausbildung, um gefährliche Raubtiere zu kontrollieren. Ohne grundlegende Überlebensfertigkeiten laufen sie Gefahr, schwer verletzt oder getötet zu werden.",al={"warum kein begleiter auf stufe eins","warum müssen jäger auf begleiter warten","wann bekommen jäger begleiter"}},{q="Welche Völker stellen sich dieser besonderen Prüfung?",a="Orcs und Dunkelspeertrolle in Durotar stellen sich dieser Prüfung, während Taurenjäger in Mulgore eine ähnliche bestehen müssen.",al={"wer bekommt diese quest","ist das nur für orcs und trolle","welche völker machen das"}},{q="Was geschieht, nachdem Ihr Euch bei Thotar gemeldet habt?",a="Nachdem Ihr Euch bei Thotar gemeldet habt, schickt er Euch los, um in ganz Durotar heimische Raubtiere aufzuspüren und zu unterwerfen. Dort beweist Ihr Euer Geschick beim Zähmen von Tieren.",al={"what comes next","nach dem weg des jägers","nächste quest nach thotar"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung konzentriert sich auf Klingenhügel, die wichtigste Siedlung im Zentrum Durotars, zwischen dem Tal der Prüfungen und Orgrimmar.",al={"wo ist klingenhügel","thotar standort","wohin gehen"}}},fx={df5b309b={q="Warum schickt der Ausbilder Euch zu Thotar?",a="Eure anfänglichen Klassenausbilder erkennen, dass Ihr die grundlegenden Fähigkeiten in Bogenschießen und Überleben entwickelt habt, die notwendig sind, um größere Verantwortungen zu übernehmen. Um als wahrer Jäger der Horde voranzukommen, müsst Ihr eine Bindung mit einem tierischen Begleiter eingehen, und Thotar in Klingenhügel ist der Meister, der damit betraut ist, vielversprechende Orcs und Trolle durch die heiligen Prüfungen des Zähmens zu führen.",al={"warum zu thotar","warum thotar","ausbilder grund thotar"}}},fp="17,129,20.299.0,24.193.0,41.82.0,14.111.0,46.158.0,42.110.0,39.139.0,36.119.0"}
P.entries["quest:6069"] = {n="The Hunter's Path",s="Thotar in Klingenhügel kann Euch helfen, einen tierischen Begleiter zu gewinnen. Ihr werdet ausgesandt, um mit ihm zu sprechen.",h="Thotar in Klingenhügel kann Euch helfen, einen tierischen Begleiter zu gewinnen.",kw={"wildtier","gefährte","jäger","pfad des jägers","begleiter","klingenhügel","thotar"},ang={["class:Hunter"]="Als Jäger hält man Euch für geschickt genug, mit einem Wildtier umzugehen und es zu Eurem Begleiter auszubilden."},sec={{t="Ein tierischer Begleiter",b="Ein Ausbilder erkennt Euer Geschick im Umgang mit Wildtieren und schickt Euch zu Thotar in Klingenhügel. Er kann Euch dabei helfen, einen eigenen Begleiter zu gewinnen."}},faq={{q="Mit wem soll ich sprechen?",a="Sprecht mit Thotar in Klingenhügel.",al={"mit wem sprechen","wohin gehen","thotar quest"}},{q="Wobei kann Thotar mir helfen?",a="Thotar kann Euch dabei helfen, einen eigenen Begleiter zu gewinnen.",al={"was macht thotar","begleiter bekommen","jägerbegleiter"}},{q="Warum werde ich zu Thotar geschickt?",a="Ein Ausbilder glaubt, dass Ihr geschickt genug seid, mit einem Wildtier umzugehen und es als Begleiter auszubilden.",al={"warum thotar","wozu das ganze","pfad des jägers"}}},fp="17,100,17.138.0,24.32.0,29.54.0,30.85.0"}
P.entries["quest:607"] = {n="Rückkehr zu MacKinley",s="Ihr bringt Phillipes Beutel zu Seewolf MacKinley, dem noch Geld geschuldet wird. Phillipe sagt, er habe die ganze Zeit zahlen wollen, und bittet Euch um Nachsicht.",h="Ihr bringt Phillipes Beutel zu Seewolf MacKinley, dem noch Geld geschuldet wird.",kw={"schulden","mackinley","seewolf","zitterhand phillipe","schlingendorntal"},sec={{t="Zitterhands Bitte",b="Zitterhand Phillipe überreicht Euch einen Beutel mit der Bezahlung für Seewolf MacKinley. Er schwört, dass er die Schulden immer zurückzahlen wollte. Phillipe sagt, er sei ein wenig betrunken gewesen und habe den Weg verloren. Er glaubt, MacKinley werde das verstehen, und beteuert, es gebe keinen Grund, grob zu werden."},{t="Seewolf hört die Geschichte",b="Seewolf MacKinley kichert, als er sich daran erinnert, wie er Phillipe die Innereien gezeigt hat. Er fragt, wie heftig Phillipe gezittert hat. MacKinley sagt, Phillipe sei leicht zu durchschauen und beim Kartenspielen gewinne er mühelos gegen ihn."}},faq={{q="Wer gibt Euch den Beutel?",a="Zitterhand Phillipe gibt Euch einen Beutel mit der Bezahlung für Seewolf MacKinley.",al={"wer gibt rückkehr zu mackinley","wo beginnt rückkehr zu mackinley"}},{q="Welche Ausrede hat Phillipe dafür, dass er nicht gezahlt hat?",a="Phillipe sagt, er sei ein wenig betrunken gewesen und habe den Weg verloren, schwört aber, dass er die Schulden immer zurückzahlen wollte.",al={"warum hat zitterhand nicht gezahlt","phillipes ausrede","warum war zitterhand phillipe spät dran"}},{q="Was kam vor diesem Schritt?",a="Zuvor ließ MacKinley Euch Phillipe in Scaring Shaky mit Innereien erschrecken.",al={"was kommt vor rückkehr zu mackinley","vorherige quest"}}},fp="19,139,12.248.0,23.205.1,24.69.0,46.99.0,27.79.0"}
P.entries["quest:6074"] = {n="Der Weg des Jägers",s="In Dun Morogh schicken die Ausbilder bereite Jäger nach Kharanos, um das Zähmen wilder Bestien zu erlernen. Grif Wildherz leitet dort die Prüfungen.",h="In Dun Morogh schicken die Ausbilder bereite Jäger nach Kharanos, um das Zähmen wilder Bestien zu erlernen.",kw={"dun morogh","grif wildherz","jäger","kharanos","olmin burningbeard","begleiterquest","zähmen","tristane shadowstone"},ang={["class:Hunter"]="Als Jäger beginnt Ihr, das einsame Fährtenlesen hinter Euch zu lassen, und lernt, wilde Raubtiere zu befehligen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Gebirgsjäger schon lange Bären und Eber als vertraute Gefährten bei Erkundungen auf den verschneiten Gipfeln von Dun Morogh halten."},sec={{t="Die wahre Berufung eines Jägers",b="Unerfahrene Jäger durchstreifen die verschneiten Felsen von Dun Morogh allein, bis sie lernen, eine Bindung zu Bestien aufzubauen. Olmin Burningbeard und Tristane Shadowstone beobachten ihre Schüler genau. Sie warten, bis ein Jäger einer wilden Kreatur ruhig entgegentreten und ihr Leben verschonen kann. Dann schicken die Ausbilder den disziplinierten Neuling über die Bergstraßen hinab nach Kharanos."},{t="Bei Grif Wildherz melden",b="In Kharanos leitet Grif Wildherz die abschließenden Prüfungen der zwergischen Jagdkunst. Eine Bestie zu zähmen erfordert mehr, als sie für Fleisch oder Fell zu erlegen. Ein Jäger braucht Geduld, körperliche Ausdauer und eine instinktive Bindung zu den wilden Raubtieren der Berge. Wildheart bereitet jeden Jäger darauf vor, seinen Willen gegen die wildesten Tiere von Dun Morogh auf die Probe zu stellen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Bereite Jäger reisen nach Kharanos, um unter Grif Wildherz mit den Zähmungsprüfungen zu beginnen.",al={"warum diese quest machen","was ist der weg des jägers","start der jägerbegleiterquest"}},{q="Wer schickt mich auf diesen Weg?",a="Jägerausbilder führen ihre Schüler auf diesen Weg. Zu ihnen gehören Olmin Burningbeard in der Hall of Arms von Eisenschmiede, Tristane Shadowstone und Einris Brightspear.",al={"questgeber","wer vergibt den weg des jägers","wo annehmen"}},{q="Wo finde ich Grif Wildherz?",a="Grif Wildherz wartet vor der Brauerei Donnerbräu in Kharanos, im verschneiten Tal von Dun Morogh.",al={"grif wildherz standort","wo ist grif","kharanos jägerausbilder"}},{q="Warum brauchen Jäger einen Ausbilder, um Bestien zu zähmen?",a="Jäger nutzen besondere Techniken und eine Zähmerrute, um mit wilden Bestien in Verbindung zu treten, ohne einen Kampf auf Leben und Tod heraufzubeschwören. Grif Wildherz lehrt diese Traditionen.",al={"warum zähmausbildung nötig","hintergrund zum zähmen von begleitern","warum zähmen noch nicht möglich"}},{q="Was geschieht, nachdem ich mich bei Grif Wildherz gemeldet habe?",a="Nachdem Ihr Euch bei Grif Wildherz gemeldet habt, stellt er Euch auf die Probe. Er schickt Euch mit einer Zähmerrute in die Wildnis, um mehrere unterschiedliche, in Dun Morogh heimische Bestien zu bändigen.",al={"nächste quest","was folgt auf den weg des jägers","questreihe danach"}},{q="Kann jeder Jäger diese bestimmte Quest annehmen?",a="Diese Aufforderung führt zwergische Jäger in Dun Morogh zum örtlichen Ausbilder in Kharanos.",al={"nur für zwerge","auch für nachtelfen möglich","volksbeschränkung"}}},fx={["5e8bda0f"]={q="Warum schicken die Jägerausbilder Euch zu Grif Wildherz?",a="Eure Ausbilder erkennen, dass Ihr die grundlegenden Fähigkeiten entwickelt habt, die notwendig sind, um mit wilden Tieren zu kommunizieren und sie zu verwalten. Anstatt die standardmäßige Kampfunterweisung fortzusetzen, verweisen sie Euch an Grif Wildherz in Kharanos, damit Ihr ein spezialisiertes Training durchlaufen könnt. In ihren Augen ist die Beherrschung der Kunst der tierischen Begleitung der wesentliche nächste Meilenstein in Eurem Wachstum als wahrer Jäger.",al={"warum zu grif schicken","jägerausbilder beweggrund","warum zu grif wildherz"}}},fp="17,143,23.329.0,27.347.0,34.77.0,26.159.0,32.98.0,45.156.0,47.164.0,40.84.0"}
P.entries["quest:608"] = {n="Die Blutsegelbukaniere",s="Im Schlingendorntal sammeln die Blutsegelbukaniere ihre Kräfte für einen Angriff. Flottenmeister Seehorn will nicht seine ganze Flotte bei einem Gegenschlag riskieren, also schickt er eine kleine Mannschaft gegen ihre Anführer, bevor sie losschlagen können.",h="Im Schlingendorntal sammeln die Blutsegelbukaniere ihre Kräfte für einen Angriff.",kw={"blackwater","blutsegel","beutebucht","firallon","keelhaul","piraten","seehorn","stillwater"},sec={{t="Die Piratenflotte enthaupten",b="Flottenmeister Seehorn will den Angriff der Blutsegelbukaniere aufhalten, bevor er an Stärke gewinnt. Er spottet über Flottenmeister Firallons seemännisches Können und beschließt dann, die Befehlshaber anzugreifen. Seehorn will keine große Seeschlacht riskieren. Stattdessen schickt er eine kleine Mannschaft in Firallons Landelager, um Firallon, Captain Stillwater und Captain Keelhaul zu töten. Ohne ihre Anführer werden die Bukaniere ohne Kommando dastehen."}},faq={{q="Wer befiehlt den Schlag gegen die Führung der Blutsegelbukaniere?",a="Flottenmeister Seehorn in Beutebucht befiehlt den Schlag. Er hofft, die feindliche Flotte zu zerschlagen, bevor sie angreifen kann.",al={"wer vergibt die quest zu den blutsegelbukanieren","questgeber der blutsegelbukaniere","wer schickt abenteurer gegen firallon"}},{q="Welche Befehlshaber der Bukaniere müssen ausgeschaltet werden?",a="Die Ziele sind Flottenmeister Firallon, Captain Stillwater und Captain Keelhaul, die Anführer der Blutsegelstreitkräfte.",al={"ziele für blutsegelbukaniere","zu tötende blutsegelbefehlshaber","wer sind die blutsegelanführer"}},{q="Warum schickt Flottenmeister Seehorn Abenteurer statt seiner Schiffe?",a="Seehorn glaubt, dass eine fähige Mannschaft das Landelager angreifen und die feindlichen Offiziere töten kann. Das könnte die Flotte zu Fall bringen, ohne seine Schiffe zu gefährden.",al={"warum abenteurer zu firallon schicken","warum nicht die blackwater fleet schicken","seehorns plan"}},{q="Wo fügt sich dieser Zusammenstoß in die größere Auseinandersetzung mit den Blutsegelbukanieren ein?",a="Der Zusammenstoß folgt auf die Entdeckung der schriftlichen Angriffspläne der Bukaniere während der früheren Nachforschungen zu den Blutsegelbukanieren im Schlingendorntal.",al={"vorherige blutsegelquest","welche quest kommt davor","reihenfolge der blutsegelquestreihe"}}},fp="24,214,29.399.0,50.110.0,49.113.0,68.147.0,85.151.0"}
P.entries["quest:6081"] = {n="Die Ausbildung des Tiers",s="In Durotar werden junge Jäger der Orcs und Trolle zum erfahrenen Meisterjäger Ormak Grimmschlag geschickt, um von ihm zu lernen. Nachdem sie sich im Umgang mit den Tieren der Ebenen bewährt haben, reisen sie von Klingenhügel nach Orgrimmar. Dort lernen sie, einen lebenslangen tierischen Begleiter zu pflegen, zu füttern und auszubilden.",h="In Durotar werden junge Jäger der Orcs und Trolle zum erfahrenen Meisterjäger Ormak Grimmschlag geschickt, um...",kw={"durotar","jägerbegleiter","orgrimmar","ormak grimmschlag","klingenhügel","thotar","die ausbildung des tiers","tal der ehre"},ang={["class:Hunter"]="Für Euch als Jäger macht diese Ausbildung Euer Tier zu einem dauerhaften, verlässlichen Verbündeten statt zu einer flüchtigen Beschwörung. Ihr erlernt die Fähigkeiten Feed Pet und Revive Pet.",["faction:Horde"]="Die Horde ist auf Späher und Tiere angewiesen, um die gefährdeten Grenzen Durotars und des Brachlands gegen Einfälle von Zentauren, Stachelebern und der Allianz zu sichern.",["race:Orc"]="Für einen Orc ist die Bindung zu einem Jagdbegleiter eine Frage kriegerischer Ehre und Pflicht, die sich im Kampf in Durotars rauen Grenzgebieten bewähren muss.",["race:Troll"]="Für Dunkelspeertrolle, die sich in Kalimdor eine neue Heimat schaffen, ist die Verständigung mit Durotars wilden Kreaturen entscheidend für die Erkundung und das Überleben auf unbekanntem Boden."},sec={{t="Jenseits der Wildnis",b="In Durotars trockenen Schluchten sind Geschick mit dem Bogen und das Überleben in der Wildnis nur ein Teil der Pflichten eines Jägers. Junge Jäger zähmen zunächst die Tiere der Ebenen: wilde Eber, Aaskrabben und gepanzerte Skorpidpirscher. Sobald sie ihre Zähigkeit bewiesen haben, schickt Thotar sie von Klingenhügel nach Norden durch die roten Lehmschluchten zu Orgrimmars befestigten Toren. Dort müssen sie Verantwortung für einen Begleiter übernehmen."},{t="Das Tal der Ehre",b="In Orgrimmars Tal der Ehre verfeinern erfahrene Pirscher und Krieger ihr Handwerk. Dort suchen junge Jäger Ormak Grimmschlag auf, einen der verehrten Meisterjäger der Horde. Er blickt über ihre Jugend hinweg und prüft, ob sie die Geduld haben, ein Tier zu befehligen und durch Hungersnot, Kampf und Verlust zu versorgen."},{t="Verbunden mit der Wildnis",b="Ein mit Gewalt bezwungenes Tier bleibt wild, bis Jäger und Begleiter einander verstehen. Ormak lehrt die Traditionen, die ihre Bindung erhalten: welche Nahrung den Geist jeder Kreatur nährt, wie Disziplin einem Tier tödliche Techniken vermittelt und welche geistige Konzentration nötig ist, um ein im Dienst gefallenes Tier wiederzubeleben."}},faq={{q="Wer vergibt die Quest „Die Ausbildung des Tiers“?",a="Thotar, der Jägerlehrer vor der Kaserne in Klingenhügel, bietet diese Ausbildung an, nachdem Ihr alle drei Prüfungstiere in Durotar bezwungen habt.",al={"questgeber","wer vergibt die ausbildung des tiers","wo beginnt die ausbildung des tiers"}},{q="Wo finde ich Ormak Grimmschlag?",a="Ormak Grimmschlag befindet sich in Orgrimmars Tal der Ehre, einem östlichen Viertel, unter erfahrenen Jägern und Kriegern, die dort als Lehrmeister dienen.",al={"ormak grimmschlag standort","ormak grimmschlag finden","wo ist ormak"}},{q="Welche Fähigkeiten lehrt Euch Ormak Grimmschlag?",a="Ormak lehrt Euch, Eurem Begleiter aktive und passive Fähigkeiten beizubringen, ihn zu füttern, damit er treu und zufrieden bleibt, und ihn wiederzubeleben, falls er im Kampf stirbt.",al={"was lerne ich","fähigkeiten als questbelohnung","fähigkeiten des jägerbegleiters"}},{q="Warum müssen Jäger der Orcs und Trolle dafür Orgrimmar aufsuchen?",a="Örtliche Lehrer wie Thotar vermitteln die Grundlagen des Überlebens in der Wildnis. Die älteren Späher und verehrten Fährtenleser der Horde, darunter Ormak Grimmschlag, bewahren in der Hauptstadt das höhere Wissen der Tierherrschaft.",al={"warum nach orgrimmar reisen","warum orgrimmar","besuch im tal der ehre"}},{q="Absolvieren andere Völker der Horde genau diese Quest?",a="Nein. Jäger der Orcs und Trolle, die in Durotar beginnen, durchlaufen diesen Ritus. Taurenjäger folgen in Mulgore unter ihren eigenen Stammesmeistern einem ähnlichen Ritual.",al={"können tauren das machen","nur für orcs","untoter jäger"}},{q="Was geschieht, wenn ein Jäger diese Ausbildung nicht abschließt?",a="Ohne diese Ausbildung kann ein Jäger einen Begleiter weder füttern noch richtig ausbilden oder wiederbeleben. Ein gefangenes Tier wird unzufrieden und schwach und verlässt seinen Jäger womöglich eines Tages.",al={"ist das erforderlich","kann ich die ausbildung des tiers überspringen"}}},fx={["3f046eec"]={q="Warum schickt Thotar Euch zu Ormak Grimmschlag?",a="Thotar hat Euch durch die Riten des Zähmens der wilden Tiere von Durotar geführt, aber zu wissen, wie man eine Bindung zu einer Kreatur aufbaut, ist nur die halbe Kunst des Jägers. Ein in der Wildnis gefangenes Tier wird verhungern oder Euch verlassen, wenn es vernachlässigt wird. Thotar schickt Euch weiter zu Ormak Grimmschlag, damit ein Veteran des Tal der Ehre Euch beibringen kann, wie Ihr Euren neuen Begleiter richtig füttert, pflegt und diszipliniert.",al={"warum will thotar dass dies erledigt wird","thotar beweggrund training des tieres","warum ormak besuchen"}}},fp="18,266,31.396.0,19.306.0,21.311.0,40.141.0,32.112.0,42.150.0,62.182.0,48.149.0,60.166.0"}
P.entries["quest:6082"] = {n="Die Zähmung der Bestie",s="In Durotar steht ein junger Jäger der Horde vor der letzten Prüfung der Zähmung der Bestie. Thotar in Klingenhügel schickt den Jäger aus, einen gepanzerten Skorpid zu zähmen. Wer besteht, erlangt die Fähigkeit, einen dauerhaften Gefährten zu zähmen, zu rufen und freizugeben.",h="In Durotar steht ein junger Jäger der Horde vor der letzten Prüfung der Zähmung der Bestie.",kw={"gepanzerter skorpid","durotar","jägerprüfung","begleiterquest","klingenhügel","bestie zähmen","zähmerrute","thotar"},ang={["class:Hunter"]="Für Euch als Jäger ist dieser Ritus ein früher Meilenstein. Er verleiht Euch die grundlegenden Fähigkeiten, tierische Gefährten zu zähmen, zu rufen und zu befehligen.",["faction:Horde"]="Als junger Angehöriger der Horde in Durotar stellt Ihr Euch den gefährlichsten Raubtieren des Landes, um Euch einen Platz unter den Kundschaftern und Versorgern der Fraktion zu verdienen.",["race:Orc"]="Als Orc ehrt Ihr durch das Unterwerfen von Durotars Skorpiden den Glauben, dass unnachgiebiger Wille und kriegerische Disziplin selbst unwirtliches Gelände bezwingen.",["race:Troll"]="Als Troll nutzt Ihr Eure scharfen Instinkte und Eure tiefe Verbundenheit mit wilden Geistern, um giftige Raubtiere zu besänftigen, die andere niederstrecken könnten."},sec={{t="Die letzte Prüfung",b="Ein Jäger muss zuerst beweisen, dass er Durotars raue Tierwelt beherrschen kann, bevor er mit einem tierischen Gefährten durch Kalimdor reist. Thotar bildet in Klingenhügel Jäger aus und schickt sie los, um drei Arten von Kreaturen mit einer verzauberten Zähmerrute zu unterwerfen. Grautatzeneber und flinke Brandungsgleiter haben sie bereits auf die Probe gestellt. Nun stehen sie einem gepanzerten Skorpid gegenüber, einem giftigen Raubtier mit schweren Panzerplatten, das für seine Widerstandskraft und Schnelligkeit bekannt ist."},{t="Verbunden mit der Wildnis",b="Einen gepanzerten Skorpid zu zähmen prüft Konzentration und Beherrschung unter Angriffen, nicht das Geschick eines Jägers beim Töten. Thotar fordert Jäger auf, sich den schnellen, sicheren Schlägen der Bestie zu stellen. Sobald der Skorpid gebändigt ist, kehrt der Jäger nach Klingenhügel zurück und gibt Thotar die Zähmerrute zurück. Dann lehrt Thotar die angeborenen Techniken der Wildnis, damit der Jäger einen dauerhaften Gefährten seiner Wahl aufspüren und an sich binden kann."}},faq={{q="Welche Kreatur muss ich für diese Prüfung zähmen?",a="Zähmt für diese Prüfung einen gepanzerten Skorpid mit Thotars Zähmerrute. Er streift durch Durotars trockene rote Felslandschaft.",al={"welche bestie zähmen","zielbestie","skorpidquest"}},{q="Darf ich den gepanzerten Skorpid nach Abschluss der Quest behalten?",a="Nein. Der gepanzerte Skorpid ist nur ein vorübergehender Gefährte und verschwindet, wenn Ihr die Zähmerrute zurückgebt. Durch den Abschluss der Prüfung lernt Ihr, eine wilde Bestie Eurer Wahl dauerhaft zu zähmen.",al={"skorpid behalten","kann ich den begleiter behalten","skorpid dauerhaft"}},{q="Wer leitet diesen Übergangsritus ein?",a="Thotar, der Jägerlehrer in Klingenhügel, leitet diesen Ritus für junge Orc- und Trolljäger.",al={"questgeber","wer vergibt die zähmung der bestie","thotars standort"}},{q="Warum sollen Jäger nach Thotars Willen gerade einen gepanzerten Skorpid zähmen?",a="Thotar sieht im gepanzerten Skorpid ein Vorbild für sichere, schnelle Schläge und Widerstandskraft. Ein so gefährliches Raubtier zu zähmen beweist, dass ein Jäger wilde Bestien beherrschen kann.",al={"warum skorpid","zweck des skorpids"}},{q="Welche Fähigkeiten erlernt man beim Abschluss dieser Quest?",a="Ihr erlernt Tame Beast, Call Pet und Dismiss Pet.",al={"belohnungen","welche zauber bekomme ich","freigeschaltete zähmfähigkeiten"}},{q="Was folgt auf diese Prüfung?",a="Nachdem Ihr gelernt habt, einen Gefährten zu zähmen und zu rufen, könnt Ihr Thotars Anweisung zu Training the Beast folgen. Dort lernt Ihr, Euren Verbündeten zu füttern und zu befehligen.",al={"nächste quest","wie geht es weiter","nach zähmung drei"}}},fx={["5a0a9a11"]={q="Warum lässt Thotar Euch Tiere selbst zähmen, anstatt es für Euch zu tun?",a="Dies ist ein Ritus des Übergangs, den jeder aufstrebende Jäger alleine durchstehen muss. Thotars Rolle in Klingenhügel ist es, Euch zu leiten und anzuleiten, aber die Beherrschung der Gemeinschaft mit der Wildnis kann nicht allein durch Worte gewährt werden. Das Zähmen einer aggressiven, giftigen Kreatur wie eines gepanzerten Skorpions beweist, dass Ihr den Willen, die Geduld und die Entschlossenheit besitzt, die erforderlich sind, um ein wildes Raubtier Eurem Befehl zu unterwerfen, bevor Euch ein dauerhafter Begleiter anvertraut wird.",al={"warum muss ich das tier zähmen","warum zähmt thotar ihn nicht","warum ich thotar skorpion"}}},fp="16,213,15.404.0,21.393.0,47.100.0,63.182.0,35.93.0,69.160.0,52.48.0,28.149.0"}
P.entries["quest:6083"] = {n="Die Zähmung der Bestie",s="An Durotars Küste schickt Die Zähmung der Bestie junge Jäger in ihre zweite Prüfung. Thotar, der Jägerlehrer in Klingenhügel, weist angehende Orc- und Trolljäger an, nahe den Echoinseln einen Brandungskriecher zu zähmen und ihre Bindung auf Küstentiere auszuweiten.",h="An Durotars Küste schickt Die Zähmung der Bestie junge Jäger in ihre zweite Prüfung.",kw={"durotar","die echoinseln","begleiter zähmen","klingenhügel","sen'jin","brandungskriecher","zähmerrute","thotar"},ang={["class:Hunter"]="Als Jäger erlernt Ihr die nötige Disziplin, um wehrhafte Tiere zu befehligen. Die natürliche Panzerung und Zähigkeit einer Kreatur können Euer Können als Fernkampfschütze ergänzen.",["race:Orc"]="Als Orc, der sich in Durotar eine dauerhafte Heimat schafft, festigt Ihr Eure Herrschaft über das raue Land, indem Ihr seine widerstandsfähigen Küstentiere unterwerft.",["race:Troll"]="Als Dunkelspeertroll kennt Ihr die Gewässer nahe den Echoinseln und Sen'jin gut. Diese Prüfung bringt Euch den wilden Tieren Eures Küstenrefugiums von Angesicht zu Angesicht gegenüber."},sec={{t="Die Bindung zur Küste",b="Ihr habt einen Schreckenseber gemeistert, und nun schickt Thotar Euch zum Meer. Durotars raue Küsten sind zerklüftet, und die seichten Riffe wimmeln von gepanzerten Krebstieren. Ein Brandungskriecher wehrt sich gegen Eindringlinge in sein Küstenrevier. Einen zu zähmen erfordert Geduld und Seelenstärke."},{t="Die Erweiterung des Willens",b="Thotar lehrt, dass ein gebundenes Tier die Stärke eines Jägers mehren sollte. Mit der Zähmerrute unterwerft Ihr einen Brandungskriecher und lernt, Kreaturen mit unterschiedlichen Gemütern in verschiedenen Umgebungen zu befehligen. Diese Prüfung beweist, dass Ihr für dauerhafte Gefährten bereit seid."}},faq={{q="Wo findet man Brandungskriecher?",a="Brandungskriecher huschen durch das seichte Wasser an Durotars Ostküste, gegenüber von Sen'jin und nahe den Gewässern, die zu den Echoinseln führen.",al={"brandungskriecher fundort","wo ist der brandungskriecher","krabbe fundort"}},{q="Welchen Zweck hat es, einen Brandungskriecher zu zähmen?",a="Thotar trägt Euch auf, einen Brandungskriecher zu zähmen, damit Ihr lernt, verschiedene Tierarten zu befehligen. Eine gepanzerte Wasserkreatur zu zähmen erweitert Eure Kontrolle und beweist, dass Ihr Tiere aus dem Wasser ebenso wie vom Festland meistern könnt.",al={"warum krabbe zähmen","brandungskriecher quest zweck"}},{q="Behalte ich den Brandungskriecher dauerhaft?",a="Nein. Die Tiere, die Ihr in diesen ersten Prüfungen zähmt, dienen vorübergehend der Übung und werden mit Thotars Zähmerrute unterworfen. Erst nach Abschluss der gesamten Reihe erlernt Ihr die Fähigkeit, Tiere dauerhaft zu zähmen.",al={"bleibt die krabbe","ist der brandungskriecher dauerhaft"}},{q="Wer vergibt diese Quest?",a="Thotar, der Jägerlehrer in Klingenhügel, gibt Euch diese Prüfung, nachdem Ihr bewiesen habt, dass Ihr einen Schreckenseber zähmen könnt.",al={"questgeber","wer startet die zähmung der bestie zwei"}},{q="Was folgt auf die Zähmung des Brandungskriechers?",a="Nachdem Ihr Thotar die Rute zurückgebracht habt, gibt er Euch eine dritte und letzte Prüfung: einen Armored Scorpid aufzuspüren und zu zähmen. Dann lehrt er Euch, Tiere dauerhaft zu meistern.",al={"nächste quest","was folgt in der questreihe"}},{q="Warum eine Zähmerrute statt natürlicher Fähigkeiten verwenden?",a="Jägernovizen haben noch nicht die geistige Autorität entwickelt, wilde Tiere dauerhaft an sich zu binden. Die Zähmerrute lässt Anfänger gefahrlos üben, ihren Willen zu bündeln, bevor sie die wahre Technik erlernen.",al={"warum zähmerrute","was ist eine zähmerrute"}}},fx={["4f8a703d"]={q="Warum will Thotar, dass ich einen Strandkrabbler zähme?",a="Thotar bildet Euch in den grundlegenden Künsten eines Jägers aus. Wenn Ihr die Kontrolle über Bestien erlangt, werden sie zu einer Erweiterung Eurer eigenen Stärke, was Euch einen deutlichen Vorteil gegenüber Euren Rivalen verschafft. Nachdem er Euch an Landtieren geprüft hat, möchte er, dass Ihr Euch den Gewässern zuwendet, um Euer Können zu erweitern und zu beweisen, dass Ihr auch temperamentvolle Wasserbewohner meistern könnt.",al={"thotars motiv","warum strandkrabbler zähmen","warum will thotar das"}},["5da4eb39"]={q="Was sind Strandkrabbler?",a="Strandkrabbler sind temperamentvolle, zähe Krabben, die in den Untiefen entlang der Ostküste von Durotar beheimatet sind und häufig in den Gewässern zwischen Sen'jin und den Echoinseln anzutreffen sind. Ihr gepanzerter Rückenpanzer und ihre aquatische Natur machen sie zu einem idealen Test, um die Meisterschaft eines angehenden Jägers über die landbewohnenden Tiere der Steppen hinaus zu erweitern.",al={"was ist ein strandkrabbler","strandkrabbler in durotar","über strandkrabbler"}}},fp="16,254,22.266.0,21.257.0,30.153.0,45.211.0,39.191.0,21.112.0,41.158.0,47.200.0"}
P.entries["quest:6084"] = {n="Die Zähmung der Bestie",s="Grif Wildherz schickt Euch in der zweiten Zähmungsprüfung zu einem Schneeleoparden. Die Prüfung geht über den Felseber hinaus.",h="Grif Wildherz schickt Euch in der zweiten Zähmungsprüfung zu einem Schneeleoparden.",kw={"dun morogh","grif wildherz","jägerquest","kharanos","schneeleopard","zähmerrute","die zähmung der bestie"},ang={["class:Hunter"]="Als Jäger lernt Ihr, wie Eber harte Treffer einstecken, während Katzen schnell und aggressiv zuschlagen.",["race:Dwarf"]="Als Zwerg teilt Ihr die eisigen Gipfel von Dun Morogh mit Schneeleoparden, deren Heimlichkeit und Jagdgeschick Respekt gebieten."},sec={{t="Eine Lektion in Finesse",b="Schneeleoparden streifen südöstlich von Kharanos umher. Der Felseber hat Eure Stärke gegen harte Schläge geprüft. Nun erwartet Grif, dass Ihr einem schnellen, anmutigen Raubtier zu dessen Bedingungen entgegentretet. Unter seinem weißen Fell ruht gefährliche Kraft, bereit zuzuschlagen."},{t="Die Zähmerrute meistern",b="Mit einer verzauberten Zähmerrute tretet Ihr einem wilden Schneeleoparden gegenüber und versucht, seine Jagdinstinkte in eine Partnerschaft zu lenken. Seine Schnelligkeit, Beweglichkeit und scharfen Reflexe stellen Euch auf andere Weise auf die Probe als der Felseber. Lernt, mit einem Raubtier zusammenzuarbeiten, das blitzschnell aus den verschneiten Felsen zuschlägt, und Ihr kommt der Beherrschung der Bestien der Wildnis näher."}},faq={{q="Welchen Zweck hat diese Quest?",a="Dies ist die zweite Prüfung im Initiationsritus der zwergischen Jäger. Grif Wildherz prüft Euer Geschick im Umgang mit verschiedenen Bestien, bevor er Euch lehrt, dauerhafte Bindungen zu tierischen Begleitern einzugehen.",al={"warum diese quest machen","schneeleopard quest zwerg","die zähmung der bestie zwei"}},{q="Wo finde ich die Schneeleoparden?",a="Schneeleoparden streifen über die felsigen Höhen und verschneiten Hänge südlich und östlich von Kharanos in Dun Morogh.",al={"schneeleopard fundort","wo sind schneeleoparden dun morogh","leopard fundort"}},{q="Warum will Grif Wildherz, dass ich einen Leoparden zähme?",a="Grif Wildherz möchte, dass Ihr sowohl Stärke als auch Finesse erlernt. Der Felseber verlässt sich auf seine Zähigkeit, während der Schneeleopard Euch lehrt, an der Seite eines schnellen, beweglichen und tödlichen Begleiters zu kämpfen.",al={"warum schneeleopard","grif wildherz leopard begründung"}},{q="Kann ich diesen Schneeleoparden dauerhaft behalten?",a="Nein. Die Bestien, die Ihr in diesen ersten Prüfungen zähmt, sind vorübergehende Partner, gebunden durch die Magie der Zähmerrute. Wenn Grif Eure Ausbildung für abgeschlossen hält, könnt Ihr jede wilde Bestie Eurer Wahl dauerhaft zähmen.",al={"kann ich den schneeleoparden behalten","ist der leopard dauerhaft"}},{q="Wer erteilt diese Prüfung?",a="Grif Wildherz, der zwergische Jägerlehrer vor dem Gasthaus in Kharanos, Dun Morogh, erteilt diese Prüfung.",al={"wer gibt die quest","questgeber","grif wildherz rolle"}},{q="Was kommt als Nächstes in der Questreihe?",a="Nachdem Ihr den Schneeleoparden gemeistert habt, schickt Grif Euch in der dritten und letzten Zähmungsprüfung zu einem Ice Claw Bear. Danach lehrt er Euch, wilde Bestien eigenständig zu zähmen und auszubilden.",al={"nächste quest","was kommt nach dem schneeleoparden"}}},fx={baf34ad8={q="Was für eine Bestie ist der Schneeleopard?",a="Schneeleoparden sind schnelle, flinke Raubtiere aus den verschneiten Bergrücken von Dun Morogh. Im Gegensatz zu den stämmigen und eigensinnigen Felsenebern aus Eurer ersten Prüfung verlassen sich diese großen weißen Katzen auf Finesse, Schnelligkeit und tödliche Angriffe. Grif Wildherz schickt Euch zu ihnen, damit Ihr lernt, mit einem empfindlichen, aggressiven Jagdpartner umzugehen, der sich ganz anders verhält als ein rohes Wildtier.",al={"schneeleoparden-kunde","warum schneeleopard zähmen","schneeleoparden in dun morogh"}},["4533de88"]={q="Warum lässt Grif Wildherz mich den Schneeleoparden selbst zähmen?",a="Dies ist Euer Initiationsritus als junger Jäger, keine lästige Aufgabe, die Grif für die Stadt erledigen muss. Zähmen erfordert die Etablierung persönlicher Dominanz und Empathie gegenüber wilden Bestien. Grif kennt das Handwerk bereits; Ihr seid derjenige, der lernen muss, die Magie der Zähmerrute zu kanalisieren und einem anstürmenden Raubtier standzuhalten, um zu beweisen, dass Ihr bereit seid, einen lebenslangen Gefährten zu befehligen.",al={"warum muss ich ihn zähmen","warum ich zähmerrute","warum schickt mich grif wildherz"}}},fp="16,114,19.236.0,24.331.0,34.184.0,34.94.0,50.184.0,47.198.0,23.101.0,29.174.1"}
P.entries["quest:6085"] = {n="Die Zähmung der Bestie",s="In Dun Morogh prüft Grif Wildherz Eure Kontrolle über einen Eiskrallenbären östlich von Kharanos. Mit einer verzauberten Rute unterwerft Ihr den Bären und lernt, ihn zu verstehen. Dann erlangt Ihr die Macht, einen dauerhaften wilden Begleiter zu zähmen, zu rufen und freizugeben.",h="In Dun Morogh prüft Grif Wildherz Eure Kontrolle über einen Eiskrallenbären östlich von Kharanos.",kw={"dun morogh","grif wildherz","jägerquest","eiskrallenbär","kharanos","begleiter zähmen","zähmerrute","die zähmung der bestie"},ang={["class:Hunter"]="Als Jäger beginnt Ihr als einzelgängerischer Bogenschütze und werdet zu einem wahren Bestienzähmer. Ihr erlangt die grundlegenden Fähigkeiten, Bestien zu zähmen und herbeizurufen.",["race:Dwarf"]="Als Zwerg kennt Ihr Bären als beliebte Begleiter der Gebirgsjäger von Dun Morogh. Sie sind dafür bekannt, ihren Meistern an sturer Widerstandskraft ebenbürtig zu sein."},sec={{t="Die Stärke der Wildnis",b="Die Gebirgsjäger und Kundschafter von Dun Morogh verlassen sich in den eisigen Felsen auf widerstandsfähige Bestien. Ihr habt an flinken, gerissenen Raubtieren geübt. Nun schickt Grif Wildherz Euch aus, um einen Eiskrallenbären in den Schneewehen östlich von Kharanos einzufangen. Seine Stärke und Ausdauer stellen die Kontrolle auf die Probe, die jeder Zwergenjäger erlernen muss."},{t="Einen Begleiter gewinnen",b="Die Zähmerrute hält den Bären gefügig, während Ihr lernt, wie wilde Instinkte auf Willenskraft und ruhige Entschlossenheit reagieren. Eure Bindung besteht nur für die Dauer der Prüfung, die Euch Disziplin lehrt. Bringt die Rute zu Grif zurück, und die Prüfungen sind abgeschlossen. Dann lehrt er Euch, eine empfängliche wilde Kreatur zu besänftigen und sie Euer ganzes Abenteurerleben lang herbeizurufen."}},faq={{q="Welches Tier muss ich für diese Quest zähmen?",a="Ihr müsst einen Eiskrallenbären in den gefrorenen Ausläufern östlich von Kharanos in Dun Morogh zähmen. Die Zähmerrute unterwirft ihn, während Ihr lernt, mit seiner rohen Kraft umzugehen.",al={"welcher bär","zieltier","zähmziel"}},{q="Behalte ich den Eiskrallenbären nach Abschluss der Quest?",a="Nein. Der mit der Zähmerrute unterworfene Eiskrallenbär dient nur als vorübergehende Prüfung Eurer Disziplin und Eures Geschicks. Wenn Ihr die Rute zu Grif Wildherz zurückbringt, verlässt Euch der Bär, und Ihr erhaltet die Fähigkeiten, jede wilde Bestie Eurer Wahl zu zähmen.",al={"bleibt der bär","begleiter behalten","bär dauerhaft"}},{q="Wo befindet sich Grif Wildherz?",a="Grif Wildherz steht vor der Brauerei Donnerbräu in Kharanos, Dun Morogh. Er bildet angehende Jäger in Treffsicherheit und Tierherrschaft aus.",al={"grifs standort","wo ist grif","jägerlehrer kharanos"}},{q="Welche Fähigkeiten lerne ich nach Abschluss dieser Prüfung?",a="Ihr lernt Tame Beast, Call Pet und Dismiss Pet. Mit diesen Fähigkeiten könnt Ihr mit einem dauerhaften Begleiter in die Welt hinausziehen.",al={"questbelohnungen","erlernte jägerfähigkeiten","tame beast belohnung"}},{q="Was ist der nächste Schritt nach Abschluss dieser Quest?",a="Grif schickt Euch weiter zu Training the Beast. Dort lernt Ihr, Euren neuen Begleiter zu füttern, zu pflegen und zu unterweisen, damit er Euch im Kampf treu bleibt.",al={"nächste quest","what comes next","training the beast"}},{q="Warum lässt Grif Jäger mehrere Arten von Bestien erproben?",a="Die drei Prüfungen machen Euch mit verschiedenen Kampfstilen vertraut: Beweglichkeit, List und rohe Kraft. Diese Wesenszüge helfen einem Gebirgsjäger, einen Begleiter zu wählen, der zu seinem Jagdstil passt.",al={"warum drei bestien","zweck der prüfungen","drei tiere"}}},fx={d0a90924={q="Was sind Eisklauenbären und warum treiben sie sich bei Kharanos herum?",a="Eisklauenbären sind stämmige, dickfellige Raubtiere, die in den verschneiten Felsen von Dun Morogh beheimatet sind und häufig in der Wildnis östlich von Kharanos umherstreifen. Grif Wildherz hält sie aufgrund ihrer rohen Zähigkeit und Kraft für einen idealen Begleiter für einen angehenden Jäger. Wenn Ihr einem von ihnen gegenübersteht, müsst Ihr beweisen, dass Ihr Euch gegen immense physische Kraft behaupten und ein wahrhaft zähes Bergwesen beherrschen könnt, bevor Ihr die volle Meisterschaft über wilde Kreaturen beansprucht.",al={"eisklauenbären-kunde","warum eisklauenbär zähmen","eisklauenbären in dun morogh"}}},fp="16,234,24.304.0,19.321.0,45.158.0,55.220.0,32.140.0,52.123.0,50.136.0,57.176.0"}
P.entries["quest:6086"] = {n="Die Ausbildung des Tiers",s="In Dun Morogh schickt Grif Wildherz junge Zwergenjäger nach Eisenschmiede, damit sie die Pflege eines dauerhaften Tierbegleiters erlernen. Nachdem sie die wilden Raubtiere des Gebirges gezähmt haben, lernen sie, ihre Tiere zu füttern und auszubilden.",h="In Dun Morogh schickt Grif Wildherz junge Zwergenjäger nach Eisenschmiede, damit sie die Pflege eines...",kw={"belia thundergranite","dun morogh","zwergenjäger","grif wildherz","hall of arms","eisenschmiede","tierausbildung","die ausbildung des tiers"},ang={["class:Hunter"]="Als Jäger lernt Ihr, einen dauerhaften Tierbegleiter zu füttern, zu befehligen und wiederzubeleben.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf Eisenschmiedes Tiermeister. Ihre treuen Begleiter leisten einen großen Beitrag zu den Spähtruppen der Allianz und patrouillieren auf den eisigen Bergpässen.",["race:Dwarf"]="Als Zwerg erbt Ihr Khaz Modans Tradition, Bären, Eber und Bergkatzen als Partner bei der Erkundung und Verteidigung der gebirgigen Wildnis zu behandeln."},sec={{t="Aus der Wildnis zur Schmiede",b="Junge Jäger schließen ihre Prüfung nahe Kharanos unter Grif Wildherz' Aufsicht ab. Sie haben mit einer Zähmerrute große Klippeneber, Schneeleoparden und stämmige Eiskrallenbären gezähmt. Dann schickt Grif sie den Bergpass hinauf nach Eisenschmiede. Dort suchen sie die Halle der Waffen im Militärviertel auf."},{t="Belia Thundergranites Lehren",b="Belia Thundergranite lehrt Tierpflege in Eisenschmiedes Hall of Arms. Als angesehene Meistertierausbilderin des Zwergenreichs zeigt sie jungen Jägern, wie sie ihre Tiere ernähren und ihnen neue Fähigkeiten für das Schlachtfeld beibringen. Sie lehrt sie auch, die Geister ihrer Tiere zurückzurufen, wenn diese bei der Verteidigung ihres Meisters fallen. Ihre Lehren machen aus einem verängstigten Wildtier einen treuen Partner."},{t="Der Bund des Zwergenjägers",b="Die zwergische Tradition verlangt Respekt zwischen Jäger und Tier, niemals Unterwerfung. Belia erinnert junge Jäger daran, dass ein Tierbegleiter die Fürsorge widerspiegelt, die er erhält. Gut gefüttert, respektiert und richtig ausgebildet kämpft ein Tier treu gegen Troggs, Frosttrolle und jede Bedrohung für Khaz Modan."}},faq={{q="Welchen Zweck hat diese Quest?",a="Die Ausbildung des Tiers schließt die Grundausbildung eines Zwergenjägers ab. Ihr lernt, einen dauerhaften Tierbegleiter zu pflegen, zu füttern und auszubilden, ihn an Eure Seite zu rufen und ihn zurückzubringen, wenn er stirbt.",al={"warum diese quest machen","die ausbildung des tiers zweck","jägertier questbelohnung"}},{q="Wer ist Belia Thundergranite?",a="Belia Thundergranite ist eine angesehene Meistertierausbilderin und leitende Lehrerin in Eisenschmiedes Hall of Arms. Sie lehrt Zwergenjäger die Pflege, Disziplin und Befehle, die gezähmte Tiere zu lebenslangen Verbündeten machen.",al={"wer ist belia","belia thundergranite hintergrund","jägerlehrer eisenschmiede"}},{q="Wo finde ich Belia Thundergranite?",a="Belia Thundergranite befindet sich in Eisenschmiedes Hall of Arms, dem Militärflügel der Stadt. Krieger, Jäger und Paladine der Zwerge und Gnome versammeln sich dort und trainieren.",al={"belia standort","wo ist belia thundergranite","wo ist hall of arms eisenschmiede"}},{q="Welche Tiere zähmen Zwergenjäger vor dieser Ausbildung?",a="Vor dieser Ausbildung besänftigen junge Jäger mit einer Zähmerrute einen großen Klippeneber, einen Schneeleoparden und einen Eiskrallenbären in Dun Morogh. Grif Wildherz beaufsichtigt diese Prüfungen.",al={"welche tiere werden gezähmt","zwerg tierprüfung tiere","tiere vorheriger quests"}},{q="Warum müssen Zwergenjäger ihre Tiere füttern?",a="Die zwergische Tierkunde betrachtet Tierbegleiter als Partner, nicht als Werkzeuge. Ein hungriges Tier wird missmutig und weniger kampfbereit. Haltet es gut genährt, um Euch seine entschlossene Treue zu verdienen und ihm zu helfen, im Kampf sein Bestes zu geben.",al={"warum tier füttern","tierz u friedenheit hintergrund","tiertreue zwerg"}},{q="Wer vergibt diese Quest?",a="Grif Wildherz ist ein erfahrener Jägerlehrer an der Straße östlich von Kharanos in Dun Morogh. Er bietet Euch diese Ausbildung an, nachdem Ihr Eure dritte Zähmprüfung abgeschlossen habt.",al={"wer startet die ausbildung des tiers","grif wildherz rolle","questgeber"}}},fx={["5ee43731"]={q="Warum schickt Grif Wildherz Euch nach Eisenschmiede?",a="Grif Wildherz hat Eure grundlegenden Prüfungen in den Felsen von Dun Morogh geleitet und Euch gelehrt, wilde Bestien zu zähmen. Doch das Meistern der Pflege, Fütterung und Disziplinierung eines Bestiengefährten erfordert fortgeschrittene Expertise. Grif schickt Euch nach Eisenschmiede, damit Belia Thundergranite, eine der angesehensten Meisterausbilderinnen der Zwerge in der Hall of Arms, Eure Ausbildung vervollständigen und sicherstellen kann, dass Euer Haustier zu einem treuen Verbündeten wird.",al={"warum schickt euch grif","grif wildherz' motiv","warum zum jägerlehrer nach eisenschmiede"}}},fp="18,205,26.281.0,32.371.0,25.293.0,34.191.0,28.210.0,37.154.0,67.171.0,41.195.0,21.157.0"}
P.entries["quest:6087"] = {n="Die Zähmung der Bestie",s="Im Dorf der Bluthufe stellt Yaw Scharfmähne einem jungen Taurenjäger eine neue Prüfung. Der Jäger muss den flinken Präriepirscher meistern.",h="Im Dorf der Bluthufe stellt Yaw Scharfmähne einem jungen Taurenjäger eine neue Prüfung.",kw={"dorf der bluthufe","jägerprüfung","mulgore","präriepirscher","zähmerrute","die zähmung der bestie","taurenjäger","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger lernt Ihr, Überlebensfertigkeiten mit abgestimmten Angriffen zu verbinden und an der Seite eines flinken Gefährten zu kämpfen.",["race:Tauren"]="Als Tauren folgt Ihr dem Weg der Shu'halo bei der Tierzähmung und knüpft unter der wachsamen Gnade der Earthmother eine heilige Verwandtschaft."},sec={{t="Die Lehren des Pirschers",b="Nachdem Ihr die Ausdauer des erwachsenen Ebenenschreiters gemeistert habt, begegnet Ihr einer neuen Art von Jäger. Präriepirscher setzen auf Schnelligkeit und ziehen in Rudeln umher. Sie greifen ohne Furcht an. Um einen zu zähmen, müsst Ihr Euch ihm nähern, ohne innezuhalten, und ebenso entschlossen handeln wie der Wolf."},{t="Muskel an Muskel",b="Yaw Scharfmähne lehrt Euch, dass die Jagd an der Seite eines Tieres weder Knechtschaft noch rohe Gewalt erfordert. Ihr und das Raubtier müsst als Einheit kämpfen, verbunden durch Respekt und einen gemeinsamen Rhythmus. Unter dem offenen Himmel von Mulgore lehrt Euch das Band mit einem Präriepirscher, die Angriffe Eures Gefährten zu ergänzen und Euch im Kampf mit ihm zu bewegen."}},faq={{q="Welches Tier soll ich in dieser Prüfung für Yaw Scharfmähne zähmen?",a="Yaw Scharfmähne fordert Euch auf, einen Präriepirscher zu zähmen, einen flinken Wolf, der durch die Ebenen von Mulgore streift.",al={"welches tier zähmen","welcher begleiter kommt als nächstes","präriepirscher zähmen"}},{q="Warum lernt ein Taurenjäger, Wölfe zu zähmen?",a="Yaw Scharfmähne lehrt, dass Präriepirscher Schnelligkeit und Furchtlosigkeit verkörpern. Das Band mit einem von ihnen hilft Euch, diese Eigenschaften zu erlernen und Eure Angriffe mit einem flinken Jagdgefährten abzustimmen.",al={"warum wölfe","geschichte der präriepirscher","warum einen wolf zähmen"}},{q="Wo findet man Präriepirscher gewöhnlich?",a="Präriepirscher durchstreifen die grasbewachsenen Ebenen im mittleren und nördlichen Mulgore, darunter die Prärien rund um das Dorf der Bluthufe.",al={"fundort der präriepirscher","wo sind präriepirscher","präriepirscher finden"}},{q="Darf ich den Präriepirscher nach der Quest behalten?",a="Nein. Die Zähmerrute knüpft nur ein vorübergehendes Band zur Ausbildung. Nach allen Prüfungen erlangt Ihr die dauerhafte Fähigkeit, einen beliebigen wilden Gefährten Eurer Wahl zu zähmen.",al={"wolf behalten möglich","präriepirscher behalten","ist dies ein dauerhafter begleiter"}},{q="Wer ist Yaw Scharfmähne?",a="Yaw Scharfmähne ist der Jägerausbilder im Dorf der Bluthufe. Er führt junge Tauren durch die geistigen und praktischen Schritte, mit denen sie die Wildnis von Mulgore meistern.",al={"wer ist yaw","geschichte von scharfmähne","yaw bluthufe"}},{q="Was folgt auf die Zähmung des Präriepirschers?",a="Nachdem Yaw Scharfmähne bestätigt hat, dass Ihr den Wolf gemeistert habt, schickt er Euch zur dritten und letzten Prüfung, in der Ihr dem verstohlenen swoop begegnet.",al={"nächste quest","was kommt nach dem präriepirscher","dritte zähmungsquest"}}},fx={f904daad={q="Warum schickt mich Yaw Scharfmähne los, um die Bestie zu zähmen, anstatt sich selbst darum zu kümmern?",a="Dies ist keine Aufgabe oder lästige Pflicht, die delegiert werden kann; es ist ein heiliger Initiationsritus in Eurer Ausbildung als Jäger. Yaw Scharfmähne kennt bereits die Wege der Wildnis und befehligt seine eigene Verbindung zur Natur. Um ein wahrer Jäger der Erdenmutter zu werden, müsst Ihr den Pfad selbst beschreiten und durch erste eigene Erfahrungen lernen, wie man einem schnellen, furchtlosen Raubtier gegenübertritt und Eure Geister zu einem vereinten Team verbindet.",al={"warum ich yaw scharfmähne","warum muss ich den präriepirscher zähmen","warum zähmt yaw ihn nicht"}}},fp="16,125,21.257.0,16.313.0,60.94.0,46.173.0,44.121.0,53.150.0,21.154.0,44.134.0"}
P.entries["quest:6088"] = {n="Die Zähmung der Bestie",s="In Mulgore stellt sich ein junger Taurenjäger bei Yaw Scharfmähne im Dorf der Bluthufe der letzten Prüfung. Mit einer verzauberten Rute zähmt Ihr einen wilden Swoop und beweist, dass Ihr den Himmel meistern könnt. Die Prüfung bringt Euch das Vertrauen der Erdenmutter und dauerhaftes Wissen, um einen Gefährten zu zähmen, zu rufen und wegzuschicken.",h="In Mulgore stellt sich ein junger Taurenjäger bei Yaw Scharfmähne im Dorf der Bluthufe der letzten Prüfung.",kw={"dorf der bluthufe","erdenmutter","tiergefährte des jägers","mulgore","swoop","zähmerrute","die zähmung der bestie","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger schließt Ihr die grundlegende Ausbildungsreihe ab und lernt, Wildtiere dauerhaft zu zähmen. Dies markiert Euren Übergang vom Lehrling zum eigenständigen Späher der Wildnis.",["race:Tauren"]="Als Shu'halo ist Eure Bindung zu einem wilden Tier eine spirituelle Gemeinschaft, gesegnet von der Erdenmutter. Sie hat überall auf den Ebenen von Mulgore eine tiefe kulturelle Bedeutung."},sec={{t="Meisterschaft über den Himmel",b="Nachdem Ihr Raubtiere auf den Ebenen von Mulgore bezwungen habt, richtet Yaw Scharfmähne Eure Ausbildung auf den offenen Himmel. Ein Swoop ist ein wilder Raubvogel mit scharfem Schnabel, weiten Sturzflügen und einschüchterndem Auftreten. Seine Klauen prüfen Eure Reflexe und Eure Ruhe, während Ihr mit der verzauberten Rute seine Instinkte mit Euren eigenen in Einklang bringt."},{t="Die Gabe der Erdenmutter",b="Für die Tauren sind die Jagd und die Gefährtenschaft mit Wildtieren spirituelle Bestrebungen, keine bloße Unterwerfung. Geschöpfe der Erde und des Himmels zu meistern, lehrt das Gleichgewicht und den Respekt, die nötig sind, um die Ebenen zu durchstreifen, ohne die Natur zu stören. Yaw Scharfmähne nimmt seine vorübergehend überlassene Zähmerrute zurück und lehrt Euch dann dauerhafte Methoden, um einen Gefährten Eurer Wahl zu rufen, wegzuschicken und dauerhaft zu zähmen."}},faq={{q="Warum muss ich für die letzte Prüfung einen Swoop zähmen?",a="Yaw Scharfmähne stellt Euch in dieser letzten Prüfung den Geschöpfen des Himmels gegenüber. Swoops greifen schnell und heftig an, und ihr imposantes Auftreten prüft, ob Ihr mit Raubtieren der Lüfte und des Bodens umgehen könnt, bevor Ihr Eigenständigkeit erlangt.",al={"warum swoop zähmen","zweck der swoopzähmung","warum ein swoop"}},{q="Behalte ich den Swoop, den ich während dieser Quest zähme?",a="Nein. Yaw Scharfmähnes Rute lässt Euch den Swoop während Eurer Ausbildung nur vorübergehend zähmen. Danach könnt Ihr jedes wilde Tier, das Ihr behalten möchtet, dauerhaft zähmen.",al={"bleibt der swoop","swoop als tiergefährte","vogel behalten möglich"}},{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Yaw Scharfmähne, der Jägerlehrer im Dorf der Bluthufe im Herzen von Mulgore, gibt Euch den dritten und letzten Schritt Eurer ersten Prüfungen im Zähmen von Wildtieren.",al={"questgeber","wer vergibt die quest","wo ist yaw scharfmähne"}},{q="Was geschieht, nachdem ich die Zähmerrute zurückgegeben habe?",a="Yaw Scharfmähne lehrt Euch die Euch innewohnenden Fähigkeiten, Wildtiere selbstständig zu zähmen, zu rufen und wegzuschicken. Er schickt Euch außerdem nach Donnerfels, damit Ihr lernt, Euren gewählten Gefährten auszubilden und zu versorgen.",al={"nächste lernschritte","belohnungen für den abschluss","was folgt nach dieser quest"}},{q="Wo finde ich wilde Swoops in Mulgore?",a="Wilde Swoops durchstreifen Mulg ores offenes Grasland und die Ränder der Tafelberge und kreisen oft über den Ebenen direkt vor dem Dorf der Bluthufe.",al={"swoopfundorte","wo sind swoops","swoop finden"}},{q="Warum gilt das Zähmen eines Tiergefährten bei den Tauren als Übergangsritus?",a="Tauren sehen Wildtiere als Mitgeschöpfe und Kinder der Erdenmutter, nicht als Werkzeuge. Eine Bindung zu einem Gefährten erfordert Geduld, gegenseitigen Respekt und spirituelles Gleichgewicht, nicht allein Gewalt.",al={"hintergrund der taurenjäger","spiritueller pfad des jägers","verbindung zur erdenmutter"}}},fx={["8301e163"]={q="Warum will Yaw Scharfmähne, dass ich einen Sturzflieger zähme?",a="Yaw Scharfmähne leitet Euch durch die letzte Prüfung Eurer Jägerausbildung. Indem Ihr lernt, eine Kreatur der Lüfte zu bezirzen, beweist Ihr Eure Meisterschaft über Bestien aller Bereiche. Sobald Ihr diese letzte Herausforderung unter der Gnade der Erdenmutter gemeistert habt, kann Yaw Euch endlich die dauerhafte Macht verleihen, einen Gefährten Eurer Wahl zu zähmen, zu beschwören und wieder fortzuschicken.",al={"yaw scharfmähnes motiv","warum einen sturzflieger zähmen","warum will yaw, dass das erledigt wird"}},fc772ddc={q="Warum lässt Yaw Scharfmähne mich diese Prüfung machen, anstatt sie selbst zu erledigen?",a="Yaw Scharfmähne hat den Weg des Jägers bereits gemeistert; seine Pflicht ist nun die eines Ausbilders und Ältestenführers im Dorf der Bluthufe. Zähmen ist keine Erledigung für Dorfwachen oder Mentoren, sondern ein wesentlicher, persönlicher Initiationsritus. Ihr müsst Euren eigenen Geist und Eure Bindung zur Natur beweisen, bevor man Euch einen lebenslangen tierischen Gefährten anvertrauen kann.",al={"warum ich zähmen der bestie","warum schickt mich yaw scharfmähne","warum muss ich den sturzflieger zähmen"}}},fp="16,283,18.312.0,22.371.0,50.219.0,45.157.0,48.146.0,43.190.0,40.118.0,58.164.0"}
P.entries["quest:6089"] = {n="Die Ausbildung des Tiers",s="In Mulgore führt Die Ausbildung des Tiers junge Taurenjäger beim Lernen an der Seite eines Tiers weiter. Nachdem sie die wilden Geschöpfe der Ebenen besänftigt haben, reisen sie nach Donnerfels, um die dauerhafte Bindung aus Fürsorge und Führung kennenzulernen.",h="In Mulgore führt Die Ausbildung des Tiers junge Taurenjäger beim Lernen an der Seite eines Tiers weiter.",kw={"tierausbildung","holt donnerhorn","die anhöhe der jäger","mulgore","taurenjäger","donnerfels","die ausbildung des tiers","yaw scharfmähne"},ang={["class:Hunter"]="Als Jäger lasst Ihr den einsamen Kampf hinter Euch und steht an der Seite eines treuen Begleiters. Dieser Ritus vollendet Eure erste Ausbildung zum Hüter der Wildnis.",["race:Tauren"]="Als Shu'halo zieht Ihr mit einem Tierbegleiter in den Kampf und tragt die heilige Pflicht, für ihn zu sorgen und die Geschöpfe der Erdenmutter zu achten."},sec={{t="Der Weg zum großen Fels",b="Taurenjäger in Mulgore haben sich Schreitern, Präriepirschern und Sturzfalken gestellt. Nun schickt Yaw Scharfmähne, ihr Mentor im Dorf der Bluthufe, jeden Neuling zur Anhöhe der Jäger in Donnerfels, um die volle Verantwortung eines Jägers zu übernehmen. Dort unterrichtet sie Holt Donnerhorn. Die Shu'halo ehren ihn für seinen Einklang mit der Wildnis, und seine Ehrfurcht vor der Erdenmutter ist noch größer."},{t="Ein heiliger Bund",b="Für die Tauren ist ein Tier ein Partner, verbunden durch Harmonie mit der Natur, niemals eine Waffe oder ein Knecht. Holt Donnerhorn lehrt Jäger, wie sie diese Bindung stark halten. Sie lernen, die Kampfinstinkte eines Geschöpfs zu lenken, es regelmäßig zu füttern und seine Verletzungen zu heilen. Fällt es bei der Verteidigung seines Gefährten auf den Ebenen, können sie seinen Geist zurückrufen."}},faq={{q="Mit wem spreche ich für diese Quest?",a="Sprecht mit Holt Donnerhorn oben auf der Anhöhe der Jäger in Donnerfels. Nach Euren ersten Prüfungen beim Zähmen wilder Tiere in Mulgore schickt Yaw Scharfmähne Euch zu ihm.",al={"quest abgeben","wer ist holt donnerhorn","wo ist holt"}},{q="Welche Fertigkeiten erlernen Taurenjäger beim Abschluss dieser Quest?",a="Holt Donnerhorn lehrt Euch, Eurem Begleiter neue Fähigkeiten beizubringen, ihn zu füttern, damit er treu und zufrieden bleibt, und ihn wiederzubeleben, falls er im Kampf stirbt.",al={"welche fähigkeiten gibt es","fertigkeiten als questbelohnung","was lehrt holt"}},{q="Wo steht diese Quest in der Questreihe für Taurenjäger?",a="Die Ausbildung des Tiers ist der letzte Schritt in der Questreihe für Jäger. Sie folgt auf „Der Weg des Jägers“ und die drei Prüfungen von „Die Zähmung der Bestie“, bei denen Ihr auf den Ebenen vorübergehend einen ausgewachsenen Schreiter, einen Präriepirscher und einen Sturzfalken besänftigt.",al={"jägerquestreihe","tierbegleiterquest mulgore","die ausbildung des tiers questreihe"}},{q="Warum genießt Holt Donnerhorn unter Taurenjägern so hohes Ansehen?",a="Holt hat sich ein Leben lang mit Azeroths wildesten Bestien gemessen und befehligt mehrere mächtige Begleiter. Er pflegt auch eine tiefe spirituelle Bindung zur Erdenmutter, und seine Weisheit macht ihn zum wichtigsten Lehrer junger Shu'halo-Jäger in Donnerfels.",al={"holt donnerhorn hintergrundgeschichte","wer ist holt"}},{q="Können Jäger ihren dauerhaften Tierbegleiter zähmen, bevor sie diese Quest abgeben?",a="Dank der vorherigen Prüfung könnt Ihr bereits wilde Tiere zähmen, doch bis Ihr mit Holt Donnerhorn sprecht, fehlt Euch das Wissen, Euren Begleiter zu füttern, wiederzubeleben oder ihm Fertigkeiten beizubringen.",al={"jetzt schon tierbegleiter zähmen","wann gibt es den tierbegleiter","ist die ausbildung des tiers nötig"}},{q="Warum ist die Pflege von Tierbegleitern in der Kultur der Tauren mit der Erdenmutter verbunden?",a="Tauren sehen jedes Lebewesen als Kind der Erdenmutter. Ein Jäger beherrscht ein Tier nicht durch bloße Willenskraft, sondern schließt einen spirituellen Bund und bietet Nahrung und Fürsorge im Austausch für Treue und Schutz.",al={"tauren tierbegleiter hintergrundgeschichte","erdenmutter tiere"}}},fx={["44ef2a73"]={q="Warum schickt Yaw Scharfmähne Euch zu Holt Donnerhorn?",a="Yaw Scharfmähne hat Euch gelehrt, wie man Bestien zähmt, aber sie zu befehligen und zu nähren erfordert tiefere Weisheit. Anstatt Eure Ausbildung halbfertig zu lassen, schickt er Euch zu Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels. Holt gehört zu den am meisten verehrten Jägern der Tauren, der bereits wilde Kreaturen in ganz Azeroth besiegt hat, und nur jemand mit seiner tiefen Bindung zur Erdenmutter kann die heiligen Verantwortungen der Aufzucht und Ausbildung eines tierischen Begleiters richtig vermitteln.",al={"warum schickt euch yaw weg","yaw scharfmähnes motiv","warum nach donnerfels"}}},fp="18,224,27.374.0,13.346.0,33.149.0,63.148.0,53.226.0,71.262.0,66.177.0,58.216.0"}
P.entries["quest:609"] = {n="Voodooschulden",s="In Beutebucht wartet „Seewolf“ MacKinley noch immer darauf, dass drei alte Schulden beglichen werden. Maury „Club Foot“ Wilkins, Jon-Jon the Crow und Chucky „Ten Thumbs“ schulden ihm Geld, doch Gerüchten zufolge irren sie durch Flüche und Verzauberungen in uralten Dschungelruinen umher. MacKinley will ihre wertvollsten Besitztümer, was auch immer ihr Schicksal sein mag.",h="In Beutebucht wartet „Seewolf“ MacKinley noch immer darauf, dass drei alte Schulden beglichen werden.",kw={"beutebucht","chucky ten thumbs","jon-jon the crow","maury club foot wilkins","ruinen von aboraz","ruinen von jubuwal","seewolf mackinley","schlingendorntal","voodooschulden"},sec={{t="Offene Rechnungen",b="Ihr habt bereits Schulden für „Seewolf“ MacKinley eingetrieben, doch drei Rechnungen sind noch offen. Maury „Club Foot“ Wilkins, Jon-Jon the Crow und Chucky „Ten Thumbs“ schulden ihm seit Monaten Geld. MacKinley dachte zunächst, sie hätten Beutebucht verlassen, um ihren Schulden zu entkommen. Dann hörte er, dass sie tief im Dschungel ein seltsameres, düstereres Schicksal ereilt hatte."},{t="Verhext in den Ruinen",b="Man munkelt, Flüche und Verzauberungen ließen die drei Männer durch uraltes Mauerwerk nordöstlich von Beutebucht irren. Sie sollen durch die Ruinen von Aboraz und die Ruinen von Jubuwal streifen. MacKinley will, dass Ihr jeden Mann findet und seine auffälligen Wertsachen an Euch nehmt: Jon-Jons goldenes Handfernrohr, Chuckys gewaltigen Ring und Maurys Klumpfuß."}},faq={{q="Wer bittet darum, diese Schulden einzutreiben?",a="„Seewolf“ MacKinley bittet Euch von seinem Posten in Beutebucht aus, die Schulden einzutreiben. Er arbeitet seine Liste von Schuldnern ab und wird ihre Schulden nicht unter den Tisch fallen lassen.",al={"wer vergibt voodooschulden","seewolf mackinley quest"}},{q="Wer sind die drei Schuldner?",a="Die drei Schuldner sind Maury „Club Foot“ Wilkins, Jon-Jon the Crow und Chucky „Ten Thumbs“. Ihre Zahlungen sind seit mehreren Monaten fällig.",al={"wer schuldet mackinley geld","voodooschulden ziele"}},{q="Wo sind die drei Schuldner zu finden?",a="Die drei Männer irren durch uralte Steinbauten nordöstlich von Beutebucht, in den Ruinen von Aboraz und den Ruinen von Jubuwal.",al={"wo sind die schuldner","wo sind aboraz und jubuwal"}},{q="Was ist den drei Männern zugestoßen?",a="MacKinley hat erfahren, dass die Männer verhext und verflucht wurden. Nun streifen sie durch die Dschungelruinen, statt in den Hafen zurückzukehren.",al={"warum sind sie verflucht","was stimmt mit ihnen nicht"}},{q="Welche Gegenstände müssen beschafft werden?",a="MacKinley will Jon-Jons goldenes Handfernrohr, Chuckys gewaltigen Ring und Maurys Klumpfuß.",al={"welche gegenstände will mackinley","voodooschulden gegenstände"}},{q="Was ging dieser Aufgabe in der Questreihe voraus?",a="Dies folgt auf Eure frühere Arbeit in Scaring Shaky und Return to MacKinley, bei der Ihr dem Piraten geholfen habt, seine Schulden einzutreiben.",al={"voodooschulden voraussetzungen","vorherige quest"}}},fp="11,316,15.341.0,22.321.0,37.164.0,26.149.0,37.118.0,31.124.0,38.88.0,40.110.0"}
P.entries["quest:61"] = {n="Lieferung nach Sturmwind",s="William Pestle schickt ein Paket aus Goldhain an seinen Bruder in Sturmwind. Mit den Kerzen darin gelangt Wachs von Kobolden im Wald von Elwynn zu Morgan in Pestle's Apothecary.",h="William Pestle schickt ein Paket aus Goldhain an seinen Bruder in Sturmwind.",kw={"wald von elwynn","goldhain","kobold candles","morgan pestle","pestle's apothecary","lieferung nach sturmwind","der handelsdistrikt","william pestle"},ang={["faction:Alliance"]="Als Streiter der Allianz bringt Ihr Vorräte auf der Königsstraße nach Sturmwind und zieht von Scharmützeln auf dem Land in Richtung Hauptstadt.",["profession:Herbalism"]="Das Familiengeschäft der Pestles hängt von örtlichen Reagenzien aus Elwynn ab. Ihr Laden in Sturmwind ist eine vertraute Anlaufstelle für Sammler und Trankbrauer."},sec={{t="Ein Familiengeschäft",b="William Pestle sammelt Kräuter, Reagenzien und Rohwaren in Goldhain. Sein Bruder Morgan führt Pestle's Apothecary im Handelsdistrikt von Sturmwind. William kann das Gasthaus \"Zur Höhle des Löwen\" nicht ohne Weiteres verlassen, also vertraut er Reisenden auf dem Weg in die Stadt seine Waren an."},{t="Vom Koboldwachs zu Hauptstadttränken",b="Williams Paket enthält große Kerzen, die von Kobolden in den Minen von Elwynn gesammelt wurden. Er sammelt sie wegen ihres Wachses, sagt aber nicht, wie die Brüder es verwenden. Ihr bringt die Lieferung zu Morgan in Pestle's Apothecary im Handelsdistrikt."}},faq={{q="Was enthält Williams Lieferung?",a="Die Lieferung enthält Kerzen, die von Kobolden im Wald von Elwynn gesammelt wurden. William sammelte sie wegen ihres Wachses und verpackte sie für Morgan in Pestle's Apothecary.",al={"inhalt der lieferung","was ist im paket","was hat william geschickt"}},{q="Wo finde ich Morgan Pestle?",a="Morgan Pestle arbeitet in Pestle's Apothecary im Handelsdistrikt von Sturmwind, nur einen kurzen Fußweg hinter den Haupttoren.",al={"morgan pestle standort","wo ist morgan","morgan pestle finden"}},{q="Wie sind William und Morgan Pestle miteinander verwandt?",a="William und Morgan Pestle sind Brüder, die gemeinsam ein alchemistisches Gewerbe betreiben. William sammelt Materialien im Wald von Elwynn, während Morgan ihren Laden in Sturmwind führt.",al={"pestle-brüder","wer ist william pestles bruder"}},{q="Warum liefert William das Paket nicht selbst aus?",a="William ist mit seinem Gewerbe und dem Sammeln alchemistischer Zutaten in Goldhain beschäftigt. Er verlässt sich auf Reisende, die ohnehin zur Hauptstadt unterwegs sind, um das Paket zu befördern.",al={"warum geht william nicht nach sturmwind","warum einen kurier anheuern"}},{q="Haben Koboldkerzen tatsächlich einen alchemistischen Nutzen?",a="William sagt, dass er und sein Bruder die Kerzen wegen ihres Wachses brauchen. Er erklärt nicht, wie sie es in der Apotheke verwenden.",al={"warum koboldkerzen","koboldwachs alchemie"}},{q="Was folgt nach der Ablieferung?",a="Mit der Ablieferung endet die kurze Questreihe, die mit dem Sammeln von Koboldkerzen im Wald von Elwynn begann. Morgan bezahlt Euch für den Transport des Pakets und heißt Euch als Kunden in seinem Laden willkommen.",al={"was folgt nach lieferung nach sturmwind","folgequest lieferung nach sturmwind"}}},fx={e0018b76={q="Warum möchte William Pestle, dass diese Lieferung zugestellt wird?",a="Morgan wartet in der Apotheke der Brüder in Sturmwind auf die Kerzenlieferung. William hat sie wegen ihres Wachses gesammelt, hat aber keine Zeit für die Reise, also bittet er einen Reisenden, die Vorräte zu befördern.",al={"warum die lieferung schicken","william pestles motiv","warum die kerzen liefern"}}},fp="21,168,14.254.0,34.230.0,34.157.0,30.116.0,42.168.0,48.165.0,48.118.0,41.183.0"}
P.entries["quest:610"] = {n="Schönling Duncan",s="Catelyn die Klinge hat den Dolch verloren, den sie auf Bitten ihres Vaters zurückgeben sollte. Sie will ihn von Schönling Duncan zurück, bevor sie Euch weiterhilft.",h="Catelyn die Klinge hat den Dolch verloren, den sie auf Bitten ihres Vaters zurückgeben sollte.",kw={"blutsegelbukaniere","beutebucht","catelyn die klinge","catelyns klinge","schönling duncan","schlingendorntal"},ang={["class:Mage"]="Als Magier hört Ihr vielleicht, wie Catelyn über arkane Gelehrte spottet. Sie sagt, sie sei von zu Hause geflohen, um ihre Tage nicht unter verstaubten, grauhaarigen Zauberwirkern verbringen zu müssen."},sec={{t="Der Groll eines Piraten",b="Catelyn die Klinge hat die Magier und ihre staubigen Wälzer hinter sich gelassen. Ansirem's Key hat Euch zu ihr geführt, doch sie kann Euch den Dolch nicht geben, den sie auf Bitten ihres Vaters zurückgeben sollte. Ein Blutsegelbukanier hat ihn ihr abgenommen. Solange ihre Klinge nicht wiederbeschafft ist, wird Catelyn nichts anderes herausgeben."},{t="Der gestohlene Stahl",b="Schönling Duncan schlug Catelyn bewusstlos und nahm ihr das Messer ab, das sie im Kampf trug. Sie verlässt sich auf diese Waffe. Nun besteht sie darauf, genau diese Klinge vom Bukanier zurückzubekommen, bevor sie Euch weiterhilft."}},faq={{q="Wer ist Schönling Duncan?",a="Schönling Duncan ist ein Blutsegelbukanier in der Nähe von Beutebucht. Er besiegte Catelyn die Klinge, schlug sie bewusstlos und nahm ihren Dolch an sich.",al={"schönling duncan","wer ist duncan","duncan pirat"}},{q="Warum will Catelyn ihren Dolch zurück?",a="Catelyn verlässt sich im Kampf auf ihr Messer und gibt sich mit keinem anderen zufrieden. Sie will den Dolch zurück, den Duncan ihr abgenommen hat, bevor sie jemandem hilft, der nach ihr sucht.",al={"catelyn dolch","catelyn messer","warum die klinge zurückholen"}},{q="Warum ist Catelyn von zu Hause fortgelaufen?",a="Catelyn verließ ihre Familie, um einem eintönigen Leben mit alten Büchern unter starren, betagten Magiern zu entkommen. Sie weigerte sich, ihre Tage so zu verbringen.",al={"warum catelyn fortlief","ansirems tochter","catelyns vorgeschichte"}},{q="Wo fügt sich dieser Schritt in die Suche ein?",a="Diese Begegnung folgt auf die Wiederbeschaffung von Ansirem's Key und findet statt, bevor die Suche The Curse of the Tides aufdeckt.",al={"questreihe","was führt zu schönling duncan"}}},fp="19,140,20.261.0,16.211.0,25.135.0,38.150.0,35.128.0,41.113.0"}
P.entries["quest:6101"] = {n="Die Zähmung der Bestie",s="In Dolanaar führt Dazalar Euch durch eine zweite Prüfung für Nachtelfenjäger. Mit einer verzauberten Zähmerrute unterwerft Ihr einen nightsaber stalker und lernt, wie sich wilde Tiere unterscheiden.",h="In Dolanaar führt Dazalar Euch durch eine zweite Prüfung für Nachtelfenjäger.",kw={"wildtiere zähmen","dazalar","dolanaar","jäger","nightsaber stalker","zähmerrute","teldrassil"},ang={["class:Hunter"]="Als Jäger lernt Ihr, die unterschiedlichen Temperamente der Tiere zu achten, bevor Ihr Euch einen lebenslangen Gefährten verdient.",["race:NightElf"]="Als Nachtelf erreicht Ihr einen traditionellen Meilenstein für Waldspäher: die Zähmung eines Nachtsäblers, eines Geschöpfs, das mit der Geschichte und Kultur der Kaldorei verwoben ist."},sec={{t="Die wechselhafte Natur der Tiere",b="Dazalar lehrt Euch, dass sich die Geschöpfe des Waldes nicht alle gleich verhalten. Jede Art hat ihr eigenes Temperament, und ein Jäger muss lernen, damit umzugehen. Unter Teldrassils Blätterdach stellt Euch diese Prüfung Tieren gegenüber, die gerissener und raubgieriger sind als Webspinner."},{t="Den Nachtsäbler unterwerfen",b="Kaldorei verehren Nachtsäbler als heilige Raubtiere, grimmige Wächter und Gefährten der Schildwachen. Mit der Zähmerrute tretet Ihr einem nightsaber stalker gegenüber und müsst dabei die Nerven bewahren und ruhige Autorität ausstrahlen. Sein Vertrauen zu gewinnen beweist, dass Ihr mit einem Raubtier umgehen könnt, ebenso wie mit den sanfteren Geschöpfen des Waldes."}},faq={{q="Was ist das Ziel dieser Quest?",a="Dazalar schickt Euch los, einen nightsaber stalker zu zähmen und zu lernen, wie sich verschiedene Raubtiere verhalten. Dies ist die zweite Prüfung in der Ausbildung eines Nachtelfenjägers; der Abschluss der gesamten dreiteiligen Prüfung schaltet das dauerhafte Zähmen von Wildtieren frei.",al={"warum diese quest machen","begleiter zähmen quest zwei","ziel der nachtsäblerzähmung"}},{q="Wo sind nightsaber stalker zu finden?",a="Nightsaber stalker streifen auf den Waldpfaden und im Unterholz südlich von Dolanaar im Zentrum von Teldrassil umher.",al={"wo sind nightsaber stalker","stalker fundort","wo die katze finden"}},{q="Darf ich den nightsaber stalker als dauerhaften Begleiter behalten?",a="Nein. Die Rute zähmt das Tier nur zur Übung. Nachdem Ihr alle drei Prüfungen abgeschlossen und die Rute zurückgegeben habt, lernt Ihr, Wildtiere dauerhaft zu zähmen und einen Gefährten auszuwählen.",al={"begleiter behalten","nachtsäbler behalten","begleiter für immer"}},{q="Wer vergibt diese Quest?",a="Dazalar, der Jägerlehrer in Dolanaar, erteilt Euch diese Aufgabe, nachdem Ihr Eure erste Zähmungsprüfung abgeschlossen habt.",al={"questgeber","wer startet die quest","dazalar standort"}},{q="Warum verehren Nachtelfen Nachtsäbler so sehr?",a="Kaldorei leben seit Jahrtausenden an der Seite von Nachtsäblern. Schildwachen und Priesterinnen von Elune haben sie als Gefährten, Späher und Kriegsreittiere eingesetzt, und einen zu zähmen bezeugt die stolze Beherrschung der Waldkünste.",al={"hintergrund zu nachtelfenkatzen","warum nachtsäbler wichtig sind","hintergrund zu nachtsäblern"}},{q="Was folgt nach dem Abschluss dieser Aufgabe?",a="Dazalar gibt Euch eine letzte Zähmungsaufgabe mit einem weiteren Geschöpf Teldrassils. Danach lehrt er Euch, überall in Azeroth dauerhafte Gefährten zu zähmen, zu füttern und zu versorgen.",al={"nächste quest","was folgt nach nightsaber stalker","nächste jägerprüfung"}}},fx={["878d77ca"]={q="Warum will Dazalar, dass Ihr einen Nachtsäbelpirscher zähmt?",a="Dazalar möchte Euch lehren, dass die Vielfalt der Natur sich ständig wandelt und doch verlässlich ist. Indem er Euch durch verschiedene Kreaturen führt, möchte er, dass Ihr das einzigartige Temperament und den Geist jedes Tieres wahrnehmt, um sicherzustellen, dass Ihr lernt, mit verschiedenen Gefährten auf ganz Teldrassil in Einklang zu kommen.",al={"warum nachtsäbelpirscher zähmen","dazalars motiv","warum nachtsäbelpirscher"}},a23887a1={q="Was ist ein Nachtsäbelpirscher und warum sucht Ihr ihn?",a="Nachtsäbelpirscher sind räuberische Großkatzen, die in den schattigen Ästen und Wäldern von Teldrassil beheimatet sind. Dazalar schickt Euch hinter einem her, damit Ihr lernt, eine Bindung mit einem schlauen, flinken Jäger einzugehen, und lernt, seinen Instinkt und sein Gleichgewicht innerhalb der Wildnis zu respektieren.",al={"was ist ein nachtsäbelpirscher","nachtsäbelpirscher in teldrassil","warum nachtsäbelpirscher jagen"}}},fp="16,173,29.251.0,23.296.0,34.218.0,39.99.0,60.161.0,21.110.0,48.196.0,38.170.0"}
P.entries["quest:6102"] = {n="Die Zähmung der Bestie",s="In Dolanaar führt „Die Zähmung der Bestie“ einen jungen Nachtelfenjäger zur letzten Prüfung seiner Grundausbildung. Unter Dazalars Anleitung zähmt der Jäger eine räuberische Eule der Lüfte, bevor er die Fähigkeit erlangt, einen lebenslangen Gefährten zu wählen.",h="In Dolanaar führt „Die Zähmung der Bestie“ einen jungen Nachtelfenjäger zur letzten Prüfung seiner...",kw={"bestie","dazalar","dolanaar","jägerbegleiter","screecher","strigid screecher","zähmung","zähmerrute","teldrassil"},ang={["class:Hunter"]="Für Euch als Jäger markiert dieser Ritus den Übergang vom einsamen Kampf zu einem lebenslangen Band mit einem wilden Gefährten.",["race:NightElf"]="Als Nachtelf folgt Ihr durch die Zähmung der heimischen Tierwelt Teldrassils dem Weg der Kaldorei, im Einklang mit der Natur zu leben, statt sie mit Gewalt zu beugen."},sec={{t="Meisterschaft im Blätterdach",b="Nachtelfenjäger müssen mit Kreaturen in ganz Teldrassil Frieden schließen, um ihre grundlegende Tierkunde abzuschließen. Nachdem sie sich Bestien des Unterholzes gestellt haben, begegnen sie dem Geist der Lüfte: dem Strigid Screecher. Diese wachsamen Raubvögel nisten hoch im Geäst westlich von Dolanaar. Geduld und ruhige Nerven sind nötig, um einen von ihnen mit der verzauberten Zähmerrute zu besänftigen."},{t="Das Band eines Jägers",b="Die Zähmung des Strigid Screecher vollendet die uralten Lehren des Einklangs zwischen Kaldoreijägern und der Natur. Der Lehrling bringt die verbrauchte Rute zu Dazalar zurück, und die Ausbildungsübungen enden. Dann erlernt der Jäger die vollständige Kunst, Bestien seiner Wahl in ganz Azeroth herbeizurufen, wegzuschicken und dauerhaft zu zähmen."}},faq={{q="Wo sind Strigid Screechers zu finden?",a="Strigid Screechers nisten in den Wäldern westlich von Dolanaar. Jäger suchen diese Raubvögel zwischen Blätterdach und Wurzeln außerhalb des Dorfes, um ihre Rute zu erproben.",al={"screecher fundort","wo ist strigid screecher","eule fundort"}},{q="Wer ist Dazalar?",a="Dazalar ist ein Nachtelf und Jägerlehrer in Dolanaar. Er leitet junge Kaldorei an, die die Grundlagen des Bogenschießens und der Fährtensuche erlernt haben. Er prüft sie an Bestien des Landes und der Lüfte, bevor er ihnen die Fähigkeit verleiht, einen echten tierischen Gefährten an sich zu binden.",al={"dazalars rolle","wer lehrt begleiterzähmung in dolanaar","jägerlehrer dolanaar"}},{q="Darf ich den Strigid Screecher als Begleiter behalten?",a="Nein. Der während dieser Prüfung gezähmte Strigid Screecher ist nur vorübergehend durch die Magie der Zähmerrute gebunden. Wenn die Prüfung endet, gibt der Jäger die Rute ab und lernt, in der Wildnis einen dauerhaften Gefährten seiner Wahl zu zähmen.",al={"eule behalten","ist screecher dauerhaft","bleibt dieser begleiter"}},{q="Was geschieht nach Abschluss dieser Prüfung?",a="Dazalar verleiht Euch die Fähigkeit, Bestien dauerhaft zu zähmen, herbeizurufen und wegzuschicken. Er verweist Euch zur weiteren Ausbildung nach Darnassus, wo Ihr lernen könnt, Euren Gefährten zu füttern und ihm das Kämpfen beizubringen.",al={"what comes next","nach der zähmung der bestie","jägerbegleiterquest abschließen"}},{q="Warum zähmen Nachtelfen gerade Eulen?",a="Eulen und andere Raubvögel haben für die Kaldorei als wachsame Jäger der Nacht und vertraute Späher eine tiefe kulturelle Bedeutung. Die Beherrschung eines Geschöpfs der Lüfte beweist, dass Ihr Raubtiere der Lüfte ebenso versteht wie Bestien am Boden.",al={"eulen hintergrund nachtelf","warum eulen","strigid screecher bedeutung"}},{q="Können Jäger nach dieser Quest jedes Tier wählen?",a="Ja. Sobald Ihr die Fähigkeit erlangt, Bestien dauerhaft zu zähmen, könnt Ihr in ganz Teldrassil und darüber hinaus nach jedem zähmbaren Geschöpf des Landes, des Wassers oder der Lüfte suchen.",al={"welche begleiter sind verfügbar","ersten begleiter wählen","jede bestie zähmbar"}}},fx={fcfecb3c={q="Warum lässt Dazalar Euch einen Strigidenschreier zähmen?",a="Dies ist Eure letzte Prüfung als angehender Jäger. Nachdem Ihr Eure Fähigkeit bewiesen habt, mit zwei verschiedenen Kreaturen des Landes umzugehen, verlangt Dazalar von Euch, dass Ihr eine meistert, die den Himmel beherrscht. Indem Ihr einen wilden Strigidenschreier zähmt, zeigt Ihr, dass Eure Empathie und Autorität über Bestien über die Erde hinausgehen, was beweist, dass Ihr bereit seid, eine dauerhafte Bindung mit einem eigenen Gefährten einzugehen.",al={"warum strigidenschreier zähmen","dazalars motiv","warum eulenprüfung"}},ebb229ae={q="Was sind Strigidenschreier?",a="Strigidenschreier sind große, räuberische Eulen, die in den Ästen von Teldrassil beheimatet sind. Sie werden von Nachtelfenjägern wegen ihrer scharfen Sicht und ihres lautlosen Fluges verehrt und jagen in den Wäldern westlich von Dolanaar. Ihre wilde Natur und ihre Anmut in der Luft machen sie zu einem idealen Test für die Geduld, den Fokus und den Befehl eines Jägers, bevor er eine dauerhafte Bindung zu einer Bestie eingeht.",al={"strigidenschreier","strigidenschreier-kunde","schreiereulen in teldrassil"}}},fp="16,230,21.353.0,15.316.0,35.156.0,15.231.0,49.231.0,41.190.0,42.231.0,47.146.0"}
P.entries["quest:6103"] = {n="Die Ausbildung des Tiers",s="In Teldrassil verlassen Nachtelfenjäger die Wildnis in Richtung Darnassus, nachdem sie im Geäst Tiere gezähmt haben. Dort lehrt Jocaste sie, einen Begleiter zu pflegen und zu disziplinieren.",h="In Teldrassil verlassen Nachtelfenjäger die Wildnis in Richtung Darnassus, nachdem sie im Geäst Tiere gezähmt...",kw={"die enklave des cenarius","darnassus","dazalar","jägerbegleiter","jocaste","teldrassil","die ausbildung des tiers"},ang={["class:Hunter"]="Als Jäger lernt Ihr, Euren Begleiter auszubilden, zu füttern und wiederzubeleben, während Ihr den Pfad des Anfängers hinter Euch lasst.",["race:NightElf"]="Als Nachtelf teilt Ihr eine Tradition der Gemeinschaft mit Tieren, die auf Respekt und Zusammenleben beruht. Ihr lernt sie in der Enklave des Cenarius in Darnassus."},sec={{t="Der Übergangsritus eines Jägers",b="Dazalar schickt Euch aus der Wildnis nahe Dolanaar nach Darnassus, nachdem Ihr bewiesen habt, dass Ihr ein Tier zähmen könnt. Bevor Ihr mit einem treuen Begleiter durch Kalimdor reist, braucht Ihr mehr als Geschick mit einer Zähmerrute. Eine wilde Kreatur zu unterwerfen, stellt Eure Stärke und Euren Willen auf die Probe, doch ein ungeschultes Tier kann noch immer unberechenbar sein."},{t="Unterweisung in der Enklave des Cenarius",b="In der Enklave des Cenarius in Darnassus lehrt Jocaste Euch, für einen Begleiter zu sorgen. Sie zeigt Euch, wie Ihr Euren Begleiter füttert, ihn zurückholt, wenn ein Unglück geschieht, und ihn für den Kampf ausbildet. Für Nachtelfen spiegelt diese Bindung Ehrfurcht vor der Natur wider, nicht bloße Kontrolle."}},faq={{q="Was ist der Zweck dieser Quest?",a="Ihr reist nach Darnassus, um zu lernen, wie Ihr einen dauerhaften tierischen Begleiter pflegt und ausbildet. Diese Lektionen schließen die ersten Schritte der Ausbildung eines Nachtelfenjägers im Umgang mit einem Begleiter ab.",al={"warum diese quest machen","quest begleiterausbildung nachtelf","was bewirkt die ausbildung des tiers"}},{q="Wo finde ich Jocaste?",a="Jocaste befindet sich in der Enklave des Cenarius in Darnassus, zwischen den Bäumen und Jägerhütten im Nordwesten der Stadt.",al={"wo ist jocaste","jocaste standort","jocaste finden"}},{q="Wer vergibt die Quest?",a="Dazalar, der Jägerlehrer in Dolanaar, schickt Euch los, nachdem Ihr alle drei Zähmprüfungen in ganz Teldrassil abgeschlossen habt.",al={"questgeber","wer vergibt die ausbildung des tiers","dazalar standort"}},{q="Welche Fertigkeiten lernt Ihr von Jocaste?",a="Jocaste lehrt Euch, Euren Begleiter zu füttern, ihn wiederzubeleben, wenn er im Kampf fällt, und ihm neue Fähigkeiten beizubringen.",al={"welche fähigkeiten erhält man","jocaste belohnungen","zauber für jägerbegleiter"}},{q="Warum legt die Kultur der Nachtelfen Wert auf die Ausbildung von Begleitern?",a="Nachtelfenjäger behandeln ihre Begleiter als Partner, nicht als Werkzeuge, denen sie Befehle erteilen. Ihre Fürsorge spiegelt Respekt vor der Natur und den Wunsch wider, im Einklang mit ihr zu leben.",al={"geschichte der nachtelfenjäger","warum bilden nachtelfen tiere aus"}},{q="Ist diese Quest auch für andere Völker verfügbar?",a="Diese Reise nach Darnassus ist für Nachtelfenjäger bestimmt. Jäger anderer Völker lernen ähnliche Fertigkeiten von Lehrmeistern ihres eigenen Volkes.",al={"können zwerge diese quest machen","kann die horde die ausbildung des tiers machen"}}},fx={["1a4b70d0"]={q="Warum schickt Dazalar Euch zu Jocaste?",a="Dazalar hat Euch gelehrt, wie man wilde Bestien zähmt, aber die Loyalität einer Kreatur zu gewinnen, ist nur der erste Schritt. Ohne richtige Anleitung bei der Fütterung, Pflege und Unterweisung Eures Gefährten kann die Bindung zwischen Jäger und Bestie nicht gedeihen. Er schickt Euch nach Darnassus, weil Jocaste zu den am meisten verehrten Jägern der Nachtelfen gehört und über die alte Weisheit verfügt, die erforderlich ist, um einen unerfahrenen Fährtenleser zu einem wahren Meister der Bestien zu erheben.",al={"warum will dazalar, dass das erledigt wird","dazalars motiv","warum zum jägerlehrer nach darnassus"}}},fp="18,168,26.297.0,32.248.0,34.166.0,24.102.0,21.112.0,38.107.0,50.141.0,39.127.0"}
P.entries["quest:611"] = {n="Der Fluch der Gezeiten",s="Vor der Küste des Schlingendorntals leiht Euch Catelyn die Klinge ihr wiederbeschafftes Messer, um damit auf einen versunkenen Altar einzuschlagen. Baron Revilgaz in Beutebucht sucht den Stein der Gezeiten für seine Sammlung alter Trollartefakte.",h="Vor der Küste des Schlingendorntals leiht Euch Catelyn die Klinge ihr wiederbeschafftes Messer, um damit auf...",kw={"altar of the tides","baron revilgaz","beutebucht","catelyn die klinge","gazban","stein der gezeiten","schlingendorntal","das finstere riff"},ang={["faction:Alliance"]="Als Abenteurer der Allianz schließt Ihr Baron Revilgaz' Suche nach dem alten Relikt in den Gewässern nahe dem Lager der Horde beim Basislager Grom'gol ab."},sec={{t="Der versunkene Altar",b="Catelyn die Klinge leiht Euch ihren wiederbeschafften Trolldolch, um einen Altar unter den Wellen zu zerstören. Sie weiß weniger über Trollruinen als ihr Vater, hat aber von einer versunkenen Trollstadt gehört. Deshalb weist sie Euch nach Nordwesten, vom Basislager Grom'gol aus. Dort, in den Unterwasserruinen des Finsteren Riffs, leuchtet der Altar of the Tides blau zwischen Meereslebewesen und Murlocs."},{t="Der gefangene Magier",b="Ein Schlag mit Catelyns Klinge gegen den Altar of the Tides bricht dessen Magie und lockt Gazban hervor, einen Goblinmagier, der den Stein der Gezeiten trägt. Wird Gazban herausgefordert, nimmt er die Gestalt eines Wasserelementars an. Sobald Ihr ihn bezwungen habt, könnt Ihr den Stein und den geliehenen Dolch nach Beutebucht zurückbringen. Baron Revilgaz hat inmitten seiner kostbaren Sammlung einen besonderen Ausstellungsständer für die im Relikt eingefangene Meeresmagie vorbereitet."}},faq={{q="Wo befindet sich der Altar of the Tides?",a="Der Altar of the Tides liegt unter dem Meer im Finsteren Riff, einer versunkenen Ruine nordwestlich des Basislagers Grom'gol. Sein blaues Leuchten ist unter Wasser leicht zu erkennen.",al={"wo ist der altar","altar of the tides standort","wo finde ich den altar"}},{q="Warum will Baron Revilgaz den Stein?",a="Baron Revilgaz sammelt alte Trollantiquitäten. Er hat Platz geschaffen und einen edlen Ständer gekauft, um das Relikt auszustellen.",al={"revilgaz stein","warum revilgaz den stein will","was macht revilgaz damit"}},{q="Warum verleiht Catelyn ihre Klinge?",a="Catelyn leiht Euch ihr wiederbeschafftes besonderes Messer, um den Altar zu zerschmettern, und bittet Euch, es nach vollbrachter Tat unversehrt zurückzubringen.",al={"catelyn messer","warum das messer verleihen","catelyn klinge"}}},fp="22,204,16.333.0,16.407.1,40.149.0,39.117.0,32.121.0"}
P.entries["quest:6121"] = {n="Neue Lektionen",s="Mathrengyl Bärenfährte schickt Allianz-Druiden von Darnassus nach Mondlichtung, um die Reinigung von Giften zu erlernen. Dort beginnt Dendrite Sternenschauer ihre Unterweisung über Gifte und Toxine.",h="Mathrengyl Bärenfährte schickt Allianz-Druiden von Darnassus nach Mondlichtung, um die Reinigung von Giften...",kw={"auberdine","cenarius","cure poison","dendrite sternenschauer","neue lektionen","mathrengyl bärenfährte","mondlichtung","nachthafen","power over poison"},ang={["class:Druid"]="Als Druide geht Ihr über die Grundlagen der Gestaltwandlung und des Überlebens hinaus, um für die Wildnis zu sorgen. Ihr lernt, die Natur von tödlichem Verderben und Giften zu befreien.",["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr, wie lebenswichtig druidische Hilfe für die gefährdeten nördlichen Siedlungen der Dunkelküste ist, darunter Auberdine.",["race:NightElf"]="Von der Enklave des Cenarius in Darnassus aus werdet Ihr zu den tieferen, althergebrachten Pflichten geführt, die mit Mondlichtung und der Dunkelküste verbunden sind."},sec={{t="Eine Gabe von Cenarius",b="Cenarius lehrt Druiden und segnet sie mit einer Verbindung zur lebendigen Welt. Zu seinen Gaben gehört die Macht, Gift mit einer einfachen Beschwörung zu reinigen. Solche Macht bringt eine Bürde mit sich. Bevor junge Druiden sie einsetzen, lernen sie die harte, gewöhnliche Arbeit kennen, Toxine ohne die Magie der Natur zu bekämpfen."},{t="Ruf nach Nachthafen",b="Mathrengyl Bärenfährte bildet Druiden in der Enklave des Cenarius in Darnassus aus. Nun schickt er seinen Schüler über die örtlichen Übungen hinaus nach Mondlichtung. In Nachthafen koordiniert Dendrite Sternenschauer die überregionalen Bemühungen des Zirkels des Cenarius. Er hat praktische Arbeit für den Novizen."},{t="Eine wirkliche Krise",b="Die Initianden von Nachthafen stehen vor einer wirklichen Krise, keiner inszenierten Prüfung und keinem Ritual. Auberdine an der Küste der Dunkelküste leidet unter einer Welle von Tiervergiftungen, die seine Bewohner nicht aufhalten können. Dendrite Sternenschauer schickt den Novizen los, um Nachforschungen anzustellen und der Dunkelküste beizustehen. Leben stehen auf dem Spiel."}},faq={{q="Wer bietet die Quest Neue Lektionen an?",a="Mathrengyl Bärenfährte, der nachtelfische Druidenlehrer in der Enklave des Cenarius in Darnassus, bietet sie an.",al={"wer vergibt neue lektionen","neue lektionen questgeber","mathrengyl bärenfährte quest"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Reist nach Mondlichtung und meldet Euch bei Dendrite Sternenschauer in Nachthafen.",al={"wohin geht es","wo ist dendrite sternenschauer","neue lektionen abgeben"}},{q="Warum müssen Druiden zunächst lernen, Gifte wie ein Laie zu heilen?",a="Druidenlehrer fürchten, dass Cenarius' Gabe, Gift mit einer Beschwörung zu heilen, zu Selbstzufriedenheit führen könnte. Indem Initianden zunächst gewöhnliche Wege erlernen, Gift zu bekämpfen, erfahren sie, welche Bürde und welches Leid es mit sich bringt.",al={"warum wie ein laie","warum gift ohne magie heilen","cenarius giftlektion"}},{q="Welches Problem gibt es in Auberdine?",a="Auberdine leidet unter schweren Tiervergiftungen entlang der Küste der Dunkelküste. Die örtlichen Nachtelfen können sie nicht heilen und haben den Zirkel des Cenarius in Mondlichtung um Hilfe gebeten.",al={"auberdine giftproblem","was geschieht in auberdine","dunkelküste tiervergiftungen"}},{q="Welche Fähigkeit gewährt diese Questreihe schließlich?",a="Die Reihe beginnt mit Power over Poison, wodurch Druiden Cure Poison erlernen, einen Zauber, der Verbündete auf magische Weise von Toxinen reinigt.",al={"welche belohnung gibt es","cure poison quest","power over poison questreihe"}},{q="Ist diese Quest für Druiden der Horde verfügbar?",a="Nein. Neue Lektionen beginnt für Allianz-Druiden in Darnassus. Tauren-Druiden erhalten einen entsprechenden Einstieg in Donnerfels, der sie ebenfalls nach Mondlichtung schickt, um die Heilung von Giften zu erlernen.",al={"horde neue lektionen","können tauren das machen","tauren neue lektionen"}}},fx={cb6ddbb8={q="Warum schickt Mathrengyl Bärenfährte Euch zur Mondlichtung?",a="Als Euer Mentor in Darnassus erkennt Mathrengyl Bärenfährte, dass Eure druidische Ausbildung den Punkt erreicht hat, an dem Ihr den Segen des Cenarius über Gifte ausüben könnt. Er kann diese heilige Kunst nicht beiläufig verleihen; die druidische Tradition verlangt, dass Ihr unter Dendrite Sternenschauer in der Mondlichtung lernt, um sicherzustellen, dass Ihr die schwere Last des Giftes versteht, bevor Ihr die Gabe meistert, es zu reinigen.",al={"warum schickt mich mathrengyl","warum druide zur mondlichtung","warum ich neue lektionen"}}},fp="12,182,20.286.0,21.255.0,19.265.1,34.94.0,45.67.0,58.198.0,42.166.0,52.126.0,40.178.0"}
P.entries["quest:6122"] = {n="Die eigentliche Ursache",s="An den Cliffspring Falls haben kranke Hirsche den Zirkel des Cenarius ans Wasser geführt. Dendrite Sternenschauer schickt junge Druiden aus Mondlichtung los, um eine Probe für die Naturforscherin Alanndarian Nachtweise aus Auberdine zu sammeln.",h="An den Cliffspring Falls haben kranke Hirsche den Zirkel des Cenarius ans Wasser geführt.",kw={"alanndarian nachtweise","auberdine","zirkel des cenarius","cliffspring falls","gift heilen","dunkelküste","dendrite sternenschauer","naga","power over poison"},ang={["class:Druid"]="Als Druide stellt Ihr Euch der Verderbnis an den Cliffspring Falls und helft bei der Herstellung von Heilmitteln. Diese Prüfung lehrt Euch, wie Ihr Gifte in der Wildnis heilt.",["race:NightElf"]="Als Nachtelf aus Auberdine seht Ihr, wie die Verderbnis der Cliffspring Falls Eure angestammten Wälder und die dort lebenden Geschöpfe bedroht."},sec={{t="Eine lebenswichtige Wasserader verdirbt",b="Die Cliffspring Falls versorgen den Norden von Dunkelküste mit Süßwasser. Als Hirsche an einer schleichenden Krankheit zu leiden begannen, suchte der Zirkel des Cenarius deren Ursache im Fluss. Dendrite Sternenschauer in Mondlichtung vermutet, dass das Wasser verunreinigt ist. Er schickt Druidenneulinge los, um am Höhleneingang unterhalb der Wasserfälle eine Probe zu sammeln."},{t="Schatten an den Wasserfällen",b="Boshafte Naga hausen in der Cliffspring River Cave, nahe dem Quellgebiet der Wasserfälle. Ihre Anwesenheit gefährdet jeden, der die Verderbnis untersuchen will. Der Zirkel des Cenarius braucht eine Probe vom Höhleneingang, um herauszufinden, was die Wildnis krank macht."},{t="Ein tieferes Leiden",b="In Auberdine stellt Alanndarian Nachtweise fest, dass die Wasserprobe die Befürchtungen des Zirkels bestätigt. Die verderbten Wasserfälle vergiften die Flussufer, doch auch abseits des unmittelbaren Wasserlaufs wurden kranke Hirsche gesichtet.\n\nDie Probe könnte helfen, mit der Herstellung eines Gegengifts zu beginnen. Alanndarian vermutet, dass sich eine weiter reichende Verderbnis im Grundwasser von Dunkelküste ausbreitet."}},faq={{q="Warum sind die Cliffspring Falls so wichtig für Dunkelküste?",a="Die Cliffspring Falls versorgen den Norden von Dunkelküste mit Süßwasser. Ihr Quellwasser speist die örtlichen Bäche und Flüsse, sodass sich Verunreinigungen im umliegenden Land und unter den Wildtieren ausbreiten können.",al={"warum cliffspring falls wichtig sind","bedeutung des klippenquells","wasserquelle von dunkelküste"}},{q="Warum erkranken die Hirsche in Dunkelküste?",a="Die Hirsche trinken aus den Cliffspring Falls und den Bächen, die sie speisen. Das Wasser ist an seiner Quelle verunreinigt, und der Schadstoff macht die Waldtiere krank.",al={"warum sind die hirsche krank","kranke hirsche in dunkelküste","was hat die hirsche vergiftet"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein altgedienter Druidenlehrer in Mondlichtung. Er leitet junge Druiden an, hält in ganz Kalimdor nach Störungen Ausschau und koordiniert die Maßnahmen des Zirkels des Cenarius bei Naturkrisen.",al={"geschichte von dendrite sternenschauer","wer hat mir diese quest gegeben","sternenschauer mondlichtung"}},{q="Wer ist Alanndarian Nachtweise?",a="Alanndarian Nachtweise ist eine Naturforscherin der Nachtelfen in Auberdine. Besorgt über die Verderbnis und die leidenden Wildtiere in Dunkelküste bat sie den Zirkel des Cenarius in Mondlichtung um Hilfe bei der Erforschung des Leidens und der Suche nach einem Heilmittel.",al={"wer ist alanndarian nachtweise","nachtweise auberdine"}},{q="Warum sind Naga an den Cliffspring Falls?",a="Naga von der Küste Dunkelküstes sind ins Landesinnere gezogen und haben das Höhlensystem hinter den Cliffspring Falls besetzt. Ihre Anwesenheit gefährdet jeden, der das Quellgebiet erreichen und das Wasser untersuchen will.",al={"naga in cliffspring cave","warum sind hier naga","cliffspring falls naga"}},{q="Welche Fähigkeit hilft diese Quest Druiden zu erlernen?",a="Die Untersuchung ist Teil der Prüfung Power over Poison. Indem Druidenanwärter die Krankheit der Wildtiere erforschen und mit Alanndarian Nachtweise an einem Gegengift arbeiten, lernen sie, Gifte zu heilen.",al={"welchen zauber gibt diese quest","druidenquest zu gift","questreihe zum heilen von gift"}}},fx={df1ca1a8={q="Warum will Dendrite Sternenschauer, dass das getan wird?",a="Als Abgesandter des Zirkels des Cenarius in der Mondlichtung ist Dendrite Sternenschauer daran gebunden, das natürliche Gleichgewicht von Kalimdor zu schützen. Alanndarian Nachtweise hat sich von Auberdine aus um Hilfe gegen eine virulente Krankheit bemüht, die die Tierwelt der Dunkelküste vergiftet. Dendrite vermutet, dass die Kontamination ihren Ursprung an den Klippenquellfällen hat, der wichtigsten Süßwasserquelle der Region, und muss deren Quelle bestätigen, um bei der Schaffung eines Heilmittels zu helfen.",al={"dendrites motiv","warum schickt mich dendrite","warum klippenquellfälle untersuchen"}},["87aa05d6"]={q="Wofür ist die Gefüllte Probe der Klippenquellfälle?",a="Die Probe enthält korrumpiertes Wasser, das direkt aus der Höhlenmündung bei den Klippenquellfällen entnommen wurde. Wenn Ihr sie zu Alanndarian Nachtweise in Auberdine bringt, kann sie die genaue Art des Giftes analysieren, das die Tierwelt der Dunkelküste befällt, und mit der Herstellung eines wirksamen Heilmittels beginnen.",al={"nutzen der gefüllten probe der klippenquellfälle","wofür ist die wasserprobe","warum klippenquellwasser sammeln"}},["00d3706a"]={q="Warum schickt Dendrite Sternenschauer Euch, anstatt es selbst zu erledigen?",a="Dendrite dient als wichtiger Verbindungsmann für den Zirkel des Cenarius in der Mondlichtung und koordiniert umfassendere druidische Bemühungen in ganz Kalimdor. Die Untersuchung der Quelle und die Zusammenarbeit mit Alanndarian vor Ort in der Dunkelküste bietet eine wesentliche Feldprüfung für einen aufsteigenden Druiden, der lernt, Macht über Gift auszuüben.",al={"warum ich dendrite","warum braucht dendrite druiden","warum einen lehrling schicken"}}},fp="20,196,26.307.0,20.240.0,15.334.1,51.178.0,42.152.0,26.190.0,29.222.0,34.192.0,47.185.0"}
P.entries["quest:6123"] = {n="Das Heilmittel sammeln",s="In der Dunkelküste brauchen kranke Rehe eine Salbe, und Alanndarian Nachtweise in Auberdine zeigt einem jungen Druiden, wie man sie herstellt. Das Heilmittel erfordert Wasser und Heilpflanzen, die in der Nähe gesammelt werden.",h="In der Dunkelküste brauchen kranke Rehe eine Salbe, und Alanndarian Nachtweise in Auberdine zeigt einem...",kw={"alanndarian nachtweise","auberdine","cure poison","dunkelküste","druidenquest","erdwurzel","das heilmittel sammeln","lunarfungus","mondkin höhlen"},ang={["class:Druid"]="Als Druide lernt Ihr, wie gewöhnliche Heilmittel gegen natürliche Gifte wirken. Dieses Wissen bereitet Euch darauf vor, heilende Kraft zu kanalisieren, ohne auf Hilfsmittel angewiesen zu sein.",["profession:Herbalism"]="Als Kräuterkundiger besitzt Ihr das geschulte Auge, das Alanndarian beim Aufspüren von Erdwurzel in der Wildnis schätzt.",["race:NightElf"]="Als Nachtelf teilt Ihr die Pflicht der Kaldorei, die heiligen Haine und die Tierwelt der Dunkelküste zu schützen, in Ehrfurcht vor Elune und den Geistern der Wildnis."},sec={{t="Ein Heilmittel für die Tierwelt der Dunkelküste",b="Alanndarian Nachtweise sucht ein Heilmittel für die kranken Rehe der Dunkelküste. Eine verunreinigte Wasserquelle hat der heimischen Tierwelt geschadet, daher soll eine Wasserprobe aus Cliffspring die Grundlage der Salbe bilden. Natürliche Zutaten mit heilender Wirkung müssen die Mischung vervollständigen. Die Rehe können sich nicht von selbst erholen, und der Zirkel des Cenarius braucht bald ein Heilmittel."},{t="Wurzeln und Mondblüten",b="Erdwurzel und Lunarfungus verleihen der Salbe Heilkraft. Erdwurzel wächst in felsigem Boden, wo das geschulte Auge eines Kräuterkundigen hilft, sie zu finden. Lunarfungus blüht in Höhlen östlich von Auberdine. Die Mondkin dort verteidigen ihr Revier inzwischen erbittert und sind aufgebracht, was das Sammeln gefährlicher macht."},{t="Der Weg zur Giftreinigung",b="Alanndarian Nachtweise lehrt den Lehrling, wie viel Sorgfalt es erfordert, ein Heilmittel gegen ein bestimmtes Gift zu brauen. Jeder Schritt beim Sammeln und Zubereiten der Zutaten verlangt Sorgfalt. Diese Lektion bereitet den Druiden darauf vor, Gifte mit Naturmagie zu reinigen, ohne für jedes ein eigenes Mittel brauen zu müssen."}},faq={{q="Welchen Zweck hat Das Heilmittel sammeln?",a="Ein Druidenlehrling sammelt Erdwurzel und Lunarfungus für Alanndarian Nachtweise in Auberdine. Aus den Zutaten entsteht eine heilende Salbe für die kranken Rehe der Dunkelküste, während die Arbeit lehrt, wie Heilmittel Giften entgegenwirken können.",al={"warum diese quest machen","das heilmittel sammeln ziel","wozu dient das heilmittel sammeln"}},{q="Wo wächst der Lunarfungus?",a="Lunarfungus wächst in Höhlen in den Hügeln direkt östlich von Auberdine. Wilde Mondkin dort verteidigen ihr Revier inzwischen erbittert und sind aggressiv geworden.",al={"wo ist lunarfungus","lunarfungus fundort","wie lunarfungus finden"}},{q="Muss ich Kräuterkundiger sein, um Erdwurzel zu bekommen?",a="Ihr braucht Herbalism nicht, um Erdwurzel zu erhalten, obwohl sie in wilden Kräutervorkommen wächst. Ohne diese Fertigkeit müsst Ihr mit einem Kräuterkundigen handeln oder das Kraut für Alanndarians Rezept von jemand anderem besorgen.",al={"herbalism für erdwurzel nötig","erdwurzel ohne kräuterkundiger zu sein","erdwurzel ohne beruf"}},{q="Wer ist Alanndarian Nachtweise?",a="Alanndarian Nachtweise ist eine Nachtelfe in Auberdine, die den Zirkel des Cenarius um Hilfe gebeten hat. Sie wacht über die Pflanzen und Tiere der Dunkelküste und führt junge Druiden durch ihre ersten Prüfungen zur Reinigung und zum Schutz der Wildnis.",al={"wer ist alanndarian","alanndarian nachtweise hintergrundgeschichte"}},{q="Warum sind die Rehe in der Dunkelküste krank?",a="Die Rehe der Dunkelküste haben Wasser getrunken, das durch eine verunreinigte Quelle vergiftet wurde. Das Gift lässt sie leiden, und ohne eine heilende Salbe können sie sich nicht erholen.",al={"warum sind rehe vergiftet","kranke rehe dunkelküste","was hat die rehe vergiftet"}},{q="Wie hilft mir diese Quest, Cure Poison zu erlernen?",a="Die Ausbildung lehrt Lehrlinge, mit welcher Sorgfalt pflanzliche Gegenmittel für einzelne Gifte zubereitet werden müssen. Der Zirkel des Cenarius nutzt diese Lektion, um Druiden darauf vorzubereiten, Naturmagie zu kanalisieren, die Gift neutralisieren kann.",al={"cure poison druidenquest","cure poison lernen","power over poison questreihe"}}},fx={["0cfb14cd"]={q="Warum möchte Alanndarian Nachtweise, dass dies getan wird?",a="Als Druidin, die in Auberdine über die Dunkelküste wacht, kann Alanndarian nicht untätig zusehen, wie die heimische Tierwelt leidet. Die örtlichen Hirsche sind einem schwächenden Leiden erlegen und können sich nicht von selbst erholen. Das Herstellen einer wirksamen Heilsalbe ist ihre unmittelbare Priorität, um ihr Leiden zu beenden und das Gleichgewicht in den korrumpierten Wäldern wiederherzustellen.",al={"alanndarian beweggrund","warum kranke hirsche heilen","warum kümmert sich alanndarian"}},e3b496ec={q="Wofür ist die Erdwurzel gut?",a="Alanndarian benutzt die Erdwurzel, um ihrer Heilsalbe wiederherstellende Eigenschaften zu verleihen. Vermischt mit der Wasserprobe aus den Cliffspring Falls, die als Basis für die Salbe dient, wirkt die natürliche medizinische Essenz des Krauts den Giften entgegen, die die Hirsche der Dunkelküste krank machen.",al={"warum erdwurzel","was bewirkt erdwurzel","erdwurzel salbe"}},["74e6ce3c"]={q="Wofür ist der Lunarfungus gut?",a="Der Lunarfungus verleiht der Salbe die notwendige Stärke. Seine wirksame, natürliche Blüte verstärkt die Heilkraft der Mischung und stellt sicher, dass das Mittel stark genug ist, um das tief sitzende Gift zu beseitigen, das die betroffenen Hirsche befällt.",al={"warum lunarfungus","zweck lunarfungus","fungus für salbe"}}},fp="18,176,33.319.0,22.279.0,28.277.1,42.213.0,33.126.0,46.199.0,29.225.0,35.140.0,46.205.0"}
P.entries["quest:6124"] = {n="Heilung der Kranken",s="An der ganzen Dunkelküste erkranken Hirsche, und „Heilung der Kranken“ gibt Euch die Möglichkeit, ihnen zu helfen. Alanndarian Nachtweise gibt Euch Salbe für die vergifteten Tiere, bevor Ihr dem Zirkel des Cenarius in der Mondlichtung Bericht erstattet.",h="An der ganzen Dunkelküste erkranken Hirsche, und „Heilung der Kranken“ gibt Euch die Möglichkeit, ihnen zu...",kw={"alanndarian nachtweise","auberdine","zirkel des cenarius","der klippenquell","heilende tiersalbe","heilung der kranken","dunkelküste","dendrite sternenschauer","gift","kränkliche hirsche"},ang={["class:Druid"]="Als Druide beweist Ihr Euren Einsatz für die Bewahrung des Gleichgewichts und bereitet Euch darauf vor, Gifte mit druidischer Magie zu beseitigen.",["race:NightElf"]="Als Nachtelf kennt Ihr die Dunkelküste als den Rand der besiedelten Gebiete Eures Volkes. Krankheit unter ihren Hirschen ist ein unheilvolles Zeichen für die kaldorei."},sec={{t="Eine Seuche in den Wäldern",b="An der ganzen Dunkelküste erkranken Hirsche, vom Klippenquell südwärts bis zur Grenze des Eschentals. Sie durchstreifen die nebligen Wälder, geschwächt von Giftstoffen im Boden und in den Bächen. Nachdem Ihr die nötigen Reagenzien gesammelt habt, gibt Euch Alanndarian Nachtweise frisch gebraute Tiersalbe, um sie zu behandeln."},{t="Geöffnete Augen in der Mondlichtung",b="Nachdem Ihr zehn Hirsche behandelt habt, erstattet Ihr Dendrite Sternenschauer in der Mondlichtung Bericht. Auberdine erfährt etwas Erleichterung, doch Dendrite sieht die Krankheit der Herden als Zeichen einer tieferen Verderbnis, die sich im Norden Kalimdors ausbreitet. Er warnt, dass die Anführer in Darnassus debattieren, während die Fäulnis voranschreitet. Der Zirkel des Cenarius muss wachsam verfolgen, wie weit sie sich über den Kontinent ausbreitet."}},faq={{q="Warum sind die Hirsche an der Dunkelküste krank?",a="Verderbnis im Boden und im Wasser der Dunkelküste macht die Hirsche krank, vom Klippenquell südwärts bis zum Eschental. Sie fressen verseuchte Pflanzen und trinken das verunreinigte Wasser, wodurch sie schwach und krank werden.",al={"warum sind hirsche krank","dunkelküste kränkliche hirsche","was hat die hirsche vergiftet"}},{q="Wer bereitet die heilende Salbe für die Hirsche zu?",a="Alanndarian Nachtweise bereitet in Auberdine die Heilende Tiersalbe aus Reagenzien zu, die Ihr sammelt. Ihre Zubereitung enthält zehn Dosen für die leidenden Tiere, während sie und die Stadtbewohner versuchen, mehr herzustellen.",al={"wer stellt das heilmittel her","alanndarian salbe","heilende tiersalbe hersteller"}},{q="Warum kümmert sich Dendrite Sternenschauer um die Hirsche?",a="Dendrite Sternenschauer beaufsichtigt die Druidenausbildung für den Zirkel des Cenarius in der Mondlichtung. Die Versorgung der Hirsche prüft das Pflichtbewusstsein eines Druiden und bestätigt, dass sich gefährliche Verderbnis in Kalimdors Wildnis ausbreitet.",al={"warum dendrite mondlichtung","interesse des zirkels des cenarius an hirschen","dendrite sternenschauer rolle"}},{q="Welche politischen Spannungen deutet Dendrite Sternenschauer an?",a="Dendrite sagt, dass einige nachtelfische Würdenträger in Darnassus die wachsende Fäulnis erkennen, während andere ihre Warnzeichen ignorieren. Er drängt Euch, Euch den harten Wahrheiten über die Natur zu stellen.",al={"darnassus spannungen","wer ignoriert die verderbnis","darnassus scheuklappen"}},{q="Wo sind die kränklichen Hirsche zu finden?",a="Kränkliche Hirsche durchstreifen die Dunkelküste, vom Gebiet südlich des Klippenquells, unmittelbar nördlich von Auberdine, bis zur Grenze des Eschentals.",al={"kränkliche hirsche fundort","wo sind die hirsche","dunkelküste hirsche fundort"}},{q="Was lernt ein Druide beim Erfüllen dieser Aufgabe?",a="Ihr lernt durch praktische Arbeit, Gift zu beseitigen. Leidende Waldtiere mit einem greifbaren Heilmittel zu behandeln, verbindet pflanzliche Heilmittel mit geistiger Macht über Gift.",al={"was lernen druiden daraus","gift heilen ausbildung druide","lehre aus heilung der kranken"}}},fx={["5b53be21"]={q="Warum möchte Alanndarian Nachtweise, dass die Hirsche geheilt werden?",a="Alanndarian sieht, wie die Tierwelt der Dunkelküste unter einem heimtückischen und sich ausbreitenden Leiden leidet. Während sie in Auberdine zurückbleibt, um die Dorfbewohner zu sammeln und mehr Medizin zu brauen, benötigt sie einen fähigen Druiden, der sofort im Feld handelt. Sich um die betroffenen Hirsche zu kümmern, beendet ihr Leiden, bevor die Krankheit die lokalen Herden vollständig auslöscht.",al={"alanndarian beweggrund","warum hirsche heilen alanndarian","alanndarian nachtweise dunkelküste hirsch"}},["73042015"]={q="Warum bittet Alanndarian Euch und nicht die Wachen von Auberdine, die Hirsche zu heilen?",a="Die Stadtbewohner und Späher von Auberdine sind damit beschäftigt, die Siedlung zu verteidigen und mit Alanndarian zusammenzuarbeiten, um mehr Salbe herzustellen. Außerdem erfordert das Beruhigen wilder, fiebriger Tiere die ruhige Hand und das Einfühlungsvermögen eines Eingeweihten des Zirkels des Cenarius. Als Druide in der Ausbildung seid Ihr besonders gut geeignet, Euch direkt um die Tiere der Wildnis zu kümmern.",al={"warum fragt alanndarian mich","warum nicht auberdine späher","warum druiden zum hirsche heilen schicken"}}},fp="15,209,25.286.0,26.345.1,35.200.0,49.192.0,48.208.0,55.181.0,35.124.0,50.167.0"}
P.entries["quest:6125"] = {n="Macht über Gift",s="In Darnassus kehrt ein junger Druide mit Macht über Gift zurück, um die Prüfung des Zirkels des Cenarius abzuschließen. Sie begann an der Dunkelküste, wo der Initiant lernte, von Hand ein Heilmittel zu brauen.",h="In Darnassus kehrt ein junger Druide mit Macht über Gift zurück, um die Prüfung des Zirkels des Cenarius...",kw={"auberdine","die enklave des cenarius","cure poison","darnassus","dendrite sternenschauer","mathrengyl bärenfährte","mondlichtung","macht über gift"},ang={["class:Druid"]="Als Druide beginnt Ihr mit einfacher Kräuterarbeit, bevor Ihr die Magie der Natur empfangt, um Gifte zu beseitigen.",["race:NightElf"]="Als Nachtelf stellt Ihr Euch dieser Prüfung in der Enklave des Cenarius in Darnassus. Sie spiegelt die Ehrfurcht der Kaldorei vor dem Gleichgewicht und ihre Fürsorge für ihre uralten Wälder wider."},sec={{t="Die Demut des Schülers",b="An der Dunkelküste schickt Alanndarian Nachtweise junge Druiden aus, um Erdwurzel und Lunarfungus von Hand zu sammeln. Daraus brauen sie eine Salbe für erkrankte Wildtiere. Bevor der Zirkel des Cenarius die Magie lehrt, die Giftstoffe austreibt, sollen Initianten lernen, wie beschwerlich die Behandlung von Vergiftungen ohne spirituellen Beistand ist. Diese Arbeit zeigt ihnen, was einfache Leute bei einer Vergiftung erdulden und warum ein Druide ihrem Leiden mit Fürsorge begegnen muss."},{t="Rückkehr zur Enklave",b="Das Heilmittel erweist sich in Auberdine als wirksam, und Starblaze schickt den Druiden über das Meer nach Darnassus. Mathrengyl Bärenfährte wartet in der Enklave des Cenarius. Erfreut über die Gelassenheit des Initianten unter Druck, lehrt er ihn, Giftstoffe durch die Kraft der Natur zu beseitigen. Doch die hochwirksamen Gifte in der Wildnis um Auberdine bereiten ihm Sorgen. Sie deuten auf eine unnatürliche Verderbnis hin, die das Gleichgewicht des Landes stört."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Prüfung bereitet einen Druiden darauf vor, Vergiftungen mit Magie zu heilen, nachdem er zunächst von Hand eine Salbe hergestellt hat. Von der Dunkelküste kehrt der Schüler zu Mathrengyl Bärenfährte in Darnassus zurück, um Cure Poison zu erlernen.",al={"warum macht über gift abschließen","macht über gift ziel","cure poison quest"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein Druidenältester in Nachthafen in der Mondlichtung. Er führt Initianten durch spirituelle Prüfungen, die ihre Geduld und Hingabe an die Natur auf die Probe stellen, und schickt sie dann zu ihren heimischen Lehrern.",al={"dendrite sternenschauer rolle","wer vergibt macht über gift"}},{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein Meister der Druidenausbildung in der Enklave des Cenarius in Darnassus. Unter den Ästen Teldrassils unterweist er Nachtelfendruiden in Gestalten, Heilkunst und den Pflichten des Zirkels des Cenarius.",al={"mathrengyl bärenfährte hintergrund","bärenfährte darnassus"}},{q="Warum musste der Druide zuerst von Hand ein Heilmittel herstellen?",a="Dendrite Sternenschauer lehrt Druiden, die körperlichen Folgen einer Vergiftung und die Mühen ihrer Behandlung ohne Magie zu verstehen. Gewöhnliche Zutaten zu sammeln und Kranke von Hand zu pflegen, lehrt Demut und Dankbarkeit für die Gaben der Natur, die sie bald empfangen werden.",al={"warum ein kräuterheilmittel herstellen","lehre von macht über gift"}},{q="Was beunruhigt Mathrengyl an der Lage in Auberdine?",a="Mathrengyl hält die tödlichen Giftstoffe in der Wildnis der Dunkelküste um Auberdine für unnatürlich. Ihre Auswirkungen auf heimische Wildtiere und Pflanzen bedrohen das Gleichgewicht des Landes und deuten auf einen verderblichen Einfluss entlang der Küste hin.",al={"auberdine gift hintergrund","mathrengyls sorge"}}},fx={["92345f63"]={q="Warum schickt Euch Dendrite Sternenschauer zurück nach Darnassus?",a="Dendrite Sternenschauer möchte, dass Ihr Eure Initiation abschließt. Nachdem er Euch gezwungen hat, Kräuter zu sammeln und die Kranken in Auberdine von Hand zu heilen, hat er sichergestellt, dass Ihr die Mühen zu schätzen wisst, denen gewöhnliche Sterbliche beim Kampf gegen Gift ausgesetzt sind. Jetzt, da Ihr die Einsätze und die Demut versteht, die von einem Hüter der Natur verlangt werden, schickt er Euch zurück, damit Mathrengyl Bärenfährte Euch den wahren druidischen Zauber verleihen kann.",al={"warum zu mathrengyl schicken","dendrite sternenschauer beweggrund","warum zurück nach darnassus"}}},fp="17,172,22.416.0,21.391.0,34.184.0,26.200.0,29.203.0,56.253.0,58.210.0"}
P.entries["quest:6126"] = {n="Neue Lektionen",s="In Donnerfels schickt Turak Runentotem junge Taurendruiden in die heilige Mondlichtung, um die Reinigung von Giften zu erlernen. Unter Dendrite Sternenschauer, einem Nachtelfendruiden, beginnen Lehrlinge dieses Studium, während echte Vergiftungen mehr als bloße Übungen verlangen.",h="In Donnerfels schickt Turak Runentotem junge Taurendruiden in die heilige Mondlichtung, um die Reinigung von...",kw={"zirkel des cenarius","das wegekreuz","cure poison","dendrite sternenschauer","neue lektionen","mondlichtung","nachthafen","turak runentotem"},ang={["class:Druid"]="Als Druide führt Euch Euer Weg von grundlegender Gestaltwandlung und Scharmützeln hin zur Obhut über die Wildnis. Nun beginnt Euer Weg damit, Cure Poison zu erlernen.",["faction:Horde"]="Als Mitglied der Horde findet Ihr in Mondlichtung unter dem heiligen Schutz des Zirkels des Cenarius Zuflucht, selbst während Hordenkrieger im Eschental gegen Nachtelfen kämpfen.",["race:Tauren"]="Als Tauren zeigt Eure Pilgerreise, wie tief sich die Kinder der Earth Mother an der Seite ihrer nachtelfischen Gefährten wieder mit den Lehren des Cenarius verbunden haben."},sec={{t="Die Gabe des Cenarius",b="Cenarius schenkte den Druiden eine Beschwörungsformel zur Reinigung von gefährlichen Giften und trug ihnen auf, die Wildnis zu schützen. Turak Runentotem lehrt, dass solche Magie fundiertes Wissen erfordert. Bevor ein Druide damit eine Plage beseitigt, muss er die körperlichen Auswirkungen von Gift verstehen und lernen, es mit gewöhnlichen Mitteln zu behandeln."},{t="Ruf nach Nachthafen",b="Turak schickt vielversprechende Akolythen von Mulgore aus über heilige Pfade nordwärts nach Mondlichtung. Dort, im friedlichen Dorf Nachthafen, unterweisen uralte Nachtelfenmentoren wie Dendrite Sternenschauer Elfen und Tauren gleichermaßen. Ihr gemeinsames Studium spiegelt den empfindlichen Waffenstillstand des Zirkels des Cenarius wider, der über den politischen Streitigkeiten zwischen Horde und Allianz steht."},{t="Eine echte Krise im Brachland",b="Nahe dem Wegekreuz im Brachland breiten sich unkontrollierte Vergiftungen unter den Tieren aus. Dendrite Sternenschauer hat keine Zeit für Übungen: Ein Hilferuf vom Wegekreuz ist eingetroffen. Diese Bitte verwandelt einen Übergangsritus in einen dringenden Feldeinsatz, bei dem junge Druiden dem Leiden wilder Tiere gegenüberstehen."}},faq={{q="Wer bietet diese Quest an und wo finde ich ihn?",a="Turak Runentotem, der Druidenlehrer der Tauren, bietet den Ritus auf der Anhöhe der Ältesten in Donnerfels an. Er ruft Initianden zu sich, die sich schon früh den Lehren des Cenarius verschrieben haben.",al={"wer vergibt neue lektionen","wo gibt es neue lektionen","questgeber neue lektionen"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein betagter Nachtelfendruide, der in Nachthafen in Mondlichtung lebt. Trotz der Spannungen zwischen Nachtelfen und Tauren lehrt er junge Druiden beider Völker die Traditionen des Zirkels des Cenarius.",al={"wer ist dendrite","dendrite sternenschauer rolle","wer ist der nachtelf in mondlichtung"}},{q="Welche Kraft erlerne ich bei dieser Quest?",a="Eure Unterweisung beginnt mit Cure Poison. Die Lektionen behandeln die körperliche und magische Natur von Gift und lehren Druiden, Verbündete und ihnen anvertraute Wildtiere von schädlichen Leiden zu reinigen.",al={"welche fähigkeit wird erlernt","für welchen zauber ist das","quest zur giftheilung"}},{q="Warum muss ein Tauren bei einem Nachtelfen lernen?",a="Der Zirkel des Cenarius ist eine neutrale Bruderschaft, die sich dem Gleichgewicht der Natur verschrieben hat. Nachtelfen gaben dem modernen Druidentum unter Cenarius zunächst seine feste Form, nahmen dann die Tauren wieder in den Orden auf und teilten trotz des Fraktionskrieges heilige Orte wie Mondlichtung.",al={"warum ein nachtelf als lehrer","tauren und nachtelfen als druiden","zirkel des cenarius fraktion"}},{q="Was geschieht am Wegekreuz?",a="Die Tierwelt um das Wegekreuz im Brachland leidet unter einer heftigen Vergiftungswelle, die die örtlichen Tierbetreuer nicht eindämmen können. Dendrite Sternenschauer verlagert Eure Ausbildung ins Gelände, wo Ihr die Ursache finden und ein Heilmittel herstellen sollt.",al={"problem am wegekreuz","was vergiftet die tiere","krankheit am wegekreuz"}},{q="Wie komme ich für diese Quest am schnellsten nach Mondlichtung?",a="Als Druide verfügt Ihr über den angeborenen Zauber Teleport: Mondlichtung, der Euch direkt nach Nachthafen bringt. Er erspart Euch einen Fußmarsch durch gefährliche, umkämpfte Gebiete.",al={"wie nach mondlichtung gelangen","reise nach nachthafen","teleport mondlichtung"}}},fx={be063b64={q="Warum schickt Euch Turak Runentotem zur Mondlichtung?",a="Turak glaubt, dass Ihr endlich bereit seid, einen der größten Segnungen zu erben, die Cenarius den Druiden verliehen hat: die Kunst, tödliche Gifte durch Beschwörung zu heilen. Solch heilige Magie wird nicht beiläufig gewährt. Um sicherzustellen, dass Ihr diese Macht respektiert, verlangt Turak, dass Ihr zuerst Gift so versteht, wie es ein gewöhnlicher Heiler tun würde, und weist Euch an Dendrite Sternenschauer in der Mondlichtung, um Eure formelle Ausbildung zu beginnen.",al={"warum schickt mich turak","turak runentotem beweggrund","warum zur mondlichtung gehen"}}},fp="12,236,20.291.0,21.363.0,28.289.1,47.178.0,26.208.0,37.189.0,50.249.0,36.231.0,59.167.0"}
P.entries["quest:6127"] = {n="Die eigentliche Ursache",s="Von Mondlichtung aus schickt Dendrite Sternenschauer Druiden der Horde zum Glutnebelgipfel, um eine Wasserprobe zu holen. Sie bittet sie, diese zu Tonga Runentotem am Wegekreuz zu bringen, wo sie Aufschluss über das Gift geben könnte, das die Tierwelt schädigt.",h="Von Mondlichtung aus schickt Dendrite Sternenschauer Druiden der Horde zum Glutnebelgipfel, um eine...",kw={"brachland","zirkel des cenarius","das wegekreuz","dendrite sternenschauer","glutnebelgipfel","power over poison","die eigentliche ursache","kränkliche gazelle","tonga runentotem"},ang={["class:Druid"]="Als Druide verfolgt Ihr Verderbnis bis zu ihrer Quelle und isoliert magische Giftstoffe, bevor sie ein Ökosystem zerstören.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, das Wegekreuz zu schützen, ein wichtiges Zentrum des Lebens der Horde in Kalimdor. Dämonische Verderbnis bedroht dort Handel und Überleben.",["race:Tauren"]="Als Tauren helft Ihr, die Gazellenherden des Brachlands vor dämonischer Verderbnis zu bewahren. Dies sind die angestammten Gebiete der Stämme Kalimdors."},sec={{t="Ein verseuchter Berg",b="Dendrite Sternenschauer fürchtet, dass die Burning Blade den Glutnebelgipfel verseucht hat. Der Berg erhebt sich nordwestlich des Wegekreuzes über dem trockenen nördlichen Brachland. Quellen und Teiche krönen seine Höhen und prägen das örtliche Wetter und die Feuchtigkeit. Nun hat sich ein Dämonenkult auf den Felsen festgesetzt, und seine finstere Zauberei könnte das Becken vergiften."},{t="Eine Seuche der Ebenen",b="Kranke Gazellen taumeln durch die nördliche Savanne, nördlich des Hauptwegs, der von Osten nach Westen durch das Wegekreuz führt. Tonga Runentotem sucht Hilfe für die einheimischen Tauren und bittet den Zirkel des Cenarius, herauszufinden, was die Herde vergiftet. Mit einer Wasserprobe vom Gipfel kann er die Krankheit untersuchen und ein Gegengift brauen."}},faq={{q="Wo bekomme ich die Wasserprobe für diese Quest?",a="Entnehmt Wasser aus dem Teich auf dem Glutnebelgipfel, nordwestlich des Wegekreuzes im Brachland. Die Burning Blade versammelt sich dort, und Dendrite Sternenschauer gibt Euch einen Probenehmer.",al={"glutnebelgipfel teich standort","wo ist der wasserteich","die eigentliche ursache wasserprobe"}},{q="Warum ist das Wasser auf dem Glutnebelgipfel so wichtig für das Brachland?",a="Die hochgelegenen Teiche des Glutnebelgipfels beeinflussen das örtliche Wetter und den Nebel. Sobald die Burning Blade sie verunreinigt, breiten sich giftige Dämpfe und abfließendes Wasser über die Ebenen aus und machen die Wildtiere im nördlichen Brachland krank.",al={"warum der glutnebelgipfel wichtig ist","brachland wetter teich","glutnebelgipfel teiche"}},{q="Wer ist Tonga Runentotem?",a="Tonga Runentotem ist ein Taurendruide am Wegekreuz im Brachland. Beunruhigt über die seltsame Krankheit unter den örtlichen Gazellen, bat er den Zirkel des Cenarius in Mondlichtung, sie zu untersuchen und das Land zu reinigen.",al={"wer ist tonga","tonga runentotem rolle","wegekreuz druide"}},{q="Wer verdirbt das Wasser auf dem Gipfel?",a="Die Burning Blade hat die Gewässer verdorben. Ihre dämonenanbetenden Hexenmeister und Teufelsmagier besetzen die gewundenen Pfade und die Spitze des Glutnebelgipfels.",al={"wer hat den teich verseucht","glutnebelgipfel kultisten","burning blade glutnebelgipfel"}},{q="Welche Fähigkeit erlerne ich durch den Abschluss dieser Questreihe?",a="Der Ritus von Power over Poison vermittelt jungen Druiden der Horde das spirituelle und kräuterkundliche Wissen, um unterwegs Vergiftungen zu heilen.",al={"power over poison belohnung","druide giftheilungszauber","gift heilen quest brachland"}},{q="Können Druiden der Allianz diese Quest machen?",a="Nein. Die eigentliche Ursache schickt Druiden der Horde ins Brachland, um Tonga Runentotem zu helfen. Druiden der Allianz unternehmen eine ähnliche Reise an der Dunkelküste, um zu lernen, Vergiftungen zu heilen.",al={"allianz gegenstück","können nachtelfen die eigentliche ursache machen","allianz giftquest"}}},fx={["41ffa32f"]={q="Warum möchte Dendrite Sternenschauer, dass dies getan wird?",a="Tonga Runentotem hat sich an den Zirkel des Cenarius in der Mondlichtung gewandt, um Hilfe zu suchen, eine sich ausbreitende Krankheit im Brachland zu stoppen. Dendrite Sternenschauer vermutet, dass die dämonenanbetende Burning Blade die Tümpel auf dem Glutnebelgipfel vergiftet hat. Da diese Hochgewässer die Wettermuster der Region beeinflussen, bedroht ihre Verderbnis das empfindliche Gleichgewicht des gesamten nördlichen Brachlands.",al={"warum braucht dendrite dies","dendrite sternenschauer beweggrund","warum wasser untersuchen"}},["54ce2e01"]={q="Wofür ist die Gefüllte Glutnebelgipfelprobe gut?",a="Die gefüllte Probe enthält verseuchtes Wasser, das direkt aus dem höchsten Tümpel des Gipfels entnommen wurde. Tonga Runentotem benötigt diese üble Probe im Wegekreuz, um die schlimmen Gifte zu analysieren, die die lokale Tierwelt infizieren, was es ihm und dem Zirkel des Cenarius ermöglicht, die Verschmutzung zu untersuchen und ein wirksames Heilmittel für die betroffenen Gazellen zu brauen.",al={"verwendung gefüllte glutnebelgipfelprobe","wofür ist die wasserprobe","zweck probe"}},["2b67a7e4"]={q="Warum schickt Dendrite Sternenschauer Euch, anstatt selbst zu gehen?",a="Als Ältester des Zirkels des Cenarius, der in der heiligen Mondlichtung residiert, beaufsichtigt Dendrite viele Angelegenheiten und verlässt sich auf vielversprechende junge Druiden, die als Hände des Zirkels in ganz Kalimdor dienen. Tongas Bitte zu beantworten, bietet eine wesentliche Lektion im Reinigen von Verderbnis und dem Meistern natürlicher Heilmittel, wobei Eure Fähigkeit getestet wird, das Land zu heilen.",al={"warum mich schicken","warum geht dendrite nicht selbst","warum ein druidenschüler"}}},fp="20,208,18.328.0,22.305.0,47.173.0,63.192.0,23.200.0,40.145.0,46.121.0,34.164.0"}
P.entries["quest:6128"] = {n="Das Heilmittel sammeln",s="Am Wegekreuz führt Tonga Runentotem junge Taurendruiden durch einen heiligen Übergangsritus. Ihr sammelt Erdwurzeln und feste Kodohörner für eine Salbe zur Behandlung der vergifteten Gazellen des Brachlands.",h="Am Wegekreuz führt Tonga Runentotem junge Taurendruiden durch einen heiligen Übergangsritus.",kw={"brachland","das wegekreuz","druidenquest","erdwurzel","das heilmittel sammeln","gazelle","kodohorn","salbe","tonga runentotem"},ang={["class:Druid"]="Als Druide stellt Ihr Euch Prüfungen, die Euch lehren, über die sterbliche Kräuterkunst hinauszuwachsen und die Magie der Natur zu kanalisieren, um Gift direkt auszutreiben.",["faction:Horde"]="Als Mitglied der Horde helft Ihr Tonga, die Tierwelt rund um das Wegekreuz zu schützen und ein stabiles Ökosystem für den Außenposten im Kernland der Horde zu bewahren.",["profession:Herbalism"]="Als Kräuterkundiger kennt Ihr den Wert wild wachsender Heilwurzeln, die sich an den felsigen Hängen der Savanne sammeln lassen."},sec={{t="Ein Rezept zur Linderung",b="Tonga Runentotem braucht Zutaten für ein Gegengift auf Grundlage der Wasserprobe, die Ihr am Glutnebelgipfel gesichert habt. Erdwurzel verleiht der Salbe ihre heilenden Eigenschaften, während gemahlenes Kodohorn ihr die Kraft gibt, Gift aus dem Körper einer Kreatur zu treiben. Für einen jungen Druiden bedeutet das Sammeln dieser Zutaten, sich auf die Gaben der Erde zu verlassen und heimische Wildtiere zu jagen."},{t="Lehren der Reinigung",b="Während Tonga Runentotem die Salbe zubereitet, lehrt er die Grenzen physischer Heilmittel. Kräuterkunde und Alchemie können bestimmten Giftstoffen entgegenwirken, doch die meisten Gifte erfordern ein eigenes Heilmittel. Statt endlose Vorräte an Kräutern und Hörnern mitzuführen, lernen Druiden, sich auf die heilenden Energien der Natur einzustimmen. Diese Lehre führt zur druidischen Kunst Vergiftung heilen."}},faq={{q="Welche Zutaten benötigt Tonga Runentotem?",a="Tonga verlangt fünf Bündel Erdwurzeln und fünf unversehrte Kodohörner. Erdwurzel bringt heilende Eigenschaften mit, während die Hörner der Salbe Wirksamkeit gegen die Giftstoffe verleihen, die den heimischen Gazellen schaden.",al={"das heilmittel sammeln gegenstände","welche reagenzien werden benötigt","materialien für das heilmittel"}},{q="Wo sind die Kodohörner zu finden?",a="Kodos durchstreifen das nördliche und mittlere Brachland und grasen oft nahe den Straßen rund um das Wegekreuz. Tonga braucht ganze, feste Hörner für die Salbe, keine brüchigen Splitter.",al={"wo sind die kodos","kodohorn fundort","kodos im brachland finden"}},{q="Muss ich Kräuterkundiger sein, um Erdwurzeln zu beschaffen?",a="Nein, Ihr benötigt keine Kräuterkunde, um Erdwurzeln zu beschaffen. Kräuterkundige ernten sie an Klippen und Felsvorsprüngen im gesamten Brachland. Druiden, die sie nicht selbst sammeln können, erhalten sie von Mitreisenden oder an Handelsposten.",al={"ist kräuterkunde erforderlich","erdwurzeln ohne kräuterkunde sammeln","berufsvoraussetzung für erdwurzel"}},{q="Warum bereitet Tonga eine physische Salbe zu?",a="Tonga stellt ein physisches Gegengift für vergiftete Gazellen her, die im gesamten nördlichen Brachland leiden. Die sorgfältige Arbeit zeigt zugleich den Vorteil angeborener magischer Reinigungszauber.",al={"warum ein gegengift herstellen","zweck der salbe","warum keine magie verwenden"}},{q="Wer ist Tonga Runentotem?",a="Tonga Runentotem ist ein älterer Taurendruide am Wegekreuz im Brachland. Er untersucht die Verderbnis, die sich in den Wasserläufen der Region ausbreitet, und leitet junge Druiden an, das Gleichgewicht der Natur zu meistern.",al={"wer vergibt das heilmittel sammeln","tonga runentotems rolle","wer ist tonga"}},{q="Was folgt auf das Sammeln dieser Zutaten?",a="Nachdem Tonga die Salbe gebraut hat, schickt er Euch in die Savanne, um sie auf erkrankte Gazellen aufzutragen und das Heilmittel zu erproben. Dann lehrt er Euch die tiefere Kunst der magischen Reinigung.",al={"was folgt auf das heilmittel sammeln","das heilmittel sammeln folgequest","nach das heilmittel sammeln"}}},fx={["239606af"]={q="Warum möchte Tonga Runentotem diese Heilzutaten sammeln?",a="Tonga bemüht sich, die einheimische Gazellenpopulation des Brachlands zu retten, die einem gefährlichen Leiden erliegt. Die Tierwelt kann sich nicht von selbst erholen, was das natürliche Gleichgewicht der Ebenen bedroht. Durch die Kombination des Wassers, das vom Glutnebelgipfel entnommen wurde, mit starken wiederherstellenden Reagenzien beabsichtigt Tonga, eine Heilsalbe zu brauen, die in der Lage ist, die Krankheit zu stoppen, bevor weitere Herden zugrunde gehen.",al={"warum tonga runentotem helfen","tonga runentotem beweggrund","warum salbe herstellen"}},eb557efc={q="Wofür wird die Erdwurzel verwendet?",a="Die Erdwurzel liefert die wesentlichen Heileigenschaften für die Salbe. Tonga nutzt die natürliche Vitalität des widerstandsfähigen Krauts, um die Wasserbasis der Salbe mit der Kraft zu infundieren, die benötigt wird, um die betroffenen Gazellen zu beruhigen und das schwächende Gift abzuwehren.",al={"warum erdwurzel benötigt","zweck erdwurzel","erdwurzel salbe"}},["9baa8a2a"]={q="Wofür werden die Kodohörner verwendet?",a="Tonga benötigt robuste Kodohörner, um der Heilsalbe ausreichende Stärke zu verleihen. In die Mischung gemahlen, verleihen ganze und intakte Hörner der Medizin die Kraft, die benötigt wird, um aggressive Gifte wirksam zu bekämpfen.",al={"warum kodohörner benötigt","zweck kodohorn","kodohorn salbe"}}},fp="18,189,19.337.0,20.321.0,46.187.0,34.158.0,49.217.0,40.177.0,23.197.0,45.170.1"}
P.entries["quest:6129"] = {n="Heilung der Kranken",s="Kranke Gazellen leiden im gesamten nördlichen Brachland. Tonga Runentotem schickt junge Druiden der Horde aus, um sie mit einer frisch zubereiteten Kräutersalbe zu behandeln, und dann zum Zirkel des Cenarius in Mondlichtung.",h="Kranke Gazellen leiden im gesamten nördlichen Brachland.",kw={"brachland","zirkel des cenarius","das wegekreuz","heilende tiersalbe","gift heilen","heilung der kranken","dendrite sternenschauer","mondlichtung","kränkliche gazelle","tonga runentotem"},ang={["class:Druid"]="Für Euch als Druiden markiert dieser Heilungsritus den Übergang vom Kräuterkundeschüler zum aktiven Hüter der Natur. Er beweist, dass Ihr bereit seid, Lebensmagie gegen tödliche Gifte einzusetzen.",["faction:Horde"]="Indem Taurendruiden erkrankte Wildtiere nahe dem Wegekreuz behandeln, helfen sie, lebenswichtige Jagdgebiete und Reisewege zu schützen, die den Stützpunkt der Horde im zentralen Kalimdor sichern.",["race:Tauren"]="Während Euer Volk seine uralten Bande zum Zirkel des Cenarius erneuert, zeigt die Heilung des Brachlands, dass die Kinder der Earth Mother würdige Hüter des Gleichgewichts sind."},sec={{t="Eine Seuche unter Herden",b="Eine unnatürliche Krankheit breitet sich unter den Gazellen im nördlichen Brachland aus. Ihr habt Erdwurzeln und Kodohörner für ein Heilmittel gesammelt, und Tonga Runentotem am Wegekreuz vertraut die Tiere nun Eurer Fürsorge an. Sucht nördlich der Hauptkreuzung und versorgt zehn leidende Gazellen. Die Salbe verschafft ihnen Linderung, bevor das Leiden im Ökosystem tiefer Fuß fasst."},{t="Der Segen des Zirkels",b="Nachdem Ihr die Salbe aufgetragen habt, reist Ihr zum friedlichen Druidenheiligtum in Mondlichtung. Dendrite Sternenschauer erkennt dort Euer Mitgefühl und Eure Wachsamkeit an. Er sagt, das Leiden der Gazellen deute auf eine tiefere Verderbnis hin, die durch Kalimdors Wildnis schleicht. Indem Taurendruiden selbst die geringsten Tiere versorgen, zeigen sie, dass die Ehrfurcht vor Cenarius über Stammesgrenzen hinausreicht. Sie erlangen tiefere Geheimnisse der Giftreinigung und Naturmagie."}},faq={{q="Wo sind die kränklichen Gazellen zu finden?",a="Die erkrankten Gazellen durchstreifen die trockenen Ebenen des nördlichen Brachlands, hauptsächlich nördlich der großen Handelsstraße, die von Osten nach Westen durch das Wegekreuz verläuft.",al={"gazellen fundort","wo sind kranke gazellen","brachland gazellen"}},{q="Wer vergibt diese Quest?",a="Tonga Runentotem, ein Taurendruide am Wegekreuz im Brachland, gibt Euch diesen Auftrag und die Heilende Tiersalbe, nachdem Ihr die benötigten Reagenzien gesammelt habt.",al={"wer vergibt heilung der kranken","questgeber","tonga runentotem standort"}},{q="Bei wem muss ich mich nach der Heilung der Tiere melden?",a="Nachdem Ihr die Tiere geheilt habt, meldet Ihr Euch bei Dendrite Sternenschauer im Druidenheiligtum in Mondlichtung. Mit Eurer Teleportationsmagie erreicht Ihr den heiligen Hain.",al={"wo diese quest abgeben","quest abgeben","dendrite sternenschauer standort"}},{q="Warum interessiert sich der Zirkel des Cenarius für das Brachland?",a="Der Zirkel des Cenarius wacht über die Harmonie des Landes. Die Krankheit unter wilden Gazellen spiegelt die Verderbnis wider, die durch Kalimdor schleicht und ungehindert die natürliche Ordnung bedroht.",al={"warum dru hiden sich um das brachland kümmern","zirkel des cenarius brachland"}},{q="Welche Fähigkeit schaltet diese Questreihe frei?",a="Dieser Übergangsritus ist die zweite Hälfte einer druidischen Prüfung. Er verleiht Euch letztlich die Fähigkeit, Euch selbst und Eure Verbündeten von Giften und Giftstoffen zu reinigen.",al={"gift heilen questbelohnung","warum diese quest als druide machen"}},{q="Können auch Nichtdruiden diese Gazellen heilen?",a="Nein. Nur Druiden können diese Aufgaben übernehmen. Es ist eine Klassenprüfung unter direkter Aufsicht des Zirkels des Cenarius.",al={"nur für druiden","wer kann heilung der kranken machen"}}},fx={f2ed6f7d={q="Warum möchte Tonga Runentotem, dass Ihr die Gazellen heilt?",a="Eine sich ausbreitende Verderbnis verwüstet die Tierwelt im nördlichen Brachland und lässt die lokalen Gazellen an einer schwächenden Krankheit leiden. Tonga Runentotem hat eine Heilsalbe vorbereitet, um dem Unwohlsein entgegenzuwirken, aber die Natur kann nicht warten. Er braucht Euch, um den leidenden Tieren sofortige Linderung zu verschaffen und die Verseuchung einzudämmen, bevor sie einen tieferen Tribut für das fragile Gleichgewicht des Landes fordert.",al={"warum gazellen heilen","tonga runentotem beweggrund","warum kranke gazellen helfen"}},f6349169={q="Warum braucht Tonga Runentotem Euch, anstatt die Gazellen selbst zu heilen?",a="Tonga hat es nur geschafft, genug Salbe für zehn Dosen herzustellen und muss im Wegekreuz bleiben, um sich mit den lokalen Behörden abzustimmen und mehr vorzubereiten. Als angehender Druide, der auf dem Pfad des Cenarius wandelt, habt Ihr die Bindung zur Natur, die erforderlich ist, um die verstreuten, kranken Kreaturen aufzuspüren und das Heilmittel zu verabreichen, ohne ihnen weiteren Stress zu verursachen.",al={"warum ich tonga runentotem","warum braucht tonga hilfe","warum keine lokalen wachen"}}},fp="15,202,23.376.0,21.428.0,36.144.0,22.163.0,44.154.0,53.187.0,42.156.0,35.112.0"}
P.entries["quest:613"] = {n="Maurys Fuß aufbrechen",s="In Beutebucht kann MacKinley noch immer nicht einfordern, was Maury ihm schuldete. Maury schloss seine Schuld im eigenen Fuß ein, also schickt MacKinley Reisende zum Ogerhügel der Mosh'Ogg im Schlingendorntal, um den Schlüssel zu finden.",h="In Beutebucht kann MacKinley noch immer nicht einfordern, was Maury ihm schuldete.",kw={"beutebucht","schlüssel","mackinley","maury","mosh'ogg","oger","seewolf","schlingendorntal"},sec={{t="Ein verschlossener Schatz",b="Nachdem der Fuß in Voodoo Dues geborgen wurde, steht Seewolf MacKinley in Beutebucht vor einem weiteren Hindernis. Sein verstorbener Schuldner hat den Fuß verschlossen und die Wertsachen, die er ihm schuldet, darin eingeschlossen."},{t="Der Hügel der Oger",b="Maury spielte mit den Ogern am Ogerhügel der Mosh'Ogg nordöstlich von Beutebucht um Geld. MacKinley erinnert sich, dass Maury erzählte, sie hätten ihn vertrieben, nachdem er zu viel gewonnen hatte. Daher vermutet MacKinley, dass sie den Schlüssel haben, und schickt Euch auf die Suche danach."}},faq={{q="Warum braucht Seewolf MacKinley Maurys Schlüssel?",a="Maury schloss das, was er schuldete, im eigenen Fuß ein. MacKinley braucht den Schlüssel, um ihn zu öffnen und die Schuld einzutreiben.",al={"warum schlüssel nötig","wofür ist der schlüssel","maurys schlüssel zweck"}},{q="Wo wird Maurys Schlüssel vermutet?",a="MacKinley vermutet, dass die Oger der Mosh'Ogg den Schlüssel an ihrem Hügel nordöstlich von Beutebucht haben könnten.",al={"wo ist der schlüssel","fundort des schlüssels","wo maurys schlüssel finden"}},{q="Warum sollten die Oger der Mosh'Ogg den Schlüssel haben?",a="Maury spielte oft mit den Ogern der Mosh'Ogg um Geld. MacKinley erinnert sich, dass sie Maury nach einem großen Gewinn vertrieben, weshalb er vermutet, dass sie den Schlüssel haben könnten.",al={"warum haben die oger den schlüssel","verbindung zwischen maury und den ogern","kannte maury die oger"}},{q="Was geschieht davor bei MacKinleys Geschäften?",a="Das Eintreiben der Schulden in Voodoo Dues folgte auf Scaring Shaky und Return to MacKinley, als MacKinley Schulden rund um Beutebucht beglich.",al={"vorherige quest","reihenfolge der questreihe","was kommt zuerst"}}},fp="21,201,14.173.0,16.220.0,47.101.0,35.93.0,42.139.0,47.122.0"}
P.entries["quest:6130"] = {n="Macht über Gift",s="In Donnerfels kehrt ein junger Druide der Horde zurück, um die Gabe von Vergiftung heilen zu empfangen. Der Initiand hat vergiftete Gazellen nahe dem Wegekreuz mit Kräutermixturen behandelt und tritt nun vor Turak Runentotem auf der Anhöhe der Ältesten.",h="In Donnerfels kehrt ein junger Druide der Horde zurück, um die Gabe von Vergiftung heilen zu empfangen.",kw={"brachland","das wegekreuz","vergiftung heilen","dendrite sternenschauer","die anhöhe der ältesten","mondlichtung","donnerfels","turak runentotem"},ang={["class:Druid"]="Als Druide verbindet Ihr handwerkliche Kräuterkunde in Kalimdor mit Naturmagie und erlangt die dauerhafte Macht, Verbündete von Giften zu befreien.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Wildnis im Herzen Kalimdors vor unnatürlicher Verderbnis zu schützen.",["race:Tauren"]="Als Tauren beweist Ihr Eure Hingabe an den Zirkel des Cenarius und haltet die Weisheit der Earth Mother auf der Anhöhe der Ältesten lebendig."},sec={{t="Eine Lektion im Leiden",b="Der Zirkel des Cenarius verlangt von einem Druiden, Leiden kennenzulernen, bevor er ihm die Macht verleiht, Gift zu heilen. Dendrite Sternenschauer schickt den Novizen zum Wegekreuz, wo Tonga Runentotem ihn Zutaten für eine Salbe sammeln lässt. Indem der Druide die vergifteten Gazellen des Brachlands von Hand und ohne spirituelle Hilfe behandelt, sieht er gewöhnliche Geschöpfe gegen natürliche und unnatürliche Gifte kämpfen."},{t="Rückkehr zur Anhöhe der Ältesten",b="Nach der Prüfung schickt Dendrite den Initianden zu Turak Runentotem, dem Großdruidenlehrer auf der Anhöhe der Ältesten in Donnerfels. Turak warnt, dass seltsame, hochwirksame Gifte nahe dem Wegekreuz das natürliche Gleichgewicht der Ebenen bedrohen. Er lobt die Gelassenheit des Initianden unter Druck und verleiht ihm die spirituelle Kunst des Giftheilens. Die lebenden Geschöpfe Kalimdors stehen nun in der Obhut des Initianden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Die Prüfung lehrt einen Druiden der Horde, Gift zu heilen. Nachdem der Initiand von Hand Heilmittel zubereitet hat, um leidende Gazellen zu retten, kehrt er zu Turak Runentotem zurück und erlernt durch druidische Zwiesprache Vergiftung heilen.",al={"warum macht über gift abschließen","was bewirkt diese quest","zweck der giftquest für druiden"}},{q="Wo befindet sich Turak Runentotem?",a="Turak Runentotem lebt oben auf der Anhöhe der Ältesten in Donnerfels. Er wohnt im Zelt und den ausgehöhlten Ruhestätten, wo Taurendruiden Zwiesprache halten und sich ausbilden lassen.",al={"turak runentotem standort","wo ist turak","turak runentotem finden"}},{q="Wer schickt den Druiden nach Donnerfels zurück?",a="Dendrite Sternenschauer schickt den Druiden nach Donnerfels zurück, nachdem dieser Wildtiere nahe dem Wegekreuz geheilt hat. Der Nachtelfendruide des Zirkels des Cenarius ist in der Mondlichtung stationiert.",al={"wer vergibt macht über gift","questgeber","dendrite sternenschauer"}},{q="Warum ließ der Zirkel des Cenarius den Druiden zunächst Tiere von Hand heilen?",a="Dendrite Sternenschauer lehrt den Druiden, den Aufwand und die Grenzen des Giftheilens zu verstehen, bevor er spirituelle Magie einsetzt. Leidende Geschöpfe kämpfen zu sehen, lehrt Mitgefühl und Achtung vor dem Gleichgewicht der Natur.",al={"warum kranke von hand heilen","warum zuerst salben verwenden","giftlektion für druiden"}},{q="Was beunruhigt Turak Runentotem am Wegekreuz?",a="Turak warnt, dass unnatürliche, aggressive Gifte die Wildtiere nahe dem Wegekreuz erreichen. Er sieht darin eine schwere Störung des Gleichgewichts des Landes, die Wachsamkeit erfordert.",al={"turaks sorge um das wegekreuz","wegekreuz gift gleichgewicht"}},{q="Ist diese Quest für Druiden der Allianz verfügbar?",a="Druiden der Allianz durchlaufen eine vergleichbare Prüfung gleichen Namens. Nachtelfische Initianden kehren zu Mathrengyl Bärenfährte in Darnassus zurück statt zu Turak Runentotem auf der Anhöhe der Ältesten.",al={"können nachtelfen dies machen","allianz macht über gift"}}},fp="17,212,21.384.0,24.381.0,34.197.0,33.141.0,42.172.0,70.206.0,51.171.0,43.166.0"}
P.entries["quest:6132"] = {n="Holt mich hier raus!",s="Im Tal der Speere fürchtet Melizza Brimbuzzle, dass die Maraudine sie fressen wollen. Sie bittet Euch, sie herauszuholen, und ihr Bruder Hornizz verspricht gute Bezahlung.",h="Im Tal der Speere fürchtet Melizza Brimbuzzle, dass die Maraudine sie fressen wollen.",kw={"zentaur","desolace","hornizz brimbuzzle","der kodofriedhof","maraudine","melizza brimbuzzle","das tal der speere"},sec={{t="Ärger im Tal",b="Melizza Brimbuzzle kam ins Tal der Speere und hoffte, mit den Maraudine ein Geschäft abzuschließen. Sie wollten nicht reden, und nun fürchtet sie, dass sie sie fressen wollen. Vor wenigen Minuten belauschte sie Zentauren, die über Holz für ihren Kochtopf sprachen. Sie will schnell fort."},{t="Das Lager ihres Bruders",b="Hornizz Brimbuzzle wartet im Lager der Familie östlich von Melizzas derzeitigem Aufenthaltsort. Es liegt neben dem Kodofriedhof. Melizza verspricht, dass ihr Bruder Euch gut bezahlen wird, wenn Ihr sie aus dem Tal bringt."},{t="Zurück im Lager",b="Hornizz sagt, Melizza habe ihm erzählt, dass Ihr kommen würdet. Er dankt Euch, dass Ihr ihr aus der Patsche geholfen habt, und vermutet dann, dass sie schon wieder in der nächsten steckt. Melizza eilt voraus und sagt, mit den Maraudine lasse sich nur schwer zusammenarbeiten. Sie macht sich zu den Gelkis auf, die sie als vernünftiger bezeichnet."}},faq={{q="Warum steckt Melizza Brimbuzzle in Schwierigkeiten?",a="Melizza ging ins Tal der Speere und hoffte, mit den Maraudine Geschäfte zu machen. Sie wollten nicht reden, und sie fürchtet, dass sie sie fressen wollen.",al={"warum ist melizza gefangen","melizza brimbuzzles geschichte","was ist mit melizza passiert"}},{q="Wer sind die Maraudine?",a="Die Maraudine sind Zentauren aus Desolace. Melizza ging ins Tal der Speere und hoffte, mit ihnen Geschäfte zu machen.",al={"maraudine zentaur","wer sind die maraudine","klan der maraudine"}},{q="Wo befindet sich Hornizz Brimbuzzle?",a="Hornizz Brimbuzzle wartet im Lager der Brimbuzzles in Desolace, neben dem Kodofriedhof und östlich von Melizzas derzeitigem Aufenthaltsort.",al={"hornizz aufenthaltsort","wo ist hornizz","hornizz brimbuzzles lager"}},{q="Warum sagt Melizza, dass ihr Bruder Euch bezahlen wird?",a="Melizza verspricht, dass ihr Bruder Hornizz Euch gut bezahlen wird, wenn Ihr sie aus dem Tal holt.",al={"melizzas belohnung","was zahlt hornizz"}}},fp="19,153,21.252.0,18.197.0,16.275.1,37.136.0,23.110.0,36.128.0,46.88.0"}
P.entries["quest:6134"] = {n="Geisterplasmasuche",s="Hornizz Brimbuzzle schickt Euch ins Tal der Knochen, um Geisterenergie zu sammeln, für die die Magram hoffentlich gut zahlen.",h="Hornizz Brimbuzzle schickt Euch ins Tal der Knochen, um Geisterenergie zu sammeln, für die die Magram...",kw={"dead goliaths","desolace","geistermagnet","ghost-o-plasm","hornizz brimbuzzle","magram","gespenster","tal der knochen"},sec={{t="Ein verwunschenes Tal",b="Hornizz Brimbuzzle schickt Euch nach Südosten ins Tal der Knochen, wo Magram-Geister wandeln. Das Tal klingt für ihn beängstigend. Doch er glaubt, dass die Geister den Magram noch mehr Angst einjagen müssen, und ist sicher, dass die Zentauren für dort eingefangene Geisterenergie gut zahlen würden."},{t="Zwischen den Dead Goliaths",b="Hornizz Brimbuzzle gibt Euch eine Kiste mit Geistermagneten. Stellt einen zwischen den beiden riesigen Skeletten namens Dead Goliaths auf, und er lockt die Geister an. Die Geister liefern Ghost-o-plasm, das Hornizz an die Magram verkaufen will. Er bittet Euch, ihm acht Portionen Ghost-o-plasm und die Kiste zu bringen."},{t="Zurück mit der Beute",b="Als Ihr zurückkehrt, sieht Hornizz Brimbuzzle, dass Ghost-o-plasm auf Euch abgefärbt hat, und nennt es schleimig. Er meint, damit ließe sich ein Vermögen machen, wenn sich die Zentauren davon überzeugen lassen, worum es sich handelt."}},faq={{q="Wer ist Hornizz Brimbuzzle?",a="Hornizz Brimbuzzle unterhält ein Lager südwestlich des Kodofriedhofs in Desolace. Er will Geisterenergie an die Magram-Zentauren verkaufen.",al={"hornizz","brimbuzzle","wer vergibt geisterplasmasuche"}},{q="Wo liegt das Tal der Knochen?",a="Das Tal der Knochen liegt südöstlich von Hornizz Brimbuzzle. Die beiden Dead Goliaths stehen am südlichen Ende des Tals. Es sind die riesigen Skelette, bei denen Ihr den Magneten aufstellt.",al={"tal der knochen lage","wo sind die geister","dead goliaths lage"}},{q="Warum will Hornizz Ghost-o-plasm?",a="Hornizz Brimbuzzle glaubt, dass die Magram-Zentauren für Geisterenergie aus dem verwunschenen Tal der Knochen gut zahlen werden. Er plant, ihnen Ghost-o-plasm zu verkaufen.",al={"warum geisterenergie sammeln","wer kauft ghost-o-plasm","zentauren geisterplasma"}},{q="Wie funktioniert der Geistermagnet?",a="Stellt einen Geistermagneten zwischen den beiden Dead Goliaths auf, und er lockt die Geister des Tals an. Die Geister liefern Ghost-o-plasm.",al={"geistermagnet verwenden","wo geistermagnet aufstellen","magram-geister anlocken"}}},fp="22,111,16.264.0,25.291.0,18.172.1,26.130.0,29.170.0,36.156.0,31.126.0"}
P.entries["quest:6141"] = {n="Bruder Anton",s="Auf der Nijelspitze sucht Bruder Anton Hilfe gegen die Untoten in Desolace. Er kam aus fernen Landen, nachdem er von der Bedrohung gehört hatte.",h="Auf der Nijelspitze sucht Bruder Anton Hilfe gegen die Untoten in Desolace.",kw={"bruder anton","bruder crowley","desolace","die nijelspitze","scharlachrot","untoter"},sec={{t="Ein Bruder in der Fremde",b="Gerüchte über Untote in Desolace erreichten Bruder Anton im fernen Kalimdor. Er buchte sofort eine Überfahrt, um sie aufzuspüren und zu vernichten. Nun sucht er nach Leuten mit Mut und Entschlossenheit. Wenn Euer Herz aufrichtig ist, schickt Bruder Crowley Euch zu ihm auf die Nijelspitze, die Stadt der Allianz in Desolace."},{t="Nachricht aus dem Osten",b="Bruder Anton hat gehört, dass Hilfe aus dem Osten kommt. Er fragt, ob Ihr diese Gerüchte mitgebracht habt und ob Ihr gekommen seid, um beim Kreuzzug des Scharlachroten Bruders zu helfen."}},faq={{q="Wer ist Bruder Anton?",a="Bruder Anton ist Bruder Crowleys Waffenbruder. Als er hörte, dass Untote Desolace heimsuchten, buchte er eine Überfahrt dorthin, um sie zu vernichten.",al={"wer ist anton","bruder anton geschichte","anton desolace"}},{q="Wo ist Bruder Anton zu finden?",a="Bruder Anton ist auf der Nijelspitze zu finden, der Stadt der Allianz in Desolace.",al={"wo ist bruder anton","anton aufenthaltsort","bruder anton fundort"}},{q="Warum ging Bruder Anton nach Kalimdor?",a="Gerüchte über Untote in Desolace in Kalimdor erreichten Bruder Anton. Er buchte sofort eine Überfahrt, um sie zu vernichten.",al={"warum ist anton in desolace","anton mission desolace","warum reiste anton"}}},fp="13,130,16.292.0,18.168.1,21.138.0,33.75.0,37.108.0"}
P.entries["quest:6142"] = {n="Muschelköder",s="In Schattenflucht vertraut Mail'Lahii einem Köder mehr als allen anderen. Er bittet um zehn Stücke weichschaliges Muschelfleisch von dem Schiffswrack weiter nördlich an der Küste.",h="In Schattenflucht vertraut Mail'Lahii einem Köder mehr als allen anderen.",kw={"muschelköder","desolace","angelköder","mail'lahii","schattenflucht","schiffswrack","weichschalige muschel"},sec={{t="Der beste Köder",b="Mail'Lahii bittet Euch um einen Köder, dem Fische nicht widerstehen können. Er hat sein ganzes Leben lang geangelt und vertraut weichschaligem Muschelfleisch mehr als allem anderen. Nördlich von Schattenflucht liegt ein Schiffswrack vor der Küste, und im ganzen Gebiet sind weichschalige Muscheln verstreut. Er möchte zehn Stücke des Fleisches."},{t="Was Mail'Lahii sagt",b="Mail'Lahii sagt, der Hexendoktor habe ihm geraten, gegen seine Kopfschmerzen angeln zu gehen, dann würde es ihm besser gehen. Er fühlt sich bereits besser."}},faq={{q="Wer ist Mail'Lahii?",a="Mail'Lahii ist ein Fischer in Schattenflucht an der Küste von Desolace. Sie hat ihr ganzes Leben lang geangelt.",al={"mailahii","wer bittet um muschelköder","fischer in schattenflucht"}},{q="Wo sind die weichschaligen Muscheln zu finden?",a="Weichschalige Muscheln liegen verstreut um ein Schiffswrack nördlich von Schattenflucht vor der Küste.",al={"muschelköder fundort","wo ist das schiffswrack","weichschaliges muschelfleisch fundort"}},{q="Warum möchte Mail'Lahii Muschelfleisch?",a="Mail'Lahii sagt, weichschaliges Muschelfleisch sei der beste Köder, und Fische könnten ihm nicht widerstehen.",al={"warum muschelköder","warum muschelfleisch"}},{q="Wie viel Muschelfleisch möchte Mail'Lahii?",a="Mail'Lahii möchte zehn Stücke weichschaliges Muschelfleisch.",al={"wie viele muscheln","muschelfleisch menge"}}},fp="9,160,13.279.0,19.127.1,17.98.0,42.98.0,34.82.0,39.53.0"}
P.entries["quest:6143"] = {n="Andere Fische zu grillen",s="In Schattenflucht bittet Euch Drulzegar Skraghook, gegen die Slitherblade zurückzuschlagen. Naga überfielen die Fischer nahe der Insel Ranazjar, und nur Drulzegar kehrte zurück.",h="In Schattenflucht bittet Euch Drulzegar Skraghook, gegen die Slitherblade zurückzuschlagen.",kw={"desolace","drulzegar","myrmidone","naga","andere fische zu grillen","die insel ranazjar","schattenflucht","skraghook","slitherblade","zauberin"},sec={{t="Eine verlorene Besatzung",b="Drulzegar Skraghook und die Besatzung fischten oft nahe der Insel Ranazjar. Die Insel liegt nördlich eines Wracks an der Küste. Eines Morgens griffen die Naga an und töteten alle außer Drulzegar. Nun erfüllen Rachegedanken Drulzegars Sinn, und die Schuldgefühle sind unerträglich."},{t="Die Naga grillen",b="Drulzegar bittet Euch, sieben Slitherblade Myrmidons, sieben Slitherblade Naga und fünf Slitherblade Sorceresses zu töten. Ein lädiertes Knie hindert Drulzegar daran, Euch zu begleiten. Die Naga lauern gewöhnlich tief unten zwischen Korallenriffen unter den Wellen, sagt Drulzegar. Eure Mühe wird belohnt werden."}},faq={{q="Wer ist Drulzegar Skraghook?",a="Drulzegar Skraghook ist ein Fischer in Schattenflucht in Desolace. Die Naga töteten die gesamte Besatzung nahe der Insel Ranazjar, und nur Drulzegar überlebte.",al={"drulzegar","drulzegar skraghook","wer vergibt andere fische zu grillen"}},{q="Wo wurde Drulzegars Besatzung angegriffen?",a="Die Naga griffen bei der Insel Ranazjar an, nördlich eines Wracks an der Küste. Die Besatzung fischte dort oft, und der Angriff erfolgte eines Morgens.",al={"wo wurden die fischer angegriffen","angriffsort der besatzung","hinterhalt bei der insel ranazjar"}},{q="Warum bekämpft Drulzegar die Naga nicht selbst?",a="Ein lädiertes Knie hindert Drulzegar daran, die Naga zu bekämpfen. Drulzegar sagt, er würde Euch helfen, sie zu töten, wenn die Verletzung nicht wäre. Schuldgefühle wegen der Besatzung lasten schwer auf Drulzegars Gewissen.",al={"warum kann drulzegar nicht kämpfen","drulzegars lädiertes knie"}},{q="Wo lauern die Naga der Slitherblade?",a="Drulzegar sagt, die Naga der Slitherblade lauern gewöhnlich tief unten zwischen Korallenriffen unter den Wellen. Die Besatzung wurde nahe der Insel Ranazjar angegriffen.",al={"aufenthaltsort der slitherblade","wo sind naga der slitherblade zu finden","aufenthaltsort der naga in desolace"}},{q="Welche Naga will Drulzegar beseitigt sehen?",a="Drulzegar will sieben Slitherblade Myrmidons, sieben Slitherblade Naga und fünf Slitherblade Sorceresses getötet sehen.",al={"welche naga müssen getötet werden","ziele für andere fische zu grillen","anforderungen für slitherblade"}}},fp="17,164,11.247.0,12.274.0,27.160.0,48.132.0,45.180.0,36.137.0,42.110.0"}
P.entries["quest:616"] = {n="Die Spukinsel",s="In Beutebucht hört Krazek von einer Insel, auf der ein Goblingeist spukt. Er sammelt ungewöhnliche Gerüchte für Baron Revilgaz, und dieses erinnert an eine alte Trolllegende.",h="In Beutebucht hört Krazek von einer Insel, auf der ein Goblingeist spukt.",kw={"baron revilgaz","beutebucht","goblingeist","krazek","stein der gezeiten","schlingendorntal","trolllegende","wasserelementare"},sec={{t="Tavernengeschichten in Beutebucht",b="Krazek sammelt für Baron Revilgaz Berichte über seltsame Geschehnisse im ganzen Schlingendorntal. In einer Taverne in Beutebucht erzählen ihm Seeleute von einer Insel vor der Küste, auf der Wasserelementare hausen. Sie sagen, der Geist eines rasenden Goblins gehe dort um. Krazek schenkt Geistergerüchten wenig Beachtung, doch diese Geschichte weckt seine Aufmerksamkeit. Er bittet Euch, sie dem Baron zu überbringen."},{t="Eine Trolllegende",b="Baron Revilgaz erinnert sich an eine alte Trolllegende aus einem Buch, als er Krazeks Bericht hört. Die Wasserelementare und die Goblinerscheinung lassen ihn vermuten, dass der Stein der Gezeiten in greifbarer Nähe sein könnte. Er hofft, das uralte Relikt seiner persönlichen Artefaktsammlung hinzuzufügen."}},faq={{q="Wer schickt Euch zu Baron Revilgaz?",a="Krazek bittet Euch, Baron Revilgaz das Gerücht zu überbringen, nachdem er Seeleute in einer Taverne in Beutebucht eine beunruhigende Geschichte erzählen hörte.",al={"wer vergibt die spukinsel","spukinsel questgeber","krazeks gerücht"}},{q="Welche Gerüchte erzählten die Seeleute?",a="Die Seeleute erzählen von einer Insel vor der Küste, auf der Wasserelementare hausen und der Geist eines rasenden Goblins umgeht.",al={"was ist auf der insel","gerücht über die spukinsel","seemannsgeschichten"}},{q="Warum interessiert sich Baron Revilgaz für eine Geistergeschichte?",a="Baron Revilgaz erinnert sich an eine alte Trolllegende aus einem Buch. Die Berichte deuten darauf hin, dass sich der uralte Stein der Gezeiten auf der Insel befinden könnte.",al={"warum revilgaz es wissen will","revilgaz' reaktion","interesse am stein der gezeiten"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Baron Revilgaz verweist Euch auf den Stein der Gezeiten und führt damit die Suche weiter.",al={"welche quest kommt als nächstes","folgequest der spukinsel","nächster schritt nach der spukinsel"}}},fp="16,159,25.358.0,14.275.0,43.121.0,34.114.0,49.133.0,40.86.0"}
P.entries["quest:6161"] = {n="Nehmt Rackmores Schatz!",s="Bei „Nehmt Rackmores Schatz!“ berichtet Rackmores Logbuch von einem Schiff, das auf dem Weg zur Mondfederfeste angegriffen wurde. Er versteckte seine Schatztruhe auf der Insel Ranazjar, um sie vor seinen Feinden zu schützen, doch beide Schlüssel zum Öffnen gingen verloren.",h="Bei „Nehmt Rackmores Schatz!“ berichtet Rackmores Logbuch von einem Schiff, das auf dem Weg zur...",kw={"truhe","desolace","mondfederfeste","goldener schlüssel","rackmore","die insel ranazjar","silberner schlüssel"},sec={{t="Eine verborgene Truhe",b="Rackmores Logbuch berichtet von seefahrenden Kreaturen, die sein Schiff auf dem Weg zur Mondfederfeste angriffen. Er versteckte seine Schatztruhe auf der Insel Ranazjar, um sie vor seinen Feinden zu schützen. Beide Schlüssel, die zum Öffnen benötigt werden, gingen verloren, einer aus Silber und einer aus Gold. Wer die Schlüssel und die Truhe findet, wird einen Schatz finden."}},faq={{q="Wohin segelte Rackmores Schiff, als es angegriffen wurde?",a="Rackmores Schiff war auf dem Weg zur Mondfederfeste, als seefahrende Kreaturen es angriffen.",al={"rackmores ziel","wohin wollte rackmore","rackmores schiffsroute"}},{q="Wo ist Rackmores Truhe versteckt?",a="Rackmore versteckte die Truhe auf der Insel Ranazjar.",al={"wo ist rackmores truhe","rackmores truhenversteck","truhe auf der insel ranazjar"}},{q="Was wird benötigt, um die Truhe aufzuschließen?",a="Zum Öffnen der Truhe werden zwei Schlüssel benötigt, einer aus Silber und einer aus Gold. Beide gingen verloren.",al={"schlüssel zu rackmores truhe","wie öffnet man rackmores truhe","was öffnet rackmores truhe"}},{q="Warum versteckte Rackmore seinen Schatz?",a="Rackmore versteckte die Truhe auf der Insel Ranazjar, um seinen Schatz vor seinen Feinden zu schützen, nachdem seefahrende Kreaturen sein Schiff angegriffen hatten.",al={"warum rackmores schatz verstecken","rackmores beweggrund für das schatzversteck"}}},fp="26,220,14.295.0,55.94.0,33.40.0,35.79.0,35.122.0"}
P.entries["quest:617"] = {n="Bündelweise Akiris",s="In Beutebucht sucht Freibeuter Bloads Akirisschilf für einen Geschäftspartner, der gut zahlt. Die Naga wurden zuletzt am nördlichen Strand gesichtet, wo Ihr ihnen das Schilf abnehmen müsst.",h="In Beutebucht sucht Freibeuter Bloads Akirisschilf für einen Geschäftspartner, der gut zahlt.",kw={"akirisschilf","beutebucht","groy","naga","freibeuter bloads","schilf","schlingendorntal"},sec={{t="Eine einträgliche Meerespflanze",b="Freibeuter Bloads bietet in Beutebucht Arbeit am Meer an. Sein Geschäftspartner Groy zahlt gut für Bündel aus Akirisschilf, einer Pflanze, die am Meer wächst und den Namen trägt, den die Naga ihr geben. Bloads weiß nicht, warum Groy das Schilf haben möchte. Er braucht zehn Stängel, und die Naga wurden zuletzt am nördlichen Strand gesichtet."}},faq={{q="Wer ist Freibeuter Bloads?",a="Freibeuter Bloads ist ein Freibeuter in Beutebucht, der allen Arbeit anbietet, die danach fragen.",al={"bloads","wer vergibt bündelweise akiris","wer ist bloads"}},{q="Was ist Akirisschilf?",a="Akirisschilf ist eine wertvolle Meerespflanze, die von den Naga so genannt wird. Freibeuter Bloads weiß nicht, wozu sie dient, aber Sammler zahlen gut für Bündel ihrer Stängel.",al={"akirisschilf","was ist akirisschilf","wofür wird akiris verwendet"}},{q="Wo sind die Naga zu finden, die das Schilf haben?",a="Die Naga mit den Stängeln streifen an der Küste nördlich von Beutebucht umher, entlang der Strände des Schlingendorntals.",al={"wo sind die naga","wo gibt es akirisschilf","akirisschilf fundort"}},{q="Wer kauft Freibeuter Bloads das Schilf ab?",a="Bloads sammelt die Bündel für einen Geschäftspartner namens Groy, der mit dem Verkauf des Meeresschilfs einen beträchtlichen Gewinn erzielt.",al={"wer ist groy","wer will akirisschilf","bloads käufer"}}},fp="20,169,24.293.0,24.78.0,23.161.0,46.105.0,41.114.0"}
P.entries["quest:618"] = {n="Negolash entgegentreten",s="An der Küste des Schlingendorntals setzt ein gestohlener Krummsäbel Ereignisse in Gang. Sprogger weiß, wie er Negolash mit den Lieblingsspeisen und -getränken des Riesen hervorlocken kann.",h="An der Küste des Schlingendorntals setzt ein gestohlener Krummsäbel Ereignisse in Gang.",kw={"ödland","bussardflügel","kapitän smotts","dschungelrankenwein","negolash","smotts' krummsäbel","sprogger","schlingendorntal"},ang={["profession:Cooking"]="Als Koch könnt Ihr Sproggers Handwerk würdigen. Er reiste ins Ödland, um das besondere Rezept für Barbecued Buzzard Wings zu lernen, das im Mittelpunkt seines Plans steht."},sec={{t="Ein hungriger Riese",b="Als Riesen das Schiff von Kapitän Smotts zerstörten, steuerte Negolash die Kombüse an. Er ließ die Mannschaft in Ruhe und machte sich über Wein und Barbecued Buzzard Wings her, Sproggers Spezialität. Sprogger war ins Ödland gereist, um das Rezept zu lernen."},{t="Die Falle im Rettungsboot",b="Sprogger plant, Negolash mit einem Festmahl anzulocken. Ihr bringt zehn Portionen Flügel und fünf Flaschen Wein zum zerstörten Rettungsboot von Kapitän Smotts an der südöstlichen Küste. Das Festmahl lockt den Riesen herbei. Dann könnt Ihr ihm entgegentreten und den Krummsäbel des Kapitäns zurückholen."}},faq={{q="Wer ist Negolash?",a="Negolash ist ein Riese, der an der Zerstörung des Schiffs von Kapitän Smotts beteiligt war. Er plünderte die Kombüse nach Speisen und Getränken, statt die Seeleute zu jagen.",al={"was ist negolash","wer ist der riese","negolash geschichte"}},{q="Woher weiß Sprogger, wie man Negolash anlockt?",a="Sprogger sah, wie Negolash beim Schiffbruch seine Küche plünderte. Der Riese bevorzugte Sproggers Barbecued Buzzard Wings und Flaschen mit Dschungelrankenwein, weshalb sich diese Vorräte als Köder eignen.",al={"wie negolash anlocken","warum bussardflügel","negolash essen"}},{q="Wo findet die Konfrontation statt?",a="Die Konfrontation findet im zerstörten Rettungsboot von Kapitän Smotts statt, das südöstlich von Sprogger an der Küste gestrandet ist.",al={"wo ist negolash","wo das essen platzieren","rettungsboot fundort"}},{q="Was ging dieser Aufgabe voraus?",a="Die Spur beginnt mit The Monogrammed Sash und führt über The Captain's Cutlass zu dieser Konfrontation.",al={"welche quest kommt zuerst","negolash entgegentreten vorherige quest","voraussetzungen für negolash"}}},fp="15,155,14.228.0,24.259.0,16.133.0,44.185.0,40.110.0,27.113.0"}
P.entries["quest:6181"] = {n="Eine eilige Nachricht",s="Rüstmeister Lewis braucht Rüstungen für Westfalls Miliz und schickt per Greif eine dringende Nachricht nach Sturmwind. Da die Streitkräfte des Königreichs kaum helfen, bittet er Euch, die Anforderung zu Thor an der Späherkuppe zu bringen, für den Flug in die Hauptstadt.",h="Rüstmeister Lewis braucht Rüstungen für Westfalls Miliz und schickt per Greif eine dringende Nachricht nach...",kw={"rüstung","flugmeister","greif","die altstadt","osric strang","volksmiliz","rüstmeister lewis","späherkuppe","sturmwind","thor"},ang={["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr die Spannungen zwischen der Hauptstadt Sturmwind und den bedrängten Grenzvorposten in Westfall.",["race:Human"]="Als Mensch aus dem Königreich tragt Ihr Lewis' Nachricht, während Sturmwinds Provinzen unter Druck stehen. Ihr lernt außerdem die Greifenrouten kennen, die die Gebiete des Königreichs verbinden."},sec={{t="Ein Hilferuf am Himmel",b="An der Späherkuppe stellt sich die Volksmiliz Defias-Gesetzlosen und Gnollen entgegen und erhält dabei kaum Hilfe von Sturmwinds Streitkräften. Rüstmeister Lewis verlässt sich für Waffen und Rüstungen auf private Kontakte in der Hauptstadt. Als die Vorräte der Miliz zur Neige gehen, wendet er sich an Osric Strang, einen Rüstungsschmied in der Altstadt. Lewis bittet Reisende, das dringende Anforderungsschreiben zu Thor zu bringen, Westfalls Greifenmeister."},{t="Das Flugnetz",b="Greifen befördern Menschen und Nachrichten rasch durch das Königreich Sturmwind. Thor betreut die Flugroute von der Späherkuppe in die Hauptstadt. Wenn Ihr ihm Lewis' Nachricht übergebt, bringt er die Anforderung auf dem Luftweg nach Sturmwind. Diese Route verbindet Westfalls Grenzgarnison trotz fehlender offizieller Hilfe mit der Hauptstadt."}},faq={{q="Warum muss Rüstmeister Lewis eine Nachricht nach Sturmwind schicken?",a="Sturmwind leistet Westfall kaum direkte militärische Hilfe, und der Volksmiliz gehen die Rüstungen aus. Lewis schickt eine Anforderung an Osric Strang, einen vertrauenswürdigen Rüstungsschmied in der Stadt, um Nachschub zu sichern.",al={"warum nachricht schicken","zweck von lewis' nachricht","warum sturmwind kontaktieren"}},{q="Wer ist Osric Strang?",a="Osric Strang ist ein Rüstungsschmied in Sturmwinds Altstadt, dessen Laden Limited Immunity heißt. Er versorgt Lewis privat, wenn die offiziellen Wege versagen.",al={"osric strang","wer ist osric","besitzer von limited immunity"}},{q="Wer ist Thor?",a="Thor ist der Greifenmeister an der Späherkuppe. Er befördert Lewis' Nachricht zwischen Westfall und Sturmwind und betreut die Greifenflüge, die beide verbinden.",al={"wer ist thor","flugmeister westfall","thor greifenmeister"}},{q="Warum schickt Sturmwind nicht direkt Soldaten und Ausrüstung nach Westfall?",a="König Varian Wrynn wird vermisst, und Sturmwinds Mittel sind knapp. Die Führung hat die abgelegenen Agrargebiete weitgehend vernachlässigt, sodass Orte wie die Späherkuppe auf freiwillige Milizen und private Absprachen angewiesen sind.",al={"warum keine hilfe aus sturmwind","warum ignoriert sturmwind westfall","wo ist die armee"}},{q="Kann jeder Abenteurer diese Aufgabe übernehmen?",a="Jeder Abenteurer der Allianz kann sie übernehmen. Abenteurern, die sich in Westfall bewährt haben, wird diese Arbeit anvertraut. Sie macht mit den Greifenrouten des Königreichs vertraut.",al={"wer kann diese quest annehmen","quest nur für menschen","können zwerge diese quest machen"}},{q="Wohin führt diese Kuriermission als Nächstes?",a="Nachdem Ihr Thor die Nachricht übergeben habt, bereitet er einen Greifenflug nach Sturmwind vor. Ihr landet am Greifenhorst der Hauptstadt und sucht dann Osric Strang in der Altstadt auf.",al={"nächster schritt","was passiert nach thor","wohin geht es als nächstes"}}},fx={be76534e={q="Warum bittet Rüstmeister Lewis Euch, seine Nachricht zu überbringen?",a="Die Verteidiger von Westfall sind überstrapaziert, von der Krone verlassen und werden von Defias-Banditen in den Ebenen belagert. Rüstmeister Lewis kann das Versorgungslager der Späherkuppe nicht aufgeben, und die Leute der Miliz können keine vereidigten Verteidiger entbehren, um als einfache Boten zu dienen, wenn jede Klinge an der Wachtlinie benötigt wird. Ein fähiger Reisender, der sich in Richtung der Hauptstadt bewegt, bietet den schnellsten, sichersten Weg, um lebenswichtige Vorräte zu arrangieren, ohne den Außenposten unterbesetzt zu lassen.",al={"warum braucht lewis mich","warum keine wache nach sturmwind schicken","warum lewis nachricht überbringen"}}},fp="15,244,23.376.0,18.312.0,62.196.0,20.146.0,12.149.0,67.224.0,39.164.0,42.155.0"}
P.entries["quest:619"] = {n="Negolash anlocken",s="An der Küste des Schlingendorntals bietet ein gekennzeichnetes Rettungsboot eine Möglichkeit, Negolash anzulocken. Zehn Barbecued Buzzard Wings und fünf Flaschen Dschungelrankenwein liegen auf dem Wrack.",h="An der Küste des Schlingendorntals bietet ein gekennzeichnetes Rettungsboot eine Möglichkeit, Negolash...",kw={"barbecued buzzard wing","dschungelrankenwein","negolash","ruined lifeboat","smotts revenge","schlingendorntal"},sec={{t="Eine verlockende Gabe",b="Das verlassene Rettungsboot trägt die verblassten Worte Smotts' Revenge. Während Ihr Negolash jagt, legt zehn Barbecued Buzzard Wings und fünf Flaschen Dschungelrankenwein auf das Wrack, um ihn hervorzulocken."}},faq={{q="Was ist das Ruined Lifeboat?",a="Das Ruined Lifeboat ist ein verlassenes, beschädigtes Boot mit den verblassten Worten Smotts' Revenge. Dort könnt Ihr Essen und Getränke anrichten, um Negolash anzulocken.",al={"smotts revenge boot","rettungsboot strangletorn","was ist smotts revenge"}},{q="Welche Vorräte werden für die Gabe benötigt?",a="Für die Gabe werden zehn Barbecued Buzzard Wings und fünf Flaschen Dschungelrankenwein benötigt, die auf dem Wrack aufgeschichtet werden.",al={"welches essen wird benötigt","negolash anlocken gegenstände","welche gegenstände für negolash"}},{q="Wann wird diese Aufgabe verfügbar?",a="Ihr könnt die Gabe nur vorbereiten, während Ihr Negolash jagt.",al={"wann ist negolash anlocken möglich","facing negolash voraussetzung","negolash anlocken freischalten"}}},fp="17,164,19.187.0,28.148.0,46.108.0,37.57.0"}
P.entries["quest:62"] = {n="Die Tiefenschachtmine",s="Südlich von Goldhain schickt Euch Marschall Dughan zur Erkundung der von Kobolden besetzten Tiefenschachtmine. Sie liegt zwischen den Bauernhöfen der Steinfelds und Maclures, und ihr Fall deutet auf Schwierigkeiten jenseits ihrer Stollen hin.",h="Südlich von Goldhain schickt Euch Marschall Dughan zur Erkundung der von Kobolden besetzten Tiefenschachtmine.",kw={"dughan","elwynn","tiefenschachtmine","goldhain","jaspismine","kobold","maclure","steinfeld"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr in der überrannten Mine ein weiteres Zeichen dafür, dass Sturmwind Mühe hat, Elwynns wichtige Stätten zu schützen.",["profession:Mining"]="Als Bergarbeiter könnt Ihr in der Tiefenschachtmine reiche Kupferadern finden, doch Kobolde, die ihr Revier verteidigen, stehen Euch im Weg."},sec={{t="Ärger südlich von Goldhain",b="Kobolde haben die Tiefenschachtmine südlich von Goldhain zwischen den Gehöften der verfeindeten Steinfelds und Maclures eingenommen. Einst lieferte sie Stein und Erz für das Reich. Nun hallt schrilles Geschnatter durch ihre feuchten Stollen, in denen Talgkerzen brennen. Marschall Dughan schickt Euch los, um die Tiefen auszukundschaften und herauszufinden, wie schlimm die Lage ist."},{t="Eine überlastete Wache",b="Als Dughan Euren Bericht hört, sorgt er sich um andere Abbaustätten, darunter die Jaspismine im Nordosten. Die Nachricht verschärft die angespannte Lage der Wache von Sturmwind. Ihre Truppen sind bereits durch die Abwehr von Defias-Banditen und Gnolleinfällen ausgelastet, sodass zu wenige bleiben, um die Stollen zu räumen."}},faq={{q="Wo liegt die Tiefenschachtmine?",a="Die Tiefenschachtmine liegt fast genau südlich von Goldhain im Wald von Elwynn, zwischen den Gehöften der Steinfelds und Maclures.",al={"tiefenschachtmine lage","wo ist die tiefenschachtmine","tiefenschachtmine karte"}},{q="Wer schickt Euch zur Erkundung der Tiefenschachtmine?",a="Marschall Dughan, der befehlshabende Offizier der Wache von Sturmwind in Goldhain, schickt Euch zur Erkundung der Stollen.",al={"wer vergibt die quest zur tiefenschachtmine","marschall dughan quest"}},{q="Welche Kreaturen haben die Mine eingenommen?",a="Kobolde haben die Mine überrannt, ihre Kerzen entzündet und die menschlichen Arbeiter vertrieben.",al={"wer ist in der tiefenschachtmine","welche monster sind in der tiefenschachtmine"}},{q="Warum braucht Marschall Dughan Abenteurer, um die Mine zu überprüfen?",a="Die Wache von Sturmwind ist durch örtliches Banditenunwesen, verbliebene Orktruppen und Gnollüberfälle so ausgelastet, dass Dughan selbst zur Bestätigung von Späherberichten keine Soldaten übrig hat.",al={"warum späher schicken","warum geht die wache nicht"}},{q="Was geschieht nach der Erkundung der Tiefenschachtmine?",a="Nachdem Ihr Marschall Dughan von den Schwierigkeiten berichtet habt, befürchtet er, dass sie weit verbreitet sind, und schickt Euch nach Nordosten zur Untersuchung der Jaspismine.",al={"nächste quest nach der tiefenschachtmine","what comes next"}},{q="Warum ist der Befall der Tiefenschachtmine bedeutsam?",a="Der Fall der Tiefenschachtmine zeigt, dass der Koboldbefall in Nordhain kein Einzelfall war. Bedrohungen aus der Wildnis dringen rasch auf das besiedelte Ackerland unmittelbar vor den Toren Sturmwinds vor.",al={"warum ist die tiefenschachtmine wichtig","geschichte der tiefenschachtmine"}}},fx={["88321243"]={q="Warum haben Kobolde die Tiefenschachtmine übernommen?",a="Kobolde sind natürliche Tunnelbewohner, die ständig unter der Erde nach Gold und wertvollen Mineralien suchen. Da die Wachen von Sturmwind überstrapaziert sind, um die Region vor Defias-Banditen und wilden Tieren zu schützen, wurden die lokalen Minen weitgehend unbewacht gelassen. Angelockt von reichen Erz- und Goldvorkommen, schwärmten die Ungeziefer in die Tiefenschachtmine, gruben sich tief ein und vertrieben alle Arbeiter.",al={"warum sind kobolde in der tiefenschachtmine","kobolde tiefenschachtmine warum","wer ist in der tiefenschachtmine"}}},fp="18,186,26.319.0,16.294.0,36.118.0,42.102.0,40.83.0,59.156.0,47.133.1,53.184.0"}
P.entries["quest:621"] = {n="Zanzils Geheimnis",s="Crank Fizzlebub sucht Zanzils Geheimnis in den Ruinen nordöstlich von Beutebucht. Das Gebräu des verbannten Trolls beugt den Willen und stärkt den Körper, und Crank will Proben für sich selbst.",h="Crank Fizzlebub sucht Zanzils Geheimnis in den Ruinen nordöstlich von Beutebucht.",kw={"aboraz","beutebucht","fizzlebub","jubuwal","mixtur","schlingendorntal","zanzil"},sec={{t="Willensbeugende Tränke",b="Nordöstlich von Beutebucht hat sich Zanzil in den Ruinen von Jubuwal und Aboraz niedergelassen. Seine früheren Stammesführer verstießen ihn, weil sie seine Macht über den Geist anderer fürchteten. Nun beherrscht er seine Anhänger mit Gebräuen aus Dschungelpflanzen. Die Mischungen betäuben ihren Willen und steigern ihre Kraft, sodass sie gefügig, aber widerstandsfähig werden."},{t="Eine einträgliche Mixtur",b="Crank Fizzlebub sieht in Zanzils Handwerk eine Einnahmequelle. Wer Macht über andere will, könnte für ein solches Gebräu fürstlich zahlen, also will der Goblin einen Vorrat aus den Ruinen. Liefert Ihr genügend Proben, bietet Crank den üblichen Lohn und einen stillen Bonus, wenn Ihr über den Handel schweigt."}},faq={{q="Wer ist Zanzil the Outcast?",a="Zanzil ist ein verbannter Troll, der in den Ruinen nordöstlich von Beutebucht lebt. Seine Anführer verbannten ihn, weil sie seine Macht über den Geist anderer fürchteten.",al={"wer ist zanzil","zanzils geschichte","warum wurde zanzil verbannt"}},{q="Was bewirkt Zanzils Mixtur eigentlich?",a="Zanzils Gebräu wird aus Dschungelpflanzen hergestellt, unterdrückt den freien Willen des Trinkenden und stärkt den Körper auf unnatürliche Weise.",al={"was ist zanzils mixtur","wirkung von zanzils mixtur","wirkung von zanzils trank"}},{q="Wo lebt Zanzil?",a="Zanzil und seine Anhänger leben in den Ruinen von Jubuwal und Aboraz, nordöstlich von Beutebucht im Schlingendorntal.",al={"zanzils aufenthaltsort","wo ist zanzil","wo sind die ruinen"}},{q="Warum will Crank Fizzlebub die Mixtur?",a="Crank Fizzlebub glaubt, dass jene, die Macht über andere wollen, gut für das Gebräu zahlen würden, und hat auch eigene Verwendungszwecke im Sinn.",al={"warum will crank die mixtur","was will crank mit zanzils mixtur machen"}},{q="Warum zahlte Crank bei der Übergabe mehr?",a="Crank zahlt einen Bonus, um Euer Stillschweigen zu erkaufen und die Beschaffung des willensbeugenden Gebräus geheim zu halten.",al={"crank fizzlebub zusatzlohn","cranks lohn für stillschweigen"}}},fp="15,171,21.317.0,19.270.0,26.143.0,39.111.0,25.111.0,42.122.0,38.100.1"}
P.entries["quest:622"] = {n="Rückkehr zu Corporal Kaleb",s="Im Rebellenlager wartet Corporal Kaleb auf den Topf, den Krazek in Beutebucht repariert hat. Er hat eine zweite Dampfpfeife und ein in seinen Boden eingebautes Hackmesser.",h="Im Rebellenlager wartet Corporal Kaleb auf den Topf, den Krazek in Beutebucht repariert hat.",kw={"beutebucht","corporal kaleb","kochtopf","krazek","rebellenlager","schlingendorntal"},sec={{t="Ein besserer Topf",b="Krazek hat den Topf fertig repariert, den Ihr ihm gebracht habt. Er hat eine weitere Dampfpfeife hinzugefügt und ein Hackmesser in den Boden eingebaut, scharf genug, um Beinknochen zu durchtrennen. Er nennt das einen sicheren Weg, den Koch zufriedenzustellen, und erwartet, dass sich der Besitzer über die Änderungen freut. Nun kann der Topf zu Corporal Kaleb im Rebellenlager zurückgebracht werden."},{t="Zurück im Lager",b="Corporal Kaleb ist begeistert, dass der Topf funktioniert, und endlich kann das Abendessen beginnen. Er hofft, dass Eure Zeit in Beutebucht gut verlaufen ist, auch wenn er die Stadt als rau bezeichnet. Er erzählt auch ein Gerücht: Goblins verschleppen manchmal betrunkene Seeleute auf Sklavenschiffe, die zu unbekannten Zielen aufbrechen."}},faq={{q="Wer ist Corporal Kaleb?",a="Corporal Kaleb wartet im Rebellenlager auf den Kochtopf, den Krazek in Beutebucht repariert.",al={"corporal kaleb","wer ist kaleb","kaleb rebellenlager","wo ist corporal kaleb","kaleb aufenthaltsort"}},{q="Was hat Krazek mit dem Topf gemacht?",a="Krazek hat den Topf repariert, eine weitere Dampfpfeife hinzugefügt und ein neues Hackmesser in den Boden eingebaut, scharf genug, um Beinknochen zu durchtrennen.",al={"krazek topf verbesserungen","was hat krazek repariert","krazek kochtopf"}},{q="Was kam vor diesem Schritt?",a="Favor for Krazek kam zuerst.",al={"vorherige quest","was führte zur rückkehr zu corporal kaleb"}}},fp="24,146,12.312.0,16.265.1,22.98.0,30.132.0,27.28.0"}
P.entries["quest:623"] = {n="Bündelweise Akiris",s="Im Schlingendorntal hat Bloads ein frisches Bündel Akirisschilfrohr für die Insel Theramore bereit. Sein Kontakt, Freibeuter Groy, hat einen Kunden, der dringend mehr möchte, doch Bloads kann erst in einer Woche in die Düstermarschen segeln.",h="Im Schlingendorntal hat Bloads ein frisches Bündel Akirisschilfrohr für die Insel Theramore bereit.",kw={"akiris","bloads","düstermarschen","groy","freibeuter","schilfrohr","schlingendorntal","theramore"},ang={["faction:Alliance"]="Die Insel Theramore ist eine Hochburg der Allianz in den Düstermarschen. Bloads warnt, dass Besucher dennoch Ärger bekommen können, wenn sie zum falschen Schlag gehören."},sec={{t="Überfahrt nach Theramore",b="Während Eurer Abwesenheit erreicht Euch eine Nachricht von jenseits des Meeres. Freibeuter Groy auf der Insel Theramore ist mit der letzten Lieferung Akirisschilfrohr zufrieden, und ein Kunde möchte sofort ein weiteres Bündel. Freibeuter Bloads kann erst in einer Woche in die Düstermarschen segeln. Also gibt er Euch das Paket, damit Ihr es persönlich über das Meer bringt."},{t="Lieferung an den Docks",b="Freibeuter Groy wartet an den Docks von Theramore. Zunächst weist er Fremde ab, doch als er erfährt, dass Bloads die Lieferung veranlasst hat, prüft er das Bündel genau. Zufrieden mit dem Schilfrohr zahlt er Euch für den Transport einen Anteil in Münzen. Dann warnt er Reisende davor, sich an seinen Docks aufzuhalten."}},faq={{q="Wer ist Freibeuter Groy?",a="Freibeuter Groy ist der Kontakt von Freibeuter Bloads auf der Insel Theramore in den Düstermarschen. Groy hat einen Kunden, der mehr Akirisschilfrohr möchte.",al={"wer ist groy","groy theramore","freibeuter groy"}},{q="Warum braucht Freibeuter Bloads einen Kurier?",a="Bloads hat gehört, dass Groys Kunde dringend ein weiteres Bündel Akirisschilfrohr möchte. Bloads kann erst in einer Woche in die Düstermarschen segeln, also bittet er Euch, es über das Meer zu bringen.",al={"warum schilfrohr transportieren","warum theramore","bloads lieferung"}},{q="Wohin muss diese Lieferung gebracht werden?",a="Das Bündel ist für die Insel Theramore bestimmt, einen Hafen der Allianz in den Düstermarschen.",al={"wohin das schilfrohr bringen","akiris lieferort","düstermarschen lieferung"}},{q="Was ging dieser Reise voraus?",a="Diese Lieferung folgt auf das erste Sammeln von Akirisschilfrohr im Schlingendorntal, bei dem Bündel zu Freibeuter Bloads gebracht wurden.",al={"vorherige quest","akirisschilfrohr questreihe","voraussetzung"}}},fp="20,209,23.311.0,21.279.1,22.128.0,41.182.0,36.77.0,30.127.0"}
P.entries["quest:624"] = {n="Cortellos Rätsel",s="Ein Pergament mit Cortellos Rätsel taucht an Bord von Schiffen der Blutsegelbukaniere entlang der wilden Ufer auf. Seine Verse führen Euch zu einem Hinweis unter einer verzierten Brücke.",h="Ein Pergament mit Cortellos Rätsel taucht an Bord von Schiffen der Blutsegelbukaniere entlang der wilden Ufer...",kw={"blutsegelbukaniere","brücke","cortello","rätsel","schriftrolle","sümpfe des elends","die wilden ufer"},sec={{t="Das Rätsel eines Bukaniers",b="Blutsegelbukaniere, die vor der Südküste des Schlingendorntals ankern, tragen verstreute Notizen mit einem Reim bei sich. Cortellos Verse beschreiben eine kunstvoll gearbeitete Brücke, abgenutzt von vielen Reisenden. Sie liegt östlich der Totenwinde und südlich des Rotkammgebirges. Folgt der Wegbeschreibung aus dem Dschungel hinaus und in die Sümpfe, wo darunter etwas wartet."},{t="Der Übergang im Sumpf",b="Die Verse führen unter eine verzierte Brücke, die die Sümpfe des Elends überspannt. Im trüben Wasser darunter liegt ein durchnässtes Pergament mit dem nächsten Schritt in Cortellos Rätsel."}},faq={{q="Wo beginnt dieses Geheimnis?",a="Das Geheimnis beginnt mit einem Pergamentfetzen in der Flotte der Blutsegelbukaniere, die vor den wilden Ufern südlich von Beutebucht ankert.",al={"wo beginnt cortellos rätsel","cortellos rätsel startort","wo findet sich cortellos rätsel"}},{q="Welchen Ort beschreibt das Rätsel?",a="Der Reim beschreibt eine viel genutzte, verzierte Brücke in den Sümpfen des Elends, östlich des Gebirgspasses der Totenwinde und südlich des Rotkammgebirges.",al={"welche brücke beschreibt cortellos rätsel","wohin weist das rätsel","brücke östlich der totenwinde südlich des rotkammgebirges"}},{q="Wonach sucht Ihr unter der Brücke?",a="Das Rätsel weist auf einen Hinweis hin, der unter der Brücke wartet.",al={"was findet sich in den sümpfen des elends","cortello hinweis unter der brücke","was liegt unter der brücke"}},{q="Wer hat das Rätsel geschrieben?",a="Das Rätsel trägt Cortellos Namen, doch das Pergament verrät nichts weiter darüber, wer er war.",al={"wer ist cortello","cortello hintergrundgeschichte","wer hat cortellos rätsel verfasst"}}},fp="17,163,20.319.0,18.160.1,30.131.0,41.134.0,46.55.0,21.87.0"}
P.entries["quest:625"] = {n="Cortellos Rätsel",s="Reisende folgen Cortellos zweitem Vers über das Meer nach Kalimdor. Seine Zeilen weisen Schatzsuchern den Weg zu einer Höhle im Südwesten der Düstermarschen.",h="Reisende folgen Cortellos zweitem Vers über das Meer nach Kalimdor.",kw={"blutsumpfbau","cortello","cortellos rätsel","düstermarschen","musty scroll","durchnässtes pergament","schlingendorntal"},sec={{t="Ein Vers übers Meer",b="Cortellos zweiter Vers schickt Suchende nach Kalimdor. Er beschreibt die Düstermarschen, ein düsteres Feuchtgebiet östlich des Brachlands."},{t="Die Höhle im Südwesten",b="Das Rätsel weist auf einen Hinweis in einer Höhle im Südwesten des Sumpfes hin."},{t="Wohin der Vers führt",b="Der Vers führt zum Blutsumpfbau, einer Höhle im Südwesten der Düstermarschen. Eine musty scroll wartet dort."}},faq={{q="Wohin schickt dieses Rätsel Reisende?",a="Der Vers schickt Suchende nach Kalimdor, in die Düstermarschen östlich des Brachlands.",al={"wohin bei cortellos rätsel","cortello teil zwei fundort","wo ist der zweite rätselhinweis"}},{q="Wo in den Düstermarschen ist der Hinweis versteckt?",a="Der Hinweis liegt in einer Höhle im Südwesten der Düstermarschen.",al={"wo ist die höhle in den düstermarschen","düstermarschen rätselhöhle","blutsumpfbau rätsel"}},{q="Welcher Gegenstand leitet diesen Schritt der Spurensuche ein?",a="Dieser Schritt beginnt mit einem durchnässten Pergament, das am Ende der Spur des ersten Rätsels in den Sümpfen des Elends gefunden wurde.",al={"wie beginnt diese quest","was startet cortellos rätsel zwei"}}},fp="17,149,31.125.0,20.68.0,21.104.1,38.79.0,45.57.0,43.106.0"}
P.entries["quest:626"] = {n="Cortellos Rätsel",s="Im Hinterland locken die letzten Verse von Cortellos Rätsel Schatzsucher an die Küste. Eine modrige Schriftrolle weist von den südlichen Tropen nach Norden, und die Spur endet unter den Wasserfällen.",h="Im Hinterland locken die letzten Verse von Cortellos Rätsel Schatzsucher an die Küste.",kw={"cortello","cortellos rätsel","hinterland","lordaeron","modrige schriftrolle","overlook cliffs","schatz","wasserfall"},sec={{t="Der letzte Hinweis",b="Der verwitterte Vers lenkt die Suche nach Norden, fort von den südlichen Tropen und hin nach Lordaeron. Dort, inmitten der großen Unruhen der umkämpften Lande, findet die lange Jagd an der Küste ihr Ende."},{t="Unter dem Wasserfall",b="Der letzte Hort liegt an der Küste des Hinterlands. Sucht unter Wasser am Fuße der großen Wasserfälle."}},faq={{q="Wohin führt dieses Rätsel?",a="Der Vers führt an die Küste des Hinterlands in Lordaeron. Sucht unter Wasser am Fuße des großen Wasserfalls, der von den Klippen herabstürzt.",al={"wo endet cortellos rätsel","wohin für cortellos rätsel teil drei","cortello hinterland fundort"}},{q="Was leitet diesen Teil der Suche ein?",a="Eine modrige Schriftrolle, die bei der früheren Suche nach Cortellos Schatz gefunden wurde, enthält das letzte Rätsel.",al={"wie beginnt cortellos rätsel teil drei","wo ist die schriftrolle zu finden"}},{q="Wer hat diese Verse geschrieben?",a="Cortello hinterließ die Rätsel und verborgenen Schriftrollen, die Suchende zu seinem Schatz führen.",al={"wer ist cortello","wer hat cortellos rätsel verfasst"}}},fp="17,191,14.198.0,19.99.0,28.139.0,36.94.0,23.81.0"}
P.entries["quest:6261"] = {n="Dungar Trinkfest",s="Am Horst im Handelsdistrikt von Sturmwind organisiert Dungar Trinkfest schnelle Greifenflüge mit Vorräten für Westfalls Verteidiger.",h="Am Horst im Handelsdistrikt von Sturmwind organisiert Dungar Trinkfest schnelle Greifenflüge mit Vorräten für...",kw={"dungar trinkfest","greifenmeister","osric strang","osrics kiste","späherkuppe","sturmwind","thor","der handelsdistrikt","westfall"},ang={["faction:Alliance"]="Die Verbindung zwischen Sturmwind und den umliegenden Siedlungen durch Greifen hilft, die Ordnung zu wahren, während die Hauptarmee des Königreichs fern ist.",["race:Dwarf"]="Als Zwerg bringt Ihr eine uralte Verbundenheit mit Greifen in das Menschenkönigreich mit, wo Betreuer wie Dungar Trinkfest und Thor sie führen.",["race:Human"]="Als Mensch verlasst Ihr Euch auf einzelne Händler und örtliche Greifenbetreuer, um die Grenzaußenposten mit Waffen zu versorgen, während das House of Nobles Westfall vernachlässigt."},sec={{t="Eine lebenswichtige Versorgungslinie",b="Gesetzlose der Defias und wilde Erntegolems haben Westfall an den Rand des Zusammenbruchs gebracht. Rüstmeister Lewis und die Volksmiliz brauchen dringend Vorräte. Lewis schickte Nachricht an die Hauptstadt, und der Rüstungsschmied Osric Strang packte die angeforderte Ausrüstung zusammen. Militärische Fracht zu Fuß durch das von Banditen heimgesuchte Elwynn und Westfall zu tragen, kostet wertvolle Zeit. Sturmwinds neue Flugrouten bieten eine lebenswichtige Verbindung zu den Grenzgebieten."},{t="Der Meister des Horstes",b="Im Handelsdistrikt von Sturmwind koordiniert Dungar Trinkfest vom Greifenhorst aus Kurier- und Passagierflüge. Wildhammerzwerge ziehen diese großen Tiere seit Langem auf und betreuen sie. Greifen befördern Menschen und Fracht durch die Länder der Menschen, wenn die Horste an beiden Enden die Route kennen. Osrics schwere Kiste direkt zu Dungar zu bringen, zeigt, wie der Lufttransport funktioniert. Er verbindet die Vorratslager der Hauptstadt mit Grenzaußenposten wie der Späherkuppe."}},faq={{q="Wer ist Dungar Trinkfest?",a="Dungar Trinkfest betreut Sturmwinds Greifen vom Horst im Handelsdistrikt aus. Er beaufsichtigt Kuriergreifen und Passagierflüge durch die Gebiete der Allianz im südlichen Lordaeron und in Azeroth.",al={"dungar","wer ist dungar","greifenmeister von sturmwind"}},{q="Warum schickt Osric diese Kiste mit einem Greifen?",a="Rüstmeister Lewis und der Volksmiliz in Westfall fehlt es im Kampf gegen die Banditen verzweifelt an Ausrüstung. Schwere Vorräte zu Fuß oder per Wagen zu transportieren, dauert Tage und birgt die Gefahr von Hinterhalten. Ein abgerichteter Greif kann Osrics Kiste in wenigen Minuten über Grenzen hinweg tragen.",al={"warum einen greifen nutzen","warum nicht zu fuß","osrics kiste liefern"}},{q="Wer ist Thor, und warum muss ich zuerst mit ihm sprechen?",a="Thor ist der Greifenmeister auf der Späherkuppe in Westfall. Greifen folgen bekannten Routen zwischen bestimmten Orten, daher können Dungars Reittiere Euch erst zurückfliegen, nachdem Ihr Euch bei Thor gemeldet und den Weg vom anderen Ende aus erkundet habt.",al={"wer ist thor","warum thor besuchen","thor greif"}},{q="Was geschieht, nachdem Dungar die Kiste angenommen hat?",a="Nachdem er die Kiste geprüft hat, macht Dungar einen Greifen bereit und weist Euch an, sie direkt zu Rüstmeister Lewis auf der Späherkuppe zu bringen.",al={"was kommt als nächstes","return to lewis","nächste quest"}},{q="Wo gehört diese Quest in die Flugquestreihe?",a="Dies ist der dritte Schritt einer Einführung in das Flugnetz. Sie beginnt in Westfall mit „A Swift Message“ und führt Euch dann mit „Continue to Sturmwind“ nach Sturmwind. Darauf folgt Dungars Teil, und die Reihe endet mit „Return to Lewis“.",al={"questreihe","flugquestreihe","wie viele quests"}},{q="Warum verlässt sich Sturmwind auf die Greifen der Zwerge?",a="Seit der Zweite Krieg die Allianz von Lordaeron mit dem Wildhammerklan aus dem Hinterland vereinte, sind Greifen die wichtigsten Kundschafter und Transporttiere der Allianzreiche. Sie ermöglichen schnelle Reisen an zerstörten Straßen und feindlichen Blockaden vorbei.",al={"warum greifen in sturmwind","hintergrund der greifen der allianz"}}},fx={["915b1473"]={q="Warum möchte Osric Strang, dass dies getan wird?",a="Osric hat die von Rüstmeister Lewis angeforderte Ausrüstung zusammengestellt und muss sie dringend nach Westfall liefern lassen. Die dort stationierten Soldaten sind schwer bedrängt und können es sich nicht leisten, ohne frische Vorräte und angemessene Ausrüstung auszukommen. Indem er Euch zu Dungar Longdrink schickt und die Greifenflüge nutzt, stellt Osric sicher, dass diese lebenswichtigen Proviantpakete so schnell wie möglich ankommen.",al={"osric strang beweggrund","warum kiste schicken","warum möchte osric dies"}}},fp="16,135,20.403.0,23.437.0,24.199.0,44.244.0,47.227.0,44.130.0,48.232.0,44.235.0"}
P.entries["quest:627"] = {n="Gefallen für Krazek",s="In Beutebucht unterbricht Krazek seine Arbeit an einem kaputten Schmortopf, um Euch um vier Ladungen Geringen Blutsteinerzes aus den nördlichen Hügeln zu bitten. Er gibt Euch das Kochgeschirr zurück, wenn Ihr sie bringt.",h="In Beutebucht unterbricht Krazek seine Arbeit an einem kaputten Schmortopf, um Euch um vier Ladungen Geringen...",kw={"arathihochland","blutstein","beutebucht","schlucht der trockenstoppel","gefallen für krazek","krazek","geringes blutsteinerz","schlingendorntal"},ang={["profession:Mining"]="Als Bergarbeiter könnt Ihr das Erz selbst fördern. Krazek warnt, dass Ihr jemanden braucht, der die Adern abbauen kann, falls Euch die Fertigkeit fehlt."},sec={{t="Ein Handel im Norden",b="Krazek unterbricht die Reparatur des kaputten Kochgeschirrs in Beutebucht, um einen Handel anzubieten. Er schickt Euch weit nach Norden ins Arathihochland. Dort birgt eine Höhle in der Schlucht der Trockenstoppel Geringes Blutsteinerz. Das Mineral ist minderwertig, doch wer seine Verwendung kennt, schätzt es."},{t="Erz aus der Schlucht",b="Krazek arbeitet weiter am Topf, während Ihr nach Norden reist. Er erwartet vier Ladungen Blutstein und verspricht eine Bezahlung, wenn Ihr genug zurückbringt. Das Erz muss abgebaut werden. Fehlt Euch die Fertigkeit, braucht Ihr jemanden, der es fördern kann."}},faq={{q="Wer ist Krazek und was will er?",a="Krazek ist ein Goblin in Beutebucht. Während er einen kaputten Schmortopf repariert, bittet er Euch, vier Ladungen seltenen Blutsteinerzes aus dem Norden mitzubringen.",al={"wer ist krazek","krazeks bitte"}},{q="Wo befindet sich das Blutsteinerz?",a="Geringes Blutsteinerz liegt in einer Berghöhle in der Schlucht der Trockenstoppel, weit im Norden im Arathihochland.",al={"wo ist blutsteinerz","blutstein fundort","schlucht der trockenstoppel lage"}},{q="Warum will Krazek minderwertiges Erz?",a="Der Blutstein aus der Höhle ist minderwertig, doch laut Krazek hat er für jene Wert, die das Handwerk und Wissen zu seiner Nutzung besitzen.",al={"warum geringes blutsteinerz","blutstein wert"}},{q="Was geschieht vor dieser Aufgabe?",a="Bevor Krazek seine Forderung stellt, bringt Ihr das beschädigte Gefäß in Krazek's Cookery nach Beutebucht.",al={"vorherige quest","was kam davor"}},{q="Was geschieht nach dem Sammeln des Blutsteins?",a="Nachdem Krazek die vier Ladungen Erz erhalten und Euch bezahlt hat, geht es mit Return to Corporal Kaleb weiter.",al={"nächste quest","what comes next"}}},fp="16,183,18.253.0,18.221.0,36.142.0,36.101.0,35.114.0,30.96.0,44.101.0"}
P.entries["quest:628"] = {n="Exzelsior",s="In Beutebucht ist Drizzlik bereit für das letzte Stück der Excelsior-Stiefel. Er braucht die Haut eines alten Salzwasserkrokilisken für ihre Außenschicht.",h="In Beutebucht ist Drizzlik bereit für das letzte Stück der Excelsior-Stiefel.",kw={"beutebucht","krokilisk","drizzlik","alter krokilisk","excelsior","salzwasserkrokilisk","schlingendorntal"},sec={{t="Die äußere Schicht",b="Drizzlik hat die Innenschicht der Stiefel fertiggestellt. Für die Außenseite verwendet er die feinsten Häute alter Krokilisken. Sie sind zäher und bieten eine bessere Oberfläche für die Verzierungen und Akzente der Excelsior-Linie. Nur die Haut eines alten Salzwasserkrokilisken passt zu seinem Plan.\n\nEinen solchen zu finden ist schwierig. Alte Krokilisken zeigen sich nur, um andere Salzwasserkrokilisken zu beschützen. Drizzlik hat außerdem gelesen, dass die Bestände der Salzwasserkrokilisken schwinden, was ihm Sorgen um sein Geschäft bereitet."},{t="Drizzliks Dank",b="Drizzlik kann die Bestellung ausführen und sie vorzeitig mit dem nächsten Schiff nach Undermine an Direktor Riddlevox schicken. Er hat zusätzliche Exemplare angefertigt und gibt Euch für Eure Mühen ein Paar. Kein Stiefel, betont er, ist so edel wie die der Excelsior-Linie."}},faq={{q="Wer ist Drizzlik?",a="Drizzlik fertigt in Beutebucht die Stiefel der Excelsior-Linie.",al={"drizzlik","stiefelmacher beutebucht","drizzlik npc"}},{q="Warum braucht Drizzlik die Haut eines alten Salzwasserkrokilisken?",a="Drizzlik sagt, die Häute alter Krokilisken seien zäher und böten eine bessere Oberfläche für die Verzierungen und Akzente der Excelsior-Linie. Nur die Haut eines alten Salzwasserkrokilisken passt zu seinem Plan.",al={"warum krokiliskenhaut","excelsior stiefelmaterialien","verwendung alter krokiliskenhaut"}},{q="Warum sind alte Salzwasserkrokilisken schwer zu finden?",a="Alte Salzwasserkrokilisken zeigen sich nur, um andere Salzwasserkrokilisken zu verteidigen, sagt Drizzlik.",al={"wo sind alte krokilisken","alten salzwasserkrokilisken finden","wie alten krokilisken beschwören"}},{q="Was kam vor dieser Bitte?",a="Some Assembly Required kam zuerst.",al={"vorherige quest","excelsior voraussetzung","some assembly required verknüpfung"}},{q="Welche Sorge hat Drizzlik wegen der Salzwasserkrokilisken?",a="Drizzlik hat gelesen, dass die Bestände der Salzwasserkrokilisken schwinden, was ihm Sorgen um sein Geschäft bereitet.",al={"sterben krokilisken aus","salzwasserkrokiliskenbestand","aussterben der krokilisken"}}},fp="9,140,15.430.0,17.222.1,16.56.0,57.152.0,48.93.0,30.34.0,59.93.0"}
P.entries["quest:6281"] = {n="Weiter nach Sturmwind",s="Ihr bringt eine Anforderung per Greif von der Späherkuppe nach Sturmwind, wo Osric Strang Euch in der Altstadt erwartet.",h="Ihr bringt eine Anforderung per Greif von der Späherkuppe nach Sturmwind, wo Osric Strang Euch in der...",kw={"flugroute","greif","lewis' notiz","limited immunity","die altstadt","osric strang","späherkuppe","thor"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Euch auf Greifenmeister verlassen, die verstreute Außenposten verbinden und abgelegene Garnisonen mit der Hauptstadt in Verbindung halten.",["race:Human"]="Als Mensch könnt Ihr in der Altstadt sehen, wie fern sich einfache Bürger und abgeschiedene Grenzlandbewohner der Politik des erhabenen House of Nobles fühlen."},sec={{t="Auf Schwingen",b="Rüstmeister Lewis bereitet auf der Späherkuppe ein Anforderungsschreiben vor. Thor, der örtliche Greifenmeister, bietet Euch den schnellsten Weg aus den umkämpften Ebenen. Für eine geringe Gebühr fliegt Ihr auf einem der ausgebildeten Greifen des Königreichs über staubiges Ackerland und die Flussgrenze des Waldes von Elwynn. Dann trägt Euch der Greif über die hohen weißen Stadtmauern von Sturmwind."},{t="Nachschubwege der Altstadt",b="Ihr landet an den Handelslandeplätzen der Hauptstadt und begebt Euch dann in die Altstadt. Dort findet Ihr Osric Strang in seinem Geschäft Limited Immunity. Osric versorgt das Grenzland, doch sein finsterer Empfang zeigt die wachsende Kluft zwischen Westfalls bedrängter Volksmiliz und den abgelenkten Herrschern in Burg Sturmwind."}},faq={{q="Welchen Zweck hat diese Quest?",a="Ihr bringt die Anforderung von Rüstmeister Lewis per Greif von der Späherkuppe nach Sturmwind. Unterwegs lernt Ihr die Route zwischen dem Außenposten und der Hauptstadt kennen.",al={"warum diese quest machen","zweck der quest","weiter nach sturmwind questziel"}},{q="Wo befindet sich Osric Strang?",a="Osric Strang betreibt Limited Immunity in der Altstadt von Sturmwind.",al={"wo ist osric strang","osric strang finden","limited immunity standort"}},{q="Warum braucht die Späherkuppe Vorräte aus Sturmwind?",a="Die Volksmiliz auf der Späherkuppe kämpft gegen die Bruderschaft der Defias und erhält kaum offizielle militärische Unterstützung aus der Hauptstadt. Rüstmeister Lewis muss Ausrüstung direkt bei zivilen Händlern kaufen.",al={"warum vorräte benötigt werden","westfall nachschubproblem","späherkuppe ausrüstung"}},{q="Wer ist Thor?",a="Thor ist der Greifenmeister auf der Späherkuppe. Er verwaltet Flugrouten, die Westfall mit Sturmwind und anderen verbündeten Knotenpunkten verbinden.",al={"wer ist thor","westfall greifenmeister","thor westfall"}},{q="Was steht in Lewis' Notiz?",a="Lewis' Notiz ist eine dringende Anforderung von Rüstmeister Lewis, die benötigte Ausrüstung und Vorräte zur Versorgung der Garnison auf der Späherkuppe aufführt.",al={"lewis' notiz","was steht in der notiz","inhalt der notiz"}},{q="Was geschieht nach der Übergabe der Notiz?",a="Nachdem Osric die Anforderung erhalten hat, schickt er Euch zu Dungar Longdrink, dem Greifenmeister von Sturmwind. Ihr organisiert den Rücktransport der bestellten Vorräte nach Westfall.",al={"was kommt als nächstes","folgequest","nach osric strang"}}},fx={["9888c0f8"]={q="Warum möchte Thor, dass dies getan wird?",a="Thor ist der Greifenmeister von Westfall, und seine Aufgabe ist es, die Kommunikation und den Transport zwischen der Grenze und der Hauptstadt aufrechtzuerhalten. Rüstmeister Lewis muss dringend Vorräte an die Späherkuppe liefern, aber Greifen fliegen nicht von selbst, ohne dass jemand die Zügel hält und die Anforderung in Osric Strangs Hände liefert. Indem er Euch an Bord eines seiner Reittiere schickt, stellt Thor sicher, dass der Hilferuf der Späherkuppe tatsächlich Sturmwind erreicht.",al={"warum schickt mich thor","thor beweggrund continue to stormwind","warum hilft greifenmeister thor"}},a35c3ce1={q="Warum braucht Thor mich, anstatt selbst nach Sturmwind zu fliegen?",a="Thor kann seinen Posten in der Späherkuppe nicht einfach verlassen. Als einziger Greifenmeister der Siedlung muss er vor Ort bleiben, um sich um den Horst zu kümmern, die Fluglinien zu verwalten und Westfall mit dem weiteren Königreich verbunden zu halten. Ein fähiger Kurier wie Ihr, der bereit ist, die Reisegebühr zu übernehmen und Lewis' Anforderung direkt an Osric Strang in der Altstadt zu überbringen, lässt die Späherkuppe ihre Nachricht nach Sturmwind bringen, ohne den Außenposten seines Betreuers zu berauben.",al={"warum ich continue to stormwind","warum kann thor die nachricht nicht liefern","warum braucht thor einen abenteurer"}}},fp="21,106,11.352.0,21.306.0,34.161.0,30.70.0,52.206.0,12.125.0,27.149.0,39.176.0"}
P.entries["quest:6282"] = {n="Harpyien drohen",s="Im Verbrannten Tal bedrohen Bloodfury-Harpyien die Straßen westlich von Sonnenfels. Maggran Erdbinder ruft Krieger der Horde auf, ihre wachsenden Reihen zu lichten und die Reisewege durch das Steinkrallengebirge offenzuhalten.",h="Im Verbrannten Tal bedrohen Bloodfury-Harpyien die Straßen westlich von Sonnenfels.",kw={"hinterkaltläufer","bloodfury","das verbrannte tal","zirkel","harpyien drohen","maggran erdbinder","schurkenfedern","schlächter","steinkrallengebirge","sonnenfels"},ang={["class:Druid"]="Als Druide seht Ihr, wie die verderbte Präsenz des Bloodfury-Zirkels das empfindliche, von Bränden verwüstete Ökosystem des Verbrannten Tals schändet.",["class:Shaman"]="Als Schamane folgt Ihr Maggran Erdbinders Ruf, aggressive Schänder zu vertreiben, die das natürliche Gleichgewicht der Elemente stören.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr durch die Säuberung des Himmels über dem Verbrannten Tal Euren Stützpunkt in Sonnenfels gegen die gefährlichen wilden Fraktionen des Steinkrallengebirges.",["race:Tauren"]="Als Tauren ist es für Euch ehrenvoll, die vordringenden Bloodfuries zu dezimieren und so Euer angestammtes Versprechen zu erfüllen, Kalimdors Wildnis zu beschützen."},sec={{t="Beschützer des Landes",b="Tauren in Sonnenfels beschützen das Steinkrallengebirge und seine friedlichen Reisenden. Maggran Erdbinder, das betagte Oberhaupt des Rückzugsortes, hat beobachtet, wie die Reihen der Harpyien wachsen. Der Bloodfury-Zirkel hat sich im versengten Verbrannten Tal ausgebreitet, bedrängt Tiere und versperrt Wege. Wenn die Schwärme weiter anwachsen, könnte Sonnenfels abgeschnitten werden."},{t="Säuberung des Verbrannten Tals",b="Westlich von Sonnenfels liegt das Verbrannte Tal, ein Ödland aus Asche, verbrannter Erde und schwelenden Bäumen, das verheerende Brände hinterlassen haben. Bloodfury-Harpyien nisten hoch in den verkohlten Überresten uralter Wälder, und das Tal ist ihre Hochburg. Maggran schickt Krieger der Horde in die feindselige Caldera, um Dutzende Harpyien zu töten: Bloodfury-Hinterkaltläufer, -Schlächter und -Schurkenfedern. Ihre Reihen zu lichten schwächt den Griff des Zirkels auf das Tal und ebnet den Weg, sich seiner matriarchalen Blutlinie zu stellen."}},faq={{q="Wer vergibt die Quest Harpyien drohen?",a="Maggran Erdbinder erteilt den Auftrag in Sonnenfels im Steinkrallengebirge, nahe dem zentralen Teich der Siedlung.",al={"questgeber harpyien drohen","wo harpyien drohen annehmen","maggran erdbinder quest"}},{q="Wo befinden sich die Bloodfury-Harpyien?",a="Bloodfury-Harpyien leben überall im Verbrannten Tal, westlich von Sonnenfels. Ein Bergpfad hinter dem Rückzugsort führt hinab ins Tal.",al={"wo sind bloodfury-harpyien","bloodfury-harpyien fundort","verbranntes tal harpyien"}},{q="Warum wollen die Tauren die Harpyien dezimieren?",a="Die Tauren sehen sich als Hüter des natürlichen Gleichgewichts im Steinkrallengebirge. Maggran Erdbinder fürchtet, dass sich die Bloodfuries aggressiv über Kalimdor ausbreiten, Unschuldige angreifen und Kreaturen daran hindern, sich frei zu bewegen.",al={"warum harpyien töten","tauren harpyien konflikt","warum hasst maggran harpyien"}},{q="Was folgt nach dem Abschluss von Harpyien drohen?",a="Nach dieser Aufgabe schickt Maggran Erdbinder Euch aus, um die herrschende Führung des Bloodfury-Zirkels auszuschalten.",al={"nächste quest harpyien drohen","harpyien drohen folgequest","was nach harpyien drohen"}},{q="Ist diese Quest nur für die Horde?",a="Ja. Nur Mitglieder der Horde können diesen Auftrag in Sonnenfels erhalten.",al={"kann allianz harpyien drohen machen","harpyien drohen nur horde","allianz harpyien drohen"}},{q="Welche Arten von Harpyien müssen getötet werden?",a="Ihr müsst im gesamten Verbrannten Tal sieben Bloodfury-Harpyien, sieben Bloodfury-Hinterkaltläufer, sieben Bloodfury-Schlächter und sieben Bloodfury-Schurkenfedern töten.",al={"welche harpyien töten","harpyienarten verbranntes tal","harpyien drohen questziele"}}},fx={["34ac97e1"]={q="Wer sind die Blutfurien-Harpyien und warum stellen sie eine Bedrohung dar?",a="Die Blutfurien sind ein bösartiger Zirkel von Harpyien, die das verbrannte Tal befallen haben. Laut Maggran Erdbinder sind sie die treibende Kraft hinter den ansteigenden Harpyienpopulationen in ganz Kalimdor. Ihre aggressive Expansion greift auf die umliegende Wildnis über und schließt unschuldige Reisende und Wildtiere in ihrem Territorium ein.",al={"blutfurien-harpyien","wer sind die blutfurien","warum blutfurien-harpyien töten"}}},fp="16,193,22.322.0,25.479.0,37.124.0,40.139.0,42.225.0,45.102.0,25.66.0,36.153.0"}
P.entries["quest:6283"] = {n="Blutfuriengeschlecht",s="Maggran Erdbinder schickt Euch ins Verbrannte Tal, um den Einfluss der Harpyien zu brechen und einen Beweis zurückzubringen.",h="Maggran Erdbinder schickt Euch ins Verbrannte Tal, um den Einfluss der Harpyien zu brechen und einen Beweis...",kw={"blutfuriengeschlecht","bloodfury ripper","das verbrannte tal","harpyien","maggran erdbinder","steinkrallengebirge","sonnenfels"},ang={["faction:Horde"]="Die Sicherung des Umlands von Sonnenfels schützt den einzigen Zufluchtsort der Horde tief im umkämpften Steinkrallengebirge.",["race:Tauren"]="Das vernarbte Land des Steinkrallengebirges schmerzt die Tauren. Ist die gewalttätige Harpyienkönigin erst beseitigt, können Älteste wie Maggran ihre Gedanken wieder auf Harmonie und Heilung richten."},sec={{t="Schlag gegen die Matriarchin",b="Harpyien vom Rand des Verbrannten Tals bedrohen Sonnenfels. Maggran Erdbinder glaubt, dass ihre Angriffe erst enden werden, wenn Bloodfury Ripper, ihre Matriarchin, tot ist. Der Schwarm behandelt sie wie eine Königin. Unter ihrer Führung handeln sie wie aus einem Guss und werden entlang des zerklüfteten westlichen Bergrückens immer kühner."},{t="Frieden in der Erde",b="Maggran bittet Euch, Bloodfury Rippers Überreste als Beweis zurückzubringen. Ohne ihre Brutkönigin verlieren die Harpyien ihre Ordnung und lassen sich leichter in Schach halten. Sonnenfels ist weniger bedroht, und Maggran kann seinen Zorn und seine ständige Wachsamkeit ablegen. Dann kann er wieder nach der Harmonie und dem Gleichgewicht streben, die den Tauren viel bedeuten."}},faq={{q="Wer vergibt die Quest Blutfuriengeschlecht?",a="Maggran Erdbinder vergibt sie. Er führt Sonnenfels an und ist dort nahe dem Wasserbecken zu finden.",al={"questgeber blutfuriengeschlecht","wer startet blutfuriengeschlecht","maggran erdbinder quest"}},{q="Welche Voraussetzung muss erfüllt sein, bevor diese Jagd verfügbar wird?",a="Zuerst müsst Ihr Harpies Threaten abschließen. Maggran schickt Euch ins Verbrannte Tal, um die Reihen der Bloodfury-Harpyien zu lichten.",al={"blutfuriengeschlecht vorquest","voraussetzung für blutfuriengeschlecht","harpies threaten folgequest"}},{q="Wo befindet sich Bloodfury Ripper?",a="Bloodfury Ripper streift durch die felsigen Hügel am nordwestlichen Rand des Verbrannten Tals. Ihre blaue Färbung hebt sie vom Schwarm ab.",al={"wo ist bloodfury ripper","bloodfury ripper finden","bloodfury ripper erscheinungsort"}},{q="Warum will Maggran Bloodfury Ripper tot sehen?",a="Maggran sieht in Bloodfury Ripper die Königin, die das ungestüme Vordringen der Harpyien in das Gebiet lenkt. Er glaubt, dass ihr Tod ihre Führung zerschlagen und ihren Einfluss auf das Tal schwächen wird.",al={"warum bloodfury ripper töten","harpyienanführerin verbranntes tal hintergrund","maggran erdbinder beweggrund"}},{q="Wie wirkt sich Bloodfury Rippers Tod auf die Tauren von Sonnenfels aus?",a="Bloodfury Rippers Tod schenkt Maggran innere Ruhe. Befreit von Zorn und der Furcht vor einem Angriff kann er sich darauf konzentrieren, das Land zu heilen.",al={"steinkrallengebirge harpyienbedrohung hintergrund","was passiert wenn bloodfury ripper stirbt","maggrans reaktion"}},{q="Was ist der schnellste Weg von Sonnenfels ins Verbrannte Tal?",a="Ein Bergpfad führt hinter Sonnenfels direkt hinunter ins Verbrannte Tal. Er umgeht die gewundenen Hauptstraßen des Steinkrallengebirges.",al={"wie von sonnenfels ins verbrannte tal gelangen","sonnenfels hinterer weg","verbranntes tal abkürzung"}}},fx={["174da5a4"]={q="Wozu dienen die Überreste der Blutfurienzerfetzerin?",a="Maggran Erdbinder verlangt die physischen Überreste der Blutfurienzerfetzerin rein als Beweis für Eure Tat. Da die Harpyienkönigin den Blutfurien-Schwarm aus den Tiefen des verbrannten Tals befehligt, benötigt Maggran einen handfesten Beweis dafür, dass sie tatsächlich gefallen ist, bevor er beruhigt wissen kann, dass die Bedrohung für Sonnenfels beendet ist.",al={"zweck der überreste der blutfurienzerfetzerin","warum harpyienüberreste aufbewahren","verwendung der blutfurienüberreste"}},["0ac0712d"]={q="Wer ist die Blutfurienzerfetzerin?",a="Die Blutfurienzerfetzerin ist die Anführerin und Matriarchin der Blutfurien-Harpyien, die in den westlichen Hügeln des verbrannten Tals nisten. Von ihrem Schwarm wie eine Königin behandelt, lenkt sie die bösartigen Kreaturen, die das Steinkrallengebirge bedrohen, und stellt sicher, dass deren Aggression trotz der Bemühungen der Horde, ihre Zahl zu dezimieren, bestehen bleibt.",al={"wer ist die blutfurien-anführerin","geschichte der blutfurienzerfetzerin","blutfurienkönigin"}}},fp="19,102,19.288.0,18.324.0,40.96.0,60.122.0,34.134.0,44.189.0,72.130.1,74.133.0"}
P.entries["quest:6284"] = {n="Arachnophobie",s="Ein Kopfgeld der Horde führt Euch westlich der Scherwindklippe zu Besseleth, der uralten Spinne, die das südliche Steinkrallengebirge heimsucht. Bringt ihren Fangzahn zu Maggran Erdbinder in Sonnenfels, und die Gebirgsstraßen könnten nach Einbruch der Dunkelheit für Reisende sicherer werden.",h="Ein Kopfgeld der Horde führt Euch westlich der Scherwindklippe zu Besseleth, der uralten Spinne, die das...",kw={"arachnophobia","besseleth","kopfgeld","maggran erdbinder","sishircanyon","spinne","steinkrallengebirge","sonnenfels","weberpass"},ang={["class:Hunter"]="Als Jäger stellt die Verfolgung einer gewaltigen Spinne durch die schattigen Felsen des Sishircanyons Eure Fähigkeiten beim Anschleichen im Gebirge auf die Probe.",["faction:Horde"]="Als Reisender der Horde helft Ihr durch Besseleths Beseitigung, die Reise nach Sonnenfels zu sichern und Euren Stützpunkt in den Felsen des zentralen Steinkrallengebirges zu schützen.",["race:Tauren"]="Als Taure könnt Ihr Maggran Erdbinder, der die schmerzhafte Narbe von Besseleths Gift trägt, bei seiner Jagd helfen."},sec={{t="Die Warnung am Straßenrand",b="Ein verwitterter Steckbrief warnt Reisende auf der Hauptstraße südlich der Scherwindklippe vor den Landstrichen westlich der Straße. Im Sishircanyon und am Weberpass wimmelt es von Spinnen. Besseleth, eine ungewöhnlich große orangefarbene Spinne, befehligt ihre Brut. Nach Sonnenuntergang überfällt sie jeden, der vom Pfad abkommt."},{t="Die Klage des Erdbinders",b="Maggran Erdbinder, ein Taure in Sonnenfels, hat das Kopfgeld auf Besseleth ausgesetzt. Bei einer früheren Begegnung traf ihn ihr gewaltiger, zwei Fuß langer Fangzahn und tötete ihn beinahe. Maggran wehrte sie ab und humpelte in Sicherheit, doch die Wunde erinnert ihn noch immer an die Gefahr in den Schatten der Schlucht. Er hofft, dass Ihr ihm Besseleths Fangzahn bringt und die Pässe sichert, damit Handel und Reisen nach Sonnenfels ohne Furcht weitergehen können."}},faq={{q="Wo beginnt die Quest Arachnophobia?",a="Untersucht den Steckbrief auf der Westseite der Hauptstraße im Steinkrallengebirge, direkt südlich des Eingangs zur Scherwindklippe.",al={"wo arachnophobia annehmen","besseleth steckbrief fundort","wie arachnophobia beginnen"}},{q="Wo ist Besseleth zu finden?",a="Besseleth haust im Sishircanyon, westlich des Steckbriefs am Straßenrand. Sie durchstreift den von Netzen überwucherten Boden der Schlucht inmitten ihrer Spinnenbrut.",al={"besseleth fundort","wo ist besseleth","spinne besseleth finden"}},{q="Wer ist Maggran Erdbinder?",a="Maggran Erdbinder ist ein Taure in Sonnenfels im Steinkrallengebirge. Er überlebte einen giftigen Angriff von Besseleth und setzte das Kopfgeld aus, um die Schlucht von ihrer Bedrohung zu befreien.",al={"wer ist maggran","maggran erdbinder rolle","wer hat arachnophobia abgegeben"}},{q="Warum ist Besseleth eine solche Bedrohung für die Region?",a="Besseleth ist eine außergewöhnlich große, erbarmungslose Spinne, die im Sishircanyon und am nahe gelegenen Weberpass auf Beute lauert. Nachts machen sie und ihre Brut Jagd auf Reisende, die nach Sonnenfels unterwegs sind.",al={"warum besseleth töten","was hat besseleth getan"}},{q="Welcher Beweis ist nötig, um das Kopfgeld zu erhalten?",a="Tötet Besseleth und nehmt einen ihrer gewaltigen, zwei Fuß langen Fangzähne an Euch. Bringt Besseleths Fangzahn zu Maggran Erdbinder in Sonnenfels, um das Kopfgeld zu erhalten.",al={"besseleth beweis","besseleth questgegenstand","was lässt besseleth fallen"}},{q="Ist diese Quest für die Allianz verfügbar?",a="Nein. Arachnophobia ist für die Horde bestimmt, da Maggran Erdbinder im Hordelager Sonnenfels das Kopfgeld aussetzt.",al={"kann die allianz arachnophobia machen","allianz arachnophobia quest"}}},fx={["28337efe"]={q="Warum ist ein Kopfgeld auf Besseleth ausgesetzt?",a="Besseleth und ihre Brut haben den Sishircanyon überrannt und jagen unschuldige Reisende, die sich nachts auf die nahe gelegenen Pfade wagen. Maggran Erdbinder selbst wurde von ihren Fängen angegriffen und verwundet und entkam nur knapp mit dem Leben. Er hat das Kopfgeld ausgesetzt, um die Bedrohung zu beseitigen, damit Reisende Sonnenfels sicher erreichen können.",al={"warum besseleth töten","warum will maggran, dass besseleth tot ist","motiv für das kopfgeld auf besseleth"}},["4849c04d"]={q="Wofür wird Besseleths Fangzahn verwendet?",a="Der Fangzahn dient als unbestreitbarer physischer Beweis für das Ableben der riesigen Spinne. Maggran Erdbinder verlangt von Euch, dass Ihr diese giftige Trophäe zurückbringt, bevor er Euch die Kopfgeldprämie gewährt und Euch zum Champion des Waldes erklärt.",al={"zweck von besseleths fangzahn","warum besseleths fangzahn sammeln","wozu dient der fangzahn"}},["9c85495e"]={q="Warum braucht Maggran Erdbinder einen Abenteurer, um Besseleth zu jagen?",a="Maggran hat bereits versucht, sich der großen Spinne selbst zu stellen, und wurde fast getötet, wobei er eine bleibende Wunde von ihrem giftigen Biss erlitt. Während er seine Verletzungen in Sonnenfels ausheilt, setzte er entlang der Straße ein offenes Kopfgeld aus, in der Hoffnung, dass ein fähiger Jäger dort Erfolg haben könnte, wo er gescheitert ist.",al={"warum tötet maggran besseleth nicht selbst","warum ich arachnophobia","warum einen abenteurer anheuern"}}},fp="13,242,20.292.0,27.420.0,41.130.0,29.138.0,27.176.0,45.183.0,43.146.0,40.124.0"}
P.entries["quest:6285"] = {n="Zurück zu Lewis",s="Eine Kiste mit Rüstungen ist für die Volksmiliz auf der Späherkuppe bestimmt, und Dungar Longdrink schickt sie per Greif aus Sturmwind. Der Flug führt über Elwynn und Westfall zu den bedrängten Verteidigern.",h="Eine Kiste mit Rüstungen ist für die Volksmiliz auf der Späherkuppe bestimmt, und Dungar Longdrink schickt...",kw={"dungar longdrink","flugroute","greif","osric","osrics kiste","volksmiliz","rüstmeister lewis","späherkuppe","thor","westfall"},ang={["class:Warrior"]="Als Krieger wisst Ihr, dass jede zur Späherkuppe geflogene Kiste mit Brustpanzern und Beinschienen einem weiteren Milizkämpfer eine Chance gibt, den Hieben der Defiasbanditen standzuhalten.",["faction:Alliance"]="Greifenrouten zwischen Sturmwind und abgelegenen Siedlungen wie der Späherkuppe helfen, ein zunehmend gespaltenes Königreich zusammenzuhalten.",["race:Dwarf"]="Als Zwerg kennt Ihr Greifen als die angestammten Reittiere Eures Volkes. Die Flugrouten des Königreichs führen sie von Dungar Longdrinks Horst in der Hauptstadt zu Thor in Westfall."},sec={{t="Eine Lebensader durch die Lüfte",b="Osric, ein Rüstungsschmied aus Sturmwinds Altstadt, hat eine schwere Kiste mit Rüstungen für die Freiwilligen der Volksmiliz auf der Späherkuppe gepackt. Defiasbanditen, hungrige Gnolle und mechanische Erntemaschinen bedrohen Westfall. Ein einzelner Wagen ist auf diesen Straßen ein leichtes Ziel, also bietet das Netz der Flugmeister den Rüstungen einen sichereren Weg zu den Verteidigern."},{t="Die Wege der Greifen",b="Greifen sind treu und gut ausgebildet, doch sie müssen ein Ziel kennen, bevor sie einen Reiter dorthin tragen. Dungar Longdrink erklärt, dass sie instinktiv zu ihrem Horst in der Hauptstadt Sturmwind zurückkehren. Für einen entlegenen Außenposten müsst Ihr zunächst dessen Flugmeister persönlich aufsuchen. Ihr habt Euch bereits bei Thor auf der Späherkuppe gemeldet und Euch damit den Himmel über dem Grenzland für schnelle Reisen erschlossen."},{t="Nachschub für die Miliz",b="Auf der Späherkuppe nimmt Rüstmeister Lewis die Kiste entgegen und beginnt, die Rüstungen unter den Verteidigern des Grenzlands zu verteilen. Er rüstet Gryan Starkmantels Freiwilligentruppe aus. Jede Lieferung hilft der Miliz, ihre Stellung gegen die Bruderschaft der Defias zu halten."}},faq={{q="Was enthält Osrics Kiste?",a="Osrics Kiste enthält frisch gefertigte Rüstungen, die der Sturmwinder Rüstungsschmied Osric zusammengestellt hat. Die Volksmiliz auf der Späherkuppe braucht sie dringend. Die Freiwilligen erhalten keinen regulären königlichen Nachschub und sind für ihre Ausrüstung auf Spenden und private Lieferungen angewiesen.",al={"osrics kiste inhalt","was ist in der kiste","was wird geliefert"}},{q="Wer ist Rüstmeister Lewis?",a="Rüstmeister Lewis ist der Versorgungsoffizier der Volksmiliz und neben dem Turm auf der Späherkuppe stationiert. Er verwaltet Rationen, Ausrüstung und Waffen für die freiwilligen Verteidiger, die sich in ganz Westfall der Bruderschaft der Defias entgegenstellen.",al={"lewis westfall","rüstmeister lewis aufgabe","wer ist lewis"}},{q="Wer ist Dungar Longdrink?",a="Dungar Longdrink ist Sturmwinds erfahrener menschlicher Greifenmeister am Horst im Handelsdistrikt der Hauptstadt. Er beaufsichtigt die Flugrouten des Königreichs für Kuriere und Reisende.",al={"dungar sturmwind","sturmwind greifenmeister","flugmeister sturmwind"}},{q="Warum fliegen Greifen nur an Orte, die Ihr bereits besucht habt?",a="Dungar sagt, Greifen seien darauf trainiert, auf direktem Weg zur Hauptstadt zurückzufinden. Sie sind auf feste Wegpunkte und persönliche Vertrautheit angewiesen, bevor sie Reiter zu entlegenen Grenzhorsten wie Thors Station auf der Späherkuppe tragen.",al={"greifenflug regel","wie flugrouten funktionieren","warum zuerst thor besuchen"}},{q="Wer ist Thor?",a="Thor ist der Flugmeister auf der Späherkuppe in Westfall. Er versorgt die Greifen des Außenpostens und empfängt Luftkuriere aus Sturmwind.",al={"thor westfall","späherkuppe greifenmeister","flugmeister thor"}},{q="Warum kann Sturmwind nicht einfach königliche Wagen mit Vorräten schicken?",a="Defiasbanditen, Riverpaw-Gnolle und Diebe machen die Straßen zwischen dem Wald von Elwynn und Westfall unsicher. Versorgungstrecks über Land drohen in Hinterhalte zu geraten und ihre Fracht zu verlieren, während die Greifenroute schneller und sicherer ist.",al={"warum greifen nutzen","warum keine lieferung über land","straßen in westfall"}}},fx={["24b76519"]={q="Warum möchte Dungar Longdrink, dass Osrics Kiste ausgeliefert wird?",a="Dungar beaufsichtigt das Greifennetzwerk von Sturmwind, das als lebenswichtige Verbindung zwischen der Hauptstadt und den bedrängten Grenzgebieten dient. Rüstmeister Lewis und die The People's Militia auf der Späherkuppe benötigen dringend Verstärkung und Rüstungen, um Westfall gegen Defias-Schläger und Gnolle zu halten. Dungar stellt sicher, dass kritische militärische Hilfe entlegene Außenposten schnell erreicht, indem er sich darauf verlässt, dass vertrauenswürdige Reisende die Vorräte per Flug befördern.",al={"motiv von dungar","warum osrics kiste schicken","warum dungar lewis hilft"}},["74eea5bf"]={q="Warum muss Dungar Euch die Kiste zustellen lassen, anstatt einen Boten zu schicken?",a="Dungar verwaltet den geschäftigen Flugpunkt der Hauptstadt und kann seinen Posten nicht verlassen, während die offizielle Garnison von Sturmwind nur selten Männer für die vernachlässigte Verteidigung von Westfall erübrigt. Da Lewis ursprünglich Euch geschickt hat, um diesen Versorgungstransport zu koordinieren, habt Ihr bereits das Vertrauen von sowohl Thor als auch der Miliz der Späherkuppe gewonnen. Die Kiste einem willigen Abenteurer anzuvertrauen, der auf dem Rücken eines Greifen zurückkehrt, ist der schnellste Weg, die Rüstung in die Hände zu bekommen, die sie benötigt.",al={"warum keinen boten schicken","warum ich dungar","warum die kiste selbst liefern"}}},fp="15,199,17.333.0,20.372.0,24.248.0,29.251.0,27.212.0,24.176.0,58.226.0,12.142.0,57.195.0"}
P.entries["quest:629"] = {n="Das Finstere Riff",s="Unter der ungezähmten Küste sucht Kin'weelay eine Scherbe aus der versunkenen Trollstadt. Er hofft, Gri'leks Geschichte nach Orgrimmar zu bringen, wo die Dunkelspeere sie bewahren können.",h="Unter der ungezähmten Küste sucht Kin'weelay eine Scherbe aus der versunkenen Trollstadt.",kw={"dunkelspeer","gri'lek","basislager grom'gol","kin'weelay","murloc","die ungezähmte küste","schlingendorntal","tafelscherbe","das finstere riff"},ang={["faction:Horde"]="Indem Ihr Kin'weelay helft, dieses Relikt für Orgrimmar zu bergen, stärkt Ihr das Band des Vertrauens zwischen der Horde und dem Stamm der Dunkelspeere.",["race:Troll"]="Für die Dunkelspeere hält dieses Fragment ihre uralten Traditionen und die Verehrung des großen Helden Gri'lek in ihrer neuen Heimat Orgrimmar lebendig."},sec={{t="Versunkene Legenden",b="Nordwestlich des Basislagers Grom'gol verbirgt die ungezähmte Küste eine uralte Trollstadt unter Wasser. Ein heftiges Erdbeben zerriss vor langer Zeit das Land und ließ die Stadt versinken. Heute werden ihre überfluteten Ruinen das Finstere Riff genannt und beherbergen feindselige Murlocs, die jeden angreifen, der sich in ihre Nähe wagt.\n\nAuf dem Meeresgrund ruht eine gewaltige Steintafel, in die Gri'leks Geschichte eingemeißelt ist. Er war ein legendärer Trollheld, und sein Andenken ist den Dunkelspeeren noch immer heilig."},{t="Ein Andenken für Orgrimmar",b="Das Monument ist zu gewaltig, um es aus der Tiefe zu bergen, also bittet Kin'weelay Euch, eine Scherbe abzubrechen. Er plant, das Fragment nach Orgrimmar zu bringen und es an einem heiligen Ort aufzustellen. Dort können die Dunkelspeere Gri'leks Stärke und Ehre in Erinnerung behalten."}},faq={{q="Wo liegt das Finstere Riff?",a="Das Finstere Riff liegt unter der ungezähmten Küste, nordwestlich des Basislagers Grom'gol im Schlingendorntal.",al={"finsteres riff lage","wo liegt das finstere riff","wie das finstere riff finden"}},{q="Warum will Kin'weelay die Tafelscherbe haben?",a="Die Tafel bewahrt die heilige Geschichte des Trollhelden Gri'lek. Kin'weelay plant, eine Scherbe nach Orgrimmar zu bringen und an einem heiligen Ort aufzustellen, damit die Dunkelspeere sein Andenken in ihrer neuen Heimat bewahren.",al={"warum tafelscherbe holen","tafelscherbe zweck","warum griklek tafel"}},{q="Was geschah mit der uralten Stadt am Finsteren Riff?",a="Vor langer Zeit erschütterte ein gewaltiges Erdbeben die ungezähmte Küste und ließ die gesamte Trollstadt im Meer versinken.",al={"was geschah mit dem finsteren riff","wie versank das finstere riff","versunkene trollstadt geschichte"}},{q="Welche Kreaturen bewohnen heute das Finstere Riff?",a="Feindselige Murlocs bewohnen die überfluteten Ruinen und greifen jeden an, der sich der versunkenen Stadt nähert.",al={"monster im finsteren riff","finsteres riff feinde","wer lebt im finsteren riff"}},{q="Wer ist Gri'lek?",a="Gri'lek ist ein legendärer Trollheld, dessen Geschichte in die Tafel unter der ungezähmten Küste eingemeißelt wurde. Den Dunkelspeeren ist sein Andenken heilig.",al={"wer ist griklek","grilek hintergrundgeschichte","held griklek"}},{q="Warum nur eine Scherbe statt der ganzen Tafel mitnehmen?",a="Das mit Inschriften versehene Monument auf dem Meeresgrund ist zu gewaltig, um es aus den Ruinen zu bergen. Eine einzelne Scherbe lässt sich nach Orgrimmar zurückbringen.",al={"warum nur eine scherbe","kann die ganze tafel mitgenommen werden","ganze tafel mitbringen"}}},fp="13,163,14.433.0,24.252.0,31.99.0,42.204.0,51.106.0,41.93.0,15.134.0,50.127.0"}
P.entries["quest:63"] = {n="Ruf des Wassers",s="Ruf des Wassers führt Schamanen aus dem Brachland über das Meer an ein verseuchtes Ufer im Silberwald. Dort stellt sich ein Initiand der Seuche an einem uralten Schrein, um Gemeinschaft mit den Wassergeistern zu erlangen.",h="Ruf des Wassers führt Schamanen aus dem Brachland über das Meer an ein verseuchtes Ufer im Silberwald.",kw={"brazier of everfount","brine","ruf des wassers","verderbte manifestation","islen wasserdeuter","das grabmal","silberwald","wassertotem"},ang={["class:Shaman"]="Als Schamane lernt Ihr, dass Eure Berufung über Stürme hinausreicht. Ihr könnt verwüstete Lande heilen und spirituelle Verderbnis bannen.",["faction:Horde"]="Als Orc oder Tauren reist Ihr von Kalimdor in den Silberwald und erlebt aus erster Hand die düsteren, seuchengeplagten Nöte Eurer verbündeten Verlassenen."},sec={{t="Eine Pilgerreise übers Meer",b="Ihr sammelt mit der Hilfe des Einsiedlers Brine reines Wasser und kehrt dann zu Islen Wasserdeuter an der Küste des Brachlands zurück. Sie schickt Euch mit der gereinigten Essenz über das Meer an die heimgesuchte Küste des Silberwalds. Der Schrein liegt direkt westlich der Zuflucht der Verlassenen, die das Grabmal genannt wird."},{t="Die Reinigung von Everfount",b="Lordaerons Seuche hat die Wasser des Brazier of Everfount verdorben, eines uralten Fokus der Elemente. Die Geister sind verstummt und wild geworden. Besiegt die verderbte Manifestation, die an die Feuerstelle gebunden ist, und bringt dann ihre Armschienen und das reinste Wasser der Flamme dar. Die Verderbnis schwindet, und ein unbefleckter Geist der Gezeiten erscheint, bereit, seinen Segen zu gewähren."}},faq={{q="Warum muss ein Schamane den weiten Weg bis in den Silberwald auf sich nehmen?",a="Islen Wasserdeuter schickt Euch aus, um Euch der Verderbnis zu stellen, nicht bloß den Frieden zu ergründen. Der Küstenschrein westlich des Grabmals wurde von Lordaerons Seuche verdorben. Seine Heilung könnte die Wassergeister erwecken, die sich weigern, mit irgendjemand anderem zu sprechen.",al={"warum in den silberwald","warum übers meer reisen","warum wasserquest im silberwald"}},{q="Was geschieht, wenn Ihr das Brazier of Everfount benutzt?",a="Legt die Armschienen des besiegten Elementars und das verbliebene reinste Wasser in die Flamme. Islen hat Euch diesen Reinigungsritus gelehrt. Er reinigt das Becken und ruft einen reinen Wassergeist herbei, der bereit ist, seinen Segen zu gewähren.",al={"brazier of everfount ereignis","was bewirkt die feuerstelle","wie das becken reinigen"}},{q="Wer verdirbt den Wasserschrein im Silberwald?",a="Lordaerons noch immer schwelende Seuche hat das Wasser des Schreins verdorben. Verderbnis sickert von den Hügeln herab, verseucht die Quelle und macht die dort heimischen Wassergeister wild und feindselig.",al={"wer hat den schrein verdorben","warum ist die manifestation verderbt","wasserverderbnis im silberwald"}},{q="Was erhaltet Ihr nach Abschluss dieser Prüfung?",a="Die Reinigung des Brazier of Everfount ermöglicht Euch die Gemeinschaft mit einem reinen Wassergeist, der bereit ist, seinen Segen zu gewähren. Bringt Islen Wasserdeuter im Brachland einen Beweis der Reinigung, um Euer Wassertotem zu erhalten und die lange Prüfung abzuschließen.",al={"ruf des wassers belohnung","wassertotem freischalten","was gibt es als belohnung"}},{q="Wo genau liegt der Schrein?",a="Der Schrein steht an der Westküste des Silberwalds, jenseits des verseuchten Bergrückens direkt westlich des Grabmals.",al={"brazier of everfount standort","wo ist der schrein","silberwald schrein koordinaten"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Taurenschamanin, die an der Händlerküste des Brachlands südlich von Ratschet lebt. Als verehrte spirituelle Führerin lehrt sie junge Schamanen der Horde die schwierigen Riten, die sie auf das Wasser einstimmen.",al={"wer ist islen","islen wasserdeuter hintergrund","wasserlehrerin im brachland"}}},fx={["43e73964"]={q="Warum möchte Islen Wasserdeuter, dass dies erledigt wird?",a="Islen Wasserdeuter versucht, das Gleichgewicht der Elemente wiederherzustellen und Eure Verbindung zu den Wassergeistern zu erweitern. Der Schrein im Silberwald ist der Seuche erlegen, was die Verbindung zu den Geistern der Region unterbrochen hat. Indem Ihr diesen Ort reinigt, helft Ihr den gepeinigten Elementaren und beweist Euren Wert als Schamane, der in der Lage ist, sich sein Wassertotem zu verdienen.",al={"motiv von islen wasserdeuter","warum den wasserschrein reinigen","warum schickt islen mich in den silberwald"}},["4cf42c2b"]={q="Wozu dienen die Verderbte Manifestationsarmschienen?",a="Die Armschienen dienen als physische Verbindung zu dem gefallenen Elementar. Wenn sie zusammen mit dem reinsten Wasser der Sole auf das Becken der ewigen Quelle gelegt werden, ermöglichen sie es dem Reinigungsritual, zu wirken, die Verderbnis zu beseitigen und einen reinen Wassergeist hervorzulocken, damit Ihr mit ihm kommunizieren könnt.",al={"verwendung der verderbten manifestationsarmschienen","was mit den armschienen tun","becken armschienen"}},["585e30b0"]={q="Was ist die Verderbte Manifestation des Wassers?",a="Es ist ein Elementargeist, der durch die Seuche, die in die Wasserwege des Silberwalds einsickert, verdreht und krank gemacht wurde. Feindselig und in Agonie bewacht er den verseuchten Schrein, unfähig, Frieden zu finden oder mit Schamanen zu kommunizieren, bis seine verderbte physische Form besiegt ist.",al={"verderbte manifestation des wassers","was bekämpfe ich im silberwald","verderbtes wasserelementar"}},["35c6941a"]={q="Warum müsst Ihr diese Reinigung durchführen anstatt jemand anderes?",a="Diese Reise ist eine wesentliche Prüfung Eures schamanischen Pfades. Gewöhnliche Wachen können nicht mit den Elementen kommunizieren oder spirituelle Prüfungen überstehen, und Islen muss bleiben, um andere Initianden zu führen. Ein Schamane muss sich dem Zorn des Elementars stellen und das Gleichgewicht persönlich wiederherstellen, um eine unzerbrechliche Bindung zum Wasser zu schmieden.",al={"warum muss ich den schrein reinigen","warum keine wachen zum silberwald schicken","warum muss der spieler gehen"}}},fp="13,190,27.271.0,23.363.1,66.227.0,51.203.0,49.174.0,48.228.0,36.107.0,23.209.0"}
P.entries["quest:630"] = {n="Flaschenpost",s="Die Flaschenpost führt Euch auf eine Insel vor der Küste des Schlingendorntals, wo Prinzessin Poobah in Ketten wartet. King Mukla befehligt die Bestien der Insel und hält sie gefangen. Um sie zu befreien, braucht Ihr den Schlüssel zu ihrer Fessel.",h="Die Flaschenpost führt Euch auf eine Insel vor der Küste des Schlingendorntals, wo Prinzessin Poobah in...",kw={"jaguero island","king mukla","prinzessin poobah","fesselschlüssel","skymane","schlingendorntal"},sec={{t="Eine Gefangene auf der Insel",b="Auf einer Insel vor der Küste des Schlingendorntals wartet Prinzessin Poobah in Ketten. Die Flaschenpost hat Euch zu ihr geführt. King Mukla ist ein großer Skymane-Gorilla, der die Kreaturen befehligt, die auf der Insel umherstreifen. Er hält Poobah gefangen, und sie vertraut darauf, dass Ihr Euch dem Affen stellt und ihren Fesselschlüssel zurückbringt."},{t="Die Bestie im Südosten",b="Prinzessin Poobah sagt, dass ihr Entführer oft im Südosten der Insel umherstreift. King Mukla ist ein furchterregender Gegner. Ihn zu besiegen ist der einzige Weg, den Fesselschlüssel zu erlangen und Poobah zu befreien."},{t="Befreiung und Dankbarkeit",b="Der Schlüssel befreit Prinzessin Poobah von ihren Ketten und bewahrt sie vor dem, was sie als tiefe Schande empfindet. Sie kann Euch nicht die vollständige Aufnahme in ihren Stamm gewähren. Stattdessen bietet sie Euch ein Zeichen des Dankes für Euren Mut an."}},faq={{q="Wer ist Prinzessin Poobah?",a="Prinzessin Poobah ist eine Stammesangehörige, die auf einer Insel vor der Küste des Schlingendorntals in Ketten gefangen gehalten wird. Sie hat einen Hilferuf in einer Flasche ausgesandt und wartet auf jemanden, der es wagt, ihren Entführer zu bezwingen und ihre Fessel aufzuschließen.",al={"poobah","wer ist poobah","prinzessin poobah hintergrundgeschichte"}},{q="Wer hält Prinzessin Poobah gefangen?",a="King Mukla hält Prinzessin Poobah gefangen. Er ist ein gewaltiger Skymane-Gorilla, der die Bestien um sich herum auf der Insel befehligt.",al={"wer hat poobah gefangen genommen","poobahs entführer","king muklas gefangene"}},{q="Wo ist King Mukla zu finden?",a="Prinzessin Poobah sagt, dass King Mukla oft im Südosten der Insel umherstreift.",al={"wo ist mukla","muklas aufenthaltsort","king mukla finden"}},{q="Was wird benötigt, um Prinzessin Poobah zu befreien?",a="Um Prinzessin Poobah zu befreien, besiegt King Mukla und nehmt den Schlüssel zu ihrer Fessel an Euch. Bringt ihn zurück, um ihre Kette aufzuschließen.",al={"poobahs fesselschlüssel","wie poobah befreien","schlüssel zur befreiung von prinzessin poobah"}},{q="Wo gehört dieser Schritt in die Geschichte?",a="Dieser Schritt folgt auf den Hilferuf aus einer Flasche und führt Euch King Mukla gegenüber. Danach könnt Ihr Prinzessin Poobah von ihren Ketten befreien.",al={"flaschenpost questreihe","flaschenpost teil zwei","poobah questreihe"}}},fp="19,226,21.304.0,26.182.0,25.206.1,23.208.0,34.123.0,26.81.0,39.110.0,38.135.0"}
P.entries["quest:6301"] = {n="Zyklus der Wiedergeburt",s="In Sonnenfels sucht Tammra Windfeld Gaeasamenkörner, um das Steinkrallengebirge zu heilen. Sie bittet die Horde, sie am Mirkfallonsee zu sammeln, damit sie sie segnen und den geschädigten Boden des Gebirges wiederherstellen kann.",h="In Sonnenfels sucht Tammra Windfeld Gaeasamenkörner, um das Steinkrallengebirge zu heilen.",kw={"das verbrannte tal","zyklus der wiedergeburt","erdenmutter","gaeasamenkorn","mirkfallonsee","new life","steinkrallengebirge","sonnenfels","tammra windfeld"},ang={["class:Druid"]="Druiden dürften den Schwerpunkt auf natürliche Kreisläufe und die Aufzucht von Samen wiedererkennen. Kargen Boden wiederherzustellen erinnert an die Fürsorge von Cenarion.",["class:Shaman"]="Tammras Arbeit folgt der Berufung der Schamanen, das ökologische Gleichgewicht wiederherzustellen. Die Geister und die Erdenmutter können erneuern, was industrielle Ausbeutung zerstört.",["race:Tauren"]="Für die Shu'halo ist es eine geistige Pflicht gegenüber der Erdenmutter, den verwundeten Boden des Steinkrallengebirges zu heilen. Damit begegnen sie den Schäden durch rücksichtslosen Holzeinschlag und Kriege zwischen den Fraktionen."},sec={{t="Eine gezeichnete Wildnis",b="Holzeinschlag und Zusammenstöße zwischen rivalisierenden Fraktionen haben die Gipfel des Steinkrallengebirges gezeichnet. Wälder wurden versengt, abgeholzt oder in Asche gelegt. Für die Tauren in Sonnenfels ist der rasche Verfall der Natur eine tiefe Wunde. Schamanen wie Tammra Windfeld wenden sich dem erneuernden Kreislauf der Erdenmutter zu, während sie daran arbeiten, das Land zu heilen."},{t="Die Samen von Mirkfallon",b="Tammra sucht am Mirkfallonsee nördlich von Sonnenfels nach seltenen Gaeasamenkörnern. Robuste Samenkapseln wachsen an den Ufern nahe dem Wasser und bergen eine Widerstandskraft, die es nur im Steinkrallengebirge gibt. Sobald die Körner gesammelt sind, versieht Tammra jedes mit einem überlieferten schamanischen Segen. Der Segen weckt seine Kraft und beschleunigt sein Wachstum."}},faq={{q="Wozu werden Gaeasamenkörner gesammelt?",a="Gaeasamenkörner bergen die Lebenskraft, die Tammra Windfeld braucht, um geschädigtes Land wiederherzustellen. Sie segnet sie mit der Macht der Erdenmutter, damit sie rasch sprießen und die durch Industrie und Krieg verwüsteten Teile des Steinkrallengebirges erneuern können.",al={"warum gaeasamenkörner","wozu dienen gaeasamenkörner","zweck von zyklus der wiedergeburt"}},{q="Wo befinden sich die Gaeasamenkörner?",a="Gaeasamenkörner wachsen am Ufer des Mirkfallonsees, nördlich von Sonnenfels im Steinkrallengebirge. Sucht rund um den See im Erdreich nahe dem Wasser.",al={"fundort gaeasamenkorn","wo gaeasamenkörner finden","mirkfallonsee samen"}},{q="Wer ist Tammra Windfeld?",a="Tammra Windfeld ist eine Taurenschamanin in Sonnenfels. Sie arbeitet daran, das Steinkrallengebirge mit Segnungen der Erdenmutter zu heilen, nachdem Holzeinschlag und kriegerische Konflikte das Land verwüstet haben.",al={"wer ist tammra","tammra windfeld hintergrund"}},{q="Was tut Tammra, sobald die Samen zurückgebracht werden?",a="Wenn Tammra die zehn Gaeasamenkörner erhält, besingt sie sie und erfüllt sie mit schamanischer Energie. Das beschleunigt ihr Wachstum und bereitet sie darauf vor, an verwüsteten Orten eingepflanzt zu werden.",al={"was geschieht mit den samen","zyklus der wiedergeburt abgeben"}},{q="Welche Quest folgt auf Zyklus der Wiedergeburt?",a="Auf Zyklus der Wiedergeburt folgt New Life. Die gesegneten Samen werden ins verwüstete Verbrannte Tal getragen, um dort die Pflanzenwelt wiederherzustellen.",al={"folgequest von zyklus der wiedergeburt","nächste quest nach zyklus der wiedergeburt","was folgt auf zyklus der wiedergeburt"}},{q="Warum muss das Land des Steinkrallengebirges geheilt werden?",a="Krieg und großflächige Kahlschläge durch industrielle Holzunternehmen haben das Steinkrallengebirge geschädigt. In versengten Ödlanden und gezeichneten Tälern kann die Natur nur schwer aus eigener Kraft nachwachsen.",al={"warum ist das steinkrallengebirge verwüstet","was geschah mit dem steinkrallengebirge"}}},fx={a7be4203={q="Warum möchte Tammra Windfeld, dass Gaea-Samen gesammelt werden?",a="Tammra ist zutiefst betrübt über die unerbittliche Zerstörung, die durch industrielle Gier und Kriegführung im gesamten Steinkrallengebirge verursacht wurde. Holzfäller und Schlachten haben die Landschaft vernarbt, und sie glaubt, dass nur die wiederherstellende Kraft der Erdenmutter solche tiefen Wunden heilen kann. Indem sie die Samen sammelt und segnet, hofft sie, den natürlichen Kreislauf der Wiedergeburt zu erneuern und die zerstörte Wildnis wieder aufzufrischen.",al={"motiv von tammra","warum samen für tammra sammeln","grund von tammra windfeld"}}},fp="16,195,20.334.0,23.304.0,45.214.0,33.165.0,24.167.0,48.181.0,36.132.0,49.177.0"}
P.entries["quest:631"] = {n="Der Thandolübergang",s="Am Thandolübergang sucht Rhag Garmason nach einem vermissten Zwergkundschafter, nachdem eine Explosion den nördlichen Übergang zerstört hat. Der Dunkeleisenklan hat Dun Modr angegriffen, die Nachrichtenverbindung unterbrochen und die Verteidiger ohne Verstärkung zurückgelassen. Ol' Rustlocke weiß vielleicht, was die Explosion verursacht hat.",h="Am Thandolübergang sucht Rhag Garmason nach einem vermissten Zwergkundschafter, nachdem eine Explosion den...",kw={"dunkeleisen","dun modr","garmason","langzopf","rustlocke","übergang","thandol","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Thandolübergang der einzige Versorgungsweg über Land ist, der Sturmwind und Eisenschmiede mit den Allianzstreitkräften in Arathi und Hillsbrad verbindet.",["race:Dwarf"]="Als Zwerg seht Ihr die Zerstörung des Thandolübergangs vielleicht als Beleidigung zwergischer Steinmetzkunst und als Schlag Eurer verhassten Verwandten vom Dunkeleisenklan gegen Khaz Modan."},sec={{t="Donner über dem Übergang",b="Eine Explosion hat die Brücke zwischen dem Sumpfland und dem Arathihochland zerrissen. Bronzenbartsoldaten an der Grenze wurden von der Zerstörung erfasst, als Dunkeleisenzwerge Dun Modr angriffen. Ihre Reihen sind ausgedünnt, und ihre Festungen werden belagert. Langzopf der Grimmige führt die Überlebenden an, während sie gegen die Angreifer standhalten."},{t="Ein Kundschafter gen Osten",b="Langzopf schickte den erfahrenen Kundschafter Ebenezer Rustlocke aus, um die östliche Brücke zu untersuchen. Er sollte herausfinden, ob noch ein Übergang oder ein Weg nach Norden nutzbar war. Seit Tagen fehlt jede Nachricht von ihm. Dun Modr wird belagert, und Rhag Garmason und die Garnison haben zu wenige Soldaten, um die vom Feind besetzten Trümmer zu durchsuchen."},{t="Ein grausiger Fund",b="Ebenezer Rustlocke liegt tot zwischen den Trümmern der östlichen Brücke. Sein Leichnam und das Pergament in seiner Faust zeigen, dass er auf seinem Erkundungsgang in einem Hinterhalt der Dunkeleisen getötet wurde. Die Dunkeleisen bedrohen weiterhin die Verbindung zwischen Khaz Modan und Lordaeron."}},faq={{q="Was ist der Thandolübergang?",a="Der Thandolübergang überspannt die Schlucht zwischen dem nördlichen Sumpfland und dem Arathihochland. Diese Zwergenbrücke ist der wichtigste Landweg von Khaz Modan in die nördlichen Gebiete Lordaerons.",al={"thandol-übergang","was ist die thandol-brücke","brücke im sumpfland"}},{q="Wer hat den Thandolübergang angegriffen?",a="Der Dunkeleisenklan der Zwerge hat die Brücke und das nahe Dun Modr angegriffen. Mit Sprengstoff zerstörten sie den Übergang, legten den Reiseverkehr der Allianz lahm und überraschten die Bronzenbartverteidiger.",al={"wer hat die brücke gesprengt","explosion am thandol-übergang","wer hat dun modr angegriffen"}},{q="Wer ist Ol' Rustlocke?",a="Ebenezer Rustlocke war ein vertrauenswürdiger Zwergkundschafter im Dienst von Langzopf dem Grimmigen. Langzopf schickte ihn nach der Explosion aus, um die östliche Brücke zu untersuchen, und Streitkräfte der Dunkeleisen töteten ihn während seines Auftrags.",al={"ebenezer rustlocke","wer ist rustlocke","vermisster kundschafter"}},{q="Wo befindet sich Rhag Garmason?",a="Rhag Garmason befindet sich nahe Dun Modr, unmittelbar südlich des Thandolübergangs im nördlichen Sumpfland. Er hilft, die Verteidigung zu koordinieren, während die Garnison von Eisenschmiede abgeschnitten ist.",al={"rhag garmason standort","wo ist rhag","questgeber dun modr"}},{q="Warum hat Eisenschmiede keine Hilfe nach Dun Modr geschickt?",a="Der Angriff kam plötzlich, die Brücke ist zerstört, und Dun Modr wird belagert. Die abgeschnittenen Verteidiger sind zu stark beansprucht, um Boten zu entsenden oder Truppen abzuziehen, und verlassen sich deshalb auf durchreisende Reisende als Nachrichtenüberbringer.",al={"warum keine verstärkung","eisenschmiede hilfe sumpfland","dun modr verstärkung"}},{q="Was geschieht nach dem Fund von Rustlockes Leichnam?",a="Bei Rustlockes Überresten findet sich ein Pergament, das zeigt, dass Kam Tiefenzorn gleich jenseits des Übergangs Sprengstoff versteckt hatte. Das Pergament gibt den Anstoß, das Lager zu zerstören, bevor der Sprengstoff die verbliebene Brücke erreicht, und anschließend im Allianzlager in der Zuflucht Hilfe zu suchen.",al={"nächste quest nach rustlocke","thandol-übergang fortsetzung","nach dem thandolübergang"}}},fx={["60853ee9"]={q="Warum möchte Rhag Garmason, dass Ol' Rustlocke gefunden wird?",a="Eine massive Explosion riss durch den Thandol-Übergang und forderte viele Zwergenverteidiger noch vor dem Angriff der Dunkeleisenzwerge. In dem Chaos entsandte Longbraid Ol' Rustlocke, um die östliche Brücke auszukundschaften und zu sehen, ob die Position gehalten oder gesichert werden konnte, aber es sind Tage vergangen, ohne ein einziges Wort. Rhag Garmason und die Überlebenden müssen unbedingt das Schicksal von Rustlocke erfahren und ob die Brücke noch ihrer Verteidigung dienen kann.",al={"warum rustlocke finden","motiv von rhag garmason","warum nach rustlocke suchen"}},["8b9f1c8c"]={q="Warum braucht Rhag Garmason die Hilfe eines Abenteurers?",a="Dun Modr wird aktiv von Dunkeleisenzwergen belagert, und die überlebende Garnison ist bis über ihre Grenzen hinaus beansprucht. Da keine Verstärkung aus Eisenschmiede eintrifft und die Verluste stündlich zunehmen, können Rhag Garmason und seine Kameraden keine einzige Wache von ihren Verteidigungslinien entbehren, um einen Suchtrupp über die Brücke zu schicken.",al={"warum ich rhag garmason","warum können die zwerge rustlocke nicht finden","warum dun modr helfen"}}},fp="16,263,21.335.0,17.301.0,14.234.1,25.176.0,30.181.0,21.196.1,31.162.0,43.204.0,46.254.1"}
P.entries["quest:632"] = {n="Der Thandolübergang",s="Am Thandol-Übergang wartet Rhag Garmason auf Nachricht von einem vermissten Späher. Er schickte Abenteurer los, um nach Ol' Ebenezer Rustlocke zu sehen, nachdem der Zwerg vom gewaltigen Steinübergang keine Meldungen mehr gesandt hatte. Die Suche unter seinen Bögen könnte eine Bedrohung für die nördlichen Nachschublinien aufdecken.",h="Am Thandol-Übergang wartet Rhag Garmason auf Nachricht von einem vermissten Späher.",kw={"arathi","dunkeleisen","tiefenzorn","ebenezer rustlocke","rhag garmason","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Thandol-Übergang Eisenschmiede und Sturmwind mit den nördlichen Festungen der Allianz verbindet. Der Fund von Rustlocke ist für die Sicherheit des Kontinents von Bedeutung.",["race:Dwarf"]="Als Zwerg erfahrt Ihr, dass die Streitkräfte der Dunkeleisenzwerge weit nördlich der Sengenden Schlucht vorgedrungen sind. Ihr Eindringen bedroht Eure Verwandten in Eisenschmiede."},sec={{t="Rustlockes Wacht",b="Langzopf der Grimmige schickte Ebenezer Rustlocke los, um über den Bauzustand und die Sicherheit des Thandol-Übergangs zu wachen. Als die Meldungen des Spähers ausblieben, befürchtete man ein Verbrechen."},{t="Tiefenzorns Befehle",b="Unter den Bögen des Übergangs findet Ihr Rustlocke tot auf. Dunkeleisen-Invasoren überfielen ihn aus den Schatten heraus. Nahe Rustlockes verkrampften Fingern liegen schriftliche Befehle, die den Namen Tiefenzorn tragen. Das Pergament deutet auf gezielte Operationen der Dunkeleisenzwerge hin, die den Übergang destabilisieren sollen, und nicht auf einen zufälligen Raubüberfall oder ein vereinzeltes Grenzscharmützel. Als Ihr Garmason die Beweise bringt, geht die Garnison von einer Routinesuche zur dringenden Verteidigung im Krieg über."}},faq={{q="Wer war Ebenezer Rustlocke?",a="Ebenezer 'Ol' Rustlocke war ein Zwerg der Allianz, der ausgesandt wurde, um den Thandol-Übergang auszukundschaften und dort Wache zu halten. Dunkeleisenzwerge überraschten ihn und töteten ihn unter der Brücke.",al={"wer ist rustlocke","ol rustlocke","ebenezer rustlocke"}},{q="Wer hat Rustlocke getötet?",a="Dunkeleisen-Agenten überfielen Rustlocke unter dem Thandol-Übergang auf Befehl von Kam Tiefenzorn.",al={"wer hat rustlocke getötet","wer hat rustlocke überfallen","rustlockes leiche"}},{q="Was findet man bei Rustlockes Leiche?",a="Ein Pergament mit Tiefenzorns Befehlen liegt neben Rustlockes geballter Faust. Es hält geheime Pläne der Dunkeleisenzwerge gegen die nördliche Brücke fest.",al={"was war in seiner hand","tiefenzorns befehle","pergament bei rustlocke"}},{q="Wer ist Rhag Garmason?",a="Rhag Garmason ist ein Offizier der Allianz, der südlich des Thandol-Übergangs im Sumpfland stationiert ist. Er sichert den Verkehr zwischen den Zwergengebieten und dem Norden.",al={"rhag garmason","wer ist garmason"}},{q="Warum ist der Thandol-Übergang so stark umkämpft?",a="Der Thandolübergang ist die einzige Landbrücke, die Khaz Modan und das Sumpfland mit dem Arathihochland und Lordaeron verbindet. Die Allianz braucht ihn für ihre Nachschublinien.",al={"warum ist der thandol-übergang wichtig","bedeutung des thandol-übergangs"}},{q="Was geschieht, nachdem Ihr Rhag Garmason die Befehle übergeben habt?",a="Nachdem Ihr Rhag Garmason die Befehle übergeben habt, schickt er Euch los, um gleich jenseits des Übergangs im Arathihochland ein Sprengstofflager der Dunkeleisenzwerge zu zerstören und ihre Sabotage zu vereiteln.",al={"was geschieht als nächstes","folgeauftrag am thandol-übergang"}}},fx={d453191c={q="Warum müsst Ihr die Befehle von Rustlockes Leiche zurückbringen?",a="Ebenezer Rustlocke kann nicht mehr sprechen oder Warnungen überbringen, aber das Pergament, das neben seiner geballten Faust liegt, enthüllt, dass die Dunkeleisenzwerge einen aktiven Komplott gegen den Thandol-Übergang gestartet haben. Wenn Rhag Garmason nicht von dem Hinterhalt erfährt und die schriftlichen Befehle von Tiefenzorn inspiziert, werden die Allianz-Streitkräfte, die die Brücke bewachen, blind für die Sabotage bleiben, die sich direkt unter ihren Füßen entfaltet.",al={"warum rustlockes leiche melden","warum tiefenzorns befehle nehmen","motiv von rustlockes leiche"}}},fp="16,267,17.155.0,17.446.1,27.172.1,21.96.1,34.142.1,21.155.0,45.165.0,54.168.1"}
P.entries["quest:6321"] = {n="Nachschub für Brill",s="Am Grabmal sucht Todeswache Podrig Waffen für eine Garnison, die von den Kämpfen zermürbt ist. Er schickt eine Anforderung nach Unterstadt, während Bestien, die Geißel und andere Bedrohungen ihre Vorräte aufzehren.",h="Am Grabmal sucht Todeswache Podrig Waffen für eine Garnison, die von den Kämpfen zermürbt ist.",kw={"fledermausführer","todeswache","gordon wendheim","hadrec","karos razok","podrig","anforderung","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde nutzt Ihr Flugrouten zwischen Garnisonen und Hauptstädten, um die Verteidigung in umkämpften Regionen zu koordinieren.",["race:Undead"]="Als Untoter helft Ihr, Außenposten der Verlassenen wie das Grabmal zu unterhalten. Sie erweitern den Einfluss der Verlassenen über Tirisfal hinaus und sichern die umliegende Wildnis für die Dark Lady."},sec={{t="Waffen für die Front",b="Todeswache Podrig sagt, das Grabmal habe ordentliche Vorräte, doch die Kämpfe im Silberwald zehren sie stetig auf. Wilde Bestien, Überreste der Geißel und andere örtliche Bedrohungen beschädigen Waffen und Rüstungen oder lassen sie nach Scharmützeln zurück. Auf Befehl von Executor Hadrec verfasst Podrig eine Anforderung an Gordon Wendheim, einen Waffenhändler in Unterstadt. Ersatzwaffen und Rüstungen helfen den Verlassenen, ihre gefährdeten Stützpunkte jenseits von Tirisfal zu halten."},{t="Das Flugnetz",b="Auf den Straßen des Silberwalds lassen sich wichtige Nachrichten und Vorräte nur langsam und unter großen Gefahren befördern. Deshalb verschicken die Verlassenen sie mit abgerichteten Vampirfledermäusen. Am Grabmal betreut Karos Razok die Fledermäuse und verbindet die dortigen Soldaten mit dem Flugnetz von Unterstadt. Diese Routen verbinden entlegene Garnisonen mit Sylvanas' Hauptstadt."}},faq={{q="Welchen Zweck hat Podrigs Anforderungsliste?",a="Executor Hadrec befahl Todeswache Podrig, Waffen für das Grabmal anzufordern. Allgemeine Vorräte waren ausreichend vorhanden, doch Waffen mussten jene ersetzen, die im Kampf gegen die Geißel und andere Bedrohungen des Waldes zerbrachen oder verloren gingen.",al={"warum podrigs anforderungsliste","was ist podrigs anforderung","zweck von nachschub für brill"}},{q="Wer ist Gordon Wendheim?",a="Gordon Wendheim ist ein Waffenhändler in Unterstadt. Podrig richtet die Anforderung neuer Waffen für das Grabmal an ihn.",al={"wer ist gordon wendheim","gordon wendheim unterstadt"}},{q="Wer ist Karos Razok?",a="Karos Razok betreut die Fledermäuse am Grabmal. Er beaufsichtigt die Schreckensfledermäuse, die Boten, Späher und Vorräte durch Lordaeron befördern.",al={"karos razoks aufgabe","wer ist der fledermausführer"}},{q="Warum Fledermäuse statt Straßenkuriere einsetzen?",a="Die Straßen des Silberwalds sind gefährlich, denn feindselige Bestien, die Geißel und andere Fraktionen bedrohen Kuriere. Fledermausrouten bieten eine schnellere und sicherere Verbindung nach Unterstadt.",al={"warum nach unterstadt fliegen","warum fledermäuse nutzen"}},{q="Welche Bedrohungen gibt es für das Grabmal?",a="Das Grabmal wird von verbliebenen Untoten der Geißel, Worgen, wilden Bestien und menschlichen Fraktionen der Region bedroht. Die Garnison braucht stetig Ersatzausrüstung, um kampfbereit zu bleiben.",al={"bedrohungen für das grabmal","warum brauchen todeswachen waffen"}},{q="Wohin führt diese Aufgabe als Nächstes?",a="Karos Razok kann einen Flug nach Unterstadt organisieren, wo die Anforderung an Gordon Wendheim gerichtet ist.",al={"welche quest folgt","was folgt nach nachschub für brill"}}},fx={f1c1132b={q="Warum muss Todeswache Podrig diesen Versorgungsbefehl ausgeliefert haben?",a="Todeswache Podrig führte auf Befehl von Exekutor Hadrec eine Bestandsaufnahme durch, um sicherzustellen, dass das Grabmal weiterhin vollständig bewaffnet bleibt. Während die allgemeinen Vorräte stabil sind, haben laufende Scharmützel im Silberwald gegen die Geißel und andere umherstreifende Bedrohungen die Wachen viele ihrer Waffen im Feld gekostet. Um zu verhindern, dass der Außenposten wehrlos wird, muss Podrig diese Anforderung dringend an Gordon Wendheim in der Unterstadt senden, damit Ersatzwaffen beschafft werden können.",al={"warum will podrig das erledigt haben","motiv von podrig","warum waffen bestellen"}},ade30847={q="Warum schickt Podrig Euch, anstatt die Lieferung selbst zu übernehmen?",a="Podrig ist im aktiven Wachdienst und erhält zusammen mit Exekutor Hadrec die Verteidigung des Grabmals aufrecht. Da feindselige Geißel in den umliegenden Wäldern umherstreifen, wird jede Todeswache benötigt, um den Perimeter zu sichern und das Lager zu halten. Ein rüstiger Reisender bietet sich als idealer Bote an, um mit dem Fledermausmeister in Kontakt zu treten, ohne einen Soldaten von seinem Posten abzuziehen.",al={"warum schickt er mich","warum geht podrig nicht selbst","warum auf einen abenteurer verlassen"}}},fp="23,178,21.436.0,18.305.0,38.219.0,22.115.0,19.134.0,38.175.0,37.161.0,31.112.0"}
P.entries["quest:6322"] = {n="Michael Garrett",s="In Unterstadt wartet Michael Garrett auf eine Kiste für das Grabmal. Gordon Wendheim packt im Handwerksviertel Feldvorräte, und Ihr bringt sie zu Garrett, damit die Fledermäuse der Verlassenen sie in Richtung Silberwald tragen.",h="In Unterstadt wartet Michael Garrett auf eine Kiste für das Grabmal.",kw={"fledermausführer","flugmeister","gordon wendheim","gordons kiste","michael garrett","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Für Reisende aus Kalimdor ist das Fledermausnetz der Verlassenen der schnellste Weg durch den Norden der Östlichen Königreiche.",["race:Undead"]="Die von Führern wie Michael Garrett betriebene Versorgung aus der Luft hilft, Sylvanas' Präsenz jenseits von Tirisfal aufrechtzuerhalten."},sec={{t="Versorgung der Außenposten",b="Die Verlassenen schicken Vorräte aus Unterstadt zu Außenposten wie dem Grabmal im Silberwald. Im Handwerksviertel packt Gordon Wendheim Feldvorräte in eine Kiste. Der Landweg durch verseuchte Wälder ist langsam, und Überreste der Geißel oder wilde Bestien könnten die Fracht überfallen."},{t="Schwingen der Verlassenen",b="Die Verlassenen umgehen gefährliche Straßen mit gefangenen Vampirfledermäusen, die von kundigen Führern gezüchtet und versorgt werden. Michael Garrett betreut die Fledermäuse von seinem Horst im Handwerksviertel von Unterstadt aus. Wenn Ihr ihm die Fracht bringt, kann er sie für den Flug über die Hügel in Richtung Silberwald auf eine Fledermaus schnallen. Die Fledermäuse verbinden die Hauptstadt mit ihren Außenposten."}},faq={{q="Wer ist Michael Garrett?",a="Michael Garrett betreut Fledermäuse im Handwerksviertel von Unterstadt. Er organisiert Reisen und Luftlieferungen zwischen der Hauptstadt der Verlassenen und verbündeten Flugmeistern in ganz Lordaeron.",al={"michael garrett","fledermausführer unterstadt","wer ist garrett"}},{q="Was ist in Gordons Kiste?",a="Gordon Wendheims Kiste enthält Feldvorräte für die Streitkräfte der Verlassenen, die am Grabmal im Silberwald stationiert sind.",al={"gordons kiste","welche vorräte","kiste grabmal"}},{q="Warum Fledermäuse statt Karren oder Pferde?",a="Die Straßen sind gefährlich, und abgerichtete Riesenfledermäuse fliegen viel schneller und umgehen dabei Hinterhalte am Boden.",al={"warum fledermausflug","warum fledermäuse nutzen","vorräte per lufttransport"}},{q="Wohin geht die Lieferung nach Michael Garrett?",a="Nachdem Michael Garrett Gordons Kiste erhalten hat, wird die Fracht für den Flug zum Fledermausführer am Grabmal im Silberwald vorbereitet.",al={"nächster schritt","nach michael garrett","wohin fliegen fledermäuse"}},{q="Wo ist Michael Garrett in Unterstadt zu finden?",a="Michael Garrett ist im südwestlichen Teil des Handwerksviertels zu finden, wo die Fledermäuse vom Grabmal landen.",al={"wo ist garrett","fledermausführer finden","standort flugmeister unterstadt"}},{q="Müsst Ihr zuvor schon am Grabmal gewesen sein?",a="Um die Lieferung auf einer Fledermaus zu begleiten, müsst Ihr mit dem Flugmeister am Grabmal gesprochen haben, um die Route freizuschalten. Andernfalls reist Ihr zu Fuß dorthin.",al={"flugroute zum grabmal erforderlich","sofort fliegen möglich"}}},fx={["2851daa3"]={q="Warum möchte Gordon Wendheim, dass dies erledigt wird?",a="Gordon Wendheim ist damit beauftragt, lebenswichtige logistische Nachschubgüter zu koordinieren, die für Das Grabmal bestimmt sind, den Außenposten der Verlassenen im Silberwald. Da er an seinem Handelsposten in der Unterstadt bleiben muss, um die Waren zu verwalten, benötigt er Euch, damit Ihr die gepackte Kiste an Michael Garrett übergebt, sodass sie schnell über deren Luftkurierroute verschickt werden kann.",al={"warum gordons kiste versenden","gordon wendheim motiv","warum kiste zu michael garrett bringen"}}},fp="15,221,22.281.0,21.321.0,23.175.0,26.112.0,40.103.0,49.146.0,48.120.0,60.155.0"}
P.entries["quest:6323"] = {n="Flug nach Unterstadt",s="Vom Grabmal bringt ein Kurier Podrigs Waffenanforderung nach Unterstadt. Eine Fledermaus der Furcht trägt die Nachricht über den Silberwald zur Hauptstadt der Verlassenen.",h="Vom Grabmal bringt ein Kurier Podrigs Waffenanforderung nach Unterstadt.",kw={"fledermaus der furcht","flugmeister","gordon wendheim","karos razok","podrigs anforderungsliste","flug nach unterstadt","das grabmal","handwerksviertel"},ang={["faction:Horde"]="Als Mitglied der Horde reist Ihr mithilfe ihrer Flugmeister schnell durch die Wildnis. Sie verbinden die Gebiete der Horde.",["profession:Blacksmithing"]="Als Schmied könnt Ihr sehen, wie Gordon Wendheim dabei hilft, Lordaerons Waffen scharf und kriegsbereit zu halten.",["race:Undead"]="Als Untoter könnt Ihr sehen, wie das Netz der Dunklen Fürstin den Silberwald mit der Hauptstadt verbindet. Es hält abgelegene Garnisonen mit der Industrie von Unterstadt in Verbindung."},sec={{t="Schwingen über dem Silberwald",b="Karos Razok betreut die Fledermäuse der Furcht beim Grabmal im Silberwald. Die Fledermäuse befördern Boten und Nachschub zwischen der Hauptstadt der Verlassenen und ihren Außenposten an der Front. Auf den Straßen darunter drohen Gefahren durch feindselige Bestien, Mondwutworgen und Überreste der Geißel. So bieten die Fledermäuse militärischen Anforderungen einen schnellen Weg in die Hauptstadt."},{t="Waffen für die Front",b="Im Handwerksviertel von Unterstadt überbringt der Kurier Podrigs Ausrüstungsanforderung an Gordon Wendheim. Der Waffenschmied bereitet Waffen für die Sache der Dunklen Fürstin vor. Er versorgt Außenposten wie das Grabmal mit kampfbereiten Waffen. Diese Außenposten verteidigen die junge Nation der Verlassenen gegen die Feinde, die sie umgeben."}},faq={{q="Welchen Zweck hat dieser Flug nach Unterstadt?",a="Der Flug bringt die Waffenanforderung von Todeswache Podrig vom Grabmal zu Gordon Wendheim im Handwerksviertel von Unterstadt. Er zeigt neuen Helden auch, wie sie das Flugnetz der Verlassenen nutzen.",al={"warum nach unterstadt fliegen","flug nach unterstadt ziel","podrigs anforderungsliste verwendung"}},{q="Wer ist Karos Razok?",a="Karos Razok betreut die Fledermäuse der Furcht beim Grabmal im Silberwald. Die Fledermäuse befördern Boten und Nachschub der Verlassenen nach Unterstadt und von dort zurück.",al={"karos razok aufgabe","wer ist der fledermausmeister beim grabmal"}},{q="Wer ist Gordon Wendheim?",a="Gordon Wendheim ist ein Waffenschmied der Verlassenen im Handwerksviertel von Unterstadt, nahe der Landeplattform des Fledermausführers. Er hält Waffen für Lady Sylvanas' Fronttruppen sauber, scharf und einsatzbereit.",al={"gordon wendheim","wo ist gordon wendheim"}},{q="Warum nutzen die Verlassenen Fledermäuse als Transportmittel?",a="Die Verlassenen nutzen Fledermäuse der Furcht, um gefährliches Gelände schnell zu überfliegen. Sie durchqueren Lordaerons verseuchten Himmel über Bedrohungen wie wilden Worgen, feindseligen rot hides und der Geißel.",al={"warum fledermäuse","flugreittiere der verlassenen"}},{q="Was geschieht nach der Lieferung?",a="Nachdem Gordon Wendheim die Anforderung erhalten hat, schickt er Kuriere zu Michael Garrett, dem Fledermausführer von Unterstadt. Sie richten eine Rückflugverbindung zum Grabmal ein.",al={"what comes next","folgequest zu flug nach unterstadt"}},{q="Wo landet die Fledermaus der Furcht in Unterstadt?",a="Die Fledermaus der Furcht landet auf dem erhöhten Fledermaushorst im Zentrum des Handwerksviertels von Unterstadt, nahe den Handwerkern und Versorgungshändlern der Stadt.",al={"fledermauslandeplatz unterstadt","wo landet die fledermaus"}}},fx={d629dc0f={q="Warum will Karos Razok, dass dies erledigt wird?",a="Als der Flugmeister, der im Grabmal stationiert ist, überwacht Karos Razok das Luftkuriernetzwerk, das den Silberwald mit der Hauptstadt verbindet. Außenposten wie Das Grabmal sind vollständig auf stetige Nachschubwege und schnelle Korrespondenz angewiesen, um gegen die umliegenden Bedrohungen zu überleben. Indem Ihr die Ausrüstungsanforderung von Todeswache Podrig direkt zu den Waffenlieferanten in der Unterstadt bringt, stellt Ihr sicher, dass die Wachen an der Front, die das Reich verteidigen, die dringend benötigten Waffen und Rüstungen erhalten.",al={"warum podrigs bestellung schicken","karos razok motiv","warum ritt zur unterstadt"}}},fp="21,158,21.325.0,16.313.0,52.193.0,19.148.0,22.194.0,41.178.0,43.156.0,47.139.0"}
P.entries["quest:6324"] = {n="Rückkehr zu Podrig",s="In Unterstadt tragt Ihr Waffen für das Grabmal, nachdem Ihr eine Depesche in die Hauptstadt gebracht habt. Fledermäuse der Verlassenen tragen Euch durch Lordaeron zu Todeswache Podrig.",h="In Unterstadt tragt Ihr Waffen für das Grabmal, nachdem Ihr eine Depesche in die Hauptstadt gebracht habt.",kw={"fledermausmeister","gordons kiste","karos razok","michael garrett","podrig","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Versorgungswege aufrechtzuerhalten, die Unterstadt mit abgelegenen Außenposten auf dem gesamten nördlichen Kontinent verbinden.",["race:Undead"]="Als Untoter helft Ihr, die vorgeschobenen Garnisonen mit Waffen zu versorgen, um Lordaeron zu verteidigen und das junge Reich von Königin Sylvanas zu sichern."},sec={{t="Die Versorgungslinie von Unterstadt",b="Todeswache Podrigs Garnison im Grabmal braucht Waffen aus Unterstadt. Ihre Schildwachen im Silberwald stehen Worgen, Überresten aus Dalaran und Nachzüglern der Geißel gegenüber. Neue Waffen helfen den Verlassenen, die Region zu halten und den Außenposten einsatzbereit zu halten."},{t="Schwingen der Verlassenen",b="Fledermausmeister Michael Garrett betreut den zentralen Horst im Handwerksviertel von Unterstadt. Die Fledermäuse der Verlassenen kennen den Rückweg in die Hauptstadt, doch vor einem Flug zu einem entfernten Außenposten sprecht Ihr mit örtlichen Führern wie Karos Razok. Indem Ihr Gordons Kiste durch Lordaeron tragt, verbindet Ihr Unterstadts Versorgung mit seinen verstreuten Festungen."}},faq={{q="Was ist in Gordons Kiste?",a="Gordons Kiste enthält neue Waffen, die in Unterstadt für die Todeswachen im Grabmal gefertigt wurden. Sie stehen Bedrohungen in der Nähe gegenüber.",al={"inhalt von gordons kiste","was wird an podrig geliefert"}},{q="Wer ist Todeswache Podrig?",a="Todeswache Podrig ist ein Soldat der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er beaufsichtigt die Versorgung und Verteidigung der Garnison.",al={"podrig","wer ist podrig"}},{q="Wer ist Michael Garrett?",a="Michael Garrett ist der Fledermausmeister der Verlassenen im Handwerksviertel von Unterstadt. Er koordiniert die Flugrouten durch Lordaeron.",al={"michael garrett","fledermausmeister in unterstadt"}},{q="Warum müsst Ihr mit einem Fledermausmeister sprechen, bevor Ihr irgendwohin fliegt?",a="Die Fledermäuse der Verlassenen kennen den Rückweg zum zentralen Horst in Unterstadt. Für einen Hinflug legt Ihr zuerst mit einem örtlichen Führer eine Route fest, damit die Fledermaus ihr Ziel sicher erreicht.",al={"regeln für flugrouten","wie funktionieren fledermausführer"}},{q="Warum ist die Versorgung des Grabmals so wichtig?",a="Das Grabmal ist der wichtigste vorgeschobene Stützpunkt der Verlassenen im Silberwald. Es sichert ihre Präsenz gegen Worgenrudel, Bedrohungen durch Moonrage und Streitkräfte aus Dalaran in der Gegend.",al={"warum ist das grabmal wichtig","bedeutung des grabmals"}},{q="Wer ist Karos Razok?",a="Karos Razok ist der Fledermausmeister im Grabmal im Silberwald. Er betreut die dort untergebrachten Fledermäuse, die den Außenposten mit Unterstadt verbinden.",al={"karos razok","fledermausmeister im grabmal"}}},fx={["02244cab"]={q="Warum möchte Michael Garrett, dass dies erledigt wird?",a="Als Fledermausmeister der Unterstadt überwacht Michael Garrett den Luftverkehr und die Kurierrouten durch die Gebiete der Verlassene. Todeswache Podrig und die Soldaten, die das Grabmal im Silberwald halten, benötigen dringend frische Rüstungen aus der Hauptstadt. Garrett stellt sicher, dass diese lebenswichtigen Waffen effizient über das Fledermausnetzwerk versandt werden, um die Vorposten der Dunklen Fürstin gegen nahe Bedrohungen zu stärken.",al={"warum michael garrett kiste","garrett motiv return to podrig","warum kiste an das grabmal senden"}},eed737b1={q="Warum schickt Michael Garrett Euch, anstatt selbst zu gehen?",a="Garrett muss am Fledermaushorst der Unterstadt stationiert bleiben, um sich um die Bestien zu kümmern und die Flüge in die Hauptstadt und aus ihr heraus zu koordinieren. Da Ihr ein fähiger Kurier seid, der ohnehin in Richtung Silberwald unterwegs ist, stellt das Anvertrauen der Kiste sicher, dass die Lieferung erfolgt, ohne wertvolle Flugmeister oder Wachen von ihren essenziellen Posten abzuziehen.",al={"warum ich","warum liefert garrett sie nicht selbst","warum ich return to podrig"}}},fp="16,163,25.241.0,21.324.0,26.120.0,25.138.0,23.122.0,65.184.0,44.169.0,19.139.0"}
P.entries["quest:633"] = {n="Der Thandolübergang",s="Am Thandol-Übergang gefährdet ein Mord Eisenschmiedes Straße nach Norden. Ebenezer Rustlocke ist tot, und Rhag Garmason hat Sprengstoff gefunden, den Kam Tiefenzorn versteckt hat.",h="Am Thandol-Übergang gefährdet ein Mord Eisenschmiedes Straße nach Norden.",kw={"arathihochland","dunkeleisenzwerge","ebon rustlocke","sprengstoff","kam tiefenzorn","magni bronzebart","rhag garmason","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Den Übergang zu halten, ist für die Sicherheit des Kontinents entscheidend. Fällt der Übergang, wird es weitaus gefährlicher, Armeen und Nachschub der Allianz nach Arathi und Lordaeron zu bringen.",["profession:Engineering"]="Als Ingenieur könnt Ihr die Zerstörungskraft von Deepfurys Munitionslager erkennen. Es wurde angelegt, um gewaltiges zwergisches Steinwerk im Stil der Titanen zu sprengen.",["race:Dwarf"]="Für die Söhne Eisenschmiedes sichert die Verteidigung des Thandol-Übergangs King Magnis Lebensader zu den Verbündeten im Norden. Sie versetzt auch den Unterwanderern der Dunkeleisenzwerge einen Schlag, die ihr eigenes Volk verraten haben."},sec={{t="Ein Komplott enthüllt",b="Ein geborgenes Dokument enthüllt das Verbrechen unter dem Thandol-Übergang. Ebenezer Rustlocke wurde im Unterbau der Brücke ermordet. Die Papiere enthüllen mehr: Kam Tiefenzorn, der Agitator der Dunkeleisenzwerge, der zuerst einen Teil der Brücke zerstörte, hat nicht aufgehört. Sein Netzwerk versteckte ein weiteres Lager schwerer Munition gleich jenseits der nördlichen Grenze im Arathihochland, bereit, die Zerstörung zu vollenden."},{t="Die Lebensader retten",b="Der Übergang verbindet Khaz Modan und Sturmwind mit den vom Krieg zerrütteten Gebieten im Norden. Rhag Garmason befiehlt einen sofortigen Angriff auf das Sabotagelager in Arathi, bevor Deepfurys Verschwörer es nutzen können. Die Zerstörung der Munition bannt die unmittelbare Gefahr und hält Eisenschmiedes Straße nach Norden offen. Doch Garmason hat noch immer zu wenige Truppen, um die Bresche zu verteidigen."}},faq={{q="Wer ist Kam Tiefenzorn?",a="Kam Tiefenzorn ist der Drahtzieher der Dunkeleisenzwerge hinter der Sabotage am Thandol-Übergang. Nachdem er den ersten Bogen zum Einsturz gebracht hatte, versteckte er jenseits der Schlucht im Arathihochland weiteren Sprengstoff, um den Rest der Brücke zu zerstören.",al={"kam tiefenzorn","wer sprengte den thandol-übergang","drahtzieher am thandol-übergang"}},{q="Warum ist der Thandol-Übergang strategisch so wichtig?",a="Der Übergang ist die einzige Landbrücke über die gewaltige Schlucht zwischen dem Sumpfland und dem Arathihochland. Fällt er, verliert die Allianz ihren wichtigsten Versorgungsweg über Land zwischen Eisenschmiede, Sturmwind und ihren Verbündeten, die im nördlichen Lordaeron ihre Stellungen halten.",al={"warum ist der thandol-übergang wichtig","geschichte des thandol-übergangs"}},{q="Was geschah mit Ebenezer Rustlocke?",a="Ebenezer Rustlocke war ein Verteidiger Eisenschmiedes, der unter der Brücke ermordet wurde. Seine Ermittlungen und die geborgenen Papiere führten Rhag Garmason zu Deepfurys verborgenem Sprengstofflager.",al={"ebon rustlockes tod","wer war rustlocke"}},{q="Wo ist das Sprengstofflager versteckt?",a="Der Sprengstoff war gleich jenseits des Übergangs auf der Seite des Arathihochlands versteckt. Deepfurys Verschwörer konnten ihn schnell zum verbliebenen Brückenbauwerk bringen.",al={"fundort des sprengstoffs","wo ist der sprengstoff","fundort des lagers"}},{q="Wer befiehlt die Zerstörung des Sprengstoffs?",a="Rhag Garmason, ein am Thandol-Übergang auf der Seite des Sumpflands stationierter Zwergenoffizier, befiehlt, das Lager zu finden und zu sprengen. Er will Rustlockes Opfer ehren und die verbliebene Brücke schützen.",al={"wer vergibt diese quest","rhag garmason"}},{q="Was geschieht nach der Zerstörung der Munition?",a="Mit der Zerstörung der Munition endet die unmittelbare Sabotagegefahr. Rhag Garmason weiß, dass seine Garnison die beschädigte Brücke ohne Hilfe nicht auf Dauer halten kann. Während er auf Eisenschmiedes Reserven wartet, schickt er ein Gesuch um Verstärkung an Captain Nials im Allianzlager in der Zuflucht im Arathihochland.",al={"was folgt nach dem thandol-übergang","quest hilfegesuch an die allianz"}}},fx={a60c1dfd={q="Warum möchte Rhag Garmason, dass die Sprengstoffe zerstört werden?",a="Rhag Garmason erfuhr aus Rustlockes geborgenem Pergament, dass Kam Tiefenzorn plante, eine weitere Explosion mit einem versteckten Vorrat auf der anderen Seite der Brücke auszulösen. Einer der Übergänge des Thandol-Übergangs ist bereits zerstört; wenn es den Dunkeleisen-Verschwörern gelingt, den verbleibenden Teil zu sprengen, wird die lebenswichtige Allianz-Versorgungsroute, die Khaz Modan mit Lordaeron und dem Arathihochland verbindet, vollständig unterbrochen werden.",al={"motiv von rhag garmason","warum sprengstoffe zerstören","warum sprengstoffe am thandol-übergang zerstören"}},b9ac4adc={q="Warum schickt Rhag Garmason einen Abenteurer anstatt seiner eigenen Wachen?",a="Rhag und die wenigen Zwergenverteidiger am Brückenkopf sind kritisch überbeansprucht und halten die Position gegen feindliche Einfälle, während sie verzweifelt auf das Eintreffen von Verstärkungen warten. Da Ebenezer Rustlocke bereits den Verschwörern zum Opfer gefallen ist, kann Rhag niemanden von der Linie entbehren, um in das von Feinden besetzte Gebiet in Arathi zu schlüpfen, was Euch zu ihrer einzigen Hoffnung macht, eine Katastrophe abzuwenden.",al={"warum ich","warum mich schicken","warum schickt rhag keine wachen"}}},fp="16,162,15.391.0,19.348.1,20.212.0,47.250.0,36.178.1,40.164.0,46.197.0,47.318.1"}
P.entries["quest:634"] = {n="Hilfegesuch an die Allianz",s="Am zerstörten Thandol-Übergang überbringt Hilfegesuch an die Allianz Dun Modrs verzweifelten Hilferuf. Infiltratoren der Dunkeleisen haben die Garnison niedergemetzelt, und die überlebenden Zwerge bitten die Menschenstreitkräfte in der Zuflucht um Hilfe, obwohl die Allianz kaum Kräfte entbehren kann.",h="Am zerstörten Thandol-Übergang überbringt Hilfegesuch an die Allianz Dun Modrs verzweifelten Hilferuf.",kw={"arathihochland","captain nials","dunkeleisen","dun modr","langzopf","die zuflucht","rhag garmason","stromgarde","thandol-übergang"},ang={["faction:Alliance"]="Für die Allianz zeigt dieser Austausch, wie zersplittert ihre Gebiete im Norden der Östlichen Königreiche weiterhin sind. Die örtlichen Garnisonen führen getrennte, verzweifelte Kämpfe ohne gemeinsame Reserven.",["race:Dwarf"]="Die Zwerge schmerzt Dun Modrs Isolation. Selbst ihre langjährigen menschlichen Verbündeten werden zu sehr bedrängt, um ihnen beizustehen.",["race:Human"]="Als menschlicher Reisender erlebt Ihr Captain Nials' Kummer, während er die Verbundenheit innerhalb der Allianz gegen Stromgardes Überleben abwägt."},sec={{t="Ein Ruf über die Kluft",b="Dun Modr liegt in Trümmern, und Zwerge der Dunkeleisen haben den Thandol-Übergang sabotiert. Die Überlebenden halten sich an einem Brückenkopf am nördlichen Rand des Sumpflands. Die Hauptreserven aus Eisenschmiede sind noch nicht eingetroffen, also blicken Rhag Garmason und Langzopf der Grimmige nach Norden ins Arathihochland. Dort erfahren sie, dass Streitkräfte der Allianz in der Zuflucht lagern. Garmason schickt einen Boten über die zerstörte Brücke, um Captain Nials um dringende militärische Hilfe zu bitten."},{t="Stromgardes Notlage",b="In der Zuflucht bekundet Captain Nials Langzopfs Soldaten sein Mitgefühl, kann aber keinen einzigen Kämpfer entbehren. Stromgarde liegt in Trümmern, überrannt von Schurken des Syndikats, Boulderfist-Ogern und Witherbark-Trollen. Die überlebenden Verteidiger widmen sich der Rückeroberung ihrer angestammten Hauptstadt. Durch seine Ehre gebunden und vom eigenen verzweifelten Kampf bedrängt, lässt Nials ausrichten, dass die Zwerge am Übergang allein standhalten müssen."}},faq={{q="Wer schickt das Hilfegesuch an die Zuflucht?",a="Nahe dem zerstörten Brückenkopf des Thandol-Übergangs an der Grenze zum Sumpfland schickt Rhag Garmason das Hilfegesuch für Langzopf den Grimmigen und Dun Modrs verbliebene Verteidiger.",al={"wer vergibt hilfegesuch an die allianz","rhag garmason quest","wer bittet um hilfe"}},{q="Warum brauchen die Zwerge Hilfe aus der Zuflucht?",a="Infiltratoren des Dunkeleisenklans haben Dun Modr angegriffen und den Thandol-Übergang sabotiert. Während die Überlebenden auf die starken Reservetruppen aus Eisenschmiede warten, fehlen ihnen die nötigen Kämpfer, um ihre Siedlung allein zurückzuerobern und den Übergang zu sichern.",al={"warum hilfe der allianz nötig","warum die zuflucht fragen","dun modr verstärkung"}},{q="Warum weigert sich Captain Nials, Soldaten zu schicken?",a="Captain Nials kann keine Truppen entbehren, weil Stromgarde in Trümmern liegt. Die Menschenstreitkräfte in der Zuflucht widmen sich der Rückeroberung der Stadt vom Syndikat, den Ogern und den Waldtrollen.",al={"warum keine hilfe von nials","warum die zuflucht ablehnt","captain nials antwort"}},{q="Wo liegt die Zuflucht?",a="Die Zuflucht liegt etwas abseits der Hauptstraße im zentralen Arathihochland, nördlich des Thandol-Übergangs zwischen dem Sumpfland und Arathi.",al={"zuflucht lage","wo ist captain nials","wie die zuflucht finden"}},{q="Was ist mit Dun Modr geschehen?",a="Nachdem sich der Dunkeleisenklan durch die Berge eingeschlichen hatte, um den Landweg zwischen den südlichen Zwergenlanden und den nördlichen Allianzgebieten zu kappen, überrannte und plünderte er Dun Modr.",al={"dun modr hintergrundgeschichte","was geschah mit dun modr","wer griff dun modr an"}},{q="Was geschieht, nachdem Captain Nials das Gesuch ablehnt?",a="Captain Nials übermittelt Langzopf dem Grimmigen sein Bedauern und bestätigt, dass keine Verstärkung der Menschen kommen wird. Die überlebenden Zwerge an der Brücke müssen sich auf ihren eigenen Einfallsreichtum, umherziehende Abenteurer und die ferne Verstärkung aus Eisenschmiede verlassen.",al={"was folgt auf hilfegesuch an die allianz","nächste quest nach dem hilfegesuch","fortsetzung der questreihe"}}},fx={["0e006c4d"]={q="Warum bittet Euch Rhag Garmason, das Gesuch zu überbringen, anstatt selbst zu gehen?",a="Rhag Garmason und die überlebenden Gebirgssoldaten sind am The Thandol Span eingekesselt und halten dort einen prekären Stützpunkt. Da Dun Modr überrannt wurde und die Reserven aus Eisenschmiede noch weit entfernt sind, können sie keinen einzigen Zwerg vom Wachdienst entbehren, um nach Norden durch gefährliches Land zu reisen.",al={"warum ich gesuch allianz","warum rhag schickt euch","warum kann rhag nicht zur die zuflucht"}}},fp="20,249,22.432.0,24.410.0,36.158.0,48.211.0,47.188.0,31.142.0,26.190.0,56.232.0"}
P.entries["quest:6341"] = {n="Auf nach Darnassus",s="Nessa Schattensang vergleicht die Fische Teldrassils mit dem Fang vom Festland. Sie schickt Proben aus Rut'theran nach Auberdine, um herauszufinden, ob die Inselfische größer und zahlreicher sind.",h="Nessa Schattensang vergleicht die Fische Teldrassils mit dem Fang vom Festland.",kw={"auberdine","bounty of teldrassil","dunkelküste","hippogryph","laird","nessa shadowsong","rut'theran","vesprystus"},ang={["faction:Alliance"]="Für die Allianz verbindet die Route zwischen Rut'theran und Auberdine die Hauptstadt der Nachtelfen mit dem übrigen nördlichen Kalimdor.",["race:NightElf"]="Für Nachtelfen führt die Reise von den Höhen Teldrassils zu den Festlandufern der Dunkelküste."},sec={{t="Die Untersuchung einer Fischerin",b="Nessa Schattensang bittet Euch, Fischgräten und Schuppen zu Laird in Auberdine zu bringen. Die Fischer in Rut'theran machen reiche Fänge mit großen Fischen. Nessa möchte herausfinden, ob die Gewässer des Festlands dieselbe Art von Fischen hervorbringen. Anhand der Proben kann Laird den Inselfang mit Fischen von der Küste der Dunkelküste vergleichen."},{t="Die Überfahrt vorbereiten",b="Nessa Schattensang schickt Euch mit der Sammlung für Auberdine zu Vesprystus, dem Hippogryphenmeister in Rut'theran. Übergebt ihm die Proben, und er organisiert Eure Überfahrt zur Dunkelküste."}},faq={{q="Was möchte Nessa untersuchen?",a="Nessa Schattensang möchte die großen, zahlreichen Fische aus den Gewässern um Rut'theran mit Fischen von der Festlandküste der Dunkelküste vergleichen. Sie schickt Gräten und Schuppen, damit Laird sie vergleichen kann.",al={"nessas ziel","warum fische vergleichen","bounty of teldrassil zweck"}},{q="Wer erhält die Fischproben in Auberdine?",a="Laird, ein Fischhändler in Auberdine, erhält die Sammlung von Nessa Schattensang.",al={"wer bekommt nessas sammlung","laird dunkelküste","auberdine fischhändler"}},{q="Warum soll das Paket zu Vesprystus gebracht werden, statt direkt nach Auberdine zu reisen?",a="Vesprystus ist der Hippogryphenmeister in Rut'theran. Nessa schickt Euch mit der Sammlung zu ihm, damit er die Überfahrt zur Dunkelküste organisieren kann.",al={"warum vesprystus","wer ist vesprystus","hippogryphenmeister rut'theran"}},{q="Wo liegt Rut'theran im Verhältnis zu Teldrassil?",a="Rut'theran liegt am südlichen Fuß Teldrassils auf Meereshöhe. Ein smaragdgrünes Portal verbindet den Ort mit Darnassus, und sein Hafen dient Schiffen und Hippogryphen auf dem Weg zum großen Baum und zurück.",al={"rut'theran lage","wo ist nessa shadowsong","wie rut'theran erreichen"}},{q="Was geschieht, nachdem die Sammlung an Vesprystus übergeben wurde?",a="Nachdem Vesprystus die Sammlung angenommen hat, bietet er Flight to Auberdine an. Ein Hippogryph trägt Euch über die Meerenge zur Dunkelküste.",al={"nach flight to auberdine","nach bounty of teldrassil","was macht vesprystus"}},{q="Gehört dies zum Verlassen des Startgebiets der Nachtelfen?",a="Ja. Diese Questreihe macht junge Nachtelfenabenteurer mit Flugrouten vertraut und führt sie von Teldrassil zur Dunkelküste, wo sie ihre Reisen fortsetzen.",al={"teldrassil verlassen","nachtelfenquest stufe zehn","weiter zur dunkelküste"}}},fx={["4163d491"]={q="Warum benötigt Nessa Schattensang Euch, um die Sammlung zu überbringen?",a="Nessa Schattensang geht ihren Pflichten und Nachforschungen an den Docks von Rut'theran nach. Da ständig Reisende die Insel verlassen, ist es weit einfacher, ihr Paket mit Proben einem fähigen Abenteurer zu übergeben, der ohnehin zur Dunkelküste reist, als ihre Arbeit zu unterbrechen, um den Transport über das Meer selbst zu organisieren.",al={"warum ich nessa","warum braucht nessa hilfe","warum abenteurer zu vesprystus schicken"}}},fp="24,191,19.308.0,17.203.0,36.189.0,47.81.0,77.158.0,62.199.0,55.128.0,58.152.0"}
P.entries["quest:6342"] = {n="Ein unerwartetes Geschenk",s="Ihr bringt ungewöhnliche Fischexemplare aus Teldrassil zu Laird nach Auberdine. Vesprystus schickt Euch von Rut'theran aus auf einem Hippogryphen los.",h="Ihr bringt ungewöhnliche Fischexemplare aus Teldrassil zu Laird nach Auberdine.",kw={"auberdine","dunkelküste","flugroute","ein unerwartetes geschenk","hippogryph","laird","nessa shadowsong","rut'theran","teldrassil","vesprystus"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr auf Hippogryphen zwischen den Küstenaußenposten im Norden Kalimdors und der Hauptstadt reisen.",["race:NightElf"]="Als Nachtelf fliegt Ihr auf einem Hippogryphen nach Auberdine, ein Übergangsritus für junge kaldorei, die Teldrassil in Richtung des angestammten Festlands verlassen."},sec={{t="Auf Schwingen zur Dunkelküste",b="Von Rut'theran aus fliegt Ihr auf einem Hippogryphen mit Fischexemplaren für Nessa Schattensang zur Dunkelküste. Das Dorf ist für junge Abenteurer, die Teldrassil verlassen, eine Zuflucht an der Schwelle zur weiten Welt. Eine Fähre überquert auch die Meerenge zwischen der Insel und dem Festland von Kalimdor, während Nachtelfen auf Hippogryphen reisen, mit denen sie verbunden sind."},{t="Sonderbare Fänge",b="An den Docks von Auberdine untersucht Laird Nessas Funde. Die Schuppen sind faustgroß, und der Kieferknochen ist beinahe doppelt so groß wie Exemplare vom Festland. Die Gewässer rund um den Fuß des Weltbaums scheinen veränderte oder ungewöhnlich große Lebewesen hervorzubringen. Die seltsamen Fänge könnten mit Teldrassils mächtigem, rastlosem Wesen zusammenhängen."}},faq={{q="Welchen Zweck hat dieser Flug?",a="Ihr bringt ungewöhnliche Fischexemplare aus den Gewässern um Rut'theran zu Laird nach Auberdine, auf einem Hippogryphenflug zwischen den Siedlungen.",al={"warum nach auberdine fliegen","ein unerwartetes geschenk questziel","warum fliegen"}},{q="Wer schickt das Paket, und was ist darin?",a="Nessa Schattensang, eine Fischerin, schickt das Paket. Es enthält Fischexemplare aus den Gewässern von Rut'theran, darunter gewaltige Schuppen und einen übergroßen Kieferknochen.",al={"nessas sammlung","was ist im paket","wer hat das paket geschickt"}},{q="Warum sind die Fische aus Teldrassil so groß?",a="Laird findet faustgroße Schuppen und einen Kieferknochen, der beinahe doppelt so groß ist wie gewöhnlich. Die Gewässer um Teldrassils Weltbaum scheinen im Vergleich zum Festland der Dunkelküste größere Tiere hervorzubringen.",al={"warum sind die fische groß","fischgröße rut'theran","riesige schuppen"}},{q="Wer ist Vesprystus?",a="Vesprystus ist der Hippogryphenmeister in Rut'theran. Er versorgt die Reittiere der Nachtelfen und organisiert Flüge über das Wasser zum Festland von Kalimdor.",al={"vesprystus hintergrund","wer ist der hippogryphenmeister"}},{q="Wer ist Laird?",a="Laird ist ein Nachtelfenfischer in Auberdine an der Dunkelküste. Er erforscht die örtlichen Wasserlebewesen und vergleicht Fänge vom Festland mit denen aus der Nähe von Teldrassil.",al={"laird hintergrund","wer ist laird","laird dunkelküste"}},{q="Könnt Ihr zwischen Rut'theran und Auberdine reisen, ohne zu fliegen?",a="Ja. Eine regelmäßige Fähre verkehrt zwischen den Docks von Rut'theran und dem Anleger von Auberdine und bietet eine Alternative zum Hippogryphenflug.",al={"boot nach auberdine","fähre zur dunkelküste","anderer weg nach auberdine"}}},fx={ddbceafb={q="Warum schickt Euch Vesprystus nach Auberdine?",a="Als Hippogryphenmeister von Rut'theran überwacht Vesprystus den wichtigen Reiseverkehr zwischen Teldrassil und dem Festland von Kalimdor. Er hat zwar Nessa Shadowsongs Paket mit ungewöhnlichen Fischproben für Laird in Auberdine bei sich, doch sein Hauptanliegen ist es, Reisende mit dem Flugnetzwerk der Nachtelfen vertraut zu machen. Indem er Euch auf dem Rücken eines Hippogryphen über das Wasser schickt, stellt er sicher, dass Ihr eine Verbindung zum Flugmeister von Auberdine aufbaut und so schnellen Transport über die Dunkelküste für Eure zukünftigen Reisen ermöglicht.",al={"warum möchte vesprystus dies erledigt haben","vesprystus motiv","warum paket auberdine schicken"}}},fp="19,132,24.326.0,15.314.0,35.135.0,44.162.0,42.181.0,18.150.0,13.158.0,63.142.0"}
P.entries["quest:6343"] = {n="Rückkehr zu Nyoma",s="Laird schickt Euch mit seinen Erkenntnissen von Auberdine zu Nessa Schattensang in Rut'theran. Dieser einführende Botengang lehrt junge Reisende, zwischen Kalimdor und Teldrassil überzusetzen.",h="Laird schickt Euch mit seinen Erkenntnissen von Auberdine zu Nessa Schattensang in Rut'theran.",kw={"auberdine","caylais moonfeather","dunkelküste","laird","nessa shadowsong","rückkehr zu nyoma","rut'theran","teldrassil"},ang={["faction:Alliance"]="Als Reisende der Allianz seid Ihr zwischen Auberdine und Rut'theran unterwegs. Dieses Tor zur See verbindet die Nachtelfensiedlungen im Norden Kalimdors mit den Interessen der Allianz in ganz Azeroth.",["race:NightElf"]="Als Nachtelf, der Teldrassils Äste zum ersten Mal verlässt, übernehmt Ihr Euren ersten offiziellen Botengang zwischen der Inselzuflucht und dem uralten Festland der Dunkelküste."},sec={{t="Ein Bote übers Meer",b="Laird schickt Euch mit seinen schriftlichen Beobachtungen zurück übers Wasser. Fische vor der Dunkelküste unterscheiden sich deutlich von denen nahe Teldrassil. Er vermutet, dass der große Weltbaum das Leben in diesen Gewässern verändert. Ihr könnt beim Hippogryphenmeister Caylais Moonfeather einen Flug buchen oder die regelmäßig verkehrende Fähre vom Pier in Auberdine nach Rut'theran nehmen."},{t="Wundersame Fänge",b="In Rut'theran erhält Nessa Schattensang Lairds Antwort und ist fasziniert von den Unterschieden im Meeresleben. Fische nahe dem Weltbaum werden so groß, dass die örtlichen Fischer unmittelbar davon profitieren, doch die Kaldorei wissen nicht, warum. Nessa plant, die Erkenntnisse mit ihren Mitdorfbewohnern zu teilen. Vorerst schöpft sie aus dem reichen Meeresleben und hält nach Kräften Ausschau, die dafür verantwortlich sein könnten."}},faq={{q="Bei wem beginnt und endet diese Quest?",a="Laird, der Fischer in Auberdine an der Dunkelküste, schickt Euch zu Nessa Schattensang in Rut'theran am Fuße Teldrassils.",al={"questgeber","wo abgeben","wer vergibt die quest"}},{q="Wie gelangt man am schnellsten zurück nach Rut'theran?",a="Ihr könnt mit Caylais Moonfeather, dem Hippogryphenmeister in Auberdine, fliegen oder die regelmäßig verkehrende Passagierfähre vom langen Pier nach Rut'theran nehmen.",al={"wie zurückkommen","reise nach rut'theran","fähre oder hippogryph"}},{q="Warum untersucht Laird die Fische?",a="Laird untersucht die Fische, weil sich die Fänge entlang der Dunkelküste stark von denen rund um Teldrassil unterscheiden. Er vermutet, dass das Wachstum und die einzigartigen Energien des Weltbaums die Tierwelt der Umgebung verändern.",al={"warum fische untersuchen","unterschied zwischen den fischen","hintergrund zu lairds antwort"}},{q="Findet Nessa heraus, warum die Fische so seltsam sind?",a="Nessa erfährt nicht sofort, warum die Fische so seltsam sind. Sie bemerkt den Unterschied und stimmt zu, dass er weitere Untersuchungen verdient. Sie teilt den Bericht mit den Dorfbewohnern und erfreut sich vorerst an den reichen Fängen.",al={"warum sind die fische groß","teldrassils fischrätsel"}},{q="Was kommt vor dieser Quest?",a="'Flight to Auberdine' geht dieser Reise voraus. Dabei wird Nessas ursprünglicher Brief von Rut'theran zu Laird an der Dunkelküste gebracht.",al={"voraussetzung","vorherige quest","flight to auberdine"}},{q="Welchen Zweck hat diese Questreihe?",a="Die Questreihe führt in Teldrassils geheimnisvollen Einfluss auf die örtliche Tierwelt ein. Sie lehrt junge Nachtelfenabenteurer, wie sie mithilfe von Schiffen und Flugmeistern zwischen ihrer Inselheimat und dem Festland von Kalimdor reisen.",al={"warum diese quest machen","reisequest"}}},fx={c6069b83={q="Warum möchte Laird, dass dieser Brief an Nessa überbracht wird?",a="Laird möchte Nessa Schattensang umgehend über den dramatischen Unterschied zwischen dem Meeresleben entlang der Küste der Dunkelküste und den Gewässern von Teldrassil informieren. Er vermutet, dass Teldrassil selbst einen ungewöhnlichen Einfluss auf die umliegende Meeresfauna ausübt, und das Teilen seiner Beobachtungen hilft den Dorfbewohnern, die seltsame Beute zu verstehen, die sie ernten.",al={"warum antwort an nessa schicken","laird antwort zweck","warum möchte laird dies erledigt haben"}}},fp="15,182,26.346.0,16.385.0,36.137.0,51.151.0,31.187.0,48.205.0,29.130.0,40.204.0"}
P.entries["quest:6344"] = {n="Nessa Schattensang",s="Unterhalb des Weltbaums in Darnassus schickt Mydrannul einen Kurier zu Nessa Schattensang. Die Lieferung führt von Rut'theran zur Dunkelküste und verbindet die Stadt im Blätterdach mit der Küste.",h="Unterhalb des Weltbaums in Darnassus schickt Mydrannul einen Kurier zu Nessa Schattensang.",kw={"auberdine","kurier","dunkelküste","darnassus","mydrannul","nessa schattensang","portal","rut'theran","die tempelgärten"},ang={["faction:Alliance"]="Als Abenteurer der Allianz lernt Ihr, wie Teldrassil mit den anderen Gebieten der Allianz auf Kalimdor verbunden ist.",["race:NightElf"]="Als Nachtelf verlasst Ihr die Höhen von Darnassus und folgt den Küstenrouten, die Eure Heimat mit den uralten Ufern der Dunkelküste verbinden."},sec={{t="Ein Auftrag jenseits des Blätterdachs",b="In Darnassus hält Mydrannul Ausschau nach Reisenden, die Arbeit und eine Bestimmung suchen. Die Angelhändlerin Nessa Schattensang muss ein Paket über das Meer zur Dunkelküste bringen lassen, also schickt Mydrannul fähige Kuriere zur Küste. Viele junge Nachtelfen beginnen ihre Reisen zwischen den Ästen von Teldrassil. Diese Lieferung führt sie über den Baum hinaus."},{t="Hinab zu den Anlegestegen",b="Von den Tempelgärten aus führt das westliche Portal in Darnassus durch den Weltbaum hinab nach Rut'theran. An den Wurzeln auf Meereshöhe verbinden Angelstege und Hippogryphenlandeplätze Teldrassil mit dem Rest von Kalimdor. Nessa Schattensang geht dort ihrem Handel nach und bereitet Lieferungen für Auberdine vor."}},faq={{q="Wer vergibt diese Quest?",a="Mydrannul bietet den Lieferauftrag in Darnassus auf der Terrasse der Krieger an.",al={"questgeber","wo beginnt die quest nessa schattensang","mydrannul standort"}},{q="Wie gelange ich nach Rut'theran?",a="Geht von den Tempelgärten aus nach Westen und tretet durch das große, leuchtende Baumportal. Es bringt Euch hinab nach Rut'theran am Fuße von Teldrassil.",al={"wie nach rut'theran gelangen","rut'theran portal","darnassus verlassen"}},{q="Wer ist Nessa Schattensang?",a="Nessa Schattensang bietet an den Anlegestegen von Rut'theran Angelbedarf an. Sie beaufsichtigt den Transport von Waren und Paketen zwischen Teldrassil und der Dunkelküste.",al={"nessa schattensang rolle","was macht nessa","nessa schattensang npc"}},{q="Wohin führt diese Questreihe?",a="Das Gespräch mit Nessa führt zu 'The Bounty of Teldrassil'. Dabei lernt Ihr den Flugmeister kennen und unternehmt Euren ersten Flug über das Wasser nach Auberdine.",al={"was kommt nach nessa schattensang","nächste quest der reihe","teldrassil flugquestreihe"}},{q="Ist Nessa mit Maiev Shadowsong verwandt?",a="Nessa und Maiev Shadowsong tragen denselben Nachnamen, doch eine persönliche Verbindung zwischen ihnen ist nicht überliefert. Nessa ist eine Angelhändlerin am Hafen, während Maiev eine legendäre Wächterin ist.",al={"nessa maiev verwandtschaft","familie shadowsong","ist nessa mit maiev verwandt"}},{q="Warum ist dieser Auftrag für junge Abenteurer wichtig?",a="Auf dieser Reise lernen junge Abenteurer, die Krone von Teldrassil zu verlassen, die Anlegestege darunter zu erreichen und über Hippogryphenflugrouten zum Festland von Kalimdor zu gelangen.",al={"warum diese quest machen","bedeutung der quest"}}},fx={feb9b9a4={q="Warum möchte Mydrannul, dass dies erledigt wird?",a="Mydrannul tut lediglich einem Freund einen Gefallen. Nessa Schattensang arbeitet unten in Rut'theran als Fischereilieferantin und benötigt einen zuverlässigen Boten, um ein Paket über das Meer zur Dunkelküste zu befördern. Mydrannul nutzt seinen Posten in Darnassus, um nach fähigen Reisenden Ausschau zu halten, die bereit sind, die Äste hinunterzugehen und ihr zu helfen.",al={"warum nessa helfen","mydrannul grund","warum zu nessa shadowsong schicken"}}},fp="16,189,26.330.0,23.299.0,22.69.0,35.149.0,24.147.0,33.151.0,37.169.0,51.154.0"}
P.entries["quest:635"] = {n="Kristall in den Bergen",s="In Arathis nördlichen Bergen zieht Euch eine Vision zu einem schimmernden Kristall. Der Anhänger von Myzrael pulsiert in Eurer Hand, während Euch ein Hilferuf erreicht.",h="In Arathis nördlichen Bergen zieht Euch eine Vision zu einem schimmernden Kristall.",kw={"arathihochland","kristall","kristall in den bergen","anhänger von myzrael","shards of myzrael","vision"},sec={{t="Ein stummes Flehen",b="Der Anhänger von Myzrael pulsiert in Eurer Hand und trägt das Flehen von jemandem zu Euch, der Hilfe braucht. Dann zeigt Euch eine Vision einen schimmernden Kristall, der in den Bergen nördlich von Arathi aus dem Boden ragt. Ihr fühlt Euch dorthin gezogen."},{t="Am Kristall",b="Am Kristall deutet sein Pulsieren darauf hin, dass eine lebendige Kraft in ihm gefangen ist."}},faq={{q="Was setzt diese Reise in Gang?",a="Der Anhänger von Myzrael setzt diese Reise in Gang. Während Ihr ihn haltet, pulsiert er mit dem Flehen von jemandem, der verzweifelt Hilfe braucht.",al={"wie erhält man kristall in den bergen","woher kommt der anhänger von myzrael","kristall in den bergen start"}},{q="Wohin führt die Vision?",a="Die Vision führt Euch zu einem schimmernden Kristall in Arathis nördlichen Bergen. Ihr fühlt Euch dorthin gezogen.",al={"wo ist der kristall","kristall in den bergen fundort","kristall aus der vision finden"}}},fp="24,152,13.210.0,14.68.1,25.121.0,27.96.0"}
P.entries["quest:6361"] = {n="Ein Bündel Bälge",s="Jahan Falkenschwinge schickt gegerbte Bälge vom Wegekreuz zur Lederverarbeitung nach Donnerfels. Ihr tragt sie durch das zentrale Kalimdor und seht, wie der Wind Rider-Horst im Wegekreuz die Siedlungen der Horde verbindet.",h="Jahan Falkenschwinge schickt gegerbte Bälge vom Wegekreuz zur Lederverarbeitung nach Donnerfels.",kw={"ahanu","bündel mit bälgen","das wegekreuz","devrak","jahan falkenschwinge","lederverarbeitung","brachland","donnerfels","wind rider"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr auf Verbindungen zwischen den Stützpunkten Kalimdors angewiesen. Orcische Bestienmeister wie Devrak überbrücken die Entfernung zwischen verbündeten Gebieten.",["race:Tauren"]="Als reisender Tauren tragt Ihr Bälge von Jägern aus dem angestammten Brachland zu Handwerkern auf den gewaltigen Tafelbergen von Donnerfels."},sec={{t="Handel durch die Savanne",b="Jäger bringen Bälge und Fleisch zum Wegekreuz. Dort sammelt Jahan Falkenschwinge Pelze aus dem ganzen Brachland. Die Außenposten können nicht jede rohe Haut verarbeiten, also bittet er Euch, sie nach Westen nach Donnerfels zu tragen. Dort können meisterhafte Lederverarbeiter aus den Pelzen Ausrüstung für die Horde herstellen."},{t="Hinauf in die Lüfte",b="Der Pfad durch das Brachland und nach Mulgore ist beschwerlich. Borstennacken und Raubtiere bedrohen jeden, der Fracht zu Fuß trägt. Deshalb schickt Jahan Euch zu Devrak, dem Wind Rider-Meister im Wegekreuz. Eine ausgebildete Wyvern kann die Waren durch die Luft tragen und die verstreuten Siedlungen der Horde verbinden."}},faq={{q="Wer vergibt die Quest „Ein Bündel Bälge“?",a="Jahan Falkenschwinge, ein Tauren im Wegekreuz im Brachland, gibt Euch Bälge zum Transport. Er hat Pelze von einheimischen Wildtieren gesammelt und braucht einen zuverlässigen Kurier, der sie in Richtung Donnerfels bringt.",al={"questgeber","wer startet ein bündel bälge","wo gibt es bündel mit bälgen"}},{q="Zu wem soll ich das Bündel mit Bälgen bringen?",a="Bringt die Bälge zu Devrak, dem orcischen Wind Rider-Meister am Horst im Wegekreuz. Er kümmert sich um Flugreisen zwischen dem Wegekreuz und anderen wichtigen Knotenpunkten der Horde.",al={"abgabe-npc","wohin mit den bälgen","mit wem sprechen"}},{q="Was geschieht, nachdem ich Devrak die Bälge gegeben habe?",a="Nachdem Ihr Devrak die Bälge gegeben habt, bittet er Euch, einen Wind Rider zu nehmen und die Fracht zu Ahanu zu fliegen, dem Lederverarbeiter hoch oben auf den Felsen von Donnerfels.",al={"nächste quest","was kommt nach ein bündel bälge","folgequest"}},{q="Warum werden diese Bälge nach Donnerfels geschickt?",a="Jahan Falkenschwinge arbeitet mit Ahanu in Donnerfels zusammen. Ahanu verarbeitet Pelze von Wild aus dem Brachland zu Lederrüstungen und Waren für die Tauren und ihre Verbündeten in der Horde.",al={"warum donnerfels","ahanu bälge","wofür sind die bälge"}},{q="Warum einen Wind Rider nehmen, statt zu Fuß zu gehen?",a="Zu Fuß das Brachland zu durchqueren und den gewaltigen Tafelberg von Donnerfels zu erklimmen, kostet Zeit. Wildtiere und Borstennackenrotten machen die Reise gefährlich, während ein Wind Rider Euch rasch über sie hinwegträgt.",al={"warum nach donnerfels fliegen","reisen mit wind rider"}},{q="Brauche ich dafür schon Erfahrung mit Flugmeistern?",a="Bei dieser frühen Lieferung könnt Ihr lernen, das Flugmeistersystem zu nutzen. Devraks Horst zeigt, wie Wind Rider weit entfernte Regionen verbinden.",al={"flugpunkt voraussetzung","ist ein flugpunkt nötig"}}},fx={["2d6b34f1"]={q="Warum bittet Jahan Falkenschwinge einen Abenteurer, die Bälge zu überbringen?",a="Jahan Falkenschwinge ist im Wegekreuz stationiert, um den Handel und das Handwerk der Siedlung zu unterstützen. Anstatt seinen Posten zu verlassen, um die weite Reise über die Ebenen nach Mulgore selbst anzutreten, verlässt er sich auf reisende Abenteurer, um Waren zu transportieren und lokale Jäger mit den Handwerkern in Donnerfels zu verbinden.",al={"warum ich bündel mit bälgern","warum braucht jahan mich","warum kann jahan falkenschwinge die bälge nicht liefern"}}},fp="17,197,24.271.0,19.282.0,38.189.0,42.150.0,46.147.0,48.153.0,40.187.0,49.133.0"}
P.entries["quest:6362"] = {n="Flug nach Donnerfels",s="Euer Wind Rider trägt behandelte Felle vom Wegekreuz nach Donnerfels, hoch über den Ebenen. Der Flug verbindet das Brachland mit der Hauptstadt der Horde.",h="Euer Wind Rider trägt behandelte Felle vom Wegekreuz nach Donnerfels, hoch über den Ebenen.",kw={"ahanu","brachland","bündel mit bälgen","das wegekreuz","devrak","hewa's armory","flug nach donnerfels","wind rider"},ang={["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch auf Wind Rider, die die Außenposten im Brachland mit den Festungen von Durotar und Mulgore verbinden.",["race:Tauren"]="Als junger Tauren, der aus dem Brachland zurückkehrt, könnt Ihr direkt zur hoch aufragenden Hauptstadt Eures Volkes fliegen."},sec={{t="Schwingen über der Savanne",b="Devrak befördert Reisende auf einem Wind Rider über das Brachland. Für viele ist es ihr erster Flug über Kalimdor. Diese Wyvern verbinden die verstreuten Siedlungen der jungen Horde und ersparen Reisenden die Landwege, auf denen Rotten von Borstennacken und Zentauren umherstreifen."},{t="Felle für die Rüstkammer",b="Behandelte Felle aus dem Brachland sind für Ahanu bestimmt, einen Handwerker in Hewa's Armory in Donnerfels. Er arbeitet unter dem großen Nistplatz der Wind Rider auf der zentralen Hochebene. Vorräte von Jagdaußenposten aus allen Teilen der Ebenen helfen ihm, einheimische Krieger und Jäger auszurüsten."}},faq={{q="Wer vergibt die Quest Flug nach Donnerfels?",a="Devrak, der Wind Rider-Meister am Wegekreuz im Brachland, bietet Reisenden mit Fellen einen Flug an.",al={"questgeber","wo beginnt flug nach donnerfels","devrak standort"}},{q="Wer ist Ahanu und wo ist er zu finden?",a="Ahanu ist ein Taurenhandwerker in Hewa's Armory in Donnerfels, nahe dem Fuß des Nistplatzes der Wind Rider der Stadt.",al={"wo ist ahanu","ahanu standort","hewa's armory"}},{q="Was wird bei dieser Lieferung transportiert?",a="Ihr bringt behandelte Felle aus dem Brachland zu Ahanu, der sie zur Lederverarbeitung und Rüstungsherstellung verwendet.",al={"was wird geliefert","bündel mit bälgen"}},{q="Warum Wind Rider nutzen, statt zu Fuß zu gehen?",a="Wind Rider überqueren das Brachland zu den hohen Tafelbergen von Donnerfels. Sie umgehen den längeren Landweg durch Mulgore und landen am Wind Rider-Turm der Stadt.",al={"warum nach donnerfels fliegen","vorteil der flugroute"}},{q="Wo beginnt diese Lieferkette?",a="Die Lieferung beginnt bei Jahan Falkenschwinge am Wegekreuz. Er stellte die behandelten Felle in der vorherigen Aufgabe „Bündel mit Bälgen“ zusammen.",al={"vorherige quest","felle questreihe"}},{q="Was folgt nach der Lieferung der Felle?",a="Nachdem Ahanu die Felle erhalten hat, schickt er Euch nach oben, um mit Tal, dem Wind Rider-Meister von Donnerfels, zu sprechen.",al={"nächste quest","folgequest von flug nach donnerfels"}}},fx={ae176b23={q="Warum schickt Euch Devrak mit den Bälgen nach Donnerfels?",a="Als Flugmeister des Wegekreuzes verwaltet Devrak die Wind Rider, die die verschiedenen Siedlungen der Horde in ganz Kalimdor verbinden. Wenn ein Bote mit einem dringenden Bündel mit Bälgen für Ahanu in Donnerfels eintrifft, ist es Devraks Aufgabe, für eine schnelle Überfahrt zu sorgen und Reisende nach der Landung auf den hohen Plateaus direkt zu ihrem Ziel zu leiten.",al={"warum möchte devrak dies erledigt haben","devrak motiv","warum bündel mit bälgern schicken"}},["1fe41edb"]={q="Warum muss Devrak Euch die Bälge überbringen lassen, anstatt es selbst zu erledigen?",a="Devrak ist an seinen Posten am Horst im Wegekreuz gebunden, wo er die Wind Rider beaufsichtigt und sich um Reisende kümmert, die das zentrale Kalimdor betreten oder verlassen. Er kann seine Pflichten nicht aufgeben, um Besorgungen in Mulgore zu machen, was einen willigen Reisenden, der ohnehin in diese Richtung unterwegs ist, zur natürlichen Wahl macht, um die Lieferung abzuschließen.",al={"warum liefert devrak nicht","warum schickt mich devrak","warum braucht devrak einen reisenden"}}},fp="21,147,25.248.0,20.256.0,42.107.0,39.110.0,43.90.0,39.156.0,37.126.0,43.107.0"}
P.entries["quest:6363"] = {n="Tal der Windreitermeister",s="In Donnerfels wartet Tal der Windreitermeister auf Ahanus Paket. Es ist für Jahan Falkenschwinge am Wegekreuz bestimmt, wo Mulg ores Lederverarbeiter mit Händlern aus dem Brachland handeln.",h="In Donnerfels wartet Tal der Windreitermeister auf Ahanus Paket.",kw={"ahanu","das wegekreuz","devrak","flugmeister","jahan","lederwaren","tal","donnerfels","wind rider"},ang={["faction:Horde"]="Als Angehörige der Horde seid Ihr auf Flugrouten zwischen dem Brachland und Donnerfels angewiesen, um Verstärkung, Handelswaren und Nachrichten durch das zentrale Kalimdor zu befördern.",["race:Tauren"]="Als Tauren seid Ihr auf die Wind Rider von Donnerfels angewiesen, die Euer Volk mit der übrigen Horde verbinden."},sec={{t="Vorräte für das Wegekreuz",b="Von der unteren Ebene von Donnerfels schickt Ahanu fertig gegerbte Häute an Jahan Falkenschwinges Handelsstand am Wegekreuz. Der Handel zwischen Mulgore und dem Brachland ist für die junge Horde wichtig. Der Weg die Klippen hinunter und über die Ebenen dauert zu Fuß Stunden, daher tragen geflügelte Kuriere Pakete über die Kluft."},{t="Meister des Plateauhorsts",b="Auf der höchsten zentralen Ebene von Donnerfels versorgt Tal die Wind Rider der Stadt, auch Wyvern genannt. Sie überqueren Kalimdors zerklüftete Gipfel und wechselnde thermische Aufwinde. Tal organisiert Flüge zu Außenposten wie dem Wegekreuz, die Boten und Fracht zwischen der Hauptstadt der Tauren und ihren orcischen Verbündeten befördern."}},faq={{q="Wer ist Tal?",a="Tal betreut den Horst der Wind Rider auf dem zentralen Plateau von Donnerfels. Er organisiert den Lufttransport für Reisende und Kuriere, deren Ziel im Brachland oder jenseits davon liegt.",al={"wer ist tal","tal donnerfels","windreitermeister tal"}},{q="Wer ist Ahanu?",a="Ahanu ist ein Lederverarbeiter der Tauren in Donnerfels. Er bereitet Lederwaren für Händler an Kalimdors Außenposten vor, darunter Jahan Falkenschwinge am Wegekreuz.",al={"ahanu","wer ist ahanu","ahanu donnerfels"}},{q="Warum müssen die Waren zum Wegekreuz?",a="Das Wegekreuz ist ein Handels- und Militärknotenpunkt im Brachland. Waren aus Mulgore, darunter Häute und Lederkleidung, versorgen dort Reisende, Jäger und Patrouillen der Horde.",al={"warum wegekreuz","lederwaren wegekreuz","jahan leder"}},{q="Kann ich mit diesem Paket direkt zum Wegekreuz fliegen?",a="Ihr könnt zum Wegekreuz fliegen, nachdem Ihr die Siedlung besucht und Kontakt mit Devrak, ihrem Windreitermeister, aufgenommen habt. Bis dahin reist Ihr zu Fuß über Land.",al={"flug zum wegekreuz möglich","tal flugroute","wie zum wegekreuz fliegen"}},{q="Was sind Wind Rider?",a="Wind Rider, auch Wyvern genannt, sind intelligente, giftige, geflügelte Raubtiere, die in Kalimdors Felsklippen heimisch sind. Sie sind seit dem Dritten Krieg mit der Horde verbündet und ihre wichtigsten Flugreittiere.",al={"wyvern","was ist ein wind rider","tauren reittiere"}},{q="Wohin führt dieser Kurierauftrag als Nächstes?",a="Nachdem Ihr die Waren bei Tal abgeliefert habt, weist er Euch an, Ahanus Paket über die Ebenen zu Jahan Falkenschwinge am Wegekreuz zu bringen.",al={"nächste quest","was nach tal","wohin gehen die lederwaren"}}},fx={["989dcaf5"]={q="Warum möchte Ahanu, dass dies erledigt wird?",a="Ahanu hat einen Vorrat an fertigen Lederwaren für Jahan hergestellt, einen Händler, der vom Wegekreuz im Brachland aus handelt. Um den Handel zwischen Mulgore und dem Rest der Gebiete der Horde am Laufen zu halten, verlassen sich Handwerker wie Ahanu auf zuverlässige Boten und die Wind Rider, um ihre Waren über die rauen Weiten zu transportieren.",al={"ahanu motiv","warum lederwaren schicken","ahanu jahan lieferung"}}},fp="25,184,27.301.0,26.302.0,11.155.0,13.153.0,46.173.0,54.155.0,21.193.0,41.131.0"}
P.entries["quest:6364"] = {n="Rückkehr zu Varg",s="Ihr bringt fertige Lederwaren zu Jahan Falkenschwinge am Wegekreuz zurück. Die Reise beginnt, nachdem Ihr Ahanu, dem Kürschner von Donnerfels, Häute gebracht habt, und führt Euch in die Wind Rider-Flugrouten der Horde zwischen Mulgore und dem Brachland ein.",h="Ihr bringt fertige Lederwaren zu Jahan Falkenschwinge am Wegekreuz zurück.",kw={"ahanu","brachland","das wegekreuz","devrak","jahan falkenschwinge","tal","donnerfels","wind rider"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr auf Wind Rider-Flugrouten angewiesen, die Mulgore, Durotar und das Brachland verbinden. Sie halten die Gebiete der Horde im zentralen Kalimdor zusammen.",["race:Tauren"]="Als Tauren könnt Ihr sehen, wie der Handel die Gerber von Mulgore mit den Außenposten im Brachland verbindet und das Grenzland der Horde unterstützt."},sec={{t="Schwingen über Kalimdor",b="Tal, der Wind Rider-Meister von Donnerfels, organisiert von der zentralen Mesa aus Flüge durch das zentrale Kalimdor. Für viele Reisende ist dies der erste Ritt auf einem ausgebildeten Wind Rider. Sobald Ihr den Wind Rider-Meister einer anderen Siedlung kennengelernt habt, etwa Devrak am Wegekreuz, kann Euch ein Wind Rider dorthin tragen. Die Tiere überwinden weite Strecken, die sonst eine gefährliche Überlandreise durch die Teufelsfelsen und das nördliche Brachland bedeuten würden."},{t="Handel am Wegekreuz",b="Jahan Falkenschwinge handelt am Wegekreuz, wo sich täglich Jäger, Späher und Söldner versammeln. Die Flüge befördern auch Waren zwischen den Siedlungen. Häute, die zu Ahanu auf den Anhöhen von Donnerfels geschickt werden, werden zu strapazierfähiger Rüstung und Ausrüstung verarbeitet. Dann fliegen sie zurück zur Wegkreuzung im Brachland, um die wachsenden Unternehmungen der Horde im Grenzland zu versorgen."}},faq={{q="Wer ist Jahan Falkenschwinge?",a="Jahan Falkenschwinge ist ein Taurenhändler am Wegekreuz im Brachland. Er kauft und verkauft Lederwaren, darunter Ausrüstung, die Handwerker aus Donnerfels aus rohen Tierhäuten fertigen.",al={"jahan","jahan falkenschwinge hintergrundgeschichte","wer ist jahan"}},{q="Warum muss ich mit einem Wind Rider zum Wegekreuz zurückfliegen?",a="Der Wind Rider bringt fertige Lederwaren zu Jahan und macht Euch mit dem Flugnetz vertraut. Tal in Donnerfels kann Wind Rider nur zu Siedlungen schicken, die bereits mit dem Horst verbunden sind, etwa zu Devraks Horst am Wegekreuz.",al={"warum zurückfliegen","wind rider rückkehr","wie funktionieren flugrouten"}},{q="Wer ist Ahanu?",a="Ahanu ist Lederverarbeiter und Kürschner auf den Anhöhen von Donnerfels. Er nimmt rohe Häute von Jägern aus dem Brachland entgegen und verarbeitet sie zu fertigen Waren, die zum Verkauf zurückgeschickt werden.",al={"ahanu","ahanu donnerfels","wer hat die waren hergestellt"}},{q="Wer ist Devrak?",a="Devrak ist der orkische Wind Rider-Meister am Wegekreuz. Er verwaltet den Horst, der das Brachland mit Hochburgen der Horde wie Orgrimmar und Donnerfels verbindet.",al={"devrak","wegekreuz flugmeister","wind rider-meister devrak"}},{q="Kann ich einen Wind Rider nutzen, ohne zuvor mit dem Meister am Zielort gesprochen zu haben?",a="Nein. Ihr könnt nur zu Außenposten fliegen, an denen Ihr bereits den örtlichen Wind Rider-Meister kennengelernt und die Horste verbunden habt.",al={"flugrouten regeln","flugmeister freischalten","überallhin fliegen möglich"}},{q="Was geschieht, nachdem ich Jahan die Lederwaren zurückgebracht habe?",a="Wenn Ihr Jahan die Lederwaren zurückbringt, schließt Ihr die Kurierkette zwischen Mulgore und dem Brachland ab. Ihr lernt, wie Flugreisen funktionieren, und könnt der Garnison und den Händlern am Wegekreuz weiterhelfen.",al={"folgequest","was kommt als nächstes","nach rückkehr zu varg"}}},fx={["65054dbe"]={q="Warum möchte Tal, dass die Lederwaren an Jahan zurückgeschickt werden?",a="Als Wind Rider-Meister von Donnerfels überwacht Tal den Flugverkehr zwischen den Plateaus und den Außenposten wie dem Wegekreuz. Euch mit Ahanus fertigen Lederwaren auf einem Reittier zurückzuschicken, beweist die Effizienz der Wind Rider und vervollständigt gleichzeitig die Handelsroute zwischen den Handwerkern auf den Höhen und Jahan Falkenschwinges blühendem Laden unterhalb.",al={"warum möchte tal dies erledigt haben","tal motiv","warum leder an jahan schicken"}}},fp="15,235,19.426.0,26.330.0,22.167.0,58.223.0,13.174.0,14.161.0,74.111.0,56.192.0"}
P.entries["quest:6365"] = {n="Fleisch für Orgrimmar",s="Am Wegekreuz schickt Zargh Fleisch aus dem Brachland nach Orgrimmar. Er bittet junge Orc- und Trollabenteurer, es zu Devrak, dem Windreitermeister, zu bringen und den Weg zur Hauptstadt der Horde kennenzulernen.",h="Am Wegekreuz schickt Zargh Fleisch aus dem Brachland nach Orgrimmar.",kw={"brachland","das wegekreuz","devrak","flugmeister","gryshka","fleischlieferung","orgrimmar","wind rider","zargh"},ang={["profession:Cooking"]="Als Koch helft Ihr, frische Fleischstücke aus dem Brachland zu Gryshkas Gasthaus in Orgrimmar zu bringen und die Eintopftöpfe der Hauptstadt für durchreisende Krieger gefüllt zu halten.",["race:Orc"]="Als Orc, der Durotar verlässt, um im Brachland zu jagen, könnt Ihr Zarghs Paket abliefern und eine Flugroute zurück zur Hauptstadt des Kriegshäuptlings erschließen.",["race:Troll"]="Als Dunkelspeertroll am Wegekreuz helft Ihr, Außenposten in der Wildnis mit Orgrimmars Versorgungslinien zu verbinden."},sec={{t="Frisches Wild aus dem Brachland",b="Wildtiere durchstreifen das Brachland, von Zhevras und Echsenausscheitern bis hin zu Kodos und Donnerfalken. Zargh hat Fleisch für Gryshka zugeschnitten, die Gastwirtin im Tal der Stärke von Orgrimmar. Er schickt Boten vom Wegekreuz zum Windreiterhorst, statt den langen, staubigen Marsch über den Südstrom nach Durotar zu wagen."},{t="Schwingen über den Steppen",b="Die Begegnung mit Devrak gibt einem jungen Krieger der Horde einen ersten Einblick in die Flugrouten der Windreiter. Windreitermeister verbinden abgelegene Orte wie das Wegekreuz mit dem befestigten Sitz der Horde in Orgrimmar. Devrak bereitet Euch und die Fracht auf einen schnellen Flug über die Savanne vor."}},faq={{q="An wen schickt Zargh dieses Fleisch?",a="Zargh schickt das Fleisch an seine Freundin Gryshka, die Gastwirtin im Tal der Stärke von Orgrimmar.",al={"wer bekommt das fleisch","für wen ist das fleisch","zargh fleischempfänger"}},{q="Warum können nur Orcs und Trolle diese Quest annehmen?",a="Diese Einführung ins Fliegen verbindet Orcs und Dunkelspeertrolle mit ihrer gemeinsamen Hauptstadt Orgrimmar. Tauren reisen über Bündel mit Bälgen nach Donnerfels, während Verlassene über Das Grabmal versorgen in den Silberwald ziehen.",al={"warum können tauren das nicht annehmen","untote fleischquest","volksbeschränkung"}},{q="Wer ist Devrak?",a="Devrak ist der orcische Windreitermeister am Wegekreuz im Brachland. Er beaufsichtigt die Wyvern, die Nachrichten, Vorräte und Reisende durch Kalimdor befördern.",al={"devrak wegekreuz","wer ist devrak"}},{q="Was geschieht, nachdem Ihr Devrak das Fleisch gegeben habt?",a="Devrak nimmt die Lieferung entgegen und organisiert für Euch und das Fleisch einen Windreiterflug zum Skytower von Orgrimmar. Anschließend liefert Ihr es über Ride to Orgrimmar bei Gryshka in ihrem Gasthaus ab.",al={"nächste quest nach fleisch für orgrimmar","was macht devrak"}},{q="Wo befindet sich Zargh?",a="Zargh befindet sich am Wegekreuz, dem zentralen Handelsplatz der Horde an der wichtigsten Wegkreuzung des Brachlands.",al={"zargh standort","wo ist zargh"}},{q="Warum einen Windreiter nehmen, statt zu Fuß zu gehen?",a="Windreiter bringen Reisende schnell durch das raue Brachland und über die Flussschlucht nach Durotar. Frisches Fleisch kann Orgrimmar erreichen, bevor es verdirbt.",al={"warum nach orgrimmar fliegen","windreiter fleisch"}}},fx={["50e2b3bf"]={q="Warum möchte Zargh, dass das Fleisch geliefert wird?",a="Zargh hat einige erlesene Fleischstücke erworben und möchte sie einfach als Geschenk an seine Freundin Gryshka senden, die Gastwirtin im zentralen Gasthaus von Orgrimmar. Da frisches Fleisch unter der sengenden Sonne des Brachlandes und von Durotar schnell verdirbt, ist es ihm wichtig, die Stücke schnell in fähige Hände zu bekommen.",al={"warum fleisch schicken","zargh motiv","warum schickt zargh fleischstücke"}},["0b0a203b"]={q="Warum benötigt Zargh Euch, anstatt das Fleisch selbst zu liefern?",a="Zargh hat seine eigenen Pflichten an seinem Posten im Wegekreuz und kann diese nicht einfach aufgeben, um die Reise zurück durch Durotar anzutreten. Anstatt seine Pflichten zu vernachlässigen, verlässt er sich auf vielversprechende Reisende der Horde, die in Richtung der Hauptstadt unterwegs sind, um seine Pakete über das lokale Wind Rider-Netzwerk zu überbringen.",al={"warum nicht zargh selbst","warum bittet mich zargh","warum einen abenteurer schicken"}}},fp="18,191,27.318.0,22.258.0,34.97.0,45.227.0,14.155.0,45.175.0,23.92.0,40.149.0"}
P.entries["quest:637"] = {n="Sully Balloos Brief",s="Am Thandol-Übergang birgt Sully Balloos Brief die letzten Worte eines Zwergs an seine Frau in Eisenschmiede. Unter der Brücke gefunden, berichtet er, wo er starb.",h="Am Thandol-Übergang birgt Sully Balloos Brief die letzten Worte eines Zwergs an seine Frau in Eisenschmiede.",kw={"arathi","zwergensoldat","eisenschmiede","sara balloo","skelett","sully balloo","thandol-übergang","durchnässter umschlag","sumpfland"},ang={["faction:Alliance"]="Als Soldat der Allianz erinnert Ihr Euch an die Opfer, die Frontkämpfer bringen, um die gefährdeten Landverbindungen zwischen den südlichen und nördlichen Allianzgebieten zu schützen.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede ehrt Ihr Sullys letzte Worte und einen Waffenbruder, der die großen Werke zwergischer Steinmetzkunst gegen Bedrohungen aus dem Norden verteidigte und dabei starb."},sec={{t="Eine Stimme vom Flussbett",b="Unter den Steinpfeilern des Thandol-Übergangs, der Landbrücke zwischen dem Sumpfland und dem Arathihochland, umklammert ein ertrunkenes Skelett noch immer einen Umschlag. Seine wassergeschädigten Seiten beginnen mit „Meine liebe Sara“ und bewahren die Zärtlichkeit von Sully Balloos sorgfältig verfassten Zeilen."},{t="Der Preis des Übergangs",b="Die Streitkräfte der Allianz und ihre Feinde haben erbittert um den Thandol-Übergang gekämpft. Dunkeleisensaboteure und Kriegstrupps, die um die Grenzlande stritten, haben den Übergang bedroht. Sully Balloo gehörte zu den Zwergensoldaten, die nach Norden geschickt wurden, um ihn zu verteidigen. Seine Familie in den Bergen wusste nichts von seinem Schicksal, bis ein Taucher seinen Abschiedsbrief aus den Fluten barg."},{t="Eine Witwe in Eisenschmiede",b="In Eisenschmiede erhält Sullys Witwe Sara Balloo den Brief und erfährt, wo ihr Mann starb. Zwischen Trauer und anhaltender Hoffnung war sie sich nicht sicher gewesen, ob er vermisst oder für immer verloren war. Seine handschriftlichen Worte zwingen sie schließlich, sich der bitteren Wahrheit seines Todes zu stellen."}},faq={{q="Wo wird Sully Balloos Brief gefunden?",a="Sully Balloos Brief wurde in der Hand eines ertrunkenen Skeletts unter den Steinpfeilern des Thandol-Übergangs gefunden, zwischen dem Sumpfland und dem Arathihochland.",al={"fundort des briefs","wo ist sully balloo","skelett am thandol-übergang"}},{q="Wer war Sully Balloo?",a="Sully Balloo war ein Zwergensoldat der Allianz, der bei der Verteidigung des Thandol-Übergangs fiel. Bevor er die Wache am Übergang antrat, schrieb er seiner Frau Sara einen Abschiedsbrief. Seine sterblichen Überreste und der Brief wurden unter dem eisigen Wasser gefunden.",al={"wer ist sully","sully balloos geschichte","wer war sully balloo"}},{q="Wer ist Sara Balloo?",a="Sara Balloo ist Sullys Witwe und lebt in Eisenschmiede. Seit Monaten wartet sie auf Nachricht über das Schicksal ihres Mannes an der nördlichen Grenze.",al={"wo ist sara balloo","wer ist sara","sara balloos aufenthaltsort"}},{q="Was geschieht, nachdem Ihr den Brief überbracht habt?",a="Nachdem Sara von Sullys Tod erfährt, überwältigt sie die Trauer. Sie bittet darum, sein Andenken zu ehren, woraus sich eine weitere Bitte in Eisenschmiede ergibt.",al={"was kommt als nächstes","sullys questreihe","nach übergabe des briefs"}},{q="Warum war der Brief unter Wasser noch unversehrt?",a="Der Umschlag, den die sterblichen Überreste des Soldaten umklammerten, schützte den Brief. Als er geborgen wurde, waren die Seiten durchnässt und teilweise aufgelöst. Genug von Sullys sorgfältiger Handschrift blieb leserlich, um den Brief zu lesen.",al={"warum ist der brief lesbar","wie hat der umschlag überdauert"}},{q="Welches reale Vorbild liegt dieser Quest zugrunde?",a="Die Geschichte ehrt Major Sullivan Ballou von der 2nd Rhode Island Infantry. Kurz vor seinem Tod bei der First Battle of Bull Run während des American Civil War schrieb er seiner Frau einen berühmten, poetischen Abschiedsbrief.",al={"wissenswertes über sully balloo","sullivan ballou","bezug zum american civil war"}}},fp="21,147,25.270.0,21.357.0,20.258.1,37.154.0,21.223.0,19.136.0,42.132.1,43.207.0,49.216.0"}
P.entries["quest:638"] = {n="Trollbann",s="In Hammerfall bereiten sich die Dunkelspeer auf Kämpfe gegen die Dschungeltrolle von Zul'Gurub vor. Vol'jin hat sie ausgesandt, um Trol'kalar aus dem zerstörten Stromgarde zu bergen, wo die Klinge in Menschenhand ruhte.",h="In Hammerfall bereiten sich die Dunkelspeer auf Kämpfe gegen die Dschungeltrolle von Zul'Gurub vor.",kw={"hammerfall","nimboya","stromgarde","trol'kalar","trollbann","vol'jin","zengu","zul'gurub"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Zengu in Hammerfall finden, wo er darauf wartet, dass das legendäre Schwert aus Menschenhand geborgen wird.",["race:Troll"]="Als Troll wisst Ihr, dass Vol'jin Trol'kalar sucht, um die Dunkelspeer gegen ihre uralten Verwandten in Zul'Gurub zu wappnen."},sec={{t="Ein gefallener König, eine begehrte Klinge",b="Nachdem König Thoras Trollbane gefallen war, wurde Stromgarde zur Ruine. Häuptling Vol'jin befahl daraufhin den Dunkelspeer, Trol'kalar heimlich fortzuschaffen. Das sagenumwobene Schwert hatte lange in Menschenhand geruht. Nun sucht der Stamm es für die bevorstehenden Kämpfe gegen die Dschungeltrolle von Zul'Gurub."},{t="Reise nach Hammerfall",b="Vol'jin sandte Zengu, einen erfahrenen Jäger, nach Hammerfall im nordöstlichen Arathihochland. Vom Schlingendorntal aus weist Nimboya Reisende an, Zengu zu finden und bei der Sicherung des legendären Schwertes zu helfen."}},faq={{q="Warum will Vol'jin das Schwert Trol'kalar?",a="Vol'jin will Trol'kalar für die bevorstehenden Kämpfe gegen die feindseligen Dschungeltrolle von Zul'Gurub.",al={"warum trolkalar","warum das schwert trollbann","zweck von trolkalar"}},{q="Wer ist Zengu?",a="Zengu ist ein erfahrener Jäger der Dunkelspeer, der nach Hammerfall im Arathihochland geschickt wurde, um die Bergung von Trol'kalar zu leiten.",al={"wer ist zengu","zengus rolle","jäger zengu"}},{q="Wohin führt Euch diese Reise?",a="Ihr reist vom Schlingendorntal nach Norden bis nach Hammerfall, einem Außenposten im nordöstlichen Arathihochland.",al={"wohin gehen","questziel","wo ist zengu"}},{q="Was ist mit Stromgarde geschehen?",a="Stromgarde liegt in Trümmern, seit sein Herrscher, König Thoras Trollbane, gefallen ist.",al={"zustand von stromgarde","was geschah mit thoras trollbane"}}},fp="9,190,30.261.0,21.192.0,43.90.0,13.118.0,33.104.0,28.70.0"}
P.entries["quest:6381"] = {n="Neues Leben",s="Tammra Windfeld schickt Reisende von Sonnenfels nach Westen, um die Heilung des Verbrannten Tals einzuleiten. Sie hofft, dass Gaeasamen dem versengten Land helfen können, sich zu erholen.",h="Tammra Windfeld schickt Reisende von Sonnenfels nach Westen, um die Heilung des Verbrannten Tals einzuleiten.",kw={"bloodfury-harpyien","das verbrannte tal","cycle of rebirth","erdhügel","feuerelementare","gaeasamen","steinkrallengebirge","sonnenfels","tammra windfeld"},ang={["class:Druid"]="Als Druide teilt Ihr Tammras Aufgabe, das Verbrannte Tal zu erneuern und das empfindliche Gleichgewicht der Natur wiederherzustellen.",["class:Shaman"]="Als Schamane wisst Ihr, dass die aufgewühlten Feuerelementare keinen Frieden finden werden, bis das geschundene Land zu heilen beginnt.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr zu schätzen, wie die Samen auf leblosem Boden üppige Vegetation hervorbringen können.",["race:Tauren"]="Als Tauren tretet Ihr in Gemeinschaft mit der Erdenmutter, indem Ihr verzauberte Samen in gezeichneten Boden pflanzt. Damit erfüllt Ihr Eure heilige Pflicht, verwundete Länder zu heilen."},sec={{t="Heilung der verbrannten Erde",b="Tammra Windfeld bittet Euch, das Verbrannte Tal zu betreten, wo Ruß, Feuerelementare und Harpyien den verwüsteten Boden heimsuchen. Sie vertraut auf die Widerstandskraft der Erdenmutter. Sucht die Gaeaerdhügel, wo fruchtbare Erde das Feuer überstanden hat."},{t="Halt für die Zukunft",b="Gaeasamen können trotz der anhaltenden elementaren Verderbnis Wurzeln schlagen. Ihre Wurzeln halten den Verfall zurück und geben Pflanzen einen Ort, an dem sie ins Tal zurückkehren können. Tammra hofft, dass neues Wachstum die Feuergeister besänftigt und die Harpyien von ihrem trostlosen Nistplatz vertreibt. Sie hofft auch, dass die Holzfällerei der Venture Company schließlich vertrieben wird."}},faq={{q="Welchen Zweck hat das Pflanzen der Gaeasamen?",a="Die verzauberten Gaeasamen können in der gezeichneten Erde des Verbrannten Tals Wurzeln schlagen und der Verderbnis widerstehen. Sie geben Pflanzen Halt, von dem aus der Wald allmählich nachwachsen und heilen kann.",al={"warum samen pflanzen","neues leben zweck","was bewirken gaeasamen"}},{q="Wohin muss ich gehen, um die Samen zu pflanzen?",a="Reist von Sonnenfels nach Westen ins Verbrannte Tal. Gaeaerdhügel liegen über das geschwärzte Becken verteilt.",al={"wo liegt das verbrannte tal","wo gaeasamen pflanzen","pflanzorte für samen"}},{q="Wer ist Tammra Windfeld?",a="Tammra Windfeld ist eine Naturkundlerin der Tauren, die in Sonnenfels im Steinkrallengebirge lebt. Sie bemüht sich, die verwundeten Geister des Landes zu besänftigen und Orte wiederherzustellen, die von elementarer Wut und industrieller Gier verwüstet wurden.",al={"wer vergibt neues leben","tammra questgeberin","tammra windfeld hintergrundgeschichte"}},{q="Welche Bedrohungen durchstreifen das Verbrannte Tal während des Pflanzens?",a="Durch die Verwüstung aufgewühlte Schurken unter den Feuerelementaren und aggressive Bloodfury-Harpyien durchstreifen das Verbrannte Tal. Die Harpyien nisten zwischen den verbrannten Bäumen.",al={"verbranntes tal feinde","was greift im verbrannten tal an","gefahren im verbrannten tal"}},{q="Welche Quest kommt vor Neues Leben?",a="Cycle of Rebirth kommt vor Neues Leben. Ihr habt Tammra geholfen, die Materialien zu sammeln, die zur Vorbereitung der verzauberten Gaeasamen benötigt werden.",al={"neues leben voraussetzung","cycle of rebirth quest","was führt zu neues leben"}},{q="Was erhofft sich Tammra langfristig für das Steinkrallengebirge?",a="Tammra hofft, dass neues Wachstum die erzürnten Feuerelementare besänftigt, die räuberischen Harpyien vertreibt und die Holzfällerei der Venture Company überdauert. Sie möchte, dass das Gebirge wieder zu einem üppigen, friedlichen Wald wird.",al={"zukunft des steinkrallengebirges","tammras ziel","was geschieht mit dem verbrannten tal"}}},fx={c43560c5={q="Wofür ist der Gaeaschutthaufen?",a="Diese Hügel sind Flecken fruchtbaren Bodens, die über die ansonsten versengte und geschwärzte Erde im verbrannten Tal verstreut sind. Tammra Windfeld benötigt Euch, um die Verzauberte Gaeasamenkörner darin zu vergraben, damit die Samen Wurzeln schlagen, der lokalen Verderbnis widerstehen und neue Vegetation hervorbringen können, um das ruinierte Ödland langsam zurückzuerobern.",al={"gaeahügel zweck","was sind gaeahügel","warum in gaeahügel pflanzen"}}},fp="8,151,26.225.0,25.321.0,47.178.0,41.105.0,24.212.0,50.144.0,33.122.0,58.209.0"}
P.entries["quest:6382"] = {n="Die Jagd im Eschental",s="Im Eschental erwartet die bewährten Jäger der Horde eine neue Prüfung unter uralten Bäumen. Jorn Himmelsdeuter schickt Euch von Camp Taurajo nach Norden zum Splitterholzposten, wo Senani Donnerherz auf Euch wartet.",h="Im Eschental erwartet die bewährten Jäger der Horde eine neue Prüfung unter uralten Bäumen.",kw={"eschental","ashenvale hunt","brachland","camp taurajo","jorn himmelsdeuter","senani donnerherz","splitterholzposten"},ang={["class:Hunter"]="Als Jäger verlasst Ihr Kalimdors Ebenen und zieht unter das dichte Blätterdach des Eschentals, wo exotische Wildtiere darauf warten, aufgespürt, erforscht und gezähmt zu werden.",["faction:Horde"]="Als Mitglied der Horde betretet Ihr ein strategisches Grenzgebiet. Ein Stützpunkt im Eschental versorgt Siedlungen in ganz Durotar und im Brachland mit Holz und Nahrung.",["race:Tauren"]="Als Tauren folgt Ihr der Führung von Jorn Himmelsdeuter und Senani Donnerherz. Sie sehen die Jagd als spirituelles Gleichgewicht und als einen Weg, die Wildnis zu ehren."},sec={{t="Unter uralte Baumkronen",b="Nachdem Ihr Euch im Brachland bewährt habt, werdet Ihr ins Eschental geschickt. Jorn Himmelsdeuter erkennt, wann ein Jäger dem heimischen Wild entwachsen ist, und weist den Weg nach Norden. Für die junge Horde bieten diese alten Wälder Ressourcen und bilden eine politische und spirituelle Grenze, die es zu verstehen und zu beanspruchen gilt."},{t="Splitterholzposten",b="Die Straße nach Norden führt am Mor'shan-Schutzwall vorbei zum Splitterholzposten, einem befestigten Lager der Horde tief zwischen den Bäumen. Senani Donnerherz, eine Taurenjägerin, begrüßt erfahrene Jäger, die härtere Überlebensprüfungen suchen. Die Horde braucht geschickte Fährtenleser, um den heimischen Raubtieren des Eschentals und den wachsamen Verteidigern des Waldes zu begegnen."}},faq={{q="Wer schickt mich auf die Eschental Hunt?",a="Jorn Himmelsdeuter, ein Taurenjäger in Camp Taurajo im südlichen Brachland, schickt Euch nach Norden, nachdem Ihr Euer Können bei der Jagd auf heimische Wildtiere bewiesen habt.",al={"wer vergibt ashenvale hunt","questgeber ashenvale hunt","jorn himmelsdeuter quest"}},{q="Wo liegt der Splitterholzposten?",a="Der Splitterholzposten liegt im östlichen Teil des zentralen Eschentals, an der Nordseite der Straße. Folgt der Hauptstraße vom Brachland nach Norden, am Mor'shan-Schutzwall vorbei und weiter durch die Wälder hinauf.",al={"splitterholzposten standort","wo ist senani donnerherz","splitterholzposten finden"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine Taurenjägerin am Splitterholzposten. Sie koordiniert Jagden im ganzen Eschental und lehrt ankommende Jäger der Horde, die wildesten Raubtiere und Geister des Waldes zu verfolgen.",al={"senani donnerherz","wer ist senani","jägerin senani"}},{q="Welche anderen Außenposten der Horde gibt es in der Nähe im Eschental?",a="Die Horde unterhält außerdem das Holzfällerlager des Kriegshymnenklans im Osten und den Außenposten von Zoram'gar an der fernen Westküste am Zoramstrand.",al={"hordenstützpunkte eschental","andere lager eschental"}},{q="Warum interessiert sich die Horde für die Jagd im Eschental?",a="Die Wildnis des Eschentals bietet Fleisch, Felle und Ressourcen, die im trockenen Durotar und im Brachland knapp sind. Sich ihren gefährlichen Wildtieren zu stellen, prüft auch den Willen und die spirituelle Stärke der Jäger und Krieger der Horde.",al={"warum im eschental jagen","horde eschental beweggründe"}},{q="Welche Herausforderungen folgen auf diese Reise?",a="Senani Donnerherz schickt erfahrene Jäger los, um unter den Baumkronen Bedrohungen des Waldes aufzuspüren, darunter den großen Bären Ursangous, die Raubkatze Shadumbra und den Hippogryphen Sharptalon.",al={"nächste quest nach ashenvale hunt","was vergibt senani"}}},fx={["854a1b41"]={q="Warum schickt Euch Jorn Himmelsdeuter ins Eschental?",a="Jorn Himmelsdeuter erkennt Eure wachsende Stärke und Eure Bereitschaft an, die Jagd im Brachland anzunehmen. Für ihn seid Ihr den lokalen Prüfungen entwachsen und bereit für größeren Ruhm. Die dichten Wälder des Eschentals stellen eine wilde Grenze dar, an der die Horde bestrebt ist, sowohl spirituelle Meisterschaft als auch politische Kontrolle zu erlangen, und er möchte fähige Jäger wie Euch, um dabei zu helfen, diese Vorherrschaft zu etablieren.",al={"warum möchte jorn himmelsdeuter dies erledigt haben","jorn himmelsdeuter motiv","warum ins eschental gehen"}},["2c1005c5"]={q="Warum wählt Jorn Himmelsdeuter Euch für diese Jagd aus?",a="Jorn hat beobachtet, wie Ihr Euer Können und Euren Mut im gesamten Brachland bewiesen habt. Als erfahrener Führer und Ältester, der in Camp Taurajo stationiert ist, besteht seine Pflicht darin, Potenzial in aufstrebenden Kriegern zu erkennen und sie dorthin zu lenken, wo die Horde am meisten Stärke benötigt. Das Eschental verlangt nach getesteten, fähigen Jägern und nicht nach unerprobten Wachen, die an die Verteidigung von Außenposten gebunden sind.",al={"warum ich eschental jagd","warum wählt jorn mich aus","warum einen abenteurer schicken"}}},fp="18,182,23.279.0,17.332.0,35.135.0,35.180.0,27.191.0,50.124.0,52.192.0,36.177.0"}
P.entries["quest:6383"] = {n="Die Jagd im Eschental",s="Im Eschental stellen sich Jäger der Horde in Senani Donnerherz' Prüfung am Splitterholzposten drei großen Raubtieren. Spürt Ursangous, Shadumbra und Sharptalon auf, um Euer Können zu beweisen.",h="Im Eschental stellen sich Jäger der Horde in Senani Donnerherz' Prüfung am Splitterholzposten drei großen...",kw={"jagd im eschental","rajenbaum","senani donnerherz","shadumbra","sharptalon","splitterholzposten","der steinkrallenpfad","ursangous"},ang={["class:Hunter"]="Als Jäger durchkämmt Ihr weite Waldgebiete, lest das Gelände und stellt Euch Bestien, die einen unachtsamen Fährtenleser leicht überwältigen können.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr im Eschental einen Pfad kriegerischer Ehre und spiritueller Verbundenheit finden, während die Warsong den Wald kahl schlagen.",["race:Tauren"]="Als Taurenjäger ehrt Ihr die Schöpfung der Erdenmutter, indem Ihr Ursangous, Shadumbra und Sharptalon aufspürt. Die Jagd hält den Respekt vor der Wildheit der Natur und die Ehre der Pirsch im Gleichgewicht."},sec={{t="Taurentradition im uralten Wald",b="Senani Donnerherz stellt die Präsenz der Horde im Eschental auf eine andere Art von Probe. Während Orcs Holz sammeln, schickt sie Jäger in den schattigen Wald, um sich seinen stärksten Raubtieren zu stellen. Stärke allein genügt nicht; Jäger brauchen List und Respekt vor der Wildnis. Sie müssen erfahren, was sie ertragen können."},{t="Die drei großen Bestien",b="Drei einzelgängerische Bestien prüfen jene, die sich auf die Jagd begeben. Ursangous, ein gewaltiger alter Bär, streift nahe dem Steinkrallenpfad umher. Shadumbra, ein listiger Nachtsäbler, schleicht an den östlichen Grenzen nahe Rajenbaum und den Laughing Sisters umher. Südlich des Splitterholzpostens zieht Sharptalon, ein wilder Hippogryph, über dem Blätterdach des Waldes seine Kreise."}},faq={{q="Wer beginnt die Jagd im Eschental?",a="Senani Donnerherz, eine im Eschental stationierte Taurenjägerin, leitet die Jagd. Sie fordert Reisende der Horde heraus, ihre Überlebenskunst in der Wildnis zu beweisen.",al={"questgeber jagd im eschental","wer vergibt die jagd","senani donnerherz quest"}},{q="Welche Bestien muss ich aufspüren?",a="Spürt Ursangous, den großen Bären, Shadumbra, den Nachtsäbler, und Sharptalon, den Hippogryphen, auf.",al={"welche tiere töten","drei bestien","ziele der jagd im eschental"}},{q="Wo ist Ursangous zu finden?",a="Ursangous streift unmittelbar westlich des Steinkrallenpfads unter den wilden Bären des Waldes umher.",al={"ursangous fundort","wo ist der bär","ursangous finden"}},{q="Wo schleicht Shadumbra umher?",a="Shadumbra schleicht südlich von Rajenbaum umher, nahe der Straße, an der die als Laughing Sisters bekannten Dryaden leben.",al={"shadumbra fundort","wo ist shadumbra","nachtsäbler fundort"}},{q="Wo lässt sich Sharptalon aufspüren?",a="Sharptalon durchstreift das Gebiet südlich des Splitterholzpostens und fliegt über die Bäume und die Lichtung.",al={"sharptalon fundort","wo ist sharptalon","hippogryph fundort"}},{q="Warum schickt Senani Donnerherz Jäger auf die Spur dieser Bestien?",a="Senani versteht die Jagd als ehrenvolle Prüfung, nicht als sinnloses Abschlachten. Die Begegnung mit den tödlichsten natürlichen Bewohnern des Waldes soll Jäger etwas über die Wildnis und ihre eigene Stärke lehren.",al={"warum auf die jagd gehen","zweck der jagd","hintergrundgeschichte der jagd"}}},fx={e25adf54={q="Was sind die Bestien der Jagd im Eschental?",a="Die Jagd fordert Euch heraus, drei legendäre Raubtiere aufzuspüren, die in den uralten Wäldern vom Eschental heimisch sind: Ursangous, ein massiver und wilder Bär, der in der Nähe vom Steinkrallenpfad umherstreift; Shadumbra, ein schwer zu fassender Nachtsäbler, der durch die Wälder südlich vom Rajenbaum schleicht; und Scharfkralle, ein grimmiger Hippogryph, der südlich vom Splitterholzposten kreist. Jedes von ihnen repräsentiert die ungezähmte Macht und List des Waldes selbst.",al={"welche bestien jage ich","ziele der jagd im eschental","wer sind die bestien"}},a64a5cc6={q="Warum lässt Senani Donnerherz Abenteurer die Jagd durchführen anstatt die örtlichen Wachen?",a="Die Jagd im Eschental ist keine militärische Aufgabe oder ein Aufruf zur Ausrottung. Es ist ein traditioneller Initiationsritus, der die persönliche List, Stärke und Entschlossenheit eines Jägers gegen die Wildnis auf die Probe stellen soll. Die Garnison vom Splitterholzposten ist damit beauftragt, den Außenposten der Horde in feindlichem Gebiet zu verteidigen, doch diese Prüfung ist eine individuelle Reise, auf der Ihr die wildesten Bestien des Waldes aufsucht, um Euren eigenen Wert zu beweisen.",al={"warum schickt man mich","warum abenteurer","warum keine wachen vom splitterholzposten"}}},fp="18,171,39.309.0,22.321.0,30.164.0,36.88.0,29.78.0,28.110.0,32.81.0,61.180.0"}
P.entries["quest:6384"] = {n="Flug nach Orgrimmar",s="Vom Wegekreuz fliegt Ihr mit Zarghs frischen Fleischstücken zu Orgrimmars Himmelsturm. Dort liefert Ihr sie bei Gastwirtin Gryshka ab.",h="Vom Wegekreuz fliegt Ihr mit Zarghs frischen Fleischstücken zu Orgrimmars Himmelsturm.",kw={"brachland","das wegekreuz","devrak","doras","gryshka","orgrimmar","himmelsturm","wind rider","zargh"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr mit einem Wind Rider zwischen dem Wegekreuz im zentralen Brachland und Orgrimmar reisen, wo Kriegshäuptling Thrall herrscht.",["profession:Cooking"]="Gryshka macht ihren Geschmack deutlich, als sie Zarghs Geschenk erhält. Sie bevorzugt die edelsten Tiere Kalimdors blutig serviert, damit ihr Geschmack erhalten bleibt."},sec={{t="Schwingen über der Savanne",b="Devrak schickt ausgebildete Wind Rider zwischen dem Wegekreuz und Orgrimmar hin und her. Ihr Flug führt über das trockene Brachland bis zu Durotars roten Klippen und erspart Reisenden den beschwerlichen Fußmarsch. Hoch über den staubigen Schluchtenpfaden tragen Wyvern Boten und Reisende samt Depeschen und Handelsgütern in die Hauptstadt."},{t="Sonderlieferung für Gryshka",b="Zargh hat frische Fleischstücke für Gastwirtin Gryshka im Tal der Stärke in Orgrimmar vorbereitet. Vom zentralen Himmelsturm ist ihr Gasthaus nur einen kurzen Fußweg entfernt. Gryshka nimmt das Paket entgegen und bemerkt liebevoll, dass Zargh weiß, wie man das Herz einer Dame gewinnt."}},faq={{q="Welchen Zweck hat dieser Flug?",a="Der Flug macht Euch mit den Flugrouten der Wind Rider der Horde vertraut. Ihr bezahlt Devrak für den Flug vom Wegekreuz nach Orgrimmar und bringt Zarghs frische Fleischstücke zu Gastwirtin Gryshka.",al={"warum nach orgrimmar fliegen","flug nach orgrimmar zweck","warum fleisch nach orgrimmar"}},{q="Wo landet der Wind Rider in Orgrimmar?",a="Der Wind Rider landet auf Orgrimmars Himmelsturm über dem Tal der Stärke. Rampen führen hinunter zum Hauptplatz, zu den Händlern in der Nähe und zu Gryshkas Gasthaus.",al={"wo landet man in org","himmelsturm standort","orgrimmar flug landung"}},{q="Wer ist Gryshka?",a="Gastwirtin Gryshka führt eine Taverne im Tal der Stärke in Orgrimmar. Sie heißt Reisende willkommen und pflegt eine herzliche Freundschaft mit Zargh, der frische Fleischstücke für ihre Küche liefert.",al={"gastwirtin gryshka","wer ist gryshka","gryshka standort"}},{q="Wer ist Devrak?",a="Devrak ist der Meister der Wind Rider am Wegekreuz im Brachland. Er versorgt die Wyvern und koordiniert den Flugverkehr zwischen dem Außenposten, Durotar und anderen Siedlungen der Horde.",al={"devrak wegekreuz","wer ist devrak","wegekreuz meister der wind rider"}},{q="Warum schickt Zargh rohes Fleisch an Gryshka?",a="Zargh schickt Gryshka frisches Wild aus dem Brachland als Geschenk. Sie schätzt die erlesenen Fleischstücke und sagt, dass sie ihr Herz gewinnen.",al={"zargh fleisch","warum fleisch an gryshka schicken","zargh und gryshka"}},{q="Was soll ich nach der Fleischlieferung tun?",a="Nachdem Ihr das Fleisch abgeliefert habt, schickt Gryshka Euch zurück zum Himmelsturm, um mit Doras, Orgrimmars Meister der Wind Rider, über den Rückflug zu sprechen.",al={"was kommt nach flug nach orgrimmar","nächste quest nach gryshka","wohin nach der lieferung"}}},fx={a3e1a2de={q="Warum möchte Devrak, dass Ihr nach Orgrimmar fliegt?",a="Devrak ist der Wind Rider-Meister des Wegekreuzes, verantwortlich für die Verbindung des Brachlandes mit dem Rest des Flugnetzwerks der Horde. Indem er für Euch die Überfahrt organisiert, um Zarghs frisches Paket an Gryshka zu liefern, hält er den wichtigen Botenverkehr zwischen Außenposten und Hauptstadt in Bewegung, während er gleichzeitig reisende Abenteurer mit der Schnelligkeit und Bequemlichkeit des Wyverntransports vertraut macht.",al={"warum schickt euch devrak","devrak motiv","warum ritt nach orgrimmar"}},["715139d2"]={q="Warum schickt Devrak Euch, anstatt selbst nach Orgrimmar zu fliegen?",a="Devrak kann seinen Sitz am Wegekreuz nicht aufgeben. Als Flugmeister besteht seine Pflicht darin, sich um die Wind Rider zu kümmern und Flüge für Boten, Späher und Krieger im gesamten zentralen Kalimdor zu koordinieren. Die Übergabe der Fracht an einen fähigen Reisenden, der in Richtung der Hauptstadt unterwegs ist, stellt sicher, dass die Lieferung prompt ankommt, ohne ihn von seinem Posten wegzuziehen.",al={"warum schickt er mich","warum kann devrak das fleisch nicht liefern","warum ich ritt nach orgrimmar"}}},fp="17,135,22.317.0,28.245.0,35.182.0,44.150.0,15.173.0,14.172.0,41.124.0,43.145.0"}
P.entries["quest:6385"] = {n="Doras der Windreitermeister",s="Gastwirtin Gryshka möchte Zargh im Wegekreuz danken und braucht einen Kurier, der ihren Dank überbringt. Sie schickt Euch zu Doras dem Windreitermeister am Himmelsturm von Orgrimmar, um Euren Rückflug ins Brachland zu organisieren.",h="Gastwirtin Gryshka möchte Zargh im Wegekreuz danken und braucht einen Kurier, der ihren Dank überbringt.",kw={"brachland","das wegekreuz","doras","flugmeister","gryshka","orgrimmar","wind rider","wyvern","zargh"},ang={["faction:Horde"]="Das Netz der Wind Rider verbindet Orgrimmar mit wichtigen Garnisonen der Region. Es hilft der jungen Horde, Truppen und Vorräte durch Kalimdors Wildnis zu bewegen.",["race:Orc"]="Als Orc teilt Ihr die enge Verbundenheit Eures Volkes mit den in Kalimdor heimischen Wyvern. Orcs verlassen sich auf ihre Wendigkeit und Stärke als fliegende Reittiere und Lasttiere."},sec={{t="Die Antwort eines Kuriers",b="Gastwirtin Gryshka schickt Zargh ihren Dank, nachdem seine Fleischlieferung aus den Jagdgründen im Brachland sicher angekommen ist. Sie hat keine Zeit, selbst durch Durotar zu reisen. Deshalb vertraut sie den Luftkurieren, die die Siedlungen der Horde verbinden, ihren Brief für den Weg über die Grenze an."},{t="Der Meister der Station",b="Am Flugturm im Tal der Stärke beaufsichtigt Doras Orgrimmars Station der Wind Rider. Ausgebildete Wyvern befördern militärische Nachrichten und Vorräte zwischen der Hauptstadt und Außenposten wie dem Wegekreuz. Sie sind weit schneller unterwegs als jeder, der zu Fuß oder mit einem Kodokarren reist."}},faq={{q="Wer ist Doras?",a="Doras betreut Orgrimmars ausgebildete Wyvern und koordiniert Flugreisen zu fernen Stützpunkten der Horde im zentralen Kalimdor.",al={"doras","wer ist doras","flugmeister orgrimmar"}},{q="Warum schickt Gastwirtin Gryshka diesen Brief?",a="Gryshka schickt Zargh, dem Schlachter im Wegekreuz, einen Dankesbrief für das Fleisch, das sicher in ihrer Taverne in Orgrimmar angekommen ist.",al={"warum brief schicken","gryshkas brief","wozu dient der brief"}},{q="Wo ist Doras zu finden?",a="Doras befindet sich oben auf dem zentralen Flugturm über Orgrimmars Tal der Stärke. Holzrampen im Inneren des Turms führen zu ihm hinauf.",al={"wo ist doras","doras standort","doras finden"}},{q="Was geschieht, nachdem Ihr Doras Gryshkas Brief gegeben habt?",a="Nachdem Ihr mit Doras gesprochen habt, macht er einen Wind Rider bereit, der Euch zurück ins Brachland trägt. Ihr könnt Gryshkas Brief bei Zargh im Wegekreuz abliefern.",al={"was kommt als nächstes","nach doras","nächste quest"}},{q="Wer ist Zargh?",a="Zargh ist ein Orcschlachter im Wegekreuz im Brachland und ein Freund von Gryshka. Er hat ihr ausgewählte Fleischstücke aus dem Brachland geschenkt.",al={"zargh","wer ist zargh"}},{q="Warum Wind Rider nutzen, statt zu Fuß zu gehen?",a="Der Landweg von Orgrimmar führt durch Durotar und über den Südstrom ins Brachland. Die Reise ist langsam und gefährlich, daher nutzt die Horde gezähmte Wind Rider, um Späher, Befehle und Kuriere rasch zwischen den Siedlungen zu befördern.",al={"warum fliegen","zweck der wind rider","hintergrund der flugrouten"}}},fx={a0f5ace5={q="Warum bittet Gryshka einen Abenteurer, ihren Brief zu befördern?",a="Gryshka betreibt die geschäftige zentrale Taverne im Tal der Stärke und kann ihren Posten nicht einfach verlassen, um zurück ins Brachland zu reisen. Ihr seid gerade angekommen und tragt eine Lieferung von Zargh aus dem Wegekreuz bei Euch, was Euch zum natürlichen Boten macht, um ihre Antwort zu befördern. Da Ihr die Route bereits kennt und Flugverbindungen freigeschaltet habt, ermöglicht ihr das Übergeben des Briefes an Euch, dass ihre Dankbarkeit schnell über das etablierte Wind Rider-Netzwerk der Horde zurückkehrt, ohne die Stadtwache von Orgrimmar von der Bewachung der Hauptstadt abzuziehen.",al={"warum ich doras","warum bittet mich gryshka wegen brief","warum bringt keine wache gryshkas brief"}}},fp="27,206,17.269.0,23.265.0,13.120.0,45.126.0,25.124.0,52.149.0,13.132.0,39.234.0"}
P.entries["quest:6386"] = {n="Kehrt nach Klingenhügel zurück",s="Gryshkas Antwort reist von Orgrimmar zu Zargh im Wegekreuz. Ein Wind Rider trägt sie über Durotar und das Brachland.",h="Gryshkas Antwort reist von Orgrimmar zu Zargh im Wegekreuz.",kw={"brachland","das wegekreuz","devrak","doras","gryshka","brief","orgrimmar","wind rider","wyvern","zargh"},ang={["faction:Horde"]="Die Wind Rider-Horste in Orgrimmar und im Wegekreuz verbinden die Hauptstadt der Horde mit Kalimdors gefährlichen Ebenen. Zwischen ihnen befördern die Wind Rider Handelswaren und Vorräte.",["race:Orc"]="Als Ork wisst Ihr, dass kräftige Stücke frischen Wildbrets zu den besten Geschenken gehören, um einem möglichen Gefährten Zuneigung und Respekt zu zeigen."},sec={{t="Rückkehr auf Schwingen",b="Ihr bringt Gryshkas schriftliche Antwort zu Zargh, nachdem Ihr ihr in Orgrimmar ein Paket mit erstklassigem Fleisch überbracht habt. Doras, der Wind Rider-Meister auf Orgrimmars hohen Klippen, stellt Euch ein Reittier für die Rückkehr ins Brachland zur Verfügung.\n\nIhr seid Devrak im Wegekreuz bereits begegnet, daher kennen die Wyvern die Flugroute. Der Flug führt durch den Wüstenhimmel und erspart Euch den langen Fußmarsch über den Südstrom."},{t="Eine Liebe im Brachland",b="Zarghs Brautwerbung hat ihm Gryshkas herzliche Antwort eingebracht. Die erlesenen Vorräte haben ihr gefallen, und Zargh feiert und denkt sogar über eine bevorstehende Hochzeit nach.\n\nDie Lieferung bringt Euch auch zum zentralen Verkehrsknotenpunkt des Brachlands zurück."}},faq={{q="Warum muss ich für die Rückkehr einen Wind Rider nutzen?",a="Doras schickt Euch mit einem Wind Rider zurück, weil Ihr Devrak im Wegekreuz bereits besucht habt. Die Wyvern fliegen zwischen den beiden Horsten, sparen Zeit und sichern die Versorgungslinien.",al={"warum zurückfliegen","wind rider erforderlich","zu fuß zurück"}},{q="Wer ist Gryshka?",a="Gryshka ist die Gastwirtin in Orgrimmars Tal der Stärke. Zargh schickte ihr erlesenes Fleisch aus dem Brachland, um ihre Gunst zu gewinnen.",al={"gryshkas geschichte","wer ist gryshka","fleischfrau in orgrimmar"}},{q="Was wollte Zargh erreichen, als er Fleisch nach Orgrimmar schickte?",a="Zargh schickte Fleisch, um Gryshka zu umwerben. Unter Orks ist ein Geschenk aus nahrhaftem, hochwertigem Wildbret aus dem Brachland eine große romantische Geste.",al={"warum schickte zargh fleisch","zarghs beweggründe","zargh brief"}},{q="Wo endet diese Quest?",a="Ihr kehrt zu Zargh im Wegekreuz im Brachland zurück, nahe dem Wachturm und den Ställen, und übergebt ihm Gryshkas Brief.",al={"wo abgeben","rückkehrort","wer bekommt gryshkas brief"}},{q="Wer ist Doras?",a="Doras ist der Wind Rider-Meister am Flughorst über Orgrimmars Tal der Stärke. Er betreut die fliegenden Reittiere, die ganz Kalimdor bereisen.",al={"doras wind rider","doras aufenthaltsort","flugmeister in orgrimmar"}},{q="Was geschieht nach dieser Quest?",a="Ihr schließt die Kurierquestreihe Meats to Orgrimmar ab. Orgrimmar und das Wegekreuz sind verbunden, und das Brachland steht Euch für weitere Reisen offen.",al={"fortsetzung der questreihe","nächste quest nach der rückkehr","meats to orgrimmar fortsetzung"}}},fx={["0a3565f0"]={q="Warum möchte Doras, dass ich zum Wegekreuz zurückkehre?",a="Doras hat kein persönliches Interesse an Zarghs Romanze, aber als Wind Rider-Meister von Orgrimmar besteht seine Rolle darin, das Luftbotennetzwerk der Horde zu demonstrieren. Da Ihr nun Orgrimmar mit dem Flughorst am Wegekreuz verbunden habt, beweist die Rückkehr auf einer Wyvern mit Gryshkas Antwort, dass das System funktioniert, während gleichzeitig wichtige persönliche Korrespondenz zurück ins Brachland befördert wird.",al={"warum schickt mich doras zurück","doras motiv rückkehr zum wegekreuz","warum gryshkas brief zurücknehmen"}}},fp="25,120,15.392.0,27.217.0,44.173.0,15.125.0,51.122.0,26.118.0,13.146.0,30.138.0"}
P.entries["quest:6387"] = {n="Ehrenlehrlinge",s="Brock Steinsucher schickt eine Bestellung für Ehrenhacken von Thelsamar nach Eisenschmiede. Er bittet Euch, Thorgrum Borrelson damit zu betrauen, sie dorthin zu bringen.",h="Brock Steinsucher schickt eine Bestellung für Ehrenhacken von Thelsamar nach Eisenschmiede.",kw={"brock steinsucher","golnir geröllzeh","greif","ehrenlehrlinge","eisenschmiede","loch modan","bergbau","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Als Reisender der Allianz in Loch Modan begegnet Ihr den Flugmeistern und Luftkurieren, die die Siedlungen miteinander verbinden.",["profession:Mining"]="Als Bergmann seht Ihr, wie Zwerge handwerkliches Können würdigen. Wer den Umgang mit Stein beherrscht und Erzadern aufspürt, kann sich die Anerkennung eines Lehrers verdienen.",["race:Dwarf"]="Als Zwerg seht Ihr die Verbundenheit zwischen Grenzsiedlungen wie Thelsamar und den Hallen der Hauptstadt tief in den Bergen."},sec={{t="Der Lohn eines Bergmanns",b="Brock unterrichtet angehende Bergleute in Gesteinszusammensetzung und Tunnelsicherheit. Er belohnt Lehrlinge, die sich hervortun, mit Ehrenhacken. Der Bergbau sichert Thelsamars Lebensunterhalt, und die Zwerge sind stolz auf ihr Handwerk. Die örtlichen Vorräte sind begrenzt, daher müssen die Hacken quer durch Khaz Modan aus Eisenschmiede kommen."},{t="Hinauf in die Lüfte",b="Thorgrum betreut den Gryphon Roost bei Thelsamar und verbindet das Grenzland über das Luftkuriernetz des Königreichs mit Eisenschmiede. Bringt ihm Brocks Bestellung, und er kann einen schnellen Kurierflug zu den Gießereien der Hauptstadt organisieren."}},faq={{q="Wer ist Brock Steinsucher?",a="Brock Steinsucher lehrt Bergbau in Thelsamar. Er bildet Anfänger im Abbau und in der Steinbearbeitung aus.",al={"brock steinsucher","wer ist brock","bergbaulehrer thelsamar"}},{q="Warum braucht Brock Hacken aus Eisenschmiede?",a="Brock braucht Ehrenhacken für Schüler, die sich im Bergbau auszeichnen, doch die örtlichen Vorräte sind begrenzt. Seine Bestellung muss Golnir Geröllzeh erreichen, einen Händler für Bergbaubedarf in Eisenschmiede.",al={"warum eisenschmiede","warum hacken","brocks liste"}},{q="Welche Rolle spielt Thorgrum Borrelson bei dieser Aufgabe?",a="Thorgrum Borrelson betreut Thelsamars Gryphon Roost. Brock bittet Euch, ihm die Bestellung zu bringen, damit er den Lufttransport nach Eisenschmiede organisieren kann.",al={"thorgrum borrelson","wer ist thorgrum","greifenmeister thelsamar"}},{q="Wer erhält die Liste in Eisenschmiede?",a="Golnir Geröllzeh erhält die Liste in Eisenschmiede. Er stellt Ehrenhacken für Brocks erfolgreiche Schüler bereit.",al={"wer bekommt die liste","golnir geröllzeh","kontakt in eisenschmiede"}},{q="Wohin führt dieser Botengang als Nächstes?",a="Nachdem Ihr mit Thorgrum Borrelson gesprochen habt, organisiert er einen Greifenflug nach Eisenschmiede. Dort könnt Ihr Brocks Bestellung bei Golnir Geröllzeh abgeben.",al={"nächster schritt","was folgt auf ehrenlehrlinge","nach brocks liste"}},{q="Wo findet diese Aufgabe statt?",a="Ihr beginnt und endet in Thelsamar, einer Siedlung in den Hügeln von Loch Modan.",al={"questort","wo ist thelsamar","wo beginnt ehrenlehrlinge"}}},fx={["7a941756"]={q="Warum bittet Brock Steinsucher einen Abenteurer, anstatt die Liste selbst zu liefern?",a="Brock ist damit beschäftigt, angehende Bergleute hier in Thelsamar auszubilden, neuen Rekruten das Handwerk beizubringen und sich um seine Schmiede zu kümmern. Seinen Posten zu verlassen, um den ganzen Weg nach Eisenschmiede zu reisen, würde den Unterricht für die lokalen Lehrlinge zum Stillstand bringen, was einen reisenden Abenteurer zum perfekten Boten macht, um seine Liste in die Stadt zu bringen.",al={"warum bittet mich brock","warum geht brock nicht nach eisenschmiede","warum kann brock die liste nicht nehmen"}}},fp="14,147,13.290.0,19.225.0,25.94.0,41.171.0,52.138.0,35.111.0,33.142.0,32.75.0"}
P.entries["quest:6388"] = {n="Gryth Thurden",s="In Eisenschmiede kann Gryth Thurden Euch mit einem Paket zurück nach Loch Modan schicken. Ihr tragt Golnir Geröllzehs Ehrenhacken für die Bergbaulehrlinge von Brock Steinsucher, und der Greifenhorst der Stadt bietet einen Weg über die Bergstraßen hinweg.",h="In Eisenschmiede kann Gryth Thurden Euch mit einem Paket zurück nach Loch Modan schicken.",kw={"flugmeister","golnir geröllzeh","gryth thurden","ehrenhacken","eisenschmiede","loch modan","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Euch auf die Greifenhorste von Eisenschmiede verlassen, um Gesandte zwischen Dun Morogh, Loch Modan und den weiter entfernten Königreichen zu befördern.",["profession:Mining"]="Als Bergmann helft Ihr den Lehrlingen von Brock Steinsucher in Loch Modan mit zeremoniellen Hacken, die in Eisenschmiede zu Ehren ihres Handwerks geschmiedet wurden.",["race:Dwarf"]="Als Zwerg verlasst Ihr Euch auf Greifen, um tückische Gipfel zu überqueren. Sie sind eine praktische Notwendigkeit und ein Quell des überlieferten Stolzes, der die Berghallen verbindet."},sec={{t="Ein Kurier für die Bergleute",b="Ihr seid von Loch Modan zur Großen Schmiede gereist, wo Golnir Geröllzeh Euch Ehrenhacken für die Bergbaulehrlinge von Brock Steinsucher gibt. Er verweist Euch auf das Greifennetzwerk von Eisenschmiede, statt Euch zu Fuß über die Gebirgspässe zu schicken. Tragt das Bündel quer durch die Stadt zum Obertiermeister, der Euren Rückflug organisieren kann."},{t="Auf Schwingen nach Thelsamar",b="Gryth Thurden beaufsichtigt die Greifenhorste von Eisenschmiede in der großen Berghalle. Greifenrouten verbinden die Stadt mit Zwergensiedlungen in ganz Khaz Modan. Nachdem Ihr die Route erkundet und mit dem örtlichen Tiermeister gesprochen habt, könnt Ihr Gryth bitten, Euren Rücktransport zu Thorgrum Borrelson in Thelsamar zu organisieren. Die Hacken sind für die Lehrlinge von Brock Steinsucher bestimmt, und die Route verbindet Bergsiedlungen durch die Luft."}},faq={{q="Wofür sind die Ehrenhacken bestimmt?",a="Golnir Geröllzeh fertigte die Ehrenhacken in Eisenschmiede als zeremonielle Werkzeuge für die Schüler von Brock Steinsucher, einem Bergbaulehrer in Thelsamar.",al={"ehrenhacken","warum ehrenhacken","hacken für brock"}},{q="Wer ist Gryth Thurden?",a="Gryth Thurden beaufsichtigt die Flugrouten von Eisenschmiede, die von der Zwergenhauptstadt zu Siedlungen in ganz Khaz Modan und darüber hinaus führen.",al={"wer ist gryth thurden","greifenmeister eisenschmiede","gryth thurden hintergrundgeschichte"}},{q="Wo befindet sich Gryth Thurden in Eisenschmiede?",a="Gryth Thurden steht am Greifenhorst der Großen Schmiede, nahe der zentralen Hauptverkehrsader und den Toren von Eisenschmiede.",al={"gryth thurden standort","wo gryth thurden finden","flugmeister eisenschmiede"}},{q="Warum muss ich zuerst mit Thorgrum Borrelson sprechen?",a="Gryth Thurden kann erst dann einen Reiter nach Thelsamar schicken, wenn Ihr mit Thorgrum Borrelson, dem Tiermeister in Loch Modan, gesprochen habt. Tiermeister schicken Reiter auf kartierten Routen los.",al={"thorgrum borrelson voraussetzung","warum flugroute nach thelsamar nötig","flug nach thelsamar nicht möglich"}},{q="Was geschieht, nachdem ich Gryth Thurden die Hacken gegeben habe?",a="Nachdem Gryth das Paket geprüft hat, bereitet er einen Greifenflug vor, damit Ihr nach Thelsamar zurückkehren und die Werkzeuge direkt bei Brock Steinsucher abliefern könnt.",al={"was kommt nach gryth thurden","nächste quest nach gryth thurden"}},{q="Wer schickt Euch zu Gryth Thurden?",a="Golnir Geröllzeh, ein Handwerker im Bereich der Großen Schmiede von Eisenschmiede, gibt Euch die Hacken und verweist Euch an Gryth.",al={"wer vergibt gryth thurden","wer vergibt diese quest"}}},fx={["05b277d3"]={q="Warum schickt Euch Golnir Geröllzeh zu Gryth Thurden?",a="Golnir Geröllzeh hat die Ehrenhacken vorbereitet, die für Brock Steinsuchers Bergbauschüler in Thelsamar bestimmt sind. Anstatt Euch zu Fuß durch den verschneiten Pass zurückwandern zu lassen, weist Golnir Euch an Gryth Thurden, den Greifenmeister von Eisenschmiede, damit Ihr lernt, wie man einen Greifenflug direkt über die Berge arrangiert.",al={"warum zu gryth schicken","golnir geröllzeh motiv","warum gryth thurden hacken"}}},fp="13,241,24.321.0,24.397.0,32.160.0,21.118.0,44.105.0,50.179.0,53.144.0,31.115.0"}
P.entries["quest:639"] = {n="Siegelzeichen von Strom",s="In Hammerfall sucht Zengu die Siegel, die Trol'kalar schützen, das Schwert von Lord Ignaeus Trollbane. Das Syndikat hat das Siegelzeichen von Strom entwendet, und vermutlich trägt einer seiner Agenten in Stromgarde es bei sich.",h="In Hammerfall sucht Zengu die Siegel, die Trol'kalar schützen, das Schwert von Lord Ignaeus Trollbane.",kw={"arathihochland","hammerfall","ignaeus","siegelzeichen von strom","stromgarde","syndikat","trol'kalar","trollbane","zengu"},sec={{t="Das Vermächtnis von Trollbane",b="Vor langer Zeit war Lord Ignaeus von Strom, genannt Trollbane, im Krieg des Imperiums von Arathor gegen die Trolle deren fähigster Widersacher. Er führte Trol'kalar in der Schlacht. In der alten Sprache der Trolle bedeutet der Name Trolltöter. Nun sind Trollbanes Söhne geschwächt, und ihre Festung liegt in Ruinen."},{t="Das erste Siegel",b="Mehrere Siegel schützen Trol'kalar, und die Überlebenden von Stromgarde nahmen jeweils einige an sich. Zengu sagt, dass sie alle wiederbeschafft werden müssen. Das Syndikat hat das erste an sich gerissen, das Siegelzeichen von Strom. Zengu glaubt, dass einer seiner Agenten in Stromgarde es besitzt. Bringt das Siegel zu Zengu nach Hammerfall zurück."}},faq={{q="Wer ist Zengu?",a="In Hammerfall in Arathi sammelt Zengu die Siegel, die Trol'kalar schützen, das Schwert von Lord Ignaeus Trollbane.",al={"wer vergibt siegelzeichen von strom","zengu hammerfall"}},{q="Was ist Trol'kalar?",a="Trol'kalar bedeutet in der uralten Sprache der Trolle Trolltöter. Lord Ignaeus von Strom, genannt Trollbane, ritt mit dem Schwert gegen die Trolle in die Schlacht.",al={"was ist trolkalar","trol'kalar bedeutung","trollbanes schwert"}},{q="Warum wird das Siegelzeichen von Strom benötigt?",a="Mehrere Siegel schützen Trol'kalar, und die Überlebenden von Stromgarde teilten sie untereinander auf. Zengu will sie alle, angefangen mit dem Siegelzeichen von Strom.",al={"warum das siegel beschaffen","zweck des siegelzeichens von strom"}},{q="Wer besitzt das Siegelzeichen von Strom?",a="Das Syndikat hat das Siegelzeichen von Strom entwendet. Höchstwahrscheinlich trägt einer seiner Agenten in Stromgarde es bei sich.",al={"wer hat das siegelzeichen von strom","wo ist das siegelzeichen von strom","syndikat siegel"}}},fp="14,186,23.280.0,15.268.0,13.109.0,19.153.0,33.147.0,29.98.0"}
P.entries["quest:6391"] = {n="Flug nach Eisenschmiede",s="Brock Steinsucher schickt Euch mit den Namen seiner besten Bergbauschüler von Thelsamar nach Eisenschmiede. Ihr bringt seine Liste zu Golnir Geröllzeh an der Großen Schmiede.",h="Brock Steinsucher schickt Euch mit den Namen seiner besten Bergbauschüler von Thelsamar nach Eisenschmiede.",kw={"brocks liste","deep mountain mining guild","golnir geröllzeh","die große schmiede","greif","kharanos","flug nach eisenschmiede","thorgrum borrelson"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Euch auf Greifenrouten verlassen, die Khaz Modans Frontgarnisonen mit seiner Hauptstadt verbinden.",["profession:Mining"]="Als Bergmann seht Ihr, wie die Deep Mountain Mining Guild vielversprechende Bergleute aus den Gruben von Loch Modan ehrt, indem sie ihre Namen in Hacken graviert.",["race:Dwarf"]="Als junger Bronzebeard-Zwerg markiert Euer Greifenflug in die Große Schmiede einen stolzen Übergang von ländlichen Außenposten ins Herz des Königreichs."},sec={{t="Auf in die Lüfte",b="Thorgrum Borrelson trägt Euch von Thelsamar über die verschneiten Bergrücken von Dun Morogh zur Bergfestung. Für viele junge Gebirgsjäger und Reisende ist dies ihr erster Flug auf einem Greifen."},{t="Ehrungen der Deep Mountain Guild",b="An der Großen Schmiede graviert Golnir Geröllzeh die Namen der Schüler in zeremonielle Ehrenhacken. Diese Ehrungen würdigen ihre harte Arbeit in den Steinbrüchen und Minen von Loch Modan."}},faq={{q="Wo beginnt und endet dieser Flug?",a="Thorgrum Borrelson trägt Euch von Thelsamar in Loch Modan zum Greifenhorst bei der Großen Schmiede in Eisenschmiede.",al={"flugroute","wohin fliegen","flugziel"}},{q="Was ist Brocks Liste?",a="Brock Steinsuchers Liste nennt seine besten Bergbauschüler in Thelsamar, damit die Gilde in Eisenschmiede ihren Fleiß ehren kann.",al={"brocks liste hintergrund","wer ist brock","was ist das papier"}},{q="Wer ist Golnir Geröllzeh?",a="Golnir Geröllzeh vertritt die Deep Mountain Mining Guild an der Großen Schmiede in Eisenschmiede. Er erhält Namenslisten von örtlichen Ausbildern und graviert die Namen der Schüler in Ehrenhacken.",al={"golnirs rolle","wo ist golnir","wer ist golnir geröllzeh"}},{q="Was geschieht, nachdem Ihr die Liste überbracht habt?",a="Sobald Golnir die Namensliste erhält, schickt er Euch zu Gryth Thurden, Eisenschmiedes Greifenmeister, um mehr über die Flugrouten des Königreichs zu erfahren.",al={"nächste quest","was danach tun","folgequest"}},{q="Warum einen Greifen nehmen, statt zu Fuß zu gehen?",a="Die Bergstraße und die Tunnel führen zu den Toren von Eisenschmiede, doch ein Greifenflug zeigt, wie schnell Reisende der Allianz zwischen Siedlungen vorankommen.",al={"warum fliegen","zu fuß nach eisenschmiede","warum ein greif"}},{q="Was ist eine Ehrenhacke?",a="Eine Ehrenhacke ist ein zeremonielles Werkzeug, das die Deep Mountain Mining Guild herausragenden Bergbauschülern verleiht. Regionale Ausbilder vermitteln ihnen die Grundlagen des Abbaus und der Geologie.",al={"ehrenhacken","hacke als belohnung","bergbauhacke zeremonie"}}},fx={d8819fd3={q="Warum möchte Thorgrum Borrelson, dass Ihr nach Eisenschmiede reitet?",a="Thorgrum Borrelson ist Thelsamars Greifenmeister im Loch Modan und sein Geschäft hängt davon ab, dass Reisende von seinem Horst aus abheben. Indem er Euren Flug nach Eisenschmiede arrangiert, damit Ihr Brocks Liste der vielversprechenden Bergbauschüler an Golnir Geröllzeh überbringen könnt, führt er Euch in die Schnelligkeit und Bequemlichkeit des Greifenflugs ein und stellt gleichzeitig sicher, dass wichtige Korrespondenz der Gilde ohne Verzögerung die Hauptstadt erreicht.",al={"thorgrum borrelson motiv","warum nach eisenschmiede schicken","warum brocks liste überbringen"}}},fp="17,161,19.186.0,33.171.0,37.107.0,21.124.0,25.179.0,40.143.0,37.143.0,25.179.0"}
P.entries["quest:6392"] = {n="Rückkehr zu Gremlock",s="Ihr bringt Brock Steinsuchers Schreiben nach Eisenschmiede und erhaltet Ehrenhacken für seine Lehrlinge. Gryth Thurden kann Euch nach Thelsamar zurückfliegen.",h="Ihr bringt Brock Steinsuchers Schreiben nach Eisenschmiede und erhaltet Ehrenhacken für seine Lehrlinge.",kw={"brock steinsucher","flugmeister","greif","gryth thurden","ehrenhacken","eisenschmiede","rückkehr zu gremlock","thelsamar"},ang={["profession:Mining"]="Die Lieferung der Ehrenhacken gibt Loch Modans angehenden Bergleuten Werkzeuge für ihre Arbeit und führt die zwergische Tradition des Grabens und Schürfens fort.",["race:Dwarf"]="Als Zwerg wisst Ihr, wie Wildhammer-Greifen und die Greifenmeister von Eisenschmiede die Zwergenfesten auf dem Luftweg verbinden."},sec={{t="Hinauf in die Lüfte",b="Gryth Thurden beaufsichtigt Eisenschmiedes Greifenflüge von der zentralen Plattform der Stadt aus. Um nach Thelsamar zu fliegen, müsst Ihr zuerst den dortigen Greifenmeister Thorgrum Borrelson kennengelernt haben. Dann kann Gryth Euch und die Hacken über die Berge tragen und so Brocks Botschaft und Werkzeuge zum Loch zurückbringen."},{t="Hacken für die Lehrlinge",b="Brock Steinsucher lehrt Bergbau in Thelsamar und braucht Werkzeuge für seine Lehrlinge. Mit den Ehrenhacken können junge Bergleute die reichen Kupfer- und Zinnadern in den Hügeln rund um den Loch abbauen."}},faq={{q="Wer ist Brock Steinsucher?",a="Brock Steinsucher ist ein zwergischer Bergbaulehrer in Thelsamar in Loch Modan. Er lehrt angehende Bergleute, Erz und Stein aus den umliegenden Hügeln zu gewinnen.",al={"brock steinsucher","wer ist brock","brock in thelsamar"}},{q="Warum muss ich auf einem Greifen fliegen, um diese Quest abzuschließen?",a="Gryth Thurden kann Euch nach Thelsamar fliegen, weil Ihr den dortigen Horst bereits besucht und mit Thorgrum Borrelson gesprochen habt. Greifen tragen Reisende nur zu Horsten, die sie bereits besucht haben.",al={"warum fliegen","flugroutenquest","greifenritt"}},{q="Wofür sind die Ehrenhacken?",a="Die Ehrenhacken sind Bergbauwerkzeuge, die Brock Steinsucher für seine neuen Schüler in Loch Modan braucht.",al={"ehrenhacken","was sind die hacken"}},{q="Wer ist Gryth Thurden?",a="Gryth Thurden ist Eisenschmiedes Greifenmeister und an der Großen Schmiede stationiert. Er verwaltet Flüge von und zur Hauptstadt quer durch Khaz Modan und darüber hinaus.",al={"gryth thurden","flugmeister eisenschmiede"}},{q="Kann ich einfach nach Thelsamar zurücklaufen, statt zu fliegen?",a="Ihr könnt nach Thelsamar zurücklaufen und die Ehrenhacken bei Brock Steinsucher abliefern. Die Reise macht Euch mit den Greifenrouten vertraut, und Brock braucht die Werkzeuge sicher in seinen Händen.",al={"kann ich zurücklaufen","muss ich den greifen nehmen"}},{q="Wo in Thelsamar befindet sich Brock?",a="Brock Steinsucher steht im Freien nahe der Schmiede und dem Amboss von Thelsamar, wo er Bergleuten in Loch Modan hilft.",al={"wo ist brock","brock steinsucher standort","brock finden"}}},fx={c8277dbd={q="Warum möchte Gryth Thurden, dass Ihr die Hacken ausliefert?",a="Gryth Thurden verwaltet die Greifenhorste von Eisenschmiede und hält die Flugrouten des Königreichs in Verbindung. Brock Steinsucher unten in Thelsamar wartet auf eine dringende Lieferung von Ehrenhacken für seine Bergbauschüler. Da Ihr bereits den Weg zwischen Eisenschmiede und Thorgrum Borrelsons Horst erkundet habt, nutzt Gryth diese Lieferung sowohl, um Brocks Versorgungsbedarf zu decken, als auch, um sicherzustellen, dass Ihr die Kunst des Greifenflugs über Khaz Modan meistert.",al={"warum will gryth das","gryth thurden motiv","warum hacken zu brock schicken"}},be2b1abc={q="Warum schickt Gryth Thurden einen Abenteurer, anstatt es selbst zu erledigen?",a="Gryth Thurden kann seinen Posten an der Großen Schmiede nicht verlassen, wo er den ständigen Strom von Reitern und die Pflege der geschätzten Greifen von Eisenschmiede überwacht. Da Ihr persönlich Brocks Schreiben in die Stadt gebracht und die Flugroute zurück nach Thelsamar freigeschaltet habt, seid Ihr der ideale Kurier, um die neu eingerichtete Verbindung zu testen und die Vorräte direkt in die Hände des Bergmanns zu bringen.",al={"warum braucht gryth mich","warum einen abenteurer nach thelsamar schicken","warum keinen kurier schicken"}}},fp="15,145,19.279.0,20.188.0,25.143.0,55.176.0,32.95.0,21.149.0,52.176.0,36.102.0"}
P.entries["quest:6393"] = {n="Krieg der Elementare",s="Im Steinkrallengebirge schickt Euch Tsunaman in Neptulons Namen gegen Feuerelementare in den Kampf. Der Wassergesandte in Sonnenfels bittet Euch, das Verbrannte Tal zu betreten und Pyrophor-Kerne von den lodernden Elementaren zu sammeln, die Ihr vernichtet. Ihr Ringen reicht über die Grenzen der Sterblichen hinaus und ist mit der uralten Rivalität zwischen den Elementarkräften verbunden.",h="Im Steinkrallengebirge schickt Euch Tsunaman in Neptulons Namen gegen Feuerelementare in den Kampf.",kw={"das verbrannte tal","krieg der elementare","feuerelementare","pyrophore","neptulon","steinkrallengebirge","sonnenfels","tribunal of the tides","tsunaman"},ang={["class:Shaman"]="Als Schamane erlebt Ihr das Aufeinanderprallen der Urkräfte, während Neptulons Diener gegen die Feuerelementare kämpfen.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Kampf der Elementare unterstützen, während Ihr durch das Steinkrallengebirge reist. Tsunaman ist in Sonnenfels stationiert."},sec={{t="Rivalität der Urkräfte",b="In Sonnenfels im Steinkrallengebirge spricht Tsunaman für das Tribunal of the Tides. Ihr vollstreckt den Willen von Neptulon the Tidehunter gegen die feurigen Verwandten seiner Wasserelementare. Ihre Feindschaft reicht weit über die Grenzen der Sterblichen hinaus. Es ist ein uralter Kampf zwischen den Urkräften Azeroths."},{t="Die Asche und die Flamme",b="Im südlichen Steinkrallengebirge liegt das Verbrannte Tal, wo Asche und Rauch das Land zeichnen. Dort sammeln sich Feuerelementare und bedrohen die umliegenden Regionen. Tsunaman schickt Euch aus, um sie zu vernichten und die Pyrophore zu sammeln, die sie hinterlassen. Diese lodernden Kerne beweisen dem Tribunal, dass die Elementare vernichtet sind."}},faq={{q="Wer ist Tsunaman?",a="Tsunaman ist ein Gesandter des Tribunal of the Tides in Sonnenfels im Steinkrallengebirge. Unter der Autorität von Neptulon the Tidehunter führt er Krieg gegen Feuerelementare und schickt Euch aus, um sie zu vernichten.",al={"wer ist tsunaman","tsunaman questgeber","sonnenfels elementar"}},{q="Warum will Neptulon die Feuerelementare vernichten?",a="Neptulon the Tidehunter hegt eine uralte Feindschaft gegen Feuerelementare und strebt ihre Vernichtung an. Das Tribunal of the Tides hat Tsunaman entsandt, um diesen Feldzug im Steinkrallengebirge zu führen.",al={"warum gegen feuerelementare kämpfen","grund für den krieg der elementare","neptulon feuerelementare"}},{q="Wo liegt das Verbrannte Tal?",a="Das Verbrannte Tal liegt im südlichen Steinkrallengebirge. Feurige Elementare und andere gefährliche Bestien, geboren aus Flammen und Verwüstung, überrennen seinen aschebedeckten Talkessel.",al={"wo liegt das verbrannte tal","feuerelementare fundort steinkrallengebirge","wo findet man pyrophore"}},{q="Was sind Pyrophore?",a="Pyrophore sind brennende Überreste, die zurückbleiben, wenn die Feuerelementare des Verbrannten Tals vernichtet werden. Tsunaman sammelt diese Kerne als Beweis ihrer Vernichtung und um die Gunst des Tribunal of the Tides zu gewinnen.",al={"was sind pyrophore","beute von feuerelementaren","pyrophore hintergrundgeschichte"}},{q="Was ist das Tribunal of the Tides?",a="Das Tribunal of the Tides ist eine Autorität unter den Wasserelementaren, die Neptulon the Tidehunter dient. Es lenkt Elementarkräfte und Gesandte wie Tsunaman, um den Willen des Tidehunters gegen rivalisierende Elementarreiche zu vollstrecken.",al={"tribunal of the tides hintergrundgeschichte","wer ist das tribunal of the tides","wasserelementare fraktion"}},{q="Wer ist Neptulon the Tidehunter?",a="Neptulon the Tidehunter ist der Elementarherr des Wassers und Herrscher über die Ozeane, Meere und alle Wasserelementare. Wie die anderen Elementarherren führt er einen uralten, endlosen Kampf gegen rivalisierende Elemente, insbesondere das Feuer.",al={"wer ist neptulon","elementarherr des wassers","neptulon tidehunter"}}},fp="13,330,31.297.0,21.307.0,16.202.0,53.191.0,34.153.0,21.205.0,34.227.0,31.223.0"}
P.entries["quest:6394"] = {n="Thazz'rils Hacke",s="Großknecht Thazz'ril braucht seine verzauberte Spitzhacke aus der nördlichen Höhle zurück. Bestien durchstreifen nun den Koven der Brennenden Klinge, wo das leuchtende Werkzeug liegt.",h="Großknecht Thazz'ril braucht seine verzauberte Spitzhacke aus der nördlichen Höhle zurück.",kw={"koven der brennenden klinge","durotar","großknecht thazz'ril","bergbau","spitzhacke","thazz'ril","das tal der prüfungen","wasserfall"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, grundlegende Werkzeuge zu sichern und Bedrohungen wie den Koven der Brennenden Klinge zu vertreiben. Das stärkt die Stellung der Horde im Tal der Prüfungen.",["profession:Mining"]="Als Bergarbeiter wisst Ihr, warum Großknecht Thazz'ril auf seine verzauberte Spitzhacke vertraut, um in ganz Durotar nach Mineralien zu suchen. Er hofft, neue Bergbaumöglichkeiten zu erschließen, sobald die Bäume vor Ort gefällt sind."},sec={{t="Ein verlorenes Werkzeug",b="Großknecht Thazz'ril leitet die Arbeiten im Tal der Prüfungen. Er betrat die nördliche Höhle, um nach Mineraladern zu suchen, und ließ seine Lieblingsspitzhacke zurück. Als er zurückkehrte, hatten wilde Bestien und feindselige Bewohner die Höhle eingenommen. Nun sucht er fähige Helfer, die das Werkzeug zurückbringen."},{t="Leuchten im Dunkeln",b="Thazz'ril verzauberte seine Lieblingsspitzhacke, damit sie im Dunkeln leuchtet und sich in düsteren Höhlen leichter benutzen lässt. Ihr Licht kennzeichnet das Werkzeug in einer Kammer mit Wasserfällen im Koven der Brennenden Klinge. Gefährliche Kreaturen durchstreifen die Schatten. Thazz'ril hofft, die Spitzhacke wieder einzusetzen und im ganzen Tal neue Bergbaumöglichkeiten zu finden."}},faq={{q="Wer ist Großknecht Thazz'ril?",a="Großknecht Thazz'ril beaufsichtigt die Arbeiten und die Rohstoffgewinnung im Tal der Prüfungen. Er leitet die Peons an, während sie Bäume fällen und das Land für den Bergbau vorbereiten.",al={"wer ist thazzril","thazzrils aufgabe","großknecht thazzril"}},{q="Warum leuchtet Thazz'rils Spitzhacke?",a="Thazz'ril verzauberte seine Lieblingsspitzhacke, damit sie im Dunkeln leuchtet und in stockfinsteren Höhlen leichter zu erkennen ist.",al={"warum ist die spitzhacke besonders","leuchtende spitzhacke","verzauberte spitzhacke"}},{q="Wo liegt der Koven der Brennenden Klinge?",a="Der Koven der Brennenden Klinge ist ein dunkles Höhlennetz nördlich des Holzfällerlagers der Peons im Tal der Prüfungen.",al={"wo liegt der koven der brennenden klinge","standort des kovens","spitzhacke höhle"}},{q="Wie hat Thazz'ril seine Spitzhacke verloren?",a="Thazz'ril ließ seine Lieblingsspitzhacke zurück, als er die nördliche Höhle nach Mineralien absuchte. Als er zurückkehrte, hatten sich wilde Bestien und finstere Kultisten in der Höhle eingenistet.",al={"wie verlor thazzril seine spitzhacke","warum die spitzhacke zurücklassen","zurückgelassene spitzhacke"}},{q="Wo in der Höhle blieb die Spitzhacke zurück?",a="Thazz'ril ließ die Spitzhacke tief in der Höhle zurück, in einer unterirdischen Kammer mit Wasserfällen, wo er die Felswände untersucht hatte.",al={"wo in der höhle","kammer der spitzhacke","wasserfallkammer"}},{q="Was plant Thazz'ril, sobald er seine Spitzhacke zurückhat?",a="Thazz'ril plant, eine ergiebige Höhle für den Bergbau zu finden, sobald seine Peons die umliegenden Bäume im Tal der Prüfungen gefällt haben.",al={"thazzrils zukunftspläne","was wird thazzril abbauen"}}},fp="16,144,11.273.0,16.311.0,25.151.0,31.106.0,33.101.0,32.163.0,40.128.0,59.133.0"}
P.entries["quest:6395"] = {n="Marlas letzter Wunsch",s="In Todesend vereint Marlas letzter Wunsch ein Ehepaar im Tod. Novize Elreth bittet Euch, Samuel Fipps zu finden, der noch immer an die Geißel gebunden ist, damit er neben Marla begraben werden kann. Die Verlassenen ehren die Bande des Lebens und grenzen sich von der Geißel ab.",h="In Todesend vereint Marlas letzter Wunsch ein Ehepaar im Tod.",kw={"todesend","grab","marla fipps","marlas letzter wunsch","novize elreth","überreste","samuel fipps","geißel"},ang={["class:Priest"]="Als Priester der Verlassenen erinnert Euch Novize Elreths Beharren auf angemessenen Bestattungsriten an Eure geistliche Pflicht angesichts von Sterblichkeit, Trauer und der Schändung von Lordaerons Toten.",["race:Undead"]="Als frisch auferstandener Verlassener könnt Ihr durch die Erfüllung von Marlas Wunsch eine Verbindung zu Eurem früheren menschlichen Leben knüpfen. Es zeigt, dass Mitgefühl und Ehre den Fall Lordaerons überdauert haben."},sec={{t="Ein tragisches Wiedersehen",b="Vor dem Dritten Krieg lebten Marla und Samuel Fipps als Mann und Frau in Lordaeron. Der Krieg verwüstete ihre Heimat, und als die Seuche über ihr Land hereinbrach, erlag Samuel ihr. Er erhob sich als willenloser Knecht der Geißel. Marla blieb der Untod erspart, doch Samuel tötete sie in seinem Wahn. Sie hegte keinen Hass gegen ihn. Novize Elreth erinnert sich an Marlas letzten Wunsch: auf dem Friedhof von Todesend neben Samuel zu ruhen."},{t="Achtung vor den Toten",b="Novize Elreth schickt Euch nordöstlich von Todesend, wo Samuel Fipps noch immer in einem zerstörten Lager umherirrt. Wer seine Qualen beendet, befreit das Tal von einem Diener der Geißel. Dann können seine Überreste zu Marlas Ruhestätte zurückgebracht werden. Elreth glaubt, dass die Achtung vor den Toten und ihren letzten Wünschen die frisch befreiten Verlassenen von der Geißel unterscheidet."}},faq={{q="Wer war Marla Fipps?",a="Marla Fipps lebte in Lordaeron und überlebte die Seuche, doch Samuel tötete sie, nachdem er zu einem willenlosen Knecht der Geißel geworden war. Sie wünschte sich, neben ihm zu ruhen.",al={"marla fipps geschichte","wer ist marla","marla hintergrund"}},{q="Wer ist Samuel Fipps?",a="Samuel Fipps war vor der Seuche Marlas Ehemann. Er fiel der Geißel anheim und verlor seinen Verstand, dann tötete er Marla. Bis Abenteurer der Verlassenen seine Qualen beenden, irrt er durch ein zerstörtes Lager nordöstlich von Todesend.",al={"samuel fipps geschichte","wer ist samuel fipps","wo ist samuel fipps"}},{q="Warum ist es Novize Elreth wichtig, die beiden gemeinsam zu begraben?",a="Novize Elreth war zu Lebzeiten mit Marla befreundet. Elreth glaubt, dass die Ehrung der Toten und der würdevolle Umgang mit ihren Überresten zeigen, dass die Verlassenen im Gegensatz zur willenlosen Geißel ihre Menschlichkeit und Moral bewahrt haben.",al={"warum marla helfen","novize elreth beweggrund","warum samuel begraben"}},{q="Ist Marla als Verlassene auferstanden?",a="Nein. Novize Elreth sagt, Marla sei der Untod erspart geblieben. Samuel tötete sie, als sie noch sterblich war, und sie wurde auf dem Friedhof von Todesend begraben.",al={"ist marla untot","wurde marla eine verlassene","marla fipps untot"}},{q="Wo befindet sich Marlas Grab?",a="Marlas Grab liegt in der ersten Reihe des Friedhofs direkt vor der Hauptkapelle von Todesend.",al={"marlas grab fundort","wo ist marla begraben","wo samuel begraben"}},{q="Wo ist Samuel Fipps zu finden?",a="Samuel Fipps irrt durch ein zerstörtes Lager an der Straße nordöstlich von Todesend.",al={"samuel fipps fundort","samuel fipps finden","wo ist samuel"}}},fx={e919b4a2={q="Wofür sind Samuels sterbliche Überreste?",a="Ihr sammelt Samuels sterbliche Überreste, damit sie endlich neben seiner Frau Marla beigesetzt werden können. Obwohl Samuel in die gedankenlose Geißel verwandelt wurde und ihr das Leben nahm, war Marlas letzter Wunsch, dass sie eine ewige Ruhestätte auf dem Friedhof von Todesend teilen.",al={"samuels überreste","warum samuels überreste sammeln","samuels überreste zweck"}},["74d32be4"]={q="Wer ist Samuel Fipps und warum müsst Ihr ihn besiegen?",a="Samuel Fipps war einst ein lebender Bewohner von Tirisfal, der der Seuche des Untodes erlag und ein willenloser Diener der Geißel wurde. Nachdem er in seinem geistlosen Zustand seine eigene Frau getötet hat, wandelt er nun als Ghul in dem zerstörten Lager nordöstlich von Todesend umher und findet keine Ruhe, bis er vernichtet wird.",al={"warum samuel fipps töten","gegen wen kämpfe ich in marlas letzter wunsch","samuel fipps lore"}}},fp="17,263,16.400.0,19.346.0,20.151.0,20.210.0,56.207.0,27.142.0,31.90.0,32.78.0"}
P.entries["quest:64"] = {n="Das vergessene Erbstück",s="In Westfall ist das vergessene Erbstück eine Taschenuhr, die bei der Flucht der Furlbrows von ihrem Hof zurückblieb. Ihre Bergung gibt ihnen die Chance, inmitten des Chaos etwas Persönliches zurückzugewinnen.",h="In Westfall ist das vergessene Erbstück eine Taschenuhr, die bei der Flucht der Furlbrows von ihrem Hof...",kw={"benny blaanco","defias","furlbrow","taschenuhr","kürbisfeld","verna brauenwirbel","kleiderschrank","westfall"},ang={["faction:Alliance"]="Die Not der Furlbrows zeigt, wie weit die Ordnung in der Kornkammer des Königreichs zerfallen ist. Als Reisender der Allianz müsst Ihr Euch um das kümmern, was die Krone vernachlässigt hat.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr, wie Gesetzlose ehrliche Bauern nur einen Tagesmarsch von der Hauptstadt entfernt von ihrem Land vertreiben. Ihre Not offenbart die Probleme im Inneren des Königreichs."},sec={{t="Vertreibung um Mitternacht",b="Bauer Brauenwirbel und Verna wurden mit Gewalt von ihrem Hof in Westfall vertrieben. Geschrei von den Kürbisfeldern weckte sie in der Nacht, sodass kaum Zeit blieb, zusammenzuraffen, was sie tragen konnten. Auf der Flucht ließ Furlbrow die Taschenuhr zurück, die Vernas Vater ihm an ihrem Hochzeitstag geschenkt hatte. Sie liegt noch immer im Kleiderschrank ihres besetzten Bauernhauses."},{t="Rowdys auf den Feldern",b="Defias-Schläger und Diebe, darunter Benny Blaanco, durchwühlen nun den verlassenen Hof der Furlbrows. Für gewöhnliche Leute könnte die Rückkehr wegen eines Erinnerungsstücks den Tod bedeuten. Ihr könnt die Taschenuhr aus dem Kleiderschrank holen und einer Familie etwas Würde zurückgeben, die durch Westfalls Gesetzlosigkeit fast alles verloren hat."}},faq={{q="Warum ist die Taschenuhr für Bauer Brauenwirbel so wichtig?",a="Vernas Vater schenkte Bauer Brauenwirbel die Taschenuhr an ihrem Hochzeitstag. Für die Furlbrows, die als Flüchtlinge ihre Lebensgrundlage verloren haben, bewahrt sie eine gefühlsvolle Verbindung zu ihrem früheren Leben und ihrem Familienerbe.",al={"warum uhr wichtig","furlbrows uhr bedeutung","wer schenkte furlbrow die uhr"}},{q="Wer hat die Furlbrows von ihrem Hof vertrieben?",a="Defias-Banditen und Plünderer vertrieben die Furlbrows in der Nacht von ihrem Hof. Ihr Angriff spiegelt die Gesetzlosigkeit wider, die viele Bauernfamilien unter Androhung von Gewalt zwingt, ihre Häuser und Felder aufzugeben.",al={"wer griff den hof an","wer besetzte furlbrows hof","was geschah mit den furlbrows"}},{q="Wo ist die Uhr versteckt?",a="Die Taschenuhr liegt in einem Schlafzimmerkleiderschrank auf dem Hof der Furlbrows, in den Kürbisfeldern westlich ihres Lagers am Straßenrand im Norden Westfalls. Hausbesetzer und Defias-Gesetzlose halten das Bauernhaus besetzt.",al={"wo ist die taschenuhr","uhr finden","standort des kleiderschranks"}},{q="Wer ist Benny Blaanco?",a="Benny Blaanco ist ein Gesetzloser, der sich mit Defias-Gefährten im Bauernhaus der Furlbrows aufhält. Sie plündern das verlassene Haus und bewachen es gegen jeden, der es zurückfordern könnte.",al={"benny blaanco hintergrund","wer ist der kerl im haus"}},{q="Wo halten sich die Furlbrows jetzt auf?",a="Bauer Brauenwirbel und Verna sitzen am Straßenrand in Westfall fest. Sie suchen bei ihrem Wagen Schutz und versuchen, den Zusammenbruch der Region zu überleben.",al={"wo sind die furlbrows","wo ist bauer brauenwirbel"}},{q="Schickt Sturmwind Wachen, um bei der Rückeroberung solcher Höfe zu helfen?",a="Sturmwinds reguläres Militär ist in Westfall kaum präsent, während in der Hauptstadt politische Gleichgültigkeit herrscht und es an Führung fehlt. Der Volksmiliz auf der Späherkuppe fehlt die Stärke, einzelne Höfe zurückzuerobern, wodurch die Siedler schutzlos bleiben.",al={"sturmwinds hilfe für westfall","warum keine wachen am hof"}}},fx={["028db52d"]={q="Was ist Brauenwirbels Taschenuhr?",a="Es ist eine gewöhnliche Uhr, aber ein unschätzbares Familienerbstück. Vernas Vater gab sie Bauer Brauenwirbel an ihrem Hochzeitstag. Nachdem sie ihr Land, ihre Ernte und ihr Zuhause in einer einzigen Nacht an Wegelagerer verloren haben, ist die Rückgewinnung dieses einzigen Andenkens alles, was das ältere Paar aus den Ruinen seines früheren Lebens retten konnte.",al={"brauenwirbels uhr","taschenuhr erbstück","was ist brauenwirbels uhr"}}},fp="22,179,19.341.0,23.309.0,56.205.0,45.209.0,26.205.0,21.162.0,36.139.0,59.247.0"}
P.entries["quest:640"] = {n="Das zerbrochene Siegelzeichen",s="Zengu schickt Euch los, um Sigile von der Miliz von Stromgarde zu bergen. Galen, Sohn von Thoras Trollbane, zerbrach das Sigil of Thoradin in elf Teile, und Ihr bringt sie zu Tor'gan in Hammerfall.",h="Zengu schickt Euch los, um Sigile von der Miliz von Stromgarde zu bergen.",kw={"arathihochland","zerbrochenes siegelzeichen","galen trollbane","hammerfall","sigil of thoradin","stromgarde","thoras trollbane","tor'gan","zengu"},sec={{t="Ein Sigil in Stücken",b="Drei Sigile bewachen die Gruft von Thoras Trollbane. Das erste habt Ihr dem Syndikat abgenommen. Die fest verschanzte Miliz von Stromgarde hält die anderen beiden. Galen, Thoras' Sohn, zerbrach das Sigil of Thoradin in elf Teile und verteilte sie unter den Verteidigern."},{t="Zu Tor'gan",b="Zengu bittet Euch, die Teile von den Verteidigern von Stromgarde zu beschaffen. Bringt sie dann zu Tor'gan, dem Troll-Schamanen in Hammerfall. Er kann sie wieder zu einem ganzen Sigil zusammenfügen."},{t="In Hammerfall",b="Tor'gan sagt, Zengu habe ihm erzählt, dass Ihr Hilfe braucht. Er untersucht die Teile und hält die Arbeit für machbar. Alle elf sind vorhanden, und die magische Struktur des Sigils lässt sich leicht wiederherstellen. Tor'gan fordert Euch auf, die Augen zu schließen. Bald verkündet er, dass das Sigil of Thoradin wieder ganz ist."}},faq={{q="Was ist das Sigil of Thoradin?",a="Das Sigil of Thoradin ist eines von drei Sigilen, die die Gruft von Thoras Trollbane bewachen. Galen zerbrach es in elf Teile und verteilte sie unter den Verteidigern von Stromgarde.",al={"sigil of thoradin hintergrund","zerbrochenes siegelzeichen bedeutung","was ist das zerbrochene siegelzeichen"}},{q="Wer hat das Sigil zerteilt?",a="Galen, Sohn von Thoras Trollbane, zerbrach das Sigil of Thoradin in elf Teile und verteilte sie unter den Verteidigern von Stromgarde.",al={"wer zerbrach das sigil","warum ist das sigil zerbrochen","galen trollbane sigil"}},{q="Wo werden die Sigilfragmente aufbewahrt?",a="Die Verteidiger von Stromgarde halten die Teile in den Reihen der fest verschanzten Miliz, die die verbleibenden Sigile bewacht.",al={"wo sind die fragmente","wer hat die fragmente","stromgarde verteidiger sigil"}},{q="Wer kann das zerbrochene Sigil zusammenfügen?",a="Tor'gan, der Troll-Schamane in Hammerfall, kann die Teile zu einem ganzen Sigil zusammenfügen.",al={"wer repariert das sigil","torgan sigil","wer fügt die fragmente zusammen"}},{q="Was ging dem voraus?",a="Dem geht Sigil of Strom voraus, wo Ihr das erste Sigil vom Syndikat geborgen habt.",al={"vorherige quest","welche quest kommt vor das zerbrochene siegelzeichen","sigil questreihe anfang"}}},fp="16,187,17.257.0,10.161.0,13.268.1,30.161.0,22.127.0,35.105.0,30.80.0,22.82.0"}
P.entries["quest:6401"] = {n="Kaya lebt",s="Makaba Flachhuf hat erfahren, dass Kaya Flathoof den Angriff der Grimtotem im Steinkrallengebirge überlebt hat. Er schickt Euch nach Sonnenfels, wo ihre Tante Tammra Windfeld voller Sorge wartet.",h="Makaba Flachhuf hat erfahren, dass Kaya Flathoof den Angriff der Grimtotem im Steinkrallengebirge überlebt...",kw={"flathoof","grimtotem","kaya","makaba","protect kaya","steinkrallengebirge","sonnenfels","tammra","tauren","windfeld"},ang={["faction:Horde"]="In der umkämpften Wildnis des Steinkrallengebirges sind die Truppen der Horde weit verstreut und knapp besetzt. Die Nachricht, dass Überlebende in Sicherheit sind, hilft den verstreuten Lagern, zusammenzuhalten.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Bedrohung durch die Grimtotem einen schmerzhaften Riss unter den Shu'halo vertieft. Unschuldige Familienmitglieder wie Kaya zu schützen, liegt Euch sehr am Herzen."},sec={{t="Ein Aufatmen",b="Die Grimtotem schlagen entlang der umkämpften Pfade des Steinkrallengebirges zu. Als ihr Dorf angegriffen wurde, fürchtete man, die junge Kaya Flathoof sei tot oder von den Abtrünnigen verschleppt worden. Ihre Rettung bringt Erleichterung, während die Stämme zwischen den zerklüfteten Felsen weiterkämpfen."},{t="Der Weg nach Sonnenfels",b="Makaba Flachhuf schickt Euch von Kaya aus nach Sonnenfels mit der Nachricht, dass sie in Sicherheit ist. Ihre Tante Tammra Windfeld wartet dort voller Sorge auf Nachricht von den Pfaden. Eure Botschaft tröstet die Familie und hält die Verbindung zum abgelegenen Außenposten der Horde aufrecht."}},faq={{q="Wer ist Kaya Flathoof?",a="Kaya Flathoof ist eine junge Tauren, die von ihrem Volk getrennt wurde, als abtrünnige Truppen der Grimtotem ihre Siedlung im Steinkrallengebirge angriffen.",al={"wer ist kaya","kaya flathoof","kaya"}},{q="Wer ist Tammra Windfeld?",a="Tammra Windfeld ist Kayas Tante und lebt in Sonnenfels im Steinkrallengebirge. Sie fürchtete, ihre Nichte sei beim Angriff der Grimtotem gestorben.",al={"tammra windfeld","wer ist tammra","kayas tante"}},{q="Wer hat Kayas Dorf angegriffen?",a="Truppen der Grimtotem haben Kayas Dorf angegriffen. Diese isolationistische Taurenfraktion macht im ganzen Gebirge Jagd auf rivalisierende Stämme und Reisende.",al={"wer hat kaya angegriffen","angriff auf das dorf","angriff der grimtotem"}},{q="Was geht dieser Quest voraus?",a="Ihr habt Kaya Flathoof gerade in 'Protect Kaya' geholfen, ihren Entführern zu entkommen und in Sicherheit zurückzukehren.",al={"voraussetzung","protect kaya","eskortquest"}},{q="Wo liegt Sonnenfels?",a="Sonnenfels liegt hoch oben im zentralen Steinkrallengebirge. Folgt der Hauptstraße nach Westen durch einen engen Gebirgspass in einen geschützten Talkessel.",al={"lage von sonnenfels","wo liegt sonnenfels","sonnenfels finden"}},{q="Warum schickt Makaba Flachhuf Euch, statt selbst zu gehen?",a="Makaba bleibt in seinem Lager nahe dem südöstlichen Rand des Steinkrallengebirges. Er schickt Euch, um seiner Familie in Sonnenfels rasch Nachricht zu bringen.",al={"warum makaba bleibt","warum mich schicken"}}},fx={["10e83b92"]={q="Warum möchte Makaba Flachhuf, dass diese Nachricht überbracht wird?",a="Ihr Dorf erlitt einen brutalen Angriff und die Überlebenden glaubten, die junge Kaya Flathoof sei bei dem Gemetzel umgekommen. Jetzt, da sie in Sicherheit ist, möchte Makaba die Nachricht sofort überbringen lassen, um die Trauer von Kayas Tante, Tammra Windfeld, zu lindern, die ängstlich im Sonnenfels wartet, ohne zu wissen, dass ihre Nichte überlebt hat.",al={"warum neuigkeiten zu tammra schicken","makaba flachhuf motiv","warum die neuigkeiten überbringen"}}},fp="12,171,18.225.0,25.235.0,21.134.0,24.141.0,28.132.0,29.91.0,34.146.0,59.133.0"}
P.entries["quest:641"] = {n="Siegelzeichen des Thoradin",s="Tor'gan hat das Siegelzeichen des Thoradin wiederhergestellt, und Zengu wartet in Hammerfall auf seine Rückkehr. Das Siegelzeichen kann das Siegel an Trollbane's tomb öffnen.",h="Tor'gan hat das Siegelzeichen des Thoradin wiederhergestellt, und Zengu wartet in Hammerfall auf seine...",kw={"arathihochland","hammerfall","siegelzeichen des thoradin","tor'gan","trol'kalar","trollbane's tomb","zengu"},sec={{t="Das wiederhergestellte Siegelzeichen",b="Tor'gans Wiederherstellung ist gelungen. Das Siegelzeichen des Thoradin kann das Siegel an Trollbane's tomb öffnen, also schickt er Euch zurück zu Zengu in Hammerfall. Zengu hat weitere Aufgaben für Euch."},{t="Auf halbem Weg",b="Zengu fragt, ob Ihr das zweite Siegelzeichen habt. Damit seid Ihr, wie er sagt, auf halbem Weg, Trol'kalar aus Trollbane's tomb zu holen. Das dritte Siegelzeichen bleibt schwer zu finden, weil seine Hüter durch Arathi ziehen. Zengu vertraut darauf, dass Ihr es finden werdet."}},faq={{q="Wozu dient das Siegelzeichen des Thoradin?",a="Das wiederhergestellte Siegelzeichen kann das Siegel an Trollbane's tomb öffnen.",al={"siegelzeichen des thoradin zweck","was bewirkt das siegelzeichen des thoradin","warum wird das siegelzeichen gebraucht"}},{q="Zu wem bringt Ihr das Siegelzeichen des Thoradin?",a="Bringt das wiederhergestellte Siegelzeichen zu Zengu in Hammerfall. Tor'gan schickt Euch zu ihm zurück.",al={"wohin mit dem siegelzeichen","wer gibt das siegelzeichen des thoradin ab","siegelzeichen des thoradin abgeben"}},{q="Wo steht dieser Schritt bei der Suche nach Trol'kalar?",a="Dieser Schritt folgt auf The Broken Sigil, als Tor'gan das Siegelzeichen aus den Stücken wiederherstellte, die Ihr ihm gebracht habt.",al={"fortschritt der siegelzeichen-questreihe","wie weit ist diese quest fortgeschritten","welche quest kommt davor"}}},fp="17,138,18.172.0,13.230.1,39.57.0,42.79.0,54.105.0"}
P.entries["quest:642"] = {n="Die gefangene Prinzessin",s="Ein schillernder Splitter trägt Myzraels Flehen aus der Tiefe durch das Arathihochland. Sie nennt sich eine Prinzessin der Erde, die von Riesen gefangen gehalten wird, und bittet Reisende, eine Kristallansammlung in der Schlucht der Trockenstoppel zu stärken.",h="Ein schillernder Splitter trägt Myzraels Flehen aus der Tiefe durch das Arathihochland.",kw={"arathihochland","schlucht der trockenstoppel","drywhisker-kobolde","erdprinzessin","schillernde splitter","motes of myzrael","myzrael","prinzessin der erde","die gefangene prinzessin"},ang={["class:Mage"]="Als Magier findet Ihr die schwingenden Splitter und Partikel voller Erdenergie vielleicht bemerkenswert, da sie Verständigung und Kraftübertragung über große Entfernungen ermöglichen.",["class:Shaman"]="Als Schamane sprecht Ihr mit Elementargeistern und könnt Myzraels Behauptung, eine Prinzessin der Erde zu sein, vielleicht einordnen. Ihre Gefangenschaft unter der Erde verlangt eine sorgfältige Prüfung der Elemente.",["profession:Mining"]="Als Bergmann könnt Ihr Drywhisker-Kobolden nahe der Schlucht und in unterirdischen Erzadern in Arathi begegnen. Vielleicht findet Ihr auch die verzauberten Kristallsplitter, die mit der Prinzessin verbunden sind."},sec={{t="Eine Stimme aus dem Stein",b="Seltsame Splitter liegen über das Arathihochland verstreut und summen vor ferner Macht. In ihrer Nähe erhebt sich Myzraels Stimme aus den Tiefen der Erde. Sie nennt sich eine Prinzessin der Erde, von uralten Riesen hinabgestürzt und unter der Erde gebunden. Von den Landen darüber abgeschnitten, nutzt sie die Kristalle, um ihr Flehen zu jedem zu tragen, der bereit ist zuzuhören."},{t="Die Verbindung zu Drywhisker",b="Myzrael schickt Euch nach Osten zur Schlucht der Trockenstoppel, wo Ihr den Kontakt zu ihr stärken sollt. Drywhisker-Kobolde bevölkern die Schlucht, und sie nennt sie Verbündete der Riesen, die sie gefangen halten. Sie tragen Motes of Myzrael bei sich und bewachen eine Ansammlung schillernder Splitter. Nehmt den Kobolden die Partikel ab und übertragt ihre Energie auf die Formation. Das wird die Kristallansammlung stärken und Eure Verbindung mit der gefangenen Prinzessin vertiefen."}},faq={{q="Wer ist Myzrael?",a="Myzrael ist die Stimme, die durch den Kristall spricht. Sie nennt sich eine Prinzessin der Erde, die tief unter dem Arathihochland gefangen ist, und bittet vorbeiziehende Reisende um Hilfe, die Oberfläche zu erreichen.",al={"wer ist die gefangene prinzessin","wer spricht durch den kristall","wer ist myzrael"}},{q="Wer hat Myzrael unter dem Hochland gefangen gesetzt?",a="Myzrael sagt, Riesen hätten sie unter Arathi eingesperrt. Sie haben sie tief unter der Erde gebunden, weshalb sie auf die verstreuten Splitter der Region angewiesen ist, um mit der Oberfläche zu sprechen.",al={"wer hat myzrael eingesperrt","wer hat die prinzessin gefangen gesetzt","warum ist myzrael unter der erde"}},{q="Was sind die Motes of Myzrael?",a="Motes of Myzrael sind kristalline oder elementare Fragmente, die Drywhisker-Kobolde bei sich tragen. Myzrael sagt, in ihnen schlummere genug Erdkraft, um die Splitteransammlungen zu aktivieren und ihre Verbindung zur Oberfläche zu stärken.",al={"warum haben die kobolde partikel","schlucht der trockenstoppel partikel","was sind motes of myzrael"}},{q="Wie sind die Drywhisker-Kobolde mit Myzraels Kerkermeistern verbunden?",a="Myzrael sagt, die Drywhisker-Kobolde in der Schlucht der Trockenstoppel seien Verbündete der Riesen, die sie eingesperrt haben. Sie bewachen eine Ansammlung von Kristallsplittern in der Schlucht, zwischen der Prinzessin und der Oberfläche.",al={"warum sind kobolde beteiligt","drywhisker-kobolde riesen","kobolde arbeiten mit riesen zusammen"}},{q="Wie kann Myzrael aus dem Untergrund sprechen?",a="Myzrael schickt ihre Stimme durch schillernde Kristallsplitter, die aus dem Boden des Arathihochlands ragen. Die Splitter tragen ihre Stimme durch die Tiefen zu den Menschen an der Oberfläche.",al={"wie spricht myzrael","schillernde splitter arathi","was sind die kristallsplitter"}},{q="Wo liegt die Schlucht der Trockenstoppel?",a="Die Schlucht der Trockenstoppel ist ein zerklüfteter Einschnitt im östlichen Arathihochland. Dort leben Drywhisker-Kobolde rings um die schillernde Splitteransammlung, die Ihr auf Myzraels Bitte mit den gesammelten Partikeln stärken sollt.",al={"wo liegt die schlucht der trockenstoppel","wohin die partikel bringen","drywhisker splitter fundort"}}},fp="20,233,22.343.0,25.439.0,15.201.0,42.162.0,30.206.0,62.187.0,46.182.0,34.188.0"}
P.entries["quest:6421"] = {n="Steinschlagklamm",s="Kobolde graben im Steinkrallengebirge nach Resonite, während Mor'rogal in Sonnenfels eine wachsende Unruhe in der Erde fürchtet.",h="Kobolde graben im Steinkrallengebirge nach Resonite, während Mor'rogal in Sonnenfels eine wachsende Unruhe in...",kw={"steinschlagklamm","earthen","kobold","mor'rogal","resonite","resonitkristall","steinkrallengebirge","sonnenfels","titan"},ang={["class:Shaman"]="Als Schamane, der auf die Erde hört, könnt Ihr eine unnatürliche Resonanz im Fels spüren, während Kobolde Relikte urzeitlicher elementarer Schöpfungskunst der Titanen freilegen.",["profession:Mining"]="Als Bergarbeiter erkennt Ihr, dass Resonite aus Boulderslide kein gewöhnliches Erz ist. Seine Struktur birgt uralte arkane Rückstände, die unterirdische Baumeister hinterlassen haben.",["race:Tauren"]="Als Taure, der die Earth Mother verehrt, könntet Ihr die uralten Werke der Titanen unter den Bergen als gefährliche Störung des natürlichen Gleichgewichts im Steinkrallengebirge betrachten."},sec={{t="Spannung im Stein",b="In Sonnenfels beobachtet Mor'rogal die Gipfel des Steinkrallengebirges und spürt, wie sich die Erde regt. Eine unnatürliche Unruhe steigt aus dem Südosten auf. In der Steinschlagklamm haben Kobolde ihre übliche Nahrungssuche aufgegeben und graben nun verbissen nach Resonite, einem seltenen Mineral unter der Erdoberfläche. Mor'rogal schickt Kundschafter der Horde an den Kobolden vorbei bis in die tiefsten Winkel der Höhle. Er bittet sie, Rohproben mitzubringen und herauszufinden, warum die Kobolde mit solcher Raserei schürfen."},{t="Die Uralten erwachen",b="Rohe Resonite-Kristalle summen vor uralter Magie der Earthen. Die Kobolde haben sich tief ins Gestein gegraben und einen Earthen freigelegt, eines jener urzeitlichen Steinwesen, die die Titanen formten, um Kalimdors unterirdische Fundamente zu gestalten. Ihr Bergbau hat ein Relikt der Urgeschichte aufgestört. Die Tauren müssen handeln, bevor sich das begrabene Wesen befreit."}},faq={{q="Wo liegt die Steinschlagklamm?",a="Südöstlich von Sonnenfels schneidet die Steinschlagklamm ins Steinkrallengebirge ein. Kobolde von Boulderslide überrennen ihre gewundenen Höhlen.",al={"steinschlagklamm lage","wo liegt die steinschlagklamm","wie die steinschlagklamm finden"}},{q="Wer vergibt die Quest Steinschlagklamm?",a="Mor'rogal, ein Taure in Sonnenfels, vergibt die Aufgabe. Sonnenfels ist der wichtigste Außenposten der Horde im Steinkrallengebirge.",al={"wer startet steinschlagklamm","questgeber steinschlagklamm","mor'rogal quest"}},{q="Was sind Resonite-Kristalle?",a="Resonite ist ein seltenes Mineral aus den Tiefen des Höhlensystems von Boulderslide. Es trägt Spuren der Magie der von den Titanen geschmiedeten Earthen, ein Zeichen dafür, dass die Kristalle nahe unterirdischen Relikten der Earthen entstanden.",al={"was ist resonite","resonite hintergrund","resonite-kristalle"}},{q="Warum bauen die Kobolde so fieberhaft Resonite ab?",a="Die Kobolde fanden Resonite, als sie nach glänzenden Erzen gruben. Ihre Grabungen führten sie tief unter die Berge, wo sie einen uralten, im Fels begrabenen Earthen aufstörten.",al={"warum schürfen die kobolde","ziel der kobolde von boulderslide","koboldplan steinkrallengebirge"}},{q="Was ist laut den Überlieferungen der Tauren ein Earthen?",a="In Mor'rogals uralten Überlieferungen sind Earthen steinerne Geschöpfe, die die Titanen vor langer Zeit schmiedeten, um das Grundgestein der Welt zu bearbeiten und zu formen.",al={"was sind earthen","earthen verbindung zu titanen","wer sind die earthen"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Nachdem Mor'rogal die Magie der Earthen in den Resonite-Kristallen entdeckt hat, bereitet er eine verzauberte Gegenmaßnahme vor. Er schickt Euch zurück in die Höhle, um der erwachten Bedrohung entgegenzutreten.",al={"nächste quest nach steinschlagklamm","was folgt auf steinschlagklamm","steinschlagklamm folgequest"}}},fx={["574c7326"]={q="Warum möchte Mor'rogal, dass dies untersucht wird?",a="Mor'rogal spürt eine unruhige Spannung im Steinkrallengebirge und fürchtet, dass ein unbekanntes Übel unter den Gipfeln brodelt. Die Kobolde haben begonnen, fieberhaft seltsame Resonitkristalle auszugraben, und Mor'rogal benötigt Proben und Aufklärung aus den Tiefen der Kavernen, um zu verstehen, welche uralten Kräfte sie möglicherweise stören.",al={"warum steinschlagklamm untersuchen","mor'rogal motiv","warum kümmert das mor'rogal"}},["6ccd8309"]={q="Gegen wen werdet Ihr in der Steinschlagklamm ausgesandt?",a="Ihr werdet gegen die Steinschlag-Kobolde ausgesandt, die die Schlucht südöstlich von Sonnenfels befallen. Normalerweise bloße Aasfresser, wurden diese Kobolde von einer hektischen Besessenheit ergriffen und graben unermüdlich tief unter der Erde, um Resoniterz abzubauen, was den Frieden der Felsen bedroht.",al={"wer ist in der steinschlagklamm","steinschlagklamm feinde","kobolde in der steinschlagklamm"}}},fp="19,126,20.449.0,22.329.1,37.134.0,40.128.0,27.177.1,51.171.1,44.128.0,41.164.1"}
P.entries["quest:643"] = {n="Siegelzeichen von Arathor",s="Zengu schickt Euch von Hammerfall aus, um ein Siegel zu suchen, das die Menschenkavallerie im Arathihochland bei sich trägt. Findet ihren Anführer, Lieutenant Valorcall, und bringt das Siegel zurück.",h="Zengu schickt Euch von Hammerfall aus, um ein Siegel zu suchen, das die Menschenkavallerie im Arathihochland...",kw={"arathihochland","hammerfall","lieutenant valorcall","siegelzeichen von arathor","stromgarde","trol'kalar","valorcall","zengu"},sec={{t="Die Kavallerie des Prinzen",b="Zengu bezweifelt, dass die Menschen Stromgarde beanspruchen können, geschweige denn das ganze Arathihochland. Dennoch schickt ihr Prinz seine letzten Reiter weiterhin durch die Lande. Zengu versteht nicht, warum. Er weiß, dass Lieutenant Valorcall diese Reiter anführt und eines der Siegel bei sich trägt. Findet Valorcall und bringt es nach Hammerfall zurück."},{t="Zu Pferde",b="Zengu warnt, dass Valorcall schwer einzuholen ist, denn sein Pferd trägt ihn rasch durch die Lande. Ist Valorcall erst beseitigt, erleiden Stromgardes Verteidiger einen schweren Schlag. Dann fehlt der Horde nur noch ein Siegel, um Trol'kalar an sich zu bringen."}},faq={{q="Wer schickt Euch auf die Suche nach dem Siegelzeichen von Arathor?",a="Zengu schickt Euch von Hammerfall aus auf die Suche nach dem Siegelzeichen von Arathor.",al={"siegelzeichen von arathor questgeber","wer vergibt siegelzeichen von arathor","wo beginnt siegelzeichen von arathor"}},{q="Wer besitzt das Siegelzeichen von Arathor?",a="Lieutenant Valorcall führt die Menschenkavallerie an und besitzt das Siegelzeichen von Arathor. Der Menschenprinz hat es ihm gegeben, und Zengu sagt, dass Valorcall zu Pferde unterwegs und schwer aufzuspüren ist.",al={"wer hat das siegelzeichen von arathor","wo ist valorcall","lieutenant valorcall standort"}},{q="Warum hat Lieutenant Valorcall das Siegel?",a="Zengu sagt, dass der Menschenprinz Lieutenant Valorcall eines der Siegel gegeben hat, aber er sagt nicht, warum.",al={"warum hat valorcall das siegel","wer gab valorcall das siegel"}},{q="Wo liegt diese Quest in der Questreihe um Trol'kalar?",a="Das Siegelzeichen von Arathor ist der fünfte Schritt in der Questreihe um Trol'kalar. Es folgt auf Sigil of Thoradin, und danach kommt Sigil of Trollbane.",al={"trolkalar questreihe arathor","was kommt vor siegelzeichen von arathor","was kommt nach siegelzeichen von arathor"}},{q="Wohin bringt Ihr das Siegel, sobald es gefunden ist?",a="Bringt das Siegel zu Zengu in Hammerfall zurück.",al={"wo siegelzeichen von arathor abgeben","siegelzeichen von arathor abgabe"}}},fp="16,164,20.312.0,12.231.1,43.61.0,31.175.0,45.100.0,44.136.0,46.44.0"}
P.entries["quest:644"] = {n="Siegelzeichen von Trollbane",s="In Hammerfall schickt Euch Zengu tief nach Stromgarde, um das Siegelzeichen von Trollbane zu holen. Prinz Galen verwahrt das letzte Siegel, das benötigt wird, um Trol'kalar zu beanspruchen.",h="In Hammerfall schickt Euch Zengu tief nach Stromgarde, um das Siegelzeichen von Trollbane zu holen.",kw={"galen trollbane","hammerfall","sigil of arathor","stromgarde","trol'kalar","zengu","zul'gurub"},sec={{t="Das letzte Siegel",b="Prinz Galen, Sohn von Thoras Trollbane, verwahrt das letzte Siegel in Stromgarde. Er wartet in einer Kapelle tief in den von der Miliz gehaltenen Bezirken. Zengu warnt, dass Galen gut bewacht und ein vortrefflicher Kämpfer ist. Ihr sollt den Prinzen töten und das Siegel zu Zengu nach Hammerfall zurückbringen."},{t="Zengus Urteil",b="Zengu fragt, ob die Linie von Ignaeus Trollbane gebrochen ist. Sobald dies der Fall ist, erklärt er, dass Trollbane-Blut sein Volk nicht länger heimsuchen wird. Sie besitzen nun jedes Siegel, das benötigt wird, um Trol'kalar zu beanspruchen. Zengu schwört, dass sie bald gegen die Trolle von Zul'Gurub losschlagen werden, die er hasst."}},faq={{q="Wer schickt Euch los, um das Siegelzeichen von Trollbane zu holen?",a="Zengu schickt Euch von Hammerfall aus, um das Siegelzeichen von Trollbane zu holen.",al={"siegelzeichen von trollbane questgeber","wer vergibt siegelzeichen von trollbane","wo beginnt siegelzeichen von trollbane"}},{q="Wo befindet sich Prinz Galen Trollbane?",a="Prinz Galen Trollbane wartet in einer Kapelle tief im Inneren von Stromgarde, in den von der Miliz gehaltenen Bezirken.",al={"prinz galen trollbane aufenthaltsort","wo ist galen trollbane","galen trollbane stromgarde"}},{q="Warum wird das Siegelzeichen von Trollbane benötigt?",a="Das Siegelzeichen von Trollbane ist das letzte Siegel, das Zengu benötigt, um das Grab von Thoras Trollbane zu öffnen. Thoras' Sohn, Prinz Galen, verwahrt es persönlich.",al={"zweck des siegelzeichens von trollbane","warum siegelzeichen von trollbane holen"}},{q="Was folgt, nachdem Ihr das Siegelzeichen von Trollbane erhalten habt?",a="Nachdem Ihr das Siegelzeichen von Trollbane erhalten habt, wird die Questreihe mit Trol'kalar fortgesetzt.",al={"nächste quest nach siegelzeichen von trollbane","was folgt auf siegelzeichen von trollbane"}}},fp="18,151,14.273.0,15.267.1,49.67.0,40.101.0,37.131.0,50.77.0"}
P.entries["quest:6441"] = {n="Satyrhörner",s="Am Splitterholzposten bieten Satyrhörner Pixel eine Handelschance in Ratschet. Der reisende Goblin sucht sie für die Reise nach Süden in die Hafenstadt.",h="Am Splitterholzposten bieten Satyrhörner Pixel eine Handelschance in Ratschet.",kw={"eschental","nachtflucht","pixel","ratschet","satyrhörner","satyrnaar","splitterholzposten","xavian"},ang={["class:Hunter"]="Dämonische Humanoide durch verderbte Waldruinen wie Satyrnaar und Nachtflucht zu verfolgen, stellt Eure Wildnisfertigkeiten auf eine gefährliche Probe.",["class:Warlock"]="Satyrn tragen mächtige Teufelsmagie in sich, und ihre Überreste interessieren jene, die dämonische Macht erforschen.",["faction:Horde"]="Wer die Satyrenklaven im Herzen von Eschental aushebt, schwächt die dämonische Bedrohung für die empfindlichen Versorgungslinien des Splitterholzpostens."},sec={{t="Eine lukrative Gelegenheit",b="Am Splitterholzposten sieht Pixel während einer Reisepause eine Gelegenheit, Gewinn zu machen. Satyrhörner erzielen in Ratschet einen hohen Preis, und Pixel will sie für die Rückreise nach Süden in die Hafenstadt haben. Statt sich den verderbten Kreaturen zu stellen, heuert Pixel vorbeiziehende Abenteurer an, die sechzehn unversehrte Hörner beschaffen sollen."},{t="Schlupfwinkel der Verderbten",b="Dämonische Satyrn hausen in verstreuten, von Teufelsmagie verseuchten Ruinen in ganz Eschental. Sie sind Überbleibsel eines Verrats während der uralten Zerschlagung. Ihr könnt ihre Stützpunkte in Nachtflucht, im befestigten Lager Satyrnaar und in den schattigen Hainen von Xavian durchsuchen. Pixel sucht Hörner aus jedem dieser Orte für die Handelskais von Ratschet."}},faq={{q="Wer ist Pixel?",a="Pixel ist ein reisender Goblin, der am Splitterholzposten in Eschental haltmacht, bevor er nach Süden zum neutralen Hafen Ratschet aufbricht.",al={"wer ist der questgeber","pixels geschichte","goblin am splitterholzposten"}},{q="Warum will Ratschet Satyrhörner?",a="Pixel sagt, dass Satyrhörner in Ratschet einen hohen Preis erzielen. Händler, Alchemisten und Sammler exotischer Waren zahlen gut für unverarbeitete dämonische Reagenzien und Kuriositäten aus den nördlichen Wäldern.",al={"warum satyrhörner","wofür werden hörner verwendet","ratschet satyrhörner"}},{q="Wo findet man Satyrhörner in Eschental?",a="Satyrn hausen an verderbten Orten in ganz Eschental, darunter Nachtflucht nordwestlich des Splitterholzpostens, Satyrnaar unweit der Hauptstraße nach Azshara und Xavian im nordöstlichen Eschental.",al={"satyrstandorte","wo findet man satyrn","nachtflucht xavian satyrnaar"}},{q="Was sind Satyrn?",a="Satyrn sind uralte Nachtelfen, die vor Jahrtausenden von der Brennenden Legion verderbt wurden. Heute tragen sie gespaltene Hufe und Hörner, dienen dunklen Mächten und verderben den Wald um sich herum.",al={"was ist ein satyr","geschichte der satyrn","sind satyrn dämonen"}},{q="Warum wird dieser Auftrag am Splitterholzposten vergeben?",a="Der Splitterholzposten ist die wichtigste Festung der Horde im Herzen von Eschental. Pixel rastet dort zwischen Handelsreisen und heuert Krieger der Horde aus der Umgebung an, die sich bereits den Gefahren des Waldes stellen.",al={"splitterholzposten satyrquest","warum nur horde"}},{q="Ist Pixel der Horde verpflichtet?",a="Nein. Pixel ist ein unabhängiger Goblinhändler, der nach Gewinn strebt. Wie viele Goblins rund um Ratschet handelt Pixel mit jedem, der wertvolle Waren liefern kann, ungeachtet der Fraktionspolitik.",al={"gehört pixel zur horde","pixels fraktion"}}},fx={["22d423d7"]={q="Warum möchte Pixel Satyrhörner?",a="Pixel ist eine unternehmungslustige Reisende auf dem Weg nach Ratschet mit einem Auge für Handel. Da sie weiß, dass Satyrhörner im Goblinhafen einen hübschen Preis erzielen, zielt sie darauf ab, einen netten Gewinn zu machen, bevor sie ihre Reise beendet. Anstatt sich den gefährlichen Bestien selbst zu stellen, ist sie bereit, fähige Abenteurer dafür zu bezahlen, die Drecksarbeit zu erledigen, damit sie die Waren ausliefern kann.",al={"warum möchte pixel das","pixel motiv satyrhörner","warum satyrhörner sammeln"}},fc903cbf={q="Warum jagt Pixel die Satyrn nicht selbst?",a="Pixel gibt bereitwillig zu, dass sie den bösartigen, magiebegabten Satyrn, die in den Ruinen im Eschental lauern, nicht gewachsen ist. Da ihr die Kampfkraft fehlt, um eine Begegnung an Orten wie Satyrnaar oder Xavian zu überleben, verlässt sie sich voll und ganz auf erfahrene Mercenaries, die durch den Splitterholzposten ziehen, um die Ware für sie zu sichern.",al={"warum braucht pixel mich","warum kann pixel die hörner nicht bekommen","warum einen abenteurer anheuern"}}},fp="11,147,23.301.0,23.319.0,13.120.0,34.177.0,44.184.0,16.175.0,50.176.0,44.188.0"}
P.entries["quest:6442"] = {n="Die Naga am Zoramstrand",s="An Eschentals Küste bedrohen Naga den Halt der Horde am Zoramstrand. Vom Außenposten von Zoram'gar aus will Marukai die Wrathtail aus den versunkenen Ruinen des uralten Zoram vertreiben.",h="An Eschentals Küste bedrohen Naga den Halt der Horde am Zoramstrand.",kw={"eschental","marukai","naga","wrathtail","köpfe der wrathtail","der zoramstrand","außenposten von zoram'gar"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Außenposten von Zoram'gar zu halten und in Eschental Fuß zu fassen. Die Naga zu vertreiben ist eine Frage des militärischen Überlebens.",["race:Orc"]="Als Orc wisst Ihr den Wert von Marukais direktem, kraftvollem Vorgehen bei der Verteidigung eines Grenzgebiets zu schätzen."},sec={{t="Ein unsicherer Brückenkopf",b="Der Halt der Horde am Zoramstrand ist zerbrechlich. Der Außenposten liegt inmitten feindlichen Nachtelfengebiets und erbitterter Waldkämpfe, doch seine Küste bietet der Horde einen Zugang zum Meer. Nun sind aggressive Naga an Land gekrochen. Sie könnten diesen Weg abschneiden und die kleine Garnison überrennen, bevor ihre Verteidigungsanlagen bereit sind."},{t="Echos des untergegangenen Zoram",b="Unter den Sandbänken des Zoramstrands liegen die zerschmetterten Überreste von Zoram, einer uralten Elfenstadt, die vor Jahrtausenden von der Großen Zerschlagung verschlungen wurde. Marukai und die Verteidiger des Außenpostens wissen nicht, warum die Wrathtail gerade jetzt aus den tiefen Gräben gekommen sind. Ihr plötzliches Interesse an den versunkenen Ruinen bedroht jeden, der über ihnen wandelt."},{t="Der Preis des Überlebens",b="Marukai sieht darin einen schlichten Überlebenskampf. Wenn Schwerter und Dreizacke gezogen sind, zählt Vernunft wenig. Sie verlangt zwanzig abgetrennte Köpfe der Wrathtail. Sie hofft, dass Gewalt die Naga in die Tiefe zurücktreibt und das Ufer für die Horde sichert."}},faq={{q="Wer vergibt die Quest Die Naga am Zoramstrand?",a="Marukai, eine Dunkelspeertrollin, vergibt die Aufgabe am Außenposten von Zoram'gar, einer Stellung der Horde am Zoramstrand im nordwestlichen Eschental.",al={"questgeber","wer vergibt die quest","marukais standort"}},{q="Welche Geschichte steckt hinter dem Zoramstrand?",a="Der Zoramstrand erstreckt sich entlang der letzten Ruhestätte der uralten Stadt Zoram. Die Große Zerschlagung zerstörte sie vor langer Zeit und ließ sie im großen Meer versinken. Ihre Ruinen liegen heute teilweise unter Wasser an Eschentals Küste.",al={"was ist zoram","geschichte von zoram","versunkene stadt"}},{q="Warum greifen die Naga das Ufer an?",a="Die Garnison der Horde weiß nicht, warum die Wrathtail gekommen sind. Die Naga sind aus den Tiefen des Ozeans emporgestürmt, um die versunkenen Ruinen zu beanspruchen und die Landbewohner zu vertreiben.",al={"warum sind naga hier","beweggrund der wrathtail","ziel der naga"}},{q="Welche Feinde muss ich für diese Quest bekämpfen?",a="Ihr tretet Mitgliedern des Wrathtail-Stammes entgegen, die über die Strände und durch die Brandung des Zoramstrands kriechen. Marukai bittet Euch, ihr zwanzig ihrer abgetrennten Köpfe zu bringen.",al={"welche naga","köpfe der wrathtail","gesuchte feinde"}},{q="Welche Quest folgt auf Die Naga am Zoramstrand?",a="Marukai bietet nach dieser Aufgabe keine weitere an. Sie dankt Euch und bittet um mehr Euresgleichen, um den Zoramstrand zu halten.",al={"nächste quest","folgequest","marukais nächste aufgabe"}},{q="Warum interessiert sich die Horde für diesen abgelegenen Strand?",a="Eschental ist zwischen der Horde und den Nachtelfen heftig umkämpft. Ein sicherer Brückenkopf am Zoramstrand bietet der Horde Zugang zum Meer und Versorgungswege jenseits der dichten Wälder im Landesinneren.",al={"warum ist die horde hier","zweck des außenpostens von zoram'gar"}}},fx={b1ee6e7c={q="Warum möchte Marukai, dass die Naga getötet werden?",a="Marukai sieht die Naga als eine aktive Gefahr für die Präsenz der Horde am Strand. Die Horde hat erbittert gekämpft, um diesen Außenposten entlang der Küste vom Eschental zu beanspruchen und zu sichern. Was auch immer für ein mysteriöses Motiv die schlangenartigen Invasoren an Land bringt, ihre wachsende Zahl droht das Lager zu überwältigen, wenn sie nicht dezimiert und zurück in die Tiefen des Ozeans getrieben werden.",al={"warum möchte marukai das","marukai motiv","warum naga zoramstrand töten"}},["7626cdcb"]={q="Wer sind die Wrathtail-Naga und warum sind sie am The Zoramstrand?",a="Der Naga-Stamm der Wrathtail ist aus dem Meer gekrochen, um die Ruinen von Zoram zu besetzen, eine uralte Kaldorei-Stadt, die während des Furors zerstört und überflutet wurde. Während ihre tieferen Absichten den Verteidigern der Horde verborgen bleiben, machen ihre schleichende Präsenz und ihre feindseligen Einfälle entlang der Küste sie zu einer unmittelbaren Bedrohung für jeden, der sich in die Nähe des Strandes wagt.",al={"wer sind die wrathtail","wrathtail naga lore","warum sind wrathtail hier"}}},fp="24,178,21.310.0,22.333.0,21.242.0,45.121.0,44.207.0,37.160.0,48.151.0,44.119.0,48.177.0"}
P.entries["quest:645"] = {n="Trol'kalar",s="In Stromgarde schickt Zengu Euch los, um Trol'kalar zu bergen, da die vier Siegel nun vereint sind.",h="In Stromgarde schickt Zengu Euch los, um Trol'kalar zu bergen, da die vier Siegel nun vereint sind.",kw={"gruft","sanktum","siegelzeichen von ignaeus","stromgarde","trol'kalar","trollbane","zengu"},sec={{t="Ein Siegel aus vieren",b="Zengu hat gesehen, wie sich die vier Siegel zum Siegelzeichen von Ignaeus vereint haben. Er glaubt, dass ihre Vereinigung die Schutzzauber auf Trollbanes Grab brechen kann. Das Grab liegt im Sanktum hinter der Kapelle von Stromgarde, und Zengu schickt Euch dorthin, um Trol'kalar zu bergen. Ein eingezäunter Pfad rechts vom Kapelleneingang führt hinab zur Gruft."},{t="Das Grab öffnet sich",b="Gravuren auf Trollbanes Grab stimmen mit den leuchtenden Linien des Siegels überein. Als sie aufeinandertreffen, verschlingt ein Lichtblitz das Siegel. Trol'kalar, das legendäre Schwert, wird aus den steinernen Händen befreit, die es hielten."}},faq={{q="Wer schickt Euch los, um Trol'kalar zu bergen?",a="Zengu schickt Euch los, um Trol'kalar zu bergen, nachdem sich die vier Siegel zum Siegelzeichen von Ignaeus vereint haben.",al={"wer vergibt diese quest","questgeber","zengu"}},{q="Wo befindet sich Trollbanes Grab?",a="Trollbanes sterbliche Überreste liegen im Sanktum hinter der Kapelle von Stromgarde. Ein eingezäunter Pfad rechts vom Kapelleneingang führt hinab zur Gruft.",al={"wo ist das grab","lage des grabes","lage der gruft"}},{q="Was geschieht mit den vier Siegeln?",a="Die vier Siegel vereinen sich zum Siegelzeichen von Ignaeus. Zengu glaubt, dass es die Schutzzauber auf Trollbanes Grab brechen kann.",al={"was geschah mit den siegeln","siegelzeichen von ignaeus"}},{q="Was ist der vorherige Schritt in dieser Questreihe?",a="Sigil of Trollbane, das letzte der vier Siegel, geht diesem Schritt voraus.",al={"vorherige quest","vorangehende quest","sigil of trollbane"}}},fp="10,89,19.309.0,14.196.1,37.91.0,34.139.0,32.108.0,40.67.0"}
P.entries["quest:646"] = {n="Trol'kalar",s="Bei Trollbane's Tomb gleitet Trol'kalar aus seiner Steinscheide, während das Licht verblasst. Ihr bringt das Schwert zu Zengu in Hammerfall.",h="Bei Trollbane's Tomb gleitet Trol'kalar aus seiner Steinscheide, während das Licht verblasst.",kw={"arathi","hammerfall","nimboya","trol'kalar","trollbane","zengu","zul'gurub"},sec={{t="Ein befreites Schwert",b="Bei Trollbane's Tomb findet Ihr Trol'kalar aus seiner Steinscheide befreit vor. Ihr bringt das Schwert in seiner Scheide zu Zengu in Hammerfall im Arathihochland."},{t="Was Zengu sagt",b="Zengu sagt, die Streitkräfte von Strom und Arathor hätten den Trollen seit Generationen nachgestellt. Nun hält sein Volk deren größte Waffe in Händen, und der langsame Vormarsch in die feuchten Wälder von Zul'Gurub wird kein Kampf mehr sein. Die Dunkelspeertrolle stehen in Eurer Schuld, sagt er. Er wird das Schwert zu Nimboya in Grom'gol bringen."}},faq={{q="Wohin muss Trol'kalar gebracht werden?",a="Bringt das Schwert, noch in seiner Steinscheide, zu Zengu in Hammerfall im Arathihochland.",al={"wohin trolkalar bringen","trol'kalar abliefern","trolkalar abgeben"}},{q="Wo finde ich das Schwert?",a="Findet das Schwert bei Trollbane's Tomb, wo das verblassende Licht es aus seiner Steinscheide befreit hat.",al={"wo ist trol'kalar","trolkalar fundort"}},{q="Was kam vor diesem Schritt?",a="Dieser Schritt folgt auf den früheren Trol'kalar-Schritt und ist der letzte in der langen Reihe.",al={"trol'kalar vorheriger schritt","trolkalar questreihe"}}},fp="10,126,16.144.0,15.298.1,33.92.0,26.94.0,27.80.0"}
P.entries["quest:6461"] = {n="Blutfresser",s="Blutfresser beginnt in Malaka'jin damit, dass geschlachtetes Wild Tiefmoosspinnen zu den Lagern der Trolle lockt. Xen'Zilla bittet die Horde, die Raubtiere von der Siedlung zurückzudrängen.",h="Blutfresser beginnt in Malaka'jin damit, dass geschlachtetes Wild Tiefmoosspinnen zu den Lagern der Trolle...",kw={"blutfresser","tiefmooskriecher","tiefmoosgiftspucker","malaka'jin","sishircanyon","spinnen","steinkrallengebirge","xen'zilla"},ang={["class:Hunter"]="Als Jäger seid Ihr ein geübter Fährtenleser, für den es in den Felsen naheliegt, gefährliche Raubtiere aufzuspüren, die verbündete Siedlungen bei der Jagd übertreffen und bedrängen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Malaka'jin zu schützen. Das Dorf sichert den Zugangsweg der Horde vom nördlichen Brachland ins Steinkrallengebirge und schützt den gesamten südlichen Pass.",["race:Troll"]="Als Troll seid Ihr den Jägern von Malaka'jin durch Eure Herkunft verbunden. Sie streben danach, sich in Kalimdors zerklüftetem Hochland ein selbstversorgendes Gebiet zu schaffen, ohne der Wildnis zu erliegen."},sec={{t="Ungebetene Gäste zum Abendessen",b="Die Trolle gründeten Malaka'jin als Grenzaußenposten im südöstlichen Steinkrallengebirge, wo sie jagen konnten. Die schroffen Hänge bieten reichlich Wild, doch sein Fleisch lockt nachtaktive Raubtiere ins Lager. Tiefmoosspinnen sind aggressive Spinnentiere, die in den Felsen und Schluchten im Norden heimisch sind. Im Schutz der Dunkelheit schleichen sie sich ein, um die Vorräte der Trolle zu plündern oder die Jäger selbst zu jagen."},{t="Die Felsen säubern",b="Xen'Zilla bittet Euch, die Raubtiere nach Norden in die Gebirgspässe zu verfolgen. Das wird helfen, Malaka'jin zu schützen und seine Vorräte zu sichern. Tiefmooskriecher und Tiefmoosgiftspucker sammeln sich am dichtesten zwischen den felsigen Schluchten und Netzen des Sishircanyons. Lichtet ihre Reihen, und die Brut wird sich von der Siedlung zurückziehen. Dann können die Jäger ruhen, ohne einen Hinterhalt aus den Schatten fürchten zu müssen."}},faq={{q="Wer vergibt die Quest Blutfresser?",a="Xen'Zilla, ein Dunkelspeertroll in Malaka'jin im südöstlichen Steinkrallengebirge, bietet durchreisenden Streitern der Horde den Jagdauftrag an.",al={"wer vergibt blutfresser","blutfresser questgeber","xen'zilla quest"}},{q="Warum greifen die Spinnen Malaka'jin an?",a="Der Geruch frisch erlegter Beute und trocknenden Fleisches lockt Tiefmoosspinnen nachts aus den Gebirgspässen herab. Die Trolle von Malaka'jin jagen das heimische Wild, und die Spinnen kommen, um Vorräte zu stehlen und die Dorfbewohner zu jagen.",al={"warum greifen spinnen an","spinnenangriffe malakajin","warum dringen spinnen ein"}},{q="Wo befinden sich die Tiefmoosspinnen?",a="Tiefmooskriecher und Tiefmoosgiftspucker durchstreifen die mittleren Pässe und Felsen nördlich von Malaka'jin. Besonders dicht sammeln sie sich in der von Netzen durchzogenen Schlucht des Sishircanyons.",al={"wo sind tiefmoosspinnen","tiefmooskriecher fundort","tiefmoosgiftspucker fundort"}},{q="Was ist Malaka'jin?",a="Malaka'jin ist ein Lager der Dunkelspeertrolle am südlichen Zugang zum Steinkrallengebirge, nahe der Grenze zum Brachland. Es dient als Jagdstützpunkt und Grenzaußenposten der Horde.",al={"was ist malaka'jin","malakajin geschichte","trolldorf steinkrallengebirge"}},{q="Geht mit diesen Spinnen eine größere Bedrohung einher?",a="Eine gewaltige, tödliche Spinnenmatriarchin lebt tief im Sishircanyon zwischen den Netzen. Ein Warnschild vor dem Canyon macht Reisende auf die Gefahr aufmerksam und fordert Gruppen auf, sie zu erlegen.",al={"große spinne steinkrallengebirge","sishircanyon elitespinne","spinnenmatriarchin steinkrallengebirge"}},{q="Was geschieht, nachdem die Spinnen dezimiert wurden?",a="Die Dezimierung der Tiefmooskriecher und Tiefmoosgiftspucker verschafft Malaka'jin eine Atempause. Die Trolljäger können ihre Fleischvorräte sichern und nachts durch ihre Lager gehen, ohne ständig in einen Hinterhalt zu geraten.",al={"blutfresser nachwirkungen","wird malakajin sicher"}}},fx={["5b921468"]={q="Was machen die Deepmoss-Spinnen im Steinkrallengebirge?",a="Die Deepmoss-Kriecher und Giftspeier sind einheimische Spinnentiere, die durch die Felsen und Schluchten des Steinkrallengebirges streifen. Obwohl sie schon immer in den Felsen heimisch waren, hat der Duft von frischem Wild, das von Trolljägern nach Malaka'jin gebracht wurde, sie näher an die Zivilisation gelockt. Jetzt ermutigt, pirschen diese aggressiven Raubtiere aktiv aus den felsigen Hügeln hervor, um die Dorflager unter dem Schutz der Dunkelheit zu überfallen.",al={"deepmoss-spinnen steinkrallengebirge","deepmoss-kriecher giftspeier","warum sind spinnen hier"}}},fp="13,179,22.391.0,18.377.0,35.138.0,41.210.0,39.164.0,19.173.0,48.179.0,42.169.0"}
P.entries["quest:6462"] = {n="Trollglücksbringer",s="Am Außenposten von Zoram'gar trauert Mitsuwa um Angehörige, die unterwegs getötet wurden, und sucht ihre gestohlenen heiligen Glücksbringer. Die Thistlefur-Furbolgs brachten die Talismane in ihre Höhle.",h="Am Außenposten von Zoram'gar trauert Mitsuwa um Angehörige, die unterwegs getötet wurden, und sucht ihre...",kw={"eschental","dunkelspeer","furbolg","mitsuwa","thistlefur hold","lager der distelfelle","trollglücksbringer","außenposten von zoram'gar"},ang={["faction:Horde"]="Als Mitglied der Horde drängt Ihr mit einem Vorstoß ins Gebiet der Thistlefur die Bedrohungen des Waldes zurück, die in Eschental Versorgungswege und Reisende der Horde überfallen.",["race:Troll"]="Als Troll ist es Eure spirituelle Pflicht, die Glücksbringer zurückzuholen. Diese heiligen Gegenstände der Ahnen müssen aus den Händen der Furbolgs gerettet werden."},sec={{t="Eine überfallene Karawane",b="Ihr seid am Außenposten von Zoram'gar, einem abgelegenen Zufluchtsort der Horde an Eschentals Westküste. Waldpfade machen die Reise gefährlich. Eine Gruppe von Dunkelspeertrollen kam nie an, nachdem die Thistlefur-Furbolgs sie überfallen hatten. Mitsuwa akzeptiert, dass seine Angehörigen gestorben sind und ihm im Jenseits wiederbegegnen werden. Doch die Furbolgs haben ihre heiligen Glücksbringer gestohlen, und diese Beleidigung kann er nicht hinnehmen."},{t="Heilige Schmuckstücke",b="Trollglücksbringer und Talismane kennzeichnen die Identität, gewähren spirituellen Schutz und verbinden ihre Träger mit den Loa. Mitsuwa betrachtet eine Trollin ohne ihren Glücksbringer als hohl und wertlos, wie einen Orc ohne Kampfnarben. Die Thistlefur-Furbolgs brachten die gestohlenen Glücksbringer nach Thistlefur Hold, tief in den Höhlen hinter dem Lager der Distelfelle. Dort versteckten sie die Talismane in Truhen, fernab ihrer rechtmäßigen Besitzer."}},faq={{q="Wer vergibt diese Quest und wo ist die Person zu finden?",a="Mitsuwa, ein Dunkelspeertroll, wartet am Außenposten von Zoram'gar am Zoramstrand an Eschentals Nordwestküste.",al={"questgeber","wo ist mitsuwa","wer startet trollglücksbringer"}},{q="Warum sind die Trollglücksbringer für Mitsuwa so wichtig?",a="Trollglücksbringer haben eine tiefe spirituelle und kulturelle Bedeutung. Für Mitsuwa ist eine Trollin ohne ihren Glücksbringer wie ein Orc ohne Kampfnarben, und diese Relikte im Besitz der Furbolgs beleidigen seine getöteten Angehörigen.",al={"bedeutung der glücksbringer","warum sind trollglücksbringer wichtig"}},{q="Wo befinden sich die Trollglücksbringer?",a="Die Glücksbringer liegen in Truhen in Thistlefur Hold, einem tiefen Höhlenkomplex am Nordrand des Lagers der Distelfelle, nördlich von Astranaar.",al={"fundort der glücksbringer","wo sind die truhen","glücksbringer finden"}},{q="Wer hat die Glücksbringer gestohlen?",a="Die Thistlefur-Furbolgs haben die Glücksbringer gestohlen. Sie überfielen und töteten Mitsuwas Angehörige auf dem Weg zum Außenposten von Zoram'gar und brachten die Glücksbringer dann in ihre Höhlen.",al={"wer nahm die glücksbringer","verantwortliche für den hinterhalt"}},{q="Was geschah mit den Trollen, die die Glücksbringer ursprünglich trugen?",a="Die Thistlefur-Furbolgs töteten die Trolle entlang des Pfades. Mitsuwa trauert um sie und glaubt an ein Wiedersehen im Jenseits, während er versucht, ihre heiligen Relikte zurückzuerlangen.",al={"schicksal der karawane","getötete trolle","mitsuwas angehörige"}},{q="Ist diese Quest für die Allianz verfügbar?",a="Nein. Mitsuwa bietet sie der Horde am Außenposten von Zoram'gar an.",al={"allianz trollglücksbringer","kann die allianz die quest machen"}}},fx={["3db0517e"]={q="Was ist der Trollglücksbringer?",a="Diese Glücksbringer sind tief heilige Relikte, die von den Dunkelspeeren getragen werden. Für ihre Kultur repräsentiert ein Glücksbringer Ehre, Identität und spirituelle Zugehörigkeit – wie Mitsuwa es ausdrückt: Ein Troll ohne ihren Glücksbringer ist so hohl und wertlos wie ein Orc ohne Narben von der Schlacht. Obwohl ihre gefallenen Besitzer ihre Verwandten im Jenseits wiedersehen werden, ist es eine unerträgliche Schande für ihr Andenken, diese verehrten Zeichen beschmutzt in den Händen wilder Bestien zu lassen.",al={"trollglücksbringer lore","was macht trollglücksbringer","was sind trollglücksbringer"}}},fp="11,155,19.358.0,15.388.0,48.112.0,49.198.0,35.134.0,21.159.0,62.173.0,40.58.0"}
P.entries["quest:647"] = {n="MacKreels Fusel",s="Dunst MacKreels Fusel muss vom zerstörten Thandol-Übergang nach Süderstade gebracht werden. Er hat auf Wache zu viel getrunken und hat nun kaum Zeit, Braumeister Bilger eine frische Ladung zu liefern und seine Schulden zu begleichen.",h="Dunst MacKreels Fusel muss vom zerstörten Thandol-Übergang nach Süderstade gebracht werden.",kw={"bilger","dunst","langzopf","mackreel","menethil","fusel","süderstade"},ang={["faction:Alliance"]="Als Reisender der Allianz nehmt Ihr den Landweg, der den Thandol-Übergang mit dem von der Allianz gehaltenen Süderstade in Hillsbrad verbindet.",["race:Dwarf"]="Als Zwerg kennt Ihr das Elend eines schlimmen Katers, verschärft durch unbezahlte Schulden für Gebräu bei einem Angehörigen Eures Volkes."},sec={{t="Der Kater einer Wache",b="Auf dem zertrümmerten Thandol-Übergang hält Dunst MacKreel in Nässe, Kälte und Langeweile Wache. Er trinkt seinen selbst gebrannten Fusel, um die feuchte Kälte zu ertragen. Das Gebräu schlägt so heftig zu, dass er seine Nachwirkungen mit Belagerungsmaschinen vergleicht, die über seinen Schädel donnern. Ein Schluck zu viel lässt ihn seine Schicht verschlafen. Langzopf der Grimmige befehligt die Zwerge, die den Übergang verteidigen, und Dunst kann sich keinen weiteren Disziplinverstoß leisten."},{t="Ein Wettlauf gegen die Zeit",b="Dunst hat bei Braumeister Bilger in Süderstade seit Langem Schulden. Er versprach eine Ladung seines eigenen Gebräus, um die Rechnung zu begleichen, doch wegen seines Katers und seiner Wachpflichten bleiben ihm nur noch wenige Minuten. Ihr eilt mit dem Krug durch das Arathihochland, auf einem Greifen und zu flinkem Fuß. Erreicht Süderstade, bevor Bilger beschließt, dass Dunst wieder einmal seine Zeche geprellt hat."}},faq={{q="Wer ist Dunst MacKreel?",a="Dunst MacKreel ist ein Zwerg auf dem zerstörten Teil des Thandol-Übergangs, der von der Seite des Arathihochlands aus erreichbar ist. Er brennt äußerst starken Fusel und trinkt im Dienst oft zu viel.",al={"dunst mackreel","wer ist dunst","questgeber mackreel"}},{q="Warum ist diese Lieferung so dringend?",a="Dunst hat sich während seiner Wache bewusstlos getrunken und dadurch viel Zeit verloren. Ihm bleibt kaum eine Viertelstunde, um den Fusel vom Thandol-Übergang nach Süderstade zu bringen und seine überfällige Zeche bei Braumeister Bilger zu begleichen.",al={"warum gibt es ein zeitlimit","warum fünfzehn minuten","mackreel fusel zeitlimit"}},{q="Wer ist Braumeister Bilger?",a="Braumeister Bilger ist ein zwergischer Meisterbrauer in der Küstensiedlung Süderstade im Vorgebirge des Hügellands. Er schätzt starken Alkohol und hat eine noch offene geschäftliche Vereinbarung mit Dunst MacKreel.",al={"braumeister bilger","wer ist bilger","bilger süderstade"}},{q="Wie bringt man den Fusel rechtzeitig nach Süderstade?",a="Vom Übergang fährt kein Boot nach Süderstade. Wenn Ihr den Flugpunkt der Zuflucht kennt, nehmt einen Greifen von der Zuflucht nach Süderstade und sucht dort Braumeister Bilger, bevor die Zeit abläuft.",al={"wie fusel abliefern","schnellster weg süderstade mackreel","fusel lieferroute"}},{q="Wer ist Langzopf?",a="Langzopf der Grimmige ist der zwergische Kommandant vor Dun Modr im Sumpfland. Er führt die Verteidiger des Thandol-Übergangs an, und Dunst fürchtet, dass Langzopf entdeckt, dass er sich auf Wache bewusstlos getrunken hat.",al={"hauptmann langzopf","langzopf menethil"}}},fx={d39890fd={q="Warum kann Dunst MacKreel den Mondschein nicht selbst ausliefern?",a="Dunst MacKreel hat sich am Vorabend viel zu sehr seinem eigenen Mondschein hingegeben und ist während seiner Wache bewusstlos geworden. Mit pochendem Kopf, einem offiziellen Wachdienst, für den er sich bei Langzopf dem Grimmigen verantworten muss, und einer Frist, die bald abläuft, um seine Schulden bei Braumeister Bilger zu begleichen, ist er nicht in der Lage, allein nach Süderstade aufzubrechen.",al={"warum ich für mackreel","warum mondschein ausliefern","warum ich für dunst mondschein"}}},fp="20,211,18.422.0,24.368.0,22.183.0,31.217.0,26.206.0,53.196.0,17.208.0"}
P.entries["quest:648"] = {n="Rettet OOX-17/TN!",s="Am Dampfdruckpier braucht OOX-17/TN Zeit und freies Gelände für den Start. Oglethorpes Stimme dringt aus dem beschädigten Roboter und bittet Euch, ihn sicher dorthin zu geleiten und anschließend Oglethorpe in Beutebucht aufzusuchen.",h="Am Dampfdruckpier braucht OOX-17/TN Zeit und freies Gelände für den Start.",kw={"beutebucht","peilroboter","mechanisches huhn","oglethorpe obnoticus","oox-17/tn","dampfdruckpier","tanaris"},sec={{t="Geleit zum Pier",b="Oglethorpes Stimme knistert erneut aus OOX-17/TN. Der Roboter hat eine eingebaute Tarnung, doch Oglethorpe braucht Zeit, um sie wieder einsatzbereit zu machen. Er braucht einen offenen, sicheren Ort, um seinen langwierigen Start zu beginnen. Oglethorpe hat den Dampfdruckpier gewählt, und die Reise dorthin gibt ihm Zeit, die Tarnung wiederherzustellen. Ihr werdet gebeten, den Roboter sicher zu geleiten."},{t="Bericht in Beutebucht",b="Sobald OOX-17/TN den Dampfdruckpier erreicht, sucht Oglethorpe Obnoticus in Beutebucht auf. Er ist ein Meistererfinder."},{t="Ein dankbarer Erfinder",b="Oglethorpe begrüßt Euch als die Person, die OOX-17/TN gerettet hat. Die Peilroboter-Serie braucht noch weitere Arbeit, doch die Rückkehr dieses Roboters hat unzählige Stunden des Wiederaufbaus und viele Goldstücke an Neubindungskosten gespart. Oglethorpe sagt, die Roboter und ihr Erfinder stehen in Eurer Schuld."}},faq={{q="Wohin muss der Roboter geleitet werden?",a="Geleitet OOX-17/TN zum Dampfdruckpier, wo er seinen langwierigen Start sicher beginnen kann.",al={"wohin geht oox-17","oox-17 geleitroute","ziel des roboters"}},{q="Wer spricht durch den Roboter?",a="Oglethorpe Obnoticus, ein Gnom und Meistererfinder, spricht durch seinen Peilroboter. Ihr könnt ihn in Beutebucht finden.",al={"wer hat oox-17 gebaut","oox-17 erschaffer","wer spricht durch den roboter"}},{q="Warum muss der Roboter an einen anderen Ort gebracht werden?",a="Der Roboter braucht einen offenen, sicheren Ort, um seinen langwierigen Start zu beginnen. Auch seine eingebaute Tarnung braucht Zeit, bis sie wieder funktioniert.",al={"warum oox-17 woanders hinbringen","warum dampfdruckpier"}},{q="Wo erstattet Ihr nach dem Geleit Bericht?",a="Erstattet Oglethorpe Obnoticus in Beutebucht Bericht.",al={"wo ist oglethorpe obnoticus","bei wem abgeben","oox-17 abgabeort"}}},fp="17,190,21.343.0,19.106.0,19.271.1,41.86.0,34.114.0,36.119.0,37.44.0"}
P.entries["quest:6481"] = {n="Der Irdene erhebt sich",s="In der Steinschlagklamm findet Mor'rogal Goggeroc schlafend in einem Resonitfass. Der Taurenschamane fürchtet, der uralte Irdene könnte ganz Kalimdor bedrohen, und entsendet einen Champion, um das Fass zu zerschlagen und Goggeroc zu töten, bevor seine Kräfte zurückkehren.",h="In der Steinschlagklamm findet Mor'rogal Goggeroc schlafend in einem Resonitfass.",kw={"steinschlagklamm","irdene","der irdene erhebt sich","goggeroc","mor'rogal","resonitfass","schamane","steinkrallengebirge"},ang={["class:Shaman"]="Als Schamane seht Ihr, wie Mor'rogal mit schamanistischer Macht Resonitkristalle verändert und das elementare Gleichgewicht stört, das Goggeroc im Fass bewahrt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr durch den Sieg über Goggeroc, die Präsenz Eurer Fraktion in den umkämpften Felsen des Steinkrallengebirges zu sichern. Ihr erwerbt Euch den bleibenden Respekt der Anführer von Donnerfels.",["race:Tauren"]="Als Tauren kennt Ihr das Steinkrallengebirge als angestammtes Jagdgebiet der Stämme von Donnerfels. Der Sieg über ein uraltes zerstörerisches Wesen in seinen Gipfeln schützt das Land vor dem Untergang."},sec={{t="Ein Schlummer im Stein",b="Späher, die in der Steinschlagklamm nach Ungeziefer suchten, fanden ein seltsames Relikt unter den Kobolden. Ein Resonitfass barg eine überirdische Kraft. Mor'rogal, ein Taurenschamane im Steinkrallengebirge, wusste, dass es zugleich Gefängnis und Zufluchtsort für Goggeroc war, einen schlummernden Irdenen. Diese uralten Wesen aus Stein können sterbliche Krieger übertreffen, und Goggerocs Freiheit könnte die gesamte Region gefährden."},{t="Der Resonitkristall",b="Mor'rogal fürchtet, was Goggeroc anrichten könnte, wenn er mit voller Kraft erwacht. Er verändert die Mischung der Resonitkristalle, die ihm gebracht werden, und erfüllt sie mit schamanistischer Magie. Der verzauberte Kristall kann das Resonitfass zerschlagen und Goggeroc wecken, solange er noch schwach ist. Krieger der Horde müssen das desorientierte titanengeschmiedete Wesen niederstrecken, bevor es den jahrhundertelangen Schlummer abschüttelt."}},faq={{q="Wer ist Mor'rogal?",a="Mor'rogal ist ein Taurenschamane, der im Steinkrallengebirge stationiert ist. Er untersucht Störungen in der Region und nutzt Elementarmagie, um uralte Artefakte und Bedrohungen einzuschätzen, die das örtliche Ungeziefer freilegt.",al={"mor rogal","wer ist der questgeber","orcschamane morrogal"}},{q="Was ist ein Irdene?",a="Irdene sind uralte Wesen, aus lebendem Stein geschmiedet und von den Titans beim Anbeginn der Welt zurückgelassen. An die Erde gebunden, besitzen sie gewaltige Kräfte. Seit Jahrtausenden schlafen sie, überall in Kalimdor und den Östlichen Königreichen vergraben.",al={"was ist ein irdene","geschichte der irdenen","wer sind die irdenen"}},{q="Warum will Mor'rogal Goggerocs Tod?",a="Mor'rogal fürchtet, Goggerocs Stärke könnte eine Katastrophe über das Steinkrallengebirge und ganz Kalimdor bringen. Er glaubt, das Land könne nur geschützt werden, indem Goggeroc vernichtet wird, solange der Schlummer ihn geschwächt hat.",al={"warum goggeroc töten","ist goggeroc böse","warum irdene töten"}},{q="Wo befindet sich Goggeroc?",a="Goggeroc liegt in einem Resonitfass tief in den Höhlen der Steinschlagklamm, im Südosten des Steinkrallengebirges. Boulderslide-Kobolde graben sich durch die Höhlen ringsum.",al={"wo ist das fass","goggerocs aufenthaltsort","resonitfass finden"}},{q="Wie erweckt Ihr Goggeroc?",a="Ihr erweckt Goggeroc, indem Ihr Mor'rogals Verzauberten Resonitkristall auf das Resonitfass in der Höhle anwendet. Seine Magie zerschlägt den Behälter und zwingt den schlafenden Irdenen ins Freie.",al={"wie goggeroc beschwören","verzauberten resonitkristall benutzen","fass öffnen"}},{q="Was geschieht nach Goggerocs Tod?",a="Wenn Ihr mit der Nachricht von Goggerocs Tod zu Mor'rogal zurückkehrt, weicht die Furcht des Schamanen. Er preist Euch als Helden, der ein großes Unheil abgewendet hat, was Euch Ehre und Ansehen unter den Tauren von Donnerfels einbringt.",al={"geschichte der questbelohnung","morrogals reaktion","der irdene erhebt sich abgeben"}}},fx={["7cc06600"]={q="Wer ist Goggeroc und warum ist er im Steinkrallengebirge?",a="Goggeroc ist ein uralter Earthen, ein Wesen aus lebendem Stein, das vor langer Zeit von den Titanen geschmiedet wurde. Eingeschlossen in einem Resonitfass tief in der Höhle der Steinschlagklamm, hat er im Schlummer unter dem Steinkrallengebirge geruht. Mor'rogal warnt, dass, sollte ein Earthen mit voller Kraft erwachen, seine unübertroffene Macht eine katastrophale Bedrohung für das Steinkrallengebirge und ganz Kalimdor darstellen würde. Das Zerschlagen des Fasses erwischt ihn, während er noch desorientiert und schwach von seinem langen Schlaf ist, was Euch die einzige Chance gibt, ihn zu bezwingen.",al={"wer ist goggeroc","goggeroc lore","was ist goggeroc"}},["9f2ce835"]={q="Warum muss Mor'rogal Euch Goggeroc besiegen lassen, anstatt sich ihm selbst zu stellen?",a="Mor'rogal nutzt seine schamanischen Kräfte im Sonnenfels, um die Resonitkristalle zu verändern, die Ihr gesammelt habt. Er schickt Euch mit dem verzauberten Kristall zurück in die Höhle, um Goggerocs Fass zu öffnen und zuzuschlagen, während der Earthen von seinem langen Schlummer geschwächt ist.",al={"warum kämpft mor'rogal nicht gegen goggeroc","warum ich","warum mich gegen goggeroc schicken"}}},fp="13,240,18.369.0,20.369.1,17.197.0,19.223.0,38.193.0,26.172.0,27.179.0,37.204.1"}
P.entries["quest:6482"] = {n="Freiheit für Ruul",s="Im nördlichen Eschental wartet Ruul tief in Thistlefur Hold in einem Käfig. Er braucht einen Verbündeten der Horde, der ihm hilft, sich durch die verdorbene Furbolghöhle in Sicherheit zu kämpfen.",h="Im nördlichen Eschental wartet Ruul tief in Thistlefur Hold in einem Käfig.",kw={"eschental","druide eskortieren","furbolg","splitterholzposten","thistlefur hold","yama snowhoof"},ang={["class:Druid"]="Als Druide kennt Ihr die Gefahr, wilde Lande in Tiergestalt zu durchqueren, wo verdorbene Einheimische Euch für Beute halten könnten.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr den gefährdeten Außenposten am Splitterholzposten mit jeder Seele, die aus den verdorbenen Höhlen des nördlichen Eschentals gerettet wird.",["race:Tauren"]="Als Tauren ehrt Ihr die Bande der Earthmother und der Horde, wenn Ihr einen Cenarion-Bruder rettet und die Sorgen seiner Angehörigen am Splitterholzposten lindert."},sec={{t="Ein Druide in Ketten",b="Ruul Schneehuf, ein Druide, sitzt in Thistlefur Hold fest. Als er in Bärengestalt die verdorbenen Wälder des nördlichen Eschentals erkundete, kam er der Höhle zu nahe. Die verdorbenen Furbolgs hatten die Weisheit ihrer Ahnen verloren und hielten ihn, von wilder Paranoia getrieben, für eine gewöhnliche Bestie. Sie sperrten ihn ein und ließen ihn hungern, statt ihn zu ehren, und zehrten seine Magie auf, bis er sich nicht mehr allein befreien konnte."},{t="Flucht aus der Höhle",b="Nachdem Hunger und Gefangenschaft Ruul geschwächt haben, kann er weder seine Gestalt wandeln noch sich allein durch die Furbolgsiedlung kämpfen. Ein Verbündeter der Horde befreit ihn und bahnt ihm einen Weg an feindseligen Thistlefurs vorbei. Als sie die Außenbezirke des Splitterholzpostens erreichen, nimmt Ruul kurz seine Taurengestalt an und dankt von Herzen. Dann kehrt er in die Wildnis zurück, um seine Erschöpfung auszuschlafen."}},faq={{q="Warum wurde Ruul Schneehuf von den Furbolgs eingesperrt?",a="Ruul erkundete den Wald in Bärengestalt, als die verdorbenen Thistlefur-Furbolgs ihn für ein wildes Tier statt für einen Druiden hielten. Sie sperrten ihn in einen Käfig und ließen ihn hungern, bis er zu schwach zur Flucht war.",al={"warum sitzt ruul fest","wie wurde ruul gefangen","warum eingesperrt"}},{q="Wer ist Yama Snowhoof?",a="Yama Snowhoof ist Ruuls Schwester und am Splitterholzposten im Eschental stationiert. Sie machte sich große Sorgen, als Ruul Tage zuvor im Wald verschwand und nicht zurückkehrte.",al={"ruuls schwester","yama splitterholzposten","wer ist yama"}},{q="Warum konnte Ruul nicht einfach seine Bärengestalt ablegen und fliehen?",a="Die Thistlefur-Furbolgs schwächten Ruul durch lange Gefangenschaft und gezieltes Aushungern. Ohne Nahrung und Kraft war seine natürliche Energie aufgezehrt, sodass er hilflos blieb, bis ihn jemand rettete.",al={"warum wandelte ruul seine gestalt nicht","druide bär falle"}},{q="Was geschieht, nachdem Ruul in Sicherheit ist?",a="Am Rand des Splitterholzpostens nimmt Ruul kurz seine natürliche Taurengestalt an, um seinen Dank auszudrücken. Dann kehrt er in seine Bärengestalt zurück und sucht sich einen ruhigen Ort, um zu schlafen und sich zu erholen.",al={"wohin geht ruul","ruuls ende"}},{q="Sind alle Furbolgs im Eschental so feindselig wie die Thistlefurs?",a="Nein. Viele Furbolgstämme haben ein edles Erbe und eine tiefe Verbundenheit zur Natur, doch die Thistlefurs im nördlichen Eschental wurden durch verderbende Einflüsse angriffslustig und unberechenbar.",al={"sind furbolgs böse","thistlefur verderbnis"}},{q="Wo findet die Rettung statt?",a="Ruul wird in Thistlefur Hold festgehalten, einer Furbolghöhle in den Hügeln nordwestlich des Splitterholzpostens und nördlich von Astranaar im Eschental.",al={"wo ist ruul","ruul schneehuf aufenthaltsort"}}},fx={cd4f3bf3={q="Warum muss Ruul Schneehuf Euch begleiten, anstatt alleine zu entkommen?",a="Ruul hat tagelang in einem Thistlefur-Käfig eingesperrt verbracht und Hunger und Gefangenschaft durch die korrumpierten Furbolgs erlitten. Seine körperliche Kraft hat ihn fast vollständig verlassen. Geschwächt, unterernährt und tief im feindseligen Thistlefur Hold gefangen, kann er sich nicht alleine an den umliegenden Stammesmitgliedern vorbeikämpfen und verlässt sich darauf, dass Ihr einen Weg in die Freiheit bahnt.",al={"warum braucht ruul hilfe","warum kann ruul nicht alleine entkommen","warum ich ruul schneehuf"}}},fp="15,164,17.394.0,19.363.1,48.194.0,21.171.1,56.196.0,39.186.1,59.197.0,33.131.0"}
P.entries["quest:65"] = {n="Die Bruderschaft der Defias",s="Von der Späherkuppe schickt Gryan Starkmantel Euch nach Osten nach Seenhain, wo ein Kontaktmann wissen könnte, wo sich die Bruderschaft der Defias versteckt.",h="Von der Späherkuppe schickt Gryan Starkmantel Euch nach Osten nach Seenhain, wo ein Kontaktmann wissen...",kw={"defias","gryan starkmantel","seenhain","rotkammgebirge","späherkuppe","westfall","wiley der schwarze"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass sich ein Verbrechersyndikat allein mit Soldatenhandwerk nicht aufdecken lässt. Stoutmantle wendet sich an jemanden, der sich mit Schatten und Gefälligkeiten auf der Straße auskennt: Wiley den Schwarzen.",["faction:Alliance"]="Als Reisender der Allianz zieht Ihr von Westfall ins Rotkammgebirge, wo die Randgebiete aufeinander angewiesen sind, während Sturmwind sie vernachlässigt."},sec={{t="Die Bedrohung im Staub",b="Die Volksmiliz kann nicht herausfinden, wer die Banditen lenkt. Gryan Starkmantel muss den inneren Kreis des Kartells und dessen Anführer entlarven, bevor die Diebe aufgehalten werden können."},{t="Ein auswärtiger Kontaktmann",b="Wiley der Schwarze wartet im Obergeschoss des Gasthauses von Seenhain. Stoutmantle vertraut darauf, dass die Unterweltkontakte des Schurken die Verstecke der Bruderschaft offenbaren. Ob Wiley eine Spur liefern kann, ist noch ungewiss."}},faq={{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel führt die Volksmiliz an, eine zusammengewürfelte Verteidigungstruppe mit Sitz auf der Späherkuppe in Westfall. Während Sturmwind die Grenzgebiete vernachlässigt, koordiniert er die Verteidigung der wenigen Bauern und Flüchtlinge, die noch dort sind.",al={"gryan starkmantel","wer vergibt diese quest","questgeber westfall"}},{q="Warum schickt Stoutmantle Euch nach Seenhain?",a="Die Volksmiliz hat keine Informanten in Westfalls Unterwelt. Gryan Starkmantel fordert einen alten Gefallen von Wiley dem Schwarzen ein, einem Schurken im Gasthaus von Seenhain, und hofft, dessen kriminelle Kontakte könnten den Anführer der Diebe enthüllen.",al={"warum seenhain","warum ins rotkammgebirge reisen","warum wiley"}},{q="Wer ist Wiley der Schwarze?",a="Wiley der Schwarze ist ein Schurke, der im zweiten Stock des Gasthauses von Seenhain im Rotkammgebirge wohnt. Er schuldet Gryan Starkmantel einen Gefallen und könnte Gerüchte aus der Unterwelt weitergeben und Kontakte zu Kriminellen vermitteln.",al={"wer ist wiley","wiley seenhain","wiley der schwarze"}},{q="Was ist die Bruderschaft der Defias?",a="In Westfall tragen die Diebe der Bruderschaft der Defias rote Halstücher und haben Bauernhöfe, Straßen und verlassene Minen besetzt. Sie vertreiben die Siedler und stellen Sturmwinds Autorität infrage.",al={"bruderschaft der defias","was sind die defias","banditen mit roten halstüchern"}},{q="Wo kann ich Wiley in Seenhain finden?",a="Wiley der Schwarze ist oben im zweiten Stock des Gasthauses von Seenhain, nahe der Brücke in der Stadt Seenhain im Rotkammgebirge.",al={"wo ist wiley","wiley finden","wileys aufenthaltsort"}},{q="Gibt es bei dieser Quest Kämpfe?",a="Nein. Ihr reist von der Späherkuppe in Westfall durch den Wald von Elwynn zum Gasthaus von Seenhain, um Wiley zu treffen.",al={"ist diese quest schwer","kämpfe bei der quest die bruderschaft der defias","feinde"}}},fx={e3561313={q="Warum benötigt Gryan Starkmantel einen Abenteurer anstelle seiner eigenen Volksmiliz?",a="Gryan Starkmantels Volksmiliz ist bereits bis zum Äußersten angespannt, nur um die Späherkuppe zu verteidigen und die wenigen verbliebenen Farmer in Westfall zu schützen. Sturmwind weigert sich, königliche Verstärkung zu schicken, wodurch die lokale Verteidigung verzweifelt unterbesetzt ist. Darüber hinaus benötigt Starkmantel speziell einen Außenseiter, der zu verdeckter Infiltration fähig ist, anstatt erkennbarer lokaler Milizkämpfer, die sofort von den Wachen der Defias entdeckt würden.",al={"warum ich","warum keine miliz schicken","warum braucht starkmantel einen abenteurer"}}},fp="22,127,22.168.0,22.188.0,25.219.0,43.215.0,23.194.0,31.179.0,36.130.0,35.102.0"}
P.entries["quest:6503"] = {n="Die Kundschafter des Eschentals",s="In Eschental schickt Kuray'bin die Horde gegen Nachtelfenspäher, die sich vom Außenposten der Silberschwingen fortschleichen. Sie sammeln Informationen über Lager und Verteidigungsanlagen der Horde, bevor sie Bericht erstatten können.",h="In Eschental schickt Kuray'bin die Horde gegen Nachtelfenspäher, die sich vom Außenposten der Silberschwingen...",kw={"allianz","eschental","die kundschafter des eschentals","horde","kuray'bin","nachtelfenspäher","außenposten der silberschwingen"},ang={["class:Hunter"]="Als Jäger nutzt Ihr Euren ausgeprägten Instinkt, Eure geschärften Sinne beim Spurenlesen und Eure Treffsicherheit, um verborgene Kundschafter tief im Wald aufzuspüren.",["class:Rogue"]="Als Schurke wendet Ihr die Verstohlenheit der Nachtelfen gegen sie selbst. Indem Ihr ihre Kundschafter ausschaltet, helft Ihr den Infiltratoren der Horde, die Schatten des Waldes zu beherrschen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr mit jedem niedergestreckten Nachtelfenspäher, örtliche Lager und Holzfällerbetriebe vor koordinierten Gegenangriffen der Allianz zu schützen."},sec={{t="Augen in den Baumkronen",b="Nachtelfenspäher vom Außenposten der Silberschwingen durchstreifen die Wälder östlich ihrer Basis und südlich nahegelegener Stellungen der Horde. Sie beobachten die Pfade und Höhenzüge, kartieren Befestigungen und verfolgen Truppenbewegungen.\n\nKuray'bin hat erfahren, dass diese Späher, die Kundschafter des Eschentals genannt, in die Wildnis geschlichen sind, um Informationen zu sammeln."},{t="Die Allianz blenden",b="Die Horde schlägt gegen feindliche Späher zu, bevor sie zum Außenposten der Silberschwingen zurückkehren können. Die Jagd auf die Kundschafter verhindert, dass ihre Befehlshaber von der Truppenstärke der Horde und den Verteidigungsanlagen ihrer Außenposten erfahren.\n\nOhne ihre vorgeschobenen Augen sind die Nachtelfen orientierungslos und weniger bereit, aggressive Vorstöße durch die umkämpften Wälder zu wagen."}},faq={{q="Wer vergibt die Quest „Die Kundschafter des Eschentals“?",a="Kuray'bin, der in Eschental stationierte Späherkoordinator der Horde, gibt den Befehl. Er verfolgt die Bewegungen der Nachtelfen im gesamten Wald und wirkt ihnen entgegen.",al={"questgeber","wer vergibt die quest","kuray'bin quest"}},{q="Wo befinden sich die Kundschafter des Eschentals?",a="Die Kundschafter patrouillieren in den Wäldern östlich des Außenpostens der Silberschwingen und südlich von Kuray'bins Lager. Sie sammeln im Unterholz Informationen.",al={"kundschafter standort","wo sind die kundschafter","wo kundschafter finden"}},{q="Warum sind die Kundschafter eine Bedrohung für die Horde?",a="Die Kundschafter sind vorgeschobene Späher, die vom Außenposten der Silberschwingen aus operieren. Wenn sie Lager der Horde kartieren und Truppenstärken ermitteln, kann die Allianz gezielte Überfälle auf verwundbare Stellungen planen.",al={"warum kundschafter töten","bedrohung durch kundschafter","aufgabe der kundschafter"}},{q="Was ist der Außenposten der Silberschwingen?",a="Der Außenposten der Silberschwingen ist eine bedeutende Militäranlage der Nachtelfen in Eschental. Die Streitkräfte der Allianz nutzen ihn als Frontstützpunkt, um den Wald zu verteidigen und der Ausbreitung der Horde entgegenzuwirken.",al={"außenposten der silberschwingen hintergrund","was ist der außenposten der silberschwingen","silberschwingen allianz"}},{q="Ist diese Quest Teil einer längeren Geschichte?",a="Dieser Einsatz steht für sich und dient dazu, die Aufklärung der Allianz in der Gegend einzuschränken. Kämpfer, die Kuray'bin helfen, das umliegende Gebiet zu sichern, erhalten eine Belohnung.",al={"questreihe","folgequest","kundschafter questreihe"}},{q="Können Spieler der Allianz diese Quest abschließen?",a="Nein. Kuray'bin arbeitet an den Fronten Eschentals ausschließlich für die Horde.",al={"ist das nur für die horde","allianzversion","kann die allianz das machen"}}},fx={["2873db73"]={q="Warum will Kuray'bin, dass die Eschental Outrunners getötet werden?",a="Kuray'bin will die Allianz blenden und sie daran hindern, einen organisierten Angriff auf das Gebiet der Horde zu starten. Die Vorhut ist kürzlich aus dem Außenposten der Silberschwingen geschlüpft, um in der Nähe der Linien der Horde zu patrouillieren. Wenn sie die Verteidigungen und Truppenbewegungen Eures Lagers auskundschaften, ist eine Offensive der Allianz so gut wie sicher. Sie zu eliminieren, beraubt den Feind wichtiger Informationen über das Schlachtfeld.",al={"motiv von kuraybin","warum die vorhut töten","grund von kuray'bin"}},["884af179"]={q="Wer sind die Eschental Outrunners?",a="Es handelt sich um Nachtelfenspäher, die vom nahe gelegenen Stützpunkt der Allianz, dem Außenposten der Silberschwingen, entsandt wurden. Unter dem dichten Blätterdach des Waldes operierend, kriechen diese agilen Vorhutsspäher nahe an die Grenzen der Horde heran, um Befestigungen zu überwachen, Patrouillenrouten zu beobachten und den Boden für zukünftige Einfälle der Allianz vorzubereiten.",al={"was sind ashenvale outrunners","wer sind die vorhut","ziel der vorhut im eschental"}}},fp="20,189,20.332.0,21.325.0,41.141.0,43.140.0,45.183.0,27.172.0,41.144.0,41.66.0"}
P.entries["quest:6504"] = {n="Die verlorenen Seiten",s="Ein Windstoß hat die verlorenen Seiten über Eschental verstreut und Gurda Zornnarbe nahe dem Splitterholzposten stranden lassen. Ohne Handbuch kann sie den Schredder nicht bedienen, den sie von Ratschet zum Holzfällerlager des Kriegshymnenklans bringt.",h="Ein Windstoß hat die verlorenen Seiten über Eschental verstreut und Gurda Zornnarbe nahe dem...",kw={"eschental","gurda zornnarbe","ratschet","schredder","schredder bedienungsanleitung","splitterholzposten","die verlorenen seiten","holzfällerlager des kriegshymnenklans"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass jeder Schredder im Holzfällerlager des Kriegshymnenklans hilft, Holz für Mauern, Hütten und Kriegsschiffe in Durotar zu beschaffen.",["profession:Engineering"]="Als Ingenieur könnt Ihr Gurdas Schwierigkeiten nachvollziehen. Wer einen Goblin-Schredder ohne die Anleitung seines Herstellers betreibt, riskiert einen Kesselausfall.",["race:Orc"]="Als Orc teilt Ihr vielleicht Gurdas Frust über die verlorenen technischen Seiten. Körperliche Arbeit und Kriegertraditionen lassen wenig Geduld für Goblinpapierkram."},sec={{t="Ein unheilvoller Windstoß",b="Der Kriegshymnenklan kauft dampfbetriebene Schredder in Ratschet, um überall in Eschental Holz zu schlagen. Ihre empfindliche Mechanik ist für einen Orc-Krieger mitunter schwer zu beherrschen. Als Gurda Zornnarbe einen neu gekauften Schredder nach Norden brachte, riss ihr ein plötzlicher Windstoß das Anleitungsheft aus den Händen. Zwölf Pergamentblätter verstreuten sich über den Waldboden."},{t="Seiten in der Wildnis",b="Der Wind trug die Seiten des Handbuchs durch ganz Eschental. Umherstreifende Kreaturen, Kultisten und Waldbewohner haben sie an sich genommen. Ohne alle drei Kapitel lässt sich der Schredder nicht bedienen. Gurda sitzt an der Straße zum Splitterholzposten fest und kann sich nicht zum Holzfällerdienst melden."}},faq={{q="Wer ist Gurda Zornnarbe?",a="Gurda Zornnarbe ist eine Arbeiterin der Horde, die einen Goblin-Schredder von Ratschet nach Eschental bringt, für die Holzfällerarbeiten im Holzfällerlager des Kriegshymnenklans.",al={"gurda","zornnarbe","wer ist der questgeber"}},{q="Warum braucht Gurda eine Anleitung, um den Schredder zu fahren?",a="Goblinmaschinen sind empfindlich und schwer zu verstehen. Selbst ein eifriger Orc kann den Schredder ohne das Handbuch seines Herstellers nicht sicher bedienen.",al={"warum handbuch","warum kann sie ihn nicht fahren","schredder bedienungsanleitung"}},{q="Wie wurden die Seiten des Handbuchs über ganz Eschental verstreut?",a="Ein heftiger Windstoß riss Gurda das Buch aus den Händen, als sie auf der Waldstraße nach Norden reiste. Seine losen Seiten verstreuten sich im Wald, und ihr blieb nur der leere vordere Buchdeckel.",al={"wie gingen die seiten verloren","wind verwehte seiten"}},{q="Wohin soll der Schredder letztlich gelangen?",a="Der Schredder ist für das Holzfällerlager des Kriegshymnenklans bestimmt, wo die Horde Holz schlägt, um Orgrimmar und Durotar zu versorgen.",al={"wohin kommt der schredder","kriegshymnen schredder ziel"}},{q="Wo sind die fehlenden Seiten zu finden?",a="Die Seiten wurden über ganz Eschental verstreut und von Humanoiden und feindseligen Waldbewohnern aufgelesen, die durch die Region streifen.",al={"wo seiten finden","wer lässt die seiten fallen"}},{q="Warum kauft die Horde Maschinen aus Ratschet?",a="Ratschet ist der nächstgelegene neutrale Hafen mit Handelsverbindungen zu Goblinkartellen. Die Horde kauft dort spezialisierte Ingenieurstechnik, Sprengwerkzeuge und dampfbetriebene Fahrzeuge für ihre Militärlogistik.",al={"horde goblinmaschinen","ratschet handel horde"}}},fx={["63589195"]={q="Warum braucht Gurda Zornnarbe Euch, um die Handbuchseiten zu finden?",a="Gurda steckt auf der Straße nahe dem Splitterholzposten mit einem ungenutzten Goblin-Schredder fest, den sie nicht bedienen kann. Sie wurde damit beauftragt, die teure Maschine aus Ratschet zurückzubringen, um sich zum Dienst im Holzfällerlager des Kriegshymnenklans zu melden. Ohne das Handbuch hat sie keine Ahnung, wie sie ihn fahren soll, und das Fahrzeug in der Wildnis aufzugeben, um zu Fuß den Wald zu durchsuchen, würde wertvolle Ausrüstung der Horde ungeschützt lassen.",al={"warum braucht gurda hilfe","warum kann gurda die seiten nicht finden","warum ich verlorene seiten"}}},fp="14,213,18.331.0,23.258.0,22.130.0,64.132.0,61.182.0,42.111.0,37.118.0,51.189.0"}
P.entries["quest:651"] = {n="Steine der Bindung",s="In Arathi halten vier Steine der Bindung Myzrael unter der Erde gefangen. Eine Stimme aus den schillernden Splittern sagt, der stärkste Stein brauche Schlüssel von den anderen dreien.",h="In Arathi halten vier Steine der Bindung Myzrael unter der Erde gefangen.",kw={"arathihochland","brennender schlüssel","wappenschlüssel","schillernde splitter","myzrael","stone of inner binding","steine der bindung","donnernder schlüssel"},sec={{t="Vier Steine",b="Über Arathi verteilt halten vier Steine Myzrael unter der Erde gefangen, sagt eine Stimme. Der Stone of Inner Binding ist der stärkste, und Schlüssel von den Stones of West, East and Outer Binding können ihn aufschließen. Sammelt den Brennenden Schlüssel, den Wappenschlüssel und den Donnernden Schlüssel. Wächter bewachen die Steine, doch wer klug ist oder Glück hat, findet vielleicht einen Weg, sie zu verbannen. Bringt die Schlüssel zum Stone of Inner Binding."},{t="Am inneren Stein",b="Myzraels Stimme dringt aus dem Stein. Die Steine der Bindung sind offen, die Fesseln lockern sich, und die Freiheit rückt näher. Myzrael preist Euch als edlen Retter."}},faq={{q="Woher stammt dieser Schritt?",a="Dieser Schritt folgt auf The Princess Trapped. Seine Stimme kommt aus den schillernden Splittern.",al={"steine der bindung questgeber","wer vergibt steine der bindung","wo beginnt steine der bindung"}},{q="Welche sind die vier Steine der Bindung?",a="Die vier sind der Stone of West Binding, der Stone of East Binding, der Stone of Outer Binding und der stärkste, der Stone of Inner Binding.",al={"welche steine der bindung","arathi steine der bindung","vier steine"}},{q="Welche Schlüssel werden benötigt, um den inneren Stein aufzuschließen?",a="Der Brennende Schlüssel, der Wappenschlüssel und der Donnernde Schlüssel werden bei den Stones of West, East and Outer Binding gesammelt.",al={"schlüssel der bindung","welche schlüssel werden benötigt","schlüssel für stone of inner binding"}},{q="Wer bewacht die Steine der Bindung?",a="Wächter wachen über die Steine, doch ein kluger Abenteurer oder einer mit Glück findet vielleicht einen Weg, sie zu verbannen.",al={"steinwächter","wer bewacht die steine","beschützer der steine der bindung"}},{q="Wohin müssen die Schlüssel gebracht werden?",a="Bringt die Schlüssel zum mächtigsten Stein, dem Stone of Inner Binding. Er muss aufgeschlossen werden, bevor sich die anderen öffnen.",al={"wohin die schlüssel bringen","steine der bindung abgeben","stone of inner binding standort"}}},fp="17,159,11.387.0,18.163.1,31.83.0,36.140.0,48.118.0,30.99.0,33.115.0"}
P.entries["quest:652"] = {n="Den Hauptstein zerbrechen",s="Die Stimme hat jetzt mehr Freiheit, doch der Keystone bindet sie noch immer. Der Keystone liegt inmitten eines Steinkreises, und Fozruk besitzt den Schlüssel, den die Behüter Rute der Ordnung nennen.",h="Die Stimme hat jetzt mehr Freiheit, doch der Keystone bindet sie noch immer.",kw={"arathihochland","fozruk","keystone","rute der ordnung","stone of inner binding","steinwächter"},sec={{t="Das letzte Schloss",b="Das Öffnen der Steine der Bindung lockerte die Gefangenschaft der Stimme, doch ein Schloss hält den Keystone noch immer verschlossen. Er liegt inmitten des Steinkreises um Euch herum. Fozruk, ein Steinwächter und einer ihrer Häscher, besitzt den Schlüssel, den die Behüter Rute der Ordnung nennen. Bringt die Rute zum Keystone und öffnet das Schloss. Die Stimme verspricht eine Dankbarkeit, die die Erde bis in ihre Grundfesten erschüttern wird. Geomantische Energie erfüllt den Keystone."},{t="Am Keystone",b="Als Ihr die Rute in den Keystone einsetzt, durchfährt ein Beben den Boden unter Euch."}},faq={{q="Was kommt vor diesem Schritt?",a="Die Steine der Bindung kamen zuerst. Sie zu öffnen, lockerte die Gefangenschaft der Stimme erheblich.",al={"voraussetzung","vorherige quest","steine der bindung voraussetzung"}},{q="Wer ist Fozruk?",a="Fozruk ist ein Steinwächter und einer der Häscher der Stimme. Er besitzt den Schlüssel zum Keystone.",al={"wer ist fozruk","fozruks geschichte","steinwächter fozruk"}},{q="Was ist die Rute der Ordnung?",a="Die Steinwächter nennen den Schlüssel zum Keystone die Rute der Ordnung. Fozruk besitzt sie.",al={"rute der ordnung","was ist die rute der ordnung","keystone schlüssel"}},{q="Wo ist der Keystone?",a="Der Keystone liegt inmitten eines Steinkreises im Arathihochland.",al={"wo ist den hauptstein zerbrechen","keystone standort","steinkreis arathi"}}},fp="21,170,13.399.0,15.66.1,28.85.0,14.91.0,25.82.0,22.67.0"}
P.entries["quest:6521"] = {n="An Unholy Alliance",s="Varimathras schickt Euch los, um Ambassador Malcin außerhalb der Hügel der Klingenhauer zu stellen. Seine Anwesenheit könnte die ungewöhnliche Stärke und die Seuchenzeichen bei einigen Quilboar erklären.",h="Varimathras schickt Euch los, um Ambassador Malcin außerhalb der Hügel der Klingenhauer zu stellen.",kw={"ambassador malcin","ein unheiliges bündnis","lich king","seuche","quilboar","hügel der klingenhauer","unterstadt","varimathras"},sec={{t="Der Gesandte",b="Varimathras wartet in der Unterstadt mit einem Auftrag auf Euch. Außerhalb der Hügel der Klingenhauer könnte die Anwesenheit von Ambassador Malcin erklären, warum einige Quilboar mächtig geworden sind und auf ihre eigene Weise Anzeichen der Seuche zeigen. Varimathras nennt die Mission des Gesandten in den Augen des Lich King gescheitert und verlangt seinen Tod."}},faq={{q="Wer beauftragt mich, Malcin zu finden?",a="Varimathras in der Unterstadt bittet Euch, Ambassador Malcin außerhalb der Hügel der Klingenhauer zu finden.",al={"wer hat mich geschickt","varimathras auftrag"}},{q="Wer ist Ambassador Malcin?",a="Ambassador Malcin ist ein Gesandter außerhalb der Hügel der Klingenhauer. Seine Anwesenheit könnte die ungewöhnliche Stärke und die Seuchenzeichen bei einigen Quilboar erklären.",al={"wer ist malcin","ambassador malcin"}},{q="Warum will Varimathras Malcin tot sehen?",a="Varimathras sagt, die Mission von Ambassador Malcin sei in den Augen des Lich King gescheitert.",al={"warum malcin töten","malcins mission"}},{q="Was geschieht mit den Quilboar?",a="Einige Quilboar sind ungewöhnlich mächtig geworden und zeigen auf ihre eigene Weise Anzeichen der Seuche.",al={"quilboar und die seuche","warum sind quilboar mächtig"}},{q="Wo ist Malcin?",a="Varimathras sagt, Ambassador Malcin sei außerhalb der Hügel der Klingenhauer.",al={"malcins aufenthaltsort","malcin finden"}},{q="Was soll ich Varimathras zurückbringen?",a="Varimathras bittet Euch, ihm den Kopf von Ambassador Malcin in der Unterstadt zu bringen.",al={"malcins kopf","was varimathras bringen"}}},fp="18,167,9.286.0,32.87.0,25.138.0,38.71.0,34.90.0,16.61.0,43.76.0"}
P.entries["quest:6522"] = {n="An Unholy Alliance",s="Eine kleine Schriftrolle ist für Varimathras in der Unterstadt bestimmt. Ihr bringt sie zu ihm.",h="Eine kleine Schriftrolle ist für Varimathras in der Unterstadt bestimmt.",kw={"eine unheilige allianz","anliegen","kleine schriftrolle","unterstadt","varimathras"},sec={{t="Vor Varimathras",b="Varimathras wartet in der Unterstadt darauf, zu erfahren, welches Anliegen Euch herführt. Die kleine Schriftrolle haltet Ihr in den Händen, und er erwartet, dass Euer Anliegen wichtig ist."}},faq={{q="Für wen ist die Schriftrolle?",a="Die kleine Schriftrolle ist für Varimathras in der Unterstadt bestimmt.",al={"für wen ist die schriftrolle","wer bekommt die schriftrolle"}},{q="Wohin soll ich die kleine Schriftrolle bringen?",a="Bringt die kleine Schriftrolle zu Varimathras in die Unterstadt.",al={"wohin mit der schriftrolle","wohin die schriftrolle bringen"}},{q="Wovon möchte Varimathras hören?",a="Varimathras fragt, über welches Anliegen Ihr sprechen möchtet.",al={"welches anliegen","was varimathras sagen"}}},fp="18,85,18.147.0,22.59.0,33.54.0,41.52.0"}
P.entries["quest:6523"] = {n="Schützt Kaya",s="Im Steinkrallengebirge wird Kaya Flathoof von feindseligen Tauren der Grimtotem gefangen gehalten. Abenteurer der Horde geleiten sie über gefährliche Pfade nach Camp Aparaje und berichten dann ihrem besorgten Vater Makaba Flachhuf, dass sie überlebt hat.",h="Im Steinkrallengebirge wird Kaya Flathoof von feindseligen Tauren der Grimtotem gefangen gehalten.",kw={"camp aparaje","eskorte","grimtotem","kaya flathoof","makaba flachhuf","schützt kaya","steinkrallengebirge","tauren"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, reisende Familien zu schützen und die Stützpunkte und Versorgungswege der Horde im Steinkrallengebirge zu stärken.",["race:Tauren"]="Als Tauren helft Ihr jemandem aus Eurem eigenen Volk, der unter den Angriffen des Grimtotemklans leidet."},sec={{t="Gefangen zwischen den Felsen",b="Kaya Flathoof wurde tief im Gebiet der Grimtotem im Steinkrallengebirge gefangen genommen. Erbitterte Rivalitäten spalten die Taurenklans, und nur wenige sehen sich schärferer Feindseligkeit ausgesetzt als die Grimtotem. Kaya ist aus der Gefangenschaft entkommen, doch bis auf befreundeten Boden führen Pfade, auf denen Feinde und Raubtiere lauern. Eine bewaffnete Eskorte bietet ihr die beste Hoffnung, hindurchzukommen."},{t="Flucht nach Camp Aparaje",b="Kaya will Camp Aparaje im östlichen Steinkrallengebirge erreichen. Von dort kennt sie den Heimweg und kann allein weiterziehen. Ihr geleitet sie über Pfade, auf denen Hinterhalte drohen, und helft ihr, auf dem Weg in Sicherheit einer erneuten Gefangennahme zu entgehen."},{t="Die Erleichterung eines Vaters",b="Makaba Flachhuf wartet nahe der südöstlichen Grenze des Steinkrallengebirges und fürchtet das Schlimmste für seine vermisste Tochter. Läufer überbringen die Nachricht, dass Kaya Camp Aparaje sicher erreicht hat. Makabas Verzweiflung weicht der Dankbarkeit gegenüber den Streitern, die sich zwischen sein Kind und ihre Entführer gestellt haben."}},faq={{q="Wer ist Kaya Flathoof?",a="Kaya Flathoof ist eine junge Taurin, die von feindseligen Streitkräften der Grimtotem im Steinkrallengebirge gefangen genommen wurde. Sie ist auf vorbeiziehende Abenteurer der Horde angewiesen, die ihr helfen, zu entkommen und sicheren Boden zu erreichen.",al={"wer ist kaya","kaya flathoof hintergrundgeschichte","kaya"}},{q="Wohin muss Kaya geleitet werden?",a="Kaya braucht eine Eskorte über die Pfade nach Camp Aparaje im östlichen Steinkrallengebirge. Sie will das Lager erreichen, von dem aus sie den Heimweg kennt.",al={"kaya eskortziel","wohin kaya bringen","wohin geht kaya"}},{q="Wer ist Makaba Flachhuf?",a="Makaba Flachhuf ist Kayas Vater und wartet voller Sorge nahe dem südöstlichen Zugang zum Steinkrallengebirge. Er bangt um sein vermisstes Kind, bis Abenteurer die Nachricht bringen, dass sie gerettet wurde.",al={"wer ist makaba","makaba flachhuf hintergrundgeschichte","kayas vater"}},{q="Wer hat Kaya gefangen genommen?",a="Feindselige Tauren der Grimtotem haben Kaya gefangen genommen. Ihre Lager und Hinterhalte verteilen sich über die zerklüfteten Felsen des Steinkrallengebirges.",al={"wer hat kaya verschleppt","wer hat kaya entführt","kayas entführer"}},{q="Was geschieht, nachdem Kaya Camp Aparaje erreicht hat?",a="Sobald Kaya Camp Aparaje erreicht hat, findet sie allein nach Hause. Ihr kehrt dann mit der freudigen Nachricht, dass sie überlebt hat, zu Makaba Flachhuf zurück.",al={"nach schützt kaya","was kommt nach der eskorte","schützt kaya folgequest"}},{q="Ist diese Quest für Spieler der Allianz verfügbar?",a="Nein. Die Familie Flathoof besteht aus friedlichen Tauren, die der Horde angehören, daher können nur Abenteurer der Horde bei dieser Rettung helfen.",al={"kann die allianz schützt kaya machen","ist kaya nur für die horde"}}},fx={ee59f589={q="Warum benötigt Kaya Flathoof Euren Schutz?",a="Kaya ist gerade ihren Entführern entkommen, sitzt aber weiterhin hinter feindlichen Linien in den Bergen fest. Wenn ihre Entführer ihre Flucht bemerken, bevor sie sicheres Gelände erreicht, wird sie wieder gefangen genommen oder getötet. Das Camp Aparaje zu erreichen, ist ihre einzige Chance, Sicherheit zu finden und Nachricht an ihren Vater Makaba zu senden, der das Schlimmste für ihr Überleben befürchtet.",al={"warum kaya beschützen","motiv von kaya flathoof","warum braucht kaya eskort"}},["87bb92ff"]={q="Warum kann Kaya Flathoof nicht alleine entkommen?",a="Kaya ist geschwächt, unbewaffnet und vollständig von feindlichem Gebiet umgeben. Ohne einen fähigen Kämpfer, der sie vor umherstreifenden Patrouillen abschirmt, während sie flieht, kann sie den Weg in Richtung Camp Aparaje nicht sicher zurücklegen, bevor ihr Verschwinden entdeckt wird.",al={"warum braucht kaya mich","warum kann kaya nicht alleine gehen","warum wird eskort benötigt"}}},fp="12,224,22.345.0,22.228.0,17.265.1,21.180.0,36.129.0,23.198.0,18.100.0,45.137.0,44.120.0"}
P.entries["quest:653"] = {n="Myzraels Verbündete",s="Myzrael ist frei, doch sie muss Kraft sammeln, bevor sie sich ihren Peinigern stellen kann. Sie nennt Euch einen edlen Verbündeten und schickt Euch zu Gerrig Knochengriff in einen Laden in Eisenschmiedes Forlorn Cavern, wo er sie zu beschwören weiß.",h="Myzrael ist frei, doch sie muss Kraft sammeln, bevor sie sich ihren Peinigern stellen kann.",kw={"arathihochland","forlorn cavern","gerrig knochengriff","riesen","eisenschmiede","schlüsselstein","myzrael"},sec={{t="Frei, um Kraft zu sammeln",b="Myzrael ist frei, aber noch nicht stark genug, um sich ihren Peinigern zu stellen. Sie würden sie jetzt überwältigen und erneut wegsperren. Deshalb wird sie im Verborgenen Kraft sammeln. Wenn sie bereit ist, will sie sich den Riesen stellen und sie den Tag bereuen lassen, an dem sie sie gefangen nahmen. Sie nennt Euch einen edlen Verbündeten und sagt, dass sie Eure Hilfe brauchen wird, um sie an die Oberfläche zu beschwören."},{t="Nachricht für Gerrig Knochengriff",b="Myzrael schickt Euch zu Gerrig Knochengriff, dessen Laden in Eisenschmiedes Forlorn Cavern liegt. Er weiß, wie sie beschworen werden kann."}},faq={{q="Wo ist Gerrig Knochengriff zu finden?",a="Gerrig Knochengriff führt einen Laden in Eisenschmiedes Forlorn Cavern.",al={"gerrig knochengriff standort","wo ist gerrig knochengriff","gerrig knochengriff finden"}},{q="Warum bleibt Myzrael im Verborgenen?",a="Myzrael muss zuerst Kraft sammeln. Würden ihre Peiniger ihr jetzt gegenübertreten, würden sie sie überwältigen und erneut einsperren.",al={"warum versteckt sich myzrael","wohin geht myzrael"}},{q="Wer sind die Peiniger, von denen Myzrael spricht?",a="Myzrael meint die Riesen, in deren Obhut sie war. Sie sagt, dass sie sich ihnen zu gegebener Zeit stellen und sie bereuen lassen wird, sie festgehalten zu haben.",al={"myzraels peiniger","wer hat myzrael eingesperrt","myzrael riesen"}},{q="Warum schickt Myzrael Euch nach Eisenschmiede?",a="Myzrael schickt Euch zu Gerrig Knochengriff, weil er weiß, wie sie beschworen werden kann. Sie wird Eure Hilfe brauchen, um sie an die Oberfläche zu beschwören, wenn sie bereit ist.",al={"warum nach eisenschmiede gehen","zweck des besuchs bei gerrig"}}},fp="16,213,23.331.0,24.110.0,35.59.0,35.114.0,38.124.0,39.150.0"}
P.entries["quest:654"] = {n="Tanaris-Feldproben",s="In Tanaris beginnt ein Feldtest, sobald die Energiequelle des Sets eingeschaltet wird. Dann beginnen Eure zwei Stunden zum Sammeln von Proben.",h="In Tanaris beginnt ein Feldtest, sobald die Energiequelle des Sets eingeschaltet wird.",kw={"basilisk","bilgewhizzle","feldtestset","gadgetzan","hyäne","energiequelle","skorpion","tanaris","wasserunternehmen"},sec={{t="Eine tickende Energiequelle",b="Chefingenieur Bilgewhizzle erwartete, dass das Set leuchtet und vibriert, sobald seine Energiequelle läuft. Nun habt Ihr zwei Stunden Zeit, um brauchbare Proben von acht Basilisken, acht Hyänen und acht Skorpionen in der Wüste von Tanaris zu sammeln.\n\nWenn die Zeit abläuft, gehen alle Daten verloren. Ihr müsst eine weitere Energiequelle von Bilgewhizzle kaufen und ihm dann das Set in Gadgetzan zurückbringen, bevor ihm die Energie ausgeht."},{t="Der Profit des Unternehmens",b="Bilgewhizzle zeigt kein Mitleid, wenn ein Set den Geist aufgibt. Für ihn zählt nur der Profit der Gadgetzan Water Company.\n\nEr wird weiter Energiequellen verkaufen, bis sich das Unternehmen den Import von Wasser aus den eisigen Quellen von Dun Morogh leisten kann."}},faq={{q="Von welchen Kreaturen werden Proben für das Feldtestset benötigt?",a="Sammelt brauchbare Proben von acht Basilisken aus Tanaris, acht Hyänen und acht Skorpionen.",al={"welche tiere testen","ziele für proben","was töten"}},{q="Wie viel Zeit steht zum Sammeln der Proben zur Verfügung?",a="Ihr habt zwei Stunden ab dem Augenblick, in dem die Energiequelle eingeschaltet wird.",al={"zeitlimit","wie viel zeit bleibt","zeitmesser"}},{q="Was geschieht, wenn der Energiequelle die Energie ausgeht?",a="Alle Daten im Set gehen verloren. Um erneut zu beginnen, kauft eine weitere Energiequelle von Chefingenieur Bilgewhizzle in Gadgetzan.",al={"wenn die zeit abläuft","quest fehlgeschlagen","energie aufgebraucht"}},{q="Wohin muss das Feldtestset gebracht werden, sobald es voll ist?",a="Bringt das volle Feldtestset zu Chefingenieur Bilgewhizzle in Gadgetzan zurück, bevor ihm die Energie ausgeht.",al={"bei wem abgeben","abgabeort","wo ist bilgewhizzle"}},{q="Warum verkauft Bilgewhizzle immer weiter Energiequellen?",a="Bilgewhizzle will, dass die Gadgetzan Water Company Profit macht. Er wird weiter Energiequellen verkaufen, bis sich das Unternehmen den Import von Wasser aus den eisigen Quellen von Dun Morogh leisten kann.",al={"bilgewhizzles ziel","ziel der gadgetzan water company","warum proben sammeln"}}},fp="22,120,22.403.0,20.237.0,54.89.0,52.67.0,42.120.0,40.99.0,49.164.0"}
P.entries["quest:6541"] = {n="Meldung bei Kadrak",s="Am Wegekreuz schickt Thork bewährte Kämpfer der Horde nach Norden zu Kadraks Wachturm. Der Orc bereitet Rekruten auf die bevorstehenden Kämpfe nahe der Grenze zum Eschental vor.",h="Am Wegekreuz schickt Thork bewährte Kämpfer der Horde nach Norden zu Kadraks Wachturm.",kw={"eschental","brachland","das wegekreuz","kadrak","splintertree","thork","wachturm","der zoramstrand"},ang={["faction:Horde"]="Als Mitglied der Horde geht Ihr von der Verteidigung besiedelter Gebiete im Brachland dazu über, lebenswichtige Rohstoffe in den umkämpften Wäldern im Norden zu sichern.",["race:Orc"]="Als Orc betretet Ihr einen entscheidenden Ort der Bewährung. Das Holz des Eschentals kann helfen, Orgrimmar zu befestigen und eine dauerhafte Heimat auf Kalimdor zu schaffen."},sec={{t="Der Weg nach Norden",b="Das Wegekreuz sieht sich Borstennacken, Zentauren und örtlichen Räubern gegenüber. Dahinter richtet die Horde ihren Blick auf die dichten Wälder des Eschentals. Thork schickt Kämpfer, die sich im zentralen Brachland bewährt haben, zum Turm an der nördlichen Grenze, wo Kadrak stationiert ist."},{t="Strategie an der Grenze",b="Kadrak überwacht den südlichen Zugang zum Eschental und organisiert Verstärkung für den Stützpunkt der Horde jenseits der Grenze. Der Splitterholzposten und ein Außenposten am Zoramstrand helfen, die Präsenz der Horde in den holzreichen Wäldern zu stärken. Die einheimischen Nachtelfen leisten ihnen erbitterten Widerstand."}},faq={{q="Wer ist Thork?",a="Thork ist ein orcischer Offizier am Wegekreuz im Brachland. Er hilft, die örtliche Verteidigung zu organisieren, und schickt vielversprechende Kämpfer in Feldzüge wie den Vorstoß ins Eschental.",al={"thork wegekreuz","wer vergibt meldung bei kadrak","thork brachland"}},{q="Wo befindet sich Kadrak?",a="Kadrak befindet sich am nördlichen Wachturm im Brachland, neben der Hauptstraße ins Eschental.",al={"kadrak standort","wo ist kadrak","kadrak wachturm"}},{q="Warum dringt die Horde ins Eschental vor?",a="Die Horde sucht Bauholz und andere Rohstoffe, um ihre neuen Städte in Durotar und im Brachland zu errichten. Das Holz ist lebenswichtig, doch die Suche danach bringt die Horde in direkten Konflikt mit den Nachtelfen.",al={"warum eschental","horde im eschental","invasion im eschental"}},{q="Welche Außenposten hat die Horde im Eschental errichtet?",a="Die Horde hat den Splitterholzposten an der zentralen Straße durch das Eschental und einen weiteren Außenposten weiter westlich am Zoramstrand errichtet.",al={"hordestützpunkte eschental","zoramstrand stützpunkt","splintertree"}},{q="Was folgt nach der Meldung bei Kadrak?",a="Nachdem Ihr Euch bei Kadrak gemeldet habt, unterrichtet er Euch über die örtliche militärische Lage. Dann schickt er Euch los, um Berichte von den Warsong-Außenposten im gesamten Eschental einzuholen.",al={"nach kadrak","nächste quest nach kadrak","was vergibt kadrak"}},{q="Kann man diesen Auftrag auch außerhalb des Brachlands erhalten?",a="Ja. Kämpfer der Horde, die von Malaka'jin im Steinkrallengebirge aus operieren, erhalten eine nahezu identische Aufforderung, sich bei Kadrak zu melden.",al={"alternative kadrak-quest","steinkrallengebirge kadrak-quest"}}},fx={d049fa98={q="Warum will Thork, dass ich mich bei Kadrak melde?",a="Die Horde sichert aktiv ihren Halt im Eschental, nachdem sie kürzlich Außenposten wie den am Zoram-Strand errichtet hat. Thork beaufsichtigt die Verteidigung des Wegekreuzes, doch die Frontlinien im Norden erfordern ständig frische Rekruten, um diese neu beanspruchten Gebiete zu schützen. Er schickt fähige Krieger hinauf zu Kadrak, der die Kampagne vom nördlichen Wachturm aus koordiniert und bestimmt, wo Verstärkung am dringendsten benötigt wird.",al={"warum bei kadrak melden","motiv von thork melden bei kadrak","warum schickt thork mich zu kadrak"}}},fp="16,159,14.255.0,17.286.0,13.174.0,24.90.0,40.190.0,53.128.0,37.154.0,69.129.0"}
P.entries["quest:6542"] = {n="Meldung bei Kadrak",s="In Malaka'jin schickt Darn Talongrip Krieger der Horde nach Norden zu Kadraks Wachtposten. Die Reise führt von den Felsen des Steinkrallengebirges nach Eschental, wo die Horde am Splitterholzposten und am Zoramstrand Vorposten unterhält.",h="In Malaka'jin schickt Darn Talongrip Krieger der Horde nach Norden zu Kadraks Wachtposten.",kw={"eschental","brachland","darn talongrip","kadrak","splitterholzposten","steinkrallengebirge","berichte des kriegshymnenklans","der zoramstrand"},ang={["faction:Horde"]="Als Krieger der Horde schließt Ihr Euch den umfassenderen Kriegsanstrengungen des Kriegshäuptlings an. Ihr verlasst das Grenzland, um Euch am Kampf um Eschentals Rohstoffe zu beteiligen.",["race:Orc"]="Als Orc zieht Ihr in einen Feldzug, der für den Kriegshymnenklan und das Überleben Durotars entscheidend ist. Kadraks Posten ist eine Bewährungsstätte für junge Orc-Krieger.",["race:Tauren"]="Als Tauren reist Ihr unter der Führung von Spähern der Horde wie Darn Talongrip. Sie helfen Reisenden, die Berggrenzen zu überqueren, und halten die Verbindung zwischen den Gebieten von bloodhoof und der Nordfront des Kriegshäuptlings offen."},sec={{t="Ein Ruf an die Nordfront",b="Darn Talongrip wacht von Malaka'jin aus über die südlichen Grenzen und die Berggrenzen der Horde. Der Orc schickt fähige Kämpfer, die das Steinkrallengebirge durchqueren, zum Wachturm im nördlichen Brachland. In Eschental ist der Druck größer. Dort geraten Schildwachen der Nachtelfen mit Holzsammlern des Kriegshymnenklans aneinander, und die Horde braucht Kämpfer, während der Kampf um den Wald weitergeht."},{t="Kadraks Wacht",b="Kadrak überwacht die Truppenbewegungen der Horde von einem Wachturm im nördlichen Brachland aus, wo die Savanne auf Eschental trifft. Die Horde hält Vorposten am Zoramstrand im Westen und am Splitterholzposten im Norden. Kadrak koordiniert Nachschub und Truppen und lässt dringende Berichte durch den umkämpften Wald überbringen."}},faq={{q="Wer schickt Euch aus dem Steinkrallengebirge zu Kadrak?",a="Darn Talongrip, ein Orc im Hordenvorposten Malaka'jin im Steinkrallengebirge, schickt fähige Kämpfer zur Waldgrenze.",al={"questgeber meldung bei kadrak","wer beginnt meldung bei kadrak steinkrallengebirge","darn talongrip quest"}},{q="Wo befindet sich Kadrak?",a="Kadrak befindet sich am nördlichen Wachturm im Brachland und bewacht die Hauptstraße nach Norden in Richtung Eschental.",al={"kadrak standort","wo ist kadrak","kadrak finden"}},{q="Warum wirbt die Horde Krieger für Eschental an?",a="Die Horde braucht Holz, um Orgrimmar zu versorgen, und hält befestigte Stellungen am Zoramstrand und am Splitterholzposten. Wegen des Widerstands der Nachtelfen brauchen die Befehlshaber Verstärkung, um das Gebiet zu sichern.",al={"warum nach eschental","horde feldzug eschental","warum in eschental kämpfen"}},{q="Was geschieht nach der Meldung bei Kadrak?",a="Kadrak unterrichtet Euch über Eschental und beauftragt Euch in „Die Berichte des Kriegshymnenklans“, Berichte zwischen den umkämpften Vorposten zu überbringen und einzusammeln.",al={"was kommt nach kadrak","die berichte des kriegshymnenklans","kadrak folgequest"}},{q="Unterscheidet sich diese Quest von der Version im Brachland?",a="Beide Depeschen schicken Euch zu Kadrak an der Grenze zu Eschental. Eine kommt vom Wegekreuz im Brachland, die andere aus dem Steinkrallengebirge. Beide führen in den Feldzug in Eschental.",al={"brachland oder steinkrallengebirge kadrak","zwei quests meldung bei kadrak","kadrak hinführungsquest doppelt"}},{q="Was ist der Zoramstrand, der in der Unterweisung erwähnt wird?",a="Der Zoramstrand ist eine Küstenregion im Nordwesten von Eschental am verhüllten Meer. Die Horde hält dort einen befestigten Strandvorposten, um Truppenbewegungen zu unterstützen und den Zugang vom Meer aus zu sichern.",al={"was ist der zoramstrand","zoramstrand vorposten","eschental strandstützpunkt"}}},fx={f0da3cc6={q="Warum will Darn Talongrip, dass Ihr Euch bei Kadrak meldet?",a="Die Horde hat kürzlich einen Außenposten am Zoram-Strand im Eschental errichtet und benötigt Rekruten zur Verteidigung ihrer neuen Fronten. Darn Talongrip, stationiert in Malaka'jin, verweist fähige Abenteurer an Kadrak am Wachturm des nördlichen Brachlands für weitere Befehle.",al={"warum schickt darn mich zu kadrak","motiv von darn talongrip","warum bei kadrak melden"}}},fp="16,210,28.358.0,14.304.0,40.135.0,24.98.0,51.199.0,39.129.0,49.188.0,51.187.0"}
P.entries["quest:6543"] = {n="Die Berichte des Kriegshymnenklans",s="Kuriere aus dem nördlichen Brachland tragen Kadraks Befehle und sammeln die Berichte des Kriegshymnenklans in ganz Eschental. Ihre Beobachtungen im Feld stammen von der Vorhut nahe Azshara, dem Splitterholzposten und dem Zoramstrand.",h="Kuriere aus dem nördlichen Brachland tragen Kadraks Befehle und sammeln die Berichte des Kriegshymnenklans in...",kw={"eschental","brachland","kadrak","splitterholzposten","vorhut des kriegshymnenklans","berichte des kriegshymnenklans","läufer des kriegshymnenklans","späher des kriegshymnenklans","der zoramstrand","außenposten von zoram'gar"},ang={["class:Hunter"]="Als Jäger stellt Ihr Eure Orientierungs- und Überlebensfähigkeiten auf Eschentals gefährlichen Straßen auf die Probe, wo wilde Raubtiere und verborgene elfische Bogenschützen drohen.",["faction:Horde"]="Das Überbringen dieser Berichte gibt einem jungen Krieger der Horde schon früh eine Rolle im Kampf gegen die Nachtelfen im nördlichen Kalimdor.",["race:Orc"]="Als Ork ehrt Ihr den Kriegshymnenklan und helft, das für den Bau Orgrimmars benötigte Holz zu beschaffen."},sec={{t="Versorgung an der Grenze",b="Kadrak überwacht den Gebirgspass zwischen dem nördlichen Brachland und Eschental von einem befestigten Turm aus. Die Horde braucht diese Route, weil das Brachland nicht das Holz liefern kann, das Orgrimmar benötigt. Deshalb ist der Kriegshymnenklan in den uralten Elfenwald vorgedrungen, um diese Vorräte zu erreichen. Kuriere überbringen Befehle zwischen verstreuten Patrouillen und helfen ihnen, ihre Einsätze aufeinander abzustimmen. Doch Hinterhalte der Nachtelfen bedrohen die Pfade durch die Wildnis."},{t="Augen in ganz Eschental",b="Späher des Kriegshymnenklans beobachten drei Gebiete Eschentals. An der Westküste beobachtet ein Läufer beim Außenposten von Zoram'gar die Aktivitäten der Naga und andere Gefahren entlang des Zoramstrands. Am Splitterholzposten koordiniert ein Späher die Verteidigung gegen Überfälle der Schildwachen. Weiter östlich überwacht ein Angehöriger der Vorhut die Straße zu den zerborstenen Ruinen von Azshara. Ihre Berichte geben Kadrak Einblick in die Bewegungen der Nachtelfen und die Schwachstellen entlang der Grenze."}},faq={{q="Wo beginnt diese Mission?",a="Die Berichte beginnen bei Kadrak, einem orkischen Offizier im hölzernen Wachturm, der den Gebirgspass zwischen dem nördlichen Brachland und dem südlichen Eschental bewacht.",al={"questgeber","kadraks standort","wer vergibt die berichte des kriegshymnenklans","wo beginnen"}},{q="Warum späht die Horde Eschental aus?",a="Die Horde sucht Holz aus Eschentals dichten Wäldern, um Siedlungen wie Orgrimmar zu errichten und zu befestigen. Nachtelfen verteidigen ihre heiligen Haine erbittert, weshalb ständige Aufklärung der Horde hilft, ihre Außenposten und Versorgungslinien im Konflikt zu halten.",al={"warum eschental","holz des kriegshymnenklans","konflikt in eschental"}},{q="Wo sind die drei Späher des Kriegshymnenklans zu finden?",a="Der Läufer des Kriegshymnenklans befindet sich beim Außenposten von Zoram'gar ganz im Nordwesten des Zoramstrands. Der Späher des Kriegshymnenklans befindet sich am Splitterholzposten an der Hauptstraße. Die Vorhut des Kriegshymnenklans patrouilliert auf der östlichen Straße zur Grenze von Azshara.",al={"standorte der späher","wo sind die späher","standorte von vorhut läufer und späher"}},{q="Wer gehört zur Vorhut des Kriegshymnenklans?",a="Zur Vorhut des Kriegshymnenklans gehören Späher und Plünderer dieses Orkklans. Ihre Reiterei und Scharmützel helfen der Horde, sich auszubreiten, Holz zu schlagen und Gebiete in Eschentals Wäldern zu verteidigen.",al={"kriegshymnenklan","wer gehört zur vorhut des kriegshymnenklans","kriegshymnenklan eschental"}},{q="Was geschieht nach der Rückgabe der Berichte?",a="Wenn Kadrak die Berichte erhält, nutzt er sie, um Truppenbewegungen zu planen, gefährdete Außenposten wie Zoram'gar und Splintertree zu verstärken und die Präsenz der Horde tiefer im Wald zu festigen.",al={"berichte abgeben","nächster schritt","was macht kadrak"}},{q="Ist die Straße durch Eschental für Kuriere niedriger Stufe sicher?",a="Nein. Schildwachen der Nachtelfen überfallen oft Reisende auf Eschentals Hauptstraße. Auch Streuner, Bären und Allianzpatrouillen aus Siedlungen wie Astranaar bedrohen Kuriere.",al={"gefahren in eschental","ist die straße sicher","überfälle der nachtelfen"}}},fx={["197774e3"]={q="Warum möchte Kadrak die Berichte gesammelt haben?",a="Kadrak bewacht die Grenze zwischen dem Brachland und den umkämpften Wäldern des Eschentals. Die Horde ist aktiv bestrebt, ihre Präsenz unter dem Blätterdach auszubauen, aber blind in das Gebiet der Nachtelfen zu marschieren, lädt zum Desaster ein. Kadrak setzte Aufklärer tief in der Region ein, um feindliche Aktivitäten und das Gelände zu überwachen. Er muss diese Aktualisierungen dringend geliefert und zurückerhalten, damit die Führung der Horde ihre taktische Lage genau einschätzen und ihre nächsten Schritte im laufenden Feldzug koordinieren kann.",al={"motiv von kadrak","warum will kadrak berichte","warum warsongberichte sammeln"}},["649e115c"]={q="Was ist der Aktualisierte Bericht der Vorhut des Kriegshymnenklans?",a="Der Aktualisierte Bericht der Vorhut des Kriegshymnenklans ist ein taktisches Geheimdokument, das von der Vorhut der Horde zusammengestellt wurde, die die östlichen Abschnitte des Eschentals in Richtung der Grenze von Azshara patrouilliert. Er enthält Beobachtungen zu Bewegungen der Allianz, Wächterpatrouillen und lokaler Geographie entlang der wichtigen Hauptstraße und versorgt Kadrak mit dem Überblick über die Ostgrenze, der für die Planung von Truppenmanövern erforderlich ist.",al={"aktualisierter bericht der vorhut des kriegshymnenklans","was ist aktualisierter bericht der vorhut","vorhutbericht"}},f6b4d8ea={q="Was ist der Aktualisierte Bericht des Läufers des Kriegshymnenklans?",a="Der Aktualisierte Bericht des Läufers des Kriegshymnenklans enthält Aufklärungsdaten, die an den westlichen Rändern des Waldes gesammelt wurden, stationiert vom Außenposten von Zoram'gar entlang des Zoram-Strandes. Diese Depesche beschreibt Bedrohungen an der Küste, lokale feindliche Kräfte und Annäherungen von der Seeseite und informiert Kadrak über die Sicherheit der Positionen der Horde weit westlich der Hauptstraße.",al={"aktualisierter bericht des läufers des kriegshymnenklans","was ist aktualisierter bericht des läufers","läuferbericht"}},["92e54885"]={q="Was ist der Aktualisierte Bericht des Spähers des Kriegshymnenklans?",a="Der Aktualisierte Bericht des Spähers des Kriegshymnenklans ist ein strategischer Bericht, der vom Splitterholzposten, dem wichtigsten Stützpunkt der Horde im zentralen Eschental, gesendet wurde. Erstellt vom dort stationierten Vorhutspäher, verfolgt er Einfälle der feindlichen Nachtelfen, logistische Versorgungsgüter und die Bereitschaft des Außenpostens, weitere Expansionen der Horde in der umliegenden Wildnis zu unterstützen.",al={"aktualisierter bericht des spähers des kriegshymnenklans","was ist aktualisierter bericht des spähers","späherbericht"}}},fp="19,205,18.410.0,21.421.0,30.150.0,37.236.0,44.214.0,30.179.0,41.195.0,58.169.0"}
P.entries["quest:6544"] = {n="Toreks Angriff",s="Am Außenposten der Silberschwingen führt Torek einen Angriff gegen die Nachtelfen an. Vom Splitterholzposten entsandt, will der Orc-Räuber im Grenzkrieg im Eschental den Widerstand der Schildwachen brechen und ihre Kommandantin Duriel Moonfire töten.",h="Am Außenposten der Silberschwingen führt Torek einen Angriff gegen die Nachtelfen an.",kw={"eschental","duriel moonfire","ertog ragetusk","räuber","schildwachen","außenposten der silberschwingen","splitterholzposten","torek"},ang={["class:Warrior"]="Ein brutaler Frontalkampf gegen kampferprobte Bogenschützen und Klingenmeister der Schildwachen stellt Eure Ausdauer auf die Probe.",["faction:Alliance"]="Duriel Moonfires Fall lässt den Außenposten der Silberschwingen schutzlos zurück und bedroht die angestammten Waldgebiete der Nachtelfen.",["faction:Horde"]="Für die Horde stellt der Durchbruch durch den Außenposten der Silberschwingen Eure Stärke auf die Probe und schwächt die Blockade der Nachtelfen um den Splitterholzposten.",["race:NightElf"]="Der Überfall trifft die Frontführung der Schildwachen und vergießt Elfenblut unter den Zweigen des Eschentals."},sec={{t="Ein Schlag aus den Schatten",b="Überall im Eschental sind die Holzfällerlager der Horde und die einheimischen Nachtelfen in einen eskalierenden Grenzkrieg verstrickt. Torek versammelt Räuber vom Splitterholzposten direkt vor dem Außenposten der Silberschwingen, um die Verteidigung der Allianz zu durchbrechen. Er stürmt vor, bevor die Nachtelfen zum Gegenangriff übergehen oder Kräfte für einen verstärkten Feldzug gegen den Splitterholzposten sammeln können."},{t="Die Einnahme von Silverwing",b="Der Außenposten der Silberschwingen ist eine Waldgarnison, die von Schildwachen der Silberschwingen und erbitterten Elfenkriegern gehalten wird. Torek nimmt ihre Anführerin Duriel Moonfire ins Visier. Fällt sie, verliert die örtliche Führung der Nachtelfen ihren Kopf, und die Räuber können Ertog Ragetusk am Splitterholzposten ihren blutigen Sieg melden."}},faq={{q="Wer ist Torek?",a="Torek ist ein Orc-Räuber, der am Splitterholzposten im Eschental stationiert ist. Wild und kampfbegierig führt er eine Schar gegen die Streitkräfte der Nachtelfen im Wald an.",al={"torek npc","wer ist torek","torek orc"}},{q="Was ist der Außenposten der Silberschwingen?",a="Der Außenposten der Silberschwingen ist eine befestigte Siedlung der Nachtelfen im Eschental. Eliteschildwachen und Krieger bewachen ihn und beobachten die Bewegungen der Horde entlang der Waldpfade.",al={"außenposten der silberschwingen","was ist silverwing"}},{q="Wer ist Duriel Moonfire?",a="Duriel Moonfire befehligt die Nachtelfen, die den Außenposten der Silberschwingen verteidigen. Sie führt seine Schildwachen gegen Angriffe der Horde, bis Toreks Räuber in das Lager eindringen und sie niederstrecken.",al={"duriel moonfire","duriel"}},{q="Wer ist Ertog Ragetusk?",a="Ertog Ragetusk ist ein Offizier der Horde am Splitterholzposten. Er ist Toreks Vorgesetzter, beaufsichtigt die Militäroperationen in der Region und nimmt Berichte über Siege gegen die Allianz entgegen.",al={"ertog ragetusk","ertog"}},{q="Warum greift die Horde den Außenposten der Silberschwingen an?",a="Die Horde und die Nachtelfen kämpfen überall im Eschental um Gebiete. Mit dem Angriff auf den Außenposten der Silberschwingen entlastet die Horde ihre Nachschubwege und schwächt die Verteidigungsstellungen der Schildwachen, die das Waldinnere schützen.",al={"warum silverwing angreifen","eschental konflikt silverwing"}},{q="Wo findet dieser Angriff statt?",a="Der Angriff beginnt direkt vor dem Außenposten der Silberschwingen, auf der von der Horde gehaltenen Ostseite des Falfarren im Eschental. Er endet im Lager der Nachtelfen.",al={"toreks angriff ort","wo ist torek"}}},fx={["6e6dcd55"]={q="Warum benötigt Torek meine Hilfe für den Angriff?",a="Torek befehligt bereits einen Trupp Plünderer des Splitterholzpostens, aber seine Späher berichten, dass der Außenposten der Silberschwingen schwer von erfahrenen Nachtelfen-Wächterinnen und Kriegern befestigt ist. Da er weiß, dass die Verteidiger nicht leicht nachgeben werden, begrüßt er einen kampffähigen Champion, um ihre Frontlinie zu verstärken und sicherzustellen, dass der Schlag gegen Duriel Moonfire in einem entscheidenden Sieg der Horde endet.",al={"warum braucht torek mich","warum rekrutiert torek spieler","warum torek helfen"}}},fp="15,215,25.343.0,17.299.0,13.152.0,27.159.0,23.179.1,22.179.0,45.210.0,34.159.0"}
P.entries["quest:6545"] = {n="Aktualisierter Bericht des Läufers des Kriegshymnenklans",s="Aktualisierter Bericht des Läufers des Kriegshymnenklans warnt vor wachsendem Druck auf die Grenze des Kriegshymnenklans im gesamten Eschental. Der Bericht macht die Befehlshaber auf immer kühnere Angriffe der Naga auf Außenposten der Horde aufmerksam.",h="Aktualisierter Bericht des Läufers des Kriegshymnenklans warnt vor wachsendem Druck auf die Grenze des...",kw={"eschental","kadrak","mor'shan","naga","schutzwall","bericht","läufer","späher","kriegshymnen"},ang={["faction:Horde"]="An der Waldgrenze zählt jeder Soldat. Eine offene Verbindung zwischen dem Brachland und den vorgeschobenen Außenposten ist überlebenswichtig.",["race:Orc"]="Als Ork wisst Ihr, dass der Kriegshymnenklan auf die Zähigkeit und Wachsamkeit seiner Läufer angewiesen ist, um unter Kriegshäuptling Thralls Befehl beanspruchtes Land zu halten."},sec={{t="Depeschen von der Front",b="Im gesamten Eschental beobachten Späher und Läufer des Kriegshymnenklans die Kämpfe und halten die Nachschublinien offen. Schildwachen der Nachtelfen und der Wald machen ihre Arbeit gefährlich, weshalb die Befehlshaber an der Grenze rasch Nachrichten brauchen. Kuriere bringen Depeschen zu abgelegenen Garnisonen und zu Befehlshabern wie Kadrak am Mor'shan-Schutzwall."},{t="Die Bedrohung der Naga",b="Die Verteidiger der Horde rechnen mit Nachtelfen zwischen den Bäumen, doch die Wachen der Außenposten melden kühnere Angriffe der Naga. Die schlangenartigen Eindringlinge schlagen von Wasserwegen und uralten Ruinen aus zu, erproben die Barrikaden und ziehen Verteidiger von Wald- und Grenzpatrouillen ab. Eine Depesche an den Mor'shan-Schutzwall warnt vor diesen koordinierten Angriffen vom Wasser aus."}},faq={{q="An wen wird der Bericht geschickt?",a="Der Bericht wird an Kadrak geschickt, einen Aufseher am Mor'shan-Schutzwall zwischen dem Eschental und dem nördlichen Brachland.",al={"wer erhält den bericht","kadrak bericht","wohin geht der bericht"}},{q="Welche Bedrohungen erwähnt der aktualisierte Bericht?",a="Der Späher meldet wiederholte Angriffe auf den örtlichen Außenposten und eine wachsende Bedrohung durch feindliche Naga in den nahen Gewässern.",al={"was steht im bericht","aktualisierter läuferbericht inhalt","angriffe der naga"}},{q="Warum verlässt sich die Horde hier auf Läufer?",a="Dichtes Laubwerk, Scharfschützen der Nachtelfen und abgelegene Außenposten machen das Fliegen in Teilen des Eschentals schwierig oder gefährlich. Läufer überbringen Nachrichten schnell und unauffällig auf bewachten Wegen.",al={"warum läufer","läufer des kriegshymnenklans hintergrund","warum keine wyvern"}},{q="Wer sind die Läufer des Kriegshymnenklans?",a="Die Läufer des Kriegshymnenklans sind Späher, Kuriere und Vorhutkämpfer des Klans. Sie sichern die Nachschublinien und beobachten feindliche Bewegungen entlang der umkämpften Grenzen des Waldes.",al={"kriegshymnenklan eschental","wer sind die läufer des kriegshymnenklans"}},{q="Wo greifen die Naga im Eschental an?",a="Die Naga greifen von Stützpunkten in Ruinen entlang der Küsten und Seen des Eschentals aus an. Sie lauern Reisenden auf und überfallen nahe gelegene Lager.",al={"wo sind die naga","eschental naga"}},{q="Welchem Zweck dient der Außenposten in diesem Gebiet?",a="Der Außenposten warnt vor Gefahren und bildet einen Stützpunkt der Verteidigung. Er sichert die Verbindung zwischen den Holzfällerbetrieben tief im Wald und dem Brachland.",al={"warum ist der außenposten hier","hordenlager zweck"}}},fx={["3fdffadb"]={q="Warum muss der Läufer des Kriegshymnenklans diesen Bericht überbringen lassen?",a="Der Außenposten steht unter wachsendem Druck durch kürzliche Angriffe der Naga, und das Kommando benötigt ein genaues Bild der Frontlinien. Der Läufer hat Wache gestanden und mehrere Wellen von Angreifern zurückgeschlagen, aber Kadrak zurück am Mor'shan-Schutzwall muss verstehen, wie gefährlich die Situation geworden ist, damit die Horde ihre Verteidigungen über das gesamte Eschental koordinieren kann.",al={"warum bericht senden","motiv des läufers","warum warsongbericht zustellen"}},ae645a70={q="Wofür ist der Warsongbericht?",a="Der Warsongbericht enthält wichtige Feldinformationen, die die eskalierenden Einfälle der Naga gegen den Außenposten beschreiben. Ihn zurückzubringen, informiert Kadrak über aktuelle Frontverteidigungen und Truppenbedarf und stellt sicher, dass die Führung der Horde über die neuesten Bedrohungen der Region informiert bleibt.",al={"zweck des warsongberichts","was ist warsongbericht","was sagt der bericht"}},["0f7ad725"]={q="Warum bittet der Läufer Euch, die Aktualisierung zu überbringen, anstatt selbst zu gehen?",a="Die Garnison des Außenpostens ist überlastet, während sie aktiv Einfälle der Naga zurückschlägt. Als kampffähiger Kurier, der ohnehin zwischen den Frontstationen reist, ermöglicht Ihr es den lokalen Verteidigern, auf ihren Posten zu bleiben, anstatt die Schutzwälle zu verlassen, um Pergament an die Grenze des Brachlands zu tragen.",al={"warum ich warsongläufer","warum nicht selbst zustellen","warum braucht der läufer euch"}}},fp="21,178,20.299.0,15.325.0,32.115.0,41.113.0,45.185.0,28.168.0,42.118.0,43.139.0"}
P.entries["quest:6546"] = {n="Aktualisierter Bericht der Vorhut des Kriegshymnenklans",s="Im östlichen Eschental kündet der Aktualisierte Bericht der Vorhut des Kriegshymnenklans von Gefahren, die die Horde bedrängen. Sein Bericht nennt Streitkräfte der Allianz, im Wald verschanzte Satyren und Naga, die durch das benachbarte Azshara ziehen.",h="Im östlichen Eschental kündet der Aktualisierte Bericht der Vorhut des Kriegshymnenklans von Gefahren, die...",kw={"eschental","azshara","kadrak","der mor'shan-schutzwall","naga","satyren","vorhut des kriegshymnenklans","bericht des kriegshymnenklans"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass jede Meldung entlang der Mor'shan-Linie für den unsicheren Brückenkopf der Horde in den Wäldern des Eschentals zählt.",["race:Orc"]="Als Ork wisst Ihr, dass der Kriegshymnenklan stolz darauf ist, die Vorhut zu stellen. Seine Späher wissen auch, dass Tapferkeit allein keine Feinde aufhalten kann, die von allen Seiten näher rücken."},sec={{t="Augen am Waldrand",b="Eine einzelne Vorhut des Kriegshymnenklans wacht über den umkämpften Ostrand des Eschentals. Die Nachschublinien der Horde werden ständig angegriffen, weshalb Vorreiter feindliche Bewegungen verfolgen, bevor Überfallkommandos den Mor'shan-Schutzwall oder den Splitterholzposten angreifen können. Begegnet Ihr einem von ihnen auf Patrouille, wisst Ihr, dass der Wald überwacht wird. Sein Bericht kann darüber entscheiden, ob eine Befestigung der Horde standhält oder durch einen Hinterhalt fällt."},{t="Gefahren an jedem Horizont",b="Der Bericht einer Vorhut des Kriegshymnenklans kündet von Gefahren in den zentralen Wäldern Kalimdors. Nachtelfen und die Allianz insgesamt bleiben eine Bedrohung, während gerissene, dämonische Satyren das östliche Eschental heimsuchen. Späher haben zudem eine gewaltige Präsenz von Naga entdeckt, die sich über die verfallenen Küstengebiete des benachbarten Azshara ausbreitet. Die Horde sieht sich aus fast jeder Richtung feindlichen Mächten gegenüber."}},faq={{q="Was ist der Bericht des Kriegshymnenklans?",a="Der Bericht des Kriegshymnenklans ist eine Aufklärungsmeldung einer Vorhut des Kriegshymnenklans über feindliche Stellungen und Gefahren in der Region. Er nennt nahe Streitkräfte der Allianz, aktive Satyrzirkel im östlichen Eschental und neu entdeckte Bewegungen der Naga in ganz Azshara.",al={"bericht des kriegshymnenklans questgegenstand","was steht im bericht","späherbericht"}},{q="Wer ist Kadrak?",a="Kadrak ist ein Kommandant der Horde am Mor'shan-Schutzwall, der Verteidigungsbarrikade, die die nördliche Grenze zwischen dem Brachland und dem Eschental bewacht. Er beaufsichtigt eintreffende Späher und koordiniert Vorstöße in den Wald.",al={"wer ist kadrak","wo ist kadrak","bei kadrak abgeben"}},{q="Warum werden die Naga in Azshara erwähnt?",a="Azshara grenzt an das östliche Eschental, und die Bewegungen der Naga dort könnten die Flanke der Horde bedrohen. Vorreiter beobachten die benachbarten Gebiete, damit die Horde im Kampf gegen die Nachtelfen nicht von einem massiven Einfall überrascht wird.",al={"verbindung zwischen naga und azshara","warum wird azshara erwähnt","bedrohung durch naga in azshara"}},{q="Was macht das östliche Eschental für die Horde so gefährlich?",a="Im östlichen Eschental trifft die Horde auf aktive Truppenverbände der Allianz, uralte Ruinen voller dämonischer Verderbnis und Satyren sowie ungezähmte Waldtiere. Boten und Patrouillen drohen Hinterhalte aus jeder Richtung.",al={"warum ist das östliche eschental gefährlich","bedrohungen im eschental","bedrohung durch satyren"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Die Vorhut des Kriegshymnenklans bildet die vorderste Linie und die berittene Aufklärung des Kriegshymnenklans im Eschental. Ihre Mitglieder verfolgen die Bewegungen der Nachtelfen, schirmen Holzfällerlager ab und sichern Handelswege.",al={"was sind vorreiter","späher des kriegshymnenklans","geschichte der vorreiter"}},{q="Warum kann der Vorreiter den Bericht nicht selbst überbringen?",a="Der Vorreiter muss den Pfad beobachten und feindliche Bewegungen verfolgen, sobald sie sich abzeichnen. Verlässt er seinen Beobachtungsposten, könnte den Truppen an der Front ein unerwarteter Vorstoß der Allianz oder der Satyren entgehen.",al={"warum überbringe ich den bericht","warum überbringt er ihn nicht selbst"}}},fx={["43097ba7"]={q="Warum muss die Vorhut des Kriegshymnenklans diesen Bericht überbringen lassen?",a="Die Horde steht an jeder Front im östlichen Eschental vor Bedrohungen. Mit der Allianz in der Nähe, Satyrn, die die Wälder verderben, und Naga, die im Grenzgebiet von Azshara Territorium besetzen, benötigt Kadrak sofortige Informationen über feindliche Bewegungen. Die Zustellung dieses Berichts stellt sicher, dass die Kommandeure der Außenposten die regionalen Gefahren verstehen und verwundbare Positionen verstärken können, bevor Feinde zuschlagen.",al={"warum bericht senden","motiv der warsongvorhut","warum aktualisierung zustellen"}}},fp="23,211,26.359.0,24.362.0,27.246.0,14.226.0,38.207.0,56.206.0,30.182.0,50.176.0"}
P.entries["quest:6547"] = {n="Aktualisierter Bericht des Spähers des Kriegshymnenklans",s="Kadraks Befehle erreichen den Aktualisierten Bericht des Spähers des Kriegshymnenklans, während Späher die umkämpften Wälder überwachen. Die Horde verlässt sich auf ihre Berichte, um ihre Stellungen im Eschental vor Angriffen der Nachtelfen zu schützen.",h="Kadraks Befehle erreichen den Aktualisierten Bericht des Spähers des Kriegshymnenklans, während Späher die...",kw={"eschental","brachland","kadrak","nachtelfen","bericht","späher","schildwachen","warsong"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, ihren Stützpunkt im Eschental zu sichern, indem Ihr Kadraks Befehle zu den äußeren Spähern bringt, denen Nachtelfenhinterhalte drohen.",["race:NightElf"]="Als Nachtelf seht Ihr in den Spähern des Kriegshymnenklans an den Grenzen eine fortwährende Entweihung von Elunes heiligen Wäldern. Die Schildwachen bemühen sich, sie zu vertreiben.",["race:Orc"]="Als Ork erbt Ihr den Kampf des Kriegshymnenklans um das Holz des Eschentals, gegen das Land und seine uralten Verteidiger."},sec={{t="Augen in den Schatten",b="Kadrak verlässt sich auf verstreute Späher des Kriegshymnenklans, um die Grenze des Eschentals zu überwachen. Nachtelfische Schildwachen nutzen den Wald als Deckung, und die Späher laufen Gefahr, abgeschnitten zu werden. Kuriere tragen schriftliche Lageberichte zwischen ihnen hin und her und halten so abgelegene Außenposten mit der Hordeführung verbunden, damit sie ihre Beobachtungen melden können."},{t="Die Stellung halten",b="Späher des Kriegshymnenklans halten Ausschau nach Überfällen der Nachtelfen, die den Wald zurückerobern wollen. Der Klan hat für jeden gerodeten oder besetzten Landstrich im Eschental mit Leben bezahlt. Kadraks Befehle halten vorgeschobene Späher mit der Horde in Verbindung und ermöglichen ihnen zu melden, ob ihre Verteidigung dem elfischen Widerstand standhält."}},faq={{q="Wer ist Kadrak?",a="Kadrak befehligt die Streitkräfte der Horde entlang der Grenze zwischen dem Brachland und dem Eschental. Er koordiniert Aufklärung, Grenzverteidigung und Nachschub für die Einsätze des Kriegshymnenklans im Wald.",al={"kadrak","wer ist kadrak","kadraks rolle"}},{q="Warum sind die Späher des Kriegshymnenklans wegen der Nachtelfen so paranoid?",a="Nachtelfen wissen, wie sie sich in den Wäldern ihrer Ahnen verbergen und Patrouillen der Horde überraschen können. Der Kriegshymnenklan fällt Bäume und besiedelt Land, das den Elfen heilig ist, wodurch seine Späher plötzlichen Angriffen ausgesetzt sind.",al={"warum nachtelfen fürchten","nachtelfen in den schatten","späher des kriegshymnenklans elfische gefahr"}},{q="Warum wird um das Eschental gekämpft?",a="Die Horde braucht das Holz und andere Ressourcen des Eschentals, um Orgrimmar zu errichten und Siedlungen im Brachland und in Durotar zu versorgen. Die Nachtelfen betrachten den Wald als heilig und kämpfen dafür, die orkischen Holzfäller und Garnisonen zu vertreiben.",al={"warum um das eschental kämpfen","krieg im eschental","horde konflikt im eschental"}},{q="Welche Rolle spielt der Kriegshymnenklan hier?",a="Der Kriegshymnenklan führt die Bemühungen der Horde an, die Ressourcen des Eschentals zu beanspruchen. Grom Hellscream führte den Klan während des Dritten Krieges in die Wälder. Seine Angehörigen halten ihre Stellungen, betreiben Holzfällerlager und kämpfen gegen die Schildwachen.",al={"kriegshymnenklan eschental","warsong rolle"}},{q="Wohin geht dieser Bericht, nachdem er den Späher erreicht hat?",a="Nachdem der Späher Kadraks Anweisungen erhalten hat, berichtet er von örtlichen Erfolgen gegen elfische Gegenangriffe. So bleiben die Anführer der Horde über die Lage an der Front informiert.",al={"wer erhält den bericht","kadraks bericht","ergebnis des späherberichts"}},{q="Haben die Pläne der Horde im Eschental zu diesem Zeitpunkt Erfolg?",a="Die Späher an der Front glauben, dass ihre Verteidigung standhält. Sie halten ihre befestigten Stellungen und wehren elfische Angriffe ab, doch das Eschental bleibt heftig umkämpft und keine Seite hat die vollständige Kontrolle.",al={"gewinnt die horde im eschental","warsong fortschritt"}}},fx={aadbe711={q="Warum möchte der Späher des Kriegshymnenklans, dass dies erledigt wird?",a="Späher des Kriegshymnenklans patrouillieren tief im feindlichen Gebiet des Eschentals, umgeben von Nachtelfen, die in den Schatten lauern. Der Späher benötigt neue Befehle von Kadrak, um die Verteidigung an der Front zu koordinieren, den hart erkämpften Stützpunkt im Wald zu halten und mitzuteilen, ob ihre Bemühungen, die Elfen zurückzudrängen, erfolgreich sind.",al={"motivation warsongspäher","warum bericht überbringen","warum braucht der späher befehle"}},ae4f0954={q="Wozu dient der Warsongbericht?",a="Der Warsongbericht enthält strategische Anweisungen und Truppenaufstellungen, die von Kadrak vom Mor'shan-Schutzwall aus versandt wurden. Für Späher, die isolierte Außenposten im Eschental halten, stellt der Erhalt dieses Berichts sicher, dass sie über die taktischen Manöver der Horde auf dem Laufenden bleiben, während sie die Ansprüche des Clans gegen lauernde Kräfte der Nachtelfen verteidigen.",al={"zweck warsongbericht","was bewirkt der warsongbericht","hintergrund warsongbericht"}},f7519c0a={q="Warum benötigt Kadrak einen Abenteurer, um den Bericht zu überbringen?",a="Die Grenze zwischen dem Brachland und dem Eschental ist voller Hinterhalte. Die am Mor'shan-Schutzwall stationierten Grunz und Wachen können ihre Stellungen nicht ohne Weiteres verlassen, ohne die Verteidigung des Außenpostens zu gefährden. Daher ist ein unabhängiger Reisender ein idealer Kurier, um durch die Wälder zu schlüpfen und vertrauliche militärische Anweisungen an isolierte Späher zu überbringen.",al={"warum soll ich den warsongbericht überbringen","warum können die wachen ihn nicht ausliefern","warum ich warsongspäher"}}},fp="20,173,19.283.0,18.292.0,14.174.0,57.200.0,35.224.0,37.208.0,51.165.0,60.196.0"}
P.entries["quest:6548"] = {n="Rächt mein Dorf",s="Makaba Flachhuf ruft Reisende der Horde auf, den Angriff der Grimtotem im südöstlichen Steinkrallengebirge zu vergelten. Er entkam nur knapp, abgeschnitten von seiner Sippe und umringt von den Toten. Nun sucht er Vergeltung im Lager der Raufbolde und angeheuerten Söldner.",h="Makaba Flachhuf ruft Reisende der Horde auf, den Angriff der Grimtotem im südöstlichen Steinkrallengebirge zu...",kw={"rächt mein dorf","grimtotem","söldner der grimtotem","raufbold der grimtotem","grundig darkcloud","makaba flachhuf","steinkrallengebirge"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr auf offene, sichere Pässe zwischen dem Brachland und dem Steinkrallengebirge angewiesen. Eine abtrünnige Bande der Grimtotem, die Reisende und verbündete Dorfbewohner tötet, bedroht die Nachschubwege des Kriegshäuptlings durch die Berge.",["race:Tauren"]="Als Tauren seht Ihr, wie der Verrat der Grimtotem die Kluft unter den Shu'halo vertieft. Dass sie ihresgleichen abschlachten, zeigt, welche Gefahr sie für Cairnes vereintes Volk darstellen."},sec={{t="Blut in den Felsen",b="Nahe der Grenze zum Brachland ist Makaba Flachhuf der einzige Überlebende eines Massakers in den roten Felspässen des Steinkrallengebirges. Räuber der Grimtotem schlugen ohne Vorwarnung zu und schlachteten nahezu alle in seiner Siedlung ab. Makaba wehrte sich und streckte mehrere Angreifer nieder. Dann zwangen sie ihn, sich zu verstecken, mit kaum mehr als seinem Leben und seinem Zorn."},{t="Die Bedrohung der Grimtotem",b="Die Grimtotem bedrängen seit Langem die Taurenstämme, die unter Oberhäuptling Cairne Bluthuf vereint sind. Anders als die friedlichen Nomaden Mulg ores setzen ihre Kriegstrupps skrupellose Raufbolde und opportunistische Söldner ein, um Gebiete zu erobern und abgelegene Siedlungen anzugreifen. Makaba denkt nun weder an Diplomatie noch an Stammesbande. Nur Blut, mit Blut vergolten, kann seiner Trauer gerecht werden."}},faq={{q="Wer hat diese Quest vergeben?",a="Makaba Flachhuf ist ein überlebender Tauren, der nahe dem südöstlichen Pass ins Steinkrallengebirge lagert. Der Grimtotemklan hat sein nahe gelegenes Dorf verwüstet, und er sucht Vergeltung an den Räubern.",al={"questgeber","makaba flachhuf","wer ist makaba"}},{q="Warum greifen die Grimtotem andere Tauren an?",a="Der Grimtotemklan lehnt die Einheit unter der Horde und Cairne Bluthufs Friedensvision ab. Er verteidigt seine Gebietsansprüche erbittert, ist fremdenfeindlich und aggressiv, überfällt rivalisierende Siedlungen, tötet Außenstehende und setzt bewaffnete Schläger und angeheuerte Söldner ein, um Regionen wie das Steinkrallengebirge zu beanspruchen.",al={"warum sind grimtotem feindselig","tauren greifen tauren an","geschichte des grimtotemklans"}},{q="Wo befinden sich die Angreifer der Grimtotem?",a="Die Raufbolde und Söldner der Grimtotem lagern im südöstlichen Steinkrallengebirge direkt westlich von Makaba Flachhuf, zwischen felsigen Hügeln über dem Pass.",al={"wo sind die gegner","standort des grimtotemlagers","wo sind die raufbolde"}},{q="Wer sind die Grimtotem Mercenaries?",a="Der Grimtotemklan heuert skrupellose Kämpfer und Söldner an, um seine Kriegstrupps zu verstärken und abgelegene Siedlungen zu terrorisieren und zu überrennen.",al={"mercenaries","söldner der grimtotem","wer sind die söldner"}},{q="Was geschieht nach dieser Quest?",a="Nachdem Ihr die Raufbolde und Söldner an vorderster Front niedergestreckt habt, bittet Makaba Euch, den Anführer hinter dem Massaker anzugreifen, Grundig Darkcloud.",al={"nächste quest","was folgt auf rächt mein dorf","kill grundig darkcloud"}},{q="Wo lag Makabas Dorf?",a="Makabas Siedlung war ein abgelegenes Taurenlager nahe den Grenzpässen im südöstlichen Steinkrallengebirge. Der Überfall der Grimtotem löschte es aus, und Makaba blieb als einer der wenigen bekannten Überlebenden zurück.",al={"flachhufs dorf","wo lag das dorf","welches dorf wurde zerstört"}}},fx={ee147ee3={q="Warum will Makaba Flachhuf, dass die Grimtotem getötet werden?",a="Makaba Flachhuf sucht Rache, nachdem der Grimtotemstamm einen brutalen Überfall auf sein Dorf gestartet und fast jeden, der dort lebte, abgeschlachtet hat. Nachdem er seine Heimat und sein Volk verloren hat, treibt ihn jetzt nur noch Vergeltung gegen den Stamm an, der seine Familie und Nachbarn massakriert hat.",al={"motiv von makaba flachhuf","warum dorf rächen","warum will makaba rache"}},["2ec07636"]={q="Wer sind die Grimtotem, die dieses Gebiet ins Visier nehmen?",a="Ihr werdet gegen die Grimtotem-Raudaus und Mercenaries ausgesandt, die im Westen kampieren. Die Grimtotem sind ein aggressiver, isolationistischer Taurenstamm, der für seine Feindseligkeit gegenüber anderen Stämmen und der Horde gleichermaßen bekannt ist und lokale Siedlungen überfällt, um seinen Halt im Steinkrallengebirge auszubauen.",al={"grimtotem-raudaus und mercenaries","wen sollt ihr töten","wer griff makabas dorf an"}},bd5303e7={q="Warum benötigt Makaba Flachhuf Eure Hilfe?",a="Makaba kämpfte während des Überfalls verzweifelt und tötete so viele Grimtotem, wie er konnte, aber er entkam kaum mit dem eigenen Leben. Verwundet, isoliert und ohne Verbündete oder Dorfwachen, um sie zu versammeln, kann er sich den verbliebenen Plünderern nicht alleine stellen.",al={"warum kann makaba nicht kämpfen","warum mich fragen","warum braucht makaba hilfe"}}},fp="17,241,18.334.0,20.358.0,20.193.0,45.262.0,42.140.0,34.132.0,30.138.1,35.187.0"}
P.entries["quest:655"] = {n="Hammerfall",s="In Hammerfall hält die Horde ein Lager, das Kriegshäuptling Orgrim Schicksalshammer das Leben kostete. Gor'mul erinnert sich an die Flucht der Gefangenen und daran, warum die Festung ihren Namen trägt.",h="In Hammerfall hält die Horde ein Lager, das Kriegshäuptling Orgrim Schicksalshammer das Leben kostete.",kw={"arathihochland","schicksalshammer","gor'mul","hammerfall","internierungslager","orgrim schicksalshammer","thrall","tor'gan"},ang={["class:Warrior"]="Als Krieger könnt Ihr Orgrim Schicksalshammer als legendären Kämpfer in Erinnerung behalten. Der Boden, auf dem er fiel, trägt die Last jener Schlacht.",["faction:Horde"]="Für die Horde erinnert Hammerfall an die Befreiung der orcischen Internierungslager und das Opfer von Kriegshäuptling Orgrim Schicksalshammer.",["race:Orc"]="Für Orcs bleibt Schicksalshammers Fall in Arathi einer der schmerzlichsten Momente der Geschichte. Er markierte das Ende einer Ära und den Aufstieg von Thralls neuer Horde."},sec={{t="Blut und zerbrochene Ketten",b="Im Arathihochland hielt die Allianz einst Orcs hinter Holz und Stahl gefangen. Der junge Thrall und Kriegshäuptling Orgrim Schicksalshammer führten einen Angriff auf die Umzäunungen des Lagers an und befreiten die Ihren. Viele Gefangene entkamen, als die Verteidigung fiel. Dann traf eine Lanze von einem Reiter Schicksalshammer von hinten. Er starb dort, wo heute Hammerfall steht."},{t="Der bleibende Schatten der Niederlage",b="Gor'mul gehörte zu jenen, die an diesem Tag nicht die Freiheit fanden. Im Chaos der Schlacht und unter den Erschütterungen der Erde sah er den Kriegshäuptling fallen und verlor den Willen zu kämpfen. Seine Brüder flohen und ließen ihn zurück. Jahrelang wanderte Gor'mul voller Trauer durch das Hochland. Die Horde hat den Ort als befestigten Stützpunkt zurückerobert, doch die Überlebenden tragen noch immer die Erinnerung an Schicksalshammers Tod in sich."}},faq={{q="Wer ist Gor'mul?",a="Gor'mul war ein gefangener Orc in dem Internierungslager, an dessen Stelle heute Hammerfall steht. Thrall und Schicksalshammer führten einen Angriff zur Befreiung der Gefangenen an, doch Gor'mul wurde bei der Flucht zurückgelassen. Jahrelang wanderte er allein und verzweifelt umher.",al={"wer ist gormul","gor mul hintergrundgeschichte","was geschah mit gormul"}},{q="Wie starb Orgrim Schicksalshammer?",a="Orgrim Schicksalshammer starb in der Schlacht zur Befreiung des Internierungslagers in Arathi. Ein berittener Ritter der Allianz traf ihn von hinten mit einer Lanze.",al={"wie starb schicksalshammer","wer tötete schicksalshammer","geschichte von schicksalshammers tod"}},{q="Warum heißt der Außenposten Hammerfall?",a="Hammerfall trägt seinen Namen nach Kriegshäuptling Orgrim Schicksalshammer, der dort fiel, als er sein Volk aus menschlicher Gefangenschaft befreite. Die Horde kehrte in das zerstörte Lager zurück und machte es zu einem dauerhaften Stützpunkt.",al={"warum heißt es hammerfall","ursprung des namens hammerfall","hammerfall geschichte"}},{q="Wer ist Tor'gan?",a="Tor'gan ist ein Vertreter der Horde, der in Hammerfall stationiert ist. Er kümmert sich mit um das Lager und versteht die anhaltenden seelischen Wunden ehemaliger Gefangener wie Gor'mul.",al={"wer ist tor'gan","torgan hammerfall","torgan quest"}},{q="Nahm Thrall an der Schlacht hier teil?",a="Ja. Thrall kämpfte an der Seite von Kriegshäuptling Orgrim Schicksalshammer beim Angriff auf das Internierungslager in Arathi. Sie durchbrachen die Verteidigung und befreiten gefangene Orcs, doch Schicksalshammer starb in der Schlacht.",al={"thrall und schicksalshammer arathi","befreiung von hammerfall","kämpfte thrall bei hammerfall"}},{q="Warum ist Gor'mul so niedergeschlagen?",a="Gor'mul sah Schicksalshammer fallen, und dieser Anblick brach seinen Kampfgeist. Als die anderen Gefangenen in die Wildnis flohen, blieb Gor'mul zurück und wanderte hoffnungslos umher, bis die Horde zurückkehrte, um Hammerfall zu errichten.",al={"warum ist gormul so traurig","gormul depression","warum verlor gormul die hoffnung"}}},fp="10,169,23.321.0,30.367.0,15.224.0,30.141.0,36.186.0,15.161.0,40.181.0,29.212.0"}
P.entries["quest:65593"] = {n="Hearts of the Lovers",s="Carendin Halgar sucht die Herzen von Avelina Lilly und Isaac Pearson, um einen Inkubus anzulocken. Ihre Sehnsucht nacheinander macht sie zu einem besonders wirksamen Köder.",h="Carendin Halgar sucht die Herzen von Avelina Lilly und Isaac Pearson, um einen Inkubus anzulocken.",kw={"mühlenbern","avelina lilly","carendin halgar","herzen der liebenden","inkubus","isaac pearson","liebende","ratschet"},sec={{t="Die Wahl der Weissagung",b="Carendin Halgar sucht zwei Herzen für seine Arbeit im Temple of the Damned. Seine Weissagung weist auf Avelina Lilly in Mühlenbern und Isaac Pearson in Ratschet hin. Avelina dient den gefallenen Magiern mit ihrer Schneiderkunst, während Isaac hofft, sich in der Küstenstadt einen Namen zu machen. Obwohl sie weit voneinander entfernt schuften, sehnt sich jeder nach dem anderen. Carendin bittet Euch, ihm ihre Herzen als Köder für einen Inkubus zu bringen."},{t="Die Herzen",b="Carendin erhält die Herzen von Avelina Lilly und Isaac Pearson. Er hält eines in jeder Hand und führt sie behutsam zusammen, dann nennt er die Liebenden Idioten."}},faq={{q="Wer sind Avelina Lilly und Isaac Pearson?",a="Avelina Lilly bietet den gefallenen Magiern in Mühlenbern Schneiderdienste an, und Isaac Pearson hofft, sich in Ratschet einen Namen zu machen. Ihre Herzen sehnen sich nacheinander.",al={"avelina und isaac","wer sind die liebenden"}},{q="Warum will Carendin ihre Herzen?",a="Carendin sagt, dass ein Inkubus von den Herzen Liebender angezogen wird und dass die tiefste Sehnsucht den stärksten Köder ergibt.",al={"inkubus herzen","warum herzen"}},{q="Wo sind die beiden Liebenden?",a="Avelina Lilly ist in Mühlenbern im Silberwald, während Isaac Pearson in Ratschet im Brachland ist.",al={"wo ist avelina","wo ist isaac"}},{q="Wer ist Carendin Halgar?",a="Carendin Halgar ist im Temple of the Damned, wo er Euch bittet, ihm die Herzen von Avelina und Isaac zu bringen.",al={"carendin","temple of the damned"}}},fp="20,155,18.387.0,10.153.1,40.165.0,36.107.0,25.101.0,23.106.0"}
P.entries["quest:65597"] = {n="The Binding",s="Carendin Halgar im Magieviertel von Unterstadt bittet Euch, mit den Lovers’ Hearts einen Inkubus zu beschwören und zu unterwerfen. Anschließend braucht er die Herzen zurück.",h="Carendin Halgar im Magieviertel von Unterstadt bittet Euch, mit den Lovers’ Hearts einen Inkubus zu...",kw={"carendin halgar","inkubus","lovers' hearts","magieviertel","beschwörung","the binding","unterstadt"},sec={{t="Eine Beschwörung in Unterstadt",b="Carendin Halgar bittet Euch im Magieviertel von Unterstadt um Hilfe. Mit den Lovers’ Hearts soll ein Inkubus beschworen und unterworfen werden, dann sollen sie ihm zurückgebracht werden. Bei Eurer Rückkehr bleiben die Herzen in Carendins Obhut."}},faq={{q="Wer bittet um Hilfe?",a="Carendin Halgar im Magieviertel von Unterstadt bittet Euch um Hilfe.",al={"wer will das","wer hat es gegeben","carendin halgar"}},{q="Wozu dienen die Lovers’ Hearts?",a="Ihr verwendet die Lovers’ Hearts, um einen Inkubus zu beschwören und zu unterwerfen.",al={"lovers hearts verwenden","was bewirken die herzen","herzen für inkubus"}},{q="Was geschieht nach der Beschwörung?",a="Ihr bringt die Lovers’ Hearts zu Carendin Halgar im Magieviertel zurück.",al={"wo herzen zurückbringen","lovers hearts zurückbringen","was als nächstes"}}},fp="11,160,28.226.0,23.72.0,34.61.0,33.72.0"}
P.entries["quest:656"] = {n="Beschwören der Prinzessin",s="Bei den Shards of Myzrael beschwört Ihr Myzrael und stellt Euch ihr, bevor sie stark genug wird, jene herauszufordern, die sie gefangen halten. Theldurin der Verirrte will, dass sie besiegt und ihre Geisterhaften Fesseln an die Shards gebunden werden.",h="Bei den Shards of Myzrael beschwört Ihr Myzrael und stellt Euch ihr, bevor sie stark genug wird, jene...",kw={"arathihochland","geisterhafte fesseln","myzrael","rolle von myzrael","shards of myzrael","theldurin der verirrte"},sec={{t="Warum sie aufgehalten werden muss",b="Theldurin fürchtet, Myzrael könnte stark genug werden, sich gegen jene zu wenden, die sie gefangen halten. Manche sagen, sie lasse sich kontrollieren. Doch Theldurin fragt, warum die Riesen sie dann angekettet hätten, wenn das wahr wäre."},{t="Bei den Shards",b="Ihr bringt die Rolle von Myzrael zu den Shards, wo Ihr zum ersten Mal mit ihr gesprochen habt, und ruft sie herbei. Sobald Myzrael besiegt ist, bindet Ihr ihre Geisterhaften Fesseln an die Shards und sperrt sie erneut ein."},{t="Wenn die Fesseln liegen",b="Als sich Myzraels Fesseln um die Shards legen, steigt aus großer Tiefe ein Wehklagen empor, dann ein Brüllen. Die Shards bieten keine Wärme oder Sicherheit mehr. Sie pulsieren voller Bedrohung, als hege das Wesen unter ihnen Groll gegen die Oberfläche."}},faq={{q="Wer schickt Euch in den Kampf gegen Myzrael?",a="Theldurin der Verirrte schickt Euch los, um Myzrael zu besiegen, bevor sie stark genug wird, jene herauszufordern, die sie gefangen halten.",al={"questgeber","wer vergibt beschwören der prinzessin","theldurins quest"}},{q="Wo findet die Beschwörung statt?",a="Ihr beschwört Myzrael bei den Shards of Myzrael, wo Ihr zum ersten Mal mit ihr gesprochen habt.",al={"wo myzrael beschwören","standort der shards of myzrael","beschwörungsort"}},{q="Warum will Theldurin Myzrael besiegt sehen?",a="Theldurin fürchtet, Myzrael könnte stark genug werden, jene herauszufordern, die sie gefangen halten. Er fragt, warum die Riesen sie angekettet haben, wenn sie sich wirklich kontrollieren ließe.",al={"warum myzrael töten","theldurins beweggründe","warum sie beschwören"}},{q="Wie wird Myzrael beschworen?",a="Ihr beschwört Myzrael bei den Shards of Myzrael mit der Rolle von Myzrael.",al={"wie sie beschwören","rolle von myzrael verwenden","beschwörungsablauf"}},{q="Was macht Ihr mit den Geisterhaften Fesseln?",a="Nachdem Ihr Myzrael besiegt habt, bindet Ihr ihre Geisterhaften Fesseln an die Shards und sperrt sie erneut ein.",al={"welcher gegenstand wird benötigt","geisterhafte fesseln","fesseln von myzrael"}}},fp="22,199,23.184.0,13.188.0,28.226.1,31.105.0,36.76.0,41.142.0,24.71.0,42.89.0"}
P.entries["quest:65601"] = {n="Love Hurts",s="Gan'rul schickt Euch Orgrimmars Hauptstraße entlang, um Magar zu finden. Seine Sehnsucht nach Krilge könnte auf den Gegenstand hinweisen, den Gan'rul braucht, um einen Inkubus in die Welt zu locken.",h="Gan'rul schickt Euch Orgrimmars Hauptstraße entlang, um Magar zu finden.",kw={"die kluft der schatten","gan'rul","inkubus","krilge","love hurts","magar","orgrimmar","sayaad"},sec={{t="Magars Suche",b="Östlich der Kluft der Schatten sehnt sich Magar nach Krilges Rückkehr. Er bittet Euch, nach etwas Wertvollem zu suchen. Bringt diesen Gegenstand zu Gan'rul, der ein Zeichen der Liebe und Hingabe braucht, um einen Inkubus zu beschwören."}},faq={{q="Wer ist Magar?",a="Magar lebt an Orgrimmars Hauptstraße und sehnt sich nach Krilges Rückkehr.",al={"wer ist magar"}},{q="Wer ist Krilge?",a="Krilge ist Magars Gefährte, und Magar sehnt sich nach Krilges Rückkehr.",al={"wer ist krilge","magars gefährte"}},{q="Was ist ein Inkubus?",a="Ein Inkubus ist ein männlicher Sayaad, abgrundtief böse und nur auf ein Ziel fixiert.",al={"inkubus bedeutung","männlicher sayaad"}},{q="Was braucht Gan'rul?",a="Gan'rul braucht einen Gegenstand, der große Liebe und Hingabe verkörpert, um einen Inkubus in die Welt zu locken.",al={"was braucht gan'rul","inkubus gegenstand"}},{q="Wo kann ich Magar finden?",a="Magar lebt östlich der Kluft der Schatten an Orgrimmars Hauptstraße.",al={"magar standort","wo ist magar"}}},fp="10,154,14.199.0,13.71.0,14.60.0,19.63.0,23.98.0,23.68.0"}
P.entries["quest:65602"] = {n="What Is Love?",s="Gakin der Dunkelbinder sucht eine Holzfigur, deren Alter und Geschichte sie für ein Inkubusritual geeignet machen. Ihre Hingabe könnte die Kreatur anlocken.",h="Gakin der Dunkelbinder sucht eine Holzfigur, deren Alter und Geschichte sie für ein Inkubusritual geeignet...",kw={"eschental","gakin der dunkelbinder","inkubus","maestras posten","ritual","sturmwind","was ist liebe","holzfigur"},sec={{t="Ein altes Andenken",b="Gakin der Dunkelbinder hat durch seine Hellsicht eine Figur aufgespürt. Er sagt, sie habe vor Tausenden von Jahren einem jungen Paar gehört, und ihre Besitzer seien fort. Ihr sollt das Andenken aus einem Haus jenseits von Maestras Posten im Eschental zu Gakin im Mage Quarter von Sturmwind bringen."},{t="Die Macht der Figur",b="Als Ihr die Holzfigur zurückbringt, spürt Gakin, dass ihre emotionale Kraft trotz der verstrichenen Zeit noch immer stark ist. Er sagt, der Inkubus werde davon angezogen, und damit sei sie das Reagenz, das er für das Ritual braucht."}},faq={{q="Was soll ich für Gakin finden?",a="Gakin bittet Euch, eine Holzfigur zu holen, die seiner Ansicht nach einen Inkubus zu seinem Ritual locken wird.",al={"welche figur","holzfigur","gakins gegenstand"}},{q="Wo ist die Figur?",a="Gakin sagt, sie sei in einem Haus jenseits von Maestras Posten im Eschental.",al={"fundort der figur","wo ist sie","haus im eschental"}},{q="Wem gehörte die Figur?",a="Die Figur gehörte vor Tausenden von Jahren einem jungen Paar.",al={"frühere besitzer","figur des paares","wer hatte sie"}},{q="Warum will Gakin die Figur?",a="Gakin spürt emotionale Energie in der Figur und sagt, sie werde einen Inkubus für sein Ritual anlocken.",al={"warum die figur","inkubusreagenz","wozu dient sie"}}},fp="13,143,15.275.0,20.201.1,32.97.0,22.63.0,23.63.0,33.97.0"}
P.entries["quest:65603"] = {n="The Binding",s="Gakin der Dunkelbinder lässt Euch in den Krypten eine Holzfigur verwenden und einem Inkubus gegenübertreten. Euer Erfolg entscheidet, ob er Euch lehren kann, den Dämon herbeizurufen.",h="Gakin der Dunkelbinder lässt Euch in den Krypten eine Holzfigur verwenden und einem Inkubus gegenübertreten.",kw={"krypten","gakin der dunkelbinder","inkubus","beschwörungsformel","sayaad","beschwörungskreis","the binding","holzfigur"},ang={["class:Warlock"]="Als Hexenmeister stellt Ihr Euch Gakins Prüfung, einen sayaad zu binden und eine Beschwörungsformel zu erlernen, mit der Ihr den Inkubus herbeiruft."},sec={{t="Eine Prüfung in den Krypten",b="Gakin der Dunkelbinder hat in den Krypten unter dem Slaughtered Lamb einen Beschwörungskreis vorbereitet. Ihr legt eine Holzfigur in dessen Mitte, um einem Inkubus, einem sayaad-Dämon, den Weg zu öffnen. Er könnte versuchen, Euch zu betören, doch Gakin warnt, dass jedes seiner Angebote falsch ist. Wenn Ihr versagt, steht Eure Seele auf dem Spiel."},{t="Die Lehre der Bindung",b="Nachdem Ihr den Inkubus bezwungen habt, lobt Gakin Euren unbeugsamen Willen. Er sagt, viele Hexenmeister, die versuchen, einen sayaad zu binden, enden als dessen nächste Mahlzeit. Dann lehrt er Euch die Beschwörungsformel, mit der Ihr den gebundenen Inkubus herbeiruft."}},faq={{q="Was soll ich tun?",a="Gakin bittet Euch, eine Holzfigur beim Beschwörungskreis in den Krypten zu verwenden, den Inkubus zu bezwingen und ihm die Figur zurückzubringen.",al={"was soll ich tun","aufgabe mit der figur","inkubus beschwören"}},{q="Wo befindet sich der Beschwörungskreis?",a="Gakin sagt, der Beschwörungskreis befindet sich in den Krypten unter dem Slaughtered Lamb.",al={"wo soll ich ihn beschwören","kreis in den krypten","unter dem lamb"}},{q="Was ist ein sayaad?",a="Ein sayaad ist ein Dämon, den man laut Gakin nicht unterschätzen sollte.",al={"sayaad-dämon","was für ein dämon","art des inkubus"}},{q="Warum sollte ich dem Inkubus misstrauen?",a="Gakin warnt, dass der Inkubus Betörung und Täuschung einsetzen könnte und jedes seiner Angebote falsch ist.",al={"kann ich ihm trauen","täuschung durch den inkubus","was wird er anbieten"}},{q="Was lehrt Gakin nach der Prüfung?",a="Nachdem Ihr den Inkubus bezwungen habt, lehrt Gakin Euch die Beschwörungsformel, mit der Ihr den gebundenen Dämon herbeiruft.",al={"was geschieht danach","lehre der bindung","beschwörungsformel für den inkubus"}}},fp="11,159,21.294.0,18.210.1,30.130.0,30.76.0,17.75.0,34.101.0,38.99.0"}
P.entries["quest:65604"] = {n="The Binding",s="Gan'rul Blutauge schickt Euch, mit dem Withered Scarf einen Inkubus zu beschwören und zu unterwerfen. Die Bindung prüft, ob Ihr den Verführungskünsten und der Macht eines Dämons gewachsen seid.",h="Gan'rul Blutauge schickt Euch, mit dem Withered Scarf einen Inkubus zu beschwören und zu unterwerfen.",kw={"gan'rul blutauge","inkubus","magar","neerus zelt","sayaad","beschwörungskreis","the binding","withered scarf"},ang={["class:Warlock"]="Als Hexenmeister werdet Ihr darin geprüft, einen Inkubus zu beschwören und zu unterwerfen. Gan'rul warnt, dass Dämonen ihre Verführungskünste gegen Euch wenden können."},sec={{t="Am Kreis",b="Gan'rul Blutauge liest Liebe in den Fäden des Withered Scarf und glaubt, dass er einen Inkubus anlocken wird. In Neerus Zelt in Orgrimmar sollt Ihr ihn am Beschwörungskreis benutzen und Eure Herrschaft über den Dämon beweisen. Gan'rul warnt, dass ein Inkubus sich nicht widerstandslos ergeben wird, und bittet Euch, den Schal nach dessen Unterwerfung zurückzubringen."},{t="Der zurückgebrachte Schal",b="Gan'rul erhält den Schal, nachdem der Inkubus unterworfen wurde. Er sagt, er werde Euch lehren, den Dämon zu beschwören, und den Schal an Magar zurückgeben. Der Stoff erinnert ihn daran, dass Hexenmeister dämonische Dunkelheit beherrschen mögen, doch niemals von Dämonen beherrscht werden dürfen."}},faq={{q="Von wem erhaltet Ihr The Binding?",a="Gan'rul Blutauge gibt Euch den Withered Scarf und bittet Euch, einen Inkubus zu beschwören und zu unterwerfen.",al={"wer ist gan'rul","gan'rul bindung","wer gibt den schal"}},{q="Was bewirkt der Withered Scarf?",a="Gan'rul spürt Liebe, die in die Fäden des Schals gewoben ist, und glaubt, dass er einen Inkubus anlocken wird.",al={"zweck des schals","withered scarf","warum der schal"}},{q="Wo ist der Beschwörungskreis?",a="Der Beschwörungskreis befindet sich in Neerus Zelt in Orgrimmar.",al={"inkubus kreis","wo beschwören","neeru zelt"}},{q="Was ist ein Inkubus?",a="Ein Inkubus ist ein Sayaad. Gan'rul warnt, dass Sayaad den Geist beherrschen und Seelen quälen und dass ein Inkubus seine Beute bezaubern kann.",al={"inkubus bedeutung","sayaad","welcher dämon"}},{q="Worum bittet Euch Gan'rul?",a="Gan'rul bittet Euch, mit dem Withered Scarf einen Inkubus zu beschwören, ihn zu unterwerfen und ihm den Schal zurückzubringen.",al={"bindung aufgabe","was ist zu tun","inkubus bindung"}}},fp="11,148,13.325.0,18.231.1,26.91.0,32.88.0,30.53.0,19.123.0,32.102.0"}
P.entries["quest:6561"] = {n="Schurkerei in der Tiefschwarzen Grotte",s="In der Tiefschwarzen Grotte ruft ein verwundeter Späher um Hilfe gegen den Kult, der Aku'mai dient. Thaelrid, Späher der Argentumdämmerung, bittet vorbeikommende Champions der Horde, Zwielichtfürst Kelris' Blutopfer in den versunkenen Ruinen zu beenden.",h="In der Tiefschwarzen Grotte ruft ein verwundeter Späher um Hilfe gegen den Kult, der Aku'mai dient.",kw={"aku'mai","argentumdämmerung","bashana runentotem","tiefschwarze grotte","schurkerei in der tiefschwarzen grotte","kelris","mondbrunnen","thaelrid","zwielichtfürst kelris","schattenhammer"},ang={["class:Druid"]="Für einen Druiden verletzt die Schändung eines uralten Nachtelfen-Mondbrunnens durch Naga und Kultisten, die die Leere verehren, Kalimdors natürliche und spirituelle Zuflucht.",["class:Shaman"]="Für einen Schamanen stören Kelris und Aku'mai das Gleichgewicht der Elemente und verwandeln reine unterirdische Gewässer in einen Ort der Schatten und Opfer.",["faction:Horde"]="Für die Horde ist das Bündnis mit einem Späher der Argentumdämmerung ein ungewöhnlicher Akt gemeinsamer Entschlossenheit gegen eine kosmische Verderbnis. Es sichert ihr schon früh die Gunst der Argentumdämmerung.",["race:Tauren"]="Bashana Runentotem sieht Kelris' Niederlage als Verteidigung der Erdenmutter. Sie beseitigt eine Abscheulichkeit, die die natürliche Ordnung der Welt ins urzeitliche Chaos stürzen wollte."},sec={{t="Ein verzweifeltes letztes Gefecht",b="Thaelrid, Späher der Argentumdämmerung, liegt verwundet im unterirdischen Tempel an der Küste von Eschental. Seine Erkundung deckte Schrecken auf, die weit über die Überfälle der Naga hinausgehen, doch seine Kräfte sind erschöpft, und er kann seine Mission nicht allein vollenden. Deshalb ruft er vorbeikommende Champions der Horde dazu auf, die Anführer des Kults in den versunkenen Hallen anzugreifen."},{t="Opfer für die Tiefe",b="Zwielichtfürst Kelris führt die Kultisten des Schattenhammers im zerstörten Tempel des Mondes an. Gemeinsam mit den ansässigen Naga vollzieht er dunkle Rituale über dem geschändeten Mondbrunnen. Gefangene werden Aku'mai lebend zum Fraß vorgeworfen, einer unersättlichen Hydra und Bestie der Alten Götter. Kelris strebt nach kosmischer Macht und urzeitlichem Chaos."},{t="Nachricht nach Donnerfels",b="Die Argentumdämmerung hielt Kelris für tot oder verschollen, daher ist eine Nachricht über sein Schicksal von Bedeutung. Thaelrid lässt den Beweis für den Tod des Kultistenführers zu Bashana Runentotem auf der Anhöhe der Ältesten in Donnerfels bringen. Bashana ist mit dem natürlichen Gleichgewicht der Erdenmutter verbunden und würdigt den Sieg über eine Verderbnis, die Kalimdor in urzeitlichen Untergang stürzen will."}},faq={{q="Wer ist Zwielichtfürst Kelris?",a="Zwielichtfürst Kelris führt die Kultisten des Schattenhammers in der Tiefschwarzen Grotte an. Die Argentumdämmerung hielt ihn für tot oder verschollen, doch er hat Macht gesammelt, indem er der uralten Hydra Aku'mai im verderbten Mondbrunnen Gefangene opferte.",al={"kelris","wer ist kelris","zwielichtfürst kelris"}},{q="Warum ist ein Mitglied der Argentumdämmerung in der Tiefschwarzen Grotte?",a="Thaelrid, Späher der Argentumdämmerung, betrat den zerstörten Nachtelfentempel, um der wachsenden Bedrohung dort nachzugehen. Die Gefahren dort haben ihn dem Tod nahe und ohne Ausweg zurückgelassen, sodass er auf eintreffende Abenteurer angewiesen ist, die seine Pflicht erfüllen und Kelris töten.",al={"argentumwache thaelrid","warum ist thaelrid hier","argentumdämmerung in der tiefschwarzen grotte"}},{q="Was ist Aku'mai?",a="Aku'mai ist eine uralte, vielköpfige Hydra, die als urzeitlicher Diener der Alten Götter gilt. Sie erwachte, als Verderbnis aus den Tiefen der Erde die heiligen Wasser des Tempels verseuchte. Nun verschlingt sie Gefangene, die der Schattenhammer ihr bringt.",al={"akumai","wer ist akumai","aku'mais hintergrundgeschichte"}},{q="Warum die Quest bei Bashana Runentotem abgeben?",a="Thaelrid schickt Champions der Horde zu Bashana Runentotem auf der Anhöhe der Ältesten in Donnerfels. Als Hüterin des Gleichgewichts der Erdenmutter hält Bashana Kontakt zu Verteidigern gegen uraltes Übel und betrachtet Kelris' Verehrung der Alten Götter als Makel auf Kalimdor.",al={"bashana runentotem","warum donnerfels","wo schurkerei in der tiefschwarzen grotte abgeben"}},{q="Was geschah mit den Ruinen der Tiefschwarzen Grotte?",a="Die Tiefschwarze Grotte war einst ein unterirdischer Tempel, der der Mondgöttin Elune geweiht war. Umwälzungen und uralte Finsternis, die aus der Erde sickerte, verseuchten den großen Mondbrunnen. Naga und Weltuntergangskultisten beanspruchten die versunkenen Heiligtümer für ihren dunklen Meister Aku'mai.",al={"geschichte der tiefschwarzen grotte","ruinen des tempels von elune","warum ist die tiefschwarze grotte verderbt"}},{q="Was ist hier das Ziel des Schattenhammer-Kults?",a="Der Schattenhammer will die Welt durch die Verehrung der Alten Götter ins urzeitliche Chaos zurückführen. Kelris sucht Macht durch dunkle Zwiesprache und wirft Unschuldige der Tiefe zum Fraß vor, um die Gunst uralter Wesen zu gewinnen.",al={"beweggründe des schattenhammers","warum ein kult in der tiefschwarzen grotte","kelris' ziele"}}},fx={["8c6f2eb7"]={q="Warum will Argentumwache Thaelrid, dass Zwielichtfürst Kelris getötet wird?",a="Zwielichtfürst Kelris und seine Kultisten des Schattenhammers opfern aktiv unschuldige Gefangene an Aku'mai, einen niederträchtigen Diener der Alten Götter, im Austausch für dunkle Macht. Thaelrid wurde von der Argentumdämmerung ausgesandt, um diese Schrecken zu beenden, und er kann nicht zulassen, dass die Verderbtheit und die chaotische Anbetung des Kults ungehindert weitergehen.",al={"beweggrund von thaelrid","warum will thaelrid kelris tot","warum kelris töten"}},["6dbae1c3"]={q="Wofür dient Kelris Kopf?",a="Der Kopf dient als unbestreitbarer Beweis für das Ableben des Kultführers. Kelris entkam der Argentumdämmerung lange Zeit, was viele zu der Annahme verleitete, er sei bereits tot oder verschollen. Ihn also Bashana Runentotem in Donnerfels zu präsentieren, bestätigt, dass seine Schreckensherrschaft und die Menschenopfer wahrhaftig ein Ende gefunden haben.",al={"zweck von kelris kopf","was tun mit kelris kopf","warum kelris kopf nehmen"}},f2efcdf9={q="Warum braucht Thaelrid Eure Hilfe, statt Kelris selbst aufzuhalten?",a="Thaelrid wurde tief im Versunkenen Tempel schwer verwundet. Geschwächt, ausgelaugt und völlig kraftlos kann er dem Kultführer nicht allein entgegentreten. Damit seid Ihr der Einzige, der seine Mission vollenden kann.",al={"warum braucht thaelrid hilfe","warum kann thaelrid kelris nicht bekämpfen","thaelrid warum ich"}}},fp="20,210,22.316.0,22.295.0,21.314.1,28.228.0,54.228.0,16.230.0,43.250.0,48.253.0,52.211.0"}
P.entries["quest:65610"] = {n="Wish You Were Here",s="Ein Mondstoffweber im Eschental bittet Euch, Krilge zu finden, der beim Schutz von Zivilisten verschwand. Seine Kameraden nennen ihn einen Deserteur, doch der Weber glaubt, dass er seinen Posten gehalten hat.",h="Ein Mondstoffweber im Eschental bittet Euch, Krilge zu finden, der beim Schutz von Zivilisten verschwand.",kw={"eschental","sumpfbestien","deserteur","himmelssturzsee","gan'rul blutauge","krilge","vermisst","mondstoff"},sec={{t="Ein vermisster Freund",b="Ein Mondstoffweber lernte Krilge kennen, als er im Eschental Mondstoff herstellte. Krilge war dort stationiert, um Zivilisten zu schützen, verschwand dann aber. Sie trafen sich oft am Himmelssturzsee, bis aggressive Sumpfbestien ihn überrannten. Der Weber hofft noch immer zu erfahren, was aus ihm geworden ist."},{t="Am See",b="Ihr sollt den Himmelssturzsee durchsuchen und Gan'rul Blutauge in Orgrimmar von Euren Entdeckungen berichten. Krilges Kameraden haben die Suche nach ihm aufgegeben. Vielleicht birgt der See noch einen Hinweis darauf, was aus ihm geworden ist."}},faq={{q="Wer ist Krilge?",a="Krilge war im Eschental stationiert, um Zivilisten zu schützen, bevor er verschwand. Er und der Mondstoffweber trafen sich oft am Himmelssturzsee.",al={"krilge","vermisster freund des mondstoffwebers"}},{q="Warum wird Krilge als Deserteur bezeichnet?",a="Krilge verschwand von seinem Posten. Diejenigen, die mit ihm dienten, haben die Suche aufgegeben und nennen ihn einen Deserteur.",al={"krilge deserteur","warum sie die suche aufgegeben haben"}},{q="Wer bittet Euch, nach Krilge zu suchen?",a="Ein Mondstoffweber, der Krilge im Eschental kennenlernte, bittet Euch, nach einem Zeichen von ihm zu suchen.",al={"wer hat mich geschickt","mondstoffweber"}},{q="Wo trafen sich Krilge und der Weber?",a="Krilge und der Weber trafen sich oft am Himmelssturzsee im Eschental, bevor aggressive Sumpfbestien das Gebiet überrannten.",al={"krilges treffpunkt","wo ist der himmelssturzsee"}},{q="Wo sollt Ihr von Euren Entdeckungen berichten?",a="Ihr sollt Gan'rul Blutauge in Orgrimmar von Euren Entdeckungen berichten.",al={"gan'rul berichten","wo soll ich berichten"}}},fp="18,169,16.258.0,11.205.0,14.134.0,38.99.0,32.83.0,36.110.0,38.71.0"}
P.entries["quest:6562"] = {n="Ärger in der Tiefe",s="Vom Steinkrallengebirge aus schickt Tsunaman Reisende der Horde an Eschentals abgelegene Küste, um Je'neu Sancrea beizustehen. Der Trollgelehrte wartet am Außenposten von Zoram'gar, wo sich entlang der Küste Gefahren zusammenbrauen.",h="Vom Steinkrallengebirge aus schickt Tsunaman Reisende der Horde an Eschentals abgelegene Küste, um Je'neu...",kw={"eschental","tiefschwarze grotte","je'neu sancrea","steinkrallengebirge","tsunaman","die scherwindklippe","der zoramstrand","außenposten von zoram'gar"},ang={["class:Shaman"]="Als Schamane könnt Ihr die Unruhe in den Wassergeistern des Zoramstrands deuten und helfen, sie von der Verderbnis zu reinigen, die sie bedroht.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Außenposten von Zoram'gar an Kalimdors Westflanke gegen Streitkräfte der Nachtelfen und Schrecken der Küste zu halten.",["race:Troll"]="Als Troll könnt Ihr Je'neu Sancrea, einem der führenden Gelehrten der Dunkelspeere, beistehen, während er uralte Geheimnisse Kalimdors aufdeckt."},sec={{t="Ein Ruf an die Küste",b="Tsunaman hört beunruhigende Berichte aus dem Norden und ruft Reisende der Horde dazu auf, Je'neu Sancrea beizustehen. Der Trollgelehrte wartet am Außenposten von Zoram'gar an Eschentals äußerster Westküste, am Zoramstrand. Dort wächst die Gefahr, und Je'neu braucht Hilfe von außerhalb des Außenpostens."},{t="Der Weg zum Zoramstrand",b="Der Weg an Eschentals Westküste ist für Reisende der Horde gefährlich. Ihr könnt die Scherwindklippe durchqueren, wo Goblins für Ärger gesorgt haben, oder vom Brachland aus nach Norden reisen. Auf beiden Wegen betretet Ihr einen Wald, über den Schildwachen der Nachtelfen wachen.\n\nTief unter Eschentals dichtem Blätterdach hält sich der Außenposten von Zoram'gar am sturmumtosten Zoramstrand. Der Außenposten blickt auf die schattigen Gewässer."},{t="Flüstern unter den Wellen",b="An der Küste weist Je'neu Sancrea auf Gefahren unter den Wellen hin, im versunkenen Tempel der Tiefschwarzen Grotte. Uralte Verderbnis, üble Wasserelementare und Kultisten des Twilight's Hammer sammeln sich dort und rühren uralte Übel auf. Je'neu setzt auf eintreffende Champions, die in die überfluteten Hallen vordringen und sich dem darin erwachenden Schrecken stellen."}},faq={{q="Wer vergibt die Quest Ärger in der Tiefe?",a="Tsunaman im Steinkrallengebirge schickt Reisende der Horde aus, um Verbündeten an Eschentals Küste beizustehen.",al={"questgeber","wer vergibt ärger in der tiefe","tsunaman"}},{q="Wo befindet sich Je'neu Sancrea?",a="Je'neu Sancrea wartet am Außenposten von Zoram'gar am Zoramstrand, an Eschentals äußerster Westküste.",al={"wo ist je'neu","jeneu sancrea standort","außenposten von zoram'gar"}},{q="Wie erreicht Ihr den Außenposten von Zoram'gar vom Steinkrallengebirge aus?",a="Reist vom Steinkrallengebirge aus nach Nordosten durch die Scherwindklippe nach Eschental oder nach Osten durch das Brachland und betretet den Wald von Süden. Zieht dann aus der Mitte Eschentals nach Westen zum Zoramstrand.",al={"weg nach eschental","wie zum zoramstrand gelangen","route vom steinkrallengebirge nach eschental"}},{q="Welchen Gefahren geht Je'neu nach?",a="Je'neu Sancrea beobachtet die Ruinen der Tiefschwarzen Grotte, wo Kultisten und verderbte Wasserwesen uralte Schrecken unter der Oberfläche aufrühren.",al={"was geschieht am zoramstrand","warum braucht jeneu hilfe"}},{q="Welche Quest folgt auf Ärger in der Tiefe?",a="Je'neu Sancrea schickt Euch in die Tiefschwarze Grotte, um die mit Elementarkraft aufgeladenen Sapphires of Aku'Mai aus ihren Tunneln zu sammeln.",al={"nächste quest","folgequest von ärger in der tiefe"}},{q="Warum gilt die Reise durch Eschental als gefährlich?",a="Nachtelfen verteidigen Eschental erbittert gegen Vorstöße der Horde. Feindliche Schildwachen und verborgene Angreifer bedrohen Reisende im Wald.",al={"gefahr in eschental","bedrohung durch nachtelfen"}}},fx={dde1b6c4={q="Warum schickt Tsunaman Euch zu Je'neu Sancrea?",a="Tsunaman weiß, dass Je'neu Sancrea am abgelegenen Außenposten von Zoram'gar isoliert ist und verzweifelt fähige Verbündete benötigt. Stationiert an der fernen Westküste von Eschental, sieht sich Je'neu zunehmenden Gefahren rund um die geheimnisvollen Tiefen der Tiefschwarzen Grotte ohne ausreichende Unterstützung gegenüber. Tsunaman entsendet Euch, um ihn zu verstärken, bevor feindliche Streitkräfte den Stützpunkt der Horde überwältigen.",al={"warum will tsunaman dies erledigt haben","warum schickst du mich nach eschental","beweggrund von tsunaman"}}},fp="20,192,22.271.0,24.383.0,24.318.1,41.99.0,32.99.0,51.196.0,37.144.0,40.120.0,57.133.0"}
P.entries["quest:6563"] = {n="Die Essenz von Aku'mai",s="Am Außenposten von Zoram'gar bittet Je'neu Sancrea Abenteurer der Horde, den Saphirabbau der Naga in der Tiefschwarzen Grotte zu stoppen. Er fürchtet, dass sie die Macht der Edelsteine missbrauchen werden.",h="Am Außenposten von Zoram'gar bittet Je'neu Sancrea Abenteurer der Horde, den Saphirabbau der Naga in der...",kw={"eschental","tiefschwarze grotte","je'neu sancrea","naga","saphir von aku'mai","trouble in the deeps","wassergeister","der zoramstrand"},ang={["class:Shaman"]="Als Schamane könnt Ihr die ruhelosen Wassergeister spüren, die in den Kristallen gebunden sind. Sie warnen vor verderbten Elementarkräften unter dem Tempel.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, den gefährdeten Stützpunkt am Außenposten von Zoram'gar zu schützen. Die Naga in der Nähe von roher magischer Macht fernzuhalten, hilft bei seiner Verteidigung.",["race:Troll"]="Als Troll könnt Ihr Euch an Je'neu Sancrea wenden, einen aufmerksamen Mystiker der Dunkelspeer. Er vertraut auf die Zwiesprache mit den Geistern und die Weisheit der Ahnen, um Kalimdors fremdartigen Bedrohungen zu begegnen."},sec={{t="Eine Bedrohung in der Tiefe",b="Vom Zoramstrand aus wacht Je'neu Sancrea über die Kaldorei-Ruinen. Naga bauen nun Saphiransammlungen in den überfluteten Kammern der Tiefschwarzen Grotte ab, wo die Edelsteine an feuchten Höhlenwänden wachsen. Sancrea spürt, dass die schlangenartigen Eindringlinge deren Macht nutzen wollen, und versucht deshalb, den Abbau zu stoppen, bevor sie diese einsetzen können."},{t="Wassergeister und arkane Macht",b="Die Sapphires of Aku'mai tragen elementare Wasserenergie in sich und beherbergen anhaftende Wassergeister. Fähige Zauberer könnten damit gefährliche arkane Rituale speisen oder Aku'mai stärken, die schattenhafte Hydra, deren Gegenwart den unterirdischen Tempel erfüllt. Die Bergung der Ansammlungen hält dieses mächtige Reagenz von den Naga fern und hilft, die Küste vor unkontrollierter Elementarmagie zu schützen."}},faq={{q="Wer vergibt diese Quest?",a="Am Außenposten von Zoram'gar am Zoramstrand im nordwestlichen Eschental stellt Je'neu Sancrea, ein Trollschamane der Dunkelspeer, diese Bitte.",al={"questgeber","wer startet die essenz von akumai","jeneu sancrea standort"}},{q="Warum wollen die Naga die Sapphires of Aku'mai?",a="Das genaue Vorhaben der Naga ist unbekannt. Die Saphire bergen mächtige elementare Wasserenergie und rohe magische Kraft, die ihre Zauber speisen könnten.",al={"warum wollen naga saphire","wozu dienen die kristalle","zweck der saphire"}},{q="Wo sind die Saphiransammlungen zu finden?",a="Saphiransammlungen säumen die Höhlenwände und Böden in den äußeren Tunneln und überfluteten Gängen der Tiefschwarzen Grotte. Sie liegen gleich hinter dem verfallenen unterirdischen Eingang am Zoramstrand.",al={"wo saphire finden","sapphire of akumai fundort","kristallvorkommen"}},{q="Was ist Aku'mai?",a="Aku'mai ist eine monströse dreiköpfige Hydra, die tief in den überfluteten Tempelruinen haust. Kultisten von Twilight's Hammer verehren ihn als Diener der Old Gods.",al={"wer ist akumai","was ist akumai","aku'mai"}},{q="Muss ich für diese Quest Dungeonbosse töten?",a="Nein. Die Saphiransammlungen wachsen in den ersten überfluteten Tunneln, bevor Ihr auf die Hauptbosse der Tiefschwarzen Grotte trefft.",al={"ist eine volle gruppe nötig","saphire allein sammeln","bossvoraussetzung"}},{q="Ist diese Quest mit einer anderen Geschichte verbunden?",a="Ja. Sie folgt auf 'Trouble in the Deeps' und setzt Je'neu Sancreas Untersuchung der wachsenden Finsternis und der Kultistenaktivitäten in der Tiefschwarzen Grotte fort.",al={"questreihe","voraussetzungen","trouble in the deeps"}}},fx={["7dd39a86"]={q="Warum möchte Je'neu Sancrea die Saphire von Aku'mai?",a="Je'neu Sancrea bemerkte, dass die Naga diese Kristallgruppen systematisch von den Höhlenwänden der Tiefschwarzen Grotte ernten. Während ihr genauer Plan unklar bleibt, spürt er gewaltige elementare Energie, die in den Steinen verweilt. Er möchte, dass sie gesammelt werden, bevor die Naga sie als mächtige arkane Komponenten waffenfähig machen können.",al={"beweggrund von jeneu sancrea","warum saphire sammeln","warum saphire von akumai sammeln"}},["644dacf9"]={q="Was ist der Saphir von Aku'mai?",a="Diese Saphire sind kristalline Formationen, die die überfluteten Tunnel der Tiefschwarzen Grotte säumen. Sie resonieren mit roher elementarer Kraft und ziehen Wassergeister an, die sich an sie klammern. Aufgrund dieser natürlichen Energiekonzentration dienen sie als gewaltige arkane Reagenzien, sofern sie korrekt kanalisiert werden.",al={"was sind die saphire","lore der saphire von akumai","kraft der saphire von akumai"}}},fp="22,160,22.319.0,30.364.0,21.129.0,46.137.0,38.185.0,16.158.0,52.117.0,47.151.0"}
P.entries["quest:6564"] = {n="Treue zu den Alten Göttern",s="Am Außenposten von Zoram'gar bringt Ihr Je'neu Sancrea eine Naga-Botschaft aus der Tiefschwarzen Grotte. Ihre Befehle deuten auf eine rituelle Verschwörung in den überfluteten Ruinen hin.",h="Am Außenposten von Zoram'gar bringt Ihr Je'neu Sancrea eine Naga-Botschaft aus der Tiefschwarzen Grotte.",kw={"aku'mai","treue","eschental","tiefschwarze grotte","feuchte notiz","je'neu sancrea","lorgus jett","alte götter","wrathscale","außenposten von zoram'gar"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass das gewaltsame Binden von Wasserelementargeistern in Ritualkristalle das natürliche Gleichgewicht stört und rasches Eingreifen erfordert.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Lorgus Jetts Notiz aufzudecken und den Außenposten von Zoram'gar vor dem Twilight's Hammer und seinen Naga-Verbündeten zu schützen. Sie bedrohen den Stützpunkt der Horde an der Westküste des Eschentals.",["race:Troll"]="Als Troll helft Ihr Eurem Stammesgenossen Je'neu Sancrea von den Dunkelspeer, uralte kosmische Wesen aufzuspüren, deren Rückkehr jeden Stamm auf Azeroth bedrohen würde."},sec={{t="Eine hastig gekritzelte Erklärung",b="Späher der Horde finden beim Kampf gegen die Naga in der Tiefschwarzen Grotte eine feuchte, zusammengeknüllte Notiz. Ihre hektischen Worte befehlen den Naga-Priesterinnen, elementare Wasserkristalle zu sammeln. Diese Kristalle sollen die Beschwörungen der Naga-Aquamanten speisen. Die Aquamanten sammeln Elementarkräfte für einen finstereren Zweck."},{t="Flüstern aus der Tiefe",b="Laut den Befehlen wollen die Naga mit der Elementarenergie der Kristalle Aku'mai besänftigen und vollständig beschwören, eine monströse Hydra im Dienste der Alten Götter. Die Notiz behauptet, dies werde die Rückkehr der größten Ära der Welt einläuten: der prähistorischen Herrschaft der Alten Götter. Am Außenposten von Zoram'gar nennt Je'neu Sancrea, ein Mystiker der Dunkelspeer, Lorgus Jett, einen Kultisten des Twilight's Hammer, als Verfasser."}},faq={{q="Was ist die Feuchte Notiz?",a="Die Feuchte Notiz enthält Befehle von Lorgus Jett, einem Kultisten des Twilight's Hammer. Sie fordert Naga-Priesterinnen auf, von Elementarenergie durchdrungene Kristalle zu sammeln, um ihre Aquamanten zu stärken und Aku'mai, einen monströsen Diener, zu beschwören.",al={"feuchte notiz","was steht in der notiz","hintergrund der notiz"}},{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Seher und Gelehrter der Dunkelspeertrolle am Außenposten von Zoram'gar im Eschental. Er vertritt den Irdenen Ring und untersucht elementare Ungleichgewichte sowie uralte Bedrohungen, die sich aus der Tiefschwarzen Grotte erheben.",al={"jeneu sancrea","wer ist jeneu","zoram außenposten questgeber"}},{q="Wer ist Lorgus Jett?",a="Lorgus Jett ist ein menschlicher Schamane des Twilight's Hammer-Kults, der mit den Naga in der Tiefschwarzen Grotte zusammenarbeitet. Er überwacht das Sammeln von Elementarkristallen, um die Rituale der Naga zu stärken und finstere, uralte Schrecken zu erwecken.",al={"lorgus jett","wer schrieb die notiz","naga anführer zoram"}},{q="Was ist Aku'mai?",a="Aku'mai ist eine gewaltige, dreiköpfige Hydra in den überfluteten Tiefen der Tiefschwarzen Grotte. Der Twilight's Hammer-Kult und die Naga verehren die Kreatur, die mit der urzeitlichen Finsternis der Alten Götter verbunden ist.",al={"akumai","wer ist akumai","aku'mai hintergrund"}},{q="Warum sammeln die Naga Wasserkristalle?",a="Die Naga sammeln Wasserkristalle, um die darin gefangenen Elementargeister anzuzapfen und ihre Aquamanten zu stärken. Sie hoffen, Aku'mai zu besänftigen und genug Macht zu sammeln, um die Alten Götter zurückzubringen.",al={"warum naga kristalle","elementarkristalle naga","aquamanten kristalle"}},{q="Wohin führt diese Questreihe?",a="Die Übergabe der Notiz an Je'neu Sancrea führt zu dem Vorhaben, Lorgus Jett aufzuspüren und hinzurichten. Dies würde die Ritualpläne des Kults in der Tiefschwarzen Grotte durchkreuzen.",al={"was kommt nach treue zu den alten göttern","treue zu den alten göttern teil zwei","nächste quest"}}},fp="26,141,23.300.0,20.366.1,22.211.0,22.207.0,19.213.0,16.198.0,43.195.0,33.152.1"}
P.entries["quest:6565"] = {n="Treue zu den Alten Göttern",s="Bei Zoram'gar geht die Horde gegen den Kult des Schattenhammers in der Tiefschwarzen Grotte vor. Je'neu Sancrea schickt Champions auf die Jagd nach Lorgus Jett, um die Kultisten zu stören, die unter Eschentals Küste uralte Zerstörungskräfte erwecken wollen.",h="Bei Zoram'gar geht die Horde gegen den Kult des Schattenhammers in der Tiefschwarzen Grotte vor.",kw={"treue zu den alten göttern","eschental","tiefschwarze grotte","je'neu sancrea","lorgus jett","alte götter","schattenhammer","zoram'gar"},ang={["class:Shaman"]="Der Schattenhammer will für die chaotischen Alten Götter elementare Wut entfesseln. Die Ausrottung des Kults hat Vorrang für jene, die sich an der Seite des Irdenen Rings dem elementaren Gleichgewicht verschrieben haben.",["faction:Horde"]="Der Sieg über Lorgus Jett schützt den Außenposten von Zoram'gar und sein abgelegenes Lager der Horde vor heimtückischen Plänen der Kultisten.",["race:Troll"]="Je'neu Sancrea zu helfen ehrt die Weisheit eines angesehenen Sehers der Dunkelspeer, der fern der Echoinseln daran arbeitet, Azeroths urtümliche Geister zu schützen."},sec={{t="Die Bedrohung unter Zoram'gar",b="Von Eschentals Küste aus wacht der Außenposten von Zoram'gar über die Tiefschwarze Grotte. Naga, verderbte Bestien und Fanatiker des Schattenhammers überrennen ihren versunkenen Tempelkomplex. Je'neu Sancrea ist ein Seher des Irdenen Rings, der an der Küste stationiert ist. Er erkennt, dass die Kultisten den Alten Göttern dienen statt dem natürlichen Gleichgewicht und den Geistern des Landes. Diese monströsen Wesen des Chaos wurden in uralten Zeiten besiegt, doch ihre bösartige Berührung wirkt in Azeroths vergessenen Winkeln fort."},{t="Lorgus Jetts Ende",b="Je'neu schickt Champions der Horde in die unterirdischen Ruinen, um Lorgus Jett zu jagen, einen etablierten Anführer der Kultisten in der Tiefschwarzen Grotte. Lorgus wirkt tief in den steinernen Gängen zwischen Ghamoo-ras Kammer und Baron Aquanis' Kammer. Je'neu ist zu gebrechlich, um selbst in die feuchte Dunkelheit vorzudringen. Lorgus' Niederlage ist entscheidend, um die dunklen Rituale zu unterbinden, die er unter Eschentals Wellen leiten wollte."},{t="Das Chaos abwehren",b="Lorgus Jetts Tod dämmt die unmittelbare Bedrohung der Küste durch die Rituale ein, doch Je'neu weiß, dass der Schattenhammer weiterhin aktiv ist. Sein heimliches Eindringen in uralte heilige Stätten deutet auf eine umfassendere Bedrohung hin, die die Rückkehr der Alten Götter anstrebt. Bei Zoram'gar verschafft Lorgus' Niederlage der Horde Zeit gegen einen Feind, der sich in den Schatten der Welt verbirgt."}},faq={{q="Wer ist Lorgus Jett?",a="Lorgus Jett ist ein etablierter Anführer der Kultisten des Schattenhammers in der Tiefschwarzen Grotte. Er leitet Rituale, die die uralten Alten Götter und ihre Herrschaft zurückbringen sollen.",al={"lorgus jett","wer ist lorgus","lorgus jett hintergrund"}},{q="Wo ist Lorgus Jett in der Tiefschwarzen Grotte zu finden?",a="Lorgus Jett patrouilliert durch die überfluteten Gänge der Tiefschwarzen Grotte, in den Verbindungshallen zwischen Ghamoo-ras Kammer und dem Altarbereich von Baron Aquanis.",al={"lorgus jett aufenthaltsort","wo ist lorgus","lorgus jett finden"}},{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Trollseher der Dunkelspeer im Dienst des Irdenen Rings, stationiert am Außenposten von Zoram'gar am Zoramstrand in Eschental. Er beobachtet elementare Störungen und die Verderbnis in der Tiefschwarzen Grotte.",al={"je'neu sancrea","wer vergibt treue zu den alten göttern","jeneu"}},{q="Warum beschäftigt sich Je'neu mit dem Schattenhammer?",a="Je'neu widmet sich dem Verständnis der Natur und des elementaren Gleichgewichts. Er sieht im Schattenhammer eine existenzielle Bedrohung, weil der Kult den chaotischen Alten Göttern dient, deren Rückkehr die Harmonie der Welt zerstören würde.",al={"warum den schattenhammer bekämpfen","irdener ring alte götter"}},{q="Was sind die Alten Götter?",a="Die Alten Götter sind urzeitliche Wesen des Chaos und der Zerstörung, die in ferner Vergangenheit über Azeroth herrschten, bevor sie besiegt und begraben wurden. Der Schattenhammer betet sie an und schmiedet Pläne, ihre Siegel zu brechen und ihre zerstörerische Herrschaft zurückzubringen.",al={"alte götter hintergrund","wer sind die alten götter","kreaturen des chaos"}},{q="Warum kann Je'neu Sancrea Lorgus Jett nicht selbst töten?",a="Je'neu ist zu gebrechlich, um sich allein in die Tiefschwarze Grotte zu wagen. Er verfolgt vom Außenposten aus spirituelle und elementare Störungen, während Champions der Horde die Kämpfe bestreiten.",al={"warum geht jeneu nicht","ist jeneu schwach"}}},fp="26,239,28.446.0,18.398.0,17.332.1,19.168.0,52.141.0,22.201.0,49.212.0,22.243.0,50.156.0"}
P.entries["quest:6568"] = {n="Nachricht von Rexxar",s="Rexxar schickt Euch mit einer Nachricht für Myranda die Vettel in die Westlichen Pestländer. Er braucht ihre Illusionskunst, um die Verteidigungen des Schwarzen Drachenschwarms zu umgehen.",h="Rexxar schickt Euch mit einer Nachricht für Myranda die Vettel in die Westlichen Pestländer.",kw={"schwarzer drachenschwarm","desolace","illusion","mistress of deception","myranda die vettel","rexxar","trauerhügel","testament of rexxar","westliche pestländer"},sec={{t="Die Kunst der Illusion",b="Rexxar braucht eine Illusion, um die Verteidigungen des Schwarzen Drachenschwarms zu umgehen. Deshalb schickt er Euch zu Myranda der Vettel, einer Meisterillusionistin, die in den Westlichen Pestländern lebt. Die Allianz von Lordaeron hat sie vertrieben. Sie hat Rexxars Volk schon früher geholfen, wenn ihr eine Sache würdig erschien. Nun überbringt Ihr ihr seine Nachricht."},{t="Ein Besucher in Lordaeron",b="Ein Mitglied der Horde sei in diesen Teilen von Lordaeron ein seltener Anblick, sagt Myranda. Dann fragt sie, was Ihr ihr gebracht habt."},{t="Myrandas Antwort",b="Myranda hält die Notiz, hält inne und lächelt dann. Sie erkundigt sich nach Rexxar und erklärt, dass das Blatt absichtlich unbeschrieben war. Es enthielt die Gedanken und Absichten seines Verfassers. Sie versteht, warum Rexxar sie nicht mit Tinte festhielt. Die Nachricht wäre gefährlich gewesen, wenn Ihr gefangen genommen oder getötet worden wäret.\n\nMyranda erklärt sich bereit zu helfen. Sie schuldet dem Kriegshäuptling noch den einen oder anderen Gefallen."}},faq={{q="Wer ist Myranda die Vettel?",a="Myranda die Vettel ist eine Meisterillusionistin aus Lordaeron, die von der dortigen Allianz vertrieben wurde. Sie lebt am Trauerhügel in den Westlichen Pestländern.",al={"wer ist myranda","myranda die vettel hintergrundgeschichte","wo ist myranda"}},{q="Warum müsst Ihr eine Illusionistin aufsuchen?",a="Rexxar braucht eine Illusion, um die Verteidigungen des Schwarzen Drachenschwarms zu umgehen. Er kennt eine Meisterillusionistin, die vielleicht helfen kann.",al={"warum verkleidung","warum eine illusionistin aufsuchen","den schwarzen drachenschwarm täuschen"}},{q="Wohin schickt Rexxar Euch?",a="Rexxar schickt Euch in die Westlichen Pestländer, um Myranda die Vettel am Trauerhügel zu finden.",al={"wohin gehen","wo ist der trauerhügel","mistress of deception ziel"}},{q="Hat Myranda der Horde schon früher geholfen?",a="Rexxar sagt, Myranda habe seinem Volk schon früher geholfen, wann immer sie eine Sache für würdig befand.",al={"mag myranda die horde","myranda allianz oder horde","myranda gefallen kriegshäuptling"}}},fp="23,150,19.293.0,22.121.0,16.334.1,23.136.0,37.105.0,27.83.0,36.82.0"}
P.entries["quest:657"] = {n="Hinweise auf eine neue Seuche?",s="Kinelory ist auf dem Weg zu Go'Sheks Hof, wo Apotheker Jorells tödliche Experimente weitergehen. Quae hat aus einer Mappe davon erfahren, doch nach einem Zusammenstoß mit Orcs ist sie zu schwer verletzt, um mitzukommen.",h="Kinelory ist auf dem Weg zu Go'Sheks Hof, wo Apotheker Jorells tödliche Experimente weitergehen.",kw={"apotheker jorell","verlassene","go'sheks hof","kinelory","phin","seuche","quae","tarrens mühle"},sec={{t="Jorells Experimente",b="Die Mappe zeigt, dass Jorell auf Go'Sheks Hof tödliche Experimente durchführt. Quae weiß nicht, was sie für Hillsbrad bedeuten. Doch Phin würde nicht wollen, dass sie weitergehen. Ein Teil von Jorells Forschung hat Tarrens Mühle bereits erreicht."},{t="Kinelorys Beschützer",b="Quae hat gegen einige Orcs gekämpft, während Ihr fort wart, und kann Kinelory nun nicht helfen. Kinelory plant, zum Hof zu gehen und die Forschung an sich zu nehmen, die Jorell noch nicht nach Tarrens Mühle geschickt hat. Unterwegs braucht sie Euren Schutz."},{t="Kinelorys Entschlossenheit",b="Kinelory sagt, sie werde jeden Einzelnen der Verlassenen persönlich vernichten, wenn das Phin Frieden bringt. Seit der Seuche hat Phin so viel für Kinelory und die anderen getan. Sie hätten nie gedacht, dass sie je wieder Freunde oder Familie finden würden. Kinelory bittet Euch, ihr zu sagen, wann Ihr bereit seid, und dann werdet Ihr sofort gemeinsam aufbrechen."}},faq={{q="Warum kann Quae Kinelory nicht begleiten?",a="Quae hat gegen einige Orcs gekämpft, während Ihr fort wart, und ist nicht in der Verfassung, Kinelory zu helfen.",al={"warum bleibt quae","warum hilft quae nicht","warum kinelory allein eskortieren"}},{q="Was wurde in der Mappe entdeckt?",a="Die Mappe enthüllt Apotheker Jorells tödliche Experimente auf Go'Sheks Hof.",al={"was war in der mappe","jorells experimente","was tut jorell"}},{q="Warum gehen Quae und Kinelory der Sache nach?",a="Quae und Kinelory sind Phins Gefährtinnen. Phin führt eine Gruppe von Abenteurern an, die seltsamen Vorkommnissen nachgehen, und er würde nicht wollen, dass Jorells Experimente weitergehen.",al={"wer ist phin","warum interessiert sie die seuche","warum phin helfen"}},{q="Wohin wird die Forschung geschickt?",a="Ein Teil von Jorells Forschung wurde bereits nach Tarrens Mühle geschickt. Kinelory plant, an sich zu nehmen, was er noch nicht verschickt hat.",al={"wohin gehen die notizen","tarrens mühle forschung"}}},fp="22,186,20.228.0,20.209.0,18.318.1,34.78.0,34.74.0,45.159.0,33.107.0"}
P.entries["quest:6571"] = {n="Nachschub des Kriegshymnenklans",s="Am Splitterholzposten braucht Locke Okarr Nachschub des Kriegshymnenklans, damit das Holzfällerlager weiterarbeitet. Ein Teil wartet im Ort, ein weiterer in Beutebucht, und der Rest liegt im ganzen Eschental in Feindeshand.",h="Am Splitterholzposten braucht Locke Okarr Nachschub des Kriegshymnenklans, damit das Holzfällerlager...",kw={"eschental","beutebucht","locke okarr","holzfällerseil","pixel","sägeblätter","splitterholzposten","holzfällerlager des kriegshymnenklans","öl des kriegshymnenklans","nachschub des kriegshymnenklans"},ang={["faction:Horde"]="Die Ausbreitung der Horde in Durotar hängt vom Holz ab, das der Kriegshymnenklan beschafft. Die Rückholung dieser Werkzeuge hilft, Orgrimmar zu unterstützen.",["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie Goblinnachschub, von Pixels Sägeblättern bis zu Schmiermitteln für Dampfmaschinen, die Maschinen am Laufen hält, während der Kriegshymnenklan die uralten Wälder des Eschentals abholzt.",["race:Orc"]="Als Orc helft Ihr, das Vermächtnis des Kriegshymnenklans im Eschental zu ehren, indem Ihr trotz der Störangriffe der Waldbewohner seine Äxte scharf und seine Lager versorgt haltet."},sec={{t="Damit die Sägen laufen",b="Vom Splitterholzposten aus sorgt Locke Okarr für die Versorgung des Holzfällerlagers des Kriegshymnenklans. Der Kriegshymnenklan braucht stetigen Nachschub an schweren Werkzeugen, um die uralten Bäume des Eschentals zu fällen. Bei Überfällen haben Furbolgs und Satyrn örtliche Vorräte verstreut oder geraubt, sodass dem Lager wichtige Ausrüstung fehlt."},{t="Eine zerrissene Versorgungskette",b="Ihr beschafft Ausrüstung aus ganz Kalimdor und darüber hinaus. Pixel, der Goblinkurier am Splitterholzposten, hat Kreissägeblätter. In Beutebucht verwahrt Werftmeister Lozgil eine Kiste mit schweren Äxten. Foulweald- und Thistlefur-Furbolgs haben Holzfällerseile geraubt, während Satyrn in Nachtflucht, Satyrnaar und Xavian Fässer mit Maschinenöl des Kriegshymnenklans für ihre ruchlosen Rituale stahlen."}},faq={{q="Welcher Nachschub des Kriegshymnenklans wird benötigt?",a="Locke Okarr braucht vier Dinge: Sägeblätter des Kriegshymnenklans von Pixel, eine Kiste Warsong Axes aus Beutebucht, von örtlichen Furbolgs geraubtes Holzfällerseil und von den Satyrn des Eschentals gestohlenes Öl des Kriegshymnenklans.",al={"nachschub des kriegshymnenklans liste","welche gegenstände werden benötigt","benötigter nachschub"}},{q="Wer ist Locke Okarr?",a="Locke Okarr ist ein Orc am Splitterholzposten, der Materiallieferungen an das Holzfällerlager des Kriegshymnenklans koordiniert. Er braucht Hilfe, um verstreute Lieferungen zurückzuholen, bevor sich die Arbeit im Lager verzögert.",al={"locke okarr hintergrund","wer vergibt nachschub des kriegshymnenklans","questgeber splitterholzposten"}},{q="Warum verschifft die Horde Ausrüstung aus Beutebucht?",a="Die Horde nutzt neutrale Handelsnetze wie das Steamwheedle Cartel, um Spezialwaren einzuführen, die sich in Durotar und im Brachland kaum in großen Mengen schmieden lassen. Über die Handelswege der Goblins gelangen schwere Holzfälleräxte durch Seehandelsplätze wie Beutebucht ins Eschental.",al={"warum beutebucht","beutebucht axtlieferung","steamwheedle werkzeuge"}},{q="Warum wollen die Satyrn Öl des Kriegshymnenklans?",a="Satyrn in Satyrnaar, Nachtflucht und Xavian zweckentfremden gestohlenes Industrieöl für verderbte Rituale, die der Brennenden Legion und der Ausbreitung der Verderbnis des Teufelswalds gewidmet sind.",al={"satyröl hintergrund","warum haben satyrn öl","öl des kriegshymnenklans rituale"}},{q="Welche Furbolgs haben das Holzfällerseil gestohlen?",a="Die Furbolgstämme der Foulweald und Thistlefur haben das Holzfällerseil geraubt. Beide stellen sich den Kahlschlägen der Horde im gesamten Eschental erbittert entgegen.",al={"wer hat das seil gestohlen","furbolgseil hintergrund","foulweald thistlefur seil"}},{q="Warum ist das Holzfällerlager des Kriegshymnenklans für die Horde so wichtig?",a="Das Holzfällerlager des Kriegshymnenklans liefert Holz, das die Horde für Bauvorhaben und militärischen Nachschub braucht. Durotars trockene Lande bieten kaum nutzbares Holz, also fällt der Kriegshymnenklan die gewaltigen Bäume des Eschentals, um Orgrimmar aufzubauen und die wachsende militärische Infrastruktur der Horde zu unterstützen.",al={"warum im eschental abholzen","kriegshymnenholz bedeutung","orcs fällen bäume"}}},fx={b7ffa730={q="Warum muss Locke Okarr diese Vorräte sammeln lassen?",a="Locke Okarr ist für die Versorgung des Holzfällerlagers des Kriegshymnenklans verantwortlich, wo es zu einem gefährlichen Mangel an wichtigen Werkzeugen gekommen ist. Lieferungen wurden im Eschental und darüber hinaus verzögert, gestohlen oder abgefangen. Sollte er diese essenziellen Holzfällermaterialien nicht umgehend liefern, droht ihm ernster Ärger von seinen Vorgesetzten im Kriegshymnenklan.",al={"warum vorräte für locke okarr","warum vorräte für locke okarr sammeln","beweggrund von locke okarr"}},["54c7a3c1"]={q="Wofür werden die Sägeblätter des Kriegshymnenklans verwendet?",a="Die Sägeblätter sind entscheidende industrielle Komponenten für die mechanisierten Schredder und Mühlen, die im Holzfällerlager des Kriegshymnenklans betrieben werden. Ohne frische Sägeblätter können die schweren Holzfällermaschinen der Horde die massiven, uralten Bäume des Eschentals nicht effizient fällen, um Bauholz für den Bau von Orgrimmar und örtlichen Lagern zu liefern.",al={"wofür sind die sägeblätter","verwendung der sägeblätter des kriegshymnenklans","sägeblätter holzfällerlager"}},["9c63ad01"]={q="Wofür wird die Axtlieferung des Kriegshymnenklans verwendet?",a="Importiert aus den Goblinschmieden in Beutebucht, versorgt diese Kiste mit strapazierfähigen Äxten die Vorhut des Kriegshymnenklans und die Arbeiter, die dichtes Gestrüpp roden und das dichte Holz des Eschentals von Hand fällen. In einem feindseligen Wald, der von Nachtelfen und Bestien wimmelt, dienen diese robusten Werkzeuge gleichzeitig als verlässliche Kriegswaffen.",al={"wofür ist die axtlieferung","verwendung der axtlieferung des kriegshymnenklans","axtlieferung beutebucht"}},["74cafbab"]={q="Wofür wird das Öl des Kriegshymnenklans verwendet?",a="Das Öl des Kriegshymnenklans ist ein schweres Schmiermittel, das benötigt wird, damit die Dampfmaschinen, Schredder und komplexen Holzfällanlagen des Lagers unter harten Bedingungen reibungslos funktionieren. Ohne es blockieren die schweren Eisenwerke und bringen den Holzbetrieb vollständig zum Erliegen.",al={"wofür ist das öl des kriegshymnenklans","zweck des öls des kriegshymnenklans","warum öl für das holzfällerlager"}},["76a0db14"]={q="Wofür wird das Holzfällerseil verwendet?",a="Dieses haltbare Hochleistungsseil wird von den Mannschaften des Holzfällerlagers verwendet, um massive Baumstämme nach dem Fällen zu ziehen, zu sichern und hochzuheben. Die riesigen Bäume des Eschentals ohne angemessene Ausrüstung zu bewältigen, ist nahezu unmöglich und birgt das Risiko, Arbeiter zu zerquetschen oder wertvolle Ausrüstung zu beschädigen.",al={"wofür ist das holzfällerseil","zweck des holzfällerseils","seil kriegshymnenlager"}},["4e02126d"]={q="Warum bittet Locke Okarr einen Abenteurer anstelle der Wachen des Außenpostens?",a="Die Garnison des Splitterholzpostens ist dünn besetzt, da sie sich gegen ständige Einfälle der Schildwachen der Silberschwingen und feindseliger Waldbewohner verteidigen muss. Locke kann keine unverzichtbaren Wachen von der Peripherie abziehen, noch kann er seinen Posten persönlich verlassen, um entlegene Winkel des Eschentals zu durchsuchen und bis nach Beutebucht zu reisen.",al={"warum ich locke okarr","warum können wachen keine vorräte beschaffen","warum nicht die wachen schicken"}}},fp="16,175,25.277.0,27.361.0,39.194.0,19.186.0,51.263.0,35.173.0,38.139.0,53.281.0"}
P.entries["quest:658"] = {n="Hinweise auf eine neue Seuche?",s="Bei Go'Sheks Hof halten Quae und Kin seit Tagen Wache, und Kin sah eine Kurierin ein kleines Haus im Süden verlassen. Sie vermuten, dass sie Notizen nach Tarrens Mühle bringt, also bittet Quae Euch, ihre Spur aufzunehmen und die Dokumente zurückzubringen.",h="Bei Go'Sheks Hof halten Quae und Kin seit Tagen Wache, und Kin sah eine Kurierin ein kleines Haus im Süden...",kw={"apotheker","arathihochland","forsaken courier","go'sheks hof","kin","phin odelic","quae","versiegelter ordner","tarrens mühle"},sec={{t="Wache am Hof",b="Quae hat erwartet, dass Phin Odelic Euch schickt. Nach Quaes Ansicht macht er sich zu viele Sorgen. Quae und Kin beobachten den Hof seit Tagen, und kürzlich sah Kin eine Kurierin ein kleines Haus im Süden verlassen. Kin redet oft, aber Quae vertraut in gefährlichen Gegenden auf Kins Sinne."},{t="Der Ordner der Kurierin",b="Quae fragt, ob Ihr ein geschickter Fährtenleser seid. Die Kurierin könnte Notizen für Tarrens Mühle bei sich tragen, und die Dokumente könnten Licht darauf werfen, was in Hillsbrad geschieht. Findet die Forsaken Courier und bringt ihren Versiegelten Ordner zu Quae nahe Go'Sheks Hof.\n\nWährend Ihr sucht, sieht Kin einen Apotheker dasselbe Haus verlassen. Quae vermutet, dass der Apotheker nichts Gutes im Schilde führt, braucht aber Beweise, bevor jemand unüberlegt handelt."}},faq={{q="Wer hat Euch geschickt, um Quae und Kin zu finden?",a="Phin Odelic hat Euch geschickt, um nach Quae und Kin zu sehen. Quae hat es erwartet, da Phin sich zu viele Sorgen macht.",al={"wer schickt mich zu quae","wer startet hinweise auf eine neue seuche","phin odelic quest"}},{q="Woher kam die Kurierin?",a="Kin sah die Kurierin ein kleines Haus im Süden verlassen.",al={"woher kommt die kurierin","standort der kurierin","haus südlich des hofs"}},{q="Wohin ist die Kurierin unterwegs?",a="Quae und Kin vermuten, dass die Kurierin Notizen für Tarrens Mühle bei sich trägt.",al={"ziel der kurierin","wohin geht die kurierin"}},{q="Welchen Gegenstand sollt Ihr beschaffen?",a="Bringt den Versiegelten Ordner der Forsaken Courier zu Quae nahe Go'Sheks Hof.",al={"welchen gegenstand hat die kurierin","versiegelter ordner"}},{q="Wer wurde noch bei dem Haus gesehen?",a="Während Ihr fort wart, sah Kin einen Apotheker dasselbe Haus im Süden verlassen.",al={"apotheker am hof","wer kam aus dem haus"}},{q="Warum möchte Quae die Dokumente haben?",a="Die Dokumente könnten Licht darauf werfen, was in Hillsbrad geschieht. Quae braucht Beweise, bevor jemand unüberlegt handelt.",al={"warum die dokumente beschaffen","wozu dienen die notizen"}}},fp="22,215,17.252.0,20.399.0,34.93.0,32.53.0,29.69.0,35.69.0,34.83.0,33.109.0"}
P.entries["quest:6581"] = {n="Sägeblätter des Kriegshymnenklans",s="Am Splitterholzposten warten die Holzfäller des Kriegshymnenklans auf Sägeblätter aus Ratschet. Ihre Kurierin Pixel tauscht die Lieferung gegen eine Waffe, um sich auf Eschentals gefährlichen Straßen zu schützen. Die Sägeblätter halten die Holzfällerlager der Horde in Betrieb.",h="Am Splitterholzposten warten die Holzfäller des Kriegshymnenklans auf Sägeblätter aus Ratschet.",kw={"eschental","tödliche donnerbüchse","pixel","ratschet","splitterholzposten","vorhut des kriegshymnenklans","sägeblätter des kriegshymnenklans","warsong supplies"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr auf Eschentals Holzfällerlager angewiesen, die Bauholz für Orgrimmar liefern. Jede Maschinenlieferung hilft, die Lager in Betrieb zu halten.",["profession:Engineering"]="Als Ingenieur könnt Ihr die Tödliche Donnerbüchse herstellen, die Pixel will. Die Ingenieurskunst liefert Waffen und Maschinen für die Kriegsanstrengungen der Horde.",["race:Orc"]="Als Orc wisst Ihr, dass der Kriegshymnenklan unter Grommash Hellscream seinen Stolz in den Holzeinschlag in Eschental setzt. Wenn die Sägeblätter weiterlaufen, stärkt das den Stützpunkt des Klans im Wald."},sec={{t="Der kluge Tausch einer Kurierin",b="Pixel hat schwere Sägeblätter aus Ratschet zum Splitterholzposten gebracht, doch sie will sie nicht verschenken. In Eschentals Wildnis zählt Sicherheit für sie mehr als Münzen. Sie verlangt dafür eine Tödliche Donnerbüchse, damit sie sich auf den gefährlichen Straßen durch feindliches Gebiet verteidigen kann."},{t="Nachschub für den Krieg",b="Die Horde braucht Holz aus Eschental, um die Engpässe in ganz Durotar und im Brachland zu lindern. In den uralten Hainen werden Äxte schnell stumpf, weshalb die Holzfäller des Kriegshymnenklans auf goblingeschmiedete Sägeblätter angewiesen sind. Pixels Lieferung versorgt die Holzfällerlager, wo die Horde trotz erbitterten Widerstands der Nachtelfen Holz für Außenposten und Kriegsmaschinen schlägt."}},faq={{q="Wer ist Pixel und warum hat sie die Sägeblätter?",a="Pixel ist eine Kurierin am Splitterholzposten, die Sägeblätter aus Ratschet gebracht hat. Sie hält die Lieferung zurück, bis sie eine Waffe zu ihrem Schutz bekommen kann.",al={"wer ist pixel","pixie splintertree","sägeblattkurierin"}},{q="Warum will Pixel eine Tödliche Donnerbüchse statt Gold?",a="Auf der gefährlichen Straße vom Brachland nach Eschental zählt Sicherheit für Pixel mehr als Münzen. Sie verlangt eine Tödliche Donnerbüchse, um sich auf ihren Reisen zu verteidigen.",al={"warum tödliche donnerbüchse","pixels waffentausch","warum eine schusswaffe"}},{q="Warum sind diese Sägeblätter so wichtig für die Horde?",a="Der Kriegshymnenklan braucht Holz für die Außenposten und Kriegsmaschinen der Horde. An Eschentals uralten Bäumen verschleißen Äxte, weshalb die Holzfällerlager auf importierte mechanische Sägeblätter angewiesen sind.",al={"warum werden sägeblätter gebraucht","bedeutung des holzes für den kriegshymnenklan","warum warsong supplies"}},{q="Woher stammen die Sägeblätter ursprünglich?",a="Die Sägeblätter stammen aus Ratschet und wurden über Land zum Splitterholzposten gebracht.",al={"herkunft der sägeblätter","sägeblätter aus ratschet","woher kamen die sägeblätter"}},{q="Welche Rolle spielt diese Quest beim Holzeinschlag des Kriegshymnenklans?",a="Die Sägeblätter gehören zu den Vorräten, die nötig sind, um die Holzfällerlager des Kriegshymnenklans in Eschental in Betrieb zu halten.",al={"lieferkette von warsong supplies","voraussetzung für sägeblätter des kriegshymnenklans"}},{q="Kann jeder die Waffe herstellen, die Pixel will?",a="Geschickte Ingenieure können aus Kupferrohren, Kupferbolzen, einem Holzschaft und Leder eine Tödliche Donnerbüchse herstellen. Kuriere und Krieger können auch auf örtlichen Märkten oder bei anderen Abenteurern eine eintauschen.",al={"wie bekommt man eine tödliche donnerbüchse","bezugsquelle für donnerbüchse","schusswaffe aus ingenieurskunst"}}},fx={["496db877"]={q="Wofür ist die Tödliche Donnerbüchse?",a="Pixel benötigt persönlichen Schutz in der Wildnis. Als Kurier, der Fracht durch ungezähmte Gebiete wie das Eschental und das Brachland transportiert, ist es gefährlich, allein zu reisen. Anstelle von Gold, das Bestien oder Nachtelfen nicht abwehren kann, verlangt sie eine verlässliche technische Schusswaffe, damit sie unterwegs auf sich selbst aufpassen kann.",al={"warum donnerbüchse","tödliche donnerbüchse pixel","wofür benutzt pixel die donnerbüchse"}}},fp="18,235,25.287.0,24.331.0,50.149.0,57.158.0,51.178.0,46.79.0,58.99.0,39.200.0"}
P.entries["quest:659"] = {n="Hinweise auf eine neue Seuche?",s="In Hillsbrad sucht Phin Odelics Gruppe nach Anzeichen für Schwierigkeiten. Quae und Kinelory werden seit Tagen vermisst, nachdem sie zu Go'Sheks Hof im Arathihochland gereist sind.",h="In Hillsbrad sucht Phin Odelics Gruppe nach Anzeichen für Schwierigkeiten.",kw={"arathihochland","go'sheks hof","vorgebirge des hügellands","kinelory","phin odelic","quae","stanley"},sec={{t="Seltsame Vorfälle",b="Phin Odelics Cousin in Hillsbrad musste seinen Hund Stanley einschläfern. Das Tier war auf mystische Weise riesig geworden und griff jeden an, der sich näherte. Phin vermutet, dass die Untoten hinter diesen seltsamen Vorfällen stecken. Deshalb sucht seine Gruppe nach Hinweisen, um das zu beweisen."},{t="Die vermissten Gefährten",b="Quae und Kinelory reisten zu Go'Sheks Hof im Arathihochland. Sie haben sich seit Tagen nicht gemeldet, und Phin fürchtet um sie. Er bittet Euch, sie in der Nähe des Hofes zu finden."}},faq={{q="Wer ist Phin Odelic?",a="Phin Odelic führt eine Gruppe an, die seltsame Vorfälle in der Gegend untersucht.",al={"phin odelic","wer gibt hinweise auf eine neue seuche","questgeber"}},{q="Was ist mit Stanley geschehen?",a="Stanley war der Hund von Phins Cousin in Hillsbrad. Das Tier wurde auf mystische Weise riesig und griff jeden an, der sich näherte, weshalb der Cousin es einschläferte.",al={"stanley hund","was ist mit dem hund geschehen","stanley hillsbrad"}},{q="Wo sollen Quae und Kinelory sein?",a="Quae und Kinelory brachen zu Go'Sheks Hof im Arathihochland auf. Phin hat seit Tagen nichts von ihnen gehört.",al={"wo ist quae","wo ist kinelory","quae aufenthaltsort","quae finden"}},{q="Warum stellt Phin Nachforschungen an?",a="Phin vermutet, dass die Untoten hinter den seltsamen Vorfällen stecken. Seine Gruppe sucht nach Hinweisen, um das zu beweisen.",al={"warum go'sheks hof","go'sheks hof untote","go'sheks hof untersuchen"}}},fp="22,165,14.244.0,22.167.0,19.70.0,25.139.0,43.110.0,26.100.0"}
P.entries["quest:66"] = {n="Die Legende von Stalvan",s="Madame Evas Vision in Dunkelhain nennt Stalvan und warnt vor dem Tod ihrer Enkelin Alyssa. Sie schickt Euch zum Rathaus von Dunkelhain, um die Aufzeichnungen zu durchsuchen.",h="Madame Evas Vision in Dunkelhain nennt Stalvan und warnt vor dem Tod ihrer Enkelin Alyssa.",kw={"alyssa","amtmann daltry","dunkelhain","todeskarte","dämmerwald","madame eva","stalvan","rathaus"},ang={["class:Priest"]="Als Priester auf Dunkelhains finsteren Straßen achtet Ihr womöglich auf spirituelle Warnungen. Madame Evas Todesomen verlangt nach Eurem seelsorgerischen Beistand.",["faction:Alliance"]="Da der Dämmerwald keine Unterstützung durch reguläre Truppen aus Sturmwind erhält, helfen Abenteurer der Allianz oft den Stadtältesten und beschützen Familien wie die von Madame Eva."},sec={{t="Eine Vision des Todes",b="In Dunkelhain legt Madame Eva beunruhigten Einheimischen die Karten und deutet Vorzeichen. Eine schreckliche Störung reißt sie aus dem Schlaf, und sie zieht die Todeskarte für ihre junge Enkelin Alyssa. Eva versetzt sich in tiefe Trance, um zu erfahren, was das Omen bedeutet. Ein Hinweis offenbart sich ihr: der Name Stalvan. Aus Sorge um ihre Familie und die Stadt bittet sie Euch, diesem Namen nachzugehen, bevor eine Tragödie geschieht."},{t="Nachforschungen im Rathaus",b="Madame Eva schickt Euch über den Platz zum Rathaus von Dunkelhain. Durchsucht dort die Aufzeichnungen nach Stalvan und sprecht mit Amtmann Daltry, der die Geschäftsbücher und öffentlichen Archive der Stadt verwaltet. Er kann helfen festzustellen, ob Stalvan einst in Dunkelhain lebte, als Reisender durchkam oder zur Vergangenheit des Dämmerwalds gehört."}},faq={{q="Wer ist Madame Eva?",a="Madame Eva ist eine Wahrsagerin und Seherin, die in Dunkelhain lebt. Sie legt Karten und versetzt sich in Trance, um Vorzeichen zu erkennen und magische Störungen im ganzen Dämmerwald zu erspüren.",al={"madame eva","wer ist eva","wahrsagerin dunkelhain"}},{q="Warum braucht Madame Eva Hilfe?",a="Madame Eva fürchtet nach einer Todesvision um ihre Enkelin Alyssa. Beim Kartenlegen erschien die Todeskarte, und ihre Trance offenbarte den Namen Stalvan, weshalb sie Hilfe bei den Nachforschungen sucht.",al={"warum stalvan beginnen","evas vision","warum eva helfen"}},{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry verwahrt Dunkelhains Aufzeichnungen im Rathaus. Er verwaltet die Geschäftsbücher, Register und historischen Dokumente der Stadt und kann zu unbekannten Namen befragt werden.",al={"amtmann daltry","daltry","wer ist der amtmann"}},{q="Was ist das Rathaus von Dunkelhain?",a="Das Rathaus von Dunkelhain beherbergt die Beamten der Stadt, historische Aufzeichnungen und den Führungsstab der Nachtwache.",al={"rathaus von dunkelhain","rathaus dämmerwald"}},{q="Wer ist Alyssa?",a="Alyssa ist Madame Evas junge Enkelin und lebt in Dunkelhain. Evas Kartenlegung warnte vor einem tödlichen Omen für sie, das mit jemandem namens Stalvan verbunden ist.",al={"alyssa","madame evas enkelin"}},{q="Wohin führen diese Nachforschungen als Nächstes?",a="Das Gespräch mit Amtmann Daltry führt Euch zu städtischen Aufzeichnungen und früheren Nachforschungen. Von dort erstreckt sich die Suche über den Dämmerwald und benachbarte Regionen, um Stalvans Vergangenheit und Schicksal aufzudecken.",al={"stalvan nächster schritt","was sagt daltry"}}},fx={aeb2106e={q="Wer ist Stalvan?",a="Zum jetzigen Zeitpunkt ist Stalvan kaum mehr als ein schattenhafter Name, der durch Madame Evas Weissagung flüstert. Beunruhigt durch eine Vorahnung tödlicher Gefahr für ihre Enkelin Alyssa, legte Eva ihre Karten und begab sich in eine tiefe Trance, um Antworten zu finden. Der Tod wurde offenbart, zusammen mit nur diesem einen Namen. Ihr werdet ausgesandt, um in den alten Aufzeichnungen von Dunkelhain aufzudecken, wer Stalvan war.",al={"wer ist stalvan","wer stalvan","was ist stalvan"}},["9e863436"]={q="Warum bittet Madame Eva Euch anstelle der The Nachtwache?",a="Madame Eva verlässt sich auf Omen und Weissagungen anstelle konventioneller Verbrechen, was es schwierig macht, einen obskuren Namen aus einer Kartenlegung formell vor die The Nachtwache zu bringen. Da Dunkelhain bereits von Wölfen, Spinnen und den Untoten belagert wird, ist die örtliche Garnison bis an ihre Grenzen damit beschäftigt, die Stadtgrenze zu verteidigen. Sie benötigt einen unabhängigen Abenteurer, der bereit ist, in ihrem Auftrag diskret in alten städtischen Aufzeichnungen zu graben.",al={"warum bittest du mich","warum nicht die stadtwache","warum nicht die the night watch"}}},fp="21,160,17.366.0,22.301.0,18.166.0,30.180.0,20.166.0,28.109.0,14.145.0,40.185.0"}
P.entries["quest:660"] = {n="Hinweise auf eine neue Seuche?",s="Kinelory ist bereit, zum Bauernhof hinunterzugehen, und bittet Euch, sie zu begleiten. Sie fürchtet, die Untoten könnten Hillsbrad Schaden zufügen, während sie warten. Ihr werdet gebraucht, um sie sicher zurückzubringen.",h="Kinelory ist bereit, zum Bauernhof hinunterzugehen, und bittet Euch, sie zu begleiten.",kw={"geleit","vorgebirge des hügellands","hinweise auf eine neue seuche","kinelory","seuche","quae"},sec={{t="Kinelory den Rücken freihalten",b="Nach den bisherigen Schritten der Untersuchung ist Kinelory bereit zu handeln. Sie bittet Euch, mit ihr zum Bauernhof hinunterzugehen und dann sicher zu Quae zurückzukehren. Die Menschen von Hillsbrad brauchen sie unter Eurem Schutz."},{t="Eine sichere Rückkehr",b="Quae dankt Euch, als Kinelory zurückkehrt. Quae gesteht, sie habe gehofft, Kinelory würde nicht allzu anstrengend sein. Kinelory ist freundlich, doch für ihre Feinde tödlich."}},faq={{q="Wer schickt Euch auf diesen Geleitauftrag?",a="Kinelory bittet Euch, sie zu begleiten, sobald sie zum Aufbruch bereit ist.",al={"questgeber","wer vergibt die quest","wer startet hinweise auf eine neue seuche 4"}},{q="Wohin muss Kinelory gehen?",a="Kinelory geht zu einem Bauernhof hinunter und kehrt dann zu Quae zurück.",al={"geleitroute","wohin geht kinelory","kinelorys ziel"}},{q="Bei wem erstattet Ihr nach Abschluss Bericht?",a="Ihr erstattet Quae Bericht, sobald Kinelory zu ihr zurückgekehrt ist.",al={"quest abgeben","wer schließt die quest ab","wo quest abgeben"}},{q="Was ging diesem Teil der Untersuchung unmittelbar voraus?",a="Der dritte Teil von Hinweise auf eine neue Seuche? führt zu diesem Teil der Untersuchung.",al={"vorherige quest","voraussetzung","was kommt davor"}},{q="Was folgt nach der sicheren Rückkehr?",a="Die Untersuchung wird mit ihrem fünften Teil fortgesetzt.",al={"nächste quest","what comes next","folgequest"}},{q="Warum muss Kinelory beschützt werden?",a="Kinelory braucht Schutz, damit sie sicher zurückkehren kann, während die Untoten den Menschen von Hillsbrad Schaden zufügen könnten.",al={"warum kinelory beschützen","warum ist kinelory wichtig"}}},fp="22,168,24.188.0,13.154.1,29.62.0,31.51.0,35.53.0,54.83.0,36.48.0,31.101.0"}
P.entries["quest:6607"] = {n="Nat Pagle, Angler Extreme",s="Nat Pagle bittet Euch, ihm vier Fischarten von weit entfernten Küsten und Flüssen zu bringen. Der Fang stammt aus den Sümpfen des Elends, Desolace, Feralas und dem Schlingendorntal.",h="Nat Pagle bittet Euch, ihm vier Fischarten von weit entfernten Küsten und Flüssen zu bringen.",kw={"angler extreme","feralas ahi","angeln","misty reed mahi mahi","nat pagle","sar'theris-barsch","savage coast blue sailfin"},sec={{t="Vier Gewässer",b="Nat Pagle wartet in den Sümpfen des Elends auf vier Fische aus ganz Azeroth. Ihr sollt ihm einen Misty Reed Mahi Mahi, einen Sar'theris-Barsch, einen Feralas Ahi und einen Savage Coast Blue Sailfin bringen. Jeder stammt von einer bestimmten Küste oder aus einem bestimmten Fluss, und Nat erwartet Euch mit dem vollständigen Fang zurück."}},faq={{q="Welche Fische möchte Nat Pagle?",a="Nat Pagle bittet um einen Misty Reed Mahi Mahi, einen Sar'theris-Barsch, einen Feralas Ahi und einen Savage Coast Blue Sailfin.",al={"nat pagle fische","angler extreme fischliste"}},{q="Wo finde ich den Misty Reed Mahi Mahi?",a="Den Misty Reed Mahi Mahi gibt es am Nebelschilfstrand in den Sümpfen des Elends.",al={"misty reed mahi fundort","fische aus den sümpfen des elends"}},{q="Woher stammt der Sar'theris-Barsch?",a="Der Sar'theris-Barsch stammt vom Sar'therisstrand in Desolace.",al={"sar'theris-barsch fundort","fische aus desolace"}},{q="Wo finde ich einen Feralas Ahi?",a="Den Feralas Ahi gibt es im Verdantis in Feralas.",al={"feralas ahi fundort","feralas fische"}},{q="Wo findet man einen Savage Coast Blue Sailfin?",a="Den Savage Coast Blue Sailfin gibt es an der ungezähmten Küste des Schlingendorntals.",al={"blue sailfin fundort","fische von der ungezähmten küste"}},{q="Was soll ich tun, nachdem ich die Fische gefangen habe?",a="Kehrt mit allen vier Fischen zu Nat Pagle zurück.",al={"wohin mit den fischen","nat pagle abgabe"}}},fp="25,184,14.340.0,32.127.0,38.81.0,35.62.0,31.48.0,46.87.0,55.50.0"}
P.entries["quest:6608"] = {n="Ihr zu gut",s="Lumak schickt Euch von Orgrimmar aus auf die Suche nach seinem Freund Nat Pagle. Euer Können übersteigt gewöhnliche Lektionen, und Nat lagert auf einer abgelegenen kleinen Insel südlich der Insel Theramore.",h="Lumak schickt Euch von Orgrimmar aus auf die Suche nach seinem Freund Nat Pagle.",kw={"angeln als fachmann","düstermarschen","lumak","nat pagle","orgrimmar","theramore","ihr zu gut"},ang={["faction:Horde"]="Selbst während des Fraktionskrieges können Menschen durch ein gemeinsames Handwerk oder einen Zeitvertreib über die Fronten hinweg Verbindungen knüpfen.",["race:Orc"]="Als Ork könnt Ihr in Lumaks Freundschaft über die feindlichen Linien hinweg seine Geduld, seinen Humor und seinen Respekt vor der Natur erkennen."},sec={{t="Lumaks Grenzen",b="Lumak unterrichtet Angler im Tal der Ehre in Orgrimmar. Er erkennt, dass Ihr alles gelernt habt, was er Euch über Rute und Rolle beibringen kann. Also gibt er zu, dass Ihr für gewöhnliche Lektionen zu gut seid. Angeln als Fachmann erfordert Wissen jenseits der Stadt und der Horde."},{t="Eine ungewöhnliche Freundschaft",b="Lumak schickt Euch auf die Suche nach seinem menschlichen Freund Nat Pagle. Obwohl Horde und Allianz in ganz Kalimdor aufeinanderprallen, warnt er Euch davor, Nat etwas anzutun oder ihn zu essen. Nat lagert auf einer kleinen Insel in den Düstermarschen, südlich der Insel Theramore. Er hält sich aus der Politik heraus und interessiert sich nur dafür, ob die Fische anbeißen."}},faq={{q="Wer schickt mich auf diese Quest?",a="Lumak, der Angellehrer im Tal der Ehre in Orgrimmar, schickt Euch los, sobald Euer Können den Expertenrang übersteigt.",al={"wer startet ihr zu gut","lumak questgeber","wo gibt es ihr zu gut"}},{q="Wo befindet sich Nat Pagle?",a="Nat Pagle lagert auf einer kleinen Insel vor der Küste der Düstermarschen, südlich der Insel Theramore.",al={"wo ist nat pagle","nat pagle standort","nat pagle finden"}},{q="Warum hat ein Ork einen menschlichen Freund?",a="Lumak und Nat Pagle wurden durch das Angeln Freunde. Ihre gemeinsame Leidenschaft überwindet die erbitterte Rivalität zwischen Orks und Menschen.",al={"lumak und nat pagle freundschaft","warum ist nat pagle mit einem ork befreundet"}},{q="Was geschieht, wenn ich mit Nat Pagle spreche?",a="Nat Pagle stellt Euch vor eine anspruchsvolle Prüfung. Ihr reist durch Azeroth und fangt seltene Fische, bevor er Euch weiter unterrichtet.",al={"was lehrt nat pagle","quest für angeln als fachmann"}},{q="Kann die Horde Theramore gefahrlos durchqueren?",a="Nein. Theramore ist eine befestigte Stadt, die von der Allianz bewacht wird. Um Nats Insel zu erreichen, folgt der Küste oder umgeht die Stadt, um den Wachen auszuweichen.",al={"kann die horde theramore durchqueren","als hordler zu nat pagle gelangen"}},{q="Warum kann Lumak mich nicht selbst weiter ausbilden?",a="Lumak hat Euch alles beigebracht, was er weiß. Nat Pagle kann Euch das Angeln als Fachmann lehren, und Angler in der ganzen bekannten Welt betrachten ihn als Legende.",al={"warum lumak die ausbildung beendet","angeln vom experten zum fachmann horde"}}},fp="13,160,14.234.0,22.281.0,27.109.0,27.87.0,36.124.0,39.115.0,44.139.0,41.134.0"}
P.entries["quest:661"] = {n="Hinweise auf eine neue Seuche?",s="In Arathi bleiben Quae und Kinelory nahe dem Hof, während Ihr Nachricht nach Süderstade bringt. Quae hat die Gegenstände vom Hof, und Kinelory ist sicher zurückgekehrt.",h="In Arathi bleiben Quae und Kinelory nahe dem Hof, während Ihr Nachricht nach Süderstade bringt.",kw={"arathihochland","verlassene","hillsbrad","kinelory","phin odelic","seuche","quae","süderstade"},sec={{t="Nachricht für Süderstade",b="Quae ist zufrieden damit, wie Ihr auf Kinelory aufgepasst habt. Sie sagt, Kinelory sei in besserer Verfassung als nach einer Nacht in der Taverne. Die Gegenstände vom Hof sollten Phin Odelic helfen zu verstehen, was in Arathi geschieht.\n\nDa der Hof angegriffen wurde, wollen Quae und Kinelory noch etwas länger dort bleiben, falls jemand Vergeltung übt. Sie bitten Euch, nach Süderstade zurückzukehren und mit Phin zu sprechen."},{t="Phins Antwort",b="Phin ist froh zu hören, dass Quae und Kinelory am Leben und wohlauf sind. Er nennt sie unersetzliche Freunde und Reisegefährten. Im Namen der gesamten Gruppe dankt er Euch mit einem Geschenk.\n\nPhin hofft, dass sie mit etwas Glück herausfinden werden, was die Verlassenen planen, und dem ein Ende setzen können."}},faq={{q="Wer schickt Euch zu Phin Odelic?",a="Quae bittet Euch, nach Süderstade zu gehen, sobald Kinelory sicher vom Hof zurückgekehrt ist.",al={"wer vergibt hinweise auf eine neue seuche fünf","wer startet hinweise auf eine neue seuche","quae quest"}},{q="Warum kehren Quae und Kinelory nicht selbst nach Süderstade zurück?",a="Quae und Kinelory wollen noch etwas länger in Arathi bleiben, falls jemand Vergeltung für den Angriff auf den Hof übt.",al={"warum bleibt quae in arathi","warum zurückbleiben","quae bleibt"}},{q="Wo ist Phin Odelic zu finden?",a="Phin Odelic ist in Süderstade.",al={"phin odelic aufenthaltsort","wo ist phin","phin odelic süderstade"}},{q="Welchen Zweck hat es, Phin Odelic Nachricht zu bringen?",a="Die Gegenstände, die Kinelory vom Hof mitgebracht hat, sollten Phin Odelic helfen zu verstehen, was in Arathi geschieht.",al={"warum phin besuchen","phin odelic zweck","was will phin"}}},fp="22,144,19.375.0,13.283.1,40.77.0,64.110.0,31.29.0,52.104.0"}
P.entries["quest:6610"] = {n="Muschelette Surprise",s="Dirge Schnetzelhack braucht Zutaten für seine Muschelette Surprise, eine neue kulinarische Kreation. Dafür bietet er Euch an, exotische Küche beizubringen und ein paar davon zuzubereiten.",h="Dirge Schnetzelhack braucht Zutaten für seine Muschelette Surprise, eine neue kulinarische Kreation.",kw={"alteraclochkäse","muschelette","muschelette surprise","dirge schnetzelhack","exotische küche","rieseneier","würziges muschelfleisch"},ang={["profession:Cooking"]="Als Koch könnt Ihr von Dirge Schnetzelhack die Feinheiten der exotischen Küche lernen."},sec={{t="Ein neues Rezept",b="Dirge Schnetzelhack möchte Euch zeigen, wie er seine Muschelette Surprise zubereitet. Dafür braucht er Rieseneier, würziges Muschelfleisch und Alteraclochkäse. Bringt ihm die gewünschten Zutaten, und Dirge bringt Euch während der Zubereitung des Gerichts die exotische Küche näher."}},faq={{q="Was ist eine Muschelette?",a="Eine Muschelette ist Dirge Schnetzelhacks neueste kulinarische Kreation, zubereitet aus Rieseneiern, würzigem Muschelfleisch und Alteraclochkäse.",al={"muschelette surprise","was ist eine muschelette"}},{q="Wer bittet um die Zutaten?",a="Dirge Schnetzelhack möchte die Zutaten für seine Muschelette Surprise.",al={"wer will die zutaten","dirges quest"}},{q="Welche Zutaten braucht Dirge?",a="Dirge braucht Rieseneier, würziges Muschelfleisch und Alteraclochkäse.",al={"muschelette-zutaten","was soll ich sammeln"}},{q="Wo finde ich die Rieseneier?",a="Die Rieseneier stammen von Rocs, die Tanaris durchstreifen, oder von anderen großen Vögeln.",al={"rieseneier fundort","wo gibt es eier"}},{q="Woher kommt das würzige Muschelfleisch?",a="Würziges Muschelfleisch findet Ihr in Muscheln.",al={"muschelfleisch quelle","würziges muschelfleisch"}},{q="Wo bekomme ich Alteraclochkäse?",a="Dirge sagt, Ihr sollt Alteraclochkäse in einer Käserei besorgen.",al={"alteraclochkäse quelle","käse für dirge"}},{q="Was bietet Dirge im Gegenzug?",a="Dirge bietet Euch an, Euch die Feinheiten der exotischen Küche beizubringen und ein paar Clamlettes zuzubereiten.",al={"was bekomme ich","dirge bringt es bei"}}},fp="18,154,12.259.0,20.117.0,34.66.0,33.59.0,32.73.0,41.38.0,30.48.0,32.104.0"}
P.entries["quest:6611"] = {n="Ab mit Euch nach Gadgetzan!",s="In Orgrimmar schickt Zamja erfahrene Horde-Köche nach Süden, um von einem exzentrischen Goblinmetzger zu lernen.",h="In Orgrimmar schickt Zamja erfahrene Horde-Köche nach Süden, um von einem exzentrischen Goblinmetzger zu...",kw={"artisan cooking","kochkunst","dirge schnetzelhack","gadgetzan","orgrimmar","tanaris","tal der stärke","zamja"},ang={["faction:Horde"]="Orgrimmar ist auf auswärtige Spezialisten angewiesen, darunter neutrale Goblinköche, damit seine Handwerker mehr als die üblichen Grundgerichte der Stämme erlernen.",["profession:Cooking"]="Als Koch erreicht Ihr den Punkt, an dem die Ausbildung in der Hauptstadt endet. Dann müsst Ihr Euch in die gefährliche Wildnis wagen, um bei einem Meister seines Fachs zu lernen."},sec={{t="Ein Koch entwächst Orgrimmar",b="Im Spalt bildet Zamja Köche aus und versorgt Krieger und Reisende, die Durotar durchqueren. Wenn ein Koch jedes Rezept und jede Technik gelernt hat, die sie kennt, hat Zamja alles gelehrt, was sie kann. Sie schickt ihren Schüler nach Tanaris, wo nur ein Meister seltsamer und exotischer Fleischsorten einem talentierten Koch weiterhelfen kann."},{t="Der Metzger in der Wüste",b="Gadgetzan ist ein dampfbetriebenes Handelszentrum in Tanaris, das vom Steamwheedle Cartel geführt wird. Dirge Schnetzelhack arbeitet in der Taverne der Stadt. Der exzentrische Goblinmetzger hat einen ungewöhnlichen Geschmack und kennt beim Essen keine Skrupel. In ganz Kalimdor ist er dafür bekannt, aus monströsen Wüstenkreaturen und manchmal auch Lederresten herzhafte Mahlzeiten für abgehärtete Abenteurer zuzubereiten."}},faq={{q="Wer schickt Euch nach Gadgetzan?",a="Zamja, die trollische Kochkunstlehrerin bei den Kochfeuern im Spalt von Orgrimmar, schickt Köche dorthin, die alles beherrschen, was sie weiß.",al={"questgeber","wer startet das","zamjas quest"}},{q="Warum schickt Zamja Euch fort?",a="Zamja hat alle Rezepte und Techniken gelehrt, die sie vermitteln kann. Sie schickt vielversprechende Köche zu Dirge Schnetzelhack in Tanaris, einem exzentrischen Experten, der aus kargen Wüstenzutaten Mahlzeiten zubereitet.",al={"warum gadgetzan","warum dirge schnetzelhack","kochmeister"}},{q="Wer ist Dirge Schnetzelhack?",a="Dirge Schnetzelhack ist ein Goblinmetzger und Lehrmeister der Kochkunst im Gasthaus von Gadgetzan. Er hat ein raues Wesen, seltsame Vorstellungen von Ernährung und findet Eiweiß in alten Lederstiefeln. Er beherrscht das Kochen mit exotischen Zutaten aus der Wildnis.",al={"wer ist dirge","dirge gadgetzan"}},{q="Ist diese Quest erforderlich, um Artisan Cooking zu erlernen?",a="Nein. Zamjas Empfehlung weist Horde-Köchen den Weg nach Tanaris. Ein Koch mit genügend Fertigkeit kann direkt nach Gadgetzan reisen und mit Dirge Schnetzelhack sprechen.",al={"ist diese quest nötig","hinführungsquest kochkunst","ist es pflicht"}},{q="Wo liegt Gadgetzan?",a="Gadgetzan ist ein ummauertes Wüstenhandelszentrum unter der Führung des Steamwheedle Cartel im Norden von Tanaris, weit im Süden Kalimdors, südlich von Tausend Nadeln.",al={"gadgetzan lage","wo ist dirge"}},{q="Lernt Zamja tatsächlich etwas, wenn Ihr zurückkehrt?",a="Zamja fordert Euch keck auf, zurückzukehren und sie zu unterrichten, sobald Ihr der größte Koch weit und breit seid. Sie bleibt eine erfahrene Lehrerin in Orgrimmar und hütet ihre Kochfeuer für die nächste Generation von Reisenden.",al={"lernt zamja kochen","zamja unterrichten"}}},fp="20,95,25.295.0,25.364.0,27.117.0,29.181.0,24.239.0,48.146.0,27.138.0,51.194.0"}
P.entries["quest:662"] = {n="Tiefsee-Bergung",s="Nach Land Ho! bittet Euch Erster Maat Nilzlix, die Seekarten und Logbücher aus zwei Wracks zu bergen, bevor jemand die Bucht verlässt.",h="Nach Land Ho!",kw={"arathihochland","beutebucht","tiefsee-bergung","harbinger","maiden's folly","nilzlix","o'breen","seehorn","spirit of silberwald"},sec={{t="Zwei Schiffe im Riff verloren",b="O'Breen führte drei Schiffe in die Bucht, überzeugt, dass dort ein Schatz lag. Die Harbinger legte sicher an. Doch die Maiden's Folly und die Spirit of Silberwald erreichten das Riff, als die Ebbe einsetzte. Beide stießen gegen ein tempelartiges Bauwerk und sanken rasch."},{t="Was Nilzlix zurückhaben will",b="Erster Maat Nilzlix möchte, dass Ihr die Logbücher und Seekarten aus beiden Wracks bergt. Er fürchtet, die Informationen könnten neugierigen Blicken ausgesetzt sein. Sollten Feinde sie finden, würde Flottenmeister Seehorn die Mannschaft über die Planke schicken."}},faq={{q="Warum sind die Maiden's Folly und die Spirit of Silberwald gesunken?",a="Die Maiden's Folly und die Spirit of Silberwald liefen in die Bucht ein, als die Ebbe einsetzte. Beide stießen gegen ein tempelartiges Bauwerk im Riff und sanken schnell.",al={"warum erlitten die schiffe schiffbruch","wie sind die schiffe gesunken","arathi bucht ursache des schiffbruchs"}},{q="Wer ist Erster Maat Nilzlix?",a="Erster Maat Nilzlix erzählt von den drei Schiffen, die O'Breen in die Bucht führte. Er möchte, dass Ihr die Logbücher und Seekarten aus den beiden gesunkenen Schiffen bergt.",al={"nilzlix","wer vergibt tiefsee-bergung"}},{q="Warum sind die Seekarten und Logbücher so wichtig?",a="Nilzlix fürchtet, dass die zurückgelassenen Informationen neugierigen Blicken ausgesetzt sind. Sollten Feinde sie in die Hände bekommen, würde Flottenmeister Seehorn die Mannschaft über die Planke schicken, sagt er.",al={"warum logbücher bergen","warum seekarten und logbücher"}},{q="Welches Schiff erreichte die Bucht sicher?",a="Nur die Harbinger legte sicher in der Bucht an. Die anderen beiden Schiffe sanken.",al={"welches schiff überstand es","harbinger schiff"}},{q="Wer ist Flottenmeister Seehorn?",a="Nilzlix nennt Flottenmeister Seehorn als denjenigen, der die Mannschaft über die Planke schicken würde, sollten die Aufzeichnungen in feindliche Hände geraten.",al={"rolle von flottenmeister seehorn","wer ist seehorn"}},{q="Was kam vor dieser Aufgabe?",a="Land Ho! kam davor.",al={"tiefsee-bergung voraussetzung","vorherige quest"}}},fp="16,121,26.247.0,23.206.0,57.158.0,26.142.0,41.157.0,28.71.0,28.117.0,27.26.0"}
P.entries["quest:6621"] = {n="König der Fäulnisklauen",s="Am Außenposten von Zoram'gar befiehlt Karang Amakkar einen Schlag gegen die Fäulnisklauen. Champions der Horde errichten ein Kriegsbanner auf dem heiligen Totemhügel des Stammes, locken Häuptling Murgut hervor und töten ihn.",h="Am Außenposten von Zoram'gar befiehlt Karang Amakkar einen Schlag gegen die Fäulnisklauen.",kw={"eschental","fäulnisklauen","furbolg","laubtatzenlichtung","karang amakkar","murgut","totemhügel","zoram'gar"},ang={["class:Shaman"]="Als Schamane erkennt Ihr in den verzerrten Totems und der Aggression der Fäulnisklauen Zeichen des spirituellen Ungleichgewichts, das die einheimischen Stämme des Eschentals nach der Invasion der Brennenden Legion heimsuchte.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie Karang Amakkar feindselige Stämme mit Machtdemonstrationen einschüchtert und zentrale Pfade für Versorgungskarawanen der Horde sichert.",["race:Orc"]="Als Ork wisst Ihr, dass es eine klassische Kriegstaktik ist, einen feindlichen Häuptling zum Zweikampf zu reizen. Sie setzt auf Stärke und eine entscheidende Konfrontation statt auf lange Scharmützel."},sec={{t="Eine Show of Force",b="Von seinem Posten am Außenposten von Zoram'gar aus sieht Karang Amakkar die verderbten Fäulnisklauen als Gefahr für die Horde. Der Stamm ist kleiner als die nördlichen Distelfelle, doch seine Mitglieder sind wild. Deshalb befiehlt Karang eine Machtdemonstration, um ihren Willen zu brechen, bevor sie Hordenpatrouillen aus dem Hinterhalt angreifen können."},{t="Entweihung und Herausforderung",b="Die Laubtatzenlichtung liegt nordöstlich des Mystralsees. Karang bereitet ein Stammeskriegsbanner für die Mitte des Totemhügels der Fäulnisklauen vor und beleidigt damit die Ahnengeister und den Stolz des Stammes. Die Verteidiger stürmen herbei, um es niederzureißen, und Häuptling Murgut tritt hervor, um seine Ehre im offenen Kampf zu verteidigen. Sein persönliches Totem an sich zu nehmen, zerschlägt die Führung des Stammes und begründet die Vorherrschaft der Horde in diesem Gebiet."}},faq={{q="Wer befiehlt den Tod von Häuptling Murgut?",a="Karang Amakkar, ein Ork am Außenposten von Zoram'gar an der Westküste des Eschentals, befiehlt Häuptling Murguts Tod, nachdem er die benachbarten Distelfellfurbolgs untersucht hat.",al={"questgeber könig der fäulnisklauen","wer vergibt könig der fäulnisklauen","karang amakkar quest"}},{q="Wo liegt die Laubtatzenlichtung?",a="Die Laubtatzenlichtung liegt südöstlich von Astranaar, nordöstlich des Mystralsees und unmittelbar südlich der östlichen Hauptstraße des Eschentals.",al={"wo liegt die laubtatzenlichtung","fäulnisklauen standort","wo karangs banner aufstellen"}},{q="Warum errichtet die Horde ein Banner auf dem Totemhügel?",a="Karangs Banner beleidigt die Fäulnisklauen auf ihrem heiligen Totemhügel. Die Provokation treibt sie zum Angriff und lockt Häuptling Murgut in den offenen Kampf, um sein Ansehen zu verteidigen.",al={"warum banner aufstellen","zweck des banners auf dem totemhügel","warum murgut herausfordern"}},{q="Wer sind die Fäulnisklauenfurbolgs?",a="Die Fäulnisklauen sind einer der Furbolgstämme des Eschentals, die nach dem Dritten Krieg dem Wahnsinn und der Verderbnis verfielen. Obwohl sie weniger zahlreich sind als die Distelfelle, bleiben sie gewalttätig und Außenstehenden gegenüber feindselig.",al={"was sind die fäulnisklauen","geschichte des stammes der fäulnisklauen","wer ist häuptling murgut"}},{q="Was bewirkt es, Murguts Totem zu beschaffen?",a="Häuptling Murguts Totem zum Außenposten von Zoram'gar zu bringen, beweist seine Niederlage. Ohne ihren Anführer und mit ihrem entweihten heiligen Hügel sind die überlebenden Fäulnisklauen so eingeschüchtert, dass sie weitere Konflikte mit der Horde meiden.",al={"murguts totem zweck","was geschieht nach murguts tod"}},{q="Wie knüpft diese Quest an die früheren Untersuchungen der Furbolgs an?",a="Nachdem Karang sich in „Between a Rock and a Thistlefur“ mit den nördlichen Distelfellen befasst hat, wendet er sich nach Süden zu den Fäulnisklauen. Er will sie vernichten, bevor sie koordinierte Überfälle starten können.",al={"between a rock and a thistlefur zusammenhang","voraussetzung könig der fäulnisklauen"}}},fx={b1528232={q="Warum will Karang Amakkar, dass Chief Murgut besiegt wird?",a="Karang Amakkar betrachtet den Foulweald-Stamm als eine wachsende Gefahr für den Stützpunkt der Horde im Eschental. Obwohl sie zahlenmäßig geringer sind als die benachbarten Thistlefur, macht sie ihre schiere Wildheit zu einer unberechenbaren Bedrohung. Indem er eine direkte Herausforderung ausspricht und ihren Häuptling tötet, zielt Karang darauf ab, ihren Willen zu brechen und eine unmissverständliche Warnung auszusprechen, dass die Horde im Wald keinerlei Bedrohungen dulden wird.",al={"beweggrund von karang","warum murgut töten","warum foulweald besiegen"}},["9b8cfe09"]={q="Wer ist Chief Murgut?",a="Chief Murgut ist der wilde Anführer der Foulweald-Furbolgs, die in der Laubtatzenlichtung südöstlich von Astranaar leben. Er behält die Herrschaft über den Stamm von ihrem heiligen Totemhügel aus und führt durch reine Stärke und territoriale Aggression. Karang schickt Euch, um ihn zu einem offenen Kampf zu provozieren, indem Ihr das Stammesgebiet mit einem Kriegsbanner der Horde schändet.",al={"wer ist murgut","chief murgut foulweald","wer ist der king of the foulweald"}}},fp="21,189,15.274.0,25.382.0,37.162.0,34.126.0,53.171.0,31.190.0,47.216.0,64.182.0"}
P.entries["quest:6622"] = {n="Triage",s="Ihr sollt verwundete Soldaten mit Triage Bandages retten. Ihre Verletzungen lassen kaum Zeit für Verzögerungen.",h="Ihr sollt verwundete Soldaten mit Triage Bandages retten.",kw={"schwer verwundet","kritisch verwundet","verwundete soldaten","patienten","soldaten","triage","triage bandagen","wunden"},sec={{t="Die Verwundeten",b="Critically Injured Soldiers erliegen ihren Verletzungen zuerst, danach folgen Badly Injured Soldiers. Injured Soldiers halten am längsten durch. Die Reihenfolge der Versorgung ist entscheidend, wenn Ihr fünfzehn Patienten retten wollt, bevor sechs ihren Wunden erliegen."}},faq={{q="Was soll ich tun?",a="Ihr sollt mit Triage Bandages fünfzehn Patienten retten, bevor sechs ihren Verletzungen erliegen.",al={"triage-quest","was ist triage","soldaten retten"}},{q="Welchen Soldaten geht es am schlechtesten?",a="Critically Injured Soldiers sterben am schnellsten, gefolgt von Badly Injured Soldiers.",al={"wer stirbt am schnellsten","kritische soldaten","schwerstverletzte"}},{q="Wer kann am längsten warten?",a="Injured Soldiers sterben am langsamsten und sollten nach den schwerer Verwundeten versorgt werden.",al={"reihenfolge der verwundeten soldaten","wer kommt zuletzt","leichtverletzte"}},{q="Wofür sind Triage Bandages gedacht?",a="Triage Bandages dienen dazu, die Wunden der Soldaten zu versorgen.",al={"bandagen verwenden","triage bandagen","wie patienten retten"}}},fp="6,104,11.215.0,28.97.0,38.80.0,21.96.0,29.57.0"}
P.entries["quest:6623"] = {n="Traumachirurg der Horde",s="In Hammerfall im Arathihochland ruft „Traumachirurg der Horde“ erfahrene Heiler an die Front. Doktor Gregory Victor braucht helfende Hände, die unter extremem Druck Leben retten können.",h="In Hammerfall im Arathihochland ruft „Traumachirurg der Horde“ erfahrene Heiler an die Front.",kw={"arathihochland","doktor gregory victor","erste hilfe","hammerfall","traumachirurg der horde","arnok","triage"},ang={["class:Priest"]="Als Priester könnt Ihr Wunden mit göttlicher Magie schließen. Weltliche Triage lehrt Euch einzuschätzen, wer noch gerettet werden kann, wenn Euer Mana versiegt.",["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch auf zähe Schlachtfeldchirurgen, die Grunzer zusammenflicken und in brutalen Grenzkonflikten wie denen im Arathihochland kampffähig halten."},sec={{t="Ein Ruf aus Hammerfall",b="Im Tal der Geister in Orgrimmar teilt Arnok, der Orc-Lehrer für Erste Hilfe, versierten Heilern mit, dass sie Doktor Gregory Victors Aufmerksamkeit erregt haben. Victor leitet den Traumachirurgen der Horde von Hammerfall in den umkämpften Hügeln des Arathihochlands aus. Arnok betrachtet diesen Ruf als die höchste Stufe in der Laufbahn eines Schlachtfeldchirurgen."},{t="Die harte Arbeit der Schlachtfeldtriage",b="In Hammerfall überfluten ständige Scharmützel mit Stromgardes Streitkräften und feindseligen örtlichen Fraktionen Doktor Victor mit verwundeten Grunzern, Räubern und Spähern. Der Chefarzt hält sich nicht mit Höflichkeiten auf. Er schickt Neuankömmlinge in ihre Kittel, damit sie sich bei einer rasanten, brutalen Notfalltriage beweisen."}},faq={{q="Was ist der Traumachirurg der Horde?",a="Der Traumachirurg der Horde ist der medizinische und chirurgische Zweig der Horde an der Front. Doktor Gregory Victor leitet ihn von Hammerfall aus, wo seine Mitglieder Kampfverletzungen behandeln und mitten im Chaos Notfalltriage durchführen.",al={"traumachirurg der horde fraktion","was ist traumachirurg der horde","wer sind die traumachirurgen der horde"}},{q="Wer schickt mich auf diesen Einsatz?",a="Arnok, der Orc-Lehrer für Erste Hilfe im Tal der Geister in Orgrimmar, überbringt den Ruf. Er betrachtet den Dienst unter Doktor Gregory Victor als die höchste Stufe in der Laufbahn eines angehenden Feldsanitäters.",al={"questgeber traumachirurg der horde","wer startet traumachirurg der horde","krenk choplimb","arnok"}},{q="Wo befindet sich Doktor Gregory Victor?",a="Doktor Gregory Victor ist im Lazarett von Hammerfall im nordöstlichen Arathihochland stationiert.",al={"doktor gregory victor standort","wo ist victor","hammerfall arzt"}},{q="Was geschieht nach der Meldung in Hammerfall?",a="Bei Eurer Ankunft fordert Doktor Victor Euch auf, für den Folgeauftrag Triage Eure Kittel anzulegen. Unter hohem Druck bestimmt Ihr die Behandlungsreihenfolge und versorgt verwundete Soldaten, deren Zustand sich rasch verschlechtert, bevor sie ihren Verletzungen erliegen.",al={"was folgt auf traumachirurg der horde","nächste quest nach traumachirurg der horde","triage quest"}},{q="Warum braucht Hammerfall so dringend Feldsanitäter?",a="Hammerfall ist in Arathi von Feindseligkeiten umgeben und steht ständig im Konflikt mit menschlichen Streitkräften, Syndikatsagenten und örtlichen Wildtieren. Verwundete strömen ins Lager und bringen das kleine medizinische Personal an seine Grenzen.",al={"warum braucht hammerfall sanitäter","hammerfall medizinische lage"}},{q="Können Spieler der Allianz diesen Auftrag annehmen?",a="Nein. „Traumachirurg der Horde“ ist für Mitglieder der Horde bestimmt. Die Allianz hat eine entsprechende medizinische Prüfung unter der Leitung von Doktor Gustav van Howzen auf der Insel Theramore.",al={"kann die allianz traumachirurg der horde machen","allianzversion von traumachirurg der horde"}}},fx={ac636cdf={q="Warum schickt Arnok mich zu Doktor Gregory Victor?",a="Doktor Gregory Victor, der Chefarzt von Horde Trauma in Hammerfall, hat persönlich nach Euch gefragt. Arnok schätzt Doktor Victor sehr und hält es für die Gelegenheit seines Lebens, unter ihm zu lernen – eine Gelegenheit, für die er nach eigenen Worten alles geben würde. Aus tiefem beruflichem Respekt und Begeisterung für Euer Talent möchte Arnok sicherstellen, dass Ihr eine solch seltene Berufung nicht verschwendet.",al={"warum will krenk das","beweggrund von krenk choplimb","warum zu victor schicken","warum will arnok das","beweggrund von arnok"}},b6720468={q="Warum bittet Doktor Victor speziell um mich?",a="Doktor Gregory Victor sucht die fähigsten Feldsanitäter der Horde, um sich den Reihen von Horde Trauma im Arathihochland anzuschließen. Eure bewiesene Meisterschaft in Erster Hilfe hat in Hammerfall seine Aufmerksamkeit erregt, was zu einer direkten persönlichen Vorladung führte, damit Ihr unter ihm trainieren könnt, anstatt unerprobte Rekruten oder gewöhnliche Soldaten aufzunehmen.",al={"warum ich horde trauma","warum braucht victor mich","warum will doktor victor mich"}}},fp="12,171,25.318.0,37.292.0,21.204.0,32.190.0,39.111.0,43.233.0,48.221.0,42.145.0"}
P.entries["quest:6625"] = {n="Traumachirurg der Allianz",s="In der gesamten Allianz werden erfahrene Sanitäter zum Dienst auf die Insel Theramore entsandt. Dort lernt Ihr bei Doktor Gustav van Howzen, dem leitenden Arzt des medizinischen Elitekorps der Allianz.",h="In der gesamten Allianz werden erfahrene Sanitäter zum Dienst auf die Insel Theramore entsandt.",kw={"traumachirurg der allianz","düstermarschen","erste hilfe","eisenschmiede","nissa feuerstein","theramore","triage","van howzen"},ang={["faction:Alliance"]="Der Traumachirurg der Allianz ermöglicht Frontkämpfern in ganz Kalimdor und den Östlichen Königreichen Zugang zu erfahrenen Sanitätern. Diese können lebensgefährliche Verletzungen unter Beschuss stabilisieren.",["race:Dwarf"]="Als Zwerg könnt Ihr die Aufmerksamkeit von Ausbildern wie Nissa Feuerstein in Eisenschmiede erregen. Sie sucht vielversprechende Sanitäter aus der Großen Schmiede für den medizinischen Dienst in Theramore."},sec={{t="Ruf an die Front",b="Euer Geschick mit Nadel, Stoff und Triage hat die Aufmerksamkeit von Doktor Gustav van Howzen geweckt. Von der Insel Theramore aus leitet er den Traumachirurgen der Allianz und versorgt Verwundete in Kalimdors erbittertsten Kriegsgebieten und darüber hinaus."},{t="Der Weg nach Theramore",b="In Eisenschmiede betrachtet Nissa Feuerstein Van Howzens persönliche Vorladung als seltenes Privileg. Die Insel Theramore ist regionalen Bedrohungen, Scharmützeln und rauer Wildnis ausgesetzt, weshalb unablässig schwer verwundete Soldaten eintreffen.\n\nIhr überquert das Meer zu den Düstermarschen. Dort prüft Van Howzen anhand seiner strengen Triage-Maßstäbe, wie besonnen Ihr den Zustand der Verwundeten beurteilt."}},faq={{q="Was ist der Traumachirurg der Allianz?",a="Der Traumachirurg der Allianz ist das medizinische Elitekorps der Allianz, das sich der Schlachtfeldmedizin und der Notfalltriage widmet. Der leitende Arzt Gustav van Howzen führt es und behandelt lebensbedrohliche Wunden, bei denen gewöhnliche Feldverbände nicht ausreichen.",al={"traumachirurg der allianz hintergrund","wer ist der traumachirurg der allianz"}},{q="Wer schickt Euch auf diese Quest?",a="Erste-Hilfe-Ausbilder der Allianz entsenden vielversprechende Sanitäter, sobald diese die grundlegende Ausbildung in ihren Städten gemeistert haben. Nissa Feuerstein in Eisenschmiede ist eine solche Ausbilderin.",al={"wer vergibt traumachirurg der allianz","eisenschmiede erste-hilfe-questgeber"}},{q="Wohin müsst Ihr reisen?",a="Ihr reist auf die Insel Theramore, eine Hafenfestung der Menschen an Kalimdors Ostküste in den Düstermarschen.",al={"wo ist van howzen","traumachirurg der allianz ziel"}},{q="Wer ist Doktor Gustav van Howzen?",a="Doktor Gustav van Howzen leitet den Traumachirurgen der Allianz als dessen leitender Arzt. Er arbeitet im Lazarett von Theramore und zählt zu den führenden Experten der Allianz für Notfallmedizin und chirurgische Triage.",al={"gustav van howzen","leitender arzt van howzen"}},{q="Was geschieht nach der Meldung bei Doktor Van Howzen?",a="In Theramore unterzieht Van Howzen die Anwärter einer praktischen Triage-Prüfung. Sie müssen beweisen, dass sie Welle um Welle sterbender Soldaten retten können, bevor er sie in die höheren Ränge der Feldmedizin aufnimmt.",al={"was folgt auf traumachirurg der allianz","triage nächste quest"}},{q="Warum liegt das Lazarett in Theramore statt in Sturmwind oder Eisenschmiede?",a="Theramore ist eine aktive Grenzgarnison inmitten unwirtlicher Sümpfe, gefährlicher Bestien und territorialer Scharmützel. Ständig treffen lebensgefährlich verwundete Soldaten ein und sorgen im Lazarett für den anhaltenden Druck, den eine fortgeschrittene Ausbildung in der Traumaversorgung erfordert.",al={"warum lazarett in theramore","warum düstermarschen für traumaversorgung"}}},fx={a452e047={q="Warum schickt Nissa Feuerstein Euch nach Theramore?",a="Doktor Gustav van Howzen, der Chefarzt von Alliance Trauma, hat die persönliche Bitte geäußert, dass Ihr Euch seinen Reihen in Theramore anschließt. Nissa Feuerstein schätzt den renommierten Chirurgen sehr und betrachtet die Arbeit unter ihm als eine unvergleichliche Ehre. Sie leitet die Vorladung weiter, weil sie sicherstellen möchte, dass Ihr eine solch seltene medizinische Gelegenheit nicht verschwendet.",al={"warum will nissa dass dies getan wird","beweggrund von nissa feuerstein","warum nach theramore schicken"}},a6ba6381={q="Warum verlangt Doktor Gustav van Howzen nach Euch persönlich?",a="Doktor Gustav van Howzen benötigt fähige, erfahrene Feldmediziner, die unter Druck mit schweren Verletzungen umgehen können. Da Ihr Eure außergewöhnliche Meisterschaft in Erster Hilfe bewiesen habt, seid Ihr dem medizinischen Korps der Allianz aufgefallen, was Doktor Gustav van Howzen dazu veranlasste, Euch persönlich nach Theramore zu rufen, um Eure Fähigkeiten unter Feldbedingungen zu beurteilen.",al={"warum ich alliance trauma","warum will vanhowzen mich","warum spieler nach theramore schicken"}}},fp="15,183,19.199.0,21.353.0,24.216.0,28.169.0,28.100.0,31.206.0,49.183.0,71.231.0"}
P.entries["quest:6626"] = {n="A Host of Evil",s="Myriam Moonsinger bittet Euch, Euch den Verteidigern und Kultisten der Hügel der Klingenhauer zu stellen. Ihre Anwesenheit ist das Problem, um das Ihr Euch in ihrem Auftrag kümmern sollt.",h="Myriam Moonsinger bittet Euch, Euch den Verteidigern und Kultisten der Hügel der Klingenhauer zu stellen.",kw={"a host of evil","death's head cultists","myriam moonsinger","razorfen battleguard","hügel der klingenhauer","razorfen thornweavers"},sec={{t="Myriams Bitte",b="Nahe dem Eingang zu den Hügeln der Klingenhauer bittet Myriam Moonsinger Euch, Euch dort den Razorfen Battleguard, Razorfen Thornweavers und Death's Head Cultists zu stellen. Sie erwartet, dass Ihr zu ihr zurückkehrt, nachdem Ihr Euch um sie gekümmert habt."}},faq={{q="Wer bittet bei den Hügeln der Klingenhauer um Hilfe?",a="Myriam Moonsinger bittet Euch nahe dem Eingang zu den Hügeln der Klingenhauer, Euch deren Verteidigern und Kultisten zu stellen.",al={"wer ist myriam","myriam moonsinger"}},{q="Welche Feinde nennt Myriam?",a="Myriam nennt Razorfen Battleguard, Razorfen Thornweavers und Death's Head Cultists.",al={"gegen wen kämpfen","razorfen feinde"}},{q="Wo finde ich Myriam bei meiner Rückkehr?",a="Kehrt zu Myriam Moonsinger nahe dem Eingang zu den Hügeln der Klingenhauer zurück.",al={"wo ist myriam","myriams standort"}}},fp="14,136,18.212.0,36.104.0,31.84.0,28.64.0"}
P.entries["quest:6627"] = {n="Test der Lehre",s="An Braug Dimspirits Zuflucht im Steinkrallengebirge erwartet Euch eine Prüfung der uralten Geschichte. Nachdem Ihr den Wälzer Vermächtnis der Aspekte geborgen habt, müsst Ihr zeigen, was Ihr daraus gelernt habt. Eine falsche Antwort schickt Euch weit über Kalimdor.",h="An Braug Dimspirits Zuflucht im Steinkrallengebirge erwartet Euch eine Prüfung der uralten Geschichte.",kw={"aspekte","braug dimspirit","erdwächter","neltharion","steinkrallengebirge","taurajo","test of faith","der wetterwinkel"},ang={["class:Mage"]="Als Magier erkennt Ihr vielleicht die Kunstfertigkeit hinter Braugs Teleportationszauber. Die Einsiedler des Steinkrallengebirges nutzen uralte Magie, um nachlässige Gelehrte zu disziplinieren.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch in Kalimdor Prüfungen, die mehr als rohe Gewalt verlangen. Von Kriegern wie Schamanen wird erwartet, dass sie die uralten Narben und Drachenmächte verstehen, die den Kontinent geprägt haben.",["race:Tauren"]="Als Tauren ehrt Ihr die Weisheit der Ahnen und die uralte Geschichte. Diese Prüfung verlangt von jungen Streitern, das Gleichgewicht der Welt zu verstehen, bevor sie sich in Gefahr begeben."},sec={{t="Eine Prüfung der Weisheit",b="Braug Dimspirits Prüfung folgt auf die Prüfungen, die Dorn Ebenenpirscher im Wetterwinkel begann. Sie verlangt Verständnis, nicht kriegerisches Überleben oder blindes Vertrauen. Braug lebt zwischen den zerklüfteten Felsen des Steinkrallengebirges. Er erwartet von Suchenden, uralte Schriften zu bergen und aus ihren Seiten zu lernen."},{t="Vermächtnis der Aspekte",b="Die Lektion handelt davon, wie die Drachenaspekte erschaffen und aufgeteilt wurden, und von ihrem Pakt lange vor der Großen Zerschlagung. Braug fragt, was der Wälzer über den Erdwächter Neltharion sagt. Sein Wahnsinn und sein Verrat veränderten Azeroths Oberfläche. Ihr müsst diese Geschichte verstehen, bevor Ihr dem Pfad der Weisheit weiter folgt."},{t="Der Preis des Ratens",b="Braug Dimspirit schickt Suchende, die falsch antworten, mit mystischen Mitteln fort. Eine falsche Antwort bringt Euch nach Camp Taurajo im Südlichen Brachland, weit weg vom Einsiedler. Um Euch erneut Braugs prüfendem Blick zu stellen, müsst Ihr den langen Rückweg ins Steinkrallengebirge antreten."}},faq={{q="Wie lautet die Antwort auf Braug Dimspirits Frage?",a="Braug fordert Euch auf, den Erdwächter aus Vermächtnis der Aspekte zu nennen. Die Antwort lautet Neltharion, der Black Aspect, der sich gegen seine Mitdrachen wandte.",al={"braugs frage beantworten","test der lehre antwort","vermächtnis der aspekte frage"}},{q="Was geschieht, wenn Ihr falsch antwortet?",a="Eine falsche Antwort führt zur sofortigen magischen Verbannung nach Camp Taurajo im Brachland. Ihr müsst zu Braugs Zuflucht im Steinkrallengebirge zurückreisen, um es erneut zu versuchen.",al={"falsche antwort test der lehre","test der lehre gescheitert","nach taurajo teleportiert"}},{q="Wer ist Braug Dimspirit?",a="Braug Dimspirit ist ein betagter Einsiedler im Steinkrallengebirge, der das Wissen und die Geschichtskenntnisse der Horde prüft. Er setzt die spirituellen Prüfungen fort, die Dorn Ebenenpirscher in Tausend Nadeln begann.",al={"braug dimspirit","wer vergibt test der lehre"}},{q="Wie hängt dies mit den Prüfungen in Tausend Nadeln zusammen?",a="Dorn Ebenenpirscher begann die Prüfungen im Wetterwinkel in Tausend Nadeln mit Test of Faith. Nachdem er körperliches und spirituelles Vertrauen geprüft hat, schickt Dorn würdige Anwärter quer durch Kalimdor zu Ältesten, die ihren Verstand, ihre Entschlossenheit und ihre Stärke prüfen.",al={"dorn ebenenpirscher verbindung","test of faith questreihe"}},{q="Zu welchem Buch befragt Euch Braug?",a="Braug prüft Euer Verständnis von Vermächtnis der Aspekte, einer uralten Abhandlung darüber, wie die Titanen die fünf großen Drachenaspekte segneten, damit sie Azeroth bewachen.",al={"welches buch braug","vermächtnis der aspekte"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Wer Braugs Prüfung über die Drachenaspekte besteht, erforscht als Nächstes weitere Teile der uralten Geschichte. Suchende müssen ferne Regionen nach verschollenen Aufzeichnungen und dem Wissen der Ahnen durchsuchen.",al={"was folgt auf test der lehre","nächste quest bei test der lehre"}}},fx={a70a9b29={q="Warum prüft Euch Braug Dimspirit?",a="Braug Dimspirit fungiert als Prüfer bei den Prüfungen, die in Tausend Nadeln begannen. Während andere Prüfungen Euer kriegerisches Können oder Euren Glauben herausfordern, wurde der Test of Lore entwickelt, um sicherzustellen, dass Ihr Euch nicht nur auf rohe Gewalt verlasst. Indem er von Euch verlangt, alte Texte zu beschaffen und deren Inhalt zu verstehen, möchte Braug Weisheit und historisches Verständnis bei denjenigen kultivieren, die danach streben, die Horde zu repräsentieren.",al={"warum prüft euch braug","braug dimspirit ziel","warum test of lore"}}},fp="12,217,17.284.0,21.322.0,22.247.1,49.147.0,39.164.0,23.185.0,56.247.0,38.150.0,38.176.0"}
P.entries["quest:6628"] = {n="Test der Lehre",s="In Unterstadt stellen sich Initianden bei Parqual Fintallas einer Prüfung ihres Geschichtswissens. Sie haben die Welt nach historischen Texten durchforstet, und dieses Examen gehört zu spirituellen Prüfungen, die in Tausend Nadeln begannen.",h="In Unterstadt stellen sich Initianden bei Parqual Fintallas einer Prüfung ihres Geschichtswissens.",kw={"dorn ebenenpirscher","lichkönig","mark of shame","nerzhul","parqual fintallas","test der lehre","tausend nadeln","unterstadt","der wetterwinkel"},ang={["faction:Horde"]="Als Mitglied der Horde stärkt Ihr die Bande zwischen Kalimdors Stämmen und dem Königreich unter Lordaeron und lernt, dass Weisheit für das Überleben ebenso wichtig ist wie Stärke.",["race:Tauren"]="Als Tauren folgt Ihr einer alten Tradition, die Euch aussendet, die düstere Geschichte Eurer nördlichen verbündeten Verlassenen und der Welt jenseits von Kalimdor kennenzulernen.",["race:Undead"]="Als Untoter begegnet Ihr einer Geschichte, die mit der Identität der Verlassenen verbunden ist: Ner'zhuls tragischer Verwandlung und dem Fluch, der Euch band, bevor Sylvanas den Griff des Lichkönigs brach."},sec={{t="Eine Prüfung des Wissens",b="Der Test der Lehre ist eine der spirituellen Prüfungen, die in Tausend Nadeln begannen. Dorn Ebenenpirscher rief die Prüfungen im Wetterwinkel ins Leben. Dieses Examen führt Anwärter aus den vom Wind geformten Schluchten von Tausend Nadeln nach Unterstadt, wo Parqual Fintallas ihr Geschichtswissen prüft und jedem Suchenden hohe Maßstäbe setzt."},{t="Die Entstehung der Geißel",b="Parqual Fintallas prüft Initianden anhand des Buches „Anfänge der Bedrohung durch die Untoten“, das erzählt, wie die Geißel in Lordaeron entstand. Er fragt nach dem Wesen auf dem Frostthron: Ner'zhul, einst ein Schamanenältester, dessen Essenz die Brennende Legion zum Lichkönig schmiedete. Dieser düstere Ursprung hilft, die Existenz der Verlassenen und die Gefahren zu erklären, denen Kalimdor und die Östlichen Königreiche gegenüberstehen."}},faq={{q="Wie lautet die Antwort auf Parquals Frage?",a="Parqual Fintallas fragt nach dem ursprünglichen Namen des Lichkönigs: Ner'zhul, dem uralten Orcschamanen, dessen Geist an den Frostthron gebunden wurde.",al={"lichkönig antwort","parqual frage","test der lehre antwort"}},{q="Was geschieht, wenn Ihr die Frage falsch beantwortet?",a="Eine falsche Antwort belegt Euch mit dem Schwächungszauber Mark of Shame. Ihr müsst warten, bis die Strafe abgelaufen ist, bevor Parqual Euch erneut zur Prüfung zulässt.",al={"mark of shame","falsche antwort test der lehre"}},{q="Wo beginnt diese Questreihe?",a="Dorn Ebenenpirscher beginnt die umfassendere Reihe spiritueller Prüfungen im Wetterwinkel in Tausend Nadeln, zwischen den hoch aufragenden Felsnadeln.",al={"wo beginnt test der lehre","dorn ebenenpirscher questreihe"}},{q="Wo befindet sich Parqual Fintallas?",a="Parqual Fintallas befindet sich in Unterstadt, zwischen den unterirdischen Bibliotheken und Gängen der Verlassenen, wo er angehende Schüler prüft.",al={"parqual finden","parqual fintallas standort"}},{q="Auf welchem Text beruht diese Prüfung?",a="Die Prüfung stützt sich auf „Anfänge der Bedrohung durch die Untoten“, ein Buch über die Ursprünge der Plague of Undeath und die Erschaffung des Lichkönigs.",al={"welches buch für test der lehre","beginnings buch"}},{q="Warum schickt eine Quest aus Tausend Nadeln Leute nach Unterstadt?",a="Die Prüfungen der Tauren fordern einen Abenteurer in jeder Hinsicht. Für dieses Examen überqueren Anwärter das Meer, um gelehrte Aufzeichnungen aufzusuchen, die in den Ruinen von Lordaeron aufbewahrt werden.",al={"warum nach unterstadt","tausend nadeln unterstadt"}}},fx={b37475e3={q="Warum will Parqual Fintallas, dass dies erledigt wird?",a="Parqual Fintallas stellt Eure Hingabe zum Streben nach Wissen auf die ultimative Probe. Er glaubt, dass Wissen in dieser gefährlichen Welt für das Überleben von größter Bedeutung ist – je mehr Ihr lernt und beobachtet, desto mehr von der Wahrheit werdet Ihr sehen. Da er Euch mit der Beschaffung des Wälzers über die Bedrohung durch die Untoten beauftragt hat, verlangt er den Beweis, dass Ihr dessen düstere Geschichte tatsächlich studiert und verinnerlicht habt, anstatt nur einen Botengang zu erledigen.",al={"parquals motiv","warum prüft mich parqual","warum test of lore"}}},fp="12,200,20.332.0,21.381.1,41.135.0,46.131.0,34.131.0,35.136.0,33.135.0,60.163.0"}
P.entries["quest:6629"] = {n="Tötet Grundig Finsterwolke",s="Am Posten der Grimmtotem wartet Grundig Darkcloud, der den Angriff auf Makaba Flachhufs Heimat anführte. Makaba schickt Euch gegen Grundig, sobald Ihr die Raufbolde und Söldner niedergestreckt habt.",h="Am Posten der Grimmtotem wartet Grundig Darkcloud, der den Angriff auf Makaba Flachhufs Heimat anführte.",kw={"schläger","darkcloud","flachhuf","grimmtotem","grundig","makaba","posten","steinkrallengebirge"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, wie wichtig das Steinkrallengebirge für Euren Vorstoß nach Kalimdor ist. Kriegsherren wie Grundig bedrohen die Versorgungswege zwischen dem Brachland und Sonnenfels.",["race:Tauren"]="Als Tauren seht Ihr, wie Grundigs Massaker die Zwietracht unter Eurem Volk vertieft. Die Grimmtotem bekämpfen die Einheit unter der Horde mit skrupelloser Gewalt."},sec={{t="Der Schlächter des Pfads",b="Makaba Flachhuf überlebte den Angriff der Grimmtotem auf seine Siedlung am Pfad im Steinkrallengebirge, doch die Trauer lastet noch immer auf ihm. Ihr habt Euch gegen die Fußsoldaten der Grimmtotem bewährt. Nun verweist Euch Makaba an Grundig Darkcloud, der das Massaker anführte, das das Dorf dem Erdboden gleichmachte, und eine ergebene Schar von Schlägern befehligt."},{t="Angriff auf den Posten der Grimmtotem",b="Grundig lagert am Posten der Grimmtotem, weiter oben an der Bergstraße im Westen. Ihr steigt zur Festung hinauf, um Makabas Angehörige zu rächen und den Pass vor weiterer Gewalt zu schützen. Dort kämpft Ihr Euch durch Grundigs Schläger und tötet ihn, bevor seine Plünderer über weitere schutzlose Lager herfallen können."}},faq={{q="Wer ist Grundig Darkcloud?",a="Grundig Darkcloud befehligt die Grimmtotem am Posten der Grimmtotem im südöstlichen Steinkrallengebirge. Er führte den Angriff an, der Makaba Flachhufs Dorf zerstörte.",al={"grundig darkcloud","wer ist grundig","anführer der grimmtotem"}},{q="Wo ist Grundig Darkcloud zu finden?",a="Grundig Darkcloud befindet sich am Posten der Grimmtotem, den Bergpfad hinauf westlich von Makaba Flachhufs Lager nahe der Grenze zum Brachland.",al={"grundigs standort","wo ist grundig","standort des postens der grimmtotem"}},{q="Was bewegt Makaba Flachhuf zu diesem Auftrag?",a="Makaba Flachhuf musste mitansehen, wie die Grimmtotem seine Heimat verwüsteten und seine Clangefährten abschlachteten. Nachdem Ihr ihre Raufbolde und Söldner niedergestreckt habt, bittet er Euch, zur Vergeltung ihren Anführer Grundig Darkcloud zu töten.",al={"warum grundig töten","makabas geschichte","makabas rache"}},{q="Warum greifen die Grimmtotem hier friedliche Siedlungen an?",a="Die Grimmtotem verachten andere Taurenstämme, besonders jene, die mit der Horde verbündet sind oder friedlichere Wege beschreiten. Sie überfallen rivalisierende Clans aus dem Hinterhalt und plündern sie, um sie aus Gebieten zu vertreiben, die die Grimmtotem beherrschen wollen.",al={"warum greifen die grimmtotem an","feindseligkeit der grimmtotem"}},{q="Was folgt auf den Tod von Grundig Darkcloud?",a="Nachdem Ihr Grundig Darkcloud und seine Schläger getötet habt, ist Makaba Flachhufs Rache vollendet. Er kann um sein Dorf trauern, im Wissen, dass der Gerechtigkeit Genüge getan wurde.",al={"was folgt nach grundig","fortsetzung der flachhuf-questreihe"}},{q="Welche Quest ist die Voraussetzung für diesen Auftrag?",a="Schließt zuerst Avenge My Village ab. Darin prüft Makaba Flachhuf Eure Entschlossenheit, indem er Euch gegen Raufbolde und Söldner der Grimmtotem schickt, die gleich im Westen lagern.",al={"voraussetzung für grundigs tötung","quest vor grundig"}}},fx={ce2e4f2e={q="Warum benötigt Makaba Flachhuf Eure Hilfe, anstatt selbst gegen Grundig zu kämpfen?",a="Makaba Flachhuf ist ein einsamer Überlebender, der auf der Bergstraße gestrandet ist, am Boden zerstört durch das Abschlachten seines Dorfes. Grundig Darkcloud befehligt den Posten der Grimmtotem, flankiert von einer persönlichen Vorhut aus wilden Bestien, die viel zu stark verteidigt ist, als dass ein einzelner, verwundeter Tauren sie direkt herausfordern könnte. Nachdem er gesehen hat, wie Ihr die einfachen Plünderer niedergemetzelt habt, setzt Makaba seine Hoffnung auf Vergeltung ganz in Eure Kampfkraft.",al={"warum ich makaba","warum kämpft makaba flachhuf nicht gegen grundig","warum schickt ihr mich kill grundig darkcloud"}}},fp="22,189,23.315.0,24.279.0,25.156.0,37.117.0,47.190.0,58.198.0,43.147.0,45.159.0"}
P.entries["quest:663"] = {n="Land in Sicht!",s="In der Faldirbucht warnt Euch Lolo, dass Kapitän O'Breens kurzer Halt weit länger dauern könnte als geplant. Die Spirit of Silberwald und die Maiden's Folly sind verloren, und Lolo verweist Euch an den Kapitän.",h="In der Faldirbucht warnt Euch Lolo, dass Kapitän O'Breens kurzer Halt weit länger dauern könnte als geplant.",kw={"beutebucht","die faldirbucht","harbinger","ausguck lolo","maiden's folly","seahorn","shakes o'breen","spirit of silberwald"},sec={{t="Lolos Begrüßung",b="Lolo begrüßt Euch in der Faldirbucht und erzählt Euch, was schiefgegangen ist. Kapitän O'Breen versprach der Mannschaft nur wenige Stunden an Land, um Schätze zu sammeln, bevor sie nach Beutebucht zurücksegeln würden. Lolo bezweifelt, dass sie nur so kurz fort sein werden.\n\nDie Spirit of Silberwald und die Maiden's Folly, zwei Schiffe der Formation, liegen nun auf dem Meeresgrund. Wenn Ihr bleiben wollt, sollt Ihr laut Lolo mit dem Kapitän sprechen."},{t="Der Bericht des Kapitäns",b="Kapitän O'Breen fürchtet, dass Seahorn das Schiff übernehmen wird, wenn sich die Nachricht von dem Unglück verbreitet. Ein Apparat des Professors wies auf verlorene Schätze nahe der Faldirbucht hin. Also legte die Harbinger dort an und gab den beiden anderen Schiffen das Signal, ihr zu folgen.\n\nDann grollte das Meer, und das Wasser wich zurück. Beide Schiffe liefen auf das Riff. O'Breen sagt, es sei kein gewöhnliches Riff, und dort unten liege etwas. Er verspricht jedem eine ansehnliche Bezahlung, der der Mannschaft hilft."}},faq={{q="Was ist mit den anderen Schiffen geschehen?",a="Die Spirit of Silberwald und die Maiden's Folly gingen verloren und liegen nun auf dem Meeresgrund.",al={"wo sind die anderen schiffe","versunkene schiffe faldir","was hat die schiffe versenkt"}},{q="Warum kam die Mannschaft zur Faldirbucht?",a="Kapitän O'Breen brachte die Mannschaft zur Faldirbucht, um Schätze zu sammeln. Sie rechneten damit, nur wenige Stunden zu bleiben, bevor sie nach Beutebucht zurücksegeln würden.",al={"warum sind sie hier","zweck der expedition","was führte sie nach arathi"}},{q="Mit wem solltet Ihr in der Faldirbucht sprechen?",a="Der Ausguck Lolo schlägt vor, dass Ihr mit Kapitän O'Breen in der Faldirbucht sprecht, wenn Ihr bleiben wollt.",al={"wer ist kapitän o'breen","wo ist shakes o'breen"}}},fp="8,195,14.382.0,21.442.1,33.87.0,39.142.0,40.94.0"}
P.entries["quest:664"] = {n="Ertrunkene Trauer",s="In der Faldirbucht trauert Kapitän Steelgut um die Maiden's Folly und bittet Euch, die Daggerspine-Naga zu töten, die die Überlebenden des Wracks erschlugen.",h="In der Faldirbucht trauert Kapitän Steelgut um die Maiden's Folly und bittet Euch, die Daggerspine-Naga zu...",kw={"arathi","daggerspine","die faldirbucht","maiden's folly","naga","o'breen","räuber","hexenmeisterin","steelgut"},sec={{t="Ein Kapitän am Feuer",b="In der Faldirbucht sitzt Kapitän Steelgut am Feuer und wünscht sich, das Meer hätte auch ihn geholt. Seine Mannschaft kämpfte hart, um die Maiden's Folly zu retten, doch plötzlich strömte Wasser herein und das Schiff sank. O'Breen erreichte sicher das Ufer, während die Naga die anderen Überlebenden töteten. Steelgut will zehn Daggerspine-Räuber und drei Daggerspine-Hexenmeisterinnen tot sehen."}},faq={{q="Wer ist Kapitän Steelgut?",a="Kapitän Steelgut befehligte die Maiden's Folly. Nach dem Verlust des Schiffes saß er an einem Feuer in der Faldirbucht.",al={"kapitän steelgut","steelgut","wer ist der questgeber"}},{q="Was geschah mit der Maiden's Folly?",a="Steelgut sagt, das Meer habe die Maiden's Folly versenkt. Das Schiff hielt sich über Wasser, dann strömte plötzlich Wasser herein, obwohl die Mannschaft hart um seine Rettung kämpfte.",al={"maidens folly","was geschah mit dem schiff","warum erlitt steelgut schiffbruch"}},{q="Warum will Kapitän Steelgut die Naga töten lassen?",a="Die Naga töteten die Überlebenden des Wracks, und Steelgut will sie tot sehen.",al={"warum naga töten","steelguts rache","daggerspine grund"}},{q="Welche Naga will Steelgut tot sehen?",a="Zehn Daggerspine-Räuber und drei Daggerspine-Hexenmeisterinnen, wie Steelgut es verlangt.",al={"welche naga töten","naga als ziel","daggerspine ziele"}}},fp="15,134,21.341.0,24.106.0,36.142.0,47.68.0,35.76.0"}
P.entries["quest:6641"] = {n="Vorsha die Peitscherin",s="Am Außenposten von Zoram'gar bedrohen Vorsha die Peitscherins Angriffe den Stützpunkt der Horde an Eschentals Küste. Die Naga in der Nähe ehren die Hydra mit einer Opferpfanne auf einer vorgelagerten Insel. Muglash will ihre Flamme löschen und Vorsha an Land locken.",h="Am Außenposten von Zoram'gar bedrohen Vorsha die Peitscherins Angriffe den Stützpunkt der Horde an Eschentals...",kw={"eschental","opferpfanne","hydra","muglash","naga","vorsha","der zoramstrand","zoram'gar"},ang={["faction:Horde"]="Die Verteidigung des Außenpostens von Zoram'gar bewahrt den nördlichen Stützpunkt der Horde in Eschental und seine Logistik, doch die Versorgungslinien dort werden ständig angegriffen.",["race:Orc"]="Als Orc teilt Ihr vielleicht Muglashs Weigerung, sich hinter behelfsmäßigen Palisaden zu verkriechen. Er zieht es vor, in die Brandung zu stürmen und räuberische Bestien im direkten Kampf zu jagen."},sec={{t="Ein Schrecken aus der Tiefe",b="An Eschentals nordwestlicher Küste zählt der Zoramstrand zu den gefährlichsten Küstenabschnitten. Der Außenposten von Zoram'gar hält dort einen schmalen Streifen gegen feindselige Wildtiere, Nachtelfen und schlangenartige Eindringlinge. Vorsha die Peitscherin gehört zu den schlimmsten Bedrohungen des Strandes. Die gewaltige Hydra greift den Außenposten ohne jeden Anlass an.\n\nSie bricht aus der Brandung hervor, um seine Befestigungen zu zermalmen und seine Krieger abzuschlachten. Dann verschwindet sie in den tiefen Fluten."},{t="Die Opferpfanne der Naga",b="Die Naga in der Nähe verehren Vorshas unersättliche Gewalttätigkeit. Auf einem Felsvorsprung vor der Küste halten sie eine Opferpfanne für sie am Brennen. Muglash, ein Orc, der den ständigen Überfällen auf den Außenposten ein Ende setzen will, hat einen Weg gefunden, die Hydra hervorzulocken.\n\nDie Entweihung der Ritualflamme wird die Nagawächter und Vorsha erzürnen. In ihrer Wut wird die Hydra an die Oberfläche schnellen und den Verteidigern Gelegenheit geben, sie in einen Hinterhalt zu locken, statt auf ein weiteres Blutbad zu warten."}},faq={{q="Wer ist Vorsha die Peitscherin?",a="Vorsha die Peitscherin ist eine gewaltige, wilde Hydra, die die Gewässer vor dem Zoramstrand heimsucht. Sie greift den Außenposten von Zoram'gar oft ohne jeden Anlass an, zerstört seine Befestigungen und schlachtet Angehörige der Horde ab.",al={"vorsha","was ist vorsha","vorsha hydra"}},{q="Warum verehren die Naga Vorsha?",a="Die Naga am Zoramstrand verehren Vorsha für ihre unerbittliche Wildheit und ihren zerstörerischen Appetit. Als Tribut an ihr bösartiges Wesen halten sie eine Opferpfanne vor der Küste am Brennen.",al={"warum mögen naga die hydra","vorsha naga opferpfanne","warum vorsha verehren"}},{q="Wie wird Vorsha zum Kampf hervorgelockt?",a="Muglash führt einen Angriff auf die Insel an, auf der die Naga Vorshas Opferpfanne hüten. Das Löschen der heiligen Flamme erzürnt die Nagawächter und Vorsha und treibt die Hydra zur Vergeltung an die Oberfläche.",al={"wie vorsha beschwören","wie vorsha rufen","opferpfanne insel vorsha"}},{q="Wer ist Muglash?",a="Muglash ist ein Orc, der am Außenposten von Zoram'gar stationiert ist. Vorshas grundlose Küstenangriffe leid, plant er, die rituelle Opferpfanne der Naga zu löschen und die Bestie an der Seite verlässlicher Verbündeter zu bekämpfen.",al={"wer ist muglash","muglash orc","zoramgar muglash"}},{q="Warum ist der Außenposten von Zoram'gar durch Küstenbestien gefährdet?",a="Der Außenposten von Zoram'gar ist ein abgeschiedenes Grenzlager an Eschentals ungeschützten Stränden. Naga beherrschen die Meeresruinen, während wilde Hydren die Brandung durchstreifen, sodass der Außenposten amphibischen Angriffen aus allen Richtungen ausgesetzt ist.",al={"warum wird zoramgar angegriffen","zoramstrand gefahr"}},{q="Was geschieht, nachdem Vorsha getötet wurde?",a="Nachdem Vorsha getötet wurde, wird der Sieg den Läufern des Kriegshymnenklans gemeldet, die am Außenposten von Zoram'gar die Verbindungslinien aufrechterhalten. Die ständige Last der Grenzwachen wird leichter, und die unmittelbare Küste ist vor plötzlichen Angriffen gesichert.",al={"vorsha quest abgeben","wem vorshas tod melden"}}},fx={["4cca3bd5"]={q="Warum will Muglash, dass Vorsha getötet wird?",a="Vorsha ist ein ständiger Schrecken für den Außenposten von Zoram'gar. Die bösartige Hydra bricht wiederholt unprovoziert aus dem Meer hervor und verwüstet die Streitkräfte der Horde und alles andere, was ihr an der Küste in den Weg kommt. Muglash zielt darauf ab, diese verheerenden Raubzüge ein für alle Mal zu beenden, indem er die Bestie an ihrem heiligen Beschwörungsort konfrontiert.",al={"muglashs motiv","warum vorsha töten","warum vorsha bekämpfen"}},["23eb1be6"]={q="Warum benötigt Muglash Eure Hilfe gegen Vorsha?",a="Die Tötung von Vorsha erfordert eine Reise zu einer Insel, die von Küsten-Naga gehalten wird, und das Löschen des heiligen Kohlebeckens, das sie zu ihren Ehren bewahren. Muglash beabsichtigt, an Eurer Seite zu kämpfen, aber er weiß, dass das Ritual nicht nur die riesige Hydra selbst, sondern auch Wellen wütender Naga-Verteidiger anlocken wird. Ein einzelner Krieger kann solche Massen nicht alleine aufhalten.",al={"warum braucht muglash hilfe","warum bewacht die horde vorsha nicht","warum ich muglash"}}},fp="17,243,22.435.0,23.448.0,25.200.0,29.163.0,33.193.0,15.192.0,54.209.0,35.213.1"}
P.entries["quest:665"] = {n="Versunkener Schatz",s="Professor Phizzlethorpe und Doktor Draxlegauge helfen nun den Blackwater Raiders bei der Suche nach einem verlorenen Elfenschatz. Bevor die Suche beginnen kann, braucht der Professor Euren Schutz, während er eine Brille für das dunkle Meer auflädt.",h="Professor Phizzlethorpe und Doktor Draxlegauge helfen nun den Blackwater Raiders bei der Suche nach einem...",kw={"arathihochland","blackwater raiders","draxlegauge","verzauberter stein","brille","o'breen","phizzlethorpe","versunkener schatz"},sec={{t="Die Brille aufladen",b="Professor Phizzlethorpe bittet Euch, ihn zu beschützen, während er eine Suche unter der Oberfläche des dunklen Meeres vorbereitet. Doktor Draxlegauge hat eine Brille gebaut, um die verlorenen Edelsteine zu finden, doch sie braucht die Kraft eines verzauberten Steins in einer Höhle ein kurzes Stück bergauf. Die Höhle ist verflucht, und wer sich ihr nähert, gerät in einen Hinterhalt. Verteidigt den Professor, während er die Energie des Steins in die Brille leitet."}},faq={{q="Wer bittet um Hilfe?",a="Professor Phizzlethorpe bittet Euch, ihn auf dem Weg zur Höhle und zurück zu beschützen, während er Doktor Draxlegauges Brille am verzauberten Stein auflädt.",al={"wer gibt diese quest","phizzlethorpe","questgeber"}},{q="Warum muss die Brille aufgeladen werden?",a="Doktor Draxlegauge hat die Brille gebaut, um die verlorenen Edelsteine im dunklen Meer zu finden. Sie braucht die Kraft des Steins, bevor sie funktionieren kann.",al={"warum brille aufladen","zweck der brille","wofür ist die brille"}},{q="Warum braucht der Professor Geleitschutz?",a="Die Höhle ist verflucht, und wer sich ihr nähert, gerät in einen Hinterhalt. Ihr müsst Professor Phizzlethorpe verteidigen, während er die Energie des Steins kanalisiert.",al={"warum phizzlethorpe beschützen","was ist in der höhle"}},{q="Für wen arbeiten der Professor und der Doktor?",a="Professor Phizzlethorpe sagt, dass er und Doktor Draxlegauge nun vollwertige Blackwater Raiders sind. Ihre Aufgabe ist es, Mr. O'Breen dabei zu helfen, den verlorenen Elfenschatz zu finden.",al={"wem helfen sie","mr obreen","blackwater raiders"}}},fp="15,226,20.358.0,23.149.0,38.127.0,38.140.0,49.161.0"}
P.entries["quest:666"] = {n="Versunkener Schatz",s="In der Faldirbucht leiht Euch Doktor Draxlegauge seine Schutzbrille, um zehn Elfen-Edelsteine für Captain O'Breen zu finden. Er erwartet sie zurück, wenn Ihr fertig seid.",h="In der Faldirbucht leiht Euch Doktor Draxlegauge seine Schutzbrille, um zehn Elfen-Edelsteine für Captain...",kw={"arathihochland","captain o'breen","doktor draxlegauge","elfen-edelstein","die faldirbucht","flottenmeister seehorn","edelsteinjagdschutzbrille","versunkener schatz"},sec={{t="Zu Stein gewordene Edelsteine",b="Die Elfen-Edelsteine liegen schon so lange auf dem Meeresgrund, dass sich dickes Gestein um sie verhärtet hat. Die Edelsteinjagdschutzbrille besitzt die Kraft, sie durch diese steinernen Hüllen hindurch aufzuspüren. Stolz auf den gnomischen Erfindergeist hinter der Schutzbrille leiht Doktor Draxlegauge sie Euch. Die Edelsteine sind für Captain O'Breen."},{t="Trockener Boden für den Doktor",b="Doktor Draxlegauge sagt, wissenschaftliche Arbeit halte ihn auf sicherem, trockenem Boden, obwohl er selbst hinunterschwimmen könnte. Er erwartet, dass Ihr die Schutzbrille anschließend zurückbringt. Captain O'Breen werde reichlich Verwendung dafür haben, sagt er."}},faq={{q="Wer schickt Euch los, um die Edelsteine zu sammeln?",a="Doktor Draxlegauge wartet in der Faldirbucht und schickt Euch los, um zehn Elfen-Edelsteine für Captain O'Breen zu sammeln.",al={"wer vergibt versunkener schatz zwei","questgeber versunkener schatz"}},{q="Warum braucht man für die Suche eine besondere Schutzbrille?",a="Durch die vielen Jahre auf dem Meeresgrund sind die Edelsteine zu dickem Gestein verhärtet. Die Kraft in der Edelsteinjagdschutzbrille lässt Euch die Edelsteine leicht finden.",al={"warum edelsteinjagdschutzbrille","was macht die schutzbrille"}},{q="Warum taucht Doktor Draxlegauge nicht selbst nach den Edelsteinen?",a="Doktor Draxlegauge sagt, wichtige wissenschaftliche Arbeit halte ihn auf sicherem, trockenem Boden.",al={"warum schwimmt draxlegauge nicht","warum bleibt draxlegauge an land"}},{q="Könnt Ihr die Edelsteinjagdschutzbrille behalten?",a="Nein. Doktor Draxlegauge leiht Euch die Schutzbrille und erwartet sie zurück, wenn Ihr fertig seid. Captain O'Breen wird sie oft benutzen.",al={"edelsteinjagdschutzbrille behalten","muss die schutzbrille zurückgegeben werden"}},{q="Wo steht diese Aufgabe in der Questreihe „Versunkener Schatz“?",a="Diese Aufgabe folgt auf den ersten Teil von „Versunkener Schatz“, in dem Professor Phizzlethorpe die Schutzbrille aufgeladen hat. Ein dritter Teil folgt.",al={"was kommt davor","was ist der nächste schritt"}}},fp="15,140,20.298.0,23.211.0,33.101.0,48.130.0,57.78.0,40.120.0,50.119.0"}
P.entries["quest:6661"] = {n="Tiefenbahn-Ratten-Razzia",s="An der Tiefenbahn bittet Monty vorbeikommende Reisende, die Ratten zusammenzutreiben. Die bezaubernde Melodie seiner Flöte bringt die lebenden Tiefenbahnratten dazu, ihr zu folgen.",h="An der Tiefenbahn bittet Monty vorbeikommende Reisende, die Ratten zusammenzutreiben.",kw={"tiefenbahnratte","tiefenbahn-ratten-razzia","die tiefenbahn","monty","rattenfänger-flöte","rattenkebab","ungeziefer"},ang={["profession:Cooking"]="Montys Bruder bereitet aus frisch gefangenen Tiefenbahnratten Rattenkebabs zu. Die Ratten müssen bis zur Zubereitung am Leben bleiben, sonst verdirbt das Fleisch."},sec={{t="Ungeziefer unter den Gleisen",b="Monty verhindert, dass Schädlinge die Tiefenbahn überrennen. Er spricht in rauem Seemannsjargon und behandelt die Bahnstrecke wie ein Schiffsdeck. Ungeziefer huscht durch den unterirdischen Bahnhof. Deshalb bittet Monty Reisende, die entlang der Strecke vorbeikommen, beim Zusammentreiben zu helfen."},{t="Eine fragwürdige Delikatesse",b="Monty gibt Helfern eine verzauberte Rattenfänger-Flöte. Ihre bezaubernde Melodie bringt Tiefenbahnratten dazu, ihr zu folgen, und sie müssen lebend zurückgebracht werden. Montys Bruder braucht frische Ratten für Rattenkebabs, bevor das Fleisch verdirbt."}},faq={{q="Wer vergibt die Quest Tiefenbahn-Ratten-Razzia?",a="Monty bittet vorbeikommende Reisende an der Tiefenbahn um Hilfe. Er braucht zusätzliche Hände, um das Ungeziefer entlang der unterirdischen Strecke in Schach zu halten.",al={"wer vergibt tiefenbahn-ratten-razzia","monty tiefenbahn","typ mit der rattenquest"}},{q="Warum müssen die Ratten für Monty lebend gefangen werden?",a="Montys Bruder braucht lebende Tiefenbahnratten, um Rattenkebabs zuzubereiten, bevor das Fleisch verdirbt. Wenn sie zu früh sterben, verdirbt das Fleisch.",al={"warum ratten lebend fangen","was macht monty mit ratten","rattenkebab hintergrundgeschichte"}},{q="Wie verzaubert Ihr die Ratten und treibt sie zusammen?",a="Monty stellt eine verzauberte Rattenfänger-Flöte zur Verfügung. Spielt ihre Melodie in der Nähe der Ratten, und sie folgen Euch zurück zu Montys Station.",al={"wie tiefenbahnratten fangen","wozu dient die flöte","rattenfänger-flöte tiefenbahn"}},{q="Wo findet diese Aufgabe statt?",a="Die Tiefenbahn verläuft unterirdisch zwischen Sturmwind und Eisenschmiede. Monty ist an ihren Bahnsteigen stationiert.",al={"wo ist tiefenbahn-ratten-razzia","monty standort","tiefenbahn ratten"}},{q="Wer ist Montys Bruder?",a="Monty erwähnt einen Bruder, der Rattenkebabs zubereitet, nennt aber keinen Namen. Sein Bruder braucht stetigen Nachschub an frischen, lebenden Ratten, damit das Fleisch nicht verdirbt.",al={"wer ist montys bruder","monty bruder koch","kebab bruder"}},{q="Warum spricht Monty wie ein Pirat?",a="Monty spricht in ausgeprägtem Seemannsjargon und behandelt die Bahn wie ein Schiffsdeck. Er hat die Schädlingsbekämpfung in der unterirdischen Bahn übernommen.",al={"warum ist ein pirat in der tiefenbahn","monty pirat tiefenbahn"}}},fp="19,138,24.241.0,23.220.1,40.128.0,44.129.0,39.133.0,32.106.0,23.152.0,34.142.0"}
P.entries["quest:6662"] = {n="Mein Bruder Nipsy...",s="Mit der Tiefenbahn schickt Monty lebende Ratten zu seinem Bruder Nipsy in Sturmwind. Nipsy betreibt am anderen Endbahnhof einen Rattenspieß-Stand, während Montys seltsames Verhalten auf die Tragödie von Gnomeregan hindeutet.",h="Mit der Tiefenbahn schickt Monty lebende Ratten zu seinem Bruder Nipsy in Sturmwind.",kw={"die tiefenbahn","gnomeregan","depot von eisenschmiede","mein bruder nipsy","monty","eigenartiges fleisch","nipsy","rattenspieß","depot von sturmwind"},ang={["faction:Alliance"]="Die Tiefenbahn verbindet Sturmwind und Eisenschmiede über eine Hochgeschwindigkeitsstrecke. Örtliche Händler versorgen Reisende an beiden Depots.",["profession:Cooking"]="Nipsy verarbeitet frische Deeprun-Ratten zu Spießen für Reisende zwischen Eisenschmiede und Sturmwind.",["race:Gnome"]="Montys Piratengehabe und seine sonderbaren Wahnvorstellungen gehen auf das Trauma des Vorfalls in Gnomeregan zurück. Sie zeigen, welche persönlichen Folgen der Untergang der Stadt für die überlebenden Gnome hatte."},sec={{t="Eine unterirdische Lieferung",b="Am Bahnhof von Eisenschmiede bittet Monty Euch, lebende Ratten mit der Tiefenbahn zu seinem Bruder Nipsy im Depot von Sturmwind zu bringen. Die kurze Fahrt verbindet die Hauptstädte der Zwerge und Menschen unter den Bergen. Unterwegs wird ungewöhnlicher Handel getrieben."},{t="Der Handel mit Rattenspießen",b="Die Kiste trägt die Aufschrift Karton mit eigenartigem Fleisch, doch darin befinden sich lebende Deeprun-Ratten. Nipsy betreibt am Endbahnhof von Sturmwind einen Rattenspieß-Stand und braucht die Ratten, bevor sie verderben. Als die Kiste unversehrt und zuckend ankommt, ist er erleichtert, Essen für die Reisenden zu haben, die den Bahnhof passieren."},{t="Die Narben von Gnomeregan",b="Monty spricht in übertriebenem Piratenjargon und warnt Reisende, ihre Gliedmaßen im Wagen der Tiefenbahn zu behalten. Nipsy sagt, Monty habe in seinem Leben noch nie ein Meer gesehen. Monty nutzt sein Piratengehabe, um das anhaltende Trauma von Gnomeregans radioaktivem Untergang zu bewältigen."}},faq={{q="Wer vergibt die Quest Mein Bruder Nipsy?",a="Monty ist ein exzentrischer Gnom auf der Seite der Tiefenbahn, die zu Eisenschmiede gehört. Tief gezeichnet von Gnomeregans Katastrophe, hat er sich die Sprache und das Gebaren eines Piraten angewöhnt, obwohl er noch nie ein Meer gesehen hat. Er fängt lebende Ratten, um sie mit der Tiefenbahn ans andere Ende der Strecke zu schicken.",al={"wer vergibt mein bruder nipsy","wer ist monty","monty tiefenbahn"}},{q="Wer ist Nipsy?",a="Nipsy ist Montys Bruder und betreibt einen Essensstand im Depot der Tiefenbahn in Sturmwind. Für seinen Rattenspieß-Handel ist er darauf angewiesen, dass Monty ihm lebende Ratten durch den Tunnel der Tiefenbahn schickt.",al={"wer ist nipsy","wo ist nipsy","nipsy standort"}},{q="Was befindet sich im Karton mit eigenartigem Fleisch?",a="Der Karton mit eigenartigem Fleisch enthält lebende Deeprun-Ratten, die Monty gefangen hat. Nipsy braucht sie lebend, damit sie nicht verderben, bevor er sie zu Spießen verarbeitet.",al={"was ist der karton mit eigenartigem fleisch","kiste mit eigenartigem fleisch","was ist in der kiste"}},{q="Warum spricht Monty wie ein Pirat?",a="Monty spricht wie ein Pirat, um das Trauma der Katastrophe von Gnomeregan zu bewältigen. Nipsy sagt, Monty habe noch nie ein Meer gesehen, obwohl er an seinem Piratengehabe festhält und Reisende davor warnt, auf den Schienen der Tiefenbahn Gliedmaßen zu verlieren.",al={"warum spricht monty wie ein pirat","ist monty ein pirat","monty pirat hintergrundgeschichte"}},{q="Was macht Nipsy mit den Ratten?",a="Nipsy bereitet Rattenspieße zu und verkauft sie an Reisende im Depot von Sturmwind. Frische Deeprun-Ratten, die mit der Tiefenbahn eintreffen, versorgen seinen Stand mit Nachschub.",al={"was macht nipsy mit den ratten","rattenspieß-geschäft","nipsy essen"}},{q="Wohin bringt Ihr die Lieferung?",a="Ihr bringt die Lieferung mit der Tiefenbahn vom Depot in Eisenschmiede zum Endbahnhof in Sturmwind. Die Tiefenbahn fährt durch den Unterwassertunnel zu Nipsys Bahnhof auf der Seite von Sturmwind.",al={"wie zu nipsy gelangen","wohin das fleisch bringen","tiefenbahnfahrt zu nipsy"}}},fp="17,183,23.243.0,19.287.0,19.248.1,38.246.0,13.171.0,42.157.0,35.216.0,33.130.0,34.180.0"}
P.entries["quest:667"] = {n="Tod von unten",s="An Bord von Shakes O'Breens Schiff im Arathihochland sammeln sich die Daggerspine-Naga zum Angriff. Ihr steht O'Breen bei, bemannt die Kanone und helft der Mannschaft, nach Beutebucht zurückzusegeln.",h="An Bord von Shakes O'Breens Schiff im Arathihochland sammeln sich die Daggerspine-Naga zum Angriff.",kw={"arathihochland","beutebucht","daggerspine","naga","shakes o'breen","schiffskanone"},sec={{t="Das Deck halten",b="Nach „Sunken Treasure“ sieht Shakes O'Breen, wie sich die Daggerspine-Naga zum Angriff sammeln. Sie sind rücksichtslos und werden immer weiter angreifen, bis O'Breen tot ist. O'Breen stellt die Sicherheit der Mannschaft über die eigene und bittet Euch, sie zu verteidigen. Ohne O'Breens Kenntnis der Meere kann die Mannschaft Beutebucht nicht erreichen. Also wartet Ihr mit O'Breen an Bord darauf, dass die Naga aus dem Wasser steigen."},{t="Nach dem Angriff",b="Wenn der Angriff endet, sagt O'Breen, dass das Schiff auslaufen wird, sobald die Flut steigt. O'Breen hätte Euch einen Platz in der Mannschaft angeboten, sieht aber, dass Ihr Wichtigeres zu tun habt."}},faq={{q="Wer greift Shakes O'Breen an?",a="Die Daggerspine-Naga sammeln sich zum Angriff auf Shakes O'Breen. Sie kommen aus dem Meer und werden immer weiter angreifen, bis O'Breen tot ist.",al={"wer greift shakes an","wer sind die angreifer","angriff der daggerspine"}},{q="Warum ist der Schutz von Shakes O'Breen für die Mannschaft so wichtig?",a="Shakes O'Breen stellt die Sicherheit der Mannschaft über die eigene. Ohne O'Breens Kenntnis der Meere kann die Mannschaft nicht nach Beutebucht zurücksegeln.",al={"warum shakes obreen schützen","warum ist shakes wichtig","shakes obreen navigation"}},{q="Wie wehrt Ihr den Angriff der Naga ab?",a="Ihr bleibt an Bord von Shakes O'Breens Schiff und bemannt die Kanone. Ihr schlagt die Naga zurück, wenn sie aus dem Meer kommen.",al={"wie tod von unten schaffen","wie shakes verteidigen","verteidigung mit der kanone"}},{q="Wo findet diese Verteidigung statt?",a="Ihr verteidigt Shakes O'Breens Schiff im Arathihochland, während die Naga aus dem Meer kommen.",al={"wo ist tod von unten","tod von unten ort"}}},fp="16,174,16.372.0,9.176.1,32.120.0,54.138.0,34.108.0,35.87.0"}
P.entries["quest:668"] = {n="Versunkener Schatz",s="Doktor Draxlegauge schickt Euch zu Captain O'Breen, der an der Brücke auf die Elfengemmen wartet. Nach Wochen unter Piraten haben der Doktor und der Professor gelernt, dass es ihrer Gesundheit schadet, Piratenschätze zu behalten.",h="Doktor Draxlegauge schickt Euch zu Captain O'Breen, der an der Brücke auf die Elfengemmen wartet.",kw={"arathihochland","captain o'breen","doktor draxlegauge","elfengemmen","piraten","shakes o'breen","versunkener schatz"},sec={{t="Schätze für den Kapitän",b="Doktor Draxlegauge möchte Captain O'Breen die Elfengemmen unbedingt überbringen. Der Kapitän wartet an der Brücke und will sie selbst sehen. Nach Wochen unter diesen Piraten haben der Doktor und der Professor gelernt, dass es ihrer Gesundheit schadet, Piratenschätze zu behalten. Also gibt Draxlegauge Euch die Gemmen, damit Ihr sie zu O'Breen bringt."}},faq={{q="Wer schickt Euch zu Captain O'Breen?",a="Doktor Draxlegauge gibt Euch die Elfengemmen, damit Ihr sie zu Captain O'Breen bringt.",al={"wer vergibt versunkener schatz drei","draxlegauge quest"}},{q="Warum will Doktor Draxlegauge die Gemmen so unbedingt loswerden?",a="Nach Wochen unter diesen Piraten haben Doktor Draxlegauge und der Professor gelernt, dass es ihrer Gesundheit schadet, Piratenschätze zu behalten.",al={"warum elfengemmen abgeben","warum einem piraten gemmen geben"}},{q="Wo steht diese Quest in der Reihe?",a="Sie folgt auf den zweiten Teil von Versunkener Schatz, und danach kommt ein vierter Teil.",al={"versunkener schatz position in der questreihe","was kommt vor versunkener schatz drei"}}},fp="15,215,24.319.0,33.72.0,55.136.0,34.82.0"}
P.entries["quest:669"] = {n="Versunkener Schatz",s="In „Versunkener Schatz“ halten Ebbe und wachsame Kreaturen Shakes O'Breen fest, also muss Nachricht nach Beutebucht gelangen.",h="In „Versunkener Schatz“ halten Ebbe und wachsame Kreaturen Shakes O'Breen fest, also muss Nachricht nach...",kw={"arathihochland","blackwater raiders","beutebucht","flottenmeister seehorn","elfischer probe-edelstein","shakes o'breen","versunkener schatz"},sec={{t="Nachricht für Beutebucht",b="Shakes O'Breen muss Flottenmeister Seehorn in Beutebucht unverzüglich von dem Fund berichten lassen. Der Wasserstand ist zu niedrig, als dass er aufbrechen könnte, und die Kreaturen, die seine Mannschaft aufgeschreckt hat, beobachten jede Bewegung. Er bittet Euch, Seehorn mitzuteilen, dass der Schatz gefunden wurde und noch mehr geborgen wird. Ihr tragt einen elfischen Probe-Edelstein als Beweis bei Euch."}},faq={{q="Warum kann Shakes O'Breen den Edelstein nicht selbst überbringen?",a="Der Wasserstand ist zu niedrig, als dass Shakes O'Breen und seine Mannschaft aufbrechen könnten, und die aufgeschreckten Kreaturen beobachten ihre Bewegungen.",al={"warum kann shakes nicht aufbrechen","warum sitzt shakes fest","warum braucht shakes einen boten"}},{q="Wer ist Flottenmeister Seehorn?",a="Flottenmeister Seehorn ist in Beutebucht, und O'Breen möchte, dass er unverzüglich von dem Fund erfährt.",al={"wer ist seehorn","wo ist flottenmeister seehorn"}},{q="Welcher Beweis wird nach Beutebucht gebracht?",a="Ihr tragt einen elfischen Probe-Edelstein bei Euch, um zu beweisen, dass der Schatz gefunden wurde und noch mehr geborgen wird.",al={"was ist der beweis","welcher edelstein wird überbracht"}}},fp="15,117,18.301.0,49.117.0,28.88.0,41.90.0"}
P.entries["quest:67"] = {n="Die Legende von Stalvan",s="In Dunkelhain durchsucht Amtmann Daltry die Stadtakten nach Stalvan Dunstmantel. Eine alte Adresse weist nach Westen, nach Mondbruch in Westfall, wo die Suche nach Stalvans Vergangenheit beginnt.",h="In Dunkelhain durchsucht Amtmann Daltry die Stadtakten nach Stalvan Dunstmantel.",kw={"daltry","dämmerwald","fußkiste","unglückseliger geist","dunstmantel","mondbruch","schule","stalvan","westfall"},ang={["class:Mage"]="Der Unglückselige Geist, der die Fußkiste bewacht, setzt Verwandlung und schwächende Flüche ein. Euch begegnet an Trauer gebundene Magie in einem ansonsten gewöhnlichen Klassenzimmer.",["faction:Alliance"]="Diese Suche zeigt, wie sehr die ländlichen Orte des Königreichs auseinandergebrochen sind. Ihr müsst das von den Defias besetzte Westfall durchqueren, um einem Registereintrag aus Dunkelhain nachzugehen."},sec={{t="Die Bitte des Amtmanns",b="Nach Euren Erkundigungen in Dunkelhain durchsucht Amtmann Daltry das Stadtregister nach Stalvan Dunstmantel. Das Register wurde seit Jahren nicht aktualisiert und nennt die Schule in Mondbruch, weit im Westen, als Stalvans letzten bekannten Wohnsitz. Daltry betrachtet die alte Adresse als gewöhnlichen Registereintrag. Er bittet Euch, Nachforschungen anzustellen und alle Aufzeichnungen mitzubringen, die Dunkelhains Archive auf den neuesten Stand bringen könnten."},{t="Die Ruinen von Mondbruch",b="Die Spur führt aus dem Dämmerwald nach Westfall, wo die Bruderschaft der Defias Mondbruch besetzt hält. Einst eine blühende Bauernsiedlung, steht der Ort nun unter der Kontrolle von Gesetzlosen. Nahe seinem Zentrum steht die verlassene Schule. Im Inneren birgt eine alte Fußkiste die ersten eindeutigen Hinweise auf Stalvans früheres Leben als Lehrer. Noch immer liegt Trauer über der Truhe."},{t="Eine tragische Heimsuchung",b="Das Öffnen der alten Fußkiste beschwört einen Unglückseligen Geist. Er greift jeden an, der Stalvans Vergangenheit aufdeckt, und verflucht Eindringlinge mit klagender Magie. Der Geist deutet auf eine ungelöste Tragödie hin, die mit dem Fortgang des Schulmeisters aus Westfall verbunden ist. Die Suche nach alten Aufzeichnungen ist zu einer Heimsuchung geworden."}},faq={{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry verwaltet Dunkelhains Stadtakten im Rathaus des Dämmerwalds. Er durchsucht das Register nach Stalvan Dunstmantel und findet Einträge, die seit Jahren unverändert sind.",al={"daltry","amtmann von dunkelhain","wer startet die legende von stalvan zwei"}},{q="Wo ist die Schule in Mondbruch?",a="Die Schule in Mondbruch steht im Zentrum von Mondbruch, im Südwesten von Westfall. Ihre Architektur ähnelt dem Rathaus von Dunkelhain, und Banditen der Defias umgeben sie.",al={"schule in mondbruch standort","wo ist die schule","wo ist stalvans fußkiste"}},{q="Was befindet sich in der alten Fußkiste?",a="Die Fußkiste enthält alte Aufzeichnungen und persönliche Gegenstände aus Stalvan Dunstmantels Zeit als Lehrer in Mondbruch. Sie liefern den nächsten Hinweis bei der Suche nach seinem Aufenthaltsort.",al={"stalvans fußkiste","was ist in der fußkiste"}},{q="Warum greift beim Öffnen der Fußkiste ein Geist an?",a="Das Öffnen der Fußkiste beschwört einen Unglückseligen Geist, der mit Verwandlung und Flüchen angreift. Der Geist ist an die Tragödie um Stalvans Vergangenheit und seinen Fortgang aus Mondbruch gebunden.",al={"unglückseliger geist","warum erscheint ein geist","fluch von stalvans geist"}},{q="Warum verließ Stalvan Westfall?",a="Stalvan war Schulmeister in Mondbruch, bevor er fortging, um anderswo im Königreich Arbeit als Privatlehrer zu suchen. Seine Habseligkeiten blieben in der alten Schule eingeschlossen.",al={"warum verließ stalvan mondbruch","stalvan mondbruch geschichte"}},{q="Kann man Mondbruch gefahrlos betreten?",a="Nein. Die Bruderschaft der Defias kontrolliert Mondbruch, also müsst Ihr Euch bewaffneten Dieben und Gesetzlosen stellen, um die Schule zu erreichen.",al={"ist mondbruch gefährlich","gegner in mondbruch"}}},fx={["803ebeb2"]={q="Warum will Amtmann Daltry, dass dies erledigt wird?",a="Amtmann Daltry ist sehr stolz auf das Führen des Stadtregisters von Dunkelhain. Bei der Überprüfung der Unterlagen für Stalvan Dunstmantel stellte er fest, dass als letzte bekannte Adresse des Mannes die Schule in Mondbruch in Westfall eingetragen ist. Da er weiß, wie veraltet dieser Eintrag ist, möchte er, dass Ihr die Schule besucht und aktuelle Informationen aufdeckt, damit er seine Geschäftsbücher ordentlich, sauber und korrekt halten kann.",al={"warum will daltry stalvan aufzeichnungen","amtmann daltrys motiv","warum stalvan finden"}}},fp="21,175,24.393.0,22.351.0,17.289.1,20.167.0,35.166.0,34.182.0,52.182.1,31.165.0,27.114.0"}
P.entries["quest:670"] = {n="Versunkener Schatz",s="Flottenmeister Seehorn wartet in Beutebucht mit einem Brief für Shakes O'Breen vor der Küste von Arathi. Seine Schiffe können erst auslaufen, wenn ihre Vorräte aufgefüllt sind.",h="Flottenmeister Seehorn wartet in Beutebucht mit einem Brief für Shakes O'Breen vor der Küste von Arathi.",kw={"arathihochland","blackwater raiders","beutebucht","flottenmeister seehorn","seehorns versiegelter brief","shakes o'breen","versunkener schatz"},sec={{t="Ein Brief für O'Breen",b="Flottenmeister Seehorn sieht in Euch einen Abenteurer. Seine Schiffe müssen ihre Vorräte auffüllen, bevor sie Beutebucht verlassen können. Hier und in der Ferne braut sich Unheil zusammen, sagt er, und er hat einen geheimen Brief für Shakes O'Breen vor der Küste von Arathi. Kann er darauf vertrauen, dass Ihr ihn sicher überbringt und seinen Inhalt vertraulich behandelt?"}},faq={{q="Wer schickt Euch los, um diesen Brief zu überbringen?",a="Flottenmeister Seehorn in Beutebucht gibt Euch einen versiegelten Brief für Shakes O'Breen.",al={"wer vergibt versunkener schatz 5","wer startet diese quest","seehorns brief questgeber"}},{q="Warum überbringt Flottenmeister Seehorn den Brief nicht selbst?",a="Seine Schiffe können erst aus Beutebucht auslaufen, wenn ihre Vorräte aufgefüllt sind.",al={"warum kann seehorn beutebucht nicht verlassen","warum sitzt flottenmeister seehorn fest"}},{q="Wo befindet sich Shakes O'Breen?",a="Shakes O'Breen ist vor der Küste des Arathihochlands beschäftigt.",al={"wo shakes obreen finden","shakes obreen aufenthaltsort","wo ist shakes"}},{q="Was ging dieser Zustellung voraus?",a="Diese Zustellung folgt auf den vierten Teil von „Versunkener Schatz“.",al={"versunkener schatz questreihe","welche quest kommt vor versunkener schatz 5"}}},fp="15,136,20.286.0,37.79.0,60.56.0,32.61.0,31.57.0"}
P.entries["quest:671"] = {n="Elende Magien",s="Im Arathihochland folgt Tor'gan einer dämonischen Präsenz zum Nordhof. Von Hammerfall aus sucht er Hilfe, um Blutsteinamulette von den Beschwörern zu beschaffen.",h="Im Arathihochland folgt Tor'gan einer dämonischen Präsenz zum Nordhof.",kw={"arathihochland","blutstein","blutsteinamulett","dämonenbeschwörung","elende magien","hammerfall","nordhof","tor'gan"},ang={["class:Warlock"]="Als Hexenmeister kennt Ihr die Rituale und Bindungsreagenzien, die zur Beschwörung von Dämonen benötigt werden. Die Blutsteinamulette auf dem Nordhof sind von besonderem Interesse.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Hammerfall ihr einziger Außenposten im Arathihochland ist. Dunkle Beschwörer unmittelbar westlich der Siedlung stellen eine direkte Bedrohung für ihre Sicherheit dar.",["race:Orc"]="Als Orc tragt Ihr eine tief verwurzelte und schmerzhafte Geschichte dämonischer Verderbnis in Euch. Verbliebene Teufelsmagie kann Euer Blut zum Kochen bringen und unnatürliche Wut wecken, wie Tor'gan sie nahe dem Nordhof verspürt."},sec={{t="Schwelende Wut",b="Dämonische Energie regt sich im Arathihochland, und Tor'gan spürt sie von seinem Posten in Hammerfall aus. Ihr Sog zieht den Orc nach Westen zum Nordhof. Dort findet er Spuren dämonischer Beschwörungen, doch die verbliebene Verderbnis bringt sein Blut zum Kochen und weckt unwillkürliche Wut, die in der Geschichte des Blutfluchs wurzelt. Er zieht sich zurück, bevor der Einfluss seine Sinne überwältigt, und sucht dann Hilfe bei anderen."},{t="Die Blutsteinamulette",b="Auf dem Nordhof fand Tor'gan ein Blutsteinamulett auf dem Boden. Es zeigte, dass dort dunkle Rituale vollzogen wurden. Solche Talismane helfen dabei, dämonische Beschwörungen zu kanalisieren und zu stabilisieren, doch das geborgene Amulett hatte seine Magie verloren. Es enthielt zu wenig Kraft für eine gründliche Untersuchung. Tor'gan bittet Reisende der Horde, zehn intakte Amulette von den Ritualwirkern des Gutshofs zu beschaffen, damit er die Rituale untersuchen und erfahren kann, welche Wesenheiten beschworen wurden."}},faq={{q="Wer vergibt die Quest Elende Magien?",a="Tor'gan erteilt den Auftrag in Hammerfall, der Festung der Horde im Arathihochland. Da er in der Nähe eine dämonische Präsenz spürt, bittet er Reisende, den Nordhof zu untersuchen.",al={"elende magien questgeber","wer startet elende magien","torgan quest arathi"}},{q="Wo liegt der Nordhof?",a="Der Nordhof liegt westlich von Hammerfall in den nördlichen Hügeln des Arathihochlands. Einst ein menschliches Gehöft, ist er heute Schauplatz geheimer Dämonenbeschwörungen mithilfe von Blutsteintalismanen.",al={"nordhof standort","wo ist der nordhof","nordhof arathi finden"}},{q="Wozu werden Blutsteinamulette verwendet?",a="Blutsteinamulette helfen Ritualwirkern, bei Dämonenbeschwörungen dunkle Magie zu kanalisieren. Wenn eine Beschwörung die Kraft eines Amuletts aufzehrt, ist der Talisman erschöpft.",al={"was ist ein blutsteinamulett","blutsteinamulett zweck","warum blutsteinamulette"}},{q="Warum verspürt Tor'gan in der Nähe des Nordhofs Wut?",a="Die verbliebenen Energien dämonischer Beschwörungen nahe dem Nordhof schüren Tor'gans Wut. Teufelsmagie bringt sein Blut zum Kochen und entfacht unkontrollierbare Wut.",al={"warum torgans blut kocht","torgan wut nordhof","warum wird torgan wütend"}},{q="Warum weigert sich Tor'gan, zum Nordhof zurückzukehren?",a="Tor'gan fürchtet, dass die verbliebene dämonische Macht gefährliche Wut in ihm wecken wird. Aus Sorge, die Kontrolle zu verlieren oder ihrem verderbenden Einfluss zu erliegen, bittet er andere, die Amulette zu beschaffen.",al={"warum will torgan nicht zum nordhof","warum kehrt torgan nicht zurück","warum kann torgan keine amulette holen"}},{q="Wie viele Blutsteinamulette werden benötigt?",a="Tor'gan bittet um zehn Blutsteinamulette vom Nordhof. Das von ihm gefundene war erschöpft, weshalb er mehrere aufgeladene Exemplare benötigt, um die dortigen Rituale zu untersuchen und zu verstehen.",al={"wie viele blutsteinamulette","blutsteinamulette anzahl","elende magien zielanzahl"}},{q="Wer beschwört auf dem Nordhof Dämonen?",a="Dunkle Ritualwirker führen auf dem Nordhof Dämonenbeschwörungen durch. Ihre Rituale und die Rückstände von Teufelsmagie erregten Tor'gans Aufmerksamkeit in Hammerfall und führten zu den Nachforschungen der Horde.",al={"wer ist auf dem nordhof","wer beschwört dämonen auf dem nordhof","nordhof kultisten"}}},fp="11,160,16.391.0,22.436.0,32.173.0,33.184.0,37.149.0,48.145.0,53.182.0,39.174.0,43.178.0"}
P.entries["quest:672"] = {n="Mut machen",s="Tor'gan will Gor'mul in Hammerfall im Arathihochland neuen Lebensmut geben. Erzählungen von Orgrimmar und Kriegshäuptling Thrall haben keinen Trost gebracht, also wendet sich Tor'gan den neu wiederentdeckten schamanistischen Traditionen der Horde zu.",h="Tor'gan will Gor'mul in Hammerfall im Arathihochland neuen Lebensmut geben.",kw={"arathihochland","gor'mul","hammerfall","hochlandraptoren augen","orgrimmar","mut machen","schamanismus","thrall","tor'gan"},ang={["class:Shaman"]="Als Schamane seht Ihr, wie die wiederbelebten Traditionen der Horde gegen Gor'muls Niedergeschlagenheit eingesetzt werden. Tor'gan ruft Tiergeister an, um seinen Lebenswillen neu zu entfachen.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie sich Kameraden in abgelegenen Außenposten wie Hammerfall um niedergeschlagene Waffenbrüder kümmern.",["race:Orc"]="Als Orc wisst Ihr, dass die Internierung und der Verlust der alten Bräuche Veteranen wie Gor'mul mit Verzweiflung und Teilnahmslosigkeit belastet haben. Manche tun sich schwer damit, Thralls neue Horde anzunehmen."},sec={{t="Ein schweres Herz in Hammerfall",b="In Hammerfall im Arathihochland ist Gor'mul in tiefe Melancholie verfallen. Seine Gefährten haben ihm von Kalimdor, der mächtigen Stadt Orgrimmar und der Führung durch Kriegshäuptling Thrall erzählt. Doch keine dieser Erzählungen hat seine Schwermut gelindert oder ihm Hoffnung gegeben."},{t="Geister der Wildnis",b="Tor'gan wendet sich den wiederbelebten spirituellen Traditionen der Horde zu, um Gor'mul zu helfen. Er sammelt die Augen von Hochlandraptoren, die Arathi durchstreifen, und fertigt ein Amulett an, das mit ihren Geistern gesegnet ist. Durch diesen Ritus hofft er, dass die Lebenskraft der Raubtiere Gor'muls Lebenswillen weckt."}},faq={{q="Wer ist Tor'gan?",a="Tor'gan ist ein Trollschamane, der in Hammerfall im Arathihochland stationiert ist. Er hofft, Gor'mul mit einem Amulett zu helfen, das mithilfe der neu wiederentdeckten schamanistischen Traditionen der Horde gefertigt wird.",al={"wer ist tor'gan","torgan hammerfall","questgeber mut machen"}},{q="Wer ist Gor'mul und warum braucht er Aufmunterung?",a="Gor'mul ist ein Orc in Hammerfall, der in Niedergeschlagenheit und Teilnahmslosigkeit versunken ist. Erzählungen von Orgrimmar und Kriegshäuptling Thrall haben seinen Lebensmut nicht geweckt.",al={"wer ist gormul","warum ist gormul traurig","orc niedergeschlagen hammerfall"}},{q="Warum braucht Tor'gan Augen von Hochlandraptoren?",a="Tor'gan verwendet die Augen von Highland Striders und Highland Thrashers, um ein schamanistisches Amulett anzufertigen. Er hofft, dass ihre Geister Gor'mul Stärke und Zähigkeit verleihen und seinen Kampfgeist neu entfachen.",al={"warum raptorenaugen","raptorenaugen amulett","zweck der raptorenaugen"}},{q="Wo spielt diese Quest?",a="Hammerfall ist der Außenposten der Horde im Arathihochland. Er ist nach dem ehemaligen Kriegshäuptling Orgrim Schicksalshammer benannt und bietet den in den Östlichen Königreichen verbliebenen Orcs einen befestigten Zufluchtsort.",al={"wo liegt hammerfall","hammerfall lage","orcs in arathi"}},{q="Was ist die neu entdeckte schamanistische Magie, von der Tor'gan spricht?",a="Die Orcs verloren ihre spirituelle Verbindung zu den Elementen und Ahnengeistern während der dämonischen Verderbnis und der Internierung. Unter Kriegshäuptling Thrall hat die Horde den uralten schamanistischen Pfad wiedergefunden, geleitet von spiritueller Harmonie statt von Teufelsmagie.",al={"schamanistische magie orcs","orc schamanismus neue horde","warum neue schamanistische magie"}},{q="Welche Geschichten konnten Gor'mul nicht aufmuntern?",a="Gor'muls Gefährten erzählten ihm von Orgrimmar, der neuen Hauptstadt jenseits des Meeres in Kalimdor, und von Kriegshäuptling Thrall, der Orgrim Schicksalshammers Rüstung und legendären Kriegshammer trägt.",al={"geschichten über thrall","welche geschichten erzählten sie gormul","orgrimmar geschichten gormul"}}},fp="15,220,27.248.0,19.268.0,15.179.0,48.134.0,43.190.0,33.175.0,63.236.0,40.170.0"}
P.entries["quest:673"] = {n="Elende Magien",s="In Hammerfall fürchtet Tor'gan, dass ein Hexenmeister in Stromgarde mit einem arkanen Relikt Dämonen beschwört. Eure erste Arbeit für ihn hat zur Jagd auf den Hexenmeister und das Relikt geführt.",h="In Hammerfall fürchtet Tor'gan, dass ein Hexenmeister in Stromgarde mit einem arkanen Relikt Dämonen...",kw={"arathihochland","blutstein","hammerfall","marez cowl","stromgarde","torgan","hexenmeister"},sec={{t="Ein Hexenmeister in Stromgarde",b="Tor'gan ist sich sicher, dass ein Hexenmeister innerhalb der Mauern von Stromgarde ein arkanes Relikt nutzt, um schreckliche Dämonen in großer Zahl herbeizurufen. Das Brennen in seinem Blut wächst von Tag zu Tag. Also schickt er Euch los, um den Hexenmeister zu finden und zu töten und dann den magischen Gegenstand von dessen Leiche zurückzubringen. Er will ihn zerstören, bevor seine Macht das Land verderben kann. Der Hexenmeister ist Marez Cowl, und der Gegenstand ist eine Beschmutzte Blutsteinkugel."},{t="Woran die Kugel erinnert",b="Nach der Zerstörung der Kugel erwartet Tor'gan, dass seine rastlosen Nächte friedlichem Schlaf weichen. Die Kugel erinnert an die schreckliche Gewalt, die Dämonen einst über die Orcs hatten. Diese Herrschaft währte, bis Hellscream sie von ihrem Fluch befreite."}},faq={{q="Wer schickt Euch auf die Jagd nach dem Hexenmeister?",a="Tor'gan in Hammerfall schickt Euch nach Stromgarde, um den Hexenmeister zu finden und ihm den magischen Gegenstand von dessen Leiche zu bringen.",al={"wer vergibt elende magien","elende magien questgeber","torgan quest"}},{q="Wo befindet sich der Hexenmeister?",a="Marez Cowl versteckt sich innerhalb der Mauern von Stromgarde, westlich und außerhalb des Keep, hinter einem Gebäude. Ihr könnt hören, wie sie einen Zauber kanalisiert.",al={"wo ist marez cowl","stromgarde hexenmeister fundort","wo marez cowl finden"}},{q="Welches Relikt sollt Ihr beschaffen?",a="Ihr sollt Marez Cowls Beschmutzte Blutsteinkugel beschaffen. Tor'gan will, dass sie ihm zur Zerstörung gebracht wird.",al={"welchen gegenstand will torgan","beschmutzte blutsteinkugel","elende magien gegenstand"}},{q="Warum will Tor'gan den Hexenmeister aufhalten?",a="Der Hexenmeister hat mithilfe eines arkanen Relikts schreckliche Dämonen in großer Zahl beschworen. Tor'gan will, dass Ihr die Macht des Relikts beseitigt und die Kugel zerstört, bevor sie das Land verderben kann.",al={"warum die kugel zerstören","torgan beweggrund","warum den hexenmeister aufhalten"}}},fp="11,165,23.399.0,20.219.1,34.123.0,29.129.0,36.111.0,42.176.0"}
P.entries["quest:674"] = {n="Mut machen",s="Ein Abgesandter der Horde hofft, dass Gor'mul durch „Mut machen“ seinen Kampfgeist wiederfindet. Das Raptorkrallen-Amulett soll ihn neu entfachen, doch Gor'mul bleibt verbittert und bezweifelt, dass irgendein Glücksbringer der Horde ihren einstigen Ruhm zurückgeben kann.",h="Ein Abgesandter der Horde hofft, dass Gor'mul durch „Mut machen“ seinen Kampfgeist wiederfindet.",kw={"gor'mul","gormul","horde","mut machen","raptoramulett","raptorkrallen-amulett","krieger"},ang={["class:Warrior"]="Als Krieger hört Ihr von einem Orc, dessen Kampfgeist durch Verzweiflung und Trauer über einen feigen Schlag erloschen ist.",["faction:Horde"]="Als Mitglied der Horde hört Ihr, wie Gor'mul ihrer einstigen Macht nachtrauert und bezweifelt, dass ein einfacher Glücksbringer ihren verlorenen Ruhm wiederherstellen kann."},sec={{t="Ein Funke für die erloschene Flamme",b="Ein Abgesandter bringt Gor'mul ein Raptorkrallen-Amulett und hofft, dass dessen Macht ihn erreicht. Der Talisman bündelt die wilde Kraft und Wildheit der Raptoren. Er soll die Flamme neu entfachen, die einst lodernd im Inneren des Orckriegers brannte."},{t="Verbitterung und Verzweiflung",b="Gor'mul beantwortet das Geschenk mit bitterem Kummer. Er erinnert sich daran, wie die mächtigsten Champions von feigen Händen niedergestreckt wurden, und weist den Talisman als polierten Knochen zurück. Er bezweifelt, dass irgendein Glücksbringer der Horde ihren einstigen Ruhm zurückgeben kann."}},faq={{q="Was ist „Mut machen“?",a="Ein Abgesandter der Horde bringt Gor'mul ein Raptorkrallen-Amulett und hofft, damit den Kampfgeist des verzagten Kriegers neu zu entfachen.",al={"was ist mut machen","mut machen quest"}},{q="Wer ist Gor'mul?",a="Gor'mul ist ein Krieger, den Verzweiflung verzehrt, seit die mächtigsten Champions durch feige Hände fielen. Er tut solche Gaben ab und bezweifelt, dass die Horde ihren einstigen Ruhm wiedererlangen kann.",al={"wer ist gormul","gor mul"}},{q="Warum wird Gor'mul das Raptorkrallen-Amulett gebracht?",a="Das Raptorkrallen-Amulett ist aus poliertem Knochen und Raptorkrallen gefertigt. Es wird Gor'mul gebracht, um durch die natürliche Kraft und Wildheit der Raptoren seine innere Flamme zu wecken.",al={"warum das amulett bringen","was bewirkt das raptorkrallen-amulett"}},{q="Warum ist Gor'mul verzagt?",a="Gor'mul verzweifelt, nachdem er mitansehen musste, wie die mächtigsten Champions von feigen Händen erschlagen wurden. Ihr Fall überzeugt ihn davon, dass Ehre und Stärke ausgelöscht werden können, und bricht seinen Kampfeswillen.",al={"warum ist gormul traurig","warum ist gormul niedergeschlagen"}},{q="Wie reagiert Gor'mul auf das Amulett?",a="Gor'mul weist das Geschenk als bloßen polierten Knochen zurück. Er glaubt, dass es weder die Horde wiederherstellen noch die Tragödie ungeschehen machen kann, die er beklagt.",al={"mag gormul das amulett","gormuls reaktion"}},{q="Was sagt Gor'mul über die Horde?",a="Gor'mul bezweifelt, dass die Horde ihren einstigen Ruhm zurückgewinnen kann, und sieht wenig Hoffnung, wenn Verrat selbst die größten Helden niederstrecken kann.",al={"kann die horde wiederhergestellt werden","gormul horde ruhm"}}},fp="15,225,26.231.0,22.218.1,24.120.0,15.164.0,50.191.0,26.182.0,37.119.0,38.130.0"}
P.entries["quest:675"] = {n="Mut machen",s="Tor'gan hofft, dass Ahnenmagie Gor'muls Stolz und Lebenswillen wiederherstellen kann. Der Schamane will einen alten Orcveteranen aus der Verzweiflung führen.",h="Tor'gan hofft, dass Ahnenmagie Gor'muls Stolz und Lebenswillen wiederherstellen kann.",kw={"amulett","gor'mul","gnade","orc","mut machen","schamane","tor'gan","veteran","kriegshäuptling"},ang={["class:Shaman"]="Als Schamane seht Ihr, wie der orcische Schamanismus den Lebensmut von Veteranen wiederherstellen kann, die noch immer unter seelischen Verletzungen leiden.",["faction:Horde"]="Unter Thralls Führung will die Horde verbitterte Veteranen wieder eingliedern und aufrichten, statt sie der Verzweiflung zu überlassen.",["race:Orc"]="Als Orc könnt Ihr womöglich die Schande nachvollziehen, die Gor'mul empfindet, weil ihm ein ehrenvoller Tod an der Seite seines einstigen Kriegshäuptlings verwehrt blieb."},sec={{t="Ein gebrochener Geist",b="Gor'mul trauert darüber, dass er überlebt hat, während sein Kriegshäuptling fiel. Viele Orcveteranen tragen die Last vergangener Kriege, doch Gor'mul glaubt, das Schicksal habe ihm einen ehrenvollen Tod an der Seite seines Anführers verwehrt. Tor'gan, ein Schamane, hofft, diesen Kummer zu lindern, indem er an die spirituelle Stärke seines Volkes erinnert. Er bereitet ein verzaubertes Amulett vor und vertraut darauf, dass die Macht der Ahnen den Stolz des alten Kriegers neu entfacht."},{t="Die Grenzen des Amuletts",b="Tor'gans Amulett erreicht Gor'mul, spendet ihm aber keinen Trost. Gor'mul wirft es in den Schmutz und fragt, warum ihm jemand Gnade erweisen sollte, wenn das Schicksal ihm ein ehrenvolles Ende verwehrt hat. Tor'gan erkennt an, dass ein einzelner Talisman jahrelangen Kummer nicht überwinden kann. Dennoch will er Gor'mul weiterhin helfen und glaubt, dass die zunehmende Ausübung des Schamanismus ihn zu seiner einstigen Ehre zurückführen kann."}},faq={{q="Wer ist Gor'mul?",a="Gor'mul ist ein verbitterter Orcveteran, der die Konflikte der alten Horde überlebte, nachdem sein Kriegshäuptling gefallen war. Er glaubt, das Schicksal habe ihm grausam einen ehrenvollen Tod an der Seite dieses Anführers verwehrt, und weist gewöhnliches Mitgefühl zurück.",al={"wer ist gormul","gormuls vorgeschichte","was fehlt gormul"}},{q="Wer ist Tor'gan und warum hilft er Gor'mul?",a="Tor'gan ist ein Schamane, der Gor'mul aus der Verzweiflung führen will. Er glaubt, dass die Wege der Ahnen gebrochene Geister heilen können und der Schamanismus einstigen Kriegern eine spirituelle Wiedergeburt ermöglichen kann. Er fertigt mit Magie erfüllte Talismane, um sie an die Stärke ihres Volkes zu erinnern.",al={"wer ist torgan","was will torgan","torgans ziel"}},{q="Welchen Zweck hatte das Amulett?",a="Tor'gan bereitete das verzauberte Amulett vor, um Gor'muls Kriegergeist durch schamanische Energie zu wecken. Gor'mul lehnte es ab und warf es zu Boden, weil er glaubte, seine Magie könne seine Verbitterung nicht vertreiben.",al={"was ist das amulett","warum warf gormul das amulett weg","hat das amulett gewirkt"}},{q="Um welchen Kriegshäuptling trauert Gor'mul?",a="Gor'mul nennt den Kriegshäuptling, um den er trauert, nicht beim Namen. Er verflucht das Schicksal dafür, dass es ihm den Tod an der Seite seines im Kampf gefallenen Anführers verwehrt hat.",al={"welcher kriegshäuptling starb","wer war gormuls kriegshäuptling","wem diente gormul"}},{q="Was hat Tor'gan vor, nachdem das Amulett versagt hat?",a="Tor'gan erkennt an, dass das Amulett allein nicht mächtig genug war. Er bleibt geduldig und glaubt, dass die wahre Macht des Schamanismus Gor'muls verlorenen Stolz neu entfachen kann.",al={"gibt torgan auf","was geschieht nach mut machen","wird sich gormul erholen"}},{q="Warum nutzt Tor'gan den Schamanismus, um Gor'mul zu helfen?",a="Tor'gan nutzt den Schamanismus, um die verwundeten Seelen und den verletzten Stolz seines Volkes zu heilen. Schamanen heilen diese Wunden und kanalisieren die Elemente für den Krieg.",al={"was zeigt das über schamanen","warum hier schamanische magie nutzen"}}},fp="15,133,15.376.0,24.363.1,15.207.0,45.240.0,35.198.0,34.118.0,52.153.0,47.132.0"}
P.entries["quest:676"] = {n="Der Hammer kann fallen",s="Tallow schickt Kämpfer aus Tarrens Mühle durch die Berge, um Hammerfall im Arathihochland zu entlasten. Bevor Ihr Euch bei Drum Teufel meldet, beweist Ihr Eure Stärke gegen Oger der Felsfäuste nahe den Ruinen von Stromgarde.",h="Tallow schickt Kämpfer aus Tarrens Mühle durch die Berge, um Hammerfall im Arathihochland zu entlasten.",kw={"arathihochland","vollstrecker der felsfäuste","oger der felsfäuste","drum teufel","hammerfall","vorgebirge des hügellands","stromgarde","tallow","tarrens mühle","der hammer kann fallen"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch hünenhaften Vollstreckern der Felsfäuste, um Euch vor erfahrenen Orckommandanten wie Drum Teufel zu beweisen.",["faction:Horde"]="Dieser Auftrag führt Euch von den örtlichen Konflikten in Hillsbrad zur umfassenderen Verteidigung des Arathihochlands, wo Hammerfall einen wichtigen Stützpunkt hält.",["race:Orc"]="Für Euch als Orc ist Hammerfall voller Bedeutung und Geschichte. Es wurde dort gegründet, wo Kriegshäuptling Orgrim Schicksalshammer während der Befreiungsfeldzüge sein Leben gab."},sec={{t="Ein barscher Ruf",b="In Tarrens Mühle hat Tallow wenig Geduld mit Kämpfern, die sich noch nicht bewiesen haben. Während Rekruten untätig herumstehen, werden weit entfernte Verbündete angegriffen. Er schickt fähige Kämpfer ostwärts durch den Thoradinswall ins Arathihochland, wo Hammerfall von mehreren Seiten belagert wird. Zuerst müssen sie sich gegen einen starken Feind bewähren. Erst dann schickt Tallow sie zum Außenposten."},{t="Prüfung durch die Felsfäuste",b="Tallow verlangt einen Beweis der Stärke am Ogerhügel nordöstlich der Ruinen von Stromgarde. Die Oger der Felsfäuste und ihre Vollstrecker halten große Teile von Arathi und bedrohen Reisende auf den Hochlandpfaden. Der Kampf gegen sie lichtet die feindlichen Reihen entlang der Straße. Er beweist auch, dass Ihr der Gefahr gewachsen seid, bevor Ihr Hammerfall erreicht."},{t="Meldung in Hammerfall",b="Sobald das Lager der Felsfäuste gesäubert ist, führt die Straße nordostwärts nach Hammerfall, das nach Kriegshäuptling Orgrim Schicksalshammer benannt wurde. Kommandant Drum Teufel empfängt die Neuankömmlinge mit müder Skepsis. Ob Tallow die Garnison verstärken oder Narren in den Tod schicken wollte, Drum Teufel setzt bewährte Kämpfer bald in den Scharmützeln ein, die den Außenposten bedrohen."}},faq={{q="Wo beginnt und endet diese Quest?",a="Tallow bietet diesen Auftrag in Tarrens Mühle im Vorgebirge des Hügellands an. Nachdem Ihr die geforderten Oger im Arathihochland besiegt habt, meldet Ihr Euch bei Drum Teufel in Hammerfall, dem Außenposten der Horde.",al={"wo beginnt der hammer kann fallen","abgabeort der quest","wer vergibt der hammer kann fallen"}},{q="Wo befinden sich die Oger der Felsfäuste?",a="Die Oger der Felsfäuste leben an einem markanten Erdhügel und in einem Lager nordöstlich der Ruinen von Stromgarde im Arathihochland.",al={"standort der oger der felsfäuste","wo sind die oger in arathi","hügel der felsfäuste"}},{q="Was ist der Außenposten Hammerfall?",a="Hammerfall ist eine befestigte Siedlung der Horde im nordöstlichen Arathihochland. Sie ehrt den ehemaligen Kriegshäuptling Orgrim Schicksalshammer, der bei der Befreiung der Internierungslager der Orcs in der Nähe fiel.",al={"was ist hammerfall","geschichte von hammerfall","wer gründete hammerfall"}},{q="Warum lässt Tallow Euch gegen Oger kämpfen, bevor Ihr Euch in Hammerfall meldet?",a="Hammerfall wird ständig angegriffen und braucht fähige Kämpfer. Tallow schickt Euch gegen die Oger der Felsfäuste, damit Ihr Eure Kampfkraft beweist, bevor Ihr zu Drum Teufel stoßt, statt als Last anzukommen.",al={"warum zuerst oger töten","tallows beweggrund","warum die prüfung"}},{q="Wer ist Drum Teufel?",a="Drum Teufel ist ein erfahrener Orckrieger und Kommandant in Hammerfall im Arathihochland. Er organisiert die Verteidigung gegen feindselige Wildtiere, Oger, Trolle und die Überreste der Allianz.",al={"drum teufels identität","kommandant von hammerfall","wer ist drum teufel"}},{q="Was folgt auf diesen Auftrag?",a="Die Meldung bei Drum Teufel führt zur Kampagne Call to Arms, einer Reihe militärischer Einsätze gegen umliegende Bedrohungen, darunter die Trollstämme der Witherbark, die das Hochland bedrohen.",al={"nächste quest","folgequest zu der hammer kann fallen","was kommt danach"}}},fx={b3b0715a={q="Wer sind die Boulderfist-Oger, gegen die Ihr ausgesandt werdet?",a="Der Boulderfist-Stamm ist ein brutaler Ogerclan, der im Arathihochland Territorium beansprucht, mit dem Schwerpunkt um ihren Hügel nordöstlich der Ruinen von Stromgarde. Wild, stur und körperlich imposant, beherrschen sie die felsigen Hügel des Hochlands und streitig gemachte Gebiete in der Umgebung. Tallow schickt Euch zu ihrem Hügel, um zu sehen, ob Ihr gegen ihre Vollstrecker an der Front bestehen könnt, um sicherzustellen, dass Ihr die notwendige Stärke besitzt, bevor Ihr Euch in den Fleischwolf der Arathi-Kriegszone werft.",al={"boulderfist oger","wer sind boulderfist","oger arathi"}}},fp="19,217,15.379.0,20.319.0,23.345.1,36.190.0,40.123.0,34.188.0,68.189.0,16.172.0,29.183.0"}
P.entries["quest:677"] = {n="Zu den Waffen",s="Drum Teufel ruft die Horde auf, von Hammerfall im Arathihochland aus zuzuschlagen. Die Witherbark haben sich den Ogern der Boulderfist angeschlossen, und die Horde will ihren Stützpunkt dort halten.",h="Drum Teufel ruft die Horde auf, von Hammerfall im Arathihochland aus zuzuschlagen.",kw={"arathihochland","axtwerfer","boulderfist","zu den waffen","drum teufel","hammerfall","kopfjäger","hexendoktor","witherbark"},ang={["faction:Horde"]="Hammerfall liegt abgeschieden im Arathihochland, umgeben von feindlichen Streitkräften. Die Verteidigung des Außenpostens ist wichtig, während die Horde versucht, sich im Land der Menschen zu behaupten.",["race:Orc"]="Hammerfall liegt auf dem Gelände eines ehemaligen Internierungslagers aus dem Zweiten Krieg. Für Euch als Ork trägt die Verteidigung dieser neuen Siedlung gegen feindliche Nachbarn das Gewicht der Befreiung.",["race:Troll"]="Als Troll der Dunkelspeer im Dienst von Thralls Horde steht Ihr den feindlichen Waldtrollen der Witherbark gegenüber. Ihre Ablehnung der neuen Horde offenbart eine tiefe Kluft zwischen Euren Völkern."},sec={{t="Die Verteidigung Hammerfalls",b="In Hammerfall versammelt Drum Teufel die Horde an ihrem befestigten Außenposten im Arathihochland. Alte Menschenruinen und feindliche Mächte umgeben die Siedlung. Die Waldtrolle der Witherbark und die Oger der Boulderfist haben einen Pakt geschlossen, der den Stützpunkt der Horde gefährdet. Drum Teufel ruft Streiter auf, zuerst zuzuschlagen und zu verhindern, dass ihre Feinde den Verlauf des Kampfes bestimmen."},{t="Die Bedrohung der Witherbark",b="Südlich von Hammerfall treffen die ersten Angriffe der Horde das Gebiet der Witherbark. Die Waldtrolle haben Diplomatie abgelehnt und sich den Ogern der Boulderfist angeschlossen, um die Horde aus dem Hochland zu vertreiben. Hammerfall nimmt ihre Axtwerfer, Kopfjäger und Hexendoktoren ins Visier, um ihre Anführer zu schwächen und zu zeigen, dass die Horde bleiben will."}},faq={{q="Wer bietet die Quest Zu den Waffen an?",a="Drum Teufel, ein Ork in Hammerfall im nordöstlichen Arathihochland, ruft die Horde zum Kampf. Er leitet Verteidigungs- und Vergeltungsangriffe, um den Außenposten vor Bedrohungen aus der Umgebung zu schützen.",al={"wer vergibt zu den waffen","wo ist drum teufel","questgeber zu den waffen"}},{q="Warum nimmt Hammerfall die Trolle der Witherbark ins Visier?",a="Die Waldtrolle der Witherbark haben sich den Ogern der Boulderfist angeschlossen, um die Horde aus dem Arathihochland zu vertreiben. Ihre Feindseligkeit gefährdet den Stützpunkt Hammerfall.",al={"warum witherbark töten","warum trolle in arathi angreifen","was haben die witherbark getan"}},{q="Wo befinden sich die Trolle der Witherbark?",a="Die Trolle der Witherbark leben in Siedlungen und Lagern südlich von Hammerfall, auch tief in Witherbark nahe den Bergen.",al={"wo sind die trolle der witherbark","lager der witherbark standort","wo sind axtwerfer in arathi"}},{q="Welche Rolle spielen die Oger der Boulderfist in diesem Konflikt?",a="Die Boulderfist sind ein brutaler Ogerklan im Arathihochland. Drum Teufel zufolge haben sie sich den Trollen der Witherbark angeschlossen, um die Horde aus dem Hochland zu vertreiben.",al={"wer sind die boulderfist","oger in arathi","bündnis zwischen boulderfist und trollen"}},{q="Was ist Hammerfall und warum muss es verteidigt werden?",a="Hammerfall ist der wichtigste Außenposten der Horde im Arathihochland, benannt nach Kriegshäuptling Orgrim Schicksalshammer. Es liegt auf dem Gelände eines alten Internierungslagers der Allianz und bietet der Horde einen hart erkämpften Zufluchtsort und Militärstützpunkt in den Östlichen Königreichen.",al={"was ist hammerfall","hammerfall geschichte","warum ist die horde in arathi"}},{q="Gehören die Trolle der Witherbark zur Horde?",a="Nein. Die Witherbark sind Waldtrolle aus den Östlichen Königreichen, während die Dschungeltrolle der Dunkelspeer zur Horde gehören. Die Witherbark lehnen Fremde ab und haben die Angebote der Horde gewaltsam zurückgewiesen.",al={"gehören die witherbark zur horde","sind waldtrolle der horde freundlich gesinnt","dunkelspeer gegen witherbark"}}},fp="12,173,20.364.0,21.332.0,34.181.0,50.170.0,40.129.0,57.165.0,50.229.0,44.202.0"}
P.entries["quest:678"] = {n="Zu den Waffen",s="In Hammerfall schickt Drum Teufel bewährte Krieger gegen die Oger der Boulderfist. Ihre Angriffe bedrohen den Stützpunkt der Horde in Arathi.",h="In Hammerfall schickt Drum Teufel bewährte Krieger gegen die Oger der Boulderfist.",kw={"arathihochland","boulderfist","boulderfist-raufbold","boulderfist magi","call to arms","drum teufel","hammerfall","oger","thandol-übergang"},ang={["class:Mage"]="Als Magier steht Ihr Boulderfist Magi gegenüber, die arkane Energien zu zerstörerischen Zwecken einsetzen.",["class:Warrior"]="Als Krieger stellt Ihr Euch einer unmittelbaren Prüfung Eurer Ausdauer und Ehre gegen rohe Gewalt und arkane Macht.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Hammerfalls Stützpunkt in den Östlichen Königreichen zu sichern, indem Ihr die angriffslustigen Oger der Boulderfist zurückdrängt.",["race:Orc"]="Als Orc liegt Euch Hammerfall, benannt nach Kriegshäuptling Orgrim Schicksalshammer, persönlich am Herzen, ebenso wie die Vertreibung der rivalisierenden Schläger, die diese Gedenkfestung bedrohen."},sec={{t="Eine Zerreißprobe",b="In Hammerfall ruft Drum Teufel Reisende, die dem Außenposten geholfen haben, dazu auf, sich einer echten Bedrohung zu stellen. Oger der Boulderfist haben die Expedition der Horde bedrängt und ihre Verteidiger auf die Probe gestellt. Teufel schickt Krieger gegen diese Feinde, keine unbedeutenden Scharmützler. Er erwartet, dass sie lebend oder mit Ehre zurückkehren, und verspricht ihnen Lob für ihre Zähigkeit im Kampf."},{t="Die Boulderfist-Bedrohung",b="Südwestlich von Hammerfall hat sich der Clan der Boulderfist nahe der Zwergenbrücke zwischen Arathi und dem Sumpfland verschanzt. Schläger kämpfen an der Seite gerissener Magier und vereinen so zermalmende Stärke mit tödlicher Magie. Ihre Angriffslust bedroht die Versorgungslinien der Horde und ihre Kontrolle über die Region. Drum Teufel befiehlt Kriegern, zehn Schläger und vier Magier der Boulderfist zu besiegen. Ihre Niederlage wird den Clan schwächen und zeigen, dass Hammerfall weder Boden preisgibt noch Rivalen in Arathi duldet."}},faq={{q="Wer vergibt die Quest „Call to Arms“?",a="Drum Teufel, ein Offizier in Hammerfall im nordöstlichen Arathihochland, lässt den Ruf erschallen. Er schickt bewährte Kämpfer gegen gefährliche Feinde, um den Außenposten zu schützen und ihre Stärke zu prüfen.",al={"wer vergibt call to arms","drum teufel quest","questgeber call to arms"}},{q="Wo befindet sich der Unterschlupf der Boulderfists?",a="Das Lager der Boulderfist liegt südwestlich von Hammerfall, am Weg zum Thandol-Übergang, der Zwergenbrücke ins Sumpfland. Schläger und Magier sammeln sich in Erdhöhlen und Hügeln im Hochland.",al={"standort der boulderfists","wo sind die oger","boulderfist-unterschlupf arathi"}},{q="Welche Feinde müssen für diese Aufgabe bezwungen werden?",a="Drum Teufel verlangt, zehn Boulderfist Brutes und vier Boulderfist Magi zu besiegen, bevor Ihr nach Hammerfall zurückkehrt. Schläger greifen im Nahkampf an, während Magier aus der Ferne arkane Zauber wirken.",al={"call to arms anzahl der siege","welche oger töten","call to arms ziele"}},{q="Warum gelten die Boulderfist-Oger als Bedrohung für Hammerfall?",a="Die Boulderfist haben sich überall in Arathi verschanzt und die Hordegarnison von Hammerfall wiederholt herausgefordert. Ihre Stellung nahe den Wegen zur südlichen Zwergenbrücke bedroht die Aufklärung und die Versorgungslinien der Horde, weshalb Drum Teufel ihre Macht eindämmen will.",al={"warum gegen boulderfists kämpfen","sind boulderfists feindlich gegenüber der horde","ogerbedrohung in arathi"}},{q="Was meint Drum Teufel damit, leibhaftig oder im Geiste zurückzukehren?",a="Drum Teufel erwartet, dass seine Kämpfer nach ihrem Erfolg lebend zurückkehren, ehrt aber jene, die im tapferen Kampf gegen mächtige Feinde fallen. Den Ogern mit Zähigkeit und Furchtlosigkeit entgegenzutreten bringt Ehre, ob ein Krieger überlebt oder nicht.",al={"zitat von drum teufel","bedeutung von im geiste zurückkehren","leibhaftig oder im geiste kommen"}},{q="Können Allianz-Spieler diese Quest annehmen?",a="Nein. Drum Teufel richtet diesen Aufruf nur an die Horde in Hammerfall. Die Streitkräfte der Allianz operieren von der Zuflucht im Westen aus und betrachten Hammerfalls Verteidiger sowie die Oger der Boulderfist als feindliche Rivalen um die Herrschaft über das Arathihochland.",al={"ist call to arms nur für die horde","allianz call to arms arathi","kann die allianz diese quest machen"}},{q="Warum nimmt Drum Teufel sowohl Raufbolde als auch Magier ins Visier?",a="Die Schläger bilden die vorderste Linie und stecken Schläge ein, während die Magier von hinten mit zerstörerischer Magie angreifen. Beide Arten zu besiegen schwächt die vereinte Stärke der Boulderfist und hindert sie daran, einen geordneten Gegenangriff auf Hammerfall zu führen.",al={"warum magier töten","wichtigkeit der boulderfist magi","boulderfist-raufbold und -magier"}}},fp="12,131,16.330.0,22.452.0,33.184.0,38.185.0,48.185.0,64.242.0,58.230.0,42.231.0,46.249.0"}
P.entries["quest:679"] = {n="Zu den Waffen",s="In Hammerfall schickt Drum Teufel Euch auf die Jagd nach den Boulderfist-Anführern in Stromgarde. Nach Euren bisherigen Taten sei es nun Zeit, der Bestie den Kopf abzuschlagen.",h="In Hammerfall schickt Drum Teufel Euch auf die Jagd nach den Boulderfist-Anführern in Stromgarde.",kw={"arathihochland","boulderfist","boulderfist-fürsten","boulderfist-schamanen","drum teufel","hammerfall","stromgarde"},sec={{t="Der Kopf des Ganzen",b="Drum Teufel sagt, Ihr seid bereit, bei einem letzten großen Schlag zu helfen. Die Boulderfist-Anführer haben sich in den Ruinen von Stromgarde eingenistet, die er als Sinnbild menschlicher Schwäche bezeichnet. Er schickt Euch los, um die Fürsten und die Schamanen zu jagen, die ihnen dienen. Sie führen Angriffe an, um die Horde aus diesen Landen zu vertreiben."}},faq={{q="Wer schickt Euch in den Kampf gegen die Boulderfist-Anführer?",a="Drum Teufel schickt Euch von Hammerfall aus los, dem Außenposten der Horde im Arathihochland.",al={"wer vergibt zu den waffen","drum teufel quest","wer startet zu den waffen 3"}},{q="Wo befinden sich die Boulderfist-Fürsten und Schamanen?",a="Die Boulderfist-Fürsten und Schamanen, die die Angriffe anführen, haben sich laut Drum Teufel in den Ruinen von Stromgarde verschanzt.",al={"wo sind die boulderfist-fürsten","boulderfist-schamanen fundort","wo sind die ogeranführer"}},{q="Wo steht dieser Schritt in der Questreihe?",a="Dies folgt auf das vorherige Zu den Waffen und ist der letzte Schritt der Questreihe, die bei Tallow in Tarrens Mühle beginnt.",al={"was kam vor zu den waffen 3","zu den waffen questreihe","hammerfall ogerquestreihe"}},{q="Was sollt Ihr für Drum Teufel mit den Boulderfist-Anführern tun?",a="Drum Teufel will, dass Ihr die Fürsten und Schamanen, die die Angriffe anführen, mit einem letzten großen Schlag tötet. Sie wollen die Horde aus diesen Landen vertreiben.",al={"warum boulderfist-fürsten töten","warum oger in stromgarde angreifen"}}},fp="12,157,21.304.0,47.78.0,51.105.0,40.112.0,56.138.0"}
P.entries["quest:68"] = {n="Die Legende von Stalvan",s="In Mondbruch führt Euch die Legende von Stalvan zurück zu Dunkelhains Aufzeichnungen. Ein verstaubter, nie abgeschickter Brief aus einer alten Fußtruhe belegt, dass Stalvan Dunstmantel dort verweilte, bevor sich seine Spur verlor.",h="In Mondbruch führt Euch die Legende von Stalvan zurück zu Dunkelhains Aufzeichnungen.",kw={"amtmann daltry","fluch von stalvan","dunkelhain","dämmerwald","ein verstaubter, nie abgeschickter brief","fußtruhe","unglückseliger geist","dunstmantel","mondbruch","stalvan"},ang={["class:Mage"]="Als Magier erkennt Ihr unter den unnatürlichen Kräften in Stalvans Gefolge die trügerischen arkanen Mittel des Schattens, von Verwandlung bis hin zu einem lähmenden Fluch.",["class:Priest"]="Als Priester erkennt Ihr, wie ein Unglückseliger Geist, gebunden an eine einfache Truhe voller Andenken, eine seelische Last trägt, die mit dem Tod nicht endete.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr Dunkelhain, die zwielichtigen Gestalten zu erfassen, die die Grenzen der Region überschritten haben."},sec={{t="Eine vergessene Spur in Mondbruch",b="Ihr findet einen verstaubten, nie abgeschickten Brief in einer alten Fußtruhe, während Ihr Stalvan Dunstmantels Vergangenheit nachspürt. Mondbruch war einst eine landwirtschaftliche Siedlung, liegt nun aber in Trümmern, voller Gesetzloser und rastloser Gespenster. Nur wenige erinnern sich an seinen kurzen Aufenthalt, doch der Brief belegt seine Anwesenheit in dem Weiler."},{t="Ein Spuk an der Fußtruhe",b="Wer die Fußtruhe anrührt, lockt einen Unglückseligen Geist aus den Schatten, der die Überreste bewacht. Er greift mit betörender Magie und dem schwächenden Fluch von Stalvan an. Trauer und dunkler Zauber haften noch immer an Stalvans Habseligkeiten."},{t="Das Stadtregister wird ergänzt",b="Ihr bringt den Brief über die Grenze nach Dunkelhain, wo Amtmann Daltry die städtischen Aufzeichnungen führt. Er findet es seltsam, dass der Brief nie verschickt wurde, doch der Beweis bestätigt Stalvans Verbindung zu Mondbruch. Die Aufzeichnungen können nun darauf hinweisen, wohin Stalvan als Nächstes floh."}},faq={{q="Was befindet sich in der alten Fußtruhe in Mondbruch?",a="Die alte Fußtruhe enthält einen verstaubten, nie abgeschickten Brief aus Stalvan Dunstmantels Zeit in Mondbruch. Er bestätigt, dass er dort lebte, bevor er verschwand.",al={"was habe ich gefunden","inhalt der fußtruhe","stalvans brief"}},{q="Warum greift ein Geist an, wenn die Truhe geöffnet wird?",a="Ein Unglückseliger Geist bewacht Stalvans vergessene Besitztümer und greift jeden an, der die Truhe anrührt. Er wirkt verstörende Magie, darunter Furcht- und Verwandlungszauber sowie den Fluch von Stalvan.",al={"unglückseliger geist","warum werde ich angegriffen","geist der fußtruhe"}},{q="Warum soll der Brief zu Amtmann Daltry gebracht werden?",a="Amtmann Daltry verwaltet Dunkelhains städtische Aufzeichnungen und das Stadtregister. Er braucht einen Beweis für Stalvans frühere Aufenthaltsorte, bevor er helfen kann, dessen Spur weiterzuverfolgen.",al={"wer ist amtmann daltry","warum daltry","rathaus von dunkelhain"}},{q="Warum ist es bedeutsam, dass der Brief nie verschickt wurde?",a="Der zurückgelassene Brief blieb in der Fußtruhe, was vermuten lässt, dass Stalvan überstürzt aufbrach oder zunehmend von Verfolgungswahn geplagt wurde. Seine Anwesenheit vertieft das Rätsel um Stalvans Wege.",al={"rätsel des nie abgeschickten briefes","warum wurde er nie verschickt"}},{q="Was bewirkt der Fluch von Stalvan?",a="Der Fluch von Stalvan, den der Unglückselige Geist wirkt, ist ein schwächender Fluch, der zehn Minuten lang alle Primärattribute seines Opfers verringert.",al={"fluch von stalvan schwächung","fluch des geistes"}},{q="Wohin führt die Spur, nachdem Daltry den Brief erhalten hat?",a="Nachdem Amtmann Daltry den Beweis aus Mondbruch in die Aufzeichnungen aufgenommen hat, kann er Euch zu Stalvans nächstem bekannten Aufenthaltsort weisen.",al={"was kommt als nächstes","wohin nach daltry","nächster hinweis"}}},fp="21,187,30.276.0,28.225.1,26.268.0,47.139.0,50.185.0,36.143.0,53.154.0,34.127.0,60.111.0"}
P.entries["quest:680"] = {n="Die echte Bedrohung",s="Korin Fel bittet Euch, die Angriffe auf Hammerfall zu beenden, indem Ihr Or'Kalar erschlagt und ihr seinen Kopf bringt.",h="Korin Fel bittet Euch, die Angriffe auf Hammerfall zu beenden, indem Ihr Or'Kalar erschlagt und ihr seinen...",kw={"arathihochland","hammerfall","korin fel","mug'thol","or'kalar","stromgarde","der turm von arathor"},sec={{t="Groll gegen ihren Ehemann",b="Korin Fel sagt, dass Ihr ihrem Ehemann gut dient, obwohl er nicht weiß, warum Hammerfall angegriffen wird. Or'Kalar dient Mug'thol in Stromgarde und trachtet ihrem Ehemann nach dem Leben. Vor Jahren hat ihr Ehemann den Oger besiegt. Nun warnen Korins Weissagungen davor, dass Or'Kalar ihm eine Falle gestellt hat."},{t="Was Korin verbirgt",b="Korin hat die Anzeichen für Or'Kalars Anwesenheit vor ihrem Ehemann verborgen. Sie fürchtet, er würde unbesonnen losstürmen, wenn er wüsste, wo der Oger ist, und bittet deshalb stattdessen Euch um Hilfe. Or'Kalar befindet sich nahe dem Turm von Arathor. Korin erwartet, dass sein Tod die Angriffe auf Hammerfall beendet."}},faq={{q="Wen versucht Korin Fel zu beschützen?",a="Korin Fel versucht, ihren Ehemann zu beschützen. Ihre Weissagungen warnen davor, dass Or'Kalar ihm eine Falle gestellt hat. Der Oger will ihn tot sehen, weil er ihn vor Jahren besiegt hat.",al={"korins ehemann","warum braucht korin hilfe"}},{q="Warum greift Or'Kalar Hammerfall an?",a="Or'Kalar greift Hammerfall als Mug'thols Marionette in Stromgarde an. Er hasst Korin Fels Ehemann, der ihn vor Jahren besiegt hat. Korin sagt, Or'Kalars Tod würde die Angriffe beenden.",al={"warum hasst or'kalar korins ehemann","wer ist or'kalar","or'kalars beweggrund"}},{q="Wo befindet sich Or'Kalar?",a="Nahe dem Turm von Arathor.",al={"or'kalars aufenthaltsort","wo ist or'kalar zu finden","or'kalar finden"}},{q="Warum hält Korin die Bedrohung vor ihrem Ehemann geheim?",a="Korin fürchtet, ihr Ehemann würde unbesonnen losstürmen, wenn er erführe, wo Or'Kalar ist. Deshalb hat sie jedes Anzeichen für die Anwesenheit des Ogers verborgen.",al={"warum geheim halten","warum or'kalar verheimlichen","korins geheimnis"}}},fp="15,98,28.274.0,16.266.0,35.158.0,37.171.0,26.30.0,57.135.0"}
P.entries["quest:681"] = {n="Nordhof",s="In der Zuflucht bittet Captain Nials Euch um Hilfe gegen das Syndikat auf dem Nordhof. Seine Kontrolle über das Land zwischen den Verteidigern von Stromgarde und Süderstade verzögert den Nachschub.",h="In der Zuflucht bittet Captain Nials Euch um Hilfe gegen das Syndikat auf dem Nordhof.",kw={"captain nials","wegelagerer","söldner","nordhof","die zuflucht","süderstade","stromgarde","syndikat"},sec={{t="Eine bedrängte Verteidigung",b="Oger, das Syndikat und die Allianz teilen Stromgarde unter sich auf, und die Fraktionen kämpfen sich in eine blutige Pattsituation. Die Streitkräfte der Allianz schwinden, während ihre Feinde erstarken. Die Verteidiger brauchen Hilfe aus Süderstade, doch der Nachschub trifft nur langsam ein."},{t="Das Syndikat auf dem Nordhof",b="Das Syndikat hält das Land zwischen den Verteidigern und Süderstade besetzt. Captain Nials bittet Euch, zum Nordhof zu gehen, dem Stützpunkt des Syndikats, und seine Wegelagerer und Mercenaries niederzustrecken. Er hofft, dass durch den nachlassenden Druck mehr Nachschubkarawanen durchkommen."}},faq={{q="Warum will Captain Nials das Syndikat auf dem Nordhof angreifen lassen?",a="Das Syndikat hält das Land zwischen den Verteidigern und Süderstade besetzt. Captain Nials hofft, dass der Druck auf die Nachschubkarawanen nachlässt, wenn Ihr seine Mitglieder in ihrem Stützpunkt tötet.",al={"warum den nordhof angreifen","nials ziel","zweck der nordhofquest"}},{q="Wie steht es derzeit um Stromgarde?",a="Oger, das Syndikat und die Allianz haben Stromgarde unter sich aufgeteilt, und die Fraktionen kämpfen sich in eine blutige Pattsituation. Die Streitkräfte der Allianz schwinden, während ihre Feinde erstarken.",al={"kriegslage in stromgarde","wer kontrolliert stromgarde","lage in stromgarde"}},{q="Woher kommt der Nachschub der Allianz?",a="Die Verteidiger hoffen auf Hilfe aus Süderstade, doch die Kontrolle des Syndikats über das Land dazwischen erschwert das Eintreffen von Nachschub.",al={"wer versorgt die zuflucht","nachschub aus süderstade","woher kommen die lieferungen"}},{q="Welche Feinde müssen auf dem Nordhof ausgeschaltet werden?",a="Zehn Wegelagerer und sechs Mercenaries des Syndikats auf dem Nordhof.",al={"wen auf dem nordhof töten","ziele auf dem nordhof","liste der syndikatsfeinde"}}},fp="15,162,20.224.0,26.254.0,70.163.0,44.162.0,44.124.0,49.74.0"}
P.entries["quest:682"] = {n="Abzeichen von Stromgarde",s="In Stromgarde zahlt das Syndikat für Milizabzeichen, die den Gefallenen abgenommen werden. In der Zuflucht will Captain Nials sie zurückgebracht haben.",h="In Stromgarde zahlt das Syndikat für Milizabzeichen, die den Gefallenen abgenommen werden.",kw={"arathi","abzeichen","captain nials","miliz","die zuflucht","stromgarde","syndikat"},sec={{t="Ein Kopfgeld auf Soldaten",b="Das Syndikat kämpft in Stromgarde gegen ein Kontingent der Miliz. Seine Anführer bieten Gold für jedes Abzeichen eines erschlagenen Milizsoldaten und hoffen, ihre Gefolgsleute so gegen die besser ausgebildeten Soldaten aufzuhetzen. Captain Nials nennt das Syndikat Halsabschneider und weigert sich, ihnen Trophäen der tapferen Gefallenen zu überlassen. Ihr betretet den von ihnen gehaltenen Teil von Stromgarde und bringt die Abzeichen zur Zuflucht zurück. Nials will ihnen klarmachen, dass sie aus den Toten keinen Profit schlagen können."},{t="Nach der Jagd",b="Captain Nials verspricht, den Angehörigen der gefallenen Milizsoldaten mitzuteilen, dass ihre Verwandten im Kampf gestorben sind. Die Nachricht ist düster, doch er hält sie für besser, als eine Familie im Ungewissen darüber zu lassen, was aus einem Vermissten geworden ist."}},faq={{q="Warum will das Syndikat Abzeichen von Stromgarde?",a="Die Anführer des Syndikats bieten Gold für jedes Abzeichen, das einem gefallenen Milizsoldaten abgenommen wird. Sie hoffen, dass die Bezahlung ihre Gefolgsleute zum Kampf gegen die besser ausgebildeten Truppen antreibt.",al={"warum syndikat abzeichen","syndikat kopfgeld stromgarde","warum abzeichen sammeln"}},{q="Wo sind die Abzeichen zu finden?",a="Ihr findet die Abzeichen in dem Teil von Stromgarde, den das Syndikat kontrolliert.",al={"wo abzeichen finden","stromgarde abzeichen fundort","abzeichen beute fundort"}},{q="Wer befiehlt die Bergung der Abzeichen?",a="Captain Nials in der Zuflucht befiehlt die Bergung der Abzeichen. Sie will nicht zulassen, dass das Syndikat Trophäen der gefallenen Milizsoldaten behält.",al={"wer vergibt abzeichen von stromgarde","captain nials abzeichen quest","questgeber abzeichen von stromgarde"}}},fp="17,132,20.450.0,14.215.1,46.161.0,27.74.0,39.129.0"}
P.entries["quest:683"] = {n="Sara Balloos Hilfegesuch",s="In Eisenschmiede trauert Sara Balloo um Sully und bittet Euch, ihr Gesuch zu König Magni Bronzebart zu bringen.",h="In Eisenschmiede trauert Sara Balloo um Sully und bittet Euch, ihr Gesuch zu König Magni Bronzebart zu...",kw={"a king's tribute","dun morogh","eisenschmiede","magni bronzebart","sara balloo","sully balloo","thandol-übergang"},ang={["faction:Alliance"]="Als Mitglied der Allianz überbringt Ihr Nachrichten zwischen trauernden Bürgern und den Anführern der Allianz. Ihr werdet Zeuge des persönlichen Leids, das die Bewahrung des Reiches fordert.",["race:Dwarf"]="Als Zwerg berührt das Überbringen des Gesuchs einer trauernden Witwe an Euren König die Bedeutung, die Euer Volk der Steinmetzkunst, der Abstammung und dem Gedenken an die Opfer der Ahnen beimisst."},sec={{t="Die Bitte einer Witwe",b="Sara hat Sullys letzten Brief erhalten, der aus den Gewässern am Thandol-Übergang geborgen wurde. Sie möchte, dass der König seines Opfers gedenkt, und schreibt ihm deshalb ein Gesuch. Ihre Trauer hindert sie daran, selbst vor den Thron zu treten. Sie vertraut Euch als Streiter der Allianz den versiegelten Brief an, damit Ihr ihn zu König Magni Bronzebart bringt."},{t="Audienz beim König",b="Am High Seat in Eisenschmiede legt König Magni Bronzebart die Staatsgeschäfte beiseite, um Saras persönliches Gesuch zu lesen. Er nimmt die tapferen Verteidiger von Khaz Modan wahr. Seine Aufmerksamkeit zeigt seine Verbundenheit mit den einfachen Zwergen, die sein Bergkönigreich erbaut haben und verteidigen."}},faq={{q="Wer ist Sara Balloo?",a="Sara Balloo ist eine Zwergin, die in Eisenschmiede lebt. Ihr Mann, der Soldat Sully Balloo, starb bei der Tragödie am Thandol-Übergang, und sie hält sein Andenken in Ehren.",al={"sara balloo","wer ist sara"}},{q="Warum möchte Sara, dass ich den König aufsuche, statt selbst zu gehen?",a="Sara ist von Trauer überwältigt, seit sie erfahren hat, was Sully zugestoßen ist. Sie fühlt sich außerstande, die Fassung zu bewahren, die bei einem Gesuch an König Magni Bronzebart am High Seat erwartet wird.",al={"warum kann sara nicht gehen","saras trauer"}},{q="Wer war Sully Balloo?",a="Sully Balloo war ein zwergischer Soldat, der den Thandol-Übergang verteidigte. Er fiel im Kampf auf der Brücke und hinterließ einen durchnässten Brief an seine Frau.",al={"sully balloo","saras ehemann"}},{q="Wo gebe ich Sara Balloos Hilfegesuch ab?",a="Ihr überbringt Saras Gesuch König Magni Bronzebart am High Seat im Zentrum von Eisenschmiede.",al={"wo ist magni","könig magni aufenthaltsort","abgabeort"}},{q="Was geschieht, nachdem König Magni das Gesuch gelesen hat?",a="Nachdem König Magni Saras Gesuch gelesen hat, ehrt er Sully Balloo, was zu A King's Tribute und zur Errichtung eines bleibenden Denkmals führt.",al={"questfortsetzung","nächste quest"}},{q="Welche Fraktion kann diese Aufgabe übernehmen?",a="Nur Mitglieder der Allianz können Saras Gesuch überbringen, bei dem es um zwergische Angelegenheiten und eine Audienz bei König Magni Bronzebart geht.",al={"kann die horde das machen","fraktionsvoraussetzung"}}},fx={ca82ce02={q="Warum möchte Sara Balloo, dass ihr Gesuch an König Magni Bronzebart übermittelt wird?",a="Sara Balloo trauert um den Verlust ihres Mannes, Sully Balloo, der bei der Verteidigung von The Thandol Span fiel. Nachdem sie endlich seinen letzten Brief erhalten hat, der unter der Spannbrücke geborgen wurde, möchte sie, dass König Magni Bronzebart das Opfer von Sully offiziell anerkennt und sein Andenken ehrt. Die Übermittlung dieses Gesuchs ist ihre Art sicherzustellen, dass die Hingabe ihres verstorbenen Mannes an die Allianz in Eisenschmiede in Erinnerung bleibt.",al={"warum will sara balloo dies erledigt haben","sara balloos motiv","warum gesuch an magni schicken"}}},fp="18,101,17.321.0,22.261.1,19.150.0,63.170.0,21.141.0,38.96.0,45.126.1,37.129.0"}
P.entries["quest:684"] = {n="GESUCHT: Marez Cowl",s="In Stromgarde berät Marez Cowl die Anführer des Syndikats und paktiert mit Dämonen. Ihr Einfluss bedroht die Streitkräfte der Allianz im Arathihochland.",h="In Stromgarde berät Marez Cowl die Anführer des Syndikats und paktiert mit Dämonen.",kw={"arathihochland","kopfgeld","captain nials","marez cowl","die zuflucht","stromgarde","syndikat","hexenmeister"},ang={["class:Paladin"]="Als Hexenmeisterin, die in den Ruinen eines alten Menschenkönigreichs offen mit Dämonen paktiert, ist Cowl ein Affront gegen das Heilige Licht und die Verteidigung Stromgardes.",["class:Warlock"]="Marez Cowl gehört zum finsteren okkulten Flügel des Syndikats. Ihre Dämonenbeschwörungen zeigen, wie politische Abtrünnige sich Dämonen zuwenden, um ihren Einfluss auszuweiten.",["faction:Alliance"]="Die Garnison der Allianz in der Zuflucht kämpft unter der Führung von Captain Nials darum, Stromgarde zurückzuerobern. Hochrangige Anführer des Syndikats wie Marez Cowl sind vorrangige strategische Ziele."},sec={{t="Kopfgeld auf die Syndikatsführung",b="In der Zuflucht setzen die Kommandanten der Allianz ein Kopfgeld auf eine hochrangige Anführerin des Syndikats aus. Marez Cowl berät das Syndikat und leitet als Agentin vor Ort dessen Arbeit in den Ruinen von Stromgarde. Das Kopfgeld soll die örtliche Befehlsstruktur der Gruppe zerschlagen."},{t="Die Hexenmeisterin von Stromgarde",b="Marez Cowl ist eine Hexenmeisterin unter den Räubern und enteigneten Adligen des Syndikats. Sie paktiert offen mit dämonischen Mächten, um ihren Willen durchzusetzen und das Gebiet des Syndikats zu verteidigen. Um ihr Versteck in Stromgarde zu erreichen, müsst Ihr Euch bewaffneten Verbrechern und den Dämonen stellen, die sie befehligt."}},faq={{q="Wer ist Marez Cowl?",a="Marez Cowl ist eine hochrangige Beraterin und Agentin des Syndikats. Sie besitzt Einfluss innerhalb der Organisation und ist eine gefährliche Hexenmeisterin, die mit Dämonen paktiert.",al={"wer ist marez cowl","marez cowl hintergrund","wer ist sie"}},{q="Wo befindet sich Marez Cowl?",a="Marez Cowl befindet sich im vom Syndikat besetzten Teil des zerstörten Stromgarde im Arathihochland. Dort haben sich Verbrecher verschanzt, und Ihr müsst Euch einen Weg durch ihre Reihen bahnen, um ihr Versteck zu erreichen.",al={"wo marez cowl finden","marez cowl aufenthaltsort","wo ist marez"}},{q="Wer hat das Kopfgeld auf Marez Cowl ausgesetzt?",a="Das Militär der Allianz im Arathihochland setzt das Kopfgeld aus. Captain Nials, Kommandant der Allianzfestung in der Zuflucht, ist dafür verantwortlich.",al={"wer hat kopfgeld auf marez cowl ausgesetzt","wer will marez cowl tot sehen","wer zahlt kopfgeld"}},{q="Warum ist ein Kopfgeld auf sie ausgesetzt?",a="Marez Cowl wird wegen ihrer Führungsrolle im Syndikat und der Beschwörung von Dämonen in Stromgarde gesucht. Sie bedroht die Garnison der Allianz, die versucht, das zerstörte Königreich zurückzuerobern.",al={"warum wird marez cowl gesucht","warum kopfgeld auf marez cowl","warum marez cowl töten"}},{q="Welche Art von Magie nutzt Marez Cowl?",a="Marez Cowl nutzt Hexenmeistermagie, um Dämonen zu beschwören und mit ihnen zu verhandeln. Seid äußerst vorsichtig, wenn Ihr Euch ihr und den Dämonen stellt, die sie befehligt.",al={"was macht marez cowl gefährlich","marez cowl kräfte","ist marez cowl stark"}},{q="Wo holt Ihr das Kopfgeld für Marez Cowl ab?",a="Nachdem Marez Cowl getötet wurde, bringt ihren Kopf zu Captain Nials in der Zuflucht, dem Außenposten der Allianz im Arathihochland.",al={"wo kopfgeld für marez cowl abholen","wo ist captain nials","marez kopf abgeben"}}},fp="18,142,31.242.0,25.262.0,18.155.0,28.184.0,36.147.0,34.171.0,39.132.0,47.124.0"}
P.entries["quest:685"] = {n="GESUCHT: Falkenstein und Otto",s="Im Arathihochland hat die Stromgarde-Miliz Lord Falkenstein und Otto zum Tode verurteilt. Falkenstein führt die örtlichen Streitkräfte des Syndikats an, und Otto beschützt ihn mit tödlichem Geschick. Ihr Tod würde den Einfluss des Syndikats in der Region schwächen. Ein Beweis muss Captain Nials in der Zuflucht erreichen.",h="Im Arathihochland hat die Stromgarde-Miliz Lord Falkenstein und Otto zum Tode verurteilt.",kw={"arathihochland","kopfgeld","captain nials","falkenstein","otto","die zuflucht","stromgarde-miliz","syndikat"},ang={["faction:Alliance"]="Lord Falkenstein und seine Agenten des Syndikats bedrohen die Überreste Stromgardes. Dieses Kopfgeld ist für die Rückeroberung des Hochlands von Bedeutung.",["race:Human"]="Als Mensch steht Ihr vor einem persönlichen Kampf. Die verräterischen Menschenadligen des Syndikats zu Fall zu bringen, hilft Euch, Euer gefallenes Königreich zu rächen."},sec={{t="Ein verzweifeltes Kopfgeld",b="Von der Zuflucht aus versuchen Stromgardes Verteidiger, die Herrschaft des Syndikats über ihre angestammten Länder zu brechen. Die Miliz hat ein Kopfgeld auf Lord Falkenstein und Otto, seinen Leibwächter, ausgesetzt. Bringt die Köpfe beider Ziele zu Captain Nials, um die Belohnung zu erhalten."},{t="Befehlshaber und Vollstrecker",b="Lord Falkenstein lenkt den Vorstoß des Syndikats ins Arathihochland. Sein Tod würde die Arbeit des kriminellen Netzwerks in der Region stören. Otto ist ein brutal effektiver Leibwächter. Seine Klingen haben Dutzende von Stromgardes verbliebenen Milizsoldaten getötet."}},faq={{q="Wer ist Lord Falkenstein?",a="Lord Falkenstein ist ein Adliger, der die Unternehmungen des Syndikats im Arathihochland befehligt. Er organisiert ihren Versuch, das zerrüttete Königreich Stromgarde zu erobern, und ist damit eines der Hauptziele der örtlichen Menschenmiliz.",al={"wer ist lord falkenstein","falkensteins geschichte","wer ist falkenstein"}},{q="Wer ist Otto?",a="Otto ist Lord Falkensteins tödlicher persönlicher Leibwächter. Er ist eher ein wilder Kämpfer als ein Stratege und hat Dutzende von Stromgardes Verteidigern im Hochland erschlagen.",al={"wer ist otto","falkensteins leibwächter","otto syndikat"}},{q="Warum hat die Stromgarde-Miliz ein Kopfgeld auf sie ausgesetzt?",a="Die Stromgarde-Miliz will die Führung des Syndikats im Arathihochland entscheidend schwächen. Falkensteins Tod würde ihre regionale Befehlsstruktur stören, während Ottos Tod eine tödliche Bedrohung beseitigen würde, die viele Kämpfer der Allianz getötet hat.",al={"warum kopfgeld auf falkenstein","warum otto und falkenstein töten","stromgarde kopfgeld"}},{q="Wer bietet die Belohnung für Otto und Falkenstein an?",a="Captain Nials, ein Offizier der Stromgarde-Miliz in der Zuflucht im Arathihochland, nimmt die Kopfgeldbeweise für Lord Falkenstein und Otto entgegen.",al={"wo otto falkenstein abgeben","wer ist captain nials","falkenstein kopfgeld abgeben"}},{q="Was tut das Syndikat im Arathihochland?",a="Das Syndikat besteht aus gefallenen Alteraci-Adligen und abtrünnigen Kräften, die inmitten des Zusammenbruchs des nördlichen Lordaeron nach Land und Reichtümern streben. Vom Arathihochland aus sind sie in Stromgardes Ruinen vorgedrungen, um den überlebenden Verteidigern die Kontrolle zu entreißen.",al={"was ist das syndikat arathi","rolle des syndikats in arathi"}},{q="Welcher Beweis ist erforderlich, um das Kopfgeld zu erhalten?",a="Bringt die abgeschlagenen Köpfe von Lord Falkenstein und Otto als Beweis für ihren Tod direkt zu Captain Nials in der Zuflucht.",al={"wohin mit ottos kopf","kopfgeldbeweis"}}},fp="28,291,18.246.0,22.253.0,24.212.0,12.163.0,55.236.0,47.146.0,52.243.0,43.121.0"}
P.entries["quest:686"] = {n="Ehrerbietung von einem König",s="König Magni Bronzebart antwortet Sara Balloo mit einer bleibenden Ehrung für ihren gefallenen Ehemann Sully. Er schickt Euch mit einem königlichen Auftrag für Großsteinmetz Marmorstein quer durch Eisenschmiede.",h="König Magni Bronzebart antwortet Sara Balloo mit einer bleibenden Ehrung für ihren gefallenen Ehemann Sully.",kw={"eisenschmiede","magni bronzebart","marmorstein","denkmal","sara balloo","sully balloo","thandol-übergang"},ang={["faction:Alliance"]="Als Kämpfer der Allianz wisst Ihr, dass die Gefallenen am Thandol-Übergang ihr Leben ließen, um lebenswichtige Versorgungslinien zwischen Khaz Modan und den nördlichen Königreichen zu schützen.",["race:Dwarf"]="Als Zwerg seht Ihr König Magnis Hingabe an sein Volk. Selbst der einfachste zwergische Fußsoldat bleibt dem Thron in Erinnerung."},sec={{t="Die Bürde eines Herrschers",b="Sara Balloos Hilfegesuch lastet auf König Magni Bronzebart. Die harten Erfordernisse des Krieges sind für das einfache Volk oft schwer zu verstehen, doch jeder Soldat unter dem Banner der Allianz lastet auf seinem Gewissen. Er kann einen Tod an der Front nicht ungeschehen machen. Er kann dafür sorgen, dass Sully Balloos Opfer in Erinnerung bleibt."},{t="Der Meißel des Steinmetzen",b="König Magni entscheidet sich für ein steinernes Denkmal für Sully, statt für leere Worte. Er vertraut Euch seinen königlichen Auftrag an und schickt Euch quer durch Eisenschmiede zu Großsteinmetz Marmorstein. Der Meistersteinmetz empfängt den persönlichen Auftrag des Königs und bereitet sich darauf vor, das Andenken des gefallenen Verteidigers in Stein zu meißeln."}},faq={{q="Wer war Sully Balloo?",a="Sully Balloo war ein zwergischer Soldat, der bei der Verteidigung des Thandol-Übergangs für die Allianz fiel. Als seine Witwe Sara Balloo von seinem Tod erfuhr, richtete sie ein Hilfegesuch an König Magni Bronzebart.",al={"wer ist sully","sully balloos geschichte","wer ist gefallen"}},{q="Warum gibt König Magni ein Denkmal in Auftrag?",a="König Magni trägt die Last jedes Zwergenlebens, das in den Kämpfen der Allianz verloren geht. Er kann Sully seiner Witwe nicht zurückgeben, also gibt er ein bleibendes Denkmal in Auftrag, um den Mut des Soldaten zu ehren.",al={"warum ein denkmal errichten","magnis beweggrund","zweck der ehrerbietung von einem könig"}},{q="Wer ist Großsteinmetz Marmorstein?",a="Großsteinmetz Marmorstein ist Eisenschmiedes Meister der Steinbearbeitung. Ihm werden bedeutende städtische und königliche Bauvorhaben in der ganzen Stadt anvertraut, und König Magni verlässt sich darauf, dass er Sully Balloos Denkmal erschafft.",al={"wer ist marmorstein","aufgabe des großsteinmetzen"}},{q="Wo spielt diese Quest?",a="Ihr reist innerhalb von Eisenschmiede, zunächst zum High Seat zu König Magni Bronzebart und dann zu Großsteinmetz Marmorstein anderswo in der Hauptstadt.",al={"wo spielt diese quest","questschauplatz"}},{q="Was kommt vor dieser Quest?",a="Zuvor überbringt Ihr Sara Balloos von Herzen kommenden Brief direkt an König Magni Bronzebart.",al={"voraussetzungen","vorherige quest"}},{q="Ist dieses Denkmal nur für Sully Balloo?",a="Das Denkmal trägt Sully Balloos Namen und soll seiner Witwe Sara Trost spenden. Es ehrt auch jeden zwergischen Kämpfer, der im Dienst der Allianz fällt.",al={"wer wird geehrt","ist es nur für sully"}}},fx={["66401eff"]={q="Warum wählt König Magni Bronzebart Euch als Verwalter für den Tribut?",a="Ihr wart die Person, die das herzliche Gesuch von Sara Balloo direkt in den High Seat getragen und ihr persönliches Schicksal vor den Thron gebracht hat. Weil Ihr Euch entschieden habt, dem Kummer einer trauernden Witwe zuzuhören und ihre Worte dem König zu überbringen, betraut Magni Euch damit, die königliche Ehrung durchzuführen, wodurch Ihr zum Verwalter seines Auftrags werdet, anstatt ihn an Palastbürokraten zu delegieren.",al={"warum ich kings tribute","warum schickt euch magni","warum ich"}}},fp="16,177,20.284.0,18.284.0,21.176.0,42.190.0,30.203.0,33.149.0,29.91.0,39.146.0"}
P.entries["quest:687"] = {n="Theldurin der Verirrte",s="Im Ödland jagt der Schattenhammerkult Theldurin den Verirrten und die Rolle von Myzrael, die er auf seiner Flucht mitnahm.",h="Im Ödland jagt der Schattenhammerkult Theldurin den Verirrten und die Rolle von Myzrael, die er auf seiner...",kw={"ödland","gerrig knochengriff","myzrael","rolle von myzrael","theldurin","theldurin der verirrte","schattenhammerkult","zaruk"},sec={{t="Der Dieb der Rolle",b="Theldurin folgte einst dem Schattenhammerkult. Dann verlor er den Verstand und wandte sich von dessen Lehren ab. Er floh mit der Rolle von Myzrael, und der Orden konnte ihn nicht einholen."},{t="Gerüchte aus dem Ödland",b="Der Schattenhammerkult hat erfahren, dass Theldurin sich rasend und verrückt im Ödland versteckt. Der Orden braucht die Rolle für die Rückkehr der Herrin. Zuerst müsst Ihr den Mann finden, der sie an sich genommen hat."}},faq={{q="Wer ist Theldurin der Verirrte?",a="Theldurin der Verirrte folgte einst dem Schattenhammerkult. Nachdem er den Verstand verloren hatte, verwarf er dessen Lehren und floh mit der Rolle von Myzrael.",al={"theldurins vorgeschichte","wer ist theldurin","theldurins geschichte"}},{q="Warum sucht der Schattenhammerkult nach ihm?",a="Der Schattenhammerkult sucht Theldurin, weil er mit der Rolle von Myzrael floh. Der Orden sagt, er brauche die Rolle, um die Herrin zurückzubringen.",al={"warum theldurin finden","warum suchen kultisten theldurin"}},{q="Wohin floh Theldurin, nachdem er den Orden verlassen hatte?",a="Gerüchten zufolge hält sich Theldurin im Ödland auf, doch der Schattenhammerkult weiß nicht genau, wo er ist.",al={"wo ist theldurin","theldurins aufenthaltsort und geschichte"}},{q="Was kommt unmittelbar vor dieser Suche?",a="Die Suche folgt auf Myzrael's Allies.",al={"vorherige quest theldurin","voraussetzung für theldurin den verirrten"}}},fp="18,115,28.174.0,22.184.0,26.142.0,45.140.0,49.96.0,39.36.0"}
P.entries["quest:688"] = {n="Myzraels Verbündete",s="Durch den Schlüsselstein erklärt Myzrael, sie sei frei, halte sich aber noch vor ihren Häschern verborgen. Sie schickt Euch zu Zaruk in Hammerfall, der weiß, wie man sie beschwören kann.",h="Durch den Schlüsselstein erklärt Myzrael, sie sei frei, halte sich aber noch vor ihren Häschern verborgen.",kw={"arathihochland","riesen","hammerfall","schlüsselstein","myzrael","zaruk"},sec={{t="Frei, doch verborgen",b="Myzrael erklärt durch den Schlüsselstein, dass sie frei ist. Sie muss im Verborgenen ihre Kräfte sammeln. Ihre Häscher würden sie überwältigen und erneut einsperren, wenn sie ihr jetzt gegenüberträten. Sie schwört, sich zu gegebener Zeit den Riesen zu stellen, die sie gefangen hielten, und sie dafür büßen zu lassen."},{t="Zaruk von Hammerfall",b="Myzrael nennt Euch einen edlen Verbündeten und sagt, dass sie Eure Hilfe zu gegebener Zeit erneut brauchen wird. Wenn sie bereit ist, wird sie Euch auftragen, sie an die Oberfläche zu beschwören. Vorerst schickt sie Euch zu Zaruk in Hammerfall, der weiß, wie das geschehen kann."}},faq={{q="Wer schickt Euch zu Zaruk?",a="Myzrael selbst spricht durch den Schlüsselstein und fordert Euch auf, Zaruk in Hammerfall aufzusuchen.",al={"wer vergibt myzraels verbündete","questgeber myzraels verbündete","wer spricht durch den schlüsselstein"}},{q="Warum versteckt sich Myzrael?",a="Myzrael sagt, ihre Häscher würden sie überwältigen und erneut einsperren, wenn sie ihr jetzt gegenüberträten. Sie versteckt sich, während sie ihre Kräfte sammelt.",al={"warum kämpft myzrael nicht","warum ist myzrael schwach","warum versteckt sich myzrael"}},{q="Wo ist Zaruk zu finden?",a="Zaruk ist in Hammerfall zu finden.",al={"zaruk standort","wo ist zaruk","zaruk finden"}},{q="Welche Rolle spielt Zaruk für Myzrael?",a="Myzrael sagt, Zaruk weiß, wie sie beschworen werden kann.",al={"warum mit zaruk sprechen","was weiß zaruk","zaruks aufgabe"}}},fp="16,157,15.260.0,19.211.0,23.85.0,22.122.0,25.33.0,38.49.0"}
P.entries["quest:689"] = {n="Ehrerbietung von einem König",s="König Magni Bronzebart hat ein Denkmal für Sully Balloo angeordnet, der bei der Verteidigung des Thandol-Übergangs fiel. Großsteinmetz Marmorstein schickt Euch nach Norden ins Hügelland, um Stein zu beschaffen, der des gefallenen Soldaten würdig ist.",h="König Magni Bronzebart hat ein Denkmal für Sully Balloo angeordnet, der bei der Verteidigung des...",kw={"alteracgranit","darrow hill","eisenschmiede","magni bronzebart","marmorstein","steinmetz","sully balloo","thandol-übergang"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Materialien aus dem Hillsbrad zu beschaffen und die Präsenz der Allianz im zerrütteten Norden zu stärken. Das Denkmal ehrt einen einfachen Soldaten, der für die gemeinsame Sache starb.",["profession:Mining"]="Als Bergmann wisst Ihr, dass die harten, unnachgiebigen Adern des Alteracgranits erfahrene Hände erfordern, um den Stein sauber und ohne Brüche abzubauen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Steinmetzkunst, Opfer im Kampf und Treue zu König Bronzebart eng miteinander verbunden sind. Die Ehrung Sully Balloos berührt alle drei."},sec={{t="Ein königlicher Auftrag",b="Großsteinmetz Marmorstein hat von König Magni Bronzebart den Auftrag erhalten, Sully Balloo zu ehren. Sully starb bei der Katastrophe am Thandol-Übergang. Dunkeleisensaboteure haben den Übergang angegriffen, eine lebenswichtige Schlagader zwischen den Zwergenlanden und den nördlichen Königreichen. Marmorstein wird eine Skulptur schaffen, die Zeit und Krieg trotzt, damit die Große Schmiede das Opfer der Zwerge in Erinnerung behält."},{t="Stein des Nordens",b="Für Sully Balloos Abbild benötigt Marmorstein Alteracgranit. Sein dichtes, widerstandsfähiges Gestein und seine gleichmäßige Struktur machen ihn bei Steinmetzen begehrt. Die besten Vorkommen liegen um Darrow Hill in den umkämpften Ausläufern des Hillsbrad. Die Reise in den unruhigen Norden ist gefährlich, doch Marmorstein sucht Stein, der des Heldentums würdig ist, das er ehren soll."}},faq={{q="Wer ist Sully Balloo?",a="Sully Balloo war ein Soldat der Allianz, der bei der Verteidigung des Thandol-Übergangs während des verheerenden Sabotageakts fiel. Nachdem seine Witwe Sara Balloo einen von Trauer erfüllten Brief geschickt hatte, ordnete König Magni Bronzebart eine dauerhafte Statue zu seinen Ehren an.",al={"sully balloo","wer war sully balloo","sully balloo hintergrundgeschichte"}},{q="Wer ist Großsteinmetz Marmorstein?",a="Großsteinmetz Marmorstein ist Eisenschmiedes Meisterbildhauer und Steinmetz. Er arbeitet in den Commons der Stadt, übernimmt königliche Aufträge und ist stolz darauf, die besten Steine der Region zu verwenden.",al={"großsteinmetz marmorstein","marmorstein eisenschmiede","wer ist marmorstein"}},{q="Warum wird Alteracgranit benötigt?",a="Alteracgranit wird in den gesamten Östlichen Königreichen wegen seiner Dichte, seiner feinen Körnung und seiner Widerstandsfähigkeit gegen Erosion geschätzt. Marmorstein glaubt, dass nur Stein dieser Qualität einer königlichen Ehrung über die Zeitalter hinweg Bestand verleihen kann.",al={"warum alteracgranit","alteracgranit zweck","was ist alteracgranit"}},{q="Wo liegt Darrow Hill?",a="Darrow Hill liegt im nördlichen Vorgebirge des Hügellands, unmittelbar unterhalb von Headland und nahe der Grenze zu Alterac. Die dortigen Höhlen bergen Alteracgranit.",al={"wo liegt darrow hill","dar­row hill lage","dar­row hill finden"}},{q="Was geschah am Thandol-Übergang?",a="Der Thandol-Übergang ist eine gewaltige Brücke über die Schlucht zwischen dem Sumpfland und dem Arathihochland. Dunkeleisensaboteure platzierten Sprengstoff, um die Versorgungswege der Allianz zu unterbrechen, und töteten dabei viele Verteidiger.",al={"thandol-übergang tragödie","thandol-übergang katastrophe","was geschah am thandol-übergang"}},{q="Was geschieht, nachdem der Granit zu Marmorstein gebracht wurde?",a="Wenn Ihr Marmorstein den Alteracgranit bringt, vollendet er das Denkmal und bittet Euch, König Magni dessen Fertigstellung zu melden.",al={"nach abgabe des granits","marmorstein statue fortschritt"}}},fx={["1680ec58"]={q="Warum will Großsteinmetz Marmorstein, dass dies erledigt wird?",a="König Magni Bronzebart hat persönlich ein Denkmal in Auftrag gegeben, um den gefallenen Soldaten Sully Balloo zu ehren. Für Großsteinmetz Marmorstein haben königliche Aufträge höchste Priorität und erfordern seine beste Arbeit. Obwohl er das endlose Blutvergießen in ganz Azeroth beklagt, besteht er darauf, nur den feinsten Stein zu verwenden, um einen wirklich epischen, bleibenden Tribut zu schaffen, der dem Wunsch des Königs würdig ist.",al={"warum interessiert das marmorstein","marmorsteins motiv","warum sully balloo monument bauen"}}},fp="16,192,18.364.0,18.333.0,20.224.0,30.184.0,30.206.0,21.139.0,34.192.0,54.125.0"}
P.entries["quest:69"] = {n="Die Legende von Stalvan",s="In Dunkelhain lenkt ein zerkratzter Registereintrag die Suche nach Stalvan Dunstmantel nach Goldhain.",h="In Dunkelhain lenkt ein zerkratzter Registereintrag die Suche nach Stalvan Dunstmantel nach Goldhain.",kw={"amtmann daltry","dunkelhain","dämmerwald","wald von elwynn","goldhain","gastwirt farley","gasthaus \"zur höhle des löwen\"","stalvan"},ang={["faction:Alliance"]="Örtliche Überlieferungen und erkaltete Spuren führen durch den Süden der Allianz, zwischen Grenzposten wie Dunkelhain und Weilern wie Goldhain.",["race:Human"]="Von der heimgesuchten Grenzregion des Dämmerwalds führt Stalvans Spur durch das Herz des Königreichs Sturmwind zum vertrauten Wald von Elwynn."},sec={{t="Eine Spur im Register",b="Amtmann Daltry findet unter Stalvan Dunstmantels früherem Eintrag im Stadtregister von Dunkelhain ein weiteres Ziel. Die hastige Notiz ist teilweise durchgestrichen. Jemand wollte den Weg verbergen oder hat es sich anders überlegt. Sie weist nach Nordwesten zum Gasthaus \"Zur Höhle des Löwen\" im Wald von Elwynn."},{t="Hinüber nach Elwynn",b="Ihr verlasst die schattigen Haine des Dämmerwalds und erreicht Goldhains sonnige Straßen, wohin auch Stalvans Spur führt. Das Gasthaus \"Zur Höhle des Löwen\" steht am Wegekreuz im Wald von Elwynn, wo sich Reisende, Händler und Soldaten versammeln. Gastwirt Farley führt den geschäftigen Schankraum und weiß vielleicht von einem gebildeten Wanderer, der ein Zimmer sucht."}},faq={{q="Warum führt die Spur nach Goldhain?",a="Amtmann Daltry fand unter Stalvans erstem Eintrag im Register von Dunkelhain eine zweite Adresse. Obwohl sie teilweise durchgestrichen ist, weist sie zum Gasthaus \"Zur Höhle des Löwen\" in Goldhain.",al={"warum goldhain","warum nach goldhain gehen","stalvan in goldhain"}},{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry führt die Aufzeichnungen im Rathaus von Dunkelhain. Er pflegt die örtlichen Register und hilft dabei, alte Dokumente über frühere Bewohner aufzuspüren.",al={"daltry","wer ist daltry"}},{q="Mit wem spreche ich im Gasthaus \"Zur Höhle des Löwen\"?",a="Sprecht mit Gastwirt Farley, der das Gasthaus \"Zur Höhle des Löwen\" führt und die Reisenden und Gäste im Blick behält, die durch Goldhain kommen.",al={"mit wem sprechen","ansprechpartner im gasthaus \"zur höhle des löwen\"","gastwirt goldhain"}},{q="Warum wurde der Eintrag im Register durchgestrichen?",a="Der Registereintrag ist nur teilweise getilgt. Vielleicht hat jemand hastig versucht, Stalvans Weg zum Wald von Elwynn zu verbergen, als er den Dämmerwald verließ.",al={"durchgestrichene notiz","warum durchgestrichen"}},{q="Kommt es bei dieser Quest zu Kämpfen?",a="Nein. Ihr reist vom Rathaus in Dunkelhain zum Schankraum in Goldhain und erkundigt Euch nach Stalvan.",al={"gibt es kämpfe","muss ich gegen etwas kämpfen"}},{q="Was ist das Gasthaus \"Zur Höhle des Löwen\"?",a="Das Gasthaus \"Zur Höhle des Löwen\" ist Goldhains zentraler Treffpunkt im Wald von Elwynn. Reisende rasten dort auf den Wegen zwischen Sturmwind, Westfall und dem Dämmerwald.",al={"gasthaus \"zur höhle des löwen\"","gasthaus goldhain"}}},fx={f40d5969={q="Warum will Amtmann Daltry, dass Stalvan aufgespürt wird?",a="Als Stadtschreiber von Dunkelhain führt Daltry die Stadtakten und das Register. Nachdem Madame Eva Euch ursprünglich auf die Spur der geheimnisvollen Figur namens Stalvan Dunstmantel gebracht hatte, half Daltry bei der Suche, indem er seine Register durchforstete. Er entdeckte einen übersehenen, teilweise durchgestrichenen Eintrag unter der ersten Adresse und weist Euch an, dem neuen Hinweis nachzugehen, um die Geschichte des schwer fassbaren Mannes zusammenzusetzen.",al={"warum interessiert das daltry","daltrys motiv stalvan","warum stalvan aufspüren"}},["136b3a3d"]={q="Warum schickt Euch Amtmann Daltry nach Goldhain, anstatt selbst zu gehen?",a="Amtmann Daltry ist ein ziviler Beamter, der an das Rathaus von Dunkelhain gebunden ist und dafür verantwortlich ist, Aufzeichnungen zu führen und der lokalen Bevölkerung in einer von Schrecken belagerten Siedlung zu dienen. Eine Reise über den Fluss in den Wald von Elwynn, um Schankwirte zu befragen, liegt außerhalb seines Amtsbereichs und seiner Pflichten, weshalb ein rüstiger Abenteurer viel besser geeignet ist, entfernten Hinweisen nachzugehen.",al={"warum mich schicken","warum geht daltry nicht selbst","warum braucht daltry einen abenteurer"}}},fp="21,98,20.274.0,20.304.0,37.167.0,20.140.0,42.126.0,48.140.0,35.92.0,29.159.0"}
P.entries["quest:690"] = {n="Malins Gesuch",s="In Sturmwind bittet Erzmagier Malin um Hilfe bei der Bergung von Relikten aus dem gefallenen Stromgarde. Er schickt erfahrene Abenteurer der Allianz nach Norden zur Zuflucht im Arathihochland, wo eine Expedition nach den magischen Relikten sucht, die beim Fall von Stromgarde zurückblieben.",h="In Sturmwind bittet Erzmagier Malin um Hilfe bei der Bergung von Relikten aus dem gefallenen Stromgarde.",kw={"arathihochland","malin","die zuflucht","skuerto","sturmwind","stromgarde","der turm von arathor","trelane","magiersanktum"},ang={["class:Mage"]="Als Magier, der das Magiersanktum besucht, könnt Ihr Malin helfen, kostbare arkane Forschungen und Relikte zu bewahren, die mit den Magiern von Arathor verbunden sind.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, die Zuflucht zu stärken, den gefährdeten verbliebenen Stützpunkt der Allianz in Arathi.",["race:Human"]="Als Mensch könnt Ihr helfen, die Schätze von Stromgarde, der Wiege der menschlichen Zivilisation, zu bergen und das Erbe von Arathor zu bewahren."},sec={{t="Die verlorenen Besitztümer eines Meisters",b="Erzmagier Malin dient im Magiersanktum von Sturmwind und handelt im Auftrag seines früheren Mentors, Erzmagier Trelane. Als Stromgarde im Chaos versank, leistete Trelane am Turm von Arathor verzweifelten Widerstand. Als feindliche Truppen die Stadt einnahmen, musste er seinen Posten aufgeben und mächtige verzauberte Besitztümer zurücklassen. Malin fürchtet, dass diese Relikte in feindliche Hände fallen könnten. Er schickt fähige Söldner nach Norden, um seine Agenten vor Ort zu verstärken und Trelanes verlorene Besitztümer zurückzuholen."},{t="Der bedrängte Außenposten der Zuflucht",b="Die Zuflucht liegt auf dem Weg zu Trelanes Relikten, im zentralen Arathihochland. Der Außenposten ist ein schwer bedrängter Zufluchtsort für die Getreuen von Stromgarde, und Malins wichtigster Kontakt dort ist der Zwerg Skuerto. Gesetzlose des Syndikats, Witherbarktrolle und Boulderfistoger bedrängen den Außenposten von allen Seiten. Bei Eurer Ankunft sind Skuerto und die Garnison zu überlastet, um Euch ohne sofortige Hilfe herzlich willkommen zu heißen."}},faq={{q="Wer ist Erzmagier Malin?",a="Erzmagier Malin ist ein menschlicher Zauberer im Magiersanktum von Sturmwind. Einst war er ein Lehrling von Erzmagier Trelane aus Stromgarde, heute leitet er von Sturmwind aus die Bemühungen, die magischen Forschungen seines Mentors zurückzuholen.",al={"erzmagier malin","wer ist malin","malin sturmwind"}},{q="Warum braucht Malin Hilfe in Arathi?",a="Stromgarde wurde belagert, und Erzmagier Trelane musste aus dem Turm von Arathor fliehen. Malins Agenten versuchen, Trelanes zurückgelassene Relikte zu bergen, sind aber überfordert und brauchen Verstärkung.",al={"warum nach arathi","malins missionsziel","warum arathihochland"}},{q="Wo befindet sich Skuerto?",a="Skuerto ist ein zwergischer Späher, der in der Zuflucht stationiert ist, einem Lager der Allianz an der Haupthandelsstraße durch das zentrale Arathihochland.",al={"skuerto finden","skuertos standort","wo ist die zuflucht"}},{q="Was geschah mit dem Turm von Arathor?",a="Der Turm von Arathor war eine arkane Bastion in Stromgarde. Als das Königreich fiel, versuchte Erzmagier Trelane, ihn gegen Schurken des Syndikats und Boulderfistoger zu halten, doch die Verteidigung brach zusammen und er musste fliehen.",al={"fall des turms von arathor","was geschah mit stromgarde","trelanes turm"}},{q="Was geschieht, nachdem Ihr Euch bei Skuerto gemeldet habt?",a="Skuerto ist bei Eurer Ankunft überfordert und abweisend. Er schickt Euch zu seinen Gefährten in der Zuflucht, um mit der Bergung von Trelanes verstreuten Besitztümern zu beginnen.",al={"malins gesuch fortsetzung","nächste quest nach malin","skuertos nächste quest"}},{q="Wer ist Erzmagier Trelane?",a="Erzmagier Trelane ist ein bedeutender Magier aus Stromgarde und der Mentor von Erzmagier Malin. Vor dem Fall des Königreichs gehörte er zu den wichtigsten Verteidigern der Hauptstadt von Arathi.",al={"erzmagier trelane","wer ist trelane","trelane stromgarde"}}},fx={["5671e9ba"]={q="Warum benötigt Erzmagier Malin für diese Aufgabe einen Abenteurer?",a="Erzmagier Malin ist an seinen Posten im Magiersanktum von Sturmwind weit im Süden gebunden. Obwohl er bereits Agenten in Die Zuflucht im Arathihochland stationiert hat, haben diese berichtet, dass die Lage rund um die gefallene Stadt Stromgarde kritisch ist und Verstärkung erfordert. Ein reisender Abenteurer besitzt die Freiheit, schnell nach Norden zu reisen, und den Kampfgeist, sich in feindselige, umkämpfte Ruinen zu wagen, die offizielle Gesandte nicht so leicht erreichen können.",al={"warum einen abenteurer schicken","warum ich malin","warum geht malin nicht selbst"}}},fp="15,250,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="Das Gewicht in Gold wert",s="In der Zuflucht braucht Lehrling Kryten Reagenzien für Erzmagier Malin. Er bittet Euch, Stoßzähne, Medizinbeutel und das Messer eines Schattenjägers von den Witherbarktrollen im Südosten von Arathi zu beschaffen.",h="In der Zuflucht braucht Lehrling Kryten Reagenzien für Erzmagier Malin.",kw={"lehrling kryten","arathihochland","erzmagier malin","medizinbeutel","die zuflucht","schattenjägermesser","skuerto","witherbark","witherbarkstoßzahn"},sec={{t="Malins Reagenzien",b="Erzmagier Malin schickte Kryten und Skuerto nach Arathi, um Reagenzien zu beschaffen. Bis Ihr eintraft, war Kryten unsicher, wie er sie beschaffen sollte. Er benötigt zehn Witherbarkstoßzähne, vier Medizinbeutel und ein Schattenjägermesser. Die Witherbarktrolle leben im Südosten von Arathi."},{t="Was die Witherbark tragen",b="Laut Krytens Nachforschungen sollte jeder Witherbarktroll Stoßzähne besitzen. Die Hexendoktoren tragen Medizinbeutel bei sich. Das Messer gehört den mächtigsten Schattenjägern, die es nach Abschluss ihrer Reifeprüfung erhalten. Nur der Kampf wird zeigen, welcher von ihnen es bei sich trägt."}},faq={{q="Für wen arbeitet Lehrling Kryten?",a="Erzmagier Malin schickte Kryten und Skuerto nach Arathi, um Reagenzien für ihn zu beschaffen.",al={"wer hat kryten geschickt","krytens meister","warum ist kryten in arathi"}},{q="Wo befinden sich die Witherbarktrolle?",a="Im Südosten von Arathi, wo die Witherbark beheimatet sind.",al={"witherbark standort","wo sind die witherbark","witherbark lage"}},{q="Welche Trolle tragen die Medizinbeutel bei sich?",a="Laut Krytens Nachforschungen tragen die Hexendoktoren der Witherbark Medizinbeutel bei sich. Jeder Witherbarktroll sollte Stoßzähne besitzen.",al={"medizinbeutel herkunft","wer hat medizinbeutel","witherbark medizinbeutel"}},{q="Wie findet Ihr das Schattenjägermesser?",a="Die mächtigsten Schattenjäger der Witherbark tragen das Messer, das ihnen nach ihrer Reifeprüfung überreicht wird. Nur der Kampf wird offenbaren, welcher von ihnen es besitzt.",al={"schattenjägermesser fundort","wer lässt das schattenjägermesser fallen","messer der reifeprüfung"}}},fp="24,195,16.251.0,25.257.0,37.76.0,40.65.0,40.115.0,40.142.0"}
P.entries["quest:692"] = {n="Die verlorenen Fragmente",s="Hinter Theldurin streiten wütende Elementare um Fetzen der Rolle von Myzrael. Ihr sammelt die zerrissenen Stücke, während er fürchtet, was ihre Magie bewirken könnte.",h="Hinter Theldurin streiten wütende Elementare um Fetzen der Rolle von Myzrael.",kw={"ödland","zerknülltes rollenfragment","elementare","myzrael","rolle von myzrael","versengtes rollenfragment","theldurin der verirrte","zerrissenes rollenfragment"},sec={{t="Ein gefährliches Pergament",b="Theldurin der Verirrte fürchtet, die Rolle von Myzrael könnte Myzrael an die Oberfläche ziehen. Dann bedenkt er eine weitere Gefahr. Vielleicht ist sie bereits frei oder sammelt Kräfte für einen Angriff. In diesem Fall könnte die Rolle das sein, was Ihr braucht, um sie erneut zu binden."},{t="Von den Elementen zerrissen",b="Wütende Elementare nahmen die Rolle an sich und rissen sie auseinander. Nun streiten sie in den Hügeln hinter Theldurin um ihre Fetzen. Bringt drei Stücke zurück: ein zerrissenes, ein zerknülltes und ein versengtes. Theldurin hofft, sie wieder zusammenfügen zu können."}},faq={{q="Wer schickt Euch los, um die Rollenfragmente zu sammeln?",a="Theldurin der Verirrte bittet Euch, Stücke der zerstörten Rolle zurückzubringen.",al={"questgeber","wer startet die verlorenen fragmente","theldurin quest"}},{q="Was soll die Rolle von Myzrael bewirken?",a="Theldurin sagt, die Magie der Rolle könnte Myzrael an die Oberfläche ziehen. Falls sie bereits frei ist, glaubt er, dass Ihr die Rolle brauchen könntet, um sie erneut zu binden.",al={"was bewirkt die rolle","rolle von myzrael hintergrund","warum rollenfragmente suchen"}},{q="Wo sind die Rollenfragmente?",a="Wütende Elementare nahmen die Rolle an sich, rissen sie auseinander und streiten nun in den Hügeln hinter Theldurin um die Fetzen.",al={"wer hat die fragmente","wo sind die rollenstücke","rollenfragmente fundort"}},{q="Was kommt vor dieser Quest?",a="Sie folgt auf Eure früheren Begegnungen mit Theldurin dem Verirrten.",al={"vorherige quest","voraussetzung für die verlorenen fragmente"}}},fp="18,147,21.234.0,20.209.0,46.73.0,45.150.0,31.110.0,29.57.0"}
P.entries["quest:6921"] = {n="Inmitten der Ruinen",s="Am Außenposten von Zoram'gar schickt Je'neu Sancrea Champions der Horde unter die Wasser der Tiefschwarzen Grotte. Der Irdene Ring hofft, dass ein Tiefenkern zeigt, was der Schattenhammer mit den Elementen anstellt.",h="Am Außenposten von Zoram'gar schickt Je'neu Sancrea Champions der Horde unter die Wasser der Tiefschwarzen...",kw={"inmitten der ruinen","eschental","tiefschwarze grotte","der irdene ring","tiefenkern","fathomstein","je'neu sancrea","moonshrine ruins","schattenhammer","außenposten von zoram'gar"},ang={["class:Shaman"]="Wenn Ihr als Schamane den Tiefenkern bergt, helft Ihr dem Irdenen Ring, die Geister des Wassers und der Erde vor dem Zwang des Schattenhammers zu schützen.",["faction:Horde"]="Wenn Ihr als Mitglied der Horde Bedrohungen aus der Tiefschwarzen Grotte beseitigt, helft Ihr, den Außenposten von Zoram'gar und den Stützpunkt der Horde an der Küste des Eschentals zu schützen.",["race:Troll"]="Wenn Ihr als Troll Je'neu Sancrea beisteht, helft Ihr einem anderen Dunkelspeer, der die Horde mit den Hütern der Elemente des Irdenen Rings verbindet."},sec={{t="Eine Bedrohung in der Tiefe",b="Der Schattenhammer hat die Tiefschwarze Grotte eingenommen, einen uralten Nachtelfentempel, der einst Elune geweiht war. Seine Kultisten beherrschen nun die überfluteten Gänge. Am Außenposten von Zoram'gar an der Küste des Eschentals beobachtet der Dunkelspeerschamane Je'neu Sancrea, wie sich die Verderbnis ausbreitet. Er fürchtet, dass der Kult die örtlichen Elemente gegen das Land und seine Verteidiger wenden wird."},{t="Der Fathomstein",b="Je'neu Sancrea schickt Champions der Horde aus, um einen Tiefenkern aus dem Fathomstein unter den Wassern der Moonshrine Ruins zu bergen. Schamanen, die den Kern lesen können, finden darin eine detaillierte Aufzeichnung elementarer Strömungen und Störungen. Der Irdene Ring hofft, dass diese Aufzeichnung das Wirken des Schattenhammers offenbart und hilft, die Region vor einer elementaren Katastrophe zu bewahren."}},faq={{q="Wer vergibt die Quest Inmitten der Ruinen?",a="Je'neu Sancrea vergibt die Aufgabe. Der Dunkelspeertroll dient dem Irdenen Ring am Außenposten von Zoram'gar am Zoramstrand im westlichen Eschental.",al={"questgeber","wo die quest annehmen","wer startet inmitten der ruinen"}},{q="Was ist ein Tiefenkern?",a="Ein Tiefenkern ist ein Artefakt, das in einem unter Wasser liegenden Fathomstein in den Ruinen verwahrt wird. Schamanen können seine Aufzeichnungen über elementare Aktivitäten lesen, darunter auch, wie die örtlichen Elemente gezwungen und manipuliert werden.",al={"was ist der tiefenkern","zweck des fathomsteins","was bewirkt der kern"}},{q="Warum sorgt sich der Irdene Ring um die Tiefschwarze Grotte?",a="Der Irdene Ring strebt nach einem Gleichgewicht zwischen den Elementen. Der Schattenhammer hat die überfluteten Ruinen eingenommen und verdirbt und unterwirft die Elemente, wodurch er die Stabilität der Region gefährdet.",al={"beweggründe des irdenen rings","warum kümmert sich der irdene ring darum","kultisten der tiefschwarzen grotte"}},{q="Wo befindet sich der Fathomstein?",a="Der Fathomstein liegt unter den Wassern der Moonshrine Ruins in der Tiefschwarzen Grotte. Forscher müssen unter die Oberfläche tauchen, um seinen Kern zu bergen.",al={"wo ist der stein","fundort des tiefenkerns","moonshrine ruins tiefenkern"}},{q="Können Spieler der Allianz diese Quest annehmen?",a="Nein. Nur Abenteurer der Horde können diese Aufgabe übernehmen. Je'neu Sancrea ist am Außenposten der Horde in Zoram'gar stationiert und unterstützt die Präsenz der Horde im Eschental, während er dem Irdenen Ring dient.",al={"nur für die horde","allianzversion","kann die allianz inmitten der ruinen machen"}},{q="Welche Gruppe hält die Tiefschwarze Grotte besetzt?",a="Der Schattenhammer hält die Tiefschwarze Grotte besetzt. Der Kult dient finsteren Old God-Wesen und missbraucht die Elemente für katastrophale Zwecke.",al={"wer ist in der tiefschwarzen grotte","feinde in der tiefschwarzen grotte","schattenhammer tiefschwarze grotte"}}},fx={["139b4a2b"]={q="Warum will Je'neu Sancrea, dass der Tiefenkern geborgen wird?",a="Je'neu Sancrea befürchtet, dass die Kultisten des Schattenhammers, die die Tiefschwarze Grotte besetzt halten, die lokalen Elemente dazu zwingen werden, sich gegen die Region und die Horde zu wenden. Ohne den Tiefenkern ist Der Irdene Ring blind gegenüber den Ritualen und elementaren Störungen, die der Kult tief unter den Ruinen durchführt.",al={"jeneu sancreas motiv","warum tiefenkern holen","warum amongst the ruins"}}},fp="17,199,20.341.0,16.355.0,38.137.0,22.197.0,58.188.0,34.152.0,37.186.0,42.139.0"}
P.entries["quest:6922"] = {n="Baron Aquanis",s="Unter Eschental hinterlässt Baron Aquanis eine seltsame Kugel voller verderbter Flüssigkeit. Je'neu Sancrea vom Irdenen Ring verdächtigt die Kultisten des Schattenhammers in den überfluteten Ruinen und hofft, die Kugel werde enthüllen, was das Elementar verdorben hat.",h="Unter Eschental hinterlässt Baron Aquanis eine seltsame Kugel voller verderbter Flüssigkeit.",kw={"eschental","baron aquanis","tiefschwarze grotte","der irdene ring","verderbnis der elemente","je'neu sancrea","seltsame wasserkugel","schattenhammer","der zoramstrand"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass der Irdene Ring die Verderbnis von Elementargeistern als schweren Verstoß gegen die natürliche Ordnung betrachtet. Die Untersuchung von Baron Aquanis' verdorbenem Zustand ist entscheidend, um das Gleichgewicht der Elemente wiederherzustellen.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Je'neu Sancrea bei seiner Arbeit mit Spähern der Horde am Außenposten von Zoram'gar unterstützen. Sie suchen nach Streitern, die die verdorbenen Gewässer unter Eschentals Küste reinigen."},sec={{t="Ein verderbtes Herz",b="In der Tiefschwarzen Grotte hat finstere Zauberei Baron Aquanis zu einem Wassergeist verzerrt. Wird das Elementar vernichtet, bleibt eine Seltsame Wasserkugel zurück. Die unzerstörbare Kugel enthält faulige Flüssigkeit, die Aquanis' natürliche Essenz offenbar erhalten und verzerrt hat. Körperliche Gewalt kann ihr nichts anhaben. Ihre Energien beunruhigen jene, die auf das Gleichgewicht der Elemente eingestimmt sind."},{t="Studien des Irdenen Rings",b="Von einem Lager am Zoramstrand aus dient Je'neu Sancrea dem Irdenen Ring. Er erkennt in der Seltsamen Wasserkugel einen Beweis für unnatürliche Einmischung. Der Orden vermutet, dass dunkle Mächte Baron Aquanis verdorben haben, und Je'neu verdächtigt die Kultisten des Schattenhammers im versunkenen Tempel. Er untersucht die Kugel, um diesen Verdacht zu prüfen und zu erfahren, wie die Kultisten Azeroths Elementargeister unterwerfen und verzerren."}},faq={{q="Was ist Baron Aquanis?",a="In den unterirdischen Gewässern der Tiefschwarzen Grotte ist Baron Aquanis ein mächtiges Wasserelementar. Anwender dunkler Künste haben das Elementar im verfallenen Tempel verdorben und gebunden.",al={"wer ist aquanis","aquanis boss","baron aquanis geschichte"}},{q="Was ist die Seltsame Wasserkugel?",a="Die Seltsame Wasserkugel ist eine unzerstörbare Sphäre, die nach dem Sieg über Baron Aquanis zurückbleibt. Darin schwappt faulige Flüssigkeit voller verderbter Energie, die den verdorbenen Zustand des Elementars aufrechterhielt.",al={"wasserkugel","seltsame wasserkugel","aquanis questgegenstand"}},{q="Warum will Je'neu Sancrea die Kugel?",a="Je'neu Sancrea untersucht die Kugel, um herauszufinden, ob der Schattenhammer die Verderbnis verursacht hat, und die Riten zur Verzerrung von Elementargeistern aufzudecken. Als Mitglied des Irdenen Rings hält er in ganz Eschental nach Störungen im Gefüge der Elemente Ausschau.",al={"warum zu jeneu bringen","jeneu sancrea zweck"}},{q="Wer steckt hinter der Verderbnis von Baron Aquanis?",a="Die Kultisten des Schattenhammers tief in der Tiefschwarzen Grotte sind die Hauptverdächtigen hinter Baron Aquanis' Verderbnis. Ihre Anwesenheit im Tempel passt zu einem Muster aus Entweihung und dunkler Zwiesprache mit unnatürlichen Wesen.",al={"wer hat aquanis verdorben","aquanis schattenhammer","kultisten tiefschwarze grotte"}},{q="Wo befindet sich Je'neu Sancrea?",a="Je'neu Sancrea ist ein Schamane des Irdenen Rings, der am Zoramstrand an Eschentals nordwestlicher Küste lagert, nahe dem Eingang zu den Höhlen der Tiefschwarzen Grotte.",al={"wo ist jeneu","aquanis quest abgeben","wo wasserkugel abgeben"}},{q="Was folgt auf die Abgabe dieser Quest?",a="Die Übergabe der Kugel führt zu weiteren Untersuchungen der Notlage der Elemente in der Region. Abenteurer helfen dem Irdenen Ring weiterhin, der wachsenden Verderbnis entgegenzutreten.",al={"nächste quest","notlage der elemente"}}},fp="13,242,17.349.0,27.391.1,22.172.0,32.194.0,39.240.0,46.219.0,32.157.0,39.157.0"}
P.entries["quest:693"] = {n="Zauberstab gegen Faust",s="In der Zuflucht hat Skuerto herausgefunden, wo Trelanes erster Gegenstand gelandet ist. Kor'gresh hat Trelanes Zauberstab der Herbeirufung in der Halle der Felsfäuste, und Skuerto will ihn zurück.",h="In der Zuflucht hat Skuerto herausgefunden, wo Trelanes erster Gegenstand gelandet ist.",kw={"arathihochland","halle der felsfäuste","korgresh","die zuflucht","skuerto","stromgarde","thandol-übergang","trelane","zauberstab der herbeirufung","zauberstab gegen faust"},sec={{t="Der Oger und der Zauberstab",b="Nach Eurer Arbeit für Lehrling Kryten hat Skuerto Trelanes ersten Gegenstand bei Kor'gresh aufgespürt. Der Oger hat den Zauberstab in der Halle der Felsfäuste und hält seine Sippe mit Eisstößen in Schach. Skuerto fürchtet, dass Kor'gresh kurz davor steht, all seine Kräfte zu entdecken. Die Halle der Felsfäuste liegt südlich der Zuflucht und dann östlich des Thandol-Übergangs."},{t="Skuertos Liste",b="Wenn Ihr zurückkehrt, zählt Skuerto den Zauberstab als einen gefundenen Gegenstand. Drei weitere stehen noch auf seiner Liste, und alle drei sind in Stromgarde."}},faq={{q="Wer vergibt die Quest Zauberstab gegen Faust?",a="In der Zuflucht im Arathihochland bittet Skuerto Euch, den Zauberstab zurückzuholen.",al={"zauberstab gegen faust questgeber","wer startet zauberstab gegen faust","wo gibt es zauberstab gegen faust"}},{q="Wo befindet sich Kor'gresh?",a="Kor'gresh ist in der Halle der Felsfäuste, südlich der Zuflucht und dann östlich des Thandol-Übergangs.",al={"wo ist korgresh","korgresh standort","korgresh finden"}},{q="Welcher Gegenstand muss zurückgeholt werden?",a="Trelanes Zauberstab der Herbeirufung ist der erste von Trelanes Gegenständen, der zurückgeholt werden muss. Kor'gresh hat ihn benutzt, um Eisstöße auf seine Sippe zu schleudern.",al={"welchen gegenstand hat kor'gresh","welcher zauberstab","trelanes zauberstab"}},{q="Welche Voraussetzungen gibt es für diese Quest?",a="Ihr erhaltet diese Aufgabe nach Worth Its Weight in Gold, der Arbeit, die Ihr für Lehrling Kryten erledigt habt.",al={"zauberstab gegen faust voraussetzungen","voraussetzungen für zauberstab gegen faust","vorquest zu zauberstab gegen faust"}}},fp="14,161,21.321.0,14.123.1,35.79.0,27.87.0,32.134.0,45.91.0"}
P.entries["quest:694"] = {n="Trelanes Verteidigung",s="Oger umringen nun den Turm von Arathor, und Skuerto braucht funktionierende Verteidigungsanlagen. Ein Azurachat von den Schamanen der Boulderfist kann zum Schlüssel werden, nachdem Lehrling Kryten in der Zuflucht ihn verzaubert hat.",h="Oger umringen nun den Turm von Arathor, und Skuerto braucht funktionierende Verteidigungsanlagen.",kw={"lehrling kryten","azurachat","schamanen der boulderfist","die zuflucht","skuerto","stromgarde","der turm von arathor","trelanes verteidigung"},sec={{t="Die Verteidigungsanlagen des Turms",b="In Stromgarde umringen Oger den Turm von Arathor. Skuerto sagt, Ihr müsst seine Verteidigungsanlagen aktivieren, um eine Chance gegen sie zu haben. Erst dann könnt Ihr die Gegenstände lebend erreichen."},{t="Ein Edelstein als Schlüssel",b="Die Schamanen der Boulderfist haben bestimmte Edelsteine aus dem Turm mitgenommen und Gefallen an ihnen gefunden. Skuerto sagt, sie werden die Edelsteine nicht lange behalten. Bringt einen Azurachat zu Lehrling Kryten in der Zuflucht. Kryten kennt den Zauber, der ihn so verzaubert, dass er als Schlüssel dient."}},faq={{q="Warum wird ein Azurachat benötigt?",a="Skuerto will die Verteidigungsanlagen des Turms aktivieren, damit Ihr Euch den Ogern rund um den Turm von Arathor stellen und die Gegenstände lebend erreichen könnt. Verzaubert wird der Edelstein als Schlüssel dienen.",al={"warum azurachat","trelanes verteidigung zweck","warum den edelstein holen"}},{q="Woher stammen die Azurachate?",a="Die Schamanen der Boulderfist haben die Azurachate aus dem Turm von Arathor mitgenommen und Gefallen an ihnen gefunden.",al={"wer nahm die achate","woher stammen die edelsteine","herkunft der achate"}},{q="Wer kann den Edelstein verzaubern?",a="Lehrling Kryten in der Zuflucht kennt den Zauber, um den Edelstein so zu verzaubern, dass er als Schlüssel dient.",al={"wer verzaubert den achat","krytens rolle","wer macht ihn zum schlüssel"}}},fp="18,190,20.166.0,15.257.0,29.161.0,37.99.0,24.91.0"}
P.entries["quest:695"] = {n="Des Lehrlings Verzauberung",s="Im Lager verzaubert Lehrling Kryten den Achat, den Ihr vom Boulderfist-Schamanen gebracht habt. Er kann die Verteidigung des Turms erwecken, und Kryten schickt Euch vor Eurem Aufbruch zu Skuerto.",h="Im Lager verzaubert Lehrling Kryten den Achat, den Ihr vom Boulderfist-Schamanen gebracht habt.",kw={"lehrling kryten","arathihochland","verzauberter achat","skuerto","turm","trelane"},sec={{t="Ein Schlüssel zum Turm",b="Lehrling Kryten überreicht Euch den verzauberten Edelstein und erklärt seine Macht. Berührt damit einen Sockel am Fuße des Turms, und seine Verteidigung erwacht. Verwendet den Edelstein, wenn Ihr bereit seid, hineinzugehen und nach Trelanes restlichen Gegenständen zu suchen. Kryten wartet im Lager auf Euch. Sprecht vor Eurem Aufbruch mit Skuerto, der alle weiteren Fragen beantworten kann."}},faq={{q="Wozu dient der verzauberte Achat?",a="Berührt mit dem verzauberten Achat einen Sockel am Fuße des Turms, und er erweckt die Verteidigung des Turms. Verwendet ihn, wenn Ihr bereit seid, hineinzugehen und nach Trelanes restlichen Gegenständen zu suchen.",al={"wozu brauche ich den achat","verzauberten achat verwenden","was bewirkt der edelstein"}},{q="Mit wem müsst Ihr vor dem Aufbruch aus dem Lager sprechen?",a="Sprecht mit Skuerto, bevor Ihr das Lager verlasst. Kryten sagt, dass Skuerto alle weiteren Fragen beantworten kann.",al={"mit wem sprechen","wohin als nächstes","wer ist skuerto"}},{q="Wo wird Kryten sein?",a="Kryten wartet im Lager auf Eure Rückkehr.",al={"wo ist kryten","kryten wartet"}}},fp="27,174,19.335.0,43.174.0,47.95.0,21.45.0"}
P.entries["quest:696"] = {n="Angriff auf den Turm",s="In der Zuflucht schickt Euch Skuerto in den von Ogern besetzten Turm, um drei mit Trelane verbundene Gegenstände zu suchen. Das Phylakterium, die Kugel und der Ember Agate sollten in Truhen im Inneren liegen, und Skuerto sagt, Malin werde sich freuen, wenn Ihr sie zurückbringt.",h="In der Zuflucht schickt Euch Skuerto in den von Ogern besetzten Turm, um drei mit Trelane verbundene...",kw={"arathihochland","angriff auf den turm","malin","oger","die zuflucht","skuerto","trelane","trelanes ember agate","trelanes kugel","trelanes phylakterium"},sec={{t="In den Turm",b="Nachdem Kryten den Edelstein verzaubert hat, schickt Euch Skuerto los, um Trelanes Phylakterium, Kugel und Ember Agate zu finden. Die drei Gegenstände sollten in Truhen im Inneren des Turms liegen, die Ihr öffnen könnt. Doch die Oger sind gefährlich. Die Verteidigung des Turms wird sich nicht um sie kümmern, und die Oger werden Euch Schmerzen zufügen, wenn sie Euch beim Stehlen erwischen."},{t="Skuertos Urteil",b="Wenn Ihr mit den drei Gegenständen zurückkehrt, sagt Skuerto, dass Malin sich keine würdigere Person hätte wünschen können, um ihnen hier zu helfen. Malin wird hocherfreut sein zu erfahren, dass ihr Vorhaben so vollkommen geglückt ist."}},faq={{q="Wer erteilt diesen Auftrag?",a="Skuerto schickt Euch von der Zuflucht im Arathihochland aus los, nachdem Kryten den Edelstein verzaubert hat.",al={"wer vergibt angriff auf den turm","questgeber angriff auf den turm","wo gibt es angriff auf den turm"}},{q="Welche Gegenstände sollt Ihr holen?",a="Ihr sollt Trelanes Phylakterium, Kugel und Ember Agate holen. Jeder Gegenstand sollte in einer Truhe im Inneren des Turms liegen.",al={"angriff auf den turm gegenstände","welche relikte holen","trelanes gegenstände"}},{q="Was werden die Oger tun?",a="Die Verteidigung des Turms wird sich nicht um die Oger kümmern. Wenn sie Euch beim Stehlen erwischen, werden sie Euch Schmerzen zufügen.",al={"sind die oger gefährlich","oger im turm"}},{q="Was geht diesem Auftrag voraus?",a="Der Auftrag folgt auf An Apprentice's Enchantment, bei dem Kryten den Edelstein verzaubert und Euch zu Skuerto schickt.",al={"angriff auf den turm voraussetzung","welche quest kommt zuerst"}}},fp="19,228,14.307.0,17.194.1,22.91.0,36.111.0,23.98.0,23.95.0"}
P.entries["quest:6962"] = {n="Leckereien für Altvater Winter",s="Am Stand von Kokelwälder in Orgrimmar ist der Darsteller von Altvater Winter es leid, Festtagswünsche anzuhören. Er bittet Euch um Lebkuchen und Milch.",h="Am Stand von Kokelwälder in Orgrimmar ist der Darsteller von Altvater Winter es leid, Festtagswünsche...",kw={"lebkuchen","altvater winter","festtagsgewürze","eiskalte milch","orgrimmar","kokelwälder","leckereien für altvater winter","winterhauch"},ang={["faction:Horde"]="In Orgrimmar bringen die Goblinhändler von Kokelwälder das Fest und einen Moment häuslicher Freude in die Kriegerstadt.",["profession:Cooking"]="Als Kochlehrling könnt Ihr Euch im einfachen Backen üben, indem Ihr Eier von Wildvögeln und saisonale Gewürze in festliche Lebkuchen verwandelt."},sec={{t="Ein müder Schirmherr des Winters",b="Der Altvater Winter, der Besucher im Tal der Stärke begrüßt, arbeitet für Kokelwälder. Stundenlang hört er Bürger von festlichen Leckereien sprechen, und das macht ihn hungrig. Also bittet er vorbeiziehende Reisende um warmes Gebäck und ein kaltes Getränk."},{t="Festtagsstimmung aus der Küche",b="Aus Festtagsgewürzen von den Händlern von Kokelwälder und kleinen Eiern von wilden Vögeln entstehen die Lebkuchen. Bringt sie zusammen mit Eiskalter Milch aus einer örtlichen Taverne. Dann bieten die Festorganisatoren Festtagsfreude und ein kleines Zeichen der Dankbarkeit."}},faq={{q="Wer ist Altvater Winter in Orgrimmar?",a="In Orgrimmar ist Altvater Winter ein Schauspieler, den Kokelwälder engagiert hat, um die legendäre Gestalt während des Winterhauchfests darzustellen. Nahe dem festlichen Verkaufsstand im Tal der Stärke begrüßt er Bürger der Horde und hört sich ihre Festtagswünsche an.",al={"wer ist altvater winter","orgrimmar altvater winter","ist er der echte altvater winter"}},{q="Um welche Leckereien bittet Altvater Winter?",a="Er bittet Euch um fünf Lebkuchen und eine Portion Eiskalte Milch, damit er einen langen Tag lang Festtagsbesucher begrüßen kann.",al={"was will er","erbetene leckereien","welche kekse braucht er"}},{q="Wie werden Lebkuchen gebacken?",a="Die Händler von Kokelwälder rund um den Festtagsstand verkaufen das Rezept und Festtagsgewürze. Sammelt kleine Eier von wilden Vögeln, vermischt sie mit den Gewürzen und backt die Lebkuchen über einem Kochfeuer.",al={"wie bekommt man lebkuchen","lebkuchenrezept","kekszutaten"}},{q="Wo gibt es Eiskalte Milch?",a="Händler für Speisen und Getränke, Gastwirte und Schankwirte verkaufen Eiskalte Milch in ganz Orgrimmar und anderen großen Siedlungen.",al={"wo gibt es eiskalte milch","milch kaufen","milchhändler"}},{q="Warum bittet Altvater Winter selbst um Essen?",a="Den ganzen Tag hört der Darsteller von Altvater Winter Kinder und Bürger von Essen, Geschenken und Feierlichkeiten sprechen, und das macht ihn hungrig. Da er seinen Posten im Tal der Stärke kaum verlassen kann, bittet er vorbeiziehende Reisende um einen kleinen Imbiss.",al={"warum will er leckereien","ist altvater winter hungrig"}},{q="Gibt es zu dieser Quest ein Gegenstück für die Allianz?",a="Ja. In Eisenschmiede bittet Altvater Winter während des Festes die Streiter der Allianz ebenfalls um Lebkuchen und kalte Milch.",al={"allianzversion","eisenschmiede leckereien"}}},fx={["87543d9b"]={q="Wofür sind die Lebkuchen und die Eiskalte Milch?",a="Smokywood Pastures lässt Altvater Winter den ganzen Tag draußen sitzen, um die Festbesucher zu begrüßen, und die Feiertagsstimmung macht hungrig. Die frischen Lebkuchen und der erfrischende Krug mit Eiskalter Milch sind einfach ein bescheidener, tröstender Snack, um seine Stimmung hochzuhalten, während er sich in Orgrimmar die Feiertagswünsche der Besucher anhört.",al={"warum milch und kekse","verwendung von lebkuchen","eiskalte milch winterhauchfest"}},["1b7dc40f"]={q="Warum bittet Altvater Winter Euch, anstatt die Leckereien selbst zu holen?",a="Altvater Winter sitzt fest auf seinem festlichen Sitz im Tal der Stärke und unterhält Gäste und verbreitet während des Winterhauchfests Feiertagsfreude. Seinen Posten zu verlassen, um einkaufen zu gehen oder Leckereien zu backen, würde die Besucher enttäuschen und die Feierlichkeiten stören, also verlässt er sich darauf, dass vorbeikommende Abenteurer die Besorgungen erledigen.",al={"warum braucht mich altvater winter","warum kann altvater winter keine milch holen","warum abenteurer nach leckereien fragen"}}},fp="30,159,24.234.0,23.236.0,39.254.0,44.137.0,36.196.0,33.117.0,50.238.0,45.141.0"}
P.entries["quest:697"] = {n="Malins Gesuch",s="In Sturmwind bringt Skuertos Brief Erzmagier Malin Neuigkeiten aus Arathi. Ihr werdet mit der Nachricht ins Mage Quarter geschickt, dass Kryten und Skuerto bald zu Hause sein werden.",h="In Sturmwind bringt Skuertos Brief Erzmagier Malin Neuigkeiten aus Arathi.",kw={"arathihochland","erzmagier malin","kryten","mage quarter","malin's request","versiegelter brief","skuerto","sturmwind"},sec={{t="Ein Brief für den Erzmagier",b="Nach Eurer Arbeit in Arathi gibt Euch Skuerto einen versiegelten Brief für Erzmagier Malin im Mage Quarter von Sturmwind. Darin steht, dass Kryten und Skuerto bald zu Hause sein werden. Skuerto vertraut darauf, dass Malin Euch für Eure Hilfe gut entlohnen wird, und wünscht Euch eine sichere Reise."},{t="Malin liest den Brief",b="Erzmagier Malin öffnet Skuertos Brief, und seine Augen weiten sich. Hocherfreut sagt er, Trelane werde sich freuen. Malin vermutet, dass Kryten und Skuerto auf ihrem Heimweg nach Sturmwind seine Begeisterung teilen."}},faq={{q="Wer schickt Euch mit dem Brief los?",a="Skuerto schickt Euch mit einem Brief für Malin los. Darin steht, dass Kryten und Skuerto bald zu Hause sein werden.",al={"wer gibt den brief","wer startet malins gesuch","questgeber malins gesuch"}},{q="Wo befindet sich Erzmagier Malin?",a="Erzmagier Malin befindet sich im Mage Quarter von Sturmwind.",al={"wo ist erzmagier malin","erzmagier malin standort","wo abgeben"}},{q="Wer ist Kryten?",a="Kryten ist Skuertos Gefährte im Arathihochland. Skuerto sagt, dass sie bald zu Hause sein werden.",al={"wer ist kryten","kryten arathi"}},{q="Was kommt vor diesem Schritt?",a="Dieser Schritt folgt auf Attack on the Tower, die Arbeit, um die Skuerto Euch am Turm in Arathi gebeten hat.",al={"vorherige quest","voraussetzung","was führt hierzu"}}},fp="15,160,25.243.0,22.193.1,30.88.0,32.46.0,14.91.0,28.90.0"}
P.entries["quest:698"] = {n="Mangelnde Reserven",s="Dar braucht mehr Sägezahnfleisch für den Außenposten am östlichen Strand. Zwischen Wachschichten und dem Kochen für die Soldaten bleibt Tok'Kar wenig Zeit, also bittet Dar Euch, welches zu bringen.",h="Dar braucht mehr Sägezahnfleisch für den Außenposten am östlichen Strand.",kw={"dar","flanke","fleisch","außenposten","sägezahn","sümpfe des elends","tok'kar"},sec={{t="Vorräte für die Küste",b="Dar sammelt Vorräte für den Außenposten am östlichen Strand. Tok'Kar bewacht den Posten und kocht für dessen Soldaten, sodass wenig Zeit für andere Arbeit bleibt. Die Soldaten essen gern Sägezahnfleisch, wenn sie welches bekommen können. Dar hatte keine Zeit, eine weitere Lieferung zu schicken."},{t="Die Wahl des Fleisches",b="Ältere Sägezähne schmecken besser, sagt Dar, also lasst die jungen in Ruhe. Sie brauchen ein oder zwei Jahre, um ihre volle Größe zu erreichen. Bringt acht unzubereitete Sägezahnflanken zu Tok'Kar in den Sümpfen des Elends."}},faq={{q="Wer bittet um das Sägezahnfleisch?",a="Dar, der den Außenposten am östlichen Strand mit Vorräten versorgt.",al={"wer vergibt mangelnde reserven","wer startet mangelnde reserven","dar sümpfe des elends"}},{q="Wo ist Tok'Kar stationiert?",a="Tok'Kar ist am Außenposten am östlichen Strand in den Sümpfen des Elends stationiert. Bringt das Fleisch dorthin.",al={"wo ist tok'kar","tokkar standort","tok'kar außenposten"}},{q="Warum müssen andere Tok'Kar Fleisch bringen?",a="Wachschichten und das Kochen für die Soldaten lassen Tok'Kar tagsüber wenig Zeit.",al={"warum braucht tok'kar fleisch","warum schickt dar nahrung"}},{q="Welche Sägezähne sollen gejagt werden?",a="Jagt ältere Sägezähne. Die jungen schmecken weniger gut und brauchen ein oder zwei Jahre, um ihre volle Größe zu erreichen.",al={"welche sägezähne","welche sägezähne lassen fleisch fallen","sägezahnflanke herkunft"}},{q="Wie viele Flanken werden benötigt?",a="Bringt Tok'Kar acht unzubereitete Sägezahnflanken.",al={"wie viele flanken","unzubereitete sägezahnflanke anzahl"}},{q="Was folgt als Nächstes in der Questreihe?",a="Ein zweiter Schritt unter demselben Namen folgt.",al={"nächste quest mangelnde reserven","mangelnde reserven folgequest"}}},fp="15,165,22.253.0,17.189.0,36.68.0,27.104.0,43.79.0,33.94.0,27.47.0,29.42.0"}
P.entries["quest:6981"] = {n="Der leuchtende Splitter",s="Tief in den Höhlen des Wehklagens findet Ihr einen grünen Splitter, dessen rauchiges Inneres Unbehagen weckt. Sein Geheimnis führt Euch nach Ratschet und weiter.",h="Tief in den Höhlen des Wehklagens findet Ihr einen grünen Splitter, dessen rauchiges Inneres Unbehagen weckt.",kw={"brachland","druids of the fang","emerald nightmare","falla weisenwind","leuchtender splitter","ratschet","stotterspritter","die höhlen des wehklagens"},ang={["class:Druid"]="Als Druide könnt Ihr den smaragdgrünen Schimmer und das rauchige Herz des Splitters als düstere Zeichen deuten, dass der Emerald Nightmare durch Eure gefallenen Mitbrüder in den Höhlen des Wehklagens die wache Welt erreicht.",["faction:Alliance"]="Als Entdecker der Allianz fern der Heimat in Kalimdor könnt Ihr die Gefahr erkennen, die von einer dunklen Macht ausgeht, die unter dem Brachland die Natur verdirbt.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr helfen, das Geheimnis des Splitters zu lüften und die Wegkreuzungen und Handelsrouten des Brachlands vor Bedrohungen zu schützen, die in den unterirdischen Quellen heranwachsen.",["race:Tauren"]="Als Tauren wisst Ihr, dass das Gleichgewicht des Brachlands für die Shu'halo von Bedeutung ist. Dieses unnatürliche Relikt zu Falla Weisenwind zu bringen, kann helfen, die Verderbnis aufzudecken, die das Land Eurer Ahnen vergiftet."},sec={{t="Ein beunruhigender Fund",b="Ihr tragt einen grünen Kristall aus den Tiefen der Höhlen des Wehklagens bei Euch. Unter seiner leuchtenden, festen Oberfläche scheinen schattenhafte Schwaden zu wallen. Wer ihn berührt, verspürt Unbehagen, und seine seltsame Präsenz deutet auf die Verderbnis um die schlafenden Druiden und ihren von Albträumen heimgesuchten Zufluchtsort hin."},{t="Antworten in Ratschet suchen",b="In Ratschet bleibt die Herkunft des Splitters unklar. Ingenieur Stotterspritter untersucht ihn, doch Goblinmaschinen und gewöhnliche Geologie können seine Natur nicht erklären. Er verweist Euch auf die felsigen Bergrücken über den Höhlen, wo Falla Weisenwind, eine Tauren-Mystikerin, über die geplagten Geister des Brachlands wacht."}},faq={{q="Was ist der Leuchtende Splitter?",a="Ihr habt den Leuchtenden Splitter tief in den Höhlen des Wehklagens gefunden. Schwache, rauchige Schemen wirbeln unter seiner glasigen Oberfläche und beunruhigen jene, die ihn untersuchen.",al={"leuchtender splitter gegenstand","was ist dieser grüne edelstein","splitter aus den höhlen des wehklagens"}},{q="Wer kann den Splitter in Ratschet untersuchen?",a="Ingenieur Stotterspritter in der Nähe des Flugmeisters von Ratschet kann den Splitter untersuchen. Seine seltsame Energie veranlasst ihn, Euch an jemanden mit spirituellem Wissen zu verweisen.",al={"wer in ratschet untersucht den splitter","ratschet npc für splitter","stotterspritter splitter"}},{q="Wo befindet sich Falla Weisenwind?",a="Falla Weisenwind hat ihr Lager auf den Berggipfeln direkt über dem Eingang der Höhlen des Wehklagens im zentralen Brachland.",al={"falla weisenwind standort","wo ist falla","berg über den höhlen des wehklagens"}},{q="Hat Stotterspritter eine Questmarkierung über dem Kopf?",a="Nein. Stotterspritter hat kein aktives Symbol über dem Kopf. Sprecht mit ihm und wählt den Dialog über den seltsamen leuchtenden Splitter, um fortzufahren.",al={"stotterspritter kein fragezeichen","abgabe bei stotterspritter nicht möglich","stotterspritter fehlerhaft"}},{q="Warum sieht der Splitter aus, als enthielte er Rauch?",a="Der rauchartige Wirbel spiegelt die Verderbnis wider, die sich in den Höhlen des Wehklagens ausbreitet. Er ist mit dem Emerald Nightmare verbunden, der in die Gedanken der schlafenden Druids of the Fang eindringt.",al={"warum raucht der splitter","grüner rauch im edelstein","verderbnis im splitter"}},{q="Wer kann die Questreihe nach Falla Weisenwind abschließen?",a="Abenteurer der Horde und der Allianz können der Geschichte gleichermaßen folgen. Falla Weisenwinds Erkenntnisse führen zu In Nightmares, wo Helden bei ihren eigenen Anführern und Ältesten Rat suchen.",al={"ist diese quest nur für die horde","allianz leuchtender splitter","wer erhält in nightmares"}}},fx={["8f9c92be"]={q="Warum müsst Ihr den Leuchtenden Splitter untersuchen?",a="Der leuchtende Splitter ist zutiefst beunruhigend. Fest und doch gefüllt mit wirbelnden, rauchig-grünen Tiefen strahlt er eine unnatürliche Präsenz aus, die nach einer Erklärung verlangt. Nachdem Ihr ihn aus dem Herzen der unruhigen Höhlen des Wehklagens geborgen habt, müsst Ihr verstehen, welche Verderbnis er in sich trägt und welche Bedrohung er für das Brachland darstellen könnte.",al={"warum leuchtenden splitter untersuchen","motiv leuchtender splitter","warum splitter nach ratschet bringen"}}},fp="17,128,22.271.0,26.297.1,26.145.0,37.156.0,32.119.0,52.135.0,47.174.0,54.168.1"}
P.entries["quest:6984"] = {n="Ein Dankeschön von Kokelwälder!",s="In Orgrimmar schickt Kaymard Kupferzwick Euch los, um Dank für die zurückgeholten gestohlenen Festtagsleckereien zu empfangen. Altvater Winter wartet darauf, jene zu ehren, die die Vorräte von Smokywood Pastures zurückgebracht haben.",h="In Orgrimmar schickt Kaymard Kupferzwick Euch los, um Dank für die zurückgeholten gestohlenen...",kw={"winterhauchfest","altvater winter","greench","kaymard kupferzwick","orgrimmar","smokywood pastures","tal der stärke","winter veil"},ang={["faction:Horde"]="In Orgrimmar verbindet die Feier der Horde zu Winter Veil schamanische Ehrfurcht vor dem Jahreszeitenwechsel mit dem Handel der Goblins.",["profession:Cooking"]="Als Koch könnt Ihr Euch bei Smokywood Pastures mit saisonalen Vorräten, exotischen Rezepten und festlichen Zutaten versorgen, die jedes Jahr sehnsüchtig erwartet werden."},sec={{t="Ein Fest fürs Geschäft",b="In Orgrimmar verkauft Smokywood Pastures Leckereien, Rezepte und festliche Freude zum Winterhauchfest. Eine Lieferung wurde in den verschneiten Hügeln des Alteracgebirges gestohlen, und das Geschäft geriet ins Stocken. Nun sind die Leckereien zurückgeholt und der Abominable Greench ist erledigt. Kaymard Kupferzwick schickt Euch los, um den Dank des Unternehmens zu empfangen."},{t="Audienz bei Altvater Winter",b="Altvater Winter wartet neben dem Festtagsbaum im Tal der Stärke. Die Goblins haben dafür gesorgt, dass er jene ehrt, die die Festtagsvorräte gerettet haben. Er gewährt ihnen einen winterlichen Segen und ein Kokelwälder Spezialgeschenk."}},faq={{q="Wer schickt mich zu Altvater Winter?",a="Nachdem Ihr die gestohlenen Festtagsleckereien zurückgeholt habt, schickt Kaymard Kupferzwick Euch zu Altvater Winter. Er vertritt Smokywood Pastures im Tal der Stärke in Orgrimmar.",al={"wer startet diese quest","questgeber","kaymards rolle"}},{q="Womit habe ich mir den Dank von Smokywood Pastures verdient?",a="Ihr habt den Abominable Greench im Alteracgebirge aufgespürt und die gestohlenen Festtagsleckereien zurückgeholt. Damit habt Ihr die Vorräte von Smokywood Pastures für das Winterhauchfest gerettet.",al={"grund für den dank","welche leckereien wurden gestohlen","greench hintergrund"}},{q="Wo in Orgrimmar befindet sich Altvater Winter?",a="Altvater Winter wartet unter dem geschmückten Baum zu Winter Veil im Tal der Stärke, neben den Verkaufsständen von Smokywood Pastures.",al={"altvater winter standort","wo ist der weihnachtsmann in org","winter veil baum org"}},{q="Wer ist Altvater Winter?",a="Altvater Winter ist ein elementarer oder sagenhafter Bote des Jahreszeitenwechsels, der das Land mit Winterschnee bedecken soll. Während des Winterhauchfests tragen Sterbliche seine roten Gewänder, um Wohlwollen zu verbreiten und Kindern und Abenteurern Leckereien zu schenken.",al={"wer ist altvater winter","ist altvater winter echt","winter veil geschichte"}},{q="Was ist Smokywood Pastures?",a="Smokywood Pastures ist ein von Goblins geführtes Unternehmen für Kochkunst und Landwirtschaft. Es versorgt die Horde und die Allianz während des Winterhauchfests mit festlichen Speisen, saisonalen Zutaten und Dekorationen.",al={"smokywood pastures geschichte","wer ist smokywood pastures","goblin festtagshändler"}},{q="Erhalte ich noch etwas, nachdem ich mit ihm gesprochen habe?",a="Ja. Altvater Winter überreicht Euch im Namen des Unternehmens ein Kokelwälder Spezialgeschenk. Eure Bemühungen bringen Euch außerdem Ansehen beim Steamwheedle Cartel ein.",al={"questbelohnung","verkleidungsset","geschenk per post"}}},fx={["553cdbb2"]={q="Warum schickt Euch Kaymard Kupferzwick zu Altvater Winter?",a="Kaymard Kupferzwick und Smokywood Pastures möchten Euch für die Bergung ihrer gestohlenen Leckereien belohnen. Indem sie Euch an Altvater Winter verweisen, damit Ihr persönlich ein besonderes Geschenk zum Winterhauchfest erhaltet, zeigen die Goblins ihre Dankbarkeit und wahren gleichzeitig das festliche kommerzielle Wohlwollen der Saison.",al={"warum dankt mir kaymard","kaymard kupferzwicks motiv","warum zu altvater winter schicken"}}},fp="32,194,19.327.0,33.232.0,47.166.0,52.175.0,50.136.0,27.240.0,27.200.0,51.155.0"}
P.entries["quest:699"] = {n="Mangelnde Reserven",s="An der Küste halten Tok'Kar und seine Soldaten nach Murlocs Ausschau, die Steinard bedrohen. Wird die Streitmacht zu groß, senden sie eine Warnung; vorerst bittet Tok'Kar Euch, sechs Klauen von sawtooth snappern zu bringen.",h="An der Küste halten Tok'Kar und seine Soldaten nach Murlocs Ausschau, die Steinard bedrohen.",kw={"klauen","murlocs","sawtooth snapper","steinard","sümpfe des elends","tok'kar"},sec={{t="Waffen für die Küste",b="Tok'Kar und die Soldaten schützen Steinard vor Murlocs entlang der Küste. Ist die Streitmacht zu groß, um sich ihr zu stellen, warnen sie die Stadt. Tok'Kar hat wenig Zeit zum Ausruhen, also bittet er Euch um Hilfe. Richtig hergerichtet ergeben die Klauen von sawtooth snappern ausgezeichnete Waffen. Bringt ihm sechs, und er bietet Euch im Gegenzug eine der Waffen des Außenpostens an, dankbar für das Fleisch und die Gesellschaft."}},faq={{q="Wer bittet um die Klauen?",a="Tok'Kar, der zum Schutz von Steinard an der Küste stationiert ist, bittet Euch um die Klauen.",al={"wer vergibt mangelnde reserven","questgeber","tokkar"}},{q="Warum braucht Tok'Kar Klauen von sawtooth snappern?",a="Richtig hergerichtete Klauen von sawtooth snappern ergeben ausgezeichnete Waffen, und Tok'Kar möchte sechs davon.",al={"warum klauen","sawtooth snapper verwendung","klauen als waffen"}},{q="Nach welcher Bedrohung hält der Küstenposten Ausschau?",a="Die Soldaten halten entlang der Küste nach Murlocs Ausschau. Sie schützen Steinard oder warnen die Stadt, wenn die Streitmacht zu groß ist.",al={"gefahren an der küste","murlocangriff auf steinard","wonach hält tokkar ausschau"}},{q="Wie geht es danach weiter?",a="Danach folgt Threat From the Sea.",al={"what comes next","nächste quest","nach mangelnde reserven"}}},fp="15,194,21.347.0,23.78.0,45.82.0,45.112.0,26.28.0"}
P.entries["quest:7"] = {n="Säuberung im Koboldlager",s="Säuberung im Koboldlager ist eine frühe militärische Aufgabe, die Marschall McBride neu eingetroffenen Rekruten im Nordhaintal überträgt. Die Mission weist Freiwillige an, das in den nördlichen Wäldern lauernde Koboldunrat auszudünnen, um zu verhindern, dass die aggressiven unterirdischen Aasfresser das Abteigelände überrennen. Sie dient als erste echte Bewährungsprobe eines Initianden bei der Verteidigung der Grenzen des Königreichs Sturmwind.",h="Säuberung im Koboldlager ist eine frühe militärische Aufgabe, die Marschall McBride neu eingetroffenen...",kw={"echokamm","wald von elwynn","kobold","marschall mcbride","nordhain","abtei von nordhain","ungeziefer"},ang={["faction:Alliance"]="Die Unruhen in Nordhain verdeutlichen die Belastung der Kerngebiete Sturmwinds, wo selbst geringfügige Plündererplagen den dringenden Einsatz einer freiwilligen Miliz erfordern.",["race:Human"]="Für die Menschen von Nordhain ist das Zurückschlagen des Koboldunrats eine grundlegende Bürgerpflicht, um die Abtei und das Ackerland vor dem Überranntwerden zu bewahren."},sec={{t="Ein Tal unter Druck",b="Das Nordhaintal war einst eine ruhige Zuflucht für Gebet, Landwirtschaft und die Ausbildung von Novizen, doch in den letzten Jahren wurden Sturmwinds Streitkräfte stark überdehnt. Da der König verschollen ist und die königlichen Garnisonen verstreut sind, drängen wilde Kreaturen und Opportunisten kühn an die Grenzen der Zivilisation vor. Marschall McBride organisiert die örtliche Verteidigung aus dem Inneren der Abtei von Nordhain und verlässt sich auf frische Freiwillige, um die heranrückenden Bedrohungen einzudämmen, bevor sie den Betrieb der Abtei stören oder die umliegenden Weinberge gefährden."},{t="Das Ungeziefer in den Wäldern",b="Kobolde sind von Natur aus feige, kerzenbesessene Höhlenbewohner, die sich gewöhnlich damit begnügen, fernab des direkten Sonnenlichts unterirdische Adern abzubauen. Doch ein ganzer Clan ist bis an die nördliche Baumgrenze von Nordhain vorgedrungen. Bleiben sie unkontrolliert, lässt ihre bloße Überzahl aus Plünderungen offene Überfälle werden. McBrides Befehl, Koboldunrat zur Strecke zu bringen, dient einem doppelten Zweck: Er schwächt ihre Vorhut und stellt auf die Probe, ob ein Rekrut die nötige Entschlossenheit besitzt, um das Reich zu beschützen."}},faq={{q="Wer befiehlt das Ausdünnen des Koboldlagers?",a="Marschall McBride erteilt den Befehl. Er ist in der Abtei von Nordhain stationiert und überwacht im Auftrag von Sturmwind die örtliche Aufnahme von Rekruten sowie die Sicherheit des Tals.",al={"wer vergibt diese quest","questgeber","rolle von marschall mcbride"}},{q="Warum halten sich die Kobolde in den nördlichen Wäldern statt in einer Mine auf?",a="Obwohl Kobolde typischerweise in Bauen und Minen leben, ist ihre Population in Nordhain so dicht geworden, dass sie in den offenen Wald überquillt. Sie haben primitive Lager zwischen den nördlichen Bäumen errichtet und streifen nahe der Grenze des zivilisierten Landes umher.",al={"warum sind kobolde draußen","kobolde an der oberfläche","warum wald"}},{q="Warum gelten diese Kobolde als Bedrohung für Sturmwind?",a="Einzeln betrachtet ist Koboldunrat ängstlich und schwach. In Rotten hingegen sind sie dreiste Diebe, die Reisende überfallen, Vorräte plündern und unverteidigte Außenposten überrennen können – was sich Sturmwind nicht leisten kann, solange sein Militär ohnehin überdehnt ist.",al={"sind kobolde gefährlich","warum ungeziefer töten"}},{q="Wohin führt diese Mission als Nächstes?",a="Nachdem das oberirdische Ungeziefer ausgedünnt wurde, bittet Marschall McBride die Rekruten, tiefer in die Echokammmine vorzudringen, wo das Herz des Koboldbefalls liegt.",al={"welche quest kommt als nächstes","nächster schritt","nach säuberung des lagers"}},{q="Erhält Nordhain regelmäßige Unterstützung durch die königliche Armee?",a="Nein. Aufgrund politischer Spannungen und Truppenknappheit im gesamten Königreich nach dem Verschwinden von König Varian müssen sich örtliche Befehlshaber wie McBride auf zivile Freiwillige, Abenteurer und Rekruten verlassen, um die Grenzsicherheit zu gewährleisten.",al={"wo sind die wachen von sturmwind","warum freiwillige"}},{q="Warum hängen Kobolde so sehr an ihren Kerzen?",a="Kobolde verehren Kerzen als ihren wichtigsten Schutz gegen die erdrückende Dunkelheit unterirdischer Tunnel. Die Flamme bedeutet für sie Sicherheit, Sicht und Besitz, weshalb sie notorisch feindselig reagieren, wenn jemand versucht, sie ihnen wegzunehmen.",al={"warum kerzen","kerzenbesessenheit"}}},fx={["921e514b"]={q="Warum schickt Euch Marschall McBride anstelle der Wachen von Sturmwind?",a="Die königliche Armee von Sturmwind hat ihre Kräfte durch die Bewältigung von Krisen im gesamten Königreich bis aufs Äußerste strapaziert, weshalb das Nordhaintal nur noch von einer Handvoll Wachen besetzt ist. McBride muss seine Soldaten um die Abtei und die Hauptstraßen herum stationiert lassen, um die Verteidigungslinien aufrechtzuerhalten. Da er keine Truppen entbehren kann, um die Wildnis zu patrouillieren, ist er auf fähige neue Rekruten und vorbeikommende Freiwillige angewiesen, um aufkommende Gefahren auszumerzen.",al={"warum keine wachen schicken","warum braucht mcbride mich","warum abenteurer gegen kobolde rekrutieren"}},afae4267={q="Warum will Marschall McBride, dass das Koboldlager gesäubert wird?",a="Ein Koboldclan hat begonnen, die Wälder nördlich der Abtei zu befallen, und Marschall McBride möchte, dass ihre Anzahl verringert wird, bevor sie das Tal überrennen. Sturmwind ist bereits durch Bedrohungen an anderer Stelle belastet, sodass Nordhain sich selbst schützen muss. Obwohl sie einzeln feige sind, werden die Kobolde in Gruppen kühn. Sie jetzt auszudünnen, hält die Siedlung sicher und beginnt die Bemühungen, sie vollständig aus Nordhain zu vertreiben.",al={"warum kobolde ausdünnen","mcbrides motiv kobolde","warum koboldlager säubern"}},["35967b57"]={q="Was ist das Koboldungeziefer, das Ihr jagen sollt?",a="Koboldungeziefer sind die Kundschafter und Aasfresser eines Clans, der in den nördlichen Wald gekrochen ist. Von Natur aus unterirdische, rattenähnliche Humanoide, sind sie für sich genommen feige Diebe, aber sie haben sich in alarmierender Zahl in den Wäldern außerhalb von Nordhain versammelt. Wenn sie nicht aufgehalten werden, bedrohen ihre um sich greifenden Lager Reisende, Obstgärten und die Abtei selbst.",al={"wer ist das koboldungeziefer","was ist koboldungeziefer","ziel koboldungeziefer"}}},fp="19,169,23.267.0,23.319.0,42.126.0,56.203.0,55.199.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="Die Legende von Stalvan",s="In Goldhain entfacht ein alter Brief erneut die Suche nach Stalvan Dunstmantel. Seine Spur führt vom Wald von Elwynn ins Kanalviertel von Sturmwind.",h="In Goldhain entfacht ein alter Brief erneut die Suche nach Stalvan Dunstmantel.",kw={"canals","verwalter folsom","goldhain","gastwirt farley","gasthaus \"zur höhle des löwen\"","dunstmantel","stalvan","sturmwind","nicht zugestellter brief"},ang={["faction:Alliance"]="Um Stalvans Geheimnis zu ergründen, reist Ihr durch die Kernlande der Allianz. Eine alte Spur führt von Goldhain zu den prächtigen Kanälen der Hauptstadt.",["race:Human"]="Als Mensch seht Ihr die dunkleren Strömungen im Königreich Sturmwind. Die Übel, die den Dämmerwald heimsuchen, reichen bis vor die Tore der Hauptstadt."},sec={{t="Schrecken um Mitternacht",b="Im Gasthaus \"Zur Höhle des Löwen\" erinnert sich Gastwirt Farley an eine stürmische Nacht vor Jahren. Ein reisender Kurier kam aus dem Regen herein und suchte Schutz. Gegen Mitternacht stürmte er in Panik die Treppe hinunter, nur mit seiner Nachtkleidung bekleidet. Er verschwand im Sturm, und niemand sah ihn je wieder."},{t="Das zurückgelassene Paket",b="Der Kurier ließ seine Tasche und seine persönliche Truhe im Zimmer im Obergeschoss zurück. Unter der vergessenen Fracht lag ein nicht abgeschickter Brief mit dem Namen Stalvan, adressiert an jemanden im Kanalviertel von Sturmwind. Die Truhe blieb am Fußende des Bettes unberührt, bis Farley erlaubte, sie zu öffnen."},{t="Ein frostiger Empfang",b="Verwalter Folsom wacht über Anwesen entlang der Kanäle von Sturmwind nahe dem Park. Als Ihr ihm den längst überfälligen Brief bringt, reagiert er auf Stalvans Namen und Handschrift mit Abscheu und Feindseligkeit statt Dankbarkeit. Seine Reaktion deutet auf alte Skandale um den Absender hin."}},faq={{q="Wo wird der nicht zugestellte Brief aufbewahrt?",a="Der nicht zugestellte Brief liegt in einer Lagertruhe im Obergeschoss des Gasthauses \"Zur Höhle des Löwen\" in Goldhain. Geht die Treppe hinauf, wendet Euch nach rechts und betretet das Schlafzimmer mit dem Bett. Die Truhe steht am Fußende des Bettgestells.",al={"brief finden","stalvans truhe fundort","wo ist die truhe"}},{q="Warum wurde der Brief ursprünglich nie zugestellt?",a="Vor Jahren suchte der Kurier im Gasthaus \"Zur Höhle des Löwen\" Schutz vor einem Wolkenbruch. Gegen Mitternacht versetzte ihn etwas in Angst und Schrecken, und er floh in seiner Nachtkleidung in den Sturm, wobei er Truhe und Lieferungen zurückließ.",al={"warum wurde der brief zurückgelassen","was erschreckte den kurier","warum floh der bote"}},{q="Wo finde ich Verwalter Folsom in Sturmwind?",a="Verwalter Folsom befindet sich entlang der Canals in Sturmwind, nahe dem Rand des Parkviertels.",al={"folsom standort","wo ist verwalter folsom","im kanalviertel abgeben"}},{q="Warum ist Verwalter Folsom über den Erhalt des Briefes verärgert?",a="Folsom erkennt Stalvans Namen und Handschrift und reagiert empört. Stalvan Dunstmantel hinterließ bei den Menschen, die mit seiner Vergangenheit in Sturmwind verbunden sind, bittere Erinnerungen und Empörung.",al={"warum ist folsom wütend","folsoms reaktion","eine ziemliche frechheit"}},{q="Wie hängt das mit den Schwierigkeiten im Dämmerwald zusammen?",a="Der Stadtrat von Dunkelhain untersucht ein fortbestehendes Übel, das mit Stalvan Dunstmantel verbunden ist. Um herauszufinden, wer er war, folgt Ihr seinen früheren Reisen und Verbindungen durch den Wald von Elwynn und Sturmwind.",al={"warum dämmerwaldquest in goldhain","wie hängt das mit dem dämmerwald zusammen"}},{q="Was geschieht, nachdem ich Verwalter Folsom den Brief gegeben habe?",a="Verwalter Folsoms schroffe Antwort eröffnet das Sturmwinder Kapitel der Ermittlungen. Ihr müsst Stalvans früherer Anstellung und den düsteren Ereignissen um die Adelsfamilie nachgehen, der er diente.",al={"nächster schritt","was folgt auf diese quest"}}},fx={["1a6ccbd1"]={q="Warum möchte Gastwirt Farley, dass Stalvans Brief zugestellt wird?",a="Gastwirt Farley hat kein persönliches Interesse an Stalvans Angelegenheiten oder dem alten Brief; er hilft Euch lediglich dabei, das Geheimnis zusammenzusetzen, das Ihr untersucht. Wenn Ihr ihn auf Stalvan Dunstmantel ansprecht, erinnert sich Farley an einen verängstigten Boten, der vor Jahren während eines Sturms aus dem Gasthaus \"Zur Höhle des Löwen\" floh und sein Kuriergepäck oben zurückließ. Da er sich daran erinnert, dass ein niemals zugestellter Brief von Stalvan zurückblieb, der an den Kanalviertel von Sturmwind adressiert war, bietet er ihn Euch an, damit Ihr Eurer schwer fassbaren Spur folgen könnt.",al={"warum hilft farley","beweggrund gastwirt farley","warum den brief zustellen"}},b7fa74bd={q="Was ist der niemals zugestellte Brief?",a="Der Brief ist ein altes Schriftstück, das Stalvan Dunstmantel vor Jahren verfasste und das für eine Adresse im Kanalviertel von Sturmwind bestimmt war. Er wurde im Gasthaus \"Zur Höhle des Löwen\" zurückgelassen, als ein Bote in reiner Panik in die Nacht floh und seine Habe in einer Truhe oben einsperrte. Für Eure Ermittlungen dient der Brief als entscheidender physischer Hinweis, der Euch zu Verwalter Folsom in Sturmwind führt, um herauszufinden, mit wem Stalvan in Kontakt stand und was aus ihm wurde.",al={"was ist ein niemals zugestellter brief","stalvan niemals zugestellter brief","was steht im brief"}}},fp="21,134,17.266.0,19.289.0,16.261.1,37.203.0,46.205.0,46.91.0,57.183.0,49.198.0,57.186.1"}
P.entries["quest:700"] = {n="Ehrerbietung von einem König",s="Magni Bronzebart errichtet Sully Balloo ein Denkmal in Eisenschmiede. Granit aus Lordaeron hält den gefallenen Zwerg im Gedächtnis seines Volkes.",h="Magni Bronzebart errichtet Sully Balloo ein Denkmal in Eisenschmiede.",kw={"ehrerbietung von einem könig","granit","eisenschmiede","lordaeron","magni bronzebart","marmorstein","denkmal","sully balloo"},ang={["class:Warrior"]="Als Krieger hört Ihr, wie Magni die selbstlose Tapferkeit von Frontsoldaten wie Sully Balloo ehrt, die im Kampf alles gaben.",["faction:Alliance"]="Das Denkmal erinnert Euch an den hohen Blutzoll, den die jüngsten Konflikte in ganz Khaz Modan und den nördlichen Königreichen forderten.",["race:Dwarf"]="Als Zwerg teilt Ihr die Tradition, gefallene Krieger unter Euren Ahnen in beständigem Stein zu ehren."},sec={{t="Ein Denkmal aus Trauer",b="König Magni Bronzebart gab ein Denkmal für Sully Balloo in Auftrag, einen Zwerg, der im Dienst seines Volkes starb. Großsteinmetz Marmorstein meißelte es aus edlem Granit, der aus den kriegszerstörten Landen Lordaerons herangeschafft wurde. Das Denkmal steht in Eisenschmiede und ehrt Soldaten, deren Opfer dazu beitragen, das Zwergenkönigreich zu bewahren."},{t="Gedanken eines Herrschers",b="Als Magni erfährt, dass das Denkmal vollendet ist, sinnt er über Stein und Sterblichkeit nach. Behauener Fels kann niemals dem Leben eines tapferen Zwerges gleichkommen, das weiß er, doch er hofft, dass das Denkmal überdauert. Dann mögen Generationen, die Azeroth durchstreifen, sich an die Helden erinnern, die bluteten, um ihre Zukunft zu sichern."}},faq={{q="Wer wird mit diesem Denkmal geehrt?",a="Das Denkmal ehrt Sully Balloo, einen tapferen Zwergensoldaten, der im Kampf für sein Volk und die Allianz sein Leben gab.",al={"für wen ist dieses denkmal","sully balloo denkmal","wer ist gestorben"}},{q="Warum wurde der Stein aus Lordaeron beschafft?",a="Großsteinmetz Marmorstein brauchte edlen Granit für eine dauerhafte königliche Ehrerbietung. Lordaeron ist für außergewöhnlichen Stein aus seinen Steinbrüchen bekannt, doch die Region liegt seit dem Wüten der Geißel in Trümmern.",al={"warum stein aus lordaeron","granit aus lordaeron","marmorsteins stein"}},{q="Wo spielt diese Quest?",a="Ihr trefft Großsteinmetz Marmorstein und überbringt dann König Magni Bronzebart im High Seat von Eisenschmiede die Nachricht.",al={"wo abgeben","bei wem quest abschließen"}},{q="Warum gibt König Magni diese Ehrerbietung persönlich in Auftrag?",a="Magni glaubt, dass Herrscher die einfachen Soldaten ehren müssen, die ihre Reiche verteidigen. Das Denkmal soll künftige Generationen an den Preis erinnern, den einfache Soldaten für ihre Sicherheit zahlten.",al={"warum ist es magni wichtig","magni bronzebart sully balloo"}},{q="Was geschieht, nachdem das Denkmal vollendet ist?",a="Mit Eurem Bericht an König Magni schließt Ihr die Questreihe um das Denkmal ab. Die Statue bleibt als dauerhaftes Wahrzeichen zu Ehren von Sully Balloo in Eisenschmiede stehen.",al={"what comes next","ehrerbietung von einem könig folgequest"}},{q="Welche Bedeutung hat die Statue für die Steinmetzkunst?",a="Großsteinmetz Marmorstein zählt zu den versiertesten zwergischen Kunsthandwerkern Eisenschmiedes. Aus eingeführtem Granit aus Lordaeron schuf er für den Monarchen ein würdiges nationales Kunstwerk.",al={"marmorsteins rolle","handwerk des großsteinmetzen"}}},fx={["964451bf"]={q="Warum schickt Euch Großsteinmetz Marmorstein zum König?",a="Ihr wart diejenigen, die die gefährliche Reise zu den Ruinen von Lordaeron gewagt haben, um den feinen Granit für die Skulptur zu bergen. Nachdem Ihr den Stein gesichert und den Tribut ermöglicht habt, betraut Großsteinmetz Marmorstein Euch damit, König Magni Bronzebart persönlich die stolze Nachricht zu überbringen, dass Sully Balloos Denkmal fertiggestellt ist.",al={"warum mich zu magni schicken","warum könig magni informieren","warum schickt marmorstein den spieler"}}},fp="16,131,26.297.0,24.259.0,38.117.0,42.172.0,33.100.0,55.178.0,44.132.0,47.169.0"}
P.entries["quest:7003"] = {n="Geschrumpfte Riesen",s="An der Vergessenen Küste von Feralas testet Zorbin Fandazzle einen Schrumpfstrahl an den Riesen nahe den Docks. Er hat ihn nach einem gnomischen Entwurf gebaut und mit Goblin-Fachwissen verbessert, dann gibt er Euch den Ultra-Shrinker zum Ausprobieren an den Riesen von Feralas.",h="An der Vergessenen Küste von Feralas testet Zorbin Fandazzle einen Schrumpfstrahl an den Riesen nahe den...",kw={"cliff giant","feralas","die vergessene küste","land walker","miniaturisierungsrückstand","ultra-shrinker","geschrumpfte riesen","zorbin fandazzle"},sec={{t="Ein Schrumpfstrahl für die Riesen",b="Zorbin Fandazzle muss die Riesen von Feralas loswerden, damit er bleiben und sein Geschäft weiterführen kann. Seine Antwort ist ein Schrumpfstrahl nach gnomischem Entwurf, verbessert durch das, was er überlegene Goblin-Fortschritte nennt. Er lässt ihn lieber von Euch testen, als sein eigenes Leben zu riskieren.\n\nSetzt den Ultra-Shrinker gegen Cliff Giants, Deep Striders, Wave Striders, Shore Striders oder Land Walkers ein. Sammelt den Miniaturisierungsrückstand, der beim Schrumpfen zurückbleibt, und bringt ihn dann zu den Docks zurück."},{t="Warum Zorbin den Rückstand will",b="Zorbin bezeichnet Miniaturisierungsrückstand als wertvoll für das Ingenieurswesen. Er hilft zu verhindern, dass ein Schrumpfstrahler seinem Benutzer um die Ohren fliegt. Dann fügt er hinzu, dass dies nur für andere Schrumpfstrahler gilt, nicht für den in Euren Händen."},{t="Zurück an den Docks",b="Zorbin ist begeistert, als Ihr mit dem Rückstand und all Euren wichtigen Gliedmaßen unversehrt zurückkehrt. Er besteht darauf, dass der Ultra-Shrinker nie riskant war, und nennt Euch einen Freund aller Goblins."}},faq={{q="Wer steckt hinter dem Ultra-Shrinker?",a="Zorbin Fandazzle hat den Ultra-Shrinker bei den Docks an der Vergessenen Küste von Feralas gebaut.",al={"wer vergibt geschrumpfte riesen","zorbin fandazzle questgeber","wo beginnt geschrumpfte riesen"}},{q="Warum will Zorbin die Riesen schrumpfen?",a="Zorbin sagt, die Riesen seien schlecht fürs Geschäft, wenn er dort bleiben soll. Geschrumpfte Riesen lassen sich viel leichter in Schach halten.",al={"warum riesen beschießen","warum riesen in feralas schrumpfen","zorbin fandazzle beweggründe"}},{q="Welche Riesen lassen sich schrumpfen?",a="Jede Art von Riesen in Feralas ist geeignet. An der Vergessenen Küste findet Ihr Cliff Giants, Deep Striders, Wave Striders, Shore Striders und Land Walkers.",al={"welche riesen lassen sich beschießen","welche riesen zählen","geschrumpfte riesen ziele"}},{q="Was ist Miniaturisierungsrückstand?",a="Miniaturisierungsrückstand bleibt nach dem Schrumpfen an einem Riesen zurück. Zorbin bezeichnet ihn als wertvoll für das Ingenieurswesen, weil er verhindert, dass ein Schrumpfstrahler seinem Benutzer um die Ohren fliegt.",al={"warum miniaturisierungsrückstand","was bewirkt der rückstand","zorbin rückstand zweck"}}},fp="13,232,30.457.0,28.193.0,17.182.1,33.84.0,39.108.0,27.154.0,32.159.0"}
P.entries["quest:701"] = {n="Arglist des Raptors",s="Tor'gan will Gor'muls schlummernden Kriegergeist durch die Arglist des Raptors wecken. Er sammelt Herzen von Highland Fleshstalkers, um ein verzaubertes Amulett herzustellen und Gor'muls Kampfeswillen wiederherzustellen.",h="Tor'gan will Gor'muls schlummernden Kriegergeist durch die Arglist des Raptors wecken.",kw={"schlummernder krieger","gor'mul","arglist des raptors","highland fleshstalkers","raptorenherzen","tor'gan","krieger"},ang={["class:Warrior"]="Als Krieger wisst Ihr, dass Tor'gan Gor'muls schlummernden Kriegergeist mit der List und Wildheit der Raptoren wecken möchte.",["faction:Horde"]="Als Mitglied der Horde erkennt Ihr eine Tradition, die sich ursprünglicher Bestien und Naturgeister bedient, um einem teilnahmslosen oder geplagten Gefährten wieder ein Ziel zu geben."},sec={{t="Den schlummernden Krieger wecken",b="Tor'gan will Gor'mul aus seiner Teilnahmslosigkeit reißen und seinen schlummernden Kriegergeist wiedererwecken. Er setzt auf Urmagie statt auf Überredung und hofft, dass ein Amulett voller Raubtieressenz Gor'mul zum Handeln bewegen wird. Durch das Amulett will er Gor'muls kriegerische Entschlossenheit erneuern und ihm die Stärke dieser Macht zeigen."},{t="Das Herz des Raubtiers",b="Tor'gan braucht Herzen von Highland Fleshstalkers, um die Instinkte eines listigen Jägers anzurufen. In schamanischen und urzeitlichen Traditionen trägt das Herz eines Raubtiers dessen Wildheit und Arglist in sich. Tor'gan verwendet diese Trophäen, um ein greifbares Zeichen herzustellen und einen Zauber zu weben. Er hofft, dass sie Gor'mul die List eines Raubtiers verleihen und ihm helfen, seine Berufung wiederzufinden."}},faq={{q="Wer ist Tor'gan?",a="Tor'gan ist eine spirituelle Gestalt, die Gor'mul helfen will. Er glaubt, dass Gor'mul den Zugang zu seiner inneren Stärke verloren hat, und sammelt deshalb Reagenzien für einen Gegenstand voller Tiermagie, um ihn aufzurütteln.",al={"wer ist tor'gan","torgan","questgeber"}},{q="Wer ist Gor'mul?",a="Gor'mul hat seinen Kampfgeist verloren, und der Krieger in ihm schlummert. Tor'gan will ihn mit ursprünglicher Raubtieressenz erfüllen, damit Gor'mul neue Macht erfahren und sich wieder zum Kampf erheben kann.",al={"wer ist gormul","warum gormul helfen","schlummernder krieger"}},{q="Warum braucht Tor'gan Raptorenherzen?",a="Tor'gan braucht zwölf Raptorenherzen, um einen greifbaren Talisman herzustellen und die Verzauberung zu weben, die Gor'mul erfüllen soll. Urmagie nutzt die Herzen von Raubtieren, um ihre Instinkte, ihre Arglist und ihre Kraft zu kanalisieren.",al={"warum raptorenherzen","wofür sind die herzen","raptorenmagie"}},{q="Woher stammen die Raptorenherzen?",a="Die Herzen stammen von Highland Fleshstalkers, räuberischen Raptoren, die für ihre unerbittliche Jagd und ihre List bekannt sind. Tor'gan glaubt, dass ihre Herzen den Zauber speisen können, der Gor'mul erwecken wird.",al={"woher die herzen bekommen","welche raptoren","highland fleshstalkers"}},{q="Was bedeutet die Arglist des Raptors?",a="Die Arglist des Raptors steht für die List, die schnellen Reflexe und den tödlichen Instinkt eines Raubtiers. Tor'gan glaubt, dass dieses Wesen Gor'muls Lethargie durchbrechen und seine Kampfinstinkte wiederbeleben kann.",al={"was ist arglist des raptors","welche macht","bedeutung der arglist des raptors"}},{q="Was ist das letztendliche Ziel des Rituals?",a="Tor'gan verwendet die gesammelten Herzen, um einen Gegenstand herzustellen und einen Zauber zu weben. Er hofft, Gor'mul neue Macht zu zeigen und sein schlummerndes Kriegerwesen zu wecken, damit Gor'mul seinen Weg wiederfinden kann.",al={"ist gormul geheilt","was geschieht nach dem ritual","funktioniert es"}}},fp="19,196,29.335.0,25.336.0,15.190.0,15.194.0,36.199.0,37.179.0,42.187.0,40.176.0"}
P.entries["quest:702"] = {n="Arglist des Raptors",s="In Hammerfall schickt Tor'gan Euch mit einer Kugel zu Gor'mul, um den Geist des Kriegers zu wecken. Ihre Energie birgt die Essenz des Raptors und könnte Gor'mul ein neues Ziel geben.",h="In Hammerfall schickt Tor'gan Euch mit einer Kugel zu Gor'mul, um den Geist des Kriegers zu wecken.",kw={"arathihochland","gor'mul","hammerfall","essenz des raptors","tor'gan","tor'gans kugel"},sec={{t="Tor'gans Kugel",b="Tor'gan gibt Euch eine Kugel, die Gor'mul mit der Essenz des Raptors erfüllen soll. Er hofft, dass sie den Geist des Kriegers weckt und ihn auf einen neuen Lebensweg führt.\n\nSobald Gor'mul wieder er selbst ist, will Tor'gan ihm die gegenwärtige Lage der Horde erklären. Er hofft, die Hilfe eines großen Kriegers für ihre unaufhörlichen Kämpfe zu gewinnen."},{t="Gor'muls Bitterkeit",b="Gor'mul begrüßt Eure Rückkehr mit Bitterkeit. Er sagt, alles, was er wolle, sei noch mehr von Tor'gans Mitleid, und verspottet Euch dann mit Gerede über bunte Schnüre."},{t="Eine seltsame Macht",b="Die Kugel weckt Gor'muls Interesse. Er bemerkt die seltsame Macht, die von ihr ausgeht."},{t="Der Raptor im Innern",b="Als Gor'mul die Kugel nimmt, regt sich sein Blut, und die List des Raptors durchströmt ihn. Er fragt sich laut, ob dies der Schamanismus sei, von dem Tor'gan gesprochen habe. Dann erklärt er sich für erneuert, während seine Stärke zurückkehrt."}},faq={{q="Wer ist Gor'mul?",a="Gor'mul ist ein niedergeschlagener Krieger in Hammerfall. Tor'gan hofft, seinen Lebensmut zu wecken und ihn auf einen neuen Weg zu führen, damit die Horde die Hilfe eines großen Kriegers gewinnt.",al={"wer ist gormul","gormul hintergrundgeschichte","was fehlt gormul"}},{q="Welchen Zweck hat Tor'gans Kugel?",a="Tor'gans Kugel birgt Energie, die Gor'mul mit der Essenz des Raptors erfüllen soll. Sie könnte seinen Geist wecken und ihm ein neues Ziel geben.",al={"was bewirkt die kugel","torgan kugel zweck","arglist kugel"}},{q="Was ging diesem Schritt voraus?",a="Zuerst kommt eine frühere Quest namens Arglist des Raptors. Dieser Schritt baut auf den dortigen Ereignissen auf.",al={"vorherige quest","voraussetzung"}}},fp="19,160,13.310.0,20.144.0,15.79.1,17.206.1,15.160.0,37.127.0,27.84.0"}
P.entries["quest:7025"] = {n="Leckereien für Altvater Winter",s="In Eisenschmiede bittet Euch der Zwerg, der Altvater Winter spielt, um einen Festtagsimbiss. Bringt ihm fünf frisch gebackene Lebkuchenplätzchen und Eiskalte Milch, und er dankt Euch mit einem festlichen Geschenk.",h="In Eisenschmiede bittet Euch der Zwerg, der Altvater Winter spielt, um einen Festtagsimbiss.",kw={"winterhauchfest","lebkuchenplätzchen","altvater winter","eiskalte milch","eisenschmiede","kokelwälder","leckereien für altvater winter"},ang={["faction:Alliance"]="Als Reisende der Allianz findet Ihr in Eisenschmiede Feierlichkeiten zum Winterhauchfest. Besucher aus allen Teilen der Östlichen Königreiche versammeln sich am Festtagsbaum in den Commons.",["profession:Cooking"]="Als Koch backt Ihr Lebkuchenplätzchen mit kleinen Eiern und Festtagsgewürzen.",["race:Dwarf"]="Als Zwerg kennt Ihr Altvater Winter als uralte Sagengestalt, die mit den Titanen und der Fülle des Winters verbunden ist. In den Commons genießt die Gestalt Plätzchen und holt damit den Mythos auf den Boden der Tatsachen."},sec={{t="Ein langer Tag im Sessel",b="Die Kokelwälder unterstützen die Feierlichkeiten zum Winterhauchfest in Eisenschmiede. Am Festtagsbaum in den Commons sitzt ein Darsteller, verkleidet als Altvater Winter. Stundenlang hört er sich die Festtagswünsche von Bürgern und erwartungsvollen Kindern an. Er trägt die Verkleidung einer unsterblichen Gestalt aus uralter Titanenlehre und Zwergenmythen."},{t="Festtagsfreude aus dem Ofen",b="Nachdem der Darsteller den ganzen Tag Geschenkwünsche angehört hat, wird er hungrig. Er bittet um fünf frisch gebackene Lebkuchenplätzchen und Eiskalte Milch. Die einfache Mahlzeit verschafft dem erschöpften Festtagsarbeiter einen Moment der Erleichterung. Eure Freundlichkeit verbreitet gute Stimmung in Eisenschmiede."}},faq={{q="Wo finde ich Altvater Winter in Eisenschmiede?",a="Altvater Winter sitzt neben dem großen Festtagsbaum und dem Stand der Kokelwälder in den Commons von Eisenschmiede, umgeben von festlichem Schmuck.",al={"wo ist altvater winter","altvater winter standort eisenschmiede","weihnachtsmann standort eisenschmiede"}},{q="Wie backt man Lebkuchenplätzchen?",a="Die Händler der Kokelwälder in der Nähe von Altvater Winter verkaufen das Rezept. Zum Backen der Plätzchen braucht Ihr Kochkunst, Festtagsgewürze vom Festtagshändler und kleine Eier, die Ihr von Wildvögeln sammelt.",al={"wo gibt es lebkuchenplätzchen","lebkuchenrezept","wie plätzchen backen"}},{q="Wo bekomme ich Eiskalte Milch?",a="Gastwirte, Lebensmittelhändler und Getränkeverkäufer in großen Städten der Allianz verkaufen Eiskalte Milch. Ihr findet sie in den Tavernen überall in Eisenschmiede.",al={"eiskalte milch händler","wo milch kaufen","milch eisenschmiede"}},{q="Ist dieser Altvater Winter die echte Sagengestalt?",a="Nein. Zum Winterhauchfest stellen die Kokelwälder einen Zwerg ein, der die mit den Titanen verbundene Sagengestalt verkörpert.",al={"ist altvater winter echt","wer ist der kerl in eisenschmiede","ist er wirklich altvater winter"}},{q="Was schickt Euch Altvater Winter nach Abschluss der Quest?",a="Nachdem Altvater Winter die Plätzchen und die Milch erhalten hat, dankt er Euch mit einer Kokelwälder Geschenkpackung.",al={"leckereien für altvater winter belohnung","post von altvater winter","kokelwälder sampler"}},{q="Können Spieler der Horde diese bestimmte Quest abschließen?",a="Diese Aufgabe in Eisenschmiede richtet sich an Reisende der Allianz. Mitglieder der Horde haben eine entsprechende Aufgabe, die sie zu Altvater Winter in Orgrimmar schickt.",al={"kann die horde diese quest machen","horde leckereien für altvater winter"}}},fx={["4b1f8d0d"]={q="Warum möchte Altvater Winter, dass dies erledigt wird?",a="Altvater Winter sitzt den ganzen Tag in Eisenschmiede, hört sich Festtagswünsche an und begrüßt Besucher, ohne eine Pause zu machen. Während das Festhauchfest jedem anderen Freude bringt, haben ihn all die Reden über Festtagsleckereien erschöpft und hungrig gemacht, also bittet er Euch, ihm einen dringend benötigten Snack zu besorgen.",al={"beweggrund altvater winter kekse","warum möchte altvater winter kekse","warum leckereien für altvater winter"}},a70b2277={q="Wofür ist die Eiskalte Milch?",a="Die Eiskalte Milch ist einfach ein erfrischendes Getränk, um die Portion warme Lebkuchenkekse hinunterzuspülen. Den ganzen Tag Reisende zu begrüßen und festliche Wünsche zuzurufen, macht durstig, und nichts ergänzt süße Festtagsplätzchen besser als ein eiskaltes Getränk.",al={"warum eiskalte milch","milch für altvater winter","zweck eiskalte milch"}},cc125737={q="Wofür sind die Lebkuchenkekse?",a="Die Lebkuchenkekse dienen als persönliche Festtagsleckerei für Altvater Winter selbst. Nachdem er Leckereien verteilt und die Wünsche eines Bürgers nach dem anderen angehört hat, sehnt er sich nach einem traditionellen Festhauchkonfekt, das mit Festtagsgewürzen hergestellt wurde, um seine Energie wieder aufzuladen.",al={"lebkuchenkekse leckereien für altvater","warum lebkuchenkekse","kekse für altvater winter"}},["6bf2696f"]={q="Warum braucht Altvater Winter Euch, anstatt die Leckereien selbst zu besorgen?",a="Altvater Winter kann seinen Posten inmitten der Feierlichkeiten nicht verlassen. Er ist am Baum in Eisenschmiede stationiert, um die Menschenmengen zu begrüßen und für Smokywood Pastures Freude zu verbreiten, was bedeutet, dass er an seinen Platz gebunden ist und auf großzügige Passanten wie Euch angewiesen ist, um Besorgungen für Essen zu machen.",al={"warum braucht altvater winter mich","warum kann altvater winter seine kekse nicht selbst besorgen","warum bittet altvater winter einen abenteurer"}}},fp="29,183,22.305.0,20.261.0,48.143.0,36.195.0,29.137.0,50.116.0,64.104.1,47.144.0"}
P.entries["quest:7029"] = {n="Vyletongue Corruption",s="Vark Battlescar bittet Euch, die von Verderbnis befallenen Pflanzen in Maraudon zu versorgen. Der orangefarbene Kristallteich und Vylestem Vines gehören dazu.",h="Vark Battlescar bittet Euch, die von Verderbnis befallenen Pflanzen in Maraudon zu versorgen.",kw={"cerulean vial","verdorbene pflanzen","maraudon","noxxious scion","oranger kristallteich","schattenflucht","vark battlescar","vylestem vines","vyletongue corruption"},sec={{t="Varks Bitte",b="In Schattenflucht bittet Vark Battlescar Euch, von Verderbnis befallene Pflanzen zu heilen. Er gibt Euch ein Coated Cerulean Vial, das Ihr am orangefarbenen Kristallbecken in Maraudon füllt. Das Fläschchen ist für die Vylestem Vines bestimmt, aus denen verderbte Noxxious Scions hervorkommen."},{t="Die Pflanzen",b="Die Noxxious Scions gehören zur Heilung der Pflanzen. Sobald Ihr acht Pflanzen geheilt habt, könnt Ihr zu Vark Battlescar in Schattenflucht zurückkehren."}},faq={{q="Was bittet Vark Battlescar mich zu tun?",a="Vark Battlescar bittet Euch, in Maraudon acht von Verderbnis befallene Pflanzen zu heilen und anschließend zu ihm nach Schattenflucht zurückzukehren.",al={"varks pflanzenaufgabe","varks bitte","was soll ich für vark tun"}},{q="Wo bekomme ich das Cerulean Vial?",a="Vark Battlescar überreicht Euch das Coated Cerulean Vial, und Ihr füllt es am orangefarbenen Kristallbecken in Maraudon.",al={"fundort des cerulean vial","wo ist das fläschchen","oranger teich"}},{q="Wozu dienen Vylestem Vines?",a="Wenn Ihr das Filled Cerulean Vial auf Vylestem Vines anwendet, kommt ein verdorbener Noxxious Scion hervor.",al={"vylestem vines","zweck der ranken","ranken und fläschchen"}},{q="Wie werden die Pflanzen geheilt?",a="Die Pflanzen werden geheilt, indem Ihr die verdorbenen Noxxious Scions tötet, die aus Vylestem Vines hervorkommen.",al={"pflanzen heilen","pflanzenverderbnis","noxxious scion und pflanzen"}},{q="Wie viele Pflanzen müssen geheilt werden?",a="Ihr müsst acht Pflanzen heilen, bevor Ihr zu Vark Battlescar zurückkehrt.",al={"anzahl der pflanzen","wie viele pflanzen","acht pflanzen"}},{q="Wo ist Vark Battlescar?",a="Vark Battlescar ist in Schattenflucht.",al={"varks aufenthaltsort","wo ist vark","vark in schattenflucht"}}},fp="21,131,16.253.0,10.139.0,39.124.0,33.107.0,32.91.0,26.99.0,29.63.0,25.41.0"}
P.entries["quest:703"] = {n="Gegrillte Bussardflügel",s="Rigglefuzz hat alle Zutaten für seine gegrillten Bussardflügel außer den Flügeln selbst.",h="Rigglefuzz hat alle Zutaten für seine gegrillten Bussardflügel außer den Flügeln selbst.",kw={"ödland","grillen","bussard","kochen","rezept","rigglefuzz","flügel"},ang={["profession:Cooking"]="Köche können das Rezept für das Gericht von Rigglefuzz lernen."},sec={{t="Eine örtliche Spezialität",b="Rigglefuzz ist stolz auf seine gegrillten Bussardflügel. Er überzieht das würzige Fleisch mit reichhaltiger Sauce, deren Duft hungrige Leute in der Nähe erreicht. Er hat alle Zutaten für eine Portion außer den Flügeln. Bringt ihm vier Bussardflügel, und vielleicht verrät er Euch das Rezept."}},faq={{q="Wer bittet um die Bussardflügel?",a="Rigglefuzz möchte Bussardflügel für eine Portion seiner gegrillten Flügel.",al={"wer vergibt gegrillte bussardflügel","wer ist rigglefuzz","questgeber"}},{q="Was bietet Rigglefuzz im Gegenzug für die Flügel an?",a="Rigglefuzz verrät Euch vielleicht das Rezept, wenn Ihr ihm genug Flügel bringt.",al={"was ist die belohnung","was bekomme ich","rezept als belohnung"}},{q="Warum braucht Rigglefuzz Bussardflügel?",a="Rigglefuzz hat alle Zutaten für das Gericht außer den Flügeln.",al={"warum bussarde","rigglefuzz beweggrund","warum will rigglefuzz flügel"}},{q="Wie viele Flügel möchte Rigglefuzz?",a="Rigglefuzz möchte vier Bussardflügel.",al={"wie viele bussardflügel","anzahl der bussardflügel"}}},fp="23,92,16.251.0,31.66.0,51.59.0,39.62.0,36.36.0"}
P.entries["quest:705"] = {n="Perlentauchen",s="Im Ödland geht Rigglefuzz das Pulver für seine Blitzbomben aus. Er schickt Euch zum Finsteren Riff im Schlingendorntal, um mehr zu sammeln.",h="Im Ödland geht Rigglefuzz das Pulver für seine Blitzbomben aus.",kw={"ödland","blaue perle","blitzbombe","perlentauchen","rigglefuzz","schlingendorntal","das finstere riff"},ang={["profession:Engineering"]="Als Ingenieur habt Ihr guten Grund, Euch für Rigglefuzz' Blitzbomben zu interessieren."},sec={{t="Ein gewitzter kleiner Goblin",b="Rigglefuzz gibt zu, dass ihm das Ödland Angst macht. Als kleiner Goblin sieht er sich ringsum Raubtieren und Aasfressern gegenüber. Er weiß, wie man Blitzbomben herstellt, und setzt sie ein, um die Tierwelt zu vertreiben. Nun geht ihm der zerstoßene blaue Perlenstaub aus."},{t="Perlen vom Riff",b="Muscheln am Finsteren Riff im Schlingendorntal enthalten blaue Perlen. Rigglefuzz scherzt, dass Ihr besser gute Stiefel tragen solltet, und wartet dann im Ödland auf neun Perlen. Er verspricht, dass sich Eure Mühe lohnen wird."}},faq={{q="Warum braucht Rigglefuzz blaue Perlen?",a="Rigglefuzz verwendet zerstoßenen blauen Perlenstaub zur Herstellung von Blitzbomben, und sein Vorrat geht zur Neige.",al={"rigglefuzz perlen","warum perlentauchen","warum blaue perlen"}},{q="Wo findet man die blauen Perlen?",a="Blaue Perlen findet man in Muscheln am Finsteren Riff im Schlingendorntal.",al={"wo sind blaue perlen","fundort blauer perlen","finsteres riff perlen"}},{q="Warum verwendet Rigglefuzz Blitzbomben?",a="Bösartige Raubtiere und dreiste Aasfresser bevölkern das Ödland, weshalb Rigglefuzz Blitzbomben einsetzt, um die Tierwelt zu verscheuchen.",al={"warum blitzbomben","rigglefuzz verteidigung"}},{q="Wie viele blaue Perlen möchte Rigglefuzz?",a="Rigglefuzz möchte, dass Ihr ihm neun blaue Perlen ins Ödland bringt.",al={"anzahl blauer perlen","wie viele perlen"}}},fp="12,136,22.241.0,20.199.0,37.93.0,32.65.0,36.118.0,42.67.0"}
P.entries["quest:706"] = {n="Feuerverzauberungen",s="Für Feuerverzauberungen im Ödland wird das noch schlagende Herz eines seltenen schwarzen Drachenwelpen benötigt. Sigrun Ironhew wartet auf Nachricht aus Eisenschmiede, und die Welpen der Lethlorklamm könnten liefern, was sie braucht.",h="Für Feuerverzauberungen im Ödland wird das noch schlagende Herz eines seltenen schwarzen Drachenwelpen...",kw={"ödland","schwarzes drachenherz","feranor steeltoe","feuerverzauberungen","eisenschmiede","die lethlorklamm","scalding whelp","scorched guardian","sigrun ironhew"},ang={["faction:Alliance"]="Sigrun Ironhew wartet auf Nachricht aus Eisenschmiede, und diese Arbeit ist für die Allianz bestimmt."},sec={{t="Die Kunst eines Lehrlings",b="Sigrun Ironhew lernte als Lehrling von Feranor Steeltoe, Feuer auf Waffen zu entfachen. Von Feranor hörte man zuletzt unter den Schmieden eines Jagdtrupps in Lordaeron. Sigrun wartet im Ödland auf Nachricht aus Eisenschmiede. Sie hat sonst wenig zu tun."},{t="Die Welpen der Lethlorklamm",b="Sigrun verrät wenig über das Verfahren. Es erfordert Blut aus dem noch schlagenden Herzen eines seltenen schwarzen Drachenwelpen. Bringt ihr ein Herz von einem Welpen aus der Lethlorklamm, und sie wird Euch die Fertigkeit zeigen. Die Scalding Whelps und Scorched Guardians dort liefern die Herzen."}},faq={{q="Wer hat Sigrun Ironhew diese Verzauberungstechnik beigebracht?",a="Sigrun erlernte die Technik als Lehrling von Feranor Steeltoe. Von Feranor hörte man zuletzt unter den Schmieden eines Jagdtrupps in Lordaeron.",al={"sigruns lehrer","wer hat sigrun ausgebildet","feranor steeltoe"}},{q="Welche Zutat wird benötigt, um eine Klinge mit Feuer zu erfüllen?",a="Die Verzauberung erfordert Blut aus dem noch schlagenden Herzen eines seltenen schwarzen Drachenwelpen.",al={"was braucht sigrun","schwarzes drachenherz voraussetzung","feuerverzauberungen materialien"}},{q="Wo findet man die schwarzen Drachenwelpen?",a="Schwarze Drachenwelpen findet man in der Lethlorklamm im östlichen Ödland.",al={"wo schwarze drachen finden","lethlorklamm welpen","schwarzes drachenherz fundort"}},{q="Warum verweilt Sigrun Ironhew im Ödland?",a="Sigrun wartet auf Nachricht aus Eisenschmiede und hat in der Zwischenzeit sonst wenig zu tun.",al={"warum ist sigrun im ödland","sigrun ironhew aufgabe"}},{q="Welche Kreaturen liefern das benötigte Herz?",a="Die Scalding Whelps und Scorched Guardians der Lethlorklamm liefern das benötigte Herz.",al={"wer lässt schwarzes drachenherz fallen","welche welpen haben herzen"}}},fp="24,208,21.244.0,28.266.0,53.142.0,52.89.0,39.72.0,48.84.0,39.84.0"}
P.entries["quest:7070"] = {n="Shadowshard Fragments",s="Erzmagier Tervosh in Theramore bittet Euch, Shadowshard Fragments aus Maraudon zu sammeln. Er braucht zehn davon.",h="Erzmagier Tervosh in Theramore bittet Euch, Shadowshard Fragments aus Maraudon zu sammeln.",kw={"erzmagier tervosh","düstermarschen","maraudon","shadowshard fragments","tervosh","theramore"},sec={{t="Tervoshs Bitte",b="Erzmagier Tervosh wartet in Theramore an der Küste der Düstermarschen. Er bittet Euch, ihm zehn Shadowshard Fragments aus Maraudon zu bringen. Die Fragmente stehen im Mittelpunkt seiner Bitte."}},faq={{q="Wer bittet um Shadowshard Fragments?",a="Erzmagier Tervosh in Theramore bittet Euch, die Shadowshard Fragments zu sammeln.",al={"wer möchte fragmente","tervosh fragmente"}},{q="Woher stammen die Fragmente?",a="Die Shadowshard Fragments stammen aus Maraudon.",al={"woher fragmente","maraudon splitter"}},{q="Wie viele Fragmente möchte Tervosh?",a="Erzmagier Tervosh bittet um zehn Shadowshard Fragments.",al={"wie viele splitter","zehn fragmente"}},{q="Wohin soll ich sie bringen?",a="Bringt die Fragmente zu Erzmagier Tervosh nach Theramore an der Küste der Düstermarschen.",al={"wohin fragmente zurückbringen","tervoshs ort"}}},fp="21,119,19.182.0,39.76.0,33.45.0,37.52.0,22.87.0"}
P.entries["quest:708"] = {n="Der Flugschreiber",s="Ein riesiger Kondor im Ödland hat eine schwarze Kiste verschluckt, die für Eisenschmiede bestimmt war.",h="Ein riesiger Kondor im Ödland hat eine schwarze Kiste verschluckt, die für Eisenschmiede bestimmt war.",kw={"ödland","schwarze kiste","korrodierte schwarze kiste","riesenkondor","hall of arms","belagerungsbrigade von eisenschmiede","pilot langbart"},ang={["faction:Alliance"]="Die Kiste trägt das Zeichen von Eisenschmiede, und ihre Spur führt nach Eisenschmiede."},sec={{t="Aus einem Kondor geborgen",b="Nach einer Ewigkeit im Magen des Kondors hatte Säure das Metall zerfressen. Ein Symbol kennzeichnet die Unterseite über den Worten Engine #19 - Belagerungsbrigade von Eisenschmiede. Ihr bringt die Kiste zu Pilot Langbart in der Hall of Arms in Eisenschmiede."}},faq={{q="Woher stammte die korrodierte schwarze Kiste?",a="Ein riesiger Kondor im Ödland hat die Kiste verschluckt, und sie scheint schon seit Ewigkeiten in seinem Magen zu liegen.",al={"woher die kiste stammt","wie die kiste hierher kam","ursprung der schwarzen kiste"}},{q="Welche Markierungen sind auf der Kiste eingeprägt?",a="Auf der Unterseite ist über den Worten Engine #19 - Belagerungsbrigade von Eisenschmiede ein Symbol eingeprägt.",al={"was steht auf der kiste","markierungen auf der schwarzen kiste","inschrift der kiste"}},{q="Wer soll die Kiste erhalten?",a="Pilot Langbart, in der Hall of Arms in Eisenschmiede.",al={"wer die kiste erhält","wohin die schwarze kiste kommt","wem die kiste gebracht werden soll"}}},fp="13,74,20.211.0,43.100.0,37.90.0,35.50.0"}
P.entries["quest:71"] = {n="Meldung an Thomas",s="Wache Thomas wartet an der östlichen Brücke zwischen Goldhain und dem Holzfällerlager des Osttals. Das Schicksal seiner vermissten Männer könnte zeigen, ob die Flussmurlocs mehr als nur Späher bedrohen.",h="Wache Thomas wartet an der östlichen Brücke zwischen Goldhain und dem Holzfällerlager des Osttals.",kw={"brücke","wald von elwynn","goldhain","wache thomas","malakai","medaillons","murlocs","rolf"},ang={["faction:Alliance"]="Der Tod von Rolf und Malakai zeigt, wie ungeschützt die Grenzen des Waldes von Elwynn sind. Selbst gewöhnliche Flusspatrouillen können überwältigt werden, wenn es an Wachen mangelt.",["race:Human"]="Als Mensch verschafft Ihr den Soldaten von Sturmwind, die bei der Verteidigung der Straßen im Inneren des Königreichs fielen, durch die Bergung ihrer Medaillons ein Stück Ehre und einen endgültigen Abschluss."},sec={{t="Eine düstere Bestätigung",b="Da er am Übergang nur wenige Männer entbehren konnte, hatte Thomas gehofft, Malakai und Rolf seien in den Flusslanden nur abgeschnitten oder aufgehalten worden. Ihre geborgenen Dienstmedaillons lassen diese Hoffnung schwinden. Beide Wachen wurden nahe den Wasserwegen erschlagen."},{t="Die Bedrohung am Wasser",b="Seit Monaten betrachtet die Führung von Sturmwind Murlocs als lästige Flussbewohner und konzentriert sich stattdessen auf Banditen und die übrigen Grenzen des Königreichs. Nun wurden zwei bewaffnete Wachen von Sturmwind an den Flussläufen im Landesinneren abgeschlachtet. Die Medaillons zeigen Thomas, dass die östliche Grenze von Elwynn angegriffen wird, und er fordert Gegenmaßnahmen, bevor die Holzfällerrouten und Siedlungen überrannt werden."}},faq={{q="Wo steht Wache Thomas?",a="Wache Thomas ist an der Steinbrücke über den Fluss im östlichen Wald von Elwynn postiert, an der Straße zwischen Goldhain und dem Holzfällerlager des Osttals.",al={"thomas standort","wache thomas brücke","wo ist wache thomas"}},{q="Wer waren Rolf und Malakai?",a="Rolf und Malakai waren Wachen von Sturmwind, die auf Patrouille in den östlichen Wald von Elwynn geschickt wurden. Murlocs an den Flussufern und am Stonecairn Lake überwältigten und töteten sie.",al={"vermisste wachen elwynn","wer war rolf","wer war malakai"}},{q="Warum waren ihre Medaillons nötig?",a="Die Medaillons weisen sie als Stadtwachen von Sturmwind aus. Ihre Rückgabe liefert Wache Thomas den Beweis, dass seine vermissten Männer im Dienst gefallen sind.",al={"warum medaillons","zweck der wachmedaillons"}},{q="Warum ist der Angriff der Murlocs so bedeutsam?",a="Murlocs werden gemeinhin als primitive, feige Plagegeister abgetan. Der Tod zweier bewaffneter Wachen zeigt, dass die Flussstämme koordinierte Hinterhalte legen und ausgebildete Soldaten bedrohen können.",al={"warum sind murlocs eine bedrohung","sind murlocs in elwynn gefährlich"}},{q="Was geschieht nach der Rückmeldung bei Thomas?",a="Thomas bittet Euch, Marschall Dughan in Goldhain einen Bericht über den Tod der Wachen und die wachsende Bedrohung durch Murlocs zu überbringen. Dughan warnt, dass die Verteidigungskräfte der Region bereits überlastet sind.",al={"nächste quest nach meldung an thomas","was tut thomas als nächstes"}},{q="Warum ist Wache Thomas allein an der Brücke postiert?",a="Sturmwinds Militär ist im ganzen Reich überlastet, während König Varian Wrynn vermisst wird und die Mittel knapp sind. An der östlichen Brücke und anderen Außenposten stehen nur wenige Wachen zum Schutz wichtiger Wege bereit.",al={"warum ist thomas allein","sturmwind brückenwache allein"}}},fx={d4d51b05={q="Warum die Medaillons an Wache Thomas übergeben?",a="Wache Thomas sandte Patrouillen zum Fluss, doch sie verschwanden ohne ein Wort. Rolf und Malakai gefallen in den Schilf liegen zu finden, gibt eine düstere Gewissheit über ihr Ende. Ihre geborgenen Medaillons an Thomas zurückzugeben, beweist zweifelsfrei, was seinen Männern zugestoßen ist, und warnt ihn vor der tödlichen Murloc-Präsenz entlang des östlichen Wassers.",al={"warum bei thomas melden","warum medaillons zu thomas bringen","zweck der meldung an thomas"}},["3744e02c"]={q="Warum seid Ihr die Person, die die Medaillons an Thomas zurückgibt?",a="Rolf und Malakai sind tot, erschlagen von den Murlocs tief im feindlichen Flussuferdorf. Wache Thomas ist allein an der östlichen Brücke stationiert und kann seinen Posten nicht unbewacht lassen. Als Reisender, der die gefallenen Wachen fand und den Murlocs trotzte, um ihre Abzeichen zu bergen, fällt die Aufgabe an Euch, die düstere Nachricht zurückzubringen.",al={"warum ich bei thomas melden","warum bringe ich die medaillons"}}},fp="16,179,19.218.0,26.390.0,30.144.0,26.154.1,36.133.1,41.180.1,44.185.1,47.196.0"}
P.entries["quest:710"] = {n="Element-Studie: Fels",s="Im Ödland braucht Lotwil Veriatus Steinsplitter, um seine Arbeit an Elementarfesseln zu testen. Niedere Steinelementare durchstreifen die Hügel direkt westlich von ihm.",h="Im Ödland braucht Lotwil Veriatus Steinsplitter, um seine Arbeit an Elementarfesseln zu testen.",kw={"ödland","niedere steinelementare","lotwil veriatus","fesseln der elementarbindung","kleine steinsplitter","element-studie: fels"},ang={["class:Mage"]="Als Magier gehört Ihr zu jenen, denen Lotwils Fesseln dienen sollen."},sec={{t="Elementarfesseln",b="Im Ödland fertigt Lotwil Veriatus Fesseln der Elementarbindung. Sobald sie fertig sind, werden Magier damit stärkere Elementare für größere Zwecke beschwören können. Um seine Offensivzauber und ein paar zusammengebaute Apparate zu testen, braucht er zehn kleine Steinsplitter. Niedere Steinelementare durchstreifen die Hügel unmittelbar westlich."}},faq={{q="Wer bittet um die Steinsplitter?",a="Lotwil Veriatus bittet um Steinsplitter für seine Arbeit im Ödland.",al={"wer vergibt diese quest","questgeber","lotwil veriatus"}},{q="Woran arbeitet Lotwil Veriatus?",a="Lotwil Veriatus fertigt Fesseln der Elementarbindung. Damit werden Magier stärkere Elementare beschwören können.",al={"lotwils projekt","fesseln der elementarbindung","was baut lotwil"}},{q="Warum braucht Lotwil kleine Steinsplitter?",a="Lotwil braucht die Splitter, um Offensivzauber und ein paar zusammengebaute Apparate zu testen.",al={"warum steinsplitter","zweck der splitter","wofür sind die splitter"}},{q="Wo sind die Steinsplitter zu finden?",a="Die Splitter stammen von niederen Steinelementaren in den Hügeln unmittelbar westlich von Lotwil.",al={"wo splitter finden","fundort niederer steinelementare","quelle der steinsplitter"}}},fp="27,147,18.305.0,35.71.0,35.104.0,40.82.0,33.84.0"}
P.entries["quest:711"] = {n="Element-Studie: Fels",s="Lotwil Veriatus ist bereit, größere Stücke zu testen, nachdem sich die kleinen Splitter wie erwartet verhalten haben. Er braucht drei große Steinplatten von Felselementaren.",h="Lotwil Veriatus ist bereit, größere Stücke zu testen, nachdem sich die kleinen Splitter wie erwartet...",kw={"ödland","große steinplatten","lotwil veriatus","felselementare","steinplatten","element-studie: fels"},sec={{t="Größere Stücke",b="Lotwil Veriatus braucht robustere Stücke für seine nächsten Tests. Felselementare haben größere Körper, daher könnten ihre Überreste ausreichend große Platten liefern.\n\nEr schickt Euch weiter nach Westen oder Südosten entlang der Bergränder, um drei große Steinplatten zu sammeln. Vorerst braucht Lotwil Zeit, um die kleineren Stücke zu testen, die Ihr gebracht habt."},{t="Lotwils Hoffnungen",b="Lotwils Zauber wirkten wie vorhergesagt auf die kleineren Stücke. Wenn das nächste Experiment wie erwartet verläuft, werden die Elementare unter seiner Kontrolle alles in den Schatten stellen, was er je zuvor beschworen hat."}},faq={{q="Wer schickt Euch los, um die großen Platten zu besorgen?",a="Lotwil Veriatus, der im Ödland arbeitet, schickt Euch los, um die großen Platten zu sammeln.",al={"wer gibt diese quest","lotwil quest","element-studie questgeber"}},{q="Was ging dieser Bitte voraus?",a="Vor dieser Bitte habt Ihr Lotwil bei der vorherigen Quest „Element-Studie: Fels“ kleine Steinsplitter gebracht.",al={"vorherige quest","vorheriger schritt","was habe ich vorher getan"}},{q="Wo sollt Ihr laut Lotwil die Felselementare finden?",a="Lotwil schickt Euch weiter nach Westen oder Südosten entlang der Bergränder.",al={"wo sind die elementare","fundorte der elementare","wo sind die platten"}},{q="Warum braucht Lotwil größere Steinplatten?",a="Lotwil braucht größere Stücke für seine nächsten Tests. Felselementare haben größere, kräftigere Körper, daher könnten ihre Überreste ausreichend große Stücke liefern.",al={"warum große platten","zweck der platten","lotwils forschungsziel"}}},fp="27,148,13.306.0,14.177.0,36.78.0,30.106.0,50.77.0,40.140.0"}
P.entries["quest:712"] = {n="Element-Studie: Fels",s="Im Ödland braucht Lotwil Veriatus Armschienen von größeren Felselementaren, um seine Fesseln zu beurteilen.",h="Im Ödland braucht Lotwil Veriatus Armschienen von größeren Felselementaren, um seine Fesseln zu beurteilen.",kw={"ödland","armschienen der felsbindung","größere felselementare","kharanos","lotwil veriatus","lucien","oger","servo"},sec={{t="Die Fesseln bemessen",b="Nach den Steinplatten braucht Lotwil Veriatus noch ein letztes Teil von den Elementaren des Ödlands. Armschienen der Felsbindung von größeren Felselementaren sollen ihm helfen, die im Bau befindlichen Fesseln zu beurteilen.\n\nSeine Hellseherei zeigte eine Gruppe im Südwesten, nahe einigen Ogern, wenn die Erinnerung nicht trügt. Er bittet um fünf Armschienen, damit Reserven vorhanden sind, da Servo oft Reagenzien und Forschungsunterlagen verlegt."}},faq={{q="Warum braucht Lotwil die Armschienen?",a="Mit Armschienen der Felsbindung kann Lotwil die Stärke seiner eigenen Fesseln bemessen.",al={"warum armschienen der felsbindung","wozu dienen die armschienen","lotwil armschienen der felsbindung"}},{q="Warum bittet Lotwil um fünf Armschienen?",a="Lotwil bittet um fünf Armschienen, damit Reserven vorhanden sind, da Servo oft Reagenzien und Forschungsunterlagen verlegt.",al={"warum fünf armschienen","wie viele armschienen","warum reserven"}},{q="Wo befinden sich die größeren Felselementare?",a="Lotwils Hellseherei zeigte eine Gruppe im Südwesten, nahe einigen Ogern. Die Hügel um Camp Cagg sind die Heimat der größeren Felselementare.",al={"wo sind felselementare","fundort größerer felselementare","wo armschienen finden"}},{q="Was geschieht mit den zuvor gesammelten Steinplatten?",a="Wenn die Arbeit hier erledigt ist, bringt Lucien die übrigen Platten zurück nach Kharanos, wo sie sich erneut als nützlich erweisen könnten.",al={"was geschah mit den steinplatten","lucien steinplatten","kharanos platten"}}},fp="27,98,20.369.0,33.79.0,37.100.0,46.126.0,50.115.0"}
P.entries["quest:713"] = {n="Kühlaufsätze setzen sich durch",s="Lotwil Veriatus braucht Frostöl für die Fesseln, die seinen herbeigerufenen Freund festhalten. Bro'kin, Lotwils Goblinfreund in Alterac, kann Euch beibringen, es herzustellen.",h="Lotwil Veriatus braucht Frostöl für die Fesseln, die seinen herbeigerufenen Freund festhalten.",kw={"ödland","bro'kin","kühlaufsätze setzen sich durch","frostöl","lotwil veriatus","die ruinen von alterac","fesseln"},sec={{t="Ein unverzichtbares Kühlmittel",b="Lotwil Veriatus sagt, Frostöl bewahre Motoren und Zahnräder vor Überhitzung. Er nennt es ein unvergleichliches Schmiermittel. Es hilft auch magischen Gegenständen, ihre Verzauberungen zu bewahren. Das Öl könnte Lotwils Fesseln genug verstärken, um seinen herbeigerufenen Freund daran zu hindern, alle zu töten."},{t="Bro'kin aus Alterac",b="Bro'kin, Lotwils Goblinfreund, kann Euch beibringen, Frostöl herzustellen. Er verkauft von einem Platz auf der Mauer der alten Stadt in den Ruinen von Alterac aus."},{t="Wenn das Öl eintrifft",b="Als das Öl eintrifft, nennt Lotwil es das perfekte Kühlmittel für die neuen Armschienen. Er schwört, dass all seine Habseligkeiten an Servo gehen, sollten die Verzauberungen kein Jahrhundert lang halten. Lotwil erwartet, dass die Magier der Versammlung voller Ehrfurcht sein werden, wenn das Werk vollendet ist."}},faq={{q="Warum braucht Lotwil Veriatus Frostöl?",a="Frostöl würde Lotwil Veriatus' Fesseln genug verstärken, um seinen herbeigerufenen Freund daran zu hindern, alle zu töten.",al={"warum frostöl","wozu dient frostöl","lotwil öl"}},{q="Wer weiß, wie man Frostöl braut?",a="Bro'kin, Lotwil Veriatus' Goblinfreund, kann Euch beibringen, Frostöl herzustellen. Er verkauft von einem Platz auf der Mauer der alten Stadt in den Ruinen von Alterac aus.",al={"wer lehrt frostöl","wo frostöl lernen","brokin rezept"}},{q="Was ist das Besondere an Frostöl?",a="Lotwil Veriatus sagt, Frostöl bewahre Motoren und Zahnräder vor Überhitzung. Er nennt es ein unvergleichliches Schmiermittel und sagt, es helfe magischen Gegenständen, ihre Verzauberungen zu bewahren.",al={"frostöl eigenschaften","warum ist frostöl gut"}}},fp="21,147,15.262.0,18.134.0,20.254.1,40.111.0,32.143.0,32.165.0"}
P.entries["quest:714"] = {n="Gyro... Was?",s="Im Ödland arbeitet Lotwil Veriatus noch immer an seiner Apparatur. Ihr habt ihm das Frostöl aus Coolant Heads Prevail gebracht, doch ein kleines Teil fehlt noch: ein Gyrochronatom.",h="Im Ödland arbeitet Lotwil Veriatus noch immer an seiner Apparatur.",kw={"ödland","apparatur","coolant heads prevail","gyrochronatom","kharanos","lotwil veriatus"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr selbst ein Gyrochronatom herstellen."},sec={{t="Ein entscheidendes Teil",b="Lotwil Veriatus ist so in seine Arbeit vertieft, dass er Euch dafür lobt, die Aufgabe weit über alle Maßstäbe hinaus erfüllt zu haben. Dann sagt er, Ihr könnt Euch um Arbeit bewerben, wenn Ihr ihn in Kharanos trefft.\n\nHastiges Herumhantieren folgt, während Lotwil versucht, etwas zu greifen. Dann bittet er um ein Gyrochronatom. Das Teil ist klein, aber entscheidend, und damit sollte sich das Projekt abschließen lassen."},{t="Die Übergabe",b="Lotwil Veriatus packt das Gyrochronatom mit einem Schrei, als Ihr es ihm übergebt. Die Arbeit sei beinahe getan, sagt er, und das Projekt habe für ihn oberste Priorität. Sein Versprechen, bald fertig zu sein, dehnt sich von wenigen Minuten auf vielleicht viel länger aus."}},faq={{q="Wer bittet um das Gyrochronatom?",a="Lotwil Veriatus arbeitet im Ödland an einer Apparatur und bittet Euch um ein Gyrochronatom.",al={"wer vergibt gyro was","gyro was questgeber","lotwil veriatus ödland"}},{q="Wofür braucht Lotwil Veriatus das Gyrochronatom?",a="Das Gyrochronatom ist ein kleines, aber entscheidendes Teil von Lotwil Veriatus' Projekt. Damit sollte er die Arbeit abschließen können.",al={"warum gyrochronatom","was baut lotwil"}},{q="Was hat es mit dem Angebot in Kharanos auf sich?",a="Lotwil Veriatus sagt, Ihr könnt Euch um Arbeit bewerben, wenn Ihr ihn in Kharanos trefft.",al={"lotwil kharanos","kharanos arbeitsangebot"}},{q="Wo findet man ein Gyrochronatom?",a="Ingenieure stellen Gyrochronatome her, und Händler für Ingenieursbedarf verkaufen sie.",al={"wie gyrochronatom bekommen","gyrochronatom bezugsquelle","wo gyrochronatom kaufen"}}},fp="13,180,14.358.0,15.227.1,36.93.0,53.125.0,33.72.0,35.67.0"}
P.entries["quest:716"] = {n="Stein ist besser als Stoff",s="Im Ödland hat Lucien Tosselwrench ein Geschenk für Euch, doch seine Arbeit ist noch nicht vollendet. Die zusätzlichen Steine, die Ihr gesammelt habt, sind bereit, aber er braucht noch Patterned Bronze Bracers.",h="Im Ödland hat Lucien Tosselwrench ein Geschenk für Euch, doch seine Arbeit ist noch nicht vollendet.",kw={"ödland","elementarer fels","verzauberte armschienen","lotwil veriatus","lucien tosselwrench","patterned bronze bracers"},ang={["profession:Blacksmithing"]="Als Schmied könnt Ihr die bronzenen Armschienen herstellen, die Lucien braucht."},sec={{t="Ein Dank für Eure Mühen",b="Nach Eurer Arbeit an Lotwils drittem Auftrag „Study of the Elements: Rock“ gibt Lucien Tosselwrench zu, dass Lotwil geizig sein kann. Er möchte es mit feinen verzauberten Armschienen aus den zusätzlichen Steinen, die Ihr gesammelt habt, bei Euch wiedergutmachen. Sie könnten Euch vor der bevorstehenden Gräueltat von Lotwils neuester Erfindung schützen."},{t="Was Lucien braucht",b="Um die Armschienen fertigzustellen, braucht Lucien Patterned Bronze Bracers, wie ein Schmied sie herstellt. Er warnt Euch, nicht lange zu warten. Niemand weiß, was als Nächstes geschieht."}},faq={{q="Wer bietet an, die Armschienen herzustellen?",a="Lucien Tosselwrench bietet im Ödland an, aus Euren zusätzlichen Steinen verzauberte Armschienen herzustellen.",al={"wer vergibt stein ist besser als stoff","questgeber","lucien tosselwrench"}},{q="Warum stellt Lucien diese Rüstung für Euch her?",a="Lucien weiß, dass Lotwil geizig sein kann, und möchte Euch für Eure Mühen entschädigen. Er sagt, die Armschienen könnten Euch auch vor Lotwils neuester Erfindung schützen.",al={"warum armschienen herstellen","luciens beweggrund","lotwil geizig"}},{q="Was braucht Lucien, um die Armschienen fertigzustellen?",a="Lucien braucht Patterned Bronze Bracers, wie ein Schmied sie herstellt, um die verzauberten Armschienen fertigzustellen.",al={"welcher gegenstand wird benötigt","benötigte gegenstände","patterned bronze bracers benötigt"}},{q="Was kommt vor dieser Quest?",a="Sie folgt auf Eure Arbeit an Lotwils drittem Auftrag „Study of the Elements: Rock“.",al={"vorherige quest","voraussetzung für stein ist besser als stoff"}}},fp="26,175,28.310.0,17.155.0,32.92.0,40.147.0,53.100.0,29.75.0"}
P.entries["quest:7162"] = {n="Flaggenjagd",s="In Alterac müssen Rekruten eine Prüfung bestehen, bevor sie der Stormpikegarde beitreten dürfen. Leutnant Haggerdin schickt sie in die Icewing Caverns, um eine dort aufgestellte Schlachtstandarte zu bergen. Der Erfolg bringt eine offizielle Stormpike-Insignie ein und eröffnet den Aufstieg durch die Ränge der Expedition.",h="In Alterac müssen Rekruten eine Prüfung bestehen, bevor sie der Stormpikegarde beitreten dürfen.",kw={"dun baldar","haggerdin","harpyien","icewing caverns","insignie","flaggenjagd","stormpike","banner der sturmlanzen"},ang={["faction:Alliance"]="Die Stormpike-Expedition ist das wichtigste militärische Unternehmen der Allianz in Alterac. Sie verbindet die archäologischen Bestrebungen der Zwerge mit der Verteidigung des Allianzgebiets gegen die Horde.",["race:Dwarf"]="Als Zwerg tretet Ihr einer Garde bei, die überwiegend von Zwergen aus Eisenschmiede geführt wird, die nach Ahnenrelikten und Geheimnissen der Titanen suchen. Diese Prüfung kann Euer erster Schritt in eine der stolzesten Militäreinheiten Eures Volkes sein."},sec={{t="Eine Prüfung des Mutes",b="Die Stormpikegarde kämpft im Alteractal gegen den Frostwolfklan. Leutnant Haggerdin befehligt die Streitkräfte der Allianz von ihrem Lager im Alteracgebirge aus. Bevor Rekruten das Schlachtfeld erreichen, prüft er ihr Geschick und ihre Nervenstärke in den Icewing Caverns südwestlich von Dun Baldar."},{t="Die Icewing Caverns",b="Tief in den Icewing Caverns wartet ein Banner der Sturmlanzen inmitten der gefrorenen Tunnel. Frostharpyien nisten in den eisigen Nischen und greifen unachtsame Eindringlinge an. Ein Rekrut, der das Banner unversehrt zurückbringt, hat gefährliches Gelände durchquert, sich dessen Raubtieren gestellt und unter Druck Disziplin bewahrt."},{t="Die Stormpike-Insignie",b="Kehrt mit der Standarte aus den Höhlen zurück, und Ihr erhaltet die Insignie eines Stormpike-Initianden und einen Platz in den Expeditionsstreitkräften. Haggerdin sagt, die Insignie könne aufgewertet werden, wenn Ihr Euch auf dem Schlachtfeld größere Ehre verdient. Der Eye of Command ist ein fernes Ziel."}},faq={{q="Wer ist Leutnant Haggerdin?",a="Leutnant Haggerdin ist ein Offizier der Allianz im Alteracgebirge, der die Rekrutierung der Stormpikegarde und die Auszeichnung für Verdienste im Feld beaufsichtigt. Er prüft angehende Kämpfer und belohnt ihren Dienst mit militärischen Insignien.",al={"leutnant haggerdin","haggerdin","wer vergibt flaggenjagd"}},{q="Wo liegen die Icewing Caverns?",a="Die Icewing Caverns liegen südwestlich von Dun Baldar, der Festung der Allianz im Alteractal. Ihre gewundenen Tunnel verlaufen unter Eis und Stein.",al={"icewing caverns lage","wo liegen die icewing caverns","fundort des banners"}},{q="Welche Gefahren lauern in den Icewing Caverns?",a="Wilde Eisharpyien leben in den Icewing Caverns. Haggerdin warnt, dass sie Eindringlingen auflauern und ihnen die Kehlen herausreißen.",al={"harpyien","was ist in den icewing caverns","icewing harpyien"}},{q="Warum verlangt die Stormpikegarde diese Prüfung?",a="Die Stormpikegarde führt einen brutalen Krieg gegen die Frostwolforks. Haggerdin prüft Rekruten vor ihrem Einsatz an der Front, damit jeder Soldat, der das Banner trägt, unter widrigen Bedingungen kämpfen kann.",al={"warum flaggenjagd","warum die bannerprüfung ablegen","stormpike aufnahmeprüfung"}},{q="Welche Belohnung gibt es für die bestandene Flaggenjagd?",a="Kehrt mit der Standarte zurück, und Ihr erhaltet die Insignie eines Stormpike-Initianden. Haggerdin kann sie aufwerten, wenn Ihr im Alteractal Ehre gewinnt.",al={"stormpike-insignie","eye of command","flaggenjagd belohnung"}},{q="Wer sind die Frostwölfe, die Haggerdin erwähnt?",a="Der Frostwolfklan ist ein Orkklan, der seit seiner Verbannung vor Jahrzehnten im Alteractal lebt. Die Stormpikegarde sieht seine Mitglieder als feindselige Wilde, die den Interessen und Ausgrabungen der Allianz im Tal im Wege stehen.",al={"frostwolf wilde","wer sind die frostwölfe","frostwolfklan"}}},fx={b9e84d22={q="Was ist der Zweck des Banners der Sturmlanzen in den Höhlen?",a="Das tief in den gefährlichen Eisflügelhöhlen aufgestellte Banner der Sturmlanzen dient als Prüfungsmarkierung für Rekruten, die sich der Expeditionstruppe anschließen wollen. Um es zu beanspruchen, müsst Ihr den bösartigen Harpyien trotzen, die die Höhlen befallen, und den Mut, den Einfallsreichtum und die Entschlossenheit beweisen, die ein wahrer Sturmlanzensoldat benötigt, bevor er jemals das offene Schlachtfeld betritt.",al={"was ist das banner der sturmlanzen","warum banner in den eisflügelhöhlen","zweck banner der sturmlanzen"}}},fp="15,256,20.271.0,19.276.0,22.254.0,28.213.0,30.136.0,46.119.0,47.191.0,53.135.0,47.209.0"}
P.entries["quest:717"] = {n="Erdbeben",s="In Lethlor fürchtet Garek, dass die Lindwürmer ausbrechen könnten. Schwarze Drachen hausen nun dort, und Oger haben das Zeichen der Erde an sich genommen. Deshalb schickt er Euch los, um die Lindwürmer zu befreien und zu töten.",h="In Lethlor fürchtet Garek, dass die Lindwürmer ausbrechen könnten.",kw={"blacklash","garek","hematus","kirin tor","krasus","die lethlorklamm","runensteine","seal of the earth","zeichen der erde","erdbeben"},ang={["faction:Alliance"]="Gareks Bitte gilt Euch als Mitglied der Allianz."},sec={{t="Ein brüchiges Gefängnis",b="In Lethlor fürchtet Garek, dass Blacklash und Hematus aus ihrem Gefängnis entkommen könnten. Schwarze Drachen hausen nun dort, und Oger haben das Zeichen der Erde an sich genommen. Garek sieht keinen sichereren Weg. Die Lindwürmer müssen sterben."},{t="Das Siegel brechen",b="Drei Runensteine halten die Lindwürmer gefangen, und das Zeichen der Erde wird benötigt, um sie zu befreien. Ihr setzt das Zeichen an den Pillars of Amethyst, Opal und Diamond ein und legt dann die Runensteine in das Seal of the Earth. Blacklash und Hematus kommen frei, und Ihr erschlagt sie. Garek bittet Euch, Schattenbringers Bindungen, die Ketten von Hematus und das Zeichen der Erde zurückzubringen."},{t="Nach der Tat",b="Nach dem Tod der Lindwürmer sagt Garek, dass sich die Kirin Tor nicht länger um Lethlors Gefangene sorgen müssen. Er plant, seinem Meister Krasus von seinem Erfolg zu berichten. Krasus wird gewiss erfreut sein."}},faq={{q="Wer sind Blacklash und Hematus?",a="Blacklash und Hematus sind Lindwürmer, die hinter einem Siegel in Lethlor gefangen gehalten werden.",al={"blacklash und hematus","wer sind die lindwürmer","was ist in lethlor gefangen"}},{q="Warum müssen die Lindwürmer getötet werden, statt eingesperrt zu bleiben?",a="Garek kann nicht mehr sicher sein, dass die Lindwürmer gefangen bleiben. Schwarze Drachen hausen nun in Lethlor, und Oger haben das Zeichen der Erde an sich genommen.",al={"warum blacklash töten","warum das gefängnis aufbrechen","warum hematus erschlagen"}},{q="Wie wird das Gefängnis entsiegelt?",a="Setzt das Zeichen der Erde an den Pillars of Amethyst, Opal und Diamond ein. Legt dann die drei Runensteine in das Seal of the Earth.",al={"wie seal of the earth öffnen","wie blacklash beschwören","wie die lindwürmer befreien"}},{q="Was muss zu Garek zurückgebracht werden?",a="Bringt Garek Schattenbringers Bindungen, die Ketten von Hematus und das Zeichen der Erde.",al={"was zu garek zurückbringen","schattenbringers bindungen","ketten von hematus"}},{q="Was kommt vor dieser Quest?",a="Sie folgt auf eine frühere Quest namens Erdbeben.",al={"vorherige quest","voraussetzung für erdbeben"}}},fp="20,175,16.194.0,17.353.0,14.179.1,30.63.0,58.140.0,27.129.0,35.82.0,29.43.0"}
P.entries["quest:718"] = {n="Illusionen",s="Im Ödland hungert Sigrun Ironhews Gruppe nach ihrer Flucht von der Ausgrabungsstätte von Uldaman.",h="Im Ödland hungert Sigrun Ironhews Gruppe nach ihrer Flucht von der Ausgrabungsstätte von Uldaman.",kw={"ödland","camp kosh","ausgrabung","illusionen","oger","sigrun ironhew","vorratskiste","uldaman"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Sigrun Ironhew helfen."},sec={{t="Hunger im Ödland",b="Sigruns Gruppe floh so überstürzt von der Ausgrabungsstätte von Uldaman, dass sie nur wenig mitnahm. Sie ließ Wagen und Vorratskisten zurück, die Oger aus Camp Kosh inzwischen durchwühlt haben. Die Oger nahmen den Karren mit sämtlichen Waffen der Gruppe mit. Seitdem hat die Gruppe keine Nahrung mehr. Sigrun gibt zu, dass die Lage peinlich ist, und bittet Euch, die Vorratskiste zurückzuholen."},{t="Bei Eurer Rückkehr",b="Als Ihr zurückkehrt, gesteht Sigrun, während Eurer Abwesenheit einen Mund voll Sand geschluckt zu haben. Der Abend verspricht bessere Aussichten. Heute Nacht wird die Gruppe losziehen, um Nahrung zu finden und wie Könige zu speisen."}},faq={{q="Wer ist Sigrun Ironhew?",a="Sigrun Ironhew gehört zu einer Gruppe, die überstürzt von der Ausgrabungsstätte von Uldaman floh und nun im Ödland keine Nahrung mehr hat.",al={"sigrun ironhew","wer vergibt illusionen","wer ist sigrun"}},{q="Warum hungert Sigruns Gruppe?",a="Oger nahmen den Karren mit sämtlichen Waffen der Gruppe mit. Seitdem hat Sigruns Gruppe keine Nahrung mehr.",al={"warum hungern sie","warum keine nahrung","sigruns nahrungsproblem"}},{q="Wer nahm die zurückgelassenen Vorräte?",a="Oger aus Camp Kosh haben die zurückgelassene Ausrüstung durchwühlt.",al={"wer stahl die kiste","oger aus camp kosh","wer nahm die waffen"}},{q="Was hofft Sigrun zurückzubekommen?",a="Sigrun hofft, die Vorratskiste zurückzubekommen, die bei der Flucht der Gruppe von der Ausgrabungsstätte zurückblieb.",al={"vorratskiste","was für sigrun zurückholen"}}},fp="7,88,22.360.0,14.186.1,22.116.0,31.97.0,32.73.0,34.94.0"}
P.entries["quest:719"] = {n="Ein Zwerg und sein Werkzeug",s="Ausgrabungsleiter Roggendol entkam einem Angriff auf seine Ausgrabungsstätte und sucht nun seine Glücksspitzhacke. Überall sind Dunkeleisenzwerge, die dem Shadowforge-Klan ähneln.",h="Ausgrabungsleiter Roggendol entkam einem Angriff auf seine Ausgrabungsstätte und sucht nun seine...",kw={"ödland","dunkeleisen","ausgrabung","hammertoe","glücksspitzhacke","roggendol","shadowforge"},sec={{t="Angreifer an der Ausgrabung",b="Dunkeleisenzwerge, die dem Shadowforge-Klan ähneln, griffen die Ausgrabungsstätte an, an der Roggendol arbeitete. Fast alle starben, darunter auch sein Boss Hammertoe. Roggendol kam nur knapp mit dem Leben davon. Die Stätte liegt nördlich von seinem Warteplatz."},{t="Eine Glücksspitzhacke",b="Ausgrabungsleiter Roggendol versucht, die beim Angriff verlorenen Vorräte zurückzubekommen, besonders seine Glücksspitzhacke. Einer der Dunkeleisenzwerge hat sie, doch Roggendol weiß nicht, welcher. Er hofft, dass Ihr helft, und wartet südlich von Hammertoes Dig Site."}},faq={{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol arbeitete an einer Ausgrabungsstätte, die von Dunkeleisenzwergen angegriffen wurde. Er entkam nur knapp und wartet nun südlich von Hammertoes Dig Site.",al={"wer ist roggendol","ausgrabungsleiter roggendol","wer vergibt ein zwerg und sein werkzeug"}},{q="Wer hat das Ausgrabungslager angegriffen?",a="Dunkeleisenzwerge, die dem Shadowforge-Klan ähneln, griffen die Ausgrabungsstätte an.",al={"wer hat die ausgrabung angegriffen","wer hat hammertoe angegriffen","was hat das lager angegriffen"}},{q="Was ist mit Hammertoe geschehen?",a="Hammertoe war Roggendols Boss und gehörte zu denen, die bei dem Angriff getötet wurden.",al={"wer ist hammertoe","lebt hammertoe noch","was ist mit boss hammertoe geschehen"}},{q="Wo befindet sich die Glücksspitzhacke?",a="Roggendol glaubt, dass einer der Dunkeleisenzwerge die Glücksspitzhacke hat, doch er weiß nicht, welcher.",al={"wo ist roggendols glücksspitzhacke","wie die spitzhacke finden","wer hat roggendols spitzhacke"}}},fp="21,147,18.228.0,12.234.0,25.140.0,33.79.0,27.69.0,32.99.0"}
P.entries["quest:72"] = {n="Die Legende von Stalvan",s="In Sturmwind sucht Ihr unter den Habseligkeiten der Flintridges nach Stalvan Dunstmantel. An den Kanälen bergen versiegelte Kisten die Überreste des Hausstands, bewacht von ruhelosen Geistern, die an das Massaker gebunden sind.",h="In Sturmwind sucht Ihr unter den Habseligkeiten der Flintridges nach Stalvan Dunstmantel.",kw={"canals","verwalter folsom","dämmerwald","flintridge","unglückseliger geist","die legende von stalvan","massaker","versiegelte kiste","sturmwind","tilloa"},ang={["class:Priest"]="Als Priester stellt Ihr Euch dem weinenden Unglückseligen Geist in den Stadtkanälen. Seine Qual ist die unschuldiger Seelen, die vor ihrer Zeit ermordet wurden, und er verlangt Frieden vom Licht.",["faction:Alliance"]="Die Tragödie der Flintridges entfaltet sich in Sturmwind, der Hauptstadt des Königreichs, wo Gewalt selbst die behütetsten Adelsgeschlechter zugrunde richten kann."},sec={{t="Nachhall eines Massakers",b="Ihr folgt Stalvans Spur vom Dämmerwald nach Sturmwind. An den Stadtkanälen bewacht Verwalter Folsom die Überreste des Hausstands der Flintridges. Schon sein Vater diente auf dem Anwesen und musste Blut aufwischen, nachdem ein Massaker den gesamten Haushalt dahingerafft hatte. Irgendwie ist Stalvans Name mit diesem Gemetzel verbunden."},{t="Versteigerung eines ruinierten Hauses",b="Das Treuhandvermögen der Flintridges ist aufgebraucht, und königliche Steuereintreiber setzen das Anwesen unter Druck. Gerettete Erbstücke und verpackte Habseligkeiten warten in versiegelten Versandkisten am Kanalufer auf ihre Versteigerung. Ihr durchsucht sie nach Stalvans Spur, bevor sich der verbliebene Familienbesitz unter Sammlern im ganzen Königreich verteilt."},{t="Ein ruheloser Schatten",b="Ein Unglückseliger Geist greift jeden an, der die Kisten der Flintridges anrührt. Das Trauma der Morde haftet an den geretteten Besitztümern der Familie. Viele glauben, die weinende Erscheinung sei der Schatten der jungen Tilloa Flintridge, noch immer an Relikte ihres jäh beendeten Lebens gebunden."}},faq={{q="Wo finde ich Verwalter Folsom?",a="Verwalter Folsom wacht an den Canals in Sturmwind über die Güter der Flintridges, nahe den am Wasser gestapelten Versandkisten.",al={"verwalter folsom fundort","wo ist folsom","wo ist verwalter folsom in sturmwind"}},{q="Was ist der Familie Flintridge zugestoßen?",a="Ein plötzliches Massaker riss den wohlhabenden Haushalt der Flintridges auseinander. Verwalter Folsom erzählt, sein Vater habe danach das Blut aufwischen müssen. Wer dafür verantwortlich war, bleibt unklar.",al={"massaker an den flintridges","was war das massaker","wer hat die familie flintridge getötet"}},{q="Warum sind die Besitztümer der Familie in Kisten am Kanal verpackt?",a="Das Treuhandvermögen der Flintridges war nach der Tragödie aufgebraucht. Auf Druck der Steuereintreiber des Königreichs wurden ihre verbliebenen Habseligkeiten zur Versteigerung in Kisten an den Kanälen verpackt.",al={"warum flintridge-besitz versteigern","warum stehen kisten an den kanälen","treuhandvermögen der flintridges"}},{q="Warum greift ein Geist an, wenn die Kiste geöffnet wird?",a="Das Trauma des Massakers band die Seelen der Opfer an ihre einstigen Besitztümer. Ein Unglückseliger Geist greift an, um die Kisten zu verteidigen, und viele halten ihn für den Schatten von Tilloa Flintridge, einem der ermordeten Kinder.",al={"unglückseliger geist sturmwind","wer ist der unglückselige geist","warum geist in sturmwinds kanälen"}},{q="Wie hängt das mit dem Dämmerwald zusammen?",a="Die Untersuchung begann in Dunkelhain mit der Suche nach Stalvan Dunstmantel. Seine Vergangenheit führte zu seiner Zeit als Hauslehrer der Familie Flintridge in Elwynn und Sturmwind.",al={"stalvan dämmerwald verbindung","warum sind wir für eine dämmerwald-quest in sturmwind","die legende von stalvan verbindung zur stadt"}},{q="Was findet Ihr in der versiegelten Kiste?",a="Die Kiste birgt muffige Erbstücke zwischen verpackten Möbeln und persönlichen Habseligkeiten. Nahe dem Boden findet Ihr eine herausgerissene Seite aus Stalvans Tagebuch, den nächsten Hinweis.",al={"was ist in der kiste","versiegelte kiste hinweis","inhalt der flintridge-kiste"}}},fx={d6eccd2d={q="Warum lässt Verwalter Folsom Euch die Kisten durchsuchen?",a="Verwalter Folsom hat persönlich nicht mehr viel, um das er sich kümmern müsste. Die Stiftung der Familie Flintridge ist völlig versiegt, was ihr verbleibendes Anwesen in Ruinen hinterlässt und ihren letzten Besitz für das Auktionshaus bestimmt, um Steuereintreiber zu befriedigen. Während seine Familie dem Anwesen über Generationen diente – sein Vater hatte das Blut nach dem grausamen Massaker beseitigt –, hat Folsom selbst keinen Grund, die düstere Wahrheit zu verbergen, und gestattet Eurer Neugier einfach, das zu durchwühlen, was übrig geblieben ist.",al={"beweggrund verwalter folsom","warum hilft folsom","warum kisten durchsuchen lassen"}}},fp="21,200,20.302.0,29.320.0,16.262.1,34.133.0,39.167.0,66.167.0,50.210.0,39.167.0,41.155.0"}
P.entries["quest:720"] = {n="Ein Hoffnungsschimmer",s="Hammertoe Grez lebt, und ein Hilferuf in Kreide auf einer zerknitterten Karte bittet Ausgrabungsleiter Roggendol um Hilfe. Die Notiz besagt, dass sie Hammertoe nach Uldaman bringen.",h="Hammertoe Grez lebt, und ein Hilferuf in Kreide auf einer zerknitterten Karte bittet Ausgrabungsleiter...",kw={"ein hoffnungsschimmer","ödland","kreidenotiz","zerknitterte karte","hammertoe grez","ausgrabungsleiter roggendol","uldaman"},sec={{t="Worte in Kreide",b="Hammertoe hinterlässt auf einer zerknitterten Karte einen kurzen Hilferuf in Kreide für Roggendol. Die Notiz besagt, dass sie Hammertoe nach Uldaman bringen, und bittet um Hilfe. Sagt Ausgrabungsleiter Roggendol, dass Hammertoe Grez lebt."}},faq={{q="Was steht auf der zerknitterten Karte?",a="Hammertoes Kreidenotiz ist an Roggendol gerichtet. Sie besagt, dass sie Hammertoe nach Uldaman bringen, und bittet um Hilfe.",al={"was steht in der notiz","kreidenachricht auf karte","text der zerknitterten karte"}},{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol ist derjenige, an den die Notiz gerichtet ist. Findet ihn und sagt ihm, dass Hammertoe Grez lebt.",al={"wer ist roggendol","wohin die zerknitterte karte bringen"}},{q="Wohin wird Hammertoe Grez laut der Nachricht gebracht?",a="Die Nachricht besagt, dass Hammertoe Grez nach Uldaman gebracht wird.",al={"wohin wird hammertoe gebracht","wohin wird grez gebracht"}}},fp="14,141,14.188.0,36.110.0,25.97.0,57.58.0"}
P.entries["quest:723"] = {n="Ein Funken Hoffnung",s="Im Ödland schickt Euch Hammertoe Grez mit seinem Amulett zu Ausgrabungsleiter Roggendol. Roggendol weiß, dass Hammertoe nach den Ursprüngen ihres Volkes suchte, und will die Schriftrollen vor dem Shadowforge-Clan bewahren.",h="Im Ödland schickt Euch Hammertoe Grez mit seinem Amulett zu Ausgrabungsleiter Roggendol.",kw={"a sign of hope","ödland","hammertoe grez","hammertoes amulett","ursprünge","ausgrabungsleiter roggendol","shadowforge"},sec={{t="Ein Amulett für Roggendol",b="Verwundet im Ödland bittet Euch Hammertoe Grez, sein Amulett zu Roggendol zu bringen. Er vertraut darauf, dass Roggendol weiß, was zu tun ist. Hammertoe suchte nach den Ursprüngen ihres Volkes und wollte die Pläne des Shadowforge-Clans durchkreuzen. Der Clan darf die Schriftrollen nicht bekommen."},{t="In Roggendols Händen",b="Als Roggendol Hammertoes Amulett erhält, sagt er, die Stimmung sei besser gewesen, als Hammertoe noch für tot gehalten wurde. Die Gewissheit vertieft seinen Schmerz nur noch. Roggendol nennt das Amulett Hammertoes Lebenswerk und schwört, dass sein Tod nicht vergebens sein wird."}},faq={{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol ist derjenige im Ödland, dem Ihr Hammertoes Amulett bringen sollt. Er weiß, wonach Hammertoe suchte.",al={"ausgrabungsleiter roggendol","wer ist roggendol","wo ist roggendol"}},{q="Was versucht Hammertoe Grez zu verhindern?",a="Hammertoe wollte die Pläne des Shadowforge-Clans durchkreuzen, der die Schriftrollen nicht in die Hände bekommen darf.",al={"hammertoes ziel","shadowforge schriftrollen","warum shadowforge aufhalten"}},{q="Wonach suchte Hammertoe Grez?",a="Hammertoe suchte nach den Ursprüngen ihres Volkes.",al={"hammertoe ursprünge","wonach suchte hammertoe"}},{q="Zu welcher Questreihe gehört dieser Schritt?",a="Dieser Schritt gehört zu der Questreihe, die mit A Sign of Hope begann.",al={"ein funken hoffnung questreihe","a sign of hope questreihe"}}},fp="17,194,20.238.0,17.232.1,25.121.0,38.87.0,32.50.0,33.62.0"}
P.entries["quest:724"] = {n="Ein Funken Hoffnung",s="Im Ödland schickt Euch Ausgrabungsleiter Roggendol mit Hammertoes Amulett nach Eisenschmiede. Historiker Karnik und Hammertoe suchten gemeinsam nach Uldamans verlorenen Artefakten. Roggendol vermutet, dass die Shadowforge herausfanden, dass die beiden mehr wussten, als sie zugaben.",h="Im Ödland schickt Euch Ausgrabungsleiter Roggendol mit Hammertoes Amulett nach Eisenschmiede.",kw={"ödland","hammertoe","hammertoes amulett","historiker karnik","eisenschmiede","ein funken hoffnung","ausgrabungsleiter roggendol","shadowforge","uldaman"},sec={{t="Eine Nachricht für Eisenschmiede",b="Ausgrabungsleiter Roggendol schickt Euch zu Historiker Karnik in Eisenschmiede. Erzählt Karnik, was mit Hammertoe geschehen ist, und legt das Amulett in seine Hände. Karnik wird entscheiden, was als Nächstes zu tun ist."},{t="Karniks Begrüßung",b="Historiker Karnik will sich keine weitere Reisegeschichte anhören, bis er das Amulett sieht. Dann stellt er seine Trauer um Hammertoe zurück und ruft Hammertoes Geist herbei, um Euch den Wert des Amuletts zu zeigen."}},faq={{q="Wer vergibt diese Quest?",a="Ausgrabungsleiter Roggendol im Ödland schickt Euch mit Hammertoes Amulett nach Eisenschmiede.",al={"wer vergibt ein funken hoffnung","ein funken hoffnung questgeber","wo beginnt ein funken hoffnung"}},{q="Wo befindet sich Historiker Karnik?",a="Historiker Karnik befindet sich in Eisenschmiede.",al={"wo ist karnik","historiker karnik standort","karnik eisenschmiede"}},{q="Warum wurde Historiker Karnik ausgewählt?",a="Karnik und Hammertoe suchten gemeinsam nach Uldamans verlorenen Artefakten, daher vertraut Roggendol darauf, dass Karnik weiß, was als Nächstes zu tun ist.",al={"warum das amulett zu karnik schicken","karniks verbindung"}},{q="Was kommt nach dieser Quest?",a="Karniks Geschichte geht mit Passing Word of a Threat weiter.",al={"nächste quest nach ein funken hoffnung","was folgt auf ein funken hoffnung"}}},fp="17,228,23.171.0,16.190.1,22.81.0,34.33.0,32.111.0,28.55.0"}
P.entries["quest:725"] = {n="Kunde über die Bedrohung breitet sich aus",s="Karnik schickt Euch mit einer versiegelten Nachricht zu Berater Belgrum. Berichtet Belgrum, was Ihr mitangesehen habt, und fragt nach dem weiteren Vorgehen, während Karnik bei Hammertoes Geist nach Antworten sucht.",h="Karnik schickt Euch mit einer versiegelten Nachricht zu Berater Belgrum.",kw={"berater belgrum","ödland","hammertoe","historiker karnik","eisenschmiede","kunde über die bedrohung breitet sich aus","shadowforge"},sec={{t="Kunde für Berater Belgrum",b="Historiker Karnik braucht Euch, um Berater Belgrum schnell zu erreichen. Berichtet ihm, was Ihr mitangesehen habt, und fragt, wie er weiter vorgehen möchte. Die versiegelte Nachricht erklärt Näheres.\n\nUnterdessen spricht Karnik mit Hammertoes Geist und hofft zu erfahren, wie sich den Machenschaften der Shadowforge im Ödland ein Ende setzen lässt. Er kann nur beten, dass Hammertoe etwas weiß, das helfen wird."}},faq={{q="Wer schickt Euch zu Berater Belgrum?",a="Historiker Karnik gibt Euch eine versiegelte Nachricht und bittet Euch, Berater Belgrum so schnell wie möglich zu finden.",al={"wer startet kunde über die bedrohung breitet sich aus","wer vergibt kunde über die bedrohung breitet sich aus","karnik quest"}},{q="Was möchte Karnik von Berater Belgrum?",a="Karnik möchte, dass Ihr Belgrum berichtet, was Ihr mitangesehen habt, und fragt, wie er weiter vorgehen möchte. Die Nachricht erklärt Näheres.",al={"warum belgrum aufsuchen","zweck der nachricht für belgrum","warum die nachricht schicken"}},{q="Was tut Historiker Karnik, während Ihr die Nachricht überbringt?",a="Während Ihr die Nachricht überbringt, spricht Karnik mit Hammertoes Geist und hofft zu erfahren, wie sich die Shadowforge im Ödland aufhalten lassen.",al={"was tut karnik","karniks plan","historiker karnik ödland"}},{q="Welche Quest kommt vor Kunde über die Bedrohung breitet sich aus?",a="Kunde über die Bedrohung breitet sich aus folgt auf Prospect of Faith, bei der Ihr Hammertoes Amulett zu Karnik in Eisenschmiede bringt.",al={"kunde über die bedrohung voraussetzung","kunde über die bedrohung breitet sich aus vorherige quest","vorherige quest"}}},fp="24,162,24.336.0,33.100.0,43.108.0,58.124.0,49.109.0"}
P.entries["quest:726"] = {n="Kunde über die Bedrohung breitet sich aus",s="Im Ödland schickt Belgrum Euch mit dem Befehl des Königs zu Karnik zurück, rasch gegen die Schattenschmiede vorzugehen.",h="Im Ödland schickt Belgrum Euch mit dem Befehl des Königs zu Karnik zurück, rasch gegen die Schattenschmiede...",kw={"festung angor","ödland","belgrum","karnik","schattenschmiede","uldaman"},sec={{t="Belgrums Antwort",b="Belgrum liest Karniks Notiz bis zum Ende. Bei der unheilvollen Kunde weiten sich seine Augen. Er schickt Euch mit dem Befehl des Königs zu Karnik zurück: Handelt nach den vorliegenden Erkenntnissen rasch und entschlossen. Die Aktivitäten der Schattenschmiede im Ödland müssen aufhören."},{t="Karniks Erwiderung",b="Karnik versteht die Dringlichkeit als die des Königs selbst und hat einen Plan bereit. Die Schattenschmiede operiert von der Festung Angor aus. Ein Schlag dort kann ihre Arbeit in Uldaman verlangsamen."}},faq={{q="Wer schickt Euch zu Karnik zurück?",a="Berater Belgrum schickt Euch zurück, nachdem er Karniks Notiz gelesen hat. Ihr überbringt den Befehl des Königs, rasch und entschlossen zu handeln.",al={"wer gibt den befehl","belgrums befehle","königliche autorität ödland"}},{q="Was will Belgrum gegen die Schattenschmiede unternehmen lassen?",a="Belgrum will, dass Karnik rasch und entschlossen handelt, um die Aktivitäten der Schattenschmiede im Ödland zu beenden.",al={"was will belgrum","schattenschmiede ödland befehl"}},{q="Was geschah zuvor?",a="Ihr habt Karniks versiegelte Notiz im früheren „Kunde über die Bedrohung breitet sich aus“ zu Berater Belgrum gebracht, nach den Schritten von Prospect of Faith.",al={"vorheriger schritt","quest vor kunde über die bedrohung breitet sich aus","vorgeschichte ödland"}}},fp="24,113,16.229.0,14.154.1,29.119.0,50.99.0,22.127.0"}
P.entries["quest:727"] = {n="Auf nach Eisenschmiede zu 'Yagyins Zusammenstellung'",s="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen nach Eisenschmiede. In einem Laden in der Forlorn Cavern soll Gerrig Knochengriff Euch für einen der Leute halten, vor denen Theldurin floh, damit Ihr ihn nach Yagyins Zusammenstellung fragen könnt.",h="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen nach Eisenschmiede.",kw={"ödland","forlorn cavern","gerrig knochengriff","eisenschmiede","siegelzeichen des hammers","theldurin der verirrte","yagyins zusammenstellung"},sec={{t="Ein vor langer Zeit geschriebenes Buch",b="Die Tafel hat Theldurin viel gelehrt, doch Fragen bleiben offen. Yagyin verfasste vor langer Zeit eine Zusammenstellung, und die Leute, vor denen Theldurin floh, bewahren an vielen Orten Abschriften auf. Ihre Gelehrtesten studieren sie. Theldurin glaubt, dass ihr gewaltiges Wissen Schutz bieten kann, und möchte deshalb, dass Ihr sie zurückbringt."},{t="Der Laden in der Forlorn Cavern",b="Gerrig Knochengriff betreibt einen Laden in der Forlorn Cavern von Eisenschmiede. Theldurin gibt Euch das Siegelzeichen des Hammers, um es Gerrig zu zeigen. Dann sollte Gerrig Euch für einen der Leute halten, vor denen Theldurin floh. Fragt ihn nach Yagyins Zusammenstellung."},{t="Gerrigs Begrüßung",b="Gerrig Knochengriff warnt Euch, darauf zu achten, was Ihr im Laden berührt. Wissen kann tödlich sein. Wenn Ihr das Siegelzeichen zeigt, begrüßt Gerrig Euch als Bruder oder Schwester und preist jene, die in der Tiefe weilen."}},faq={{q="Warum will Theldurin Yagyins Zusammenstellung haben?",a="Die Tafel verrät Theldurin viel, lässt jedoch Fragen offen. Yagyins vor langer Zeit verfasste Zusammenstellung birgt gewaltiges Wissen, das Schutz bieten kann. Theldurin möchte, dass Ihr sie zurückbringt.",al={"warum wird yagyins zusammenstellung gebraucht","was ist yagyins zusammenstellung","zweck von yagyins zusammenstellung"}},{q="Wo ist Gerrig Knochengriff?",a="In der Forlorn Cavern von Eisenschmiede, wo er einen Laden betreibt.",al={"wo ist gerrig knochengriff","gerrig knochengriff standort","wer ist gerrig"}},{q="Wofür wird das Siegelzeichen des Hammers verwendet?",a="Theldurin gibt Euch das Siegelzeichen des Hammers, um es Gerrig Knochengriff zu zeigen. Er möchte, dass Gerrig Euch für einen der Leute hält, vor denen Theldurin floh.",al={"was bewirkt das siegelzeichen","verwendung des siegelzeichens des hammers","warum das siegelzeichen verwenden"}},{q="Wo gehört dies in die Questreihe?",a="Es folgt auf Solution to Doom bei Theldurin dem Verirrten. Die Questreihe geht mit dem nächsten Schritt weiter.",al={"was kommt vor auf nach eisenschmiede zu 'yagyins zusammenstellung'","reihenfolge der questreihe yagyin"}}},fp="32,203,23.272.0,30.214.0,17.185.1,40.186.0,25.53.0,41.134.0,33.92.0"}
P.entries["quest:728"] = {n="Auf nach Unterstadt zu 'Yagyins Zusammenstellung'",s="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen für Bewahrer Bel'dugur in die Unterstadt von Lordaeron. Er will, dass der Bewahrer Euch für einen der Leute hält, vor denen er floh, und bittet Euch, Yagyins Zusammenstellung zu finden.",h="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen für Bewahrer Bel'dugur in die Unterstadt von...",kw={"ödland","bel'dugur","zusammenstellung","hammer","siegelzeichen","theldurin","unterstadt","yagyin"},sec={{t="Ein vor Urzeiten verfasstes Buch",b="Die Tafel hat Theldurin vieles beantwortet, doch Fragen bleiben offen. Yagyin verfasste vor Urzeiten eine Zusammenstellung, und die Leute, vor denen Theldurin floh, bewahren an vielen Orten Abschriften davon auf. Ihre Gelehrtesten studieren die Seiten. Theldurin glaubt, dass das umfassende Wissen darin sie beschützen kann, und will deshalb, dass Ihr die Zusammenstellung zurückbringt."},{t="Der Bewahrer in Unterstadt",b="Bewahrer Bel'dugur wartet in der Unterstadt von Lordaeron. Theldurin gibt Euch das Siegelzeichen des Hammers, damit Ihr es dem Bewahrer zeigt, der Euch für einen der Leute halten soll, vor denen Theldurin floh. Fragt Bel'dugur nach der Zusammenstellung."},{t="Ein Wort der Vorsicht",b="Bewahrer Bel'dugur begrüßt Euch als eifrigen Sucher der Sammlung. Wissen, so warnt der Bewahrer, verleiht den Starken Macht, treibt die Schwachen jedoch in den Wahnsinn. Nachdem Ihr das Siegelzeichen vorgezeigt habt, mahnt Bel'dugur Euch, mit solchen Zeichen diskret umzugehen. Einige zweifeln an der Rechtschaffenheit ihres Gelöbnisses, während andere sie scheitern sehen wollten, wenn sie davon wüssten. Wer das Gelöbnis teilt, muss vorsichtig, wachsam und geduldig sein."}},faq={{q="Wer schickt Euch nach Unterstadt?",a="Theldurin der Verirrte schickt Euch los, um Bewahrer Bel'dugur zu finden, und gibt Euch das Siegelzeichen des Hammers mit.",al={"wer startet diese quest","wer vergibt to the undercity for yagyin's digest","questgeber"}},{q="Wozu dient das Siegelzeichen des Hammers?",a="Theldurin gibt Euch das Siegelzeichen des Hammers, damit Ihr es Bewahrer Bel'dugur zeigt und dieser Euch für einen der Leute hält, vor denen Theldurin floh.",al={"verwendung des siegelzeichens des hammers","warum brauche ich das siegelzeichen","was bewirkt das siegelzeichen"}},{q="Was ist Yagyins Zusammenstellung?",a="Yagyins Zusammenstellung ist ein Buch, das Yagyin vor Urzeiten verfasste. Theldurin sagt, es berge umfassendes Wissen, das die Gelehrtesten unter den Leuten studieren, vor denen er floh.",al={"was ist yagyins zusammenstellung","wer ist yagyin","yagyins buch"}},{q="Wo ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur befindet sich in der Unterstadt von Lordaeron.",al={"bewahrer bel'dugur aufenthaltsort","wo ist bewahrer bel'dugur zu finden","beldugur unterstadt"}},{q="Was kam davor?",a="Solution to Doom kam davor.",al={"vorherige quest","was kommt davor","solution to doom zusammenhang"}}},fp="36,197,23.281.0,27.197.0,17.375.1,31.101.0,36.135.0,24.142.0,26.50.0,22.34.0"}
P.entries["quest:729"] = {n="Der geistesabwesende Ausgrabungsleiter",s="An der südlichen Dunkelküste überrennen feindselige Steingolems eine Ausgrabungsstätte, und Archäologin Hollee sucht in Auberdine Hilfe. Sie fürchtet um Ausgrabungsleiter Wirrbart, ihren älteren Kollegen, dessen Forschung ihn oft blind für tödliche Gefahren macht.",h="An der südlichen Dunkelküste überrennen feindselige Steingolems eine Ausgrabungsstätte, und Archäologin...",kw={"auberdine","dunkelküste","forscherliga","fossil","golems","greywhisker","hollee","wirrbart"},ang={["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie Forscher aus Eisenschmiede die fremdartigen uralten Länder ihrer Nachtelfenverbündeten in Kalimdor erforschen.",["race:Dwarf"]="Als Zwerg erlebt Ihr Wirrbarts besessene Neugier: Für ein noch nicht katalogisiertes Fossil riskiert er Leib und Leben."},sec={{t="Eine gefährliche Ausgrabung",b="Archäologin Hollee kam mit der Forscherliga über das Meer. Meister Greywhisker schickte sie zu Ausgrabungsleiter Wirrbart in die Lehre, dessen Entdeckungen ihn in den akademischen Kreisen von Eisenschmiede berühmt gemacht hatten. Die Liga entsandte die beiden, um uralte Ruinen entlang der ungezähmten Küste der Dunkelküste zu untersuchen. Als sie die vermeintlichen Überreste einer großen Zivilisation freilegten, brachen gewalttätige Steingolems aus der Erde hervor und überrannten die Stätte."},{t="Blind für das Unheil",b="In Panik floh Hollee durch die Nacht nach Auberdine, dem Hafen der Nachtelfen, um Hilfe zu suchen. Wirrbart bemerkte die Gefahr kaum. In seine Relikte vertieft, blieb der betagte Ausgrabungsleiter zwischen den Trümmern, während schwerfällige Konstrukte sein Lager umringten. Wer ihn südlich von Auberdine erreicht, findet ihn über fehlende Steinbürsten und verlegte Fossilien murrend vor."}},faq={{q="Wer ist Ausgrabungsleiter Wirrbart?",a="Ausgrabungsleiter Wirrbart ist ein gefeierter zwergischer Forscher der Forscherliga von Eisenschmiede. Seine Entdeckungen machten ihn in zwergischen Gelehrtenkreisen berühmt, doch wertvolle Relikte können ihn blind für Gefahren in seiner Nähe machen.",al={"wirrbart","ausgrabungsleiter wirrbart geschichte","wer ist der ausgrabungsleiter"}},{q="Warum ist Archäologin Hollee in Auberdine?",a="Meister Greywhisker beauftragte Hollee, Wirrbart zu unterstützen. Als gefährliche Golems an ihrer Ausgrabungsstätte aus der Erde stiegen, floh sie in Panik nach Norden nach Auberdine, um Hilfe für eine Rettung zu suchen.",al={"archäologin hollee","hollee auberdine","warum floh hollee"}},{q="Was gruben die Zwerge an der Dunkelküste aus?",a="Die Zwerge legten unter der Dunkelküste die vermeintlichen Überreste einer großen uralten Zivilisation frei. Bevor Golems die Stätte überrannten, hatte Wirrbart ein geheimnisvolles Fossil und steinerne Artefakte entdeckt.",al={"was grub wirrbart aus","dunkelküste ausgrabungsstätte","wirrbart fossil"}},{q="Wo ist Ausgrabungsleiter Wirrbart zu finden?",a="Ausgrabungsleiter Wirrbart befindet sich an der Ausgrabungsstätte an der südlichen Dunkelküste, zwischen uralten Ruinen südlich von Auberdine. Gefährliche Golems umringen sein Lager, während er nach seiner Steinbürste und seinem Fossil sucht.",al={"wo ist wirrbart","wirrbart aufenthaltsort","ausgrabungsleiter wirrbart finden"}},{q="Wer schickte diese Expedition an die Dunkelküste?",a="Die Forscherliga entsandte die Expedition auf Befehl von Meister Greywhisker aus Eisenschmiede. Greywhisker schickte Hollee zu Wirrbart in die Lehre, damit sie die uralten Ruinen der Dunkelküste untersuchte.",al={"wer schickte hollee","meister greywhisker","forscherliga dunkelküste"}},{q="Ist Wirrbart wirklich in Gefahr?",a="Ja. Feindselige Golems durchstreifen die Ruinen um Wirrbart, doch er ist blind für die Gefahr. Er konzentriert sich darauf, seine Funde zu katalogisieren, und fragt sich, wo seine Werkzeuge und seine Gehilfin geblieben sind.",al={"ist wirrbart tot","wirrbart am leben","wirrbart helfen"}}},fx={["90475777"]={q="Warum möchte Archäologin Hollee, dass dies erledigt wird?",a="Hollee war begeistert, unter Ausgrabungsleiter Wirrbart zu lernen, einem berühmten Forscher der Forscherliga von Eisenschmiede. Doch als feindselige Golems aus der Ausgrabungsstätte brachen, ließ ihn seine tiefe Zerstreutheit die Gefahr völlig vergessen. Hollee floh nach Auberdine, um Verstärkung zu holen, in der Angst, dass ihr Mentor getötet wird, wenn ihn niemand aus den Ruinen holt.",al={"warum braucht hollee hilfe","beweggrund hollee","warum nach wirrbart suchen"}},["1b9bcac6"]={q="Warum bittet Hollee Euch, nach Wirrbart zu sehen, anstatt selbst zu gehen?",a="Hollee entkam der Ausgrabungsstätte nur knapp mit dem Leben, als sich die Steingolems erhoben. Verängstigt und ohne die kampferprobten Fähigkeiten, sich allein durch die feindseligen Konstrukte zu kämpfen, muss sie sicher in Auberdine bleiben und sich auf fähige, vorbeikommende Abenteurer verlassen, die sich zurück in das Getümmel wagen und nach ihrem Mentor sehen.",al={"warum ich hollee","warum geht hollee nicht zurück","warum hilft auberdine nicht"}}},fp="28,221,14.427.0,17.354.0,28.215.0,41.166.0,46.205.0,40.191.0,38.186.0,30.178.0"}
P.entries["quest:730"] = {n="Ärger in Dunkelküste?",s="In Darnassus braucht Chefarchäologe Grauflaum Hilfe bei der Suche nach seiner vermissten Mannschaft. Sein Hilferuf führt Euch über das Meer nach Auberdine, wo die Zwergenexpedition an der wilden Küste von Dunkelküste in Schwierigkeiten geriet.",h="In Darnassus braucht Chefarchäologe Grauflaum Hilfe bei der Suche nach seiner vermissten Mannschaft.",kw={"archäologe","auberdine","dunkelküste","darnassus","explorers league","grauflaum","hollee","ärger in dunkelküste"},ang={["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie die Zusammenarbeit zwischen Eisenschmiede und Darnassus wächst und Teldrassil mit dem Festland Kalimdors verbindet.",["race:Dwarf"]="Als Zwerg seht Ihr, wie die Tradition der Explorer’s League, Titanenwissen und uralte Geschichte zu erforschen, auf neue Kontinente getragen wird.",["race:NightElf"]="Als Nachtelf betrachtet Ihr die Zwergengräber, die in den Küstenruinen Eurer Vorfahren eintreffen, vielleicht mit vorsichtiger Belustigung oder stiller Sorge."},sec={{t="Eine schweigende Expedition",b="Darnassus ist die prächtige Hauptstadt der Nachtelfen und Heimat von Zwergenforschern aus Eisenschmiede, die Kalimdors uralte Geheimnisse erforschen. Chefarchäologe Grauflaum schickte eine Ausgrabungsgruppe über das Wasser nach Dunkelküste, um uralte Artefakte zu bergen. Wochen sind vergangen, ohne eine Nachricht oder einen Fortschrittsbericht. Grauflaum fürchtet, dass seine Mannschaft vor Ort von Gefahren ereilt wurde."},{t="Freigelegte Bedrohungen",b="Grauflaum beklagt, dass viele in der Allianz die Zwergenarchäologie als exzentrisches Hobby abtun. Entdeckungen in Khaz Modan haben seine Kollegen überzeugt, dass eine furchterregende uralte Macht Azeroth von Lordaeron bis Kalimdor bedroht. Deshalb ist die Arbeit in den Ruinen von Dunkelküste mehr als reine Forschung. Die Expedition will historische Kataklysmen und die tief verwurzelten Gefahren verstehen, die unter uralter Erde begraben liegen."},{t="Kontakt in Auberdine",b="Ihr segelt von Teldrassil über die Meerenge nach Auberdine, dem Zufluchtsort an der Küste. Archäologin Hollee wartet in der Stadt, erleichtert darüber, dass Grauflaum Hilfe geschickt hat. Hollee sagt, dass die Expedition in großer Not ist. Weiter die Küste hinunter geriet die Mannschaft bei der Suche nach uralten Relikten in Schwierigkeiten."}},faq={{q="Wer vergibt die Quest „Ärger in Dunkelküste?“?",a="Chefarchäologe Grauflaum bittet in Darnassus um Hilfe und sucht Reisende, die nach seiner vermissten Mannschaft sehen.",al={"wer vergibt ärger in dunkelküste","questgeber ärger in dunkelküste","wo gibt es ärger in dunkelküste"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Reist von Darnassus über das Meer nach Auberdine in Dunkelküste, wo Archäologin Hollee wartet.",al={"wohin gehen","abgabeort","bei wem abgeben"}},{q="Warum sind Zwergenarchäologen in Darnassus und Dunkelküste?",a="Nach Entdeckungen in Khaz Modan begannen Zwergenforscher, uralte Stätten in ganz Kalimdor nach Hinweisen auf uralte Mächte zu untersuchen, die Azeroth bedrohen.",al={"warum sind zwerge in darnassus","zwerge in dunkelküste","zwergenarchäologie kalimdor"}},{q="Was geschieht, nachdem ich Archäologin Hollee gefunden habe?",a="Ein Gespräch mit Archäologin Hollee in Auberdine führt zu „The Absent Minded Prospector“. Diese Folgequest fordert Euch auf, in der Wildnis von Dunkelküste nach Ausgrabungsleiter Wirrbart zu suchen.",al={"what comes next","folgequest","nächste quest"}},{q="Warum hat sich die Ausgrabungsmannschaft nicht gemeldet?",a="Die Mannschaft stieß bei ihrer Arbeit in Dunkelküste auf unerwartete Gefahren und Rückschläge. Ihre Mitglieder wurden voneinander getrennt, und die Verbindung nach Darnassus brach ab.",al={"was geschah mit der ausgrabung","warum sind sie verschwunden","mannschaft vermisst"}},{q="Auf welche drohende Gefahr bezieht sich Grauflaum?",a="Grauflaum verweist auf Entdeckungen in Khaz Modan, die auf eine uralte, allgegenwärtige Gefahr tief in Azeroths historischen Ruinen hindeuten.",al={"welche uralte bedrohung","grauflaums warnung","khaz modan bedrohung"}}},fx={["0c1ca2fe"]={q="Warum möchte Chefarchäologe Grauflaum, dass dies erledigt wird?",a="Chefarchäologe Grauflaum hat seit Wochen nichts von seinem Ausgrabungsteam in Dunkelküste gehört. Nach bedrohlichen Entdeckungen in Khaz Modan, die eine große und uralte Macht enthüllen, die ganz Azeroth bedroht, kann er es sich nicht leisten, den Kontakt zu seinen Forschern zu verlieren, insbesondere wenn deren Arbeit entscheidend ist, um diese drohenden Gefahren aufzudecken.",al={"beweggrund grauflaum","warum nach dunkelküste schicken","warum ausgrabungsteam finden"}}},fp="21,205,19.359.0,16.403.0,20.286.1,42.110.0,45.102.0,58.154.0,48.175.0,45.147.0,48.134.0"}
P.entries["quest:731"] = {n="Der geistesabwesende Ausgrabungsleiter",s="In den südlichen Ruinen der Dunkelküste setzt Ausgrabungsleiter Wirrbart seine Grabung fort und hofft auf einen wertvollen Fund für die Forscherliga. Feindselige Troggs und seine Vergesslichkeit machen die Suche gefährlich, und seine Assistentin in Auberdine muss erfahren, dass er in Sicherheit ist.",h="In den südlichen Ruinen der Dunkelküste setzt Ausgrabungsleiter Wirrbart seine Grabung fort und hofft auf...",kw={"auberdine","dunkelküste","eskorte","ausgrabung","forscherliga","fossil","hollee","wirrbart","troggs"},ang={["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr die wissenschaftlichen und diplomatischen Beziehungen zwischen der zwergischen Forscherliga und den Nachtelfen von Teldrassil, indem Ihr Wirrbart helft und seine Funde bewahrt.",["race:Dwarf"]="Für Zwerge verkörpert Wirrbart die glühende Leidenschaft und den Starrsinn der Forscherliga. Seine Hingabe an das uralte Wissen über die Titanen macht ihn blind für die Gefahren um ihn herum.",["race:NightElf"]="Für Euch als Nachtelf mag die zwergische Grabung in der Dunkelküste die Skepsis Eures Volkes bestätigen: Wirrbarts Ausgrabung legte eine Horde gewalttätiger Troggs unter heiligem Boden frei."},sec={{t="Eine gefährliche Ausgrabung",b="Weit im Süden der Dunkelküste liegt Wirrbarts Grabung inmitten uralter Ruinen. Zwergische Ausgräber stießen dort bei ihrer Suche auf Troggs, die die Arbeiter vertrieben und ihr Lager belagerten. Wirrbart will nicht mit leeren Händen nach Auberdine zurückkehren. Er begibt sich in Gefahr, um ein Fossil zu bergen, und hofft, damit die Kosten der Expedition vor der Forscherliga zu rechtfertigen."},{t="Verworrene Erinnerungen und Troggüberfälle",b="Wirrbart bei der Ausgrabung zu beschützen ist gefährlich und frustrierend. Er zieht seine Kreise über das Gelände, verwechselt Pinsel mit Fossilien und stolpert an Gerüsten und verlassenen Zelten vorbei. Jeder Halt lockt aggressive Troggs aus den schattigen Winkeln des Steinbruchs hervor. Nachdem Reisende Welle um Welle der unterirdischen Unholde bezwungen haben, erinnert sich Wirrbart daran, wo sein wertvoller Fund ist: Er hat das Fossil bereits Hollee gegeben. Er kehrt vergnügt an die Arbeit zurück."}},faq={{q="Wer ist Ausgrabungsleiter Wirrbart?",a="Ausgrabungsleiter Wirrbart ist ein erfahrener Feldforscher der zwergischen Forscherliga. Er ist in der Dunkelküste stationiert und wurde entsandt, um uralte Küstenruinen auszugraben, doch seine extreme Zerstreutheit bringt ihn oft in Lebensgefahr.",al={"wirrbart","wer ist der ausgrabungsleiter","der geistesabwesende ausgrabungsleiter"}},{q="Warum ist Wirrbart noch an der Grabungsstätte?",a="Wirrbart weigert sich, ohne handfesten Beweis für seine Arbeit nach Darnassus zurückzukehren. Er will ein geheimnisvolles Fossil bergen, um es der Forscherliga vorzulegen, bevor er das Lager aufgibt.",al={"warum an der grabung bleiben","warum ist wirrbart dort","warum ist er nicht geflohen"}},{q="Woher kamen die Troggs?",a="Wirrbarts Team grub tief in die Erde und stieß in unterirdische Hohlräume vor, die von Troggs bewohnt waren. Die primitiven Kreaturen strömten nach oben und überrannten die Maschinen, Zelte und Arbeiter.",al={"warum gibt es troggs in der dunkelküste","troggs der dunkelküste","troggs an der grabungsstätte"}},{q="Wer ist Archäologin Hollee?",a="Archäologin Hollee ist Wirrbarts Kollegin und Assistentin in Auberdine. Verzweifelt über die lange Abwesenheit ihres Mentors und mit seiner Vergesslichkeit vertraut, bittet sie Reisende, ihn zu finden und seine sichere Rückkehr zu gewährleisten.",al={"hollee","archäologin hollee","wirrbarts assistentin"}},{q="Was geschieht, nachdem das Fossil gefunden wurde?",a="Nachdem Ihr Wirrbart bei der Suche auf dem Grabungsgelände geholfen habt, berichtet Archäologin Hollee in Auberdine, dass er in Sicherheit ist.",al={"questfortsetzung","was als nächstes","nach wirrbarts eskorte"}}},fx={["6ea255c4"]={q="Warum möchte Ausgrabungsleiter Wirrbart das Fossil finden?",a="Wirrbart steht unter dem Druck des Kapitels der Forscherliga in Darnassus, zu beweisen, dass er tatsächlich Fortschritte bei der Ausgrabungsstätte gemacht hat. Obwohl er schrecklich verwirrt und geistesabwesend ist, weiß er, dass er greifbare Ergebnisse – insbesondere das geheimnisvolle Fossil und schriftliche Funde – vorzeigen muss, um seine Expedition zu rechtfertigen und seine Vorgesetzten zufrieden zu stellen.",al={"beweggrund wirrbart","warum nach fossil suchen","warum fossil wirrbart finden"}},["4634f683"]={q="Warum braucht Wirrbart Eure Hilfe bei der Suche in der Ausgrabung?",a="Die Ausgrabungsstätte wurde von feindseligen Troggs überrannt, und Wirrbart ist ein zerstreuter Forscher, kein erfahrener Krieger. Er ist völlig darauf fixiert, seine verlorenen Artefakte und Notizen zu bergen, was ihn völlig anfällig für Hinterhalte macht, während er ohne jemanden, der bewaffnet ist und ihm den Rücken freihält, durch die Ausgrabungsstätte irrt.",al={"warum braucht wirrbart eine eskortierung","warum braucht wirrbart schutz","warum nicht alleine suchen wirrbart"}}},fp="28,251,21.333.0,35.415.1,28.223.0,39.180.0,31.175.0,28.213.0,38.98.1"}
P.entries["quest:732"] = {n="Erdbeben",s="Garek bittet Euch um Hilfe, nachdem er von allem gehört hat, was Ihr für Sigrun getan habt. Sein Meister, Krasus von den Kirin Tor, schickte ihn ins Ödland, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut. Zuerst braucht er das gestohlene Zeichen der Erde.",h="Garek bittet Euch um Hilfe, nachdem er von allem gehört hat, was Ihr für Sigrun getan habt.",kw={"festung angor","camp boff","dunkeleisen","deathwing","garek","kirin tor","krasus","die lethlorklamm","zeichen der erde"},sec={{t="Eine vertrauliche Angelegenheit",b="Krasus von den Kirin Tor schickte Garek ins Ödland, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut. Er kann Euch den genauen Auftrag nicht verraten, nur dass er von großer Bedeutung ist. Umherziehende Oger haben das Zeichen der Erde gestohlen, und Garek braucht es zurück, bevor er Euch mehr erzählen kann. Sie werden manchmal in der Nähe von Camp Boff gesehen."},{t="Die umherziehenden Oger",b="Oger ziehen im Ödland von Lager zu Lager. Zunehmende Hitze und wirbelnde Winde erschweren es, ihrer Spur zu folgen. Garek hat gehört, dass sie manchmal Camp Boff durchqueren, also sucht dort, falls Ihr ihre Fährte verliert."},{t="Garek erklärt",b="Wenn Ihr mit dem Zeichen zurückkehrt, erzählt Euch Garek, dass die Dunkeleisenzwerge der Festung Angor es erschaffen haben, um Deathwings Zwillingsleutnants zu binden, die skrupellosen Blacklash und Hematus."}},faq={{q="Für wen arbeitet Garek?",a="Krasus von den Kirin Tor ist Gareks Meister. Er schickte Garek ins Ödland, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut.",al={"wer schickte garek","gareks meister","krasus ödland"}},{q="Was ist das Zeichen der Erde?",a="Umherziehende Oger haben das Zeichen der Erde gestohlen, und Garek braucht es zurück, bevor er Euch mehr erzählen wird.",al={"zeichen der erde","was ist das zeichen der erde","zeichen der erde hintergrund"}},{q="Wo sind die umherziehenden Oger zu finden?",a="Die Oger ziehen im Ödland zwischen den Lagern umher. Garek hat gehört, dass sie manchmal Camp Boff durchqueren.",al={"wo sind die oger","oger camp boff","wo ist das zeichen der erde"}},{q="Warum hält Garek den Auftrag geheim?",a="Garek will weder den Auftrag noch die damit verbundenen Aufgaben verraten. Er sagt nur, dass er von großer Bedeutung ist.",al={"warum geheim","garek geheimer auftrag"}}},fp="20,219,19.300.0,19.211.0,14.168.1,25.115.0,30.98.0,39.104.0,42.100.0"}
P.entries["quest:7321"] = {n="Milde Schildkrötensuppe",s="In Tarrens Mühle hofft Christoph Jeffkott, mit Milder Schildkrötensuppe zu beweisen, dass die Verlassenen mit Sorgfalt kochen können. Er braucht Schnappkieferfleisch aus Hillsbrads Wasserläufen und von den Ufern des Lordameresees.",h="In Tarrens Mühle hofft Christoph Jeffkott, mit Milder Schildkrötensuppe zu beweisen, dass die Verlassenen mit...",kw={"christoph jeffkott","kochen","vorgebirge des hügellands","der lordameresee","schnappkiefer","milde schildkrötensuppe","tarrens mühle","schildkrötenfleisch"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Tarrens Mühle gut zu versorgen und die Moral zu stärken, während Ihr seine Grenzen verteidigt.",["profession:Cooking"]="Als Koch könnt Ihr lernen, Milde Schildkrötensuppe mit Schnappkiefern aus dem Lordameresee und Hillsbrads Flüssen zuzubereiten.",["race:Undead"]="Als Untoter könnt Ihr sehen, dass der Tod Christoph Jeffkotts Leidenschaft fürs Kochen nicht gemindert hat."},sec={{t="Kochkunst der Verlassenen",b="Viele glauben, die Verlassenen hätten die Annehmlichkeiten des Lebens aufgegeben, darunter auch die feine Küche. Christoph Jeffkott in Tarrens Mühle sieht das anders. Er prahlt damit, dass seine reichhaltige Schildkrötensuppe Seelen aus dem Jenseits zurücklocken könnte. Mit sorgfältiger Zubereitung will er zeigen, dass untote Hände in einem von Seuche und Krieg gezeichneten Land noch immer ein wärmendes Gericht bereiten können."},{t="Jagd auf die Schnappkiefer",b="Jeffkott sammelte einst Zutaten an Hillsbrads Wasserläufen und am Ostufer des Lordameresees im benachbarten Alterac. Nun halten ihn seine Pflichten in Tarrens Mühle und nahe Streitkräfte der Allianz von der Jagd ab. Also verlässt er sich auf durchreisende Köche der Horde, die Schnappkiefer jagen und ihm ihr Fleisch bringen. Ihre Hilfe hält sein Rezept am Leben."}},faq={{q="Warum liegt einem Koch der Verlassenen daran, heiße Suppe zuzubereiten?",a="Die Verlassenen brauchen Nahrung weniger als lebende Sterbliche, doch Christoph Jeffkott ist stolz auf sein Handwerk. Er will beweisen, dass die Untoten mit Geschick kochen können, und scherzt, seine Brühe könne die Toten wieder zum Leben erwecken.",al={"untote kochkunst","warum suppe kochen","untote essen nahrung"}},{q="Wo findet man Schildkrötenfleisch für dieses Rezept?",a="Schnappkieferfleisch stammt von angriffslustigen Schildkröten an den Flüssen im Vorgebirge des Hügellands, in Alterac und an den Ufern des Lordameresees.",al={"wo sind schildkröten","fundorte von schildkröten","fundorte von schnappkiefern"}},{q="Warum kann Christoph Jeffkott seine Zutaten nicht selbst sammeln?",a="Jeffkotts Pflichten in Tarrens Mühle halten ihn auf Trab, während nahe Streitkräfte der Allianz seine eigenen Jagdausflüge gefährlicher machen.",al={"warum geht christoph nicht","jeffkott sitzt im ort fest"}},{q="Sind Kochkenntnisse erforderlich, um diese Quest anzunehmen?",a="Ja. Christoph Jeffkott teilt sein Rezept nur mit Köchen, und für den Anfang sind keine fortgeschrittenen Kenntnisse nötig.",al={"kochkenntnisse nötig","beruf kochen voraussetzung"}},{q="Welche Bedeutung hat Tarrens Mühle für die Horde in Hillsbrad?",a="Tarrens Mühle ist der wichtigste Stützpunkt der Horde im Vorgebirge des Hügellands. Einst ein Menschendorf, dient der Ort heute den Verlassenen und ihren Verbündeten als befestigte Basis. Häufig kommt es zu Zusammenstößen mit dem nahen Süderstade und der Allianz.",al={"was ist tarrens mühle","geschichte von tarrens mühle"}},{q="Gibt es Schildkrötensuppe nur bei der Horde?",a="Köche der Allianz können von menschlichen Köchen in Süderstade ein Rezept für Schildkrötensuppe lernen, die ebenfalls örtliche Schildkröten verwenden. Christoph Jeffkotts persönliches Anliegen und seine Sichtweise gehören zur Horde.",al={"allianzversion","kann die allianz schildkrötensuppe bekommen"}}},fx={["7509a6d7"]={q="Wofür ist das Schildkrötenfleisch?",a="Christoph Jeffkott benötigt das Schildkrötenfleisch, um seine charakteristische beruhigende Schildkrötenbisque zu brauen. Auch wenn Untote vielleicht nicht die Kälte oder den Hunger wie die Lebenden spüren, ist Jeffkott sehr stolz auf sein kulinarisches Handwerk. Er behauptet, sein Geheimrezept sei so gut, dass die Menschen von den Toten zurückkehren würden, nur um eine heiße Schüssel zu genießen.",al={"verwendung schildkrötenfleisch","warum schildkrötenfleisch","wofür wird schildkrötenfleisch verwendet"}},["5469f6c5"]={q="Was sind die Schnappkiefer, die Ihr für diese Bisque jagt?",a="Schnappkiefer sind bösartige Süßwasserschildkröten mit hartem Panzer, die in den Gewässern von Lordaeron heimisch sind, besonders reichlich entlang der Ufer des Lordameresee und der örtlichen Flussufer. Obwohl sie wild und gefährlich für unvorsichtige Reisende sind, liefert ihr zähes Fleisch das entscheidende, reichhaltige Fleisch, das Christoph für seine Bisque benötigt.",al={"schnappkiefer hillsbrad","lordameresee schnappkiefer","wen jage ich"}}},fp="22,190,19.346.0,20.316.0,54.207.0,47.127.0,56.123.0,49.100.0,59.215.0,37.178.0"}
P.entries["quest:733"] = {n="Schnorrerei",s="In Sigrun Ironhews Lager hängen Verteidigung und Versorgung vom Altmetall ab. Sie braucht sieben Stücke, und die Oger in der Nähe tragen reichlich davon bei sich.",h="In Sigrun Ironhews Lager hängen Verteidigung und Versorgung vom Altmetall ab.",kw={"ödland","die staubspeiergrotte","explorers' league","eisenschmiede","oger","altmetall","schnorrerei","sigrun ironhew"},sec={{t="Ein Lager ohne Material",b="Sigrun Ironhew braucht Material für die Verteidigung des Lagers und andere Zwecke. Der Prospector sorgt sich um den Zustand des Lagers, deshalb will Sigrun bald mit der Arbeit beginnen. Ihr fehlt Altmetall."},{t="Das Altmetall der Oger",b="Die Oger in der Nähe tragen Altmetall bei sich, was dem Gerede über Belagerungsmaschinen im Ödland mehr Gewicht verleiht. Ihr Hauptlager, die Staubspeiergrotte, liegt einen langen Fußmarsch westlich von Sigruns Lager."}},faq={{q="Wer bittet um das Altmetall?",a="Sigrun Ironhew braucht Altmetall, um Verteidigungsanlagen zu bauen und das Lager zu versorgen.",al={"questgeber","wer vergibt schnorrerei","sigrun"}},{q="Warum braucht das Lager Altmetall?",a="Dem Lager fehlt Material für Verteidigungsanlagen und andere Zwecke. Der Prospector sorgt sich um seinen Zustand.",al={"warum altmetall benötigt","zweck des altmetalls","verteidigungsanlagen"}},{q="Wo ist das Altmetall zu finden?",a="Die Oger in der Nähe tragen Altmetall bei sich. Ihr Hauptlager, die Staubspeiergrotte, liegt einen langen Fußmarsch westlich von Sigruns Lager.",al={"altmetall fundort","wo altmetall bekommen","ogerlager"}},{q="Was kommt davor?",a="Die Quest folgt auf Mirages.",al={"vorherige quest","schnorrerei voraussetzung"}}},fp="10,123,25.189.0,16.162.0,34.71.0,35.98.0,35.106.0,23.19.0"}
P.entries["quest:734"] = {n="Das wird schwierig",s="Im Ödland schickt Euch Lotwil Veriatus zu Lucien Tosselwrench, um ein benötigtes Zahnrad Nr. 5 zu holen. Bringt es zu Lotwil zurück.",h="Im Ödland schickt Euch Lotwil Veriatus zu Lucien Tosselwrench, um ein benötigtes Zahnrad Nr.",kw={"ödland","zahnrad nr. 5","lotwil veriatus","lucien tosselwrench","fesseln"},sec={{t="Zahnrad Nummer fünf",b="Lotwil Veriatus wendet sich den Fesseln zu und schickt Euch dann zu Lucien Tosselwrench. Er braucht ein Zahnrad Nr. 5 und bittet Euch, es ihm zurückzubringen."},{t="Luciens Urteil",b="Als Ihr Zahnrad Nr. 5 erwähnt, klingt Lucien Tosselwrench wenig zuversichtlich, wie die Dinge ausgehen werden."}},faq={{q="Wer vergibt diese Quest?",a="Lotwil Veriatus bittet Euch darum, während er im Ödland an einem Satz Fesseln arbeitet.",al={"wer vergibt diese quest","lotwil veriatus quest","questgeber"}},{q="Was braucht Lotwil?",a="Lotwil braucht ein Zahnrad Nr. 5. Er bittet Euch, es zurückzubringen, nachdem Ihr mit Lucien Tosselwrench gesprochen habt.",al={"was will lotwil","welches zahnrad","zahnrad 5"}},{q="Mit wem spreche ich wegen des Zahnrads?",a="Lotwil schickt Euch zu Lucien Tosselwrench im Ödland.",al={"wo zahnrad 5 finden","wer ist lucien","lucien tosselwrench"}}},fp="24,111,15.147.0,16.86.1,21.76.0,22.92.0,32.56.0"}
P.entries["quest:735"] = {n="Der Stern, die Hand und das Herz",s="In Eisenschmiede bietet Gerrig Knochengriff Yagyins Zusammenstellung für drei Gegenstände der Macht an. Ihre Namen werden vor lauschenden Ohren geheim gehalten und auf einem Zettel festgehalten.",h="In Eisenschmiede bietet Gerrig Knochengriff Yagyins Zusammenstellung für drei Gegenstände der Macht an.",kw={"knochengriffs notiz","gerrig knochengriff","hand von dagun","eisenschmiede","legacy heart","stern von xil'yeh","yagyins zusammenstellung"},sec={{t="Ein Handel mit verschlossenen Lippen",b="Gerrig Knochengriff hört Euch nach Yagyins Zusammenstellung fragen und überlegt, ob Ihr irgendwo eine neue Niederlassung des Ordens gründen wollt. Gerrig beschließt, dass es Gerrig nicht zusteht, danach zu fragen. Gerrig hat ein zusätzliches Exemplar zur Hand und glaubt, dass Angehörige des Ordens einander helfen sollten. Daher bittet Gerrig Euch, drei Gegenstände der Macht zu bringen. Ihre Namen bleiben unausgesprochen, falls jemand lauscht, und Gerrig schreibt sie auf."},{t="Die drei Gegenstände",b="Gerrigs Notiz nennt den Stern von Xil'yeh, die Hand von Dagun und das Legacy Heart. Gerrig will alle drei haben, bevor Yagyins Zusammenstellung übergeben wird."},{t="Gerrigs Urteil",b="Mit den Relikten in der Hand nennt Gerrig Euch einfallsreich. Gerrig glaubt, dass Ihr eine neue Niederlassung des Ordens gut leiten werdet, wenn deren Gründung tatsächlich Euer Auftrag ist."}},faq={{q="Wer verlangt die drei Gegenstände?",a="Gerrig Knochengriff in Eisenschmiede verlangt drei Gegenstände und bietet dafür ein zusätzliches Exemplar von Yagyins Zusammenstellung an.",al={"questgeber","wer startet der stern die hand und das herz","gerrig knochengriff quest"}},{q="Welche drei Gegenstände will Gerrig Knochengriff?",a="Gerrig Knochengriffs Notiz nennt den Stern von Xil'yeh, die Hand von Dagun und das Legacy Heart.",al={"benötigte gegenstände","welche relikte braucht er","knochengriffs notiz gegenstände"}},{q="Warum schreibt Gerrig die Gegenstände auf, statt sie auszusprechen?",a="Gerrig schreibt die Namen auf, weil jemand lauschen könnte.",al={"warum die namen aufschreiben","warum die geheime notiz","knochengriff flüstert"}},{q="Was kam davor in der Questreihe?",a="Sie folgt auf „To Eisenschmiede for Yagyins Zusammenstellung“, wo Theldurin der Verirrte Euch zu Gerrig schickte.",al={"vorausgesetzte quest","vorherige quest"}}},fp="32,154,30.392.0,15.140.0,16.158.1,29.104.0,43.89.0,60.62.0,35.89.0"}
P.entries["quest:736"] = {n="Der Stern, die Hand und das Herz",s="In Unterstadt prüft Bewahrer Bel'dugur jene, die ihren eigenen Zirkel leiten wollen. Um eine neue Niederlassung zu gründen, brauchen sie Yagyins Zusammenstellung, doch er verlangt drei unbenannte Gegenstände der Macht.",h="In Unterstadt prüft Bewahrer Bel'dugur jene, die ihren eigenen Zirkel leiten wollen.",kw={"bel'dugurs notiz","bewahrer bel'dugur","orden","der stern die hand und das herz","drei gegenstände der macht","unterstadt","yagyins zusammenstellung"},ang={["class:Warlock"]="Als Hexenmeister sucht Ihr Yagyins Zusammenstellung, um eine neue Schar zu sammeln und die okkulte Meisterschaft Eures Ordens zu erweitern.",["race:Undead"]="Als Untoter findet Ihr Bewahrer Bel'dugur in Unterstadt, wo er Praktizierende der Verlassenen anleitet, die nach verbotenen Riten suchen."},sec={{t="Eine Prüfung der Bruderschaft",b="Praktizierende, die ihren eigenen Zirkel leiten wollen, kommen zu Bewahrer Bel'dugur in Unterstadt. Um eine Niederlassung zu gründen und Anhänger zu sammeln, brauchen sie Yagyins Zusammenstellung, ein Werk rituellen Wissens, das er verwahrt. Bel'dugur hilft einem Bruder, verlangt aber zunächst einen Beweis seiner Würdigkeit, bevor er ihm solches Wissen anvertraut."},{t="Die unausgesprochenen Relikte",b="Bewahrer Bel'dugur verlangt drei Gegenstände der Macht im Austausch für Yagyins Zusammenstellung. Ihre Namen bergen Gefahr oder haben heiliges Gewicht, daher will er sie nicht laut aussprechen. Stattdessen schreibt er sie auf eine vertrauliche Notiz. Wer alle drei findet, erweist sich als würdig, eine eigene Niederlassung zu gründen."}},faq={{q="Wer ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur lebt in Unterstadt und hilft Mitgliedern seiner dunklen Bruderschaft. Er hütet mächtiges Wissen und verlangt von Anwärtern einen Beweis ihrer Würdigkeit, bevor er ihnen heilige Schriften anvertraut.",al={"wer ist bewahrer bel'dugur","bel'dugurs rolle","beldugur unterstadt"}},{q="Was ist Yagyins Zusammenstellung?",a="Yagyins Zusammenstellung ist ein Werk rituellen Wissens, das benötigt wird, um innerhalb eines verschwiegenen okkulten Ordens eine neue Niederlassung zu gründen oder Anhänger zu sammeln.",al={"was ist yagyins zusammenstellung","yagyins zusammenstellung zweck","yagyins zusammenstellung buch"}},{q="Welche Gegenstände verlangt Bewahrer Bel'dugur?",a="Bel'dugur verlangt drei Gegenstände der Macht. Er schreibt ihre Namen auf eine vertrauliche Notiz, weil er sie nicht laut aussprechen will.",al={"welche gegenstände braucht bel'dugur","beldugurs notiz gegenstände","drei gegenstände der macht"}},{q="Warum werden die Namen der verlangten Gegenstände nicht laut ausgesprochen?",a="Bel'dugur will die Namen der drei Relikte nicht laut aussprechen. Ihre Gefährlichkeit oder heilige Bedeutung erfordert Verschwiegenheit.",al={"warum kann bel'dugur die gegenstandsnamen nicht aussprechen","namen nicht aussprechen können","unausgesprochene gegenstandsnamen"}},{q="Was bedeutet es, eine weitere Schar zu sammeln?",a="Eine Schar zu sammeln bedeutet, Anhänger anzuwerben und eine unabhängige Niederlassung der Bruderschaft zu gründen, bereit, andere Praktizierende anzuleiten.",al={"was bedeutet eine schar sammeln","eine niederlassung eröffnen","niederlassung unseres ordens"}},{q="Wo liegt der Mittelpunkt dieser Quest?",a="Im Mittelpunkt der Geschichte steht Bewahrer Bel'dugur in Unterstadt, der unterirdischen Hauptstadt der Verlassenen.",al={"wo spielt diese quest","bel'dugurs aufenthaltsort","quest abgabeort"}}},fp="32,178,21.311.0,19.280.0,24.186.0,24.123.0,41.118.0,58.118.0,42.136.0,29.90.0"}
P.entries["quest:737"] = {n="Verbotenes Wissen",s="Yagyins Zusammenstellung ist in Eurer Obhut, für Theldurin den Verirrten bestimmt und vor unfreundlichen Händen geschützt.",h="Yagyins Zusammenstellung ist in Eurer Obhut, für Theldurin den Verirrten bestimmt und vor unfreundlichen...",kw={"ödland","verbotenes wissen","the star the hand and the heart","theldurin der verirrte","yagyins zusammenstellung"},sec={{t="Ein Buch, das brennt",b="Gerrig Knochengriff in Eisenschmiede oder Bewahrer Bel'dugur in Unterstadt übergibt Euch Yagyins Zusammenstellung. Schützt sie vor unfreundlichen Händen, während Ihr sie zu Theldurin dem Verirrten bringt. Sie birgt viele Wahrheiten, und Wahrheit hat die Eigenart, zu brennen."},{t="Theldurins Hoffnung",b="Theldurin ruft aus, dass noch Hoffnung schimmert. Eure Bemühungen könnten sie alle noch retten, sagt er, und Euch ein Denkmal und einen Schrein einbringen, während Euer Name über Generationen gepriesen wird.\n\nDiese Hoffnung besteht nur, solange SIE unter der Oberfläche bleiben. Wenn SIE sich befreien und emporsteigen, werden alle zu Wurmfutter."}},faq={{q="Welcher Gegenstand muss überbracht werden?",a="Yagyins Zusammenstellung muss überbracht werden. Sie birgt viele Wahrheiten und muss vor unfreundlichen Händen geschützt werden.",al={"welches buch ist das","was ist yagyins zusammenstellung","was mitbringen"}},{q="Wer erhält die Zusammenstellung?",a="Theldurin der Verirrte soll Yagyins Zusammenstellung erhalten.",al={"wer bekommt das buch","bei wem abgeben","wohin kommt die zusammenstellung"}},{q="Was ging dem voraus?",a="Davor kam der Schritt, bei dem Ihr drei Gegenstände im Tausch gegen Yagyins Zusammenstellung beschafft habt.",al={"vorherige quest","was führt hierzu","welche quest kommt vor verbotenes wissen"}}},fp="19,93,17.215.0,16.268.1,32.99.0,24.49.0,22.82.0"}
P.entries["quest:738"] = {n="Sucht Agmond",s="Seit Wochen gibt es keine Nachricht von Prospector Agmond bei den Ausgrabungen im Ödland. Ausgrabungsleiter Eisenband braucht Euch nun, um Agmond zu finden und seinen Bericht zurückzubringen.",h="Seit Wochen gibt es keine Nachricht von Prospector Agmond bei den Ausgrabungen im Ödland.",kw={"agmond","festung angor","ödland","eisenschmiede","ausgrabungsleiter eisenband"},sec={{t="Ein schweigsamer Ausgrabungsleiter",b="Prospector Agmond leitete die Ausgrabungen im Ödland südwestlich von Eisenband. Eisenband nennt ihn nicht länger einen Ausgrabungsleiter, denn seit Wochen gibt es keine Nachricht von ihm. Er braucht Euch, um Agmond zu finden und den Bericht zu bergen. Von Agmond hörte man zuletzt bei der südlichsten Ausgrabung, einem kleinen Trupp jenseits der Festung Angor. Beginnt dort."},{t="Wo die Spur endet",b="Am Ende Eurer Suche findet Ihr ein Skelett, bei dem es sich um Agmonds Überreste handeln muss. Der Körper ist zertrümmert und zerschlagen, und die Knochen sind vollständig abgenagt."}},faq={{q="Wer ist Prospector Agmond?",a="Prospector Agmond leitete die Ausgrabungen im Ödland, südwestlich von Ausgrabungsleiter Eisenband.",al={"wer ist agmond","wer agmond","agmond geschichte"}},{q="Warum sucht Ausgrabungsleiter Eisenband nach Agmond?",a="Ausgrabungsleiter Eisenband hat seit Wochen nichts von Agmond gehört und braucht seinen Bericht.",al={"warum agmond finden","eisenband sucht agmond"}},{q="Wo hielt sich Prospector Agmond zuletzt auf?",a="Von Agmond hörte man zuletzt bei der südlichsten Ausgrabung im Ödland, einem kleinen Trupp jenseits der Festung Angor.",al={"agmond aufenthaltsort","wo ist agmonds ausgrabungsstätte","wo war agmond"}},{q="Was kommt davor in der Questreihe?",a="Davor kommt Ironband Wants You!",al={"vorherige quest","voraussetzung für sucht agmond"}}},fp="11,151,19.307.0,20.154.1,25.92.0,46.80.0,45.98.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Agmond liegt tot im Ödland, und neben seiner Hand ist Murdaloc in den Sandstein geritzt. Tötet seinen Mörder und überbringt Ausgrabungsleiter Eisenband in Loch Modan die Nachricht.",h="Agmond liegt tot im Ödland, und neben seiner Hand ist Murdaloc in den Sandstein geritzt.",kw={"agmond","ödland","loch modan","murdaloc","ausgrabungsleiter eisenband","stonevault bonesnapper","trogg"},sec={{t="Ein Name im Sandstein",b="Blut zeichnet Agmonds Spur von Westen her über Stein und Sand. Es zeigt, wie weit der Zwerg kroch, bevor er starb. Neben seiner reglosen Hand ist ein einziges Wort in den Sandstein des Ödlands geritzt: Murdaloc. Tötet Agmonds Mörder und eine Reihe von Stonevault Bonesnappern und überbringt dann Ausgrabungsleiter Eisenband in Loch Modan die Nachricht."},{t="Eisenbands Antwort",b="Ausgrabungsleiter Eisenband nimmt die Nachricht mit ernstem Gesicht entgegen. Er erinnert sich an Agmond als stark von Arm, grimmig mit dem Hammer und dickköpfig. Eisenband sagt, verfluchte Troggs hätten Agmond getötet. Er glaubt, dass Agmond unterwegs eine ganze Reihe von ihnen mit in den Tod gerissen hat."}},faq={{q="Wer war Agmond?",a="Agmond war ein Zwerg, der für Ausgrabungsleiter Eisenband die Ausgrabungsstätten im Ödland beaufsichtigte. Eure Suche nach ihm endete bei einem Skelett.",al={"wer ist agmond","agmond geschichte"}},{q="Wer ist Murdaloc?",a="Murdaloc ist der Name, der neben Agmonds toter Hand in den Sandstein geritzt ist. Tötet Agmonds Mörder, Murdaloc.",al={"was ist murdaloc","murdaloc geschichte"}},{q="Wohin muss der Bericht gebracht werden?",a="Bringt den Bericht zu Ausgrabungsleiter Eisenband in Loch Modan.",al={"wem von murdaloc berichten","wo ist eisenband"}}},fp="8,162,23.321.0,16.245.1,15.133.0,16.108.0,33.54.0"}
P.entries["quest:74"] = {n="Die Legende von Stalvan",s="An Sturmwinds Kanälen findet Ihr in der Kiste der Flintridges einen Hinweis auf Stalvan Dunstmantels Vergangenheit. Ihre zerrissene Tagebuchseite weist auf Marschall Haggard im Wald von Elwynn hin.",h="An Sturmwinds Kanälen findet Ihr in der Kiste der Flintridges einen Hinweis auf Stalvan Dunstmantels...",kw={"dämmerwald","wald von elwynn","unglückseliger geist","marshal haggard","dunstmantel","versiegelte kiste","stalvan","zerrissene tagebuchseite"},ang={["faction:Alliance"]="Als Ermittler der Allianz deckt Ihr auf, wie persönliche Schrecken im Herzen von Elwynn den Marschällen von Sturmwind entgehen können.",["race:Human"]="Als Mensch seht Ihr Marschall Haggard als Teil von Sturmwinds alternder Veteranengeneration. Er bewahrt entscheidende Erinnerungen an das Königreich, bevor First and Second Wars Familien auseinanderrissen."},sec={{t="Die Vergangenheit freilegen",b="Unter einer Keramikvase in der Versiegelten Kiste liegt eine zerrissene Seite aus Stalvan Dunstmantels Tagebuch. Muffige Erbstücke der Flintridges, alte Jagdtrophäen und Familienporträts füllen die Kiste. Stalvans eigene Handschrift gewährt einen Einblick in das Leben des zurückgezogenen Gelehrten, bevor das Unglück zuschlug."},{t="Das schwindende Augenlicht des Marschalls",b="Marschall Haggard müht sich mit seinem schwindenden Augenlicht, das mitgenommene Pergament zu lesen. Die unverwechselbare Handschrift weckt Erinnerungen an Dokumente und Vorfälle aus vergangenen Jahren, bevor die Dunkelheit ihm das Augenlicht nahm."}},faq={{q="Wo befindet sich die Versiegelte Kiste?",a="Die Versiegelte Kiste steht neben den Canals von Sturmwind, direkt hinter Verwalter Folsom. Darin liegen die Habseligkeiten der Familie Flintridge, und die Seite daraus geht an Marschall Haggard im Südosten des Waldes von Elwynn.",al={"fundort der kiste","wo ist die kiste","haggard kiste"}},{q="Was befindet sich in der Versiegelten Kiste?",a="Die Kiste enthält staubige Erbstücke, ein Familienporträt, alte Bücher, Jagdtrophäen und eine Keramikvase. Unter der Vase liegt eine zerrissene Seite aus Stalvans Tagebuch.",al={"inhalt der kiste","was ist in der kiste","zerrissene seite kiste"}},{q="Wer ist Marschall Haggard?",a="Marschall Haggard ist ein betagter Offizier aus Sturmwind im Ruhestand, der allein im Süden des Waldes von Elwynn lebt. Sein Augenlicht schwindet und er ist gebrechlich, doch seine Erinnerungen an alte Aufzeichnungen und Reisende machen ihn zu einem entscheidenden Zeugen vergangener Ereignisse.",al={"wer ist haggard","marshal haggard hintergrundgeschichte","alter marschall elwynn"}},{q="Warum ist diese Tagebuchseite wichtig?",a="Die zerrissene Seite ist ein unmittelbares Beweisstück aus Stalvan Dunstmantels eigener Hand. Ihre unverwechselbare Schrift und die darin nachklingenden Gedanken verbinden Berichte aus dem Dämmerwald und Elwynn mit seinem persönlichen Niedergang.",al={"warum die zerrissene seite wichtig ist","tagebuchseite hinweis","stalvans tagebuch"}},{q="Was geschieht, wenn die Kiste geöffnet wird?",a="Wer die Überreste von Stalvans Vergangenheit aufwühlt, schreckt die ruhelosen Toten auf. Ein rachsüchtiger Unglückseliger Geist erscheint und greift jene an, die das Unglück aufzuklären versuchen.",al={"unglückseliger geist erscheinen","geist nach kiste","warum hat ein geist angegriffen"}},{q="Wohin führt die Ermittlung als Nächstes?",a="Sobald die zerrissene Seite Marschall Haggard erreicht, lenkt seine Erinnerung an die Handschrift die Ermittlung zu weiteren erhaltenen Bruchstücken von Stalvans Geschichte.",al={"nächster schritt","nach der zerrissenen seite","wohin als nächstes"}}},fp="21,171,19.265.0,24.200.1,34.215.0,32.158.0,23.226.0,35.183.0,38.152.0,39.152.0"}
P.entries["quest:741"] = {n="Der geistesabwesende Ausgrabungsleiter",s="Von der Dunkelküste schickt Hollee Wirrbarts Fossil nach Darnassus, während sie bleibt, um auf den umherwandernden Ausgrabungsleiter aufzupassen. Chefarchäologe Grauflaum zeigt reges Interesse an dem Fund.",h="Von der Dunkelküste schickt Hollee Wirrbarts Fossil nach Darnassus, während sie bleibt, um auf den...",kw={"archäologe","dunkelküste","darnassus","forscherliga","fossil","grauflaum","hollee","wirrbart"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, ihre Völker über große Entfernungen hinweg zu verbinden. Zwergische Forscher verlassen sich auf Reisende, um Funde sicher von den abgelegenen Stränden der Dunkelküste nach Darnassus zu bringen.",["race:Dwarf"]="Als Zwerg dient Ihr mit dem Transport von Wirrbarts Fossil dem wichtigsten Ziel der Forscherliga: die ferne Vergangenheit der Welt zu ergründen und den Wert zwergischer Beharrlichkeit zu zeigen.",["race:NightElf"]="Als Nachtelf kann es Euch befremden, wenn zwergische Ausgräber uralte Überreste aus dem heiligen Boden der Dunkelküste bergen. Die Zusammenarbeit mit der Liga wahrt die Bande der Allianz."},sec={{t="Ein Kurier zur Hauptstadt",b="Ausgrabungsleiter Wirrbart hat an der Küste der Dunkelküste ein merkwürdiges Fossil gefunden. Er gräbt lieber weiter, als sich an Vorschriften zu halten. Deshalb bleibt Archäologin Hollee bei ihm, inmitten der gefährlichen Bestien und feindseligen Kultisten der Küste. Sie bittet Euch, das Exemplar nach Darnassus zu bringen, wo eine wissenschaftliche Delegation der Zwerge untergebracht ist."},{t="Zwergische Interessen in Kalimdor",b="Zwerge aus Eisenschmiede haben unter dem Banner der Forscherliga das große Meer überquert. Sie suchen in Kalimdors Boden nach uralten Relikten und verlorener Geschichte. In Darnassus staunt Chefarchäologe Grauflaum über Wirrbarts Talent, uralte Schätze zu finden. Nachtelfen betrachten ihre Wälder als lebendige Heiligtümer, während die Liga die uralten Lande als Boden sieht, den es zu erforschen und zu entschlüsseln gilt."}},faq={{q="Was ist das Geheimnisvolle Fossil?",a="Ausgrabungsleiter Wirrbart hat an der Küste der Dunkelküste ein unbestimmtes versteinertes Exemplar gefunden. Sein Alter und seine seltsame Beschaffenheit machen es zu einem begehrten Fund für die Gelehrten der Forscherliga in Darnassus.",al={"geheimnisvolles fossil","was ist das für ein fossil","wirrbarts fossil"}},{q="Warum bleibt Hollee an der Dunkelküste zurück?",a="Archäologin Hollee bleibt, um auf Ausgrabungsleiter Wirrbart aufzupassen. Er wandert bei seinen Ausgrabungen umher und missachtet Gefahren, deshalb will sie ihn nicht allein in der Wildnis lassen, während sie seine Entdeckungen nach Darnassus bringt.",al={"warum geht hollee nicht","hollee bleibt","warum hollee bleibt"}},{q="Wer ist Chefarchäologe Grauflaum?",a="Chefarchäologe Grauflaum ist ein hochrangiger Vertreter der Forscherliga von Eisenschmiede. Von Darnassus aus beaufsichtigt er die archäologischen Arbeiten im nördlichen Kalimdor und untersucht dort Relikte, die zwergische Ausgräber mitbringen.",al={"grauflaum","wer ist grauflaum","chefarchäologe grauflaum"}},{q="Warum ist die Forscherliga in Darnassus tätig?",a="König Magni Bronzebart beauftragte die Forscherliga damit, die Ursprünge des Zwergenvolks und die uralte Geschichte in ganz Azeroth zu ergründen. Freundschaftliche Beziehungen zu den Nachtelfen ermöglichen es zwergischen Gelehrten, von Darnassus aus Expeditionen zu unternehmen und Kalimdors vergessene Lande zu erforschen.",al={"zwerge in darnassus","forscherliga darnassus","warum sind zwerge hier"}},{q="Wohin gelangt dieses Fossil nach Darnassus?",a="Chefarchäologe Grauflaum untersucht das Fossil in Darnassus. Funde dieser Bedeutung sollen katalogisiert oder über die Wege der Liga an das große Museum in Eisenschmiede weitergeleitet werden.",al={"wohin kommt das fossil","fossil nächster schritt"}},{q="Wo hat Wirrbart das Exemplar gefunden?",a="Wirrbart legte das Exemplar an der wilden Küste der Dunkelküste frei, zwischen Schiffswracks, uralten Ruinen und versteinerten Meereslebewesen aus der Zeit vor der Great Sundering.",al={"wo wurde das fossil gefunden","wirrbarts ausgrabungsstätte"}}},fx={c70c2c67={q="Warum möchte Archäologin Hollee, dass das Fossil nach Darnassus geliefert wird?",a="Ausgrabungsleiter Wirrbart möchte seinen Fund sofort untersuchen lassen, aber jemand muss ihn zu ihren Vorgesetzten bringen. Hollee ist entschlossen, Dunkelküste nicht zu verlassen, während Wirrbart in der Wildnis zurückbleibt, also verlässt sie sich darauf, dass Ihr den unbezahlbaren Fund in ihrem Namen direkt zu Chefarchäologe Grauflaum nach Darnassus bringt.",al={"warum fossil nach darnassus schicken","beweggrund hollee","warum fossil zustellen"}}},fp="28,180,24.315.0,29.381.0,30.181.0,41.202.0,39.222.0,52.261.0,46.181.0,38.151.0"}
P.entries["quest:742"] = {n="Die Jagd im Eschental",s="In Donnerfels schickt die Jagd im Eschental junge Champions der Horde nach Norden, um an den Waldaußenposten zu dienen. Herolde weisen sie an, sich für eine Bewährungsjagd bei Senani Donnerherz am Splitterholzposten zu melden.",h="In Donnerfels schickt die Jagd im Eschental junge Champions der Horde nach Norden, um an den Waldaußenposten...",kw={"eschental","jagd","senani","splitterholz","donnerfels","donnerherz","windschreiter","der zoramstrand"},ang={["class:Hunter"]="Als Jäger könnt Ihr Eure Fährtenlesekunst in Eschentals dichtem Wald verfeinern, wo Raubtiere durch ein Gelände streifen, das sich von den trockenen, offenen Savannen des Südens unterscheidet.",["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch auf den Splitterholzposten und den Zoramstrand, um die nördlichen Nachschubwege zu sichern. Neue Rekruten helfen dabei, wilde Tiere und feindselige Einheimische in Schach zu halten.",["race:Tauren"]="Als Tauren, der auf Mulg Ores offenen Ebenen aufgewachsen ist, steht Ihr unter Eschentals dichtem Blätterdach vor einer ungewohnten Herausforderung. Angehörige Eures Volkes wie Senani wachen über die Jagd."},sec={{t="Ein Ruf vom High Rise",b="Kliffläufer Windschreiter trägt eine offene Einladung für bewährte Abenteurer durch Donnerfels. Nördlich des Brachlands hat die Horde in einem uralten Wald Fuß gefasst, und ihre Außenposten brauchen junge Krieger. Wer dem Ruf folgt, wird sich rauerem Land stellen und seine Überlebensfähigkeiten jenseits von Mulgore auf die Probe stellen."},{t="Die nördliche Grenze",b="Eschental bietet der Horde reiche Ressourcen und große Gefahren. Der Splitterholzposten liegt an der Hauptstraße, während ein abgelegener Außenposten an der Westküste am Zoramstrand steht. Am Splitterholzposten organisiert Senani Donnerherz, eine erfahrene Wildniskundige, eine große Jagd. Dort zähmen Rekruten die Wildnis und erringen Ruhm für die Horde."}},faq={{q="Wer bietet diese Quest in Donnerfels an?",a="Kliffläufer Windschreiter überbringt vorbeiziehenden Abenteurern in Donnerfels den Ruf. Er macht fähige Kämpfer auf die Expansionsbestrebungen der Horde aufmerksam und weist ihnen den Weg zu Außenposten, die Hilfe brauchen.",al={"wer startet ashenvale hunt","questgeber ashenvale hunt","kliffläufer windschreiter"}},{q="Wo liegt der Splitterholzposten?",a="Der Splitterholzposten ist eine befestigte Siedlung der Horde im Osten von Eschental. Reist nach Norden über die Grenze des Brachlands und folgt dann dem östlichen Waldpfad tiefer in den Wald.",al={"splitterholzposten lage","wie zum splitterholzposten gelangen","wo ist splitterholz"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine erfahrene Fährtenleserin der Tauren, die am Splitterholzposten stationiert ist. Sie organisiert Jagden in Eschental und stellt Rekruten der Horde im Kampf gegen die örtlichen Raubtiere auf die Probe.",al={"senani donnerherz","wer ist senani","donnerherz npc"}},{q="Warum jagt die Horde in Eschental?",a="Die Horde jagt in Eschental, um Holz zu beschaffen und ihr Gebiet zu sichern. Die Jagd verringert die Zahl der wilden Tiere, die ihre Lager bedrohen, und lässt junge Abenteurer sich in unbekanntem Gelände beweisen.",al={"warum in eschental jagen","ashenvale hunt zweck","horde eschental ziele"}},{q="Was ist der Zoramstrand, der in der Einweisung erwähnt wird?",a="Der Zoramstrand ist ein Lager der Horde an der äußersten Westküste von Eschental, dem Meer zugewandt. Er ist ein zweiter Marinestützpunkt und ein Bollwerk gegen Naga und feindselige Waldbewohner.",al={"was ist der zoramstrand","zoramstrand außenposten","zoram außenposten"}},{q="Was geschieht, nachdem Ihr Euch bei Senani gemeldet habt?",a="Wenn Ihr Euch bei Senani Donnerherz meldet, heißt sie Euch am Außenposten willkommen und schickt Euch auf die umfassendere Jagd. Sie weist Euch an, Eschentals wildesten Bestien nachzustellen und sie zu bezwingen.",al={"was folgt auf ashenvale hunt","nächste quest nach senani","fortsetzung der jagd"}}},fx={af70e220={q="Warum möchte Kliffläufer Windschreiter, dass Ihr ins Eschental geht?",a="Kliffläufer Windschreiter dient als Herold für die Horde und weist fähige junge Champions den Weg dorthin, wo sie am dringendsten gebraucht werden. Die Horde sichert aggressiv ihre Grenzposten in den ungezähmten Wäldern nördlich des Brachlands, und Jäger wie Senani Donnerherz benötigen frische Rekruten, um ihre Präsenz zu verstärken und in der Wildnis Ruhm zu erlangen.",al={"warum ins eschental schicken","beweggrund von kliffläufer windschreiter","warum will windschreiter das"}}},fp="18,197,28.293.0,21.333.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.171.0"}
P.entries["quest:743"] = {n="Windfuriengefahr",s="Ruul Adlerklaue prüft Eure Kampfbereitschaft gegen die Windfurienharpyien in Mulgore. Ihr Tempo und ihre Klauen werden Euch an den südöstlichen Klippen fordern, bevor Ihr die Heimat der Tauren verlasst.",h="Ruul Adlerklaue prüft Eure Kampfbereitschaft gegen die Windfurienharpyien in Mulgore.",kw={"dorf der bluthufe","windfuriengefahr","harpyien","mulgore","ruul adlerklaue","taurenprüfung","windfurien","windfury talons"},ang={["class:Warrior"]="Als Krieger lernt Ihr durch Ruul Adlerklaues Herausforderung, schnelle Sturzangriffe zu parieren. Sie schult Euch darin, wilden Angreifern aus der Luft mit festem Stand und Disziplin zu begegnen.",["faction:Horde"]="Als Verbündeter der Tauren zeigt Ihr durch Ruuls Prüfung Euren Einsatz für den Schutz des Kernlands der Horde. Sie kann Euch den Respekt des Dorfes der Bluthufe einbringen.",["race:Tauren"]="Als junger Tauren helft Ihr durch das Ausräumen der Windfuriennester, die Ebenen zu verteidigen. Unter den wachsamen Augen der Dorfältesten markiert dies Euren Übergang ins anerkannte Erwachsenenalter."},sec={{t="Das Urteil eines Lehrers",b="Ruul Adlerklaue beobachtet vom Dorf der Bluthufe aus Reisende, die Mulgore durchqueren. Er fordert jene, die erwachsen werden oder sich auf weitere Reisen vorbereiten, dazu auf, ihre Kampfinstinkte zu beweisen. Jenseits der geschützten Täler von Mulgore verlangt das Überleben nach Besonnenheit im Kampf gegen gerissene Feinde. Ruul misst Eure Stärke an den wildesten heimischen Raubtieren des Landes."},{t="Die Bedrohung der Windfurien",b="Die Windfurienharpyien nisten am südöstlichen Gebirgsrand von Mulgore, fernab der ausgetretenen Pfade. Sie bedrohen umherstreifende Wildtiere und allein reisende Wanderer. Auf der Jagd nach frischem Fleisch stürzen sie sich blitzschnell herab und schlagen mit rasiermesserscharfen Klauen zu. Besiegt sie und bringt ihre Krallen zurück, um zu beweisen, dass Ihr eine fest verwurzelte Bedrohung bezwingen und einen Angriff aus der Luft abwehren könnt."}},faq={{q="Wer ist Ruul Adlerklaue?",a="Ruul Adlerklaue ist ein erfahrener Taurenkrieger und Lehrer im Dorf der Bluthufe. Er prüft junge Abenteurer, bevor sie in die gefährlicheren Regionen Kalimdors reisen.",al={"ruul adlerklaue","wer vergibt windfuriengefahr","ruul"}},{q="Wo findet man die Windfurienharpyien in Mulgore?",a="Die Windfurienharpyien nisten entlang der südöstlichen Berge von Mulgore, in einfachen Nestern hoch auf Felsen und an den Hängen der Ausläufer. Ihre Nester liegen abseits der Hauptstraße durch das Tal.",al={"windfurienharpyien fundort","wo sind windfurienharpyien","windfuriennester fundort"}},{q="Warum gelten die Windfurienharpyien als natürliche Feinde der Tauren?",a="Die Windfurienharpyien sind angriffslustige Aasfresser, die ihr Revier verteidigen und jeden angreifen, der sich ihren Nistplätzen nähert. Ihr Hunger nach frischem Fleisch und ihre Angriffe auf Reisende und Weidetiere machen sie zu einer ständigen Bedrohung für die Ebenen.",al={"warum bekämpfen tauren harpyien","harpyienbedrohung mulgore","windfurien hintergrundgeschichte"}},{q="Welchen Beweis verlangt Ruul Adlerklaue von der Jagd?",a="Ruul fordert Euch auf, acht Windfury Talons von erlegten Harpyien zurückzubringen. Die Krallen sind ihre wichtigsten natürlichen Waffen.",al={"windfuriengefahr beweis","was für ruul sammeln","windfurien questziel"}},{q="Warum müssen sich Abenteurer dieser Prüfung stellen, bevor sie Mulgore verlassen?",a="Ruul betrachtet die Windfurienharpyien als Prüfung der Kampfbereitschaft. Ihr Tempo, ihre Wildheit und ihre Klauen fordern jene, die sich auf Gefahren jenseits der schützenden Steilhänge von Mulgore vorbereiten.",al={"zweck der prüfung","warum windfuriengefahr absolvieren","ruuls prüfung"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt im Herzen von Mulgore nahe dem Stonebullsee, südlich des Great Gate und von Donnerfels. Reisende Tauren finden dort Kultur, Handel und Ausbildung.",al={"dorf der bluthufe lage","wo liegt das dorf der bluthufe","ruul standort"}}},fx={d8522cbd={q="Warum möchte Ruul Adlerklaue, dass die Windfury-Harpyien gejagt werden?",a="Ruul Adlerklaue ist ein Krieger und Mentor, der damit beauftragt ist, junge Abenteurer auf das Leben jenseits der sicheren Grenzen von Mulgore vorzubereiten. Er sieht die grausamen Windfury-Harpyien als natürliche Prüfung an – ein wahrer Maßstab für Euer kriegerisches Können und Eure Bereitschaft, Euch den härteren Bedrohungen der weiteren Welt zu stellen.",al={"warum harpyien jagen","ruuls beweggrund","grund von ruul adlerklaue"}},["1789ad72"]={q="Wer sind die Windfury-Harpyien?",a="Die Windfury-Harpyien sind wilde, vogelartige Aasfresser, die entlang der Bergvorsprünge südöstlich des Dorfes der Bluthufe nisten. Bösartig und gerissen, haben sie lange Zeit Reisende und die Tierwelt in ganz Mulgore gejagt, getrieben von einem unersättlichen Hunger nach frischem Fleisch und einer natürlichen Feindseligkeit gegenüber den Tauren.",al={"windfury-harpyien","wer sind die windfury","windfury-harpyien in mulgore"}},["29c303b8"]={q="Warum jagt Ruul Adlerklaue die Harpyien nicht selbst?",a="Ruul ist ein Lehrer, dessen Aufgabe im Dorf der Bluthufe darin besteht, die nächste Generation von Verteidigern zu fördern, nicht ihre Schlachten für sie zu schlagen. Diese Aufgabe ist ausdrücklich ein Initiationsritus: Ihr müsst Eure eigene Stärke gegen die Raubtiere von Mulgore beweisen, bevor Ihr als geeignet angesehen werdet, jenseits der Ebenen zu reisen.",al={"warum ich","warum mich schicken","warum macht ruul es nicht selbst"}}},fp="23,183,22.325.0,19.354.0,23.162.0,48.176.0,70.210.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="Vorbereitungen auf die Zeremonie",s="Eyahn Eagletalon fertigt einen Kopfschmuck für seinen Bruder, der bald vor Oberhäuptling Cairne Bluthuf treten wird. Er bittet Euch, die leuchtenden Federn von Harpyien jenseits von Donnerfels zu sammeln, während er die Lederbänder gerbt.",h="Eyahn Eagletalon fertigt einen Kopfschmuck für seinen Bruder, der bald vor Oberhäuptling Cairne Bluthuf...",kw={"cairne bluthuf","zeremonie","federn","harpyie","kopfschmuck","mulgore","vorbereitungen auf die zeremonie","tauren","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde ehrt Ihr die Bräuche Eurer Taurenverbündeten auf den Tafelbergen von Donnerfels, wenn Ihr ihnen bei ihren zeremoniellen Pflichten helft.",["race:Tauren"]="Als Tauren wisst Ihr, dass Kopfschmuck aus Naturmaterialien mit Ehre und Übergangsriten vor dem Oberhäuptling verbunden ist. Bei der Herstellung eines solchen Ornats zu helfen, zeigt den gemeinsamen Stolz und Geist der Stämme."},sec={{t="Dem Häuptling zu Ehren",b="Unter den Tauren erfüllt es einen mit Stolz und Ehrfurcht, vor Oberhäuptling Cairne Bluthuf zu treten. Familien ehren diesen Anlass, indem sie angemessene Kleidung vorbereiten. Der traditionelle Kopfschmuck besteht aus behandeltem Leder und symbolträchtigem Gefieder, wobei jeder Bestandteil Würde und Respekt vor dem Anführer der vereinten Stämme zeigen soll."},{t="Federn der Felsen",b="Ein zeremonieller Kopfschmuck braucht ein Lederband und Federn für seine Krone. Während die Lederriemen gegerbt werden, müssen lange, makellose Federn gesammelt werden. Harpyien nisten in den zerklüfteten Hügeln nördlich und nordwestlich von Donnerfels, also müsst Ihr Euch in ihre feindseligen Nester wagen, um Federn der benötigten Größe und Farbe zu finden."}},faq={{q="Welche Zeremonie wird vorbereitet?",a="Die Zeremonie gilt dem Auftritt eines Tauren vor Oberhäuptling Cairne Bluthuf. Sein Bruder fertigt für diesen Anlass einen Kopfschmuck aus gegerbtem Leder und leuchtenden Federn.",al={"was ist das für eine zeremonie","was ist die zeremonie","wer tritt vor bluthuf"}},{q="Wer ist Oberhäuptling Bluthuf?",a="Oberhäuptling Cairne Bluthuf führt die vereinten Taurenstämme von Donnerfels aus. Vor ihn zu treten, ist für jeden Tauren eine Ehre.",al={"wer ist oberhäuptling bluthuf","cairne bluthuf","wer ist bluthuf"}},{q="Warum werden Harpyienfedern für den Kopfschmuck benötigt?",a="Der Kopfschmuck benötigt Federn einer bestimmten Größe und Farbe. Sein Entwurf sieht azurblaues und bronzefarbenes Gefieder vor, während die Lederriemen gegerbt werden.",al={"warum werden harpyienfedern benötigt","warum harpyienfedern","warum federn"}},{q="Wo befinden sich die Harpyien?",a="Die Harpyien leben im zerklüfteten Gelände nördlich und nordwestlich von Donnerfels in Mulgore.",al={"wo leben harpyien","wo sind harpyien zu finden","wo sind azurblaue und bronzefarbene federn"}},{q="Welche Rolle spielen Harpyien in Mulgore?",a="Harpyien sind bösartige, vogelartige humanoide Wesen, die in Mulgores zerklüfteten Felsen nisten. Sie bedrohen Reisende und die Stämme, während ihr großes, farbenprächtiges Gefieder Material für zeremoniellen Schmuck liefert.",al={"warum werden harpyien gejagt","was sind harpyien"}},{q="Wer fertigt den zeremoniellen Kopfschmuck?",a="Eyahn Eagletalon gerbt die Lederriemen und fertigt den Kopfschmuck für seinen Bruder, der sich darauf vorbereitet, vor den Häuptling zu treten.",al={"wer macht den kopfschmuck","wer fertigt den kopfschmuck"}}},fp="24,212,22.307.0,21.314.0,36.161.0,23.121.0,48.143.0,30.82.0,37.203.0,41.130.0"}
P.entries["quest:745"] = {n="Gemeinsame Nutzung des Landes",s="In Mulgore bittet Euch Baine Bluthuf, die Bleichmähnengnolle davon abzuhalten, die Wildtiere der Ebenen zu töten. Ihr helft, die Herden und die Lebensweise der Tauren im Einklang mit der Erdenmutter zu schützen.",h="In Mulgore bittet Euch Baine Bluthuf, die Bleichmähnengnolle davon abzuhalten, die Wildtiere der Ebenen zu...",kw={"baine bluthuf","dorf der bluthufe","gnolle","mulgore","bleichmähnen","poachers","gemeinsame nutzung des landes","kürschner","gerber"},ang={["class:Druid"]="Als Druide wisst Ihr, dass ungezügelte Wilderei dem Geist der Ebenen schadet. Die Harmonie des Landes braucht Eure Hilfe.",["class:Hunter"]="Die Kürschner und Wilderer der Bleichmähnen jagen grausam und verschwenderisch. Ihnen fehlt der Respekt eines wahren Jägers vor wilden Geschöpfen.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr Eure Verbindung zu den Anführern der jungen Taurennation, indem Ihr Baine Bluthuf helft.",["race:Tauren"]="Als junger Tauren folgt Ihr Baines Ruf, Mulgore zu verteidigen und das Gleichgewicht der Erdenmutter zu ehren."},sec={{t="Ein Land im Ungleichgewicht",b="Die Tauren nehmen vom Land nur das, was sie brauchen, und ehren die Erdenmutter in allen Dingen. Bleichmähnengnolle haben sich südlich des Dorfes der Bluthufe und in einer Höhle im Westen niedergelassen. Überall auf den Ebenen schlachten sie Wildtiere ab und lassen Kadaver zurück. Ihre verschwenderischen Jagden schaden dem Gleichgewicht des Graslandes und bedrohen die friedliche Heimat, die sich die Tauren in Mulgore aufbauen."},{t="Wenn Worte versagen",b="Baine Bluthuf versuchte, die Angelegenheit friedlich beizulegen, indem er mit den Bleichmähnengnollen sprach. Sie wiesen jeden Versuch zurück und töteten weiter Wildtiere. Nun schickt er junge Krieger in ihre Jagdlager, um die Wilderer, Gerber und Kürschner aufzuhalten, bevor das Grasland dauerhaften Schaden nimmt."},{t="Der Kreislauf von Leben und Tod",b="Bei Eurer Rückkehr lehrt Baine, dass Leben niemals aus Bosheit genommen werden darf, auch wenn es nötig sein kann, um die Harmonie zu bewahren. Leben und Tod bilden einen Kreislauf. Jeder Beschützer von Mulgore muss diese Wahrheit in sich tragen."}},faq={{q="Wer vergibt diese Quest?",a="Baine Bluthuf, Sohn des Oberhäuptlings Cairne Bluthuf, gibt Euch diese Aufgabe im Dorf der Bluthufe im Herzen von Mulgore.",al={"questgeber","wer startet gemeinsame nutzung des landes","baines quest"}},{q="Warum gehen die Tauren gegen die Bleichmähnengnolle vor?",a="Die Bleichmähnengnolle jagen Mulgores Wildtiere rücksichtslos und dezimieren die Herden. Außerdem wiesen sie die Versuche der Tauren zurück, friedlich mit ihnen zu sprechen.",al={"warum gnolle töten","bleichmähnenproblem","was haben die gnolle getan"}},{q="Wo befinden sich diese Gnolle?",a="Die Bleichmähnen lagern südlich des Dorfes der Bluthufe und leben im Höhlensystem des Bleichmähnenfelsens im Westen.",al={"standorte der gnolle","lager der bleichmähnen","wo sind bleichmähnen zu finden"}},{q="Haben die Tauren zuerst versucht, Frieden zu schließen?",a="Ja. Baine sagt, die Tauren hätten mehrmals versucht, mit den Gnollen zu sprechen und das Land zu teilen, doch die Bleichmähnen lehnten ihre friedlichen Angebote ab.",al={"haben tauren mit gnollen gesprochen","diplomatie mit den bleichmähnen"}},{q="Welche Lehre will Baine hier vermitteln?",a="Baine möchte, dass junge Verteidiger verstehen, dass Leben und Tod einen unzerbrechlichen Kreislauf bilden. Leben zu nehmen kann nötig sein, um das Gleichgewicht zu schützen, doch es muss mit Respekt vor der Erdenmutter geschehen.",al={"baines lehre","bedeutung von gemeinsame nutzung des landes"}},{q="Wer sind die Bleichmähnengnolle?",a="Die Bleichmähnengnolle sind ein primitiver, hyänenartiger Stamm, der in Mulgore heimisch ist. Sie haben blasses Fell, verteidigen ihr Gebiet aggressiv und missachten die Harmonie der Ebenen.",al={"wer sind die bleichmähnen","stamm der bleichmähnen"}}},fx={["901e0c5d"]={q="Gegen wen werdet Ihr bei Sharing the Land ausgesandt?",a="Baine sendet Euch gegen die Palemane-Gnolle, die auf die Ebenen südlich des Dorfes der Bluthufe übergegriffen haben und in einer westlichen Höhle Schutz suchen. Diese Wilderer, Abfleischer und Gerber haben rücksichtslos die Tierwelt von Mulgore abgeschlachtet, ohne Ehrfurcht vor dem Gleichgewicht oder der Erdenmutter. Da sie jedes friedliche Angebot der Tauren gewaltsam zurückgewiesen haben, ist Gewalt das einzige Mittel, das bleibt, um ihre Wilderei zu stoppen.",al={"ziele von sharing the land","wen töte ich bei sharing the land","palemane-gnolle bei sharing the land"}}},fp="16,178,21.364.0,15.287.0,28.197.0,21.117.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="Zwergenbuddelei",s="Im Dorf der Bluthufe fürchtet Baine Bluthuf, dass die Prospektoren Mulgore entstellen und seine Tiere erzürnen. Er bittet junge Verteidiger der Horde, ihre Spitzhacken zu zerbrechen und die Grabungen aufzuhalten.",h="Im Dorf der Bluthufe fürchtet Baine Bluthuf, dass die Prospektoren Mulgore entstellen und seine Tiere...",kw={"baine bluthuf","dorf der bluthufe","zwerg","schmiede","kodo","mulgore","spitzhacken","prospektor"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass unbedachte Grabungen das Grundgestein erschüttern, die Elemente aufwühlen und unter den Geistern und Geschöpfen des Landes Unruhe stiften.",["faction:Horde"]="Als Mitglied der Horde seht Ihr in Allianzzwergen, die in Hordengebiete eindringen, eine Bedrohung für den brüchigen Frieden seit dem Dritten Krieg. Sie missachten die Stammesgrenzen.",["profession:Mining"]="Als Bergarbeiter schätzt Ihr vielleicht, was im Gestein liegt, doch die Arbeit der Zwerge in Mulgore opfert Respekt und Harmonie rücksichtsloser Zerstörung.",["race:Tauren"]="Als Tauren wisst Ihr, dass der Leib der Earth Mother heilig ist. Fremde, die Mulg ores Steppen durchbohren, verlangen nach einer entschlossenen Antwort."},sec={{t="Eindringlinge in den Hügeln",b="Nordwestlich des Dorfes der Bluthufe haben zwergische Prospektoren eine Ausgrabungsstätte in Mulgore abgesteckt. Die Forscherliga durchsucht Kalimdor nach Titanenrelikten und Geheimnissen der Irdenen. Oft nehmen sie wenig Rücksicht auf die Ländereien oder Bräuche der dortigen Bewohner. Für die Tauren ist die Erde eine lebendige Mutter, die Verehrung verdient, statt nach Stein und Metall durchgraben zu werden."},{t="Die heilige Erde verteidigen",b="Baine Bluthuf sieht in den Maschinen und Sprengungen der Zwerge eine Bedrohung für das empfindliche Gleichgewicht der Ebenen. Ihr Lärm versetzt die einheimischen Tiere in Aufruhr und treibt die Kodos in Raserei. Deshalb wollen die Tauren die Spitzhacken der Prospektoren an den Schmieden zerschlagen. Die zerbrochenen Werkzeuge sollen die Zwerge warnen und die Grabungen aufhalten, bevor bleibender Schaden entsteht."}},faq={{q="Warum graben Zwerge in Mulgore?",a="Zwergische Prospektoren suchen unter Mulgore nach verborgenen Geheimnissen und Artefakten. Ihr Bergbau missachtet das Gebiet und die Bräuche der Tauren und bringt sie mit ihnen in Konflikt.",al={"zwerge in mulgore","warum sind prospektoren hier","zwergische ausgrabung mulgore"}},{q="Wer vergibt die Quest Zwergenbuddelei?",a="Baine Bluthuf erteilt den Auftrag im Dorf der Bluthufe im Herzen von Mulgore. Er ist der junge Sohn von Oberhäuptling Cairne Bluthuf.",al={"questgeber zwergenbuddelei","wer startet zwergenbuddelei"}},{q="Warum will Baine die Werkzeuge zerschlagen lassen, statt sie nur zu stehlen?",a="Baine will die Spitzhacken zerbrechen lassen, damit die Ausgrabung sofort zum Stillstand kommt. Ihre Zerstörung an den Schmieden warnt die Zwerge, dass sich die Geheimnisse des Landes nicht mit roher Gewalt gewinnen lassen.",al={"warum die spitzhacken zerbrechen","zwergenwerkzeuge zerschlagen"}},{q="Wie wirken sich die Grabungen auf Mulg ores Tierwelt aus?",a="Die Grabungen und die Wunden in der Erde versetzen Mulg ores einheimische Geschöpfe in Aufruhr, besonders die Kodos, die durch die Hügel streifen. Friedliche Herden werden reizbar und angriffslustig.",al={"wütende kodos","warum sind die tiere wütend"}},{q="Wo lassen sich die Spitzhacken zerschlagen?",a="Ihr könnt die Spitzhacken an einer funktionierenden Schmiede zerschlagen. Im Ausgrabungslager der Zwerge gibt es eine, und die Schmiede in Donnerfels haben eine weitere.",al={"wo ist die schmiede","prospektorenspitzhacken an schmiede zerschlagen"}},{q="Hängt diese Quest mit der weiteren Präsenz der Forscherliga in Kalimdor zusammen?",a="Ja. Zwergische Expeditionen aus Eisenschmiede unterhalten Außenposten in ganz Kalimdor, darunter in Mulgore, im Brachland und in Southern Kalimdor. Ihre Ansprüche auf Land und heiligen Boden führen oft zu Scharmützeln mit den Völkern der Horde.",al={"forscherliga mulgore","eisenschmiede in kalimdor"}}},fx={["755e231a"]={q="Wozu dienen die Zerbrochene Werkzeuge?",a="Die Zerbrochene Werkzeuge dienen als greifbarer Beweis dafür, dass Ihr die Operationen der Zwerge gestoppt habt. Anstatt die Goldsucher einfach zu vertreiben oder ihre Ausrüstung zu nehmen, möchte Baine Bluthuf, dass ihre Spitzhacken in einer Schmiede zerschlagen und zu ihm zurückgebracht werden, um sicherzustellen, dass ihre Arbeit eingestellt wird und ein deutliches Zeichen gegen die Entweihung der heiligen Erde gesetzt wird.",al={"zerbrochene werkzeuge","warum zerbrochene werkzeuge","zweck der zerbrochenen werkzeuge"}},["95107d94"]={q="Wer sind die Zwerge, die in Mulgore graben?",a="Es sind Zwergen-Goldsucher, die ein Ausgrabungslager in den nordwestlichen Hügeln von Mulgore errichtet haben. Angetrieben von Gerüchten, dass uralte Geheimnisse unter den Ebenen begraben liegen, suchen sie nach historischen Relikten und Titanenwissen, ohne sich um die spirituelle Entweihung zu scheren, die ihre Steinbrüche dem Land und seiner Tierwelt zufügen.",al={"zwerge in mulgore","wer sind die zwergengräber","goldsucher in mulgore"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="Die Jagd beginnt",s="In Camp Narache sammeln junge Jäger Nahrung und Federn für ihr Volk. Grull Falkenwind schickt Euch auf die Hochwolkenebene, um Ebenenschreiter zu jagen, denn das Dorf ist auf die Versorgung durch seine Jugend angewiesen.",h="In Camp Narache sammeln junge Jäger Nahrung und Federn für ihr Volk.",kw={"camp narache","häuptling falkenwind","federn","grull falkenwind","jagd beginnt","mulgore","ebenenschreiter","die hochwolkenebene"},ang={["class:Hunter"]="Als Jäger übt Ihr Treffsicherheit und Fährtenlesen, während Ihr die flinken Ebenenschreiter der Hochwolkenebene jagt. Ihr lernt auch, die Tiere zu ehren, die Euch ernähren.",["race:Tauren"]="Als junger shu'halo verbindet Euch Eure erste Jagd auf Ebenenschreiter auf der Hochebene mit dem Land und Eurer Pflicht, Camp Narache zu ernähren."},sec={{t="Der Unterhalt eines Stammes",b="Tauren jagen auf der Hochwolkenebene, um ihr Volk zu ernähren und zu kleiden. Sie schätzen das Pirschen und die Hetzjagd als Disziplinproben und als Sport. Wenn die Vorräte von Camp Narache knapp werden, sammeln junge Jäger Ebenenschreiterfleisch zum Kochen und Federn für Stammestrachten."},{t="Anerkennung verdienen",b="Grull Falkenwind beurteilt Neuankömmlinge, die hoffen, die Hochwolkenebene zu verlassen und in die weiten Ebenen von Mulgore aufzubrechen. Bevor sie seinen Vater, Häuptling Falkenwind, treffen dürfen, verlangt er von ihnen, ihr Können zu beweisen. Eine erfolgreiche Jagd zeugt von Eigenständigkeit und hilft, den Stamm zu versorgen."}},faq={{q="Wer vergibt diese Quest?",a="Grull Falkenwind gibt Euch diese Aufgabe in Camp Narache. Als Sohn von Häuptling Falkenwind leitet er junge Jäger auf der Hochwolkenebene an.",al={"questgeber","wer startet die jagd beginnt","grull falkenwind"}},{q="Warum werden Ebenenschreiter statt anderer Tiere gejagt?",a="Ebenenschreiter sind auf der Hochebene zahlreich. Ihr Fleisch füllt die knappen Nahrungsvorräte auf, und ihre Federn werden für traditionelle Kleidung und Schmuck der Tauren verwendet.",al={"warum ebenenschreiter","ebenenschreiterfleisch und federn","ebenenschreiter jagen"}},{q="Warum muss ich mich beweisen, bevor ich Häuptling Falkenwind treffe?",a="Grull Falkenwind verlangt von Euch grundlegende Überlebensfertigkeiten und Treue zum Dorf, bevor Ihr Häuptling Falkenwind trefft und größere Verantwortung übernehmt.",al={"warum sich vor häuptling falkenwind beweisen","häuptling falkenwinds anerkennung","warum zuerst jagen"}},{q="Was ist das übergeordnete Ziel dieser Prüfungen auf der Hochwolkenebene?",a="Die Hochwolkenebene prüft junge Tauren, bevor sie in die weiten Ebenen von Mulgore hinabsteigen und die Hauptstadt Donnerfels betreten.",al={"zweck der prüfungen auf der hochebene","warum bin ich auf der hochwolkenebene","die hochwolkenebene verlassen"}},{q="Was folgt nach dieser Jagd?",a="Nachdem Ihr Fleisch und Federn zurückgebracht habt, erkennt Grull Eure Jagd an und schickt Euch los, größeres, schwerer auffindbares Wild auf der Hochebene aufzuspüren.",al={"nächste quest","folgequest","was folgt nach die jagd beginnt"}},{q="Jagen Tauren nur zum Überleben?",a="Tauren jagen, um Nahrung und Materialien wie Leder, Knochen und Federn zu gewinnen. Sie jagen auch aus sportlichem Ehrgeiz und für spirituelle Verbundenheit. Die Jagd schärft die Instinkte, die ihre Stämme wachsam und stark halten.",al={"jagdphilosophie der tauren","jagd als sport","warum jagen tauren"}}},fx={["395288c5"]={q="Warum möchte Grull Falkenwind, dass dies erledigt wird?",a="Grull Falkenwind sieht Potenzial in Euch und möchte, dass Ihr Euren Wert vor dem Stamm und seinem Vater, Häuptling Falkenwind, beweist. Die Fleischvorräte von Camp Narache sind zur Neige gegangen und das Lager benötigt frische Federn. Indem er Euch aussendet, um sie zu ernten, testet er Euren Jagdinstinkt, während er gleichzeitig die lebensnotwendigen Vorräte des Dorfes wieder auffüllt.",al={"warum will grull ebenenschreiter jagen","beweggrund von grull falkenwind","warum ebenenschreiter für grull jagen"}},f26a5c4f={q="Wozu dient das Ebenenschreiterfleisch?",a="Das Fleisch wird gesammelt, um die schwindenden Nahrungsvorräte von Camp Narache wieder aufzufüllen. Das Überleben auf der Hochwolkenebene erfordert verlässliche Nahrung, und die Jagd auf Ebenenschreiter liefert das frische Fleisch, das benötigt wird, um die jungen Jäger und Ältesten im Lager zu ernähren.",al={"wofür wird ebenenschreiterfleisch benutzt","warum ebenenschreiterfleisch sammeln","nutzen von ebenenschreiterfleisch"}},fb1052a7={q="Wozu dient die Ebenenschreiterfeder?",a="Ebenenschreiterfedern werden von den Tauren von Camp Narache verwendet, um Kleidung und Schmuck herzustellen. Der Stamm verlässt sich auf jeden Teil der Tiere, die sie jagen, und verarbeitet robustes Gefieder zu praktischer Kleidung und Festtagsgewändern, die für das Leben auf der Mesa geeignet sind.",al={"wofür werden ebenenschreiterfedern benutzt","warum ebenenschreiterfedern sammeln","nutzen von ebenenschreiterfedern"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="Vergiftetes Wasser",s="Verseuchte Brunnen in Mulgore bedrohen das Wasser, das die Tauren und die heimische Tierwelt am Leben erhält. Mull Donnerhorn im Dorf der Bluthufe bittet junge Verteidiger der Horde, Bestandteile für ein Läuterungstotem zu sammeln.",h="Verseuchte Brunnen in Mulgore bedrohen das Wasser, das die Tauren und die heimische Tierwelt am Leben erhält.",kw={"dorf der bluthufe","läuterungstotem","mulgore","mull donnerhorn","ebenenschreiter","vergiftetes wasser","präriewolf","brunnen der winterhufe"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Goblins durch das Vergiften frischer Quellen das natürliche Gleichgewicht von Mulgore bedrohen. Ihr schützt seine empfindliche Pflanzen- und Tierwelt.",["class:Shaman"]="Als Schamane reinigt Ihr verschmutztes Wasser mit einem Totem aus Tierbestandteilen und ehrt damit den Schamanismus der Tauren und seine Verbundenheit mit der heimischen Tierwelt.",["race:Tauren"]="Als Tauren wisst Ihr, dass vergiftetes Süßwasser die Gaben der Earth Mother entweiht. Die Läuterung der Brunnen ist eine Pflicht, während Ihr in Mulgore erwachsen werdet."},sec={{t="Ein entweihtes Land",b="Goblin-Eindringlinge und ihre Handlanger haben die Brunnen von Mulgore verseucht. Die Verschmutzung bedroht das Wasser, das die Taurenstämme und die heimische Tierwelt am Leben erhält. Mull Donnerhorn, ein Ältester im Dorf der Bluthufe, hat den Schaden entdeckt. Die Tauren haben sich erst kürzlich hier niedergelassen, und diese Brunnen sind lebenswichtig für das Leben auf ihren heiligen Ebenen."},{t="Die Essenz der Natur sammeln",b="Mull greift auf den Schamanismus der Tauren zurück, um den Brunnen der Winterhufe zu läutern. Er braucht ein Ritualtotem, das mit der Kraft der heimischen Tiere von Mulgore gefertigt wird. Ihr sammelt Pfoten von Präriewölfen und Krallen von ausgewachsenen Ebenenschreitern auf den südwestlichen Ebenen. Die Kraft des Landes selbst soll gegen die Verschmutzung eingesetzt werden."}},faq={{q="Wer hat die Wasserbrunnen in Mulgore vergiftet?",a="Goblin-Eindringlinge und ihre Handlanger haben die heiligen Brunnen von Mulgore verseucht und bedrohen damit das Wasser, das die Tauren und die heimische Tierwelt am Leben erhält.",al={"wer hat die brunnen verseucht","wer hat mulgore vergiftet","wer hat das wasser verschmutzt"}},{q="Warum braucht Mull Donnerhorn Wolfspfoten und Ebenenschreiterkrallen?",a="Mull verwendet Präriewolfpfoten und Ebenenschreiterkrallen, um ein Läuterungstotem herzustellen, das in der Kraft der heimischen Tiere von Mulgore verwurzelt ist.",al={"warum wolfspfoten","warum ebenenschreiterkrallen","totemmaterialien"}},{q="Die Läuterung welches Brunnens wird mit dieser Quest vorbereitet?",a="Aus den gesammelten Bestandteilen wird ein Läuterungstotem für den Brunnen der Winterhufe hergestellt.",al={"für welchen brunnen ist das","welcher wasserbrunnen"}},{q="Wo befindet sich Mull Donnerhorn?",a="Mull Donnerhorn befindet sich im Dorf der Bluthufe, der Hauptsiedlung der Tauren im Herzen von Mulgore, nahe dem Stonebullsee.",al={"mull donnerhorn standort","wo ist mull","wo vergiftetes wasser abgeben"}},{q="Wo sind die benötigten Wölfe und Ebenenschreiter zu finden?",a="Präriewölfe und ausgewachsene Ebenenschreiter durchstreifen die Ebenen südwestlich vom Dorf der Bluthufe.",al={"wo präriewölfe finden","ebenenschreiter standort","jagdgebiete"}},{q="Was geschieht, nachdem Mull die Pfoten und Krallen erhalten hat?",a="Mull bindet die Pfoten und Krallen zu einem Läuterungstotem der Winterhufe zusammen und schickt Euch dann zum Brunnen der Winterhufe, um das Läuterungsritual durchzuführen.",al={"nächste quest nach vergiftetes wasser","was ist als nächstes zu tun"}}},fx={["50414ce1"]={q="Warum möchte Mull Donnerhorn, dass dies erledigt wird?",a="Goblins und ihre Handlanger haben die heiligen Wasserbrunnen in ganz Mulgore vergiftet und treffen damit die Lebensader der Heimat der Tauren. Für Mull Donnerhorn und die Bewohner des Dorfes der Bluthufe lädt das Belassen der Brunnen in diesem Zustand Krankheit ein und entweiht das heilige Gleichgewicht der Erde. Sie zu reinigen ist eine dringende spirituelle und praktische Pflicht.",al={"beweggrund von mull donnerhorn","warum wasserbrunnen reinigen","warum quest poison water"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="Die Überfallene Karawane",s="Nahe dem Stonebullsee zieht die Überfallene Karawane noch immer Bergungsarbeiter der Venture Company an. Taurenkrieger brannten den Konvoi nieder, nachdem sie bei einem Scharmützel Gefährten verloren hatten. Intakte Kisten zeigen das Ausmaß der Unternehmungen der Venture Company in Mulgore.",h="Nahe dem Stonebullsee zieht die Überfallene Karawane noch immer Bergungsarbeiter der Venture Company an.",kw={"morin wolkenpirscher","mulgore","überfallene karawane","stonebullsee","vorratskiste","venture company"},ang={["faction:Horde"]="Die ungehinderte Expansion des Unternehmens nach Mulgore bedroht die Stabilität von Donnerfels, weshalb Späher der Horde die Logistik der Venture Company stören müssen.",["profession:Mining"]="Die robusten Kisten und Logistikaufzeichnungen zeigen, wie die Venture Company in ganz Mulgore rücksichtslos nach mineralischen Rohstoffen sucht und sie abbaut.",["race:Tauren"]="Die Maschinen der Venture Company schänden die Ebenen, und ihre Rodungen treffen Eure angestammte Heimat unmittelbar. Ihre Vorräte zu bergen und zu zerstören hilft, Mulgore zu verteidigen."},sec={{t="Vergeltung am See",b="Taurenkrieger brannten einen Konvoi der Venture Company nieder, nachdem ein früheres Scharmützel sie zwei Gefährten gekostet hatte. Morin Wolkenpirscher und seine Krieger schlugen rasch zu und setzten dann die Wagen in Brand, um die bewaffneten Eindringlinge zu vertreiben. Sie ließen die Trümmer zurück und glaubten, das Feuer würde alles verzehren, was die Goblins hatten abtransportieren wollen."},{t="Unerledigte Angelegenheiten",b="Bergungsarbeiter der Venture Company sind zu den geschwärzten Trümmern zurückgekehrt, was darauf hindeutet, dass das Feuer nicht die gesamte Fracht vernichtet hat. Morin schickt Späher aus, um die Überreste zu untersuchen, statt blind weitere Leben zu riskieren. Intakte Kisten inmitten der rußgeschwärzten Trümmer tragen die Insignien der Venture Company Mining Division. Sie sind für den Transport zu zentralen Verarbeitungsanlagen gepackt."}},faq={{q="Warum wurde die Karawane zerstört?",a="Morin Wolkenpirscher und seine Taurenkrieger überfielen die Karawane und brannten sie als Vergeltung nieder, nachdem zwei ihrer Späher bei einem früheren Scharmützel mit der Venture Company getötet worden waren.",al={"wer hat die karawane zerstört","warum ist die karawane niedergebrannt","angriff auf die karawane"}},{q="Wo liegt die Überfallene Karawane?",a="Die ausgebrannten Wagen liegen am Nordufer des Stonebullsees, östlich vom Dorf der Bluthufe in Mulgore.",al={"standort der karawane","wo ist die karawane","standort der überfallenen karawane"}},{q="Warum kehren die Goblins zu den Trümmern zurück?",a="Die Venture Company schickte Bergungsarbeiter, weil das Feuer nicht ihre gesamte Fracht vernichtet hatte. Sie wollen robuste Vorratskisten bergen, die für den Transport zu ihren zentralen Verarbeitungsbetrieben gekennzeichnet sind.",al={"warum sind bergungsarbeiter hier","bergungsarbeiter der venture company","was wollen die goblins"}},{q="Was befindet sich in den Vorratskisten?",a="Die Kisten tragen die Insignien der Venture Company Mining Division und enthalten mineralische Rohstoffe, die zur Veredelung und Verarbeitung in den wichtigsten Industrieanlagen des Unternehmens bestimmt sind.",al={"kisteninhalt","was ist in der kiste","versiegelte vorratskiste"}},{q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Späher und Fährtenleser der Tauren, der östlich vom Dorf der Bluthufe stationiert ist. Er überwacht feindliche Vorstöße im gesamten zentralen Mulgore, insbesondere jene der Venture Company.",al={"wer ist morin","morin wolkenpirschers rolle"}},{q="Was verrät diese Karawane über die Venture Company?",a="Die Karawane zeigt, dass die Präsenz der Venture Company in Mulgore über einen bloßen Erkundungstrupp hinausgeht. Dahinter steht ein organisiertes industrielles Abbauvorhaben mit bewaffneten Nachschublinien und zentralisierten Veredelungsnetzwerken.",al={"präsenz der venture company in mulgore","warum sind goblins in mulgore"}}},fx={["89fc7cfd"]={q="Warum möchte Morin Wolkenpirscher, dass die Karawanenkisten untersucht werden?",a="Morin und seine Krieger haben den Karawanen-Konvoi der Venture Company beim Stonebullsee überfallen, um gefallene Kameraden zu rächen, die Wagen verbrannt und angenommen, dass das Feuer alles Nützliche vernichten würde. Dass Goblins als Plünderer in den Trümmern wühlten, machte ihn darauf aufmerksam, dass etwas Wertvolles oder Gefährliches die Flammen überlebt haben musste. Er braucht Euch, damit Ihr die Kisten untersucht und erfahrt, was die Venture Company durch Mulgore transportierte und warum sie so begierig darauf ist, es zurückzuholen.",al={"warum karawane untersuchen","beweggrund von morin wolkenpirscher","warum lieferkisten durchsuchen"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="Die Reise beginnt erst",s="In Orgrimmar lernen erfahrene Lederverarbeiter, wie Onyxias Schuppen vor dem Schwarzen Drachenschwarm schützen können. Oberanführer Runthak lehrt sie eine seltene Technik zur Herstellung von Umhängen gegen die Flammen der Schwarzfelsspitze.",h="In Orgrimmar lernen erfahrene Lederverarbeiter, wie Onyxias Schuppen vor dem Schwarzen Drachenschwarm...",kw={"blackrock","brutmutter","umhang","lederverarbeitung","runthak","nefarian","onyxia","schuppe"},ang={["faction:Horde"]="Für die Horde ist Schutzausrüstung aus gefallenen Feinden unerlässlich, um ihre Streitkräfte vor weiteren Verwüstungen durch Drachen zu bewahren."},sec={{t="Das Vermächtnis einer Brutmutter",b="Onyxias Fall ist ein Triumph für die Horde, doch der Schwarze Drachenschwarm bleibt eine Bedrohung. Ihre geschuppte Haut widersteht Drachenflammen. Deshalb suchen die Anführer der Horde Handwerker, die die Überreste des Drachen zu schützender Rüstung verarbeiten können, statt sie verkommen zu lassen."},{t="Schutz vor Schattenflammen",b="Oberanführer Runthak lehrt begabte Lederverarbeiter, den Onyxiaschuppenumhang zu nähen. Seine Unterweisung dient weder bloß der Zurschaustellung noch als Zeichen von Prestige. Tief im Schwarzfels speit Onyxias Bruder Nefarian verheerendes Feuer. Ohne den verzauberten Schutz der Schuppen ihrer Brutmutter würde jede Vorhut, die sich dem Lord of Blackrock stellt, zu Asche verbrennen."}},faq={{q="Wer bietet diese Quest an und wo ist diese Person zu finden?",a="Oberanführer Runthak bietet diese Quest in Orgrimmar an. Er würdigt die Champions der Horde, die meisterhafte Lederverarbeitung beherrschen und zu Onyxias Niederlage beigetragen haben.",al={"runthak questgeber","wo ist oberanführer runthak","questbeginn"}},{q="Welche Voraussetzung muss erfüllt sein, um diese Quest zu erhalten?",a="Nur erfahrene Lederverarbeiter, die die Ereignisse nach Onyxias Niederlage abgeschlossen haben, können diese Quest erhalten, etwa nach Abschluss von 'Victory for the Horde' oder 'A Most Puzzling Circumstance'.",al={"lederverarbeitung voraussetzung","wie die quest erhalten","voraussetzungen"}},{q="Was lehrt Oberanführer Runthak?",a="Oberanführer Runthak lehrt Lederverarbeiter, den Onyxiaschuppenumhang aus Schuppen der gefallenen Brutmutter herzustellen.",al={"questbelohnung rezept","onyxia umhang muster","was wird erlernt"}},{q="Warum ist der Onyxiaschuppenumhang wichtig?",a="Der Umhang schützt seinen Träger vor Nefarians tödlichem, sengendem Atem. Ohne seinen einzigartigen Schutz wäre eine Begegnung mit dem Meister der Brut tödlich.",al={"warum den umhang herstellen","zweck des umhangs","nefarian umhang"}},{q="Wer ist der Lord of Blackrock?",a="Nefarian ist der Lord of Blackrock, ein mächtiger schwarzer Drache und Onyxias Bruder. Von den Höhen des Schwarzfels aus schmiedet er Pläne, die sterblichen Völker zu unterwerfen.",al={"wer ist der lord of blackrock","nefarian identität","lord of blackrock"}},{q="Warum heißt es in der Quest, dass die Reise erst begonnen hat?",a="Onyxia wurde erschlagen, doch der größere Krieg gegen den Schwarzen Drachenschwarm und Nefarians Machenschaften im Schwarzfels hat sich nur verschärft.",al={"bedeutung des titels","warum die reise erst beginnt"}}},fx={cb1b5404={q="Warum möchte Oberanführer Runthak dies erledigt haben?",a="Oberanführer Runthak strebt die vollständige Vernichtung des Schwarzen Drachenschwarms an. Zwar war Onyxias Niederlage ein gewaltiger Triumph, doch ihre Brut sucht das Reich unter dem Befehl ihres Bruders Nefarian noch immer heim. Indem er die uralte Technik lehrt, schützende Umhänge aus den Schuppen der Brutpflegerin zu schmieden, stellt Runthak sicher, dass die Streiter der Horde über die lebenswichtige Verteidigung verfügen, die erforderlich ist, um Nefarians tödlicher Schattenglamme standzuhalten und den Krieg zu beenden.",al={"warum gibt runthak diese quest","oberanfuehrer runthak motiv","runthak ziel"}}},fp="26,199,22.250.0,27.344.1,49.139.0,49.183.0,33.118.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="Die Reise beginnt erst",s="In Sturmwind ehrt Major Mattingly den Handwerker, der Onyxia zu Fall brachte. Er lehrt ihn, aus ihren Schuppen einen Umhang zu fertigen.",h="In Sturmwind ehrt Major Mattingly den Handwerker, der Onyxia zu Fall brachte.",kw={"schwarzer drachenschwarm","blackrock","lederverarbeitung","major mattingly","nefarian","onyxia","onyxiaschuppenumhang","sturmwind"},ang={["faction:Alliance"]="Als Held der Allianz tragt Ihr Sturmwinds Sieg über Onyxia in die bevorstehende Offensive gegen ihren Bruder Nefarian am Schwarzfels."},sec={{t="Seltene Meisterschaft",b="Nur wenige, die halfen, Onyxia zu Fall zu bringen, können ihre Haut verarbeiten. Wenn ein Meister der Lederverarbeitung zu Major Mattingly nach Sturmwind kommt, erkennt der Offizier, wie wichtig diese Fertigkeit in kommenden Schlachten sein könnte."},{t="Schutz vor dem Schwarzen Drachenschwarm",b="Auch nach Onyxias Tod bleibt der Schwarze Drachenschwarm eine Bedrohung. Major Mattingly lehrt den Handwerker, ihre Schuppen zu behandeln und zu einem Onyxiaschuppenumhang zu vernähen. Er schützt vor dem feurigen Atem ihres Bruders Nefarian, dem Lord of Blackrock."}},faq={{q="Wer bietet die Quest Die Reise beginnt erst an?",a="Major Mattingly in Sturmwind bietet dieses Wissen Helden der Allianz an, die im Feldzug gegen Onyxia gekämpft haben und die Lederverarbeitung meistern.",al={"wer vergibt die reise beginnt erst","wo gibt es die reise beginnt erst","questgeber die reise beginnt erst"}},{q="Was lehrt diese Quest?",a="Major Mattingly lehrt Meister der Lederverarbeitung, aus Onyxias Schuppen einen Onyxiaschuppenumhang herzustellen.",al={"welches rezept gibt es","onyxia umhang rezept","belohnung für die reise beginnt erst"}},{q="Warum ist der Onyxiaschuppenumhang notwendig?",a="Der Onyxiaschuppenumhang schützt seinen Träger vor dem feurigen Atem von Nefarian, dem Lord of Blackrock.",al={"warum wird der onyxia umhang benötigt","wofür ist der onyxiaschuppenumhang","schutz vor schattenflammen"}},{q="Wer ist der Lord of Blackrock, den Major Mattingly erwähnt?",a="Nefarian ist der Lord of Blackrock, ein mächtiger schwarzer Drache und Onyxias Bruder. Er herrscht über die Schwarzfelsspitze und führt die Ränke des Schwarzen Drachenschwarms fort.",al={"wer ist lord of blackrock","wer ist nefarian","mattinglys drachenwarnung"}},{q="Warum muss der Held Lederverarbeiter sein, um dieses Wissen zu erhalten?",a="Ein Meister der Lederverarbeitung besitzt die nötigen fortgeschrittenen Fertigkeiten, um Drachenschuppen zu bearbeiten, ohne ihre magische Schutzwirkung zu zerstören.",al={"warum nur lederverarbeitung","kann jeder diese quest erhalten","voraussetzung lederverarbeiter"}},{q="Beendet Onyxias Tod die Bedrohung durch schwarze Drachen in Sturmwind?",a="Nein. Onyxia ist tot, doch ihr Bruder Nefarian herrscht weiterhin über den Schwarzfels und schmiedet Pläne gegen die Allianz und die sterblichen Völker.",al={"ist sturmwind jetzt sicher","onyxia tot was nun","schwarzer drachenschwarm nach onyxia"}}},fx={b42a6800={q="Warum bietet Euch Major Mattingly dieses Wissen an?",a="Major Mattingly weiß, dass das Töten von Onyxia nur der erste Schlag war. Die Brutmutter ist tot, aber ihre Verwandten bedrohen Azeroth immer noch von den Höhen des Schwarzfels. Um den verbleibenden Schwarzer Drachenschwarm zu eliminieren, müssen Champions die sengenden Flammen von Nefarian selbst überleben. Mattingly teilt diese spezielle Technik, damit die Helden der Allianz schützende Umhänge aus Onyxias Schuppen anfertigen und den Krieg beenden können.",al={"warum bringt mattingly es euch bei","beweggrund von major mattingly","grund von mattingly"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="Die Legende von Stalvan",s="In Elwynn führt Euch die Suche nach der Legende von Stalvan zum Haus von Marschall Haggard. Wegen seiner nachlassenden Sehkraft blieben die Papiere in einer Truhe im Obergeschoss ungelesen.",h="In Elwynn führt Euch die Suche nach der Legende von Stalvan zum Haus von Marschall Haggard.",kw={"dämmerwald","wald von elwynn","verblasste tagebuchseite","unglückseliger geist","marshal haggard","stalvan"},ang={["faction:Alliance"]="Die Suche nach Stalvans Vergangenheit führt Euch in die düstere Geschichte, die sich in Elwynns friedlichem Ackerland verbirgt.",["race:Human"]="Als Mensch folgt Ihr Stalvan durch vertraute Siedlungen und seht, wie sich Einsamkeit und Bosheit vor aller Augen verbergen können."},sec={{t="Der Dachboden eines Veteranen",b="Marschall Haggard lebt nahe dem südöstlichen Rand des Waldes von Elwynn, unweit vom Dämmerwald und dem Rotkammgebirge. Im Obergeschoss steht eine alte Truhe mit Pergamenten, die er beim Einzug in sein abgelegenes Heim fand. Seine nachlassende Sehkraft hinderte ihn daran, sie zu lesen, und sie blieben unberührt, bis Ihr nach Stalvan fragt."},{t="Verweilende Schatten",b="Die Papiere in Haggards Truhe im Obergeschoss wecken eine ruhelose Macht, die mit Stalvans Vergangenheit verbunden ist. Wenn Ihr seine Habseligkeiten aufwühlt, erscheint ein Unglückseliger Geist. Unter den Papieren trägt eine Tagebuchseite Stalvans eigene Worte und zeigt, dass der zurückgezogen lebende Gelehrte vor seinem Verschwinden Spuren in Elwynn hinterließ."}},faq={{q="Wer ist Marschall Haggard?",a="Marschall Haggard ist ein alternder Veteran, der in einer abgelegenen Hütte im Südosten des Waldes von Elwynn lebt. In seinem Heim liegen alte Papiere, die Stalvan Dunstmantel gehörten.",al={"marshal haggard","haggard elwynn","wer ist haggard"}},{q="Warum führte die Spur zurück in den Wald von Elwynn?",a="Hinweise aus Dunkelhain und Mondbruch zeichnen Stalvans Reisen durch das südliche Gebiet von Sturmwind nach. In Haggards Heim liegen Papiere, die Stalvan zurückließ.",al={"warum wald von elwynn","stalvan elwynn","warum zu haggard gehen"}},{q="Was befindet sich in der Truhe im Obergeschoss?",a="Die Truhe im Obergeschoss enthält eine verblasste Tagebuchseite von Stalvan Dunstmantel, zwischen Pergamenten, die Haggard nie richtig untersuchen konnte.",al={"truhe im obergeschoss","verblasste tagebuchseite","was ist in der truhe"}},{q="Warum greift ein Geist an, wenn die Truhe geöffnet wird?",a="Ein Unglückseliger Geist sucht Relikte aus Stalvans Vergangenheit heim. Er greift an, wenn ein Außenstehender seine Schriften und Erinnerungen aufwühlt.",al={"unglückseliger geist","warum greift der geist an","geist in haggards haus"}},{q="Wie bringt dies die Ermittlungen zu Stalvan voran?",a="Die verblasste Seite liefert Beweise aus erster Hand in Stalvans eigener Handschrift und hilft Euch, seine Vergangenheit zusammenzusetzen.",al={"stalvans geheimnis","was enthüllt die seite","schritt der stalvan-questreihe"}},{q="Warum konnte Marschall Haggard die Papiere nicht selbst lesen?",a="Das Alter hat Haggards Sehkraft geschwächt und seinen Blick getrübt. Er konnte die kleine, verwitterte Schrift auf den verblassten Papieren nicht lesen.",al={"haggard blind","warum braucht haggard hilfe"}}},fx={["7284e072"]={q="Warum möchte Marschall Haggard, dass dies erledigt wird?",a="Marschall Haggard ist ein alter Soldat, der im ruhigen Ruhestand lebt, aber er trägt immer noch die Instinkte eines Offiziers des Reiches in sich. Als Ihr kommt, um die Wahrheit über Stalvan Dunstmantel zu erfahren, erinnert er sich an die weggeworfenen Pergamente, die in der Truhe lagen, als er das Haus übernahm. Obwohl er kein persönliches Interesse an dem dunklen Geheimnis hat, möchte er Eure Ermittlungen so gut er kann unterstützen – auch wenn sein nachlassendes Augenlicht ihn daran hindert, die Papiere selbst zu untersuchen.",al={"warum haggard helfen","beweggrund von marshal haggard","warum will haggard das journal"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="Die Jagd geht weiter",s="Grull Falkenwind schickt junge Jäger in die südlichen Hügel der Hochwolkenebene, um Bergcougarpelze zu beschaffen. Die Felle sollen die Kinder des Stammes kleiden und helfen, seine Zelte auszubessern.",h="Grull Falkenwind schickt junge Jäger in die südlichen Hügel der Hochwolkenebene, um Bergcougarpelze zu...",kw={"camp narache","häuptling falkenwind","grull falkenwind","bergcougarpelze","die hochwolkenebene","jagd der tauren","die jagd geht weiter"},ang={["class:Hunter"]="Als Jäger lernt Ihr die Jagdweise der Ebenen: Pirscht Euch mit Bedacht an Tiere heran, nehmt nur das Nötige und betrachtet sie niemals als Zeitvertreib oder Trophäen.",["race:Tauren"]="Als junger Taure, der auf der Hochwolkenebene erwachsen wird, lernt Ihr, jeden Teil eines Tieres für den Stamm zu nutzen, von Nahrung über Kleidung bis zur Unterkunft. Dies ist ein wesentlicher Übergangsritus."},sec={{t="Der Zweck der Jagd",b="In Camp Narache schickt Grull Falkenwind junge Jäger nach Süden in die Hügel der Hochwolkenebene, um Bergcougars zu jagen. Hier geht es nicht um Trophäen. Die Jagd lehrt junge Jäger, für ihre Gemeinschaft zu sorgen."},{t="Schutz für den Stamm",b="Camp Narache braucht die Pelze, um Kleidung für die Kinder des Stammes herzustellen und abgenutzte Fellzelte auszubessern. Wenn Ihr sie zurückbringt, werden die Ältesten Euch für Euren Beitrag dankbar sein. Grull verspricht, seinem Vater, Häuptling Falkenwind, von Euren Taten zu berichten."}},faq={{q="Warum braucht der Stamm Bergcougarpelze?",a="Der Stamm braucht Bergcougarpelze, um Kleidung für seine Kinder herzustellen und die Dorfzelte in Camp Narache auszubessern. Grull Falkenwind sagt, dass die Felle für beides gebraucht werden.",al={"warum cougars jagen","wofür sind cougarpelze","verwendung von bergcougarpelzen"}},{q="Wer vergibt diese Quest?",a="Grull Falkenwind vergibt die Jagd in Camp Narache. Er ist ein angesehener Jäger und der Sohn von Häuptling Falkenwind, und er leitet junge Jäger dazu an, die Siedlung zu unterstützen.",al={"wer vergibt die jagd geht weiter","questgeber camp narache"}},{q="Wo sind die Bergcougars zu finden?",a="Bergcougars durchstreifen die Hügel südlich von Camp Narache auf der Hochwolkenebene.",al={"wo sind die cougars","bergcougars fundort","wo bergcougars finden"}},{q="In welcher Beziehung steht Grull Falkenwind zu Häuptling Falkenwind?",a="Grull Falkenwind ist der Sohn von Häuptling Falkenwind, dem Stammesführer in Camp Narache. Grull verspricht, mit seinem Vater über Eure Taten zu sprechen, wenn Ihr die benötigten Pelze bringt.",al={"wie häuptling falkenwind beeindrucken","häuptling falkenwinds sohn"}},{q="Was lehrt diese Jagd über die Tradition der Tauren?",a="Bei den Tauren ist die Jagd weder Zeitvertreib noch eine Suche nach Trophäen. Fell, Fleisch und Knochen eines Tieres zum Wohl der Gemeinschaft zu nutzen, ehrt die Ebenen und hilft dem Stamm zu überleben.",al={"jagdphilosophie der tauren","warum in mulgore jagen"}},{q="Warum gelten Bergcougarpelze als besonders wertvoll?",a="Bergcougarpelze sind dick und strapazierfähig und trotzen den Elementen auf den Ebenen. Sie wärmen die Kinder und helfen, Behausungen auszubessern, weshalb die Dorfältesten sie schätzen.",al={"sind cougarpelze wertvoll","warum werden cougarpelze geschätzt"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="Die Überfallene Karawane",s="In Mulgore liefert die Überfallene Karawane den Spähern der Bluthufe Beweise für einen illegalen Stützpunkt im Gebiet der Tauren. Die Venture Company plündert die Bodenschätze des Landes, und die Späher bereiten sich darauf vor, ihre angestammten Ebenen zu verteidigen.",h="In Mulgore liefert die Überfallene Karawane den Spähern der Bluthufe Beweise für einen illegalen Stützpunkt...",kw={"dorf der bluthufe","morin wolkenpirscher","mulgore","späher","überfallene karawane","vorratskiste","venture company","dokumente der venture company"},ang={["class:Druid"]="Als Druide ist Euch das Gleichgewicht des Landes heilig. Der zerstörerische, raucherfüllte Tagebau der Venture Company ist eine Entweihung, deren Spuren getilgt werden müssen.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass ihre Sicherheit von Mulg ores Treue und Stabilität abhängt. Fremde Handelskartelle, die seine Hügel verwüsten, bedrohen Donnerfels selbst.",["profession:Mining"]="Als Bergmann erkennt Ihr, dass die hochwertigen Erze in der Kiste reiche unterirdische Adern unter Mulg ores östlichen Hügeln belegen, die Fremde zur Ausbeutung anlocken.",["race:Tauren"]="Als Tauren mögt Ihr die groben Maschinen, die Mulg ores angestammte Ebenen aufreißen, als Frevel an der Earth Mother und Kriegserklärung gegen Euren neu gewonnenen Frieden ansehen."},sec={{t="Beweise der Ausbeutung",b="Östlich vom Dorf der Bluthufe liegt eine überfallene Karawane am Straßenrand. In einer versiegelten Vorratskiste befinden sich abgebautes Erz und Mineralien sowie ein zusammengebundenes Bündel Dokumente der Venture Company. Die Papiere beweisen, dass die Firma ohne Erlaubnis tief in den friedlichen Tälern von Mulgore mit dem Bergbau begonnen hat."},{t="Die Wacht der Späher",b="Morin Wolkenpirscher und seine Spähergefährten bewachen Mulg ores Grenzen mit großer Sorgfalt. Sie fürchten, dass fremde Fraktionen ihre friedliche Heimat ausbeuten werden. Als Morin die geborgenen Dokumente erhält, bestätigen sie seine schlimmsten Befürchtungen. Rauch über den östlichen Ausläufern kündet von einer sich ausweitenden Handelsinvasion. Die Tauren müssen die Schänder zurückdrängen, bevor ihre Hügel vollständig ausgehöhlt sind."}},faq={{q="Was befindet sich in der versiegelten Vorratskiste?",a="Die versiegelte Vorratskiste enthält abgebautes Erz und rohe Mineralien neben einem zusammengebundenen Bündel Dokumente der Venture Company, die ihre Tätigkeiten beschreiben.",al={"beute der vorratskiste","was ist in der kiste","kisteninhalt"}},{q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Taurenspäher, der an der Straße östlich vom Dorf der Bluthufe in Richtung der Grenze zum Brachland stationiert ist. Er patrouilliert durch Mulgore und spürt Bedrohungen von außen auf.",al={"wer ist morin","morin wolkenpirschers aufgabe","späher morin"}},{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company will Mulg ores natürliche Ressourcen und Erzadern ausbeuten und gräbt sich ohne Rücksicht auf die Erde oder ihre Bewohner in die Hügel.",al={"warum sind goblins hier","venture company ziel mulgore","was wollen die goblins"}},{q="Woher kam die Karawane?",a="Die Karawane gehörte der Venture Company. Sie transportierte abgebautes Erz und Betriebsunterlagen von den Anlagen der Firma in den Ausläufern ab, bevor sie auf dem Weg zerstört wurde.",al={"wem gehörte die karawane","herkunft der karawane","wer hat die karawane angegriffen"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Mit den Dokumenten in der Hand schickt Morin Wolkenpirscher Krieger los, um die Führung der Venture Company zu stellen und ihren Bergbaubetrieb in den östlichen Ausläufern stillzulegen.",al={"what comes next","nächste quest nach überfallene karawane","weitere untersuchung der karawane"}},{q="Warum bedroht das die Tauren?",a="Den Tauren ist das Land heilig, und sie verehren die Earth Mother. Der rücksichtslose Tagebau und die industrielle Verschmutzung durch die Venture Company entweihen Mulg ores unberührte Landschaft.",al={"warum kümmert das die tauren","bedrohung durch die venture company","bedrohung für mulgore"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="Eine bescheidene Bitte",s="Auf der Hochwolkenebene bittet Häuptling Falkenwind einen jungen Abenteurer, nach seiner Mutter zu sehen. Dringende Stammesangelegenheiten halten ihn in Camp Narache fest, also schickt er Euch nach Südosten zu dem Brunnen, wo Großmutter Falkenwind Wasser holen wollte.",h="Auf der Hochwolkenebene bittet Häuptling Falkenwind einen jungen Abenteurer, nach seiner Mutter zu sehen.",kw={"eine bescheidene bitte","camp narache","häuptling falkenwind","großmutter falkenwind","mulgore","die hochwolkenebene","wasserbrunnen"},ang={["faction:Horde"]="Naraches ruhige, ländliche Pflichten zeigen die gemeinschaftliche Lebensweise der Tauren vor dem Hintergrund des härteren Überlebenskampfes innerhalb der noch jungen Horde.",["race:Tauren"]="Für junge Taurenkrieger zeigt das Befolgen des Häuptlingsrufs Respekt vor den Ältesten und Einsatz für das gemeinsame Wohlergehen des Stammes, wie es die Earth Mother lehrt."},sec={{t="Gemeinschaftliche Harmonie und Pflicht",b="Von jedem Stammesmitglied wird erwartet, zur Harmonie beizutragen und seinen Teil zu leisten. Für junge Tauren beginnt die Pflicht mit der Fürsorge für die Gemeinschaft, nicht allein mit dem Kampfgeschick gegen Borstennacken oder Raubtiere. Häuptling Falkenwind ist durch die Führung und Verteidigung des Lagers an seinen Posten gebunden. Deshalb vertraut er darauf, dass junge Abenteurer über die Ältesten wachen."},{t="Der Brunnen südöstlich von Narache",b="Die Brunnen außerhalb des Lagers versorgen die Hochwolkenebene mit Wasser. Großmutter Falkenwind verließ Camp Narache früh am Morgen, um frisches Wasser aus einer Quelle südöstlich des Lagers zu holen. Revierverteidigende Wildtiere und Bristleback-Borstennacken durchstreifen das Land. Wenn eine Älteste stundenlang fortbleibt, wird Häuptling Falkenwind besorgt und schickt Euch los, um sicherzugehen, dass sie unversehrt ist."}},faq={{q="Wer vergibt diese Quest und wo finde ich diese Person?",a="Häuptling Falkenwind, der Anführer von Camp Narache auf der Hochwolkenebene in Mulgore, vergibt die Aufgabe. Er befindet sich im zentralen Pavillon des Lagers und kümmert sich um die örtlichen Angelegenheiten.",al={"wer vergibt eine bescheidene bitte","wo quest annehmen","häuptling falkenwind standort"}},{q="Wo befindet sich Großmutter Falkenwind?",a="Großmutter Falkenwind befindet sich am Wasserbrunnen direkt südöstlich von Camp Narache, im tiefer gelegenen Teil der Hochebene.",al={"großmutter falkenwind standort","wo ist die mutter","wasserbrunnen standort"}},{q="Warum sieht Häuptling Falkenwind nicht selbst nach seiner Mutter?",a="Häuptling Falkenwind muss in Camp Narache bleiben, um dringende Stammesangelegenheiten zu regeln und junge Kämpfer anzuleiten. Als Häuptling vertraut er darauf, dass der Stamm für seine Mitglieder sorgt, und verlässt sich auf junge Abenteurer, die sich an seiner Stelle um Dorfangelegenheiten kümmern.",al={"warum kann der häuptling nicht gehen","warum sieht falkenwind nicht nach","häuptling falkenwind beschäftigt"}},{q="Ist Großmutter Falkenwind am Brunnen in Gefahr?",a="Aggressive Bergpumas und Schreiter durchstreifen die umliegenden Ebenen, doch Großmutter Falkenwind ist neben dem Brunnen in Sicherheit. Sie ist angenehm überrascht, dass jemand den Weg auf sich genommen hat, um nach einer Ältesten zu sehen.",al={"ist sie in sicherheit","wird großmutter angegriffen","gefahr am wasserbrunnen"}},{q="Welche kulturelle Bedeutung hat diese Quest für die Tauren?",a="Die Kultur der Tauren schätzt Familie, eine enge Gemeinschaft und Respekt vor den Ältesten. Junge Helden lernen, dass Stärke im bescheidenen Dienst und im Schutz ihrer Angehörigen liegt, nicht im Streben nach persönlichem Ruhm.",al={"taurenkultur eine bescheidene bitte","warum ist dies eine bescheidene bitte","älteste der tauren"}},{q="Was geschieht, nachdem ich Großmutter Falkenwind gefunden habe?",a="Nachdem Ihr mit Großmutter Falkenwind gesprochen habt, bittet sie Euch um weitere Hilfe dabei, die gefüllte Wasserkanne zurück ins Lager zu tragen.",al={"nächste quest","eine bescheidene bitte folgequest","was tun nachdem die mutter gefunden wurde"}}},fx={b1d313d3={q="Warum möchte Häuptling Falkenwind, dass Ihr nach seiner Mutter seht?",a="Seine betagte Mutter verließ Camp Narache früh am Morgen, um Wasser aus dem Brunnen im Südosten zu holen, und sie ist schon sehr lange fort. Das Leben der Tauren beruht auf gemeinschaftlicher Verantwortung und gegenseitiger Fürsorge, und obwohl sich Falkenwind um ihr Wohlergehen sorgt, halten ihn seine Pflichten als Häuptling im Lager fest.",al={"warum will falkenwind das erledigt haben","beweggrund von häuptling falkenwind","warum nach großmutter falkenwind sehen"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="Eine bescheidene Bitte",s="Auf der Hochwolkenebene tragen junge Tauren auf Großmutter Falkenwinds Bitte Brunnenwasser nach Camp Narache. Die Arbeit lehrt Demut und Fürsorge für den Stamm.",h="Auf der Hochwolkenebene tragen junge Tauren auf Großmutter Falkenwinds Bitte Brunnenwasser nach Camp Narache.",kw={"camp narache","häuptling falkenwind","großmutter falkenwind","eine bescheidene bitte","mulgore","die hochwolkenebene","rites of the earthmother","wasserkanne"},ang={["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie die Familie Falkenwind den Tauren Zusammenhalt und Überleben in Mulgore vermittelt, einem friedlichen, doch standhaften Teil von Thralls Horde.",["race:Tauren"]="Als Tauren zeigt Ihr durch das Wassertragen für Eure Ältesten Fürsorge für die Gemeinschaft und Bereitschaft, den Pfad der Erdenmutter zu beschreiten."},sec={{t="Die Lebenskraft der Jugend",b="Großmutter Falkenwind geht ihren Pflichten am Brunnen am südlichen Rand der Hochwolkenebene nach. Das Alter hat sie langsamer werden lassen, doch sie ist viele Pfade durch die Ebenen gewandert. Wenn junge Tauren, die ihr Volk verteidigen wollen, ihr begegnen, lenkt sie deren Tatkraft auf die Bedürfnisse der Gemeinschaft. Im Dienst können sie sich beweisen, indem sie für andere sorgen."},{t="Dienst am Stamm",b="Ihr tragt eine gefüllte Kanne nach Nordwesten zu Camp Narache und übergebt sie Häuptling Falkenwind, dem Anführer der Siedlung und Sohn von Großmutter Falkenwind. In den trockenen Ebenen von Mulgore hängt das Leben von gemeinsamer Arbeit und einer stetigen Versorgung mit frischem Wasser ab. Einem älteren Stammesmitglied eine Last abzunehmen, zeigt Respekt vor jenen, deren Fürsorge den Stamm zusammenhält."},{t="Ein Pfad nach Donnerfels",b="Wenn Ihr das Wasser seiner Mutter nach Camp Narache bringt, sieht Häuptling Falkenwind darin mehr als eine erledigte Pflicht. Der Brauch der Tauren verlangt von jenen, die in fernen Ländern für ihr Volk eintreten wollen, mit Demut und Hilfsbereitschaft zu beginnen. Eure stille Disziplin fällt dem Häuptling auf. Er empfiehlt Euch für die Rites of the Earthmother, spirituelle Prüfungen, die die Tore nach Donnerfels öffnen."}},faq={{q="Wer ist Großmutter Falkenwind?",a="Großmutter Falkenwind ist eine Älteste der Familie Falkenwind, die den Brunnen auf der Hochwolkenebene betreut. Sie ist die Mutter von Häuptling Falkenwind und lehrt junge Tauren Demut und Fürsorge für ihren Stamm.",al={"großmutter falkenwind","wer vergibt eine bescheidene bitte","älteste falkenwind"}},{q="Wo befindet sich der Brunnen?",a="Der Brunnen liegt südöstlich von Camp Narache auf den grasbewachsenen Ebenen der Hochwolkenebene. Daneben stehen Kannen mit frischem Wasser bereit, die Reisende und jene, die das Lager versorgen, zurücktragen können.",al={"standort des brunnens","wo ist der brunnen","wasserkanne finden"}},{q="Wer ist Häuptling Falkenwind?",a="Häuptling Falkenwind führt Camp Narache auf der Hochwolkenebene. Er leitet die Ausbildung und die spirituellen Riten junger Tauren, die sich darauf vorbereiten, dem gesamten Stamm in Mulgore zu dienen.",al={"häuptling falkenwind","wer ist der häuptling","anführer von camp narache"}},{q="Warum gilt diese Pflicht als wichtige Prüfung?",a="Tauren schätzen Demut, Fürsorge für die Gemeinschaft und Respekt vor den Ältesten. Alltägliche Pflichten zeigen, dass Euch Euer Volk ebenso am Herzen liegt wie Euer eigener Ruhm im Kampf.",al={"warum wasser tragen","warum eine bescheidene bitte","ist diese quest wichtig"}},{q="Was folgt nach dem Abschluss von Eine bescheidene Bitte?",a="Nachdem Ihr das Wasser getragen habt, verweist Häuptling Falkenwind Euch auf die Rites of the Earthmother, traditionelle Herausforderungen für heranwachsende Tauren.",al={"what comes next","nächste quest","nach einer bescheidenen bitte"}},{q="Wohin führt dieser Pfad schließlich?",a="Der Respekt der Ältesten bereitet Euch darauf vor, die Hochwolkenebene zu verlassen und durch Mulgore nach Donnerfels zu reisen, zu den hohen Tafelbergen der Hauptstadt.",al={"späteres reiseziel","wohin geht es","ziel donnerfels"}}},fx={["57bce500"]={q="Warum möchte Großmutter Falkenwind, dass dies erledigt wird?",a="Großmutter Falkenwind gibt zu, dass ihren alternden Beinen die frühere Kraft fehlt, was einfache tägliche Aufgaben rund um die Hochwolkenebene langsam und ermüdend macht. Wichtiger noch, sie betrachtet diesen routinemäßigen Botengang als eine wichtige moralische Lektion für Euch. Das Liefern von lebensnotwendigem Trinkwasser an ihren Sohn, Häuptling Falkenwind, dient als erste Prüfung, um zu sehen, ob Ihr die Bescheidenheit, Geduld und den Gemeinschaftsgeist besitzt, die von einem wahren Diener des Stammes erwartet werden.",al={"beweggrund von großmutter falkenwind","warum wasser zu häuptling falkenwind bringen","warum eine demütige aufgabe"}},b511fd77={q="Wozu dient die Wasserkanne?",a="Die Wasserkanne ist ein einfaches Tongefäß, das frisch aus dem Brunnen auf der Hochwolkenebene geschöpft wurde, um Camp Narache mit sauberem Wasser zu versorgen. Der Transport testet Eure Hingabe zu gemeinschaftlichen Aufgaben und stellt sicher, dass selbst angehende Abenteurer den Wert der Unterstützung ihrer Verwandten lernen, bevor sie nach größerem militärischen Ruhm streben.",al={"zweck der wasserkanne","warum wasserkanne","was ist die kanne"}},["19ad5d96"]={q="Warum bittet Großmutter Falkenwind Euch, anstatt es selbst zu tun?",a="Großmutter Falkenwind ist alt und gibt zu, dass ihre Beine nicht mehr die frühere Kraft haben, was bedeutet, dass das Tragen schwerer Kannen sie weitaus mehr Zeit kostet als früher. Wenn ein körperlich fähiger Neuling wie Ihr sich ihr nähert, ergreift sie die Gelegenheit, sowohl ihre eigene Last zu erleichtern als auch Eure Bereitschaft zu testen, unglamouröse, alltägliche Arbeit für das Lager zu verrichten.",al={"warum nicht großmutter","warum mich um wasser bitten","warum kann falkenwind kein wasser holen"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="Winterhufsäuberung",s="Der Brunnen der Winterhufe in Mulgore wurde verunreinigt. Mull Donnerhorn gibt Euch im Dorf der Bluthufe ein geweihtes Totem, um ihn zu reinigen. Die Arbeiten der Goblins haben die nahen Quellen verseucht, und die Reinigung dieses Brunnens ist der erste Schritt zur Heilung der Gewässer im zentralen Mulgore.",h="Der Brunnen der Winterhufe in Mulgore wurde verunreinigt.",kw={"dorf der bluthufe","säuberung","mulgore","mull donnerhorn","gift","totem","venture company","wasserbrunnen","winterhuf"},ang={["class:Druid"]="Als Druide seht Ihr, wie durstige Wildtiere zur gereinigten Quelle zurückkehren. Ihre Rückkehr zeigt, warum die Natur überall dort Heilung braucht, wo die Zivilisation sie bedroht.",["class:Shaman"]="Als Schamane leitet Ihr Geister durch Totems, um industrielle Verderbnis zu reinigen und Euren Bund mit den elementaren Wassern zu ehren.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Frischwasserversorgung des Taurenherzlands zu sichern, eines südlichen Pfeilers der jungen Horde.",["race:Tauren"]="Als Taure kennt Ihr Mulg ores Brunnen als heilige, lebensspendende Gaben der Erdenmutter. Sie vor der Gier der Goblins zu schützen, ist sowohl eine Pflicht gegenüber Eurem Volk als auch eine heilige Verpflichtung."},sec={{t="Ein geschändetes Land",b="Mulg ores grasbewachsene Ebenen sind auf die Brunnen der Ahnen angewiesen, um Wild und verstreute Taurenstämme zu versorgen. Die Venture Company hat kürzlich ihre Industriesöldner in die Hügel südöstlich des Dorfes der Bluthufe gebracht. Ihre Arbeiten haben das örtliche Grundwasser verseucht und den Brunnen der Winterhufe vergiftet. Wilde Tiere meiden sein Wasser, und den nahen Lagern droht Gefahr, wenn sich die Verderbnis durch das Erdreich ausbreitet."},{t="Das Ritual der Wasserreinigung",b="Mull Donnerhorn schnitzt ein Reinigungstotem und segnet es im Namen der Erdenmutter. Bewaffnete Schläger der Venture Company haben die Quelle besetzt, also müsst Ihr Euch ihnen stellen, um den Brunnen zu erreichen. Stellt das Totem an seiner Fassung auf, und es wird die verseuchten Abwässer vertreiben. Dann kann sauberes Wasser aus den Tiefen der Erde aufsteigen."}},faq={{q="Wo liegt der Brunnen der Winterhufe?",a="Der Brunnen der Winterhufe liegt in den Hügeln südöstlich des Dorfes der Bluthufe in Mulgore. Goblinarbeiter und Söldner der Venture Company patrouillieren in der Nähe.",al={"brunnen der winterhufe standort","wo ist der brunnen der winterhufe","brunnen der winterhufe finden"}},{q="Warum wurde der Brunnen vergiftet?",a="Die Venture Company begann in der Nähe mit Bergbau und Grabungen. Giftige Abwässer und Abfälle sickerten ins Grundwasser, sodass die Quelle für heimische Wildtiere und Tauren nicht mehr als Trinkwasserquelle geeignet war.",al={"wer hat das wasser vergiftet","warum ist der brunnen verschmutzt","venture company brunnen"}},{q="Wer ist Mull Donnerhorn?",a="Mull Donnerhorn ist ein spiritueller Ältester im Dorf der Bluthufe, der ein tiefes Gespür für die Gesundheit der Erde hat. Er fertigt zeremonielle Totems, um die Schäden durch fremde Eindringlinge zu heilen.",al={"wer ist mull","mull donnerhorn rolle"}},{q="Was geschieht nach der Reinigung des Brunnens?",a="Sobald der Brunnen der Winterhufe wieder klares Wasser führt und Wildtiere gefahrlos trinken können, schickt Mull Donnerhorn Euch zu weiteren gefährdeten Brunnen in Mulgore, beginnend mit dem Thunderhorn Totem.",al={"what comes next","nach der winterhufsäuberung","was tut mull als nächstes"}},{q="Wer bewacht den Brunnen?",a="Arbeiter und Mietlinge im Dienst der Venture Company halten den Brunnen besetzt. Dieses von Goblins geführte Syndikat beutet die natürlichen Rohstoffe des Landes aus, ohne Rücksicht auf das örtliche Ökosystem.",al={"wer bewacht den brunnen der winterhufe","welche feinde sind am brunnen"}},{q="Wie wirkt das Reinigungstotem?",a="Mit heiligen Riten und Schutzzeichen der Tauren geschnitzt, nutzt das Totem Naturgeister und den Segen der Erdenmutter, um die Quelle von unnatürlichen chemischen Schadstoffen zu reinigen.",al={"reinigungstotem hintergrund","wie wirkt mulls totem"}}},fx={["16ee77f0"]={q="Warum möchte Mull Donnerhorn, dass der Brunnen der Winterhufe gereinigt wird?",a="Der Brunnen der Winterhufe ist lebenswichtig für das Gleichgewicht und das Überleben von Mulgore. Sein Wasser wurde verschmutzt, was sowohl die örtliche Tierwelt als auch die Stämme, die davon abhängen, bedroht. Mull Donnerhorn hat ein geweihtes Reinigungstotem vorbereitet, aber seine Kraft muss direkt zum Ort des Geschehens gebracht werden, um das Wasser zu heilen und die Harmonie im Land wiederherzustellen.",al={"warum den brunnen von winterhoof reinigen","beweggrund von mull donnerhorn","warum wasser von winterhoof reinigen"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="Dienst an der Horde",s="In Orgrimmar hat Zor Einbaum den mit Juwelen besetzten Anhänger erhalten und hat Euch mehr über Euren Dienst an der Horde zu erzählen.",h="In Orgrimmar hat Zor Einbaum den mit Juwelen besetzten Anhänger erhalten und hat Euch mehr über Euren Dienst...",kw={"düstermarschen","anhänger","bericht an zor","dienst an der horde","zor einbaum"},sec={{t="Zor Einbaum in Orgrimmar",b="Der mit Juwelen besetzte Anhänger befindet sich nun bei Zor Einbaum in Orgrimmar. Kehrt zu ihm zurück, um mehr über Euren Dienst an der Horde zu erfahren."},{t="Zors letztes Wort",b="Zor sagt, die Gelehrten brauchen Zeit, um den Anhänger zu studieren. Er bietet Euch ein kleines Zeichen der Anerkennung für Euren Dienst an der Horde an. Eure Taten bringen Euch und der Horde Ehre."}},faq={{q="Wer hat den Anhänger jetzt?",a="Zor Einbaum in Orgrimmar hat den Anhänger. Ihr habt ihn von Nazeer Bloodpike in Brackenwall dorthin gebracht.",al={"wer nimmt den anhänger","wer gibt diese quest","zor einbaums rolle"}},{q="Was kommt vor dieser Quest?",a="„Bericht an Zor“ kommt zuerst. Ihr habt den mit Juwelen besetzten Anhänger zu Zor Einbaum gebracht.",al={"welche quest kam davor","dienst an der horde voraussetzung","vorherige quest"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="Riten der Erdenmutter",s="Auf der Hochwolkenebene beginnen junge Tauren ihre spirituelle Reise unter der Obhut von Häuptling Falkenwind. Er schickt sie südlich von Camp Narache zu Seher Grauzunge, der ihre ersten Schritte auf dem Weg zu den Prüfungen begleitet.",h="Auf der Hochwolkenebene beginnen junge Tauren ihre spirituelle Reise unter der Obhut von Häuptling Falkenwind.",kw={"camp narache","häuptling falkenwind","erdenmutter","die hochwolkenebene","rites of the earthmother","seher grauzunge","tauren"},ang={["class:Druid"]="Als Druide beginnt Ihr Euren Weg zur Harmonie mit der Natur, indem Ihr die heilige Führung der Stammesältesten und Seher ehrt.",["class:Shaman"]="Als angehender Schamane beginnt Ihr mit Riten, die von den Sehern des Stammes gesegnet wurden. Sie sind ein unerlässlicher erster Schritt zur Gemeinschaft mit den Elementen und den Geistern Mulg ores.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr in diesen heiligen Prüfungen das spirituelle Herz Eurer taurenischen Verbündeten erkennen, die sich kürzlich der Horde angeschlossen haben.",["race:Tauren"]="Als Taure beginnt Ihr mit den Rites of the Earthmother eine spirituelle Reise. Sie prüfen Eure Bereitschaft, Eurem Stamm zu dienen und die Erdenmutter zu verehren."},sec={{t="An der Schwelle der Prüfungen",b="Auf der Hochwolkenebene schickt Häuptling Falkenwind junge Tauren zu Seher Grauzunge in den Hügeln südlich von Camp Narache. Der Seher begleitet die Jugend zu Beginn ihres spirituellen Weges. Diese Reise führt sie über den Lageralltag hinaus und hin zu den Pflichten, die ihre Stammesbräuche verlangen."},{t="Der Erdenmutter zugewandt",b="Die Erdenmutter prägt die Glaubensvorstellungen der Tauren über die Schöpfung und das tägliche Leben. Ihre Riten prüfen Reife, Widerstandskraft und spirituelle Tiefe. Seher Grauzunge warnt jene, die seine Zuflucht erreichen, dass die Prüfungen völlige Hingabe an die Traditionen der Hochebene verlangen."}},faq={{q="Wer vergibt die Quest Rites of the Earthmother?",a="Häuptling Falkenwind weist junge Tauren aus Camp Narache an, Seher Grauzunge in den umliegenden Hügeln aufzusuchen.",al={"wer startet rites of the earthmother","questgeber"}},{q="Wo kann ich Seher Grauzunge finden?",a="Seher Grauzunge lebt in den Hügeln unmittelbar südlich von Camp Narache, auf der Hochwolkenebene in Mulgore.",al={"wo ist seher grauzunge","grauzunge standort","grauzunge finden"}},{q="Was sind die Rites of the Earthmother?",a="Die Rites of the Earthmother sind heilige traditionelle Prüfungen, in denen junge Tauren ihre Weisheit, Stärke und Hingabe an ihr Volk und ihren Glauben beweisen.",al={"was sind rites of the earthmother","erdenmutter prüfungen hintergrund"}},{q="Wer ist Seher Grauzunge?",a="Seher Grauzunge ist ein angesehener spiritueller Ältester, der südlich von Camp Narache lebt und Initianden durch die heiligen Prüfungen der Erdenmutter führt.",al={"wer ist seher grauzunge","grauzunge rolle"}},{q="Wer ist Häuptling Falkenwind?",a="Häuptling Falkenwind führt Camp Narache auf der Hochwolkenebene und bereitet junge Tauren vor, bevor er sie zu den Sehern schickt.",al={"wer ist häuptling falkenwind","falkenwind rolle"}},{q="Was ist nötig, um diese Aufgabe abzuschließen?",a="Ihr reist von Camp Narache aus nach Süden in die Hügel und sprecht mit Seher Grauzunge, um Eure Bereitschaft für die Prüfungen zu bekunden.",al={"was ist zu tun","wie quest abschließen"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="Totem der Donnerhörner",s="Im Dorf der Bluthufe bittet Mull Donnerhorn junge Streiter der Horde, ein heiliges Reinigungstotem zu fertigen. Die Verschmutzung durch die Venture Company breitet sich in Mulg ores Brunnen aus, und Raubtierklauen sollen die ursprüngliche Kraft der Ebenen in sein Holz binden.",h="Im Dorf der Bluthufe bittet Mull Donnerhorn junge Streiter der Horde, ein heiliges Reinigungstotem zu...",kw={"dorf der bluthufe","reinigung","pumaklauen","flachlandberglöwe","mulgore","mull donnerhorn","präriepirscher","pirscherklauen","totem der donnerhörner","wasserbrunnen"},ang={["class:Hunter"]="Als Jäger lernt Ihr die heimischen Raubtiere der Ebenen kennen und ehrt die erlegte Beute, während Ihr ihre Klauen sammelt, um das Ökosystem zu bewahren.",["class:Shaman"]="Als Schamane ruft Ihr die lebendigen Geister des Landes an, um Wasser zu reinigen, das durch unnatürliche, rücksichtslose Unternehmungen verdorben wurde.",["race:Tauren"]="Als Tauren ist es Eure heilige Stammespflicht, die Grundwasserleiter Mulg ores vor fremder Ausbeutung zu schützen. Der Auftrag der Earth Mother verlangt ein Leben im Gleichgewicht statt Plünderung."},sec={{t="Jagd auf die Raubtiere der Ebenen",b="Mull Donnerhorn braucht natürliche Klauen für ein Reinigungstotem. Die Venture Company vergiftet Mulg ores Wasser, während sie das Land ausbeutet, und Mull arbeitet an einem Gegenmittel. Präriepirscher und Flachlandberglöwen streifen östlich und westlich des Dorfes der Bluthufe umher. Ihre Klauen tragen die natürliche Essenz der Raubtiere und leiten deren rohe, unverdorbene Lebenskraft in das Totem."},{t="Das Wesen der Jagd",b="Die Tradition der Tauren unterscheidet die Jagd nach Nahrung oder für das spirituelle Gleichgewicht von der maßlosen Plünderung durch die Goblins. Mull glaubt, dass die reine Jagdweise einheimischer Raubtiere helfen kann, verdorbene Erde zu reinigen. Die Maschinen der Goblins verschmutzen die Quellen mit Öl und Industrieabfällen. Die natürliche Stärke der Tiere kann die spirituelle Kraft liefern, um den Brunnen der Donnerhörner wiederherzustellen."}},faq={{q="Warum braucht Mull Donnerhorn Raubtierklauen?",a="Mull nutzt die Klauen von Präriepirschern und Flachlandberglöwen, um den reinen, ursprünglichen Raubtiergeist der Ebenen in ein Reinigungstotem zu leiten. Er glaubt, dass der Geist natürlicher Jäger der künstlichen Verschmutzung durch die Industrie entgegenwirken kann.",al={"warum klauen","zweck der pirscherklauen","zweck der pumaklauen"}},{q="Wer verdirbt das Wasser in Mulgore?",a="Die in Mulgore tätigen Goblins der Venture Company verschmutzen das Land und das Wasser. Ihr rücksichtsloser Rohstoffabbau und ihre Bohranlagen leiten giftigen Schlamm in die Grundwasserleiter, die die Brunnen der Stämme speisen.",al={"wer hat den brunnen verseucht","warum ist der brunnen vergiftet","was hat mulgore vergiftet"}},{q="Wo findet man Präriepirscher und Flachlandberglöwen?",a="Präriepirscher und Flachlandberglöwen durchstreifen die offenen Ebenen im Herzen Mulg ores, vor allem die hügeligen Savannen östlich und westlich des Dorfes der Bluthufe.",al={"präriepirscher fundort","wo flachlandberglöwen finden","pumaklauen fundorte"}},{q="Was geschieht nach der Herstellung des Totems der Donnerhörner?",a="Nachdem Mull das Totem geschnitzt und mit den Klauen verzaubert hat, schickt er Euch zum verseuchten Brunnen der Donnerhörner. Dort vollzieht Ihr das Reinigungsritual und vertreibt das Gift.",al={"was kommt als nächstes","nach dem totem der donnerhörner","totem folgequest"}},{q="Wie hängt das mit der vorherigen Reinigung am Brunnen der Winterhufe zusammen?",a="Die Tauren bemühen sich, die heiligen Gewässer Mulg ores zu bewahren. Der Brunnen der Winterhufe wurde zuerst gereinigt, und nun bedroht die Verschmutzung den weiter nördlich gelegenen Brunnen der Donnerhörner.",al={"verbindung zu den winterhufen","vorherige totemquest"}},{q="Warum verwenden die Tauren nicht einfach Heilkräuter statt Tierklauen?",a="Die Ritualkunst der Tauren schöpft aus den elementaren und körperlichen Aspekten der Natur. Die scharfe Reinheit von Spitzenraubtieren liefert eine aktive, kämpferische spirituelle Kraft, die die aggressiven Industriegifte der Goblins durchdringen kann.",al={"warum keine kräuter","schamanische totemmaterialien"}}},fx={cb047e40={q="Warum möchte Mull Donnerhorn, dass dies getan wird?",a="Der Brunnen der Donnerhörner wird stündlich stärker verseucht, vergiftet durch rücksichtslose Goblin-Operationen in der Nähe. Mull Donnerhorn muss ein heiliges Läuterungstotem herstellen, um den Brunnen zu reinigen, bevor sich die Verderbnis weiter durch die Erde ausbreitet und seinem Volk schadet.",al={"warum mull dies möchte","mull donnerhorns motiv","warum thunderhorn totem fertigen"}},["43953f1d"]={q="Gegen welche Kreaturen werdet Ihr wegen der Krallen ausgesandt?",a="Ihr werdet ausgesandt, um die wilden Raubtiere zu jagen, die durch die Ebenen von Mulgore streifen: die Präriepirscher und Flachlandpumas. Diese Bestien durchstreifen die Gebiete östlich und westlich des Dorfes der Bluthufe auf natürliche Weise und leben und jagen als Teil des natürlichen Gleichgewichts des Landes.",al={"was jage ich","wer sind die ziele","beute für thunderhorn totem"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="Ritus der Kraft",s="In Camp Narache stellen sich junge Tauren im Ritus der Kraft den Stachelebern der Bristleback. Sie bringen Häuptling Falkenwind Gürtel, um ihren Mut zu beweisen und den Stamm zu verteidigen.",h="In Camp Narache stellen sich junge Tauren im Ritus der Kraft den Stachelebern der Bristleback.",kw={"dornrankenklamm","bristleback","camp narache","häuptling falkenwind","erdenmutter","mulgore","stacheleber","ritus der kraft","seher grauzunge"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Hochwolkenebene zu verteidigen, eines ihrer wichtigsten Gebiete zur Rekrutierung neuer Mitglieder. Dort können junge Krieger und Schamanen sicher heranreifen und dem neuen Bündnis helfen.",["race:Tauren"]="Als junger Tauren beginnt Ihr die uralten Riten, indem Ihr beweist, dass Ihr Euer Volk vor den Stachelebern verteidigen könnt, bevor Ihr die Hochwolkenebene verlasst."},sec={{t="Die erste Prüfung",b="Seher Grauzunge ruft junge Tauren dazu auf, die Rites of the Earthmother mit dem Ritus der Kraft zu beginnen. Um die Anerkennung der Stammesältesten und Aufnahme in Donnerfels zu erlangen, muss sich jeder Initiand dieser Pflicht stellen. Die Prüfung zeigt, ob sie den Todfeinden des Stammes mutig entgegentreten und die Hochwolkenebene verteidigen können."},{t="Die Bedrohung durch Bristleback",b="Östlich von Camp Narache liegt die Dornrankenklamm, die Heimat der Stacheleber der Bristleback. Sie dringen in das Land der Ahnen ein, überfallen Jagdtrupps aus dem Hinterhalt und plündern im Schutz der Dunkelheit die Lagervorräte. Ihr werdet aufgefordert, sie zu erschlagen und ihre Gürtel zurückzubringen. Die Gürtel beweisen Eure Tapferkeit und tragen zur Sicherheit der Siedlung bei."}},faq={{q="Welchem Zweck dient der Ritus der Kraft?",a="Der Ritus der Kraft prüft den Mut eines jungen Tauren im Kampf und leitet die Rites of the Earthmother ein. Wer Bedrohungen für das Lager bezwingt, erwirbt als Initiand das Recht, weiter auf Anerkennung in Donnerfels hinzuarbeiten.",al={"warum den ritus der kraft absolvieren","geschichte des ritus der kraft","zweck des ritus der kraft"}},{q="Wer erteilt den Auftrag zu dieser Prüfung und beurteilt sie?",a="Seher Grauzunge erteilt den Auftrag und erklärt dessen geistige und praktische Anforderungen. Bringt Häuptling Falkenwind in Camp Narache zwölf Gürtel der Bristleback als Beweis Eurer Tapferkeit.",al={"wer erteilt den ritus der kraft","bei wem den ritus der kraft abgeben"}},{q="Wo liegt die Dornrankenklamm?",a="Die Dornrankenklamm liegt östlich von Camp Narache auf der Hochwolkenebene. Feindselige Stacheleber der Bristleback leben in ihrer dornigen Schlucht.",al={"wo liegt die dornrankenklamm","lage der dornrankenklamm"}},{q="Warum werden die Bristleback bekämpft?",a="Die Bristleback dringen in die angestammten Jagdgründe des Stammes ein. Sie überfallen Taurenjäger aus dem Hinterhalt und stehlen nachts Vorräte aus Camp Narache, wodurch sie zu Feinden des Stammes werden.",al={"warum bristleback töten","was haben die stacheleber getan"}},{q="Warum werden Gürtel statt anderer Trophäen gesammelt?",a="Die Gürtel beweisen, dass ein Initiand sich den Stachelebern gestellt und ihre erwachsenen Krieger im Nahkampf besiegt hat, statt aus der Ferne Beute aufzusammeln.",al={"warum gürtel der bristleback","warum gürtel"}},{q="Was folgt auf den Abschluss des Ritus der Kraft?",a="Das Bestehen des Ritus der Kraft beweist die Tapferkeit eines Initianden und befähigt ihn zu den nächsten Prüfungen der Erdenmutter. Diese Prüfungen setzen den förmlichen Weg zum Erwachsensein und zu geistigem Ansehen innerhalb des Stammes fort.",al={"was folgt auf den ritus der kraft","nächster ritus der erdenmutter"}}},fx={f38315d5={q="Warum schickt Euch Seher Grauzunge zu den Borstennacken?",a="Seer Grauzunge führt die Jugend von Camp Narache durch die heiligen Rites of the Earthmother. Für Eure erste Prüfung muss er Eure kämpferische Entschlossenheit gegen eine reale und dringende Gefahr für den Stamm testen. Die Borstennacken-Stacheleber dringen in die Ländereien der Tauren ein, überfallen Jäger und stehlen im Schutz der Dunkelheit. Indem er Euch schickt, um sie zu konfrontieren, stellt Grauzunge sicher, dass Ihr Euer Volk beschützt, während Ihr Eure Stärke beweist und Euch den Respekt des Stammes verdient.",al={"warum möchte grauzunge dies","seher grauzunges motiv","warum rite of strength"}},e0dd8e68={q="Warum werdet Ihr ausgesandt, diese Prüfung allein zu absolvieren?",a="Die Rite of Strength ist ein persönlicher Initiationsritus, keine einfache Aufgabe für die Garnison. Während Stammeskrieger den Außenposten bewachen, muss jeder junge Tauren unabhängig Tapferkeit und kämpferische Fähigkeiten demonstrieren, bevor er in Donnerfels als Erwachsener anerkannt wird. Die Prüfung verlangt, dass Ihr Euch den Feinden Eures Volkes selbst stellt, damit die Ältesten wissen, dass Ihr den Stamm verteidigen könnt, wenn Ihr dazu gerufen werdet.",al={"warum ich rite of strength","warum keine wachen zu borstennacken","warum muss ich gegen borstennacken kämpfen"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="Donnerhornsäuberung",s="In Mulgore ruft Euch die Donnerhornsäuberung dazu auf, den Brunnen der Donnerhörner zu reinigen. Mull Donnerhorn bereitet ein Totem für den Ritus vor, und die Ahnen von Thunderhorn danken Euch, wenn die Quelle rein ist.",h="In Mulgore ruft Euch die Donnerhornsäuberung dazu auf, den Brunnen der Donnerhörner zu reinigen.",kw={"ahnengeister","dorf der bluthufe","säuberungstotem","earth mother","mulgore","mull donnerhorn","donnerhornsäuberung","brunnen der donnerhörner"},ang={["class:Druid"]="Als Druide reinigt Ihr vergiftete Gewässer, um die Verderbnis im lebendigen Land von Mulgore aufzuhalten und die natürliche Harmonie der Ebenen zu bewahren.",["class:Shaman"]="Als Schamane leitet Ihr die Energie der Ahnen durch Totems, um verdorbene Quellen zu heilen. Das ist der Kern Eurer Berufung.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr ihren Bund mit den stolzen Shu'halo, indem Ihr den Tauren helft, ihre heiligen Quellen zu schützen.",["race:Tauren"]="Als Tauren ehrt Ihr die Earth Mother und schützt die Euren, während sie sich in Mulgore eine dauerhafte, friedliche Heimat schaffen."},sec={{t="Eine verseuchte Lebensader",b="Wasserbrunnen versorgen die Taurenstämme, die sich im Grasland von Mulgore niedergelassen haben. Wenn Gift eine unterirdische Quelle verseucht, leiden die Tierwelt und die nahen Siedlungen. Der Brunnen der Donnerhörner liegt nördlich vom Dorf der Bluthufe, und sein Wasser bedarf einer spirituellen Reinigung."},{t="Reinigung durch die Ahnen",b="Mull Donnerhorn fertigt ein Säuberungstotem für den Ritus an. Tragt es zur vergifteten Quelle und leitet die Macht der Ahnen hindurch, um die Giftstoffe zu vertreiben. Wenn die Reinigung gelingt, besuchen die Ahnen von Thunderhorn Mull im Traum und sprechen ihren Dank aus."}},faq={{q="Wo liegt der Brunnen der Donnerhörner?",a="Der Brunnen der Donnerhörner liegt in den Ebenen nördlich vom Dorf der Bluthufe in Mulgore. Er ist eine von mehreren Wasserstellen, die die örtlichen Taurenclans versorgen.",al={"standort des brunnens der donnerhörner","wo ist der brunnen","wo das totem benutzen"}},{q="Wer leitet dieses Reinigungsritual ein?",a="Mull Donnerhorn beginnt den Ritus. Er lebt im Dorf der Bluthufe und fertigt Totems an, um das leidende Land von Mulgore zu heilen.",al={"wer gibt die quest","mull donnerhorn standort","questgeber"}},{q="Warum müssen die Wasserbrunnen in Mulgore gereinigt werden?",a="Gift und Verderbnis bedrohen die Ebenen und die Taurenstämme, die auf sauberes Wasser angewiesen sind.",al={"warum brunnen reinigen","was ist mit dem wasser passiert","warum ist der brunnen vergiftet"}},{q="Woher weiß Mull, dass das Ritual erfolgreich war?",a="Nach dem erfolgreichen Ritus besuchen die Ahnen von Thunderhorn Mull im Traum und danken Euch für Eure Tat.",al={"traum von den ahnen","woher mull es weiß","ergebnis der brunnenreinigung"}},{q="Was folgt auf die Reinigung des Brunnens der Donnerhörner?",a="Nachdem der Brunnen der Donnerhörner gereinigt ist, schickt Mull Euch los, um mit der Herstellung des Wildmane Totems einer weiteren leidenden Region zu helfen.",al={"was kommt als nächstes","nächste quest nach donnerhornsäuberung","wildmane totem als nächstes"}},{q="Was ist das Läuterungstotem der Donnerhörner?",a="Das Läuterungstotem der Donnerhörner ist ein spiritueller Fokus, den Mull Donnerhorn herstellt, um das verdorbene Wasser des Ahnenbrunnens seines Clans zu reinigen.",al={"säuberungstotem","was ist der totemgegenstand","mulls totem"}}},fx={da3030fe={q="Warum benötigt Mull Donnerhorn Euch, um den Brunnen zu reinigen?",a="Mull Donnerhorn hat den rituellen Fokus gefertigt, doch die Reinigung heiligen Bodens ist ein Ritus des Dienstes und der Ehre für aufstrebende Champions unter den Tauren und ihren Verbündeten. Indem Ihr das Läuterungstotem der Donnerhörner selbst zum verseuchten Brunnen tragt, beweist Ihr Eure Hingabe an die Erdenmutter und die Ahnengeister seines Clans und verdient Euch die Gunst und Führung der Ahnen, die über die Gewässer wachen.",al={"warum ich für mull donnerhorn","warum schickt mull euch","warum läuterungsritual durchführen"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="Totem der Wildmähnen",s="Am Wildmane-Brunnen will Mull Donnerhorn Mulgores letzte vergiftete Gewässer heilen. Er braucht Zähne von Präriewolfalphatieren für ein Totem, das sie reinigen kann.",h="Am Wildmane-Brunnen will Mull Donnerhorn Mulgores letzte vergiftete Gewässer heilen.",kw={"dorf der bluthufe","mulgore","mull donnerhorn","präriewolfalphatier","donnerfels","totem","wasserbrunnen","wildmane"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euren Respekt vor der Wildnis und ihren wildesten Raubtieren auf die Probe, während Ihr gerissene Alphawölfe rund um die hohen Klippen aufspürt.",["class:Shaman"]="Als Schamane wisst Ihr, welche Sorgfalt nötig ist, um Raubtiertotems und elementares Wasser im Kampf gegen giftige Verderbnis in Einklang zu bringen.",["race:Tauren"]="Als Tauren erbt Ihr die Pflicht, die Brunnen der Ahnen zu heilen und zu ehren, was die Erdenmutter dem Land abverlangt."},sec={{t="Der letzte Brunnen",b="Der Wildmane-Brunnen ist die letzte vergiftete Wasserquelle im Herzen Mulgores. Mull Donnerhorn hat alles Nötige für die Brunnen der Winterhufe und der Thunderhorn gesammelt, doch vergiftetes Wasser schadet weiterhin wandernden Wildtieren und Siedlungen überall in den Ebenen. Mächtige Zutaten aus dem Land werden gebraucht, um sein Gleichgewicht wiederherzustellen."},{t="Die Stärke des Raubtiers",b="Präriewolfalphatiere durchstreifen Mulgores Grasland, besonders am Fuß der hohen Klippen unterhalb von Donnerfels. Mull Donnerhorn braucht ihre Zähne für ein reinigendes Totem, das für die nördlichen Gewässer bestimmt ist. Ihre Stärke und Ausdauer werden dem Totem die Macht dieser wilden Jäger verleihen."},{t="Opfer und Gleichgewicht",b="Für Tauren ist es eine ernste Angelegenheit, den Geschöpfen des Landes etwas zu nehmen. Mull Donnerhorn betrachtet die Alphazähne als Notwendigkeit, nicht als Eroberung. Das Opfer der Raubtiere könnte helfen, die vergifteten Gewässer der Erdenmutter zu heilen."}},faq={{q="Wofür wird das Totem der Wildmähnen gebraucht?",a="Mull Donnerhorn fertigt das Totem an, um den Wildmane-Brunnen zu reinigen, die letzte verseuchte Wasserquelle, die Mulgores Tauren bedroht.",al={"warum das totem der wildmähnen herstellen","zweck des totems der wildmähnen"}},{q="Warum werden gerade Zähne von Präriewolfalphatieren benötigt?",a="Die tiefe Verderbnis des Wildmane-Brunnens verlangt nach der wilden Stärke eines Spitzenjägers. Alphazähne bringen diese ursprüngliche Kraft in das Totem ein.",al={"warum wolfszähne","zweck der präriewolfalphazähne"}},{q="Wo findet man Präriewolfalphatiere in Mulgore?",a="Präriewolfalphatiere durchstreifen Mulgores nördliche Ebenen, besonders das Grasland am Fuß von Donnerfels.",al={"fundort der präriewolfalphatiere","wo präriewolfalphatiere finden"}},{q="Wer fertigt das Totem an?",a="Mull Donnerhorn, ein spiritueller Ältester im Dorf der Bluthufe, fertigt jedes reinigende Totem an, nachdem ein Initiand die Opfergaben gesammelt hat.",al={"wer stellt das totem her","totem questgeber"}},{q="Was folgt auf die Herstellung des Totems der Wildmähnen?",a="Nachdem Mull Donnerhorn aus den Alphazähnen ein Totem gefertigt hat, tragt Ihr es nach Norden, um den Wildmane-Brunnen zu reinigen.",al={"what comes next","totem der wildmähnen nächste quest"}},{q="Wie spiegelt dieses Ritual den Glauben der Tauren wider?",a="Tauren betrachten das Töten eines Tieres als einen feierlichen Austausch mit der Natur. Mull trauert um die getöteten Wölfe und ehrt ihren Beitrag zur Heilung der Erde.",al={"tauren philosophie totem","mull donnerhorn glaube"}}},fx={["054e923c"]={q="Warum möchte Mull Donnerhorn, dass das Wildmane Totem hergestellt wird?",a="In Mulgore muss nur noch ein korrumpierter Brunnen gereinigt werden – derjenige, der zum Wildmähnen-Clan gehört. Mull Donnerhorn hat sich der Reinigung der heiligen Brunnen der Erdenmutter verschrieben, und die Herstellung dieses letzten Läuterungstotems unter Verwendung des Raubtiergeistes des Landes ist wesentlich für den Abschluss des heiligen Ritus und die Wiederherstellung von reinem Wasser für den Stamm.",al={"warum mull wildmane totem will","mull donnerhorns motiv","warum wildmane totem herstellen"}},["2aa23a29"]={q="Wofür wird der Präriealphazahn verwendet?",a="Die Zähne des Präriewolf-Alphas repräsentieren das Opfer und die wilde Vitalität der Spitzenprädatoren von Mulgore. Mull Donnerhorn bindet acht dieser Reißzähne in das Wildmane Totem, damit dessen Geist die natürliche Ordnung besänftigen und das Ritual stärken kann, das benötigt wird, um die Verderbnis aus dem Brunnen der Wildmähnen zu tilgen.",al={"nutzung präriealphazahn","wofür sind präriealphazähne","zähne für wildmane totem"}},eb5f4bd0={q="Warum jagt Ihr Präriewolf-Alphas?",a="Ihr werdet ausgesandt, um Präriewolf-Alphas zu jagen, die dominanten Rudelführer, die die Ebenen rund um die Basis von Donnerfels durchstreifen. Ihre Stärke und Wildheit verkörpern das natürliche Gleichgewicht der Ebenen und liefern die wirkungsvolle Essenz, die Mull Donnerhorn für das letzte Wasser-Reinigungsritual benötigt.",al={"warum präriewolf-alphas töten","ziel präriewolf-alpha","hinter wem seid ihr her"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="Die Jaspismine",s="Späher sind zur Jaspismine im Osten Elwynns unterwegs, wohin sich Kobolde ausgebreitet haben könnten. Marschall Dughan muss wissen, wie weit sie vorgedrungen sind.",h="Späher sind zur Jaspismine im Osten Elwynns unterwegs, wohin sich Kobolde ausgebreitet haben könnten.",kw={"azora","dughan","elwynn","tiefenschachtmine","goldhain","jaspismine","kobold","mine","späher"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie verwundbar Sturmwinds Kerngebiete ohne zentrale königliche Unterstützung geworden sind, nachdem sowohl die Tiefenschachtmine als auch die Jaspismine verloren gingen.",["profession:Mining"]="Als Bergarbeiter seht Ihr wertvolle Vorkommen in den Tunneln der Jaspismine, doch revierverteidigende Kobolde stehen zwischen Euch und dem Erz.",["race:Human"]="Als Mensch erlebt Ihr, wie Elwynns ländliche Infrastruktur ins Wanken gerät, während grenznahe Rohstoffquellen unweit der Hauptstadt verloren gehen."},sec={{t="Ein zweiter Einfall",b="Nachdem Kobolde die Tunnel der Tiefenschachtmine südlich von Goldhain überrannt hatten, fürchtete Marschall Dughan, sie hätten weitere Minen erreicht. Die Jaspismine liegt in den felsigen Ausläufern nordöstlich des Turms von Azora. Ihr Stein und Metall versorgen das Königreich. Da die Wachen von Sturmwind für Patrouillen in der Stadt gebraucht werden, schickt Dughan unabhängige Abenteurer nach Osten, um herauszufinden, ob Kobolde auch diese Mine eingenommen haben."},{t="Überlastete Verteidigung",b="Späher, die die Kammern der Jaspismine erreichen, stellen fest, dass Kobolde die menschlichen Bergleute vertrieben und die dunklen Gänge befestigt haben. Marschall Dughan trifft ein weiterer Schlag, während sich die Krise verschärft. König Varian Wrynn ist verschollen, und königliche Truppen werden weiterhin von den entlegenen Gebieten ferngehalten. Die örtliche Garnison hat zu wenige Soldaten, um die Mine zu räumen. Dem Herzen des Königreichs fehlen Rohstoffe, und Bedrohungen engen es ein."}},faq={{q="Wo liegt die Jaspismine?",a="Die Jaspismine liegt in den nördlichen Ausläufern im Osten des Waldes von Elwynn. Reist von Goldhain auf der Hauptstraße nach Osten, passiert den Turm von Azora und wendet Euch dann nach Norden in die Hügel.",al={"wo ist die jaspismine","lage der jaspismine","wie die jaspismine finden"}},{q="Warum braucht Marschall Dughan einen Späher, statt Wachen zu schicken?",a="Marschall Dughan kann zu wenige Wachen entbehren. König Varian Wrynn ist verschollen, und der politische Stillstand in der Hauptstadt hat die örtlichen Truppen beim Schutz von Höfen und Ortschaften vor Banditen und Gnollen überlastet. Deshalb verlässt sich Dughan auf zivile Späher.",al={"warum abenteurer schicken","warum keine wache von sturmwind","wo sind die wachen"}},{q="Warum besetzen Kobolde die Minen Elwynns?",a="Kobolde graben Tunnel zu Erzadern und feuchten Höhlen. Als Sturmwinds militärische Präsenz nachließ, wurden sie kühner und drangen in menschliche Minen wie die Tiefenschachtmine und die Jaspismine vor, um Gold, Erz und Gebiete zu beanspruchen.",al={"warum kobolde in der jaspismine","was wollen kobolde","grund für koboldbefall"}},{q="Was geschieht nach der Erkundung der Jaspismine?",a="Nachdem Ihr den Fall der Jaspismine gemeldet habt, steht Marschall Dughan vor dem Verlust der Minen im Osten und Bedrohungen an mehreren Fronten. Er richtet seine Aufmerksamkeit auf den Westen Elwynns, wo Riverpaw-Gnolle die Weststromgarnison stark unter Druck setzen.",al={"was kommt nach der jaspismine","fortsetzung nach der jaspismine"}},{q="Warum ist der Verlust der Jaspismine für Sturmwind bedeutend?",a="Elwynns Minen liefern Erz und Stein, die Sturmwind für seine Wirtschaft und zum Schmieden von Waffen und Rüstungen braucht. Der Verlust der Tiefenschachtmine und der Jaspismine bringt den Rohstoffabbau zum Erliegen und schwächt die Erholung des Königreichs.",al={"warum die jaspismine wichtig ist","bedeutung der jaspismine"}},{q="Wem gehört der nahe gelegene Turm von Azora?",a="Der Turm von Azora ist ein kleiner Magierturm an der östlichen Straße des Waldes von Elwynn. Theocritus, der Erzmagier von Azora, hat dort den Vorsitz, und Azoras Diener kümmern sich um den Turm. Reisende nutzen ihn als Orientierungspunkt auf dem Weg zu den östlichen Ausläufern.",al={"was ist der turm von azora","wer lebt im turm von azora"}}},fx={a973508b={q="Warum möchte Marschall Dughan, dass die Jaspismine erkundet wird?",a="Nachdem bereits bestätigt wurde, dass Kobolde die The Fargodeep Mine überrannt haben, fürchtet Marschall Dughan, dass der Befall kein isolierter Vorfall ist. Er muss wissen, ob sich die Bedrohung auch nach Osten zur Jaspismine ausgebreitet hat. Die Sicherung der Ressourcenversorgung von Elwynn und das Verständnis des vollen Ausmaßes der heraufziehenden Gefahr sind entscheidend für die Verteidigung der Ortschaft Goldhain und den Schutz der wichtigen Handelsrouten von Sturmwind.",al={"dughans motiv jaspismine","warum jaspismine auskundschaften","warum muss dughan jaspismine untersucht haben"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmähnensäuberung",s="In Mulgore erreicht die Läuterung durch die Tauren den letzten Brunnen. Mull Donnerhorn im Dorf der Bluthufe schickt Euch mit dem fertigen Wildmane Totem nach Norden, um das vergiftete Wasser zu läutern und die Lebensweise der Tauren zu schützen.",h="In Mulgore erreicht die Läuterung durch die Tauren den letzten Brunnen.",kw={"dorf der bluthufe","läuterung","earth mother","mulgore","mull donnerhorn","totem","venture company","wasserbrunnen","wildmähnen"},ang={["class:Druid"]="Als Druide helft Ihr, die Zerstörung durch die Goblins rückgängig zu machen, indem Ihr verseuchte Ökosysteme heilt und Mulg ores Weiden schützt.",["class:Shaman"]="Als Schamane nutzt Ihr rituelle Totems, um maschinell verursachte Verschmutzung zu beseitigen und die Harmonie zwischen den Naturelementen und den lebenden Gemeinschaften zu bewahren.",["race:Tauren"]="Als Taure ist die Wiederherstellung der drei angestammten Brunnen Mulg ores für Euch ein Übergangsritus. Er beweist Eure Hingabe an die Bewahrung der Gaben der Earth Mother."},sec={{t="Die Gabe der Earth Mother läutern",b="Mulg ores Brunnen versorgen die Herden, den Boden und die Taurenstämme, die sich um Donnerfels versammelt haben. Die Venture Company und vordringende Goblins haben sie mit giftigen Industrieabwässern verseucht. Die Ältesten der Tauren erkennen die Gefahr für ihr Volk und ihr Land.\n\nDer Brunnen der Winterhufe und der Brunnen der Donnerhörner sind geläutert. Nun bleibt der Brunnen der Wildmähnen, die dritte und letzte verderbte Stätte. Sein Wasser bedarf noch der spirituellen Läuterung."},{t="Das Wildmane Totem",b="Das Läuterungstotem der Wildmähnen wird aus Elementen gefertigt, die in der ganzen Region gesammelt wurden. Es schöpft aus der heilenden Kraft der Ahnengeister und der elementaren Erde. Stellt es neben dem verseuchten Wasser nördlich von Donnerfels auf. Das Ritual zerstreut Chemikalien, zieht Giftstoffe heraus und belebt den natürlichen Wasserfluss.\n\nDie Läuterung schützt die Tauren vor Krankheiten. Sie macht auch deutlich, dass sie die Schändung ihres heiligen Landes nicht dulden werden."}},faq={{q="Warum wurde der Brunnen der Wildmähnen vergiftet?",a="Von industrieller Gier getriebene Goblinbetriebe und Holzunternehmen vergifteten Mulg ores Grundwasser mit chemischen Abfällen. Die Abfälle bedrohen die Tierwelt und die Stammessiedlungen.",al={"wer hat den brunnen vergiftet","warum ist der brunnen schmutzig","goblingift"}},{q="Wo liegt der Brunnen der Wildmähnen?",a="Der Brunnen der Wildmähnen liegt auf den Ebenen direkt nördlich der hoch aufragenden Tafelberge von Donnerfels.",al={"standort des brunnens der wildmähnen","wo ist der brunnen der wildmähnen","brunnen der wildmähnen finden"}},{q="Wer leitet dieses Läuterungsritual ein?",a="Mull Donnerhorn, ein Ältester im Dorf der Bluthufe, leitet Euch bei der Herstellung der Totems an und schickt Euch aus, die Brunnen zu läutern.",al={"wer vergibt wildmähnensäuberung","questgeber","mull donnerhorn standort"}},{q="Welche anderen Brunnen gehören zu dieser Läuterung?",a="Der Brunnen der Wildmähnen ist die dritte von drei lebenswichtigen Wasserquellen. Der Brunnen der Winterhufe und der Brunnen der Donnerhörner, beide im Süden, kamen zuerst.",al={"andere brunnen","brunnen in mulgore","brunnen der winterhufe und donnerhörner"}},{q="Wie wirkt das Läuterungstotem?",a="Das mit Ahnenmagie und geläuterten Naturelementen gefertigte Totem leitet heilende spirituelle Kraft ins Grundwasser, um die Schadstoffe der Goblins zu neutralisieren.",al={"funktionsweise des läuterungstotems","wie reinigt das totem wasser"}},{q="Was bedeutet der Abschluss dieses Rituals für das Dorf der Bluthufe?",a="Die Läuterung aller drei Brunnen sichert den Stämmen im Herzen Mulg ores sauberes Trinkwasser. Sie ehrt die Pflicht der Tauren, die Earth Mother von den Schäden industrieller Ausbeutung zu heilen.",al={"ergebnis der quest","warum die brunnen läutern","bedeutung für die geschichte der tauren"}}},fx={["119d5a48"]={q="Warum möchte Mull Donnerhorn, dass der Brunnen der Wildmähnen gereinigt wird?",a="Mull Donnerhorn wacht über das spirituelle Gleichgewicht und die lebenswichtigen Ressourcen von Mulgore. Die üblen Operationen der Venture Company vergifteten die kostbaren Wasserquellen des Landes und bedrohten das Überleben der Stämme und ihrer Herden. Der Brunnen der Wildmähnen ist der letzte der drei alten Brunnen, die noch verseucht sind, und seine Reinigung ist unerlässlich, um die Erdenmutter zu heilen und sicheres Trinkwasser für das Dorf der Bluthufe und Donnerfels zu sichern.",al={"mull donnerhorns motiv","warum brunnen der wildmähnen reinigen","warum liegen mull die brunnen am herzen"}},b4cee6a1={q="Was ist das Läuterungstotem der Wildmähnen?",a="Das Läuterungstotem der Wildmähnen ist ein rituell vorbereitetes Hilfsmittel, das von Mull Donnerhorn gefertigt wurde, um Ahnen- und Erdgeister zu kanalisieren. Wenn es am verseuchten Brunnen der Wildmähnen nördlich von Donnerfels aktiviert wird, stößt das Totem den giftigen Schlamm aus, der von Goblin-Umweltverschmutzern hinterlassen wurde, reinigt den Grundwasserleiter und versetzt die Quelle in ihren natürlichen, ursprünglichen Zustand zurück.",al={"nutzung läuterungstotem der wildmähnen","was ist das wildmane totem","zweck läuterungstotem"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="Sturzfliegerjagd",s="Harken Windtotem bittet Euch, Sturzfliegern in ganz Mulgore nachzustellen. Ihre Kielfedern stellen Geduld, Schläue und Treffsicherheit auf die Probe und ehren die Prüfungen der Erdenmutter.",h="Harken Windtotem bittet Euch, Sturzfliegern in ganz Mulgore nachzustellen.",kw={"dorf der bluthufe","harken windtotem","mulgore","sturzflieger","sturzfliegerjagd","tauren prüfung","trophäensturzfliegerkiel"},ang={["class:Druid"]="Als Druide kommt Ihr beim Verfolgen von Sturzfliegern über die Tafelberge von Mulgore den Raubvögeln näher, die das Gleichgewicht am Himmel wahren helfen.",["class:Hunter"]="Als Jäger lernt Ihr beim Verfolgen von Sturzfliegern, fliegender Beute nachzustellen, ihr Verhalten zu deuten und wachsame Raubvögel mit präzisen Angriffen zu treffen.",["race:Tauren"]="Als Taure ist die Jagd auf Mulg ores flinke Sturzflieger für Euch ein Übergangsritus. Sie schärft Eure Fähigkeiten im Fährtenlesen und bewahrt die Bräuche der Ahnen."},sec={{t="Eine Prüfung scharfer Augen",b="Im offenen Grasland von Mulgore stellen Sturzflieger das Auge eines Jägers auf die Probe. Diese großen Vögel verschmelzen mit Himmel und Ebene, kreisen hoch oben oder gleiten tief durch das hohe Gras. Sie verlangen Konzentration und flinke Füße, anders als schwerfällige Ebenenschreiter oder grasende Kodos. Junge Jäger stellen ihnen nach, um ihr Können zu beweisen und sich Ansehen unter den Stämmen zu verdienen."},{t="Zeichen der Jagd",b="Harken Windtotem verlangt Trophäenkielfedern, um Disziplin zu lehren, nicht um die Tierwelt auszudünnen. Tauren tragen Andenken an eine hart erkämpfte Pirsch als Zeichen von Schläue und Ausdauer. Makellose Kielfedern, den Ältesten im Dorf der Bluthufe überreicht, zeigen, dass ein Jäger die Gemeinschaft ernähren und verteidigen kann. Flinke Hufe und scharfe Sinne bereiten sie auf die weite Welt vor."}},faq={{q="Welchen Zweck hat die Jagd auf Sturzflieger für Harken Windtotem?",a="Harken Windtotem bittet Euch, Sturzfliegern in ganz Mulgore nachzustellen und Eure Schläue, Schnelligkeit und Hingabe auf die Probe zu stellen. Unversehrte Trophäenkielfedern bezeugen Euer Können und bringen Euch Ehre unter den Tauren im Dorf der Bluthufe.",al={"warum sturzflieger jagen","harken windtotem quest zweck","sturzfliegerjagd zweck"}},{q="Wo begegnet man Sturzfliegern gewöhnlich?",a="Sturzflieger durchstreifen die offenen Ebenen von Mulgore, segeln über dem Gras oder suchen außerhalb von Siedlungen wie dem Dorf der Bluthufe nach Beute.",al={"wo sind sturzflieger","sturzflieger fundorte mulgore","sturzflieger finden"}},{q="Warum gelten Sturzflieger als schwierige Jagdbeute?",a="Sturzflieger sind schnelle, wachsame Raubvögel, die über die Ebenen verstreut leben. Ihr braucht scharfe Augen, um sie zu erspähen, und schnelle Schritte, um sie einzuholen, bevor sie entkommen.",al={"warum sind sturzflieger schwer zu fangen","sturzflieger verhalten"}},{q="Was bedeuten die Trophäenkielfedern für die Tauren?",a="Trophäensturzfliegerkiele stehen für Geduld, einen scharfen Blick und eine erfolgreiche Jagd. Sie zeigen, dass Ihr die Instinkte besitzt, um den Stamm zu versorgen und zu beschützen.",al={"trophäensturzfliegerkiel bedeutung","bedeutung der kielfedern"}},{q="Wer ist Harken Windtotem?",a="Harken Windtotem ist ein angesehener Taure aus dem Dorf der Bluthufe. Er beobachtet Neuankömmlinge und angehende Jäger und beurteilt ihren Einfallsreichtum durch traditionelle Prüfungen in den Ebenen.",al={"wer vergibt sturzfliegerjagd","harken windtotem hintergrundgeschichte"}},{q="Beeinflusst diese Jagd das Gleichgewicht der Natur in Mulgore?",a="Die Tauren betrachten die Jagd als heiligen Austausch mit der Erdenmutter, nicht als mutwilliges Abschlachten. Das Sammeln von Kielfedern prüft Disziplin und ehrt gewitzte Beute, während es das Gleichgewicht des Stammes wahrt.",al={"ist sturzfliegerjagd überjagung","sturzflieger gleichgewicht mulgore"}}},fx={["0d785fcd"]={q="Warum schickt Harken Windtotem einen Außenstehenden, anstatt selbst Swoops zu jagen?",a="Harken Windtotem schickt Euch nicht, weil er nicht jagen kann, sondern um Euren Wert zu testen. Für Tauren erfordert das Verfolgen der listigen Swoops über die Ebenen scharfe Augen, Geduld und schnelle Hufe. Indem er Euch die Aufgabe überträgt, ihre Federn zurückzubringen, gibt Harken Euch die Gelegenheit, Euer Können und Eure Entschlossenheit im Dorf der Bluthufe unter Beweis zu stellen und zu zeigen, dass Ihr ein Jäger von echtem Wert seid.",al={"warum schickt man mich swoop jagen","warum braucht harken mich","warum kann harken keine swoops jagen"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem erkennt Euer Talent für unauffälliges Vorgehen und bittet Euch, die Mine der Venture Company zu betreten. Er möchte, dass Ihr Seaforium Mining Charges aus den Vorratskarren der Mine holt.",h="Boarton Shadetotem erkennt Euer Talent für unauffälliges Vorgehen und bittet Euch, die Mine der Venture...",kw={"sprengmaterial","boarton shadetotem","maske","mine","seaforium mining charges","unauffälliges vorgehen","donnerfels","venture company"},ang={["class:Rogue"]="Boarton glaubt, dass Ihr als Schurke ein Talent für unauffälliges Vorgehen habt, und bittet Euch, die Mine der Venture Company zu betreten."},sec={{t="Ein unauffälliges Vorgehen",b="Boarton Shadetotem in Donnerfels glaubt, dass Ihr unauffällig vorgehen könnt. Er gibt Euch eine Maske und bittet Euch, die nahe gelegene Mine der Venture Company zu betreten. Dort sollt Ihr Seaforium Mining Charges aus Karren mit Sprengmaterial nehmen und sie ihm bringen."}},faq={{q="Wer bittet mich, die Mine zu betreten?",a="Boarton Shadetotem in Donnerfels bittet Euch, die Mine der Venture Company zu betreten.",al={"wer ist boarton","boarton shadetotem","wer hat das gegeben"}},{q="Wonach suche ich in der Mine?",a="Ihr sollt Seaforium Mining Charges aus Karren mit Sprengmaterial nehmen.",al={"was stehlen","minenvorräte","seaforium charges"}},{q="Warum gibt Boarton mir eine Maske?",a="Boarton gibt Euch eine Maske, damit Ihr die nahe gelegene Mine der Venture Company betreten könnt.",al={"maske verkleidung","warum die maske","mine infiltrieren"}},{q="Wo ist die Mine der Venture Company?",a="Die Mine liegt südöstlich von Donnerfels.",al={"standort der mine","wo ist die mine","mine der venture company"}},{q="Wem werden die Vorräte weggenommen?",a="Die Vorräte befinden sich in der Mine der Venture Company.",al={"wem gehören die vorräte","vorräte der venture company","mine der gesellschaft"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem bittet Euch, aus Windfury Cones nördlich von Donnerfels eine Salbe herzustellen. Er hofft, dass sie die Wunden einer Klinge mit bitterer Kraft brennen lässt.",h="Boarton Shadetotem bittet Euch, aus Windfury Cones nördlich von Donnerfels eine Salbe herzustellen.",kw={"boarton shadetotem","harpyien","mörser und stößel","salbe","stalk with the earthmother","donnerfels","windfury cones"},sec={{t="Eine bittere Salbe",b="Boarton Shadetotem in Donnerfels möchte eine giftige Salbe aus Zapfen, die nahe den Harpyiennestern im Norden gesammelt werden. Ihr sollt die Windfury Cones mit Mörser und Stößel zerstoßen und ihm dann das Ergebnis bringen. Er warnt, dass die fertige Salbe selbst auf der Haut schmerzen könnte."}},faq={{q="Wer bittet um die Salbe?",a="Boarton Shadetotem in Donnerfels bittet Euch, eine Salbe aus Windfury Cones zuzubereiten.",al={"wer will die salbe","boarton shadetotems bitte"}},{q="Wo wachsen die Windfury Cones?",a="Die Harpyien nördlich von Donnerfels nisten in einem Baum, der das giftige Harz erzeugt. Herabgefallene Zapfen liegen um ihre Nester herum.",al={"wo zapfen finden","windfury cone fundort"}},{q="Was soll die Salbe bewirken?",a="Auf eine Klinge aufgetragen, soll die Salbe die Wunden eines Gegners brennen lassen und sein Blut in Salz verwandeln.",al={"was bewirkt die salbe","giftige klingensalbe"}},{q="Warum warnt Boarton davor, sie zu berühren?",a="Boarton sagt, dass selbst Hautkontakt mit der fertigen Salbe schmerzhaft sein könnte.",al={"salbe hautkontakt warnung","ist die salbe gefährlich"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="Ein Botschafter des Bösen",s="Im Ödland schickt Euch Historiker Karnik los, um Botschafter Infernus zu töten. Ihr sollt Berater Belgrum in Eisenschmiede einen Beweis für die Tötung überbringen.",h="Im Ödland schickt Euch Historiker Karnik los, um Botschafter Infernus zu töten.",kw={"berater belgrum","botschafter infernus","festung angor","ödland","historiker karnik","eisenschmiede","ragnaros","shadowforge","uldaman"},sec={{t="Der Botschafter in der Festung Angor",b="Ragnaros entsandte Botschafter Infernus zur Festung Angor, um die Suche der Shadowforge nach verlorenen Artefakten in Uldaman zu beaufsichtigen. Die Suche hat bereits viele Zwergenleben gekostet, und weitere Zwerge sterben. Karnik fürchtet, die Shadowforge könnten die Artefakte gegen Eisenschmiede einsetzen. Deshalb schickt er Euch zurück ins Ödland, um Infernus zu vernichten und Belgrum einen Beweis Eures Sieges zu überbringen. Die Zeit drängt. Ragnaros wird nicht warten, bis die Shadowforge bereit sind."},{t="Belgrums Dank",b="Berater Belgrum lobt Eure Hingabe an Eisenschmiede und seine Bewohner. Er wird Karnik von Eurem Erfolg berichten, und Hilfe wird ins Ödland geschickt, um die Ausgrabungsstätte zurückzuerobern. Im Namen von König Bronzebeard hat Belgrum noch eine weitere Bitte an Euch."}},faq={{q="Wer ist Botschafter Infernus?",a="Ragnaros entsandte Infernus zur Festung Angor, um die Suche der Shadowforge nach verlorenen Artefakten in Uldaman zu beaufsichtigen.",al={"wer ist infernus","infernus geschichte","botschafter infernus hintergrund"}},{q="Wo ist Botschafter Infernus?",a="Botschafter Infernus befindet sich in der Festung Angor im Ödland.",al={"wo botschafter infernus finden","botschafter infernus aufenthaltsort","wo ist infernus"}},{q="Warum will Karnik Botschafter Infernus vernichten lassen?",a="Die Suche der Shadowforge in Uldaman hat bereits viele Zwergenleben gekostet. Karnik fürchtet, dass die gefundenen Artefakte gegen Eisenschmiede eingesetzt werden könnten.",al={"warum botschafter infernus töten","was macht infernus in uldaman","eisenschmiede bedrohung ödland"}},{q="Bei wem beginnt und endet diese Quest?",a="Historiker Karnik in Eisenschmiede schickt Euch los, um Infernus zu töten. Ihr überbringt Berater Belgrum in Eisenschmiede einen Beweis Eures Sieges.",al={"wer startet ein botschafter des bösen","bei wem ein botschafter des bösen abgeben","ein botschafter des bösen questgeber"}},{q="Welcher Beweis wird verlangt?",a="Berater Belgrum verlangt Botschafter Infernus' Armschienen als Beweis Eures Sieges.",al={"was wird von infernus benötigt","botschafter infernus beweis","infernus armschienen"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
